import { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { Button } from "@/components/ui/button";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { Lock, Unlock, AlertTriangle } from "lucide-react";
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle, AlertDialogTrigger } from "@/components/ui/alert-dialog";

interface AccountLock {
  id: string;
  email: string;
  locked_at: string;
  locked_until: string;
  reason: string;
  failed_attempts: number;
  alert_sent: boolean;
}

export const AccountLockManagement = () => {
  const [locks, setLocks] = useState<AccountLock[]>([]);
  const [loading, setLoading] = useState(true);
  const { toast } = useToast();

  useEffect(() => {
    loadLocks();
  }, []);

  const loadLocks = async () => {
    try {
      const { data, error } = await supabase
        .from('account_locks')
        .select('*')
        .order('locked_at', { ascending: false });

      if (error) throw error;
      setLocks(data || []);
    } catch (error: any) {
      toast({
        title: "Erro ao carregar bloqueios",
        description: error.message,
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const handleUnlock = async (email: string) => {
    try {
      const { error } = await supabase
        .from('account_locks')
        .delete()
        .eq('email', email);

      if (error) throw error;

      toast({
        title: "Conta desbloqueada",
        description: `A conta ${email} foi desbloqueada com sucesso`,
      });

      loadLocks();
    } catch (error: any) {
      toast({
        title: "Erro ao desbloquear conta",
        description: error.message,
        variant: "destructive",
      });
    }
  };

  const isLocked = (lockedUntil: string) => {
    return new Date(lockedUntil) > new Date();
  };

  if (loading) {
    return <div className="p-4">Carregando bloqueios...</div>;
  }

  return (
    <Card>
      <CardHeader>
        <div className="flex items-center gap-2">
          <Lock className="h-5 w-5" />
          <CardTitle>Gerenciamento de Bloqueios</CardTitle>
        </div>
        <CardDescription>
          Contas bloqueadas por tentativas de login falhadas
        </CardDescription>
      </CardHeader>
      <CardContent>
        {locks.length === 0 ? (
          <div className="text-center text-muted-foreground py-8">
            Nenhuma conta bloqueada
          </div>
        ) : (
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Email</TableHead>
                <TableHead>Tentativas</TableHead>
                <TableHead>Status</TableHead>
                <TableHead>Bloqueado até</TableHead>
                <TableHead>Motivo</TableHead>
                <TableHead>Ações</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {locks.map((lock) => (
                <TableRow key={lock.id}>
                  <TableCell className="font-medium">{lock.email}</TableCell>
                  <TableCell>
                    <Badge variant="destructive">{lock.failed_attempts} falhas</Badge>
                  </TableCell>
                  <TableCell>
                    {isLocked(lock.locked_until) ? (
                      <Badge variant="destructive">
                        <Lock className="h-3 w-3 mr-1" />
                        Bloqueado
                      </Badge>
                    ) : (
                      <Badge variant="outline">
                        Expirado
                      </Badge>
                    )}
                  </TableCell>
                  <TableCell className="text-sm">
                    {new Date(lock.locked_until).toLocaleString('pt-BR')}
                  </TableCell>
                  <TableCell className="text-sm text-muted-foreground">
                    {lock.reason}
                  </TableCell>
                  <TableCell>
                    {isLocked(lock.locked_until) && (
                      <AlertDialog>
                        <AlertDialogTrigger asChild>
                          <Button variant="outline" size="sm">
                            <Unlock className="h-4 w-4 mr-1" />
                            Desbloquear
                          </Button>
                        </AlertDialogTrigger>
                        <AlertDialogContent>
                          <AlertDialogHeader>
                            <AlertDialogTitle>Desbloquear conta</AlertDialogTitle>
                            <AlertDialogDescription>
                              Tem certeza que deseja desbloquear a conta {lock.email}?
                              O usuário poderá tentar fazer login novamente.
                            </AlertDialogDescription>
                          </AlertDialogHeader>
                          <AlertDialogFooter>
                            <AlertDialogCancel>Cancelar</AlertDialogCancel>
                            <AlertDialogAction onClick={() => handleUnlock(lock.email)}>
                              Desbloquear
                            </AlertDialogAction>
                          </AlertDialogFooter>
                        </AlertDialogContent>
                      </AlertDialog>
                    )}
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        )}
      </CardContent>
    </Card>
  );
};

import { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Download, Search } from "lucide-react";

interface AuditLog {
  id: string;
  created_at: string;
  tipo_evento: string;
  descricao: string;
  usuario_id: string | null;
  ip_address: string | null;
  user_agent: string | null;
  metadata: any;
}

export const ActionLogs = () => {
  const [logs, setLogs] = useState<AuditLog[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [eventType, setEventType] = useState<string>("all");
  const { toast } = useToast();

  useEffect(() => {
    loadLogs();
  }, [eventType]);

  const loadLogs = async () => {
    try {
      setLoading(true);

      let query = supabase
        .from('auditoria_admin')
        .select('*')
        .order('created_at', { ascending: false })
        .limit(100);

      if (eventType !== 'all') {
        query = query.eq('tipo_evento', eventType);
      }

      const { data, error } = await query;

      if (error) throw error;
      setLogs(data || []);
    } catch (error: any) {
      toast({
        title: "Erro ao carregar logs",
        description: error.message,
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const exportLogs = async () => {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      const csvContent = generateCSV();
      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });

      await supabase.rpc('registrar_exportacao', {
        p_user_id: user.id,
        p_export_type: 'audit_logs',
        p_table_name: 'auditoria_admin',
        p_filters: { event_type: eventType },
        p_record_count: logs.length,
        p_file_format: 'csv'
      });

      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `logs-auditoria-${new Date().toISOString().split('T')[0]}.csv`;
      link.click();

      toast({
        title: "Logs exportados",
        description: "Arquivo CSV baixado com sucesso",
      });
    } catch (error: any) {
      toast({
        title: "Erro ao exportar",
        description: error.message,
        variant: "destructive",
      });
    }
  };

  const generateCSV = () => {
    let csv = 'Data/Hora,Tipo de Evento,Descrição,IP\n';

    logs.forEach(log => {
      const date = new Date(log.created_at).toLocaleString('pt-BR');
      const descricao = (log.descricao || '').replace(/,/g, ';');
      const ip = log.ip_address || '-';

      csv += `${date},${log.tipo_evento},"${descricao}",${ip}\n`;
    });

    return csv;
  };

  const filteredLogs = logs.filter(log => {
    if (!searchTerm) return true;
    const searchLower = searchTerm.toLowerCase();
    return (
      log.tipo_evento.toLowerCase().includes(searchLower) ||
      log.descricao?.toLowerCase().includes(searchLower)
    );
  });

  const getEventBadgeVariant = (tipo: string): "default" | "destructive" | "secondary" | "outline" => {
    if (tipo.includes('delete') || tipo.includes('error') || tipo.includes('lock')) return 'destructive';
    if (tipo.includes('create') || tipo.includes('success')) return 'default';
    if (tipo.includes('update') || tipo.includes('change')) return 'secondary';
    return 'outline';
  };

  const eventTypes = [
    { value: 'all', label: 'Todos os Eventos' },
    { value: 'login', label: 'Login' },
    { value: 'logout', label: 'Logout' },
    { value: 'data_export', label: 'Exportação de Dados' },
    { value: 'user_create', label: 'Criação de Usuário' },
    { value: 'user_update', label: 'Atualização de Usuário' },
    { value: 'user_delete', label: 'Exclusão de Usuário' },
    { value: 'password_reset', label: 'Reset de Senha' },
    { value: 'permission_change', label: 'Mudança de Permissão' },
    { value: 'config_change', label: 'Mudança de Configuração' },
  ];

  return (
    <div className="space-y-6">
      <Card>
        <CardHeader>
          <CardTitle>Logs de Auditoria</CardTitle>
          <CardDescription>
            Registro completo de todas as ações administrativas do sistema
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          {/* Filtros */}
          <div className="flex flex-wrap gap-4">
            <div className="flex-1 min-w-[200px]">
              <div className="relative">
                <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
                <Input
                  placeholder="Buscar em logs..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-8"
                />
              </div>
            </div>

            <Select value={eventType} onValueChange={setEventType}>
              <SelectTrigger className="w-[200px]">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {eventTypes.map(type => (
                  <SelectItem key={type.value} value={type.value}>
                    {type.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>

            <Button onClick={exportLogs} variant="outline">
              <Download className="h-4 w-4 mr-2" />
              Exportar CSV
            </Button>
          </div>

          {/* Tabela */}
          <div className="rounded-md border">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Data/Hora</TableHead>
                  <TableHead>Evento</TableHead>
                  <TableHead>Descrição</TableHead>
                  <TableHead>IP</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {loading ? (
                  <TableRow>
                    <TableCell colSpan={4} className="text-center">
                      Carregando...
                    </TableCell>
                  </TableRow>
                ) : filteredLogs.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={4} className="text-center text-muted-foreground">
                      Nenhum log encontrado
                    </TableCell>
                  </TableRow>
                ) : (
                  filteredLogs.map((log) => (
                    <TableRow key={log.id}>
                      <TableCell className="font-mono text-xs">
                        {new Date(log.created_at).toLocaleString('pt-BR')}
                      </TableCell>
                      <TableCell>
                        <Badge variant={getEventBadgeVariant(log.tipo_evento)}>
                          {log.tipo_evento}
                        </Badge>
                      </TableCell>
                      <TableCell className="max-w-md truncate">
                        {log.descricao}
                      </TableCell>
                      <TableCell className="font-mono text-xs">
                        {log.ip_address || '-'}
                      </TableCell>
                    </TableRow>
                  ))
                )}
              </TableBody>
            </Table>
          </div>

          <div className="text-sm text-muted-foreground">
            Mostrando {filteredLogs.length} de {logs.length} registros
          </div>
        </CardContent>
      </Card>
    </div>
  );
};

import { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger, DialogFooter } from "@/components/ui/dialog";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { toast } from "sonner";
import {
  Phone,
  Plus,
  Edit,
  Trash2,
  CheckCircle,
  XCircle,
  Loader2,
  Share2,
  Building2,
  Package,
  Brain,
  Settings
} from "lucide-react";

interface Provider {
  id: string;
  nome: string;
  api_base_url: string;
  custo_mensal_numero: number;
  custo_por_mensagem: number;
  moeda: string;
  ativo: boolean;
}

interface PhoneNumber {
  id: string;
  phone_number: string;
  display_name: string;
  is_shared: boolean;
  status: string;
  provider_id: string | null;
  provider?: Provider;
}

interface PhonePackage {
  id: string;
  nome: string;
  descricao: string | null;
  quantidade_numeros: number;
  preco_mensal: number;
  moeda: string;
  inclui_creditos: number;
  planos_permitidos: string[];
  destaque: boolean;
  ativo: boolean;
  stripe_price_id: string | null;
}

interface Allocation {
  id: string;
  tenant_id: string;
  phone_number_id: string;
  departamento: string;
  is_primary: boolean;
  status: string;
  alocado_em: string;
  tenant?: { nome: string };
  phone_number?: PhoneNumber;
}

export function AdminWhatsAppManagement() {
  const [loading, setLoading] = useState(true);
  const [providers, setProviders] = useState<Provider[]>([]);
  const [phoneNumbers, setPhoneNumbers] = useState<PhoneNumber[]>([]);
  const [packages, setPackages] = useState<PhonePackage[]>([]);
  const [allocations, setAllocations] = useState<Allocation[]>([]);

  // Dialog states
  const [newNumberDialog, setNewNumberDialog] = useState(false);
  const [newPackageDialog, setNewPackageDialog] = useState(false);
  const [editingPackage, setEditingPackage] = useState<PhonePackage | null>(null);

  // Form states
  const [newNumber, setNewNumber] = useState({
    phone_number: '',
    display_name: '',
    is_shared: false,
    provider_id: ''
  });
  const [newPackage, setNewPackage] = useState({
    nome: '',
    descricao: '',
    quantidade_numeros: 1,
    preco_mensal: 0,
    inclui_creditos: 0,
    planos_permitidos: ['pro', 'enterprise'],
    destaque: false,
    stripe_price_id: ''
  });

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setLoading(true);
    try {
      const [providersRes, numbersRes, packagesRes, allocationsRes] = await Promise.all([
        supabase.from('whatsapp_providers').select('*').order('nome'),
        supabase.from('whatsapp_phone_numbers').select('*, provider:whatsapp_providers(*)').order('created_at', { ascending: false }),
        supabase.from('phone_number_packages').select('*').order('preco_mensal'),
        supabase.from('tenant_phone_allocations').select(`
          *,
          tenant:tenants(nome),
          phone_number:whatsapp_phone_numbers(*)
        `).eq('status', 'active').order('alocado_em', { ascending: false }).limit(50)
      ]);

      if (providersRes.data) setProviders(providersRes.data);
      if (numbersRes.data) setPhoneNumbers(numbersRes.data);
      if (packagesRes.data) setPackages(packagesRes.data);
      if (allocationsRes.data) setAllocations(allocationsRes.data as any);
    } catch (error) {
      console.error('Error loading data:', error);
      toast.error('Erro ao carregar dados');
    } finally {
      setLoading(false);
    }
  };

  const handleCreateNumber = async () => {
    if (!newNumber.phone_number || !newNumber.display_name) {
      toast.error('Preencha todos os campos obrigatórios');
      return;
    }

    try {
      const { error } = await supabase.from('whatsapp_phone_numbers').insert({
        phone_number: newNumber.phone_number,
        display_name: newNumber.display_name,
        is_shared: newNumber.is_shared,
        provider_id: newNumber.provider_id || null,
        status: 'active'
      });

      if (error) throw error;

      toast.success('Número criado com sucesso');
      setNewNumberDialog(false);
      setNewNumber({ phone_number: '', display_name: '', is_shared: false, provider_id: '' });
      loadData();
    } catch (error: any) {
      console.error('Error creating number:', error);
      toast.error(error.message || 'Erro ao criar número');
    }
  };

  const handleToggleNumberStatus = async (id: string, currentStatus: string) => {
    const newStatus = currentStatus === 'active' ? 'inactive' : 'active';
    try {
      const { error } = await supabase
        .from('whatsapp_phone_numbers')
        .update({ status: newStatus })
        .eq('id', id);

      if (error) throw error;
      toast.success('Status atualizado');
      loadData();
    } catch (error: any) {
      toast.error(error.message || 'Erro ao atualizar status');
    }
  };

  const handleSavePackage = async () => {
    if (!newPackage.nome || newPackage.preco_mensal <= 0) {
      toast.error('Preencha nome e preço');
      return;
    }

    try {
      if (editingPackage) {
        const { error } = await supabase
          .from('phone_number_packages')
          .update({
            nome: newPackage.nome,
            descricao: newPackage.descricao || null,
            quantidade_numeros: newPackage.quantidade_numeros,
            preco_mensal: newPackage.preco_mensal,
            inclui_creditos: newPackage.inclui_creditos,
            planos_permitidos: newPackage.planos_permitidos,
            destaque: newPackage.destaque,
            stripe_price_id: newPackage.stripe_price_id || null
          })
          .eq('id', editingPackage.id);

        if (error) throw error;
        toast.success('Pacote atualizado');
      } else {
        const { error } = await supabase.from('phone_number_packages').insert({
          nome: newPackage.nome,
          descricao: newPackage.descricao || null,
          quantidade_numeros: newPackage.quantidade_numeros,
          preco_mensal: newPackage.preco_mensal,
          inclui_creditos: newPackage.inclui_creditos,
          planos_permitidos: newPackage.planos_permitidos,
          destaque: newPackage.destaque,
          stripe_price_id: newPackage.stripe_price_id || null
        });

        if (error) throw error;
        toast.success('Pacote criado');
      }

      setNewPackageDialog(false);
      setEditingPackage(null);
      setNewPackage({
        nome: '',
        descricao: '',
        quantidade_numeros: 1,
        preco_mensal: 0,
        inclui_creditos: 0,
        planos_permitidos: ['pro', 'enterprise'],
        destaque: false,
        stripe_price_id: ''
      });
      loadData();
    } catch (error: any) {
      toast.error(error.message || 'Erro ao salvar pacote');
    }
  };

  const handleTogglePackageStatus = async (id: string, currentStatus: boolean) => {
    try {
      const { error } = await supabase
        .from('phone_number_packages')
        .update({ ativo: !currentStatus })
        .eq('id', id);

      if (error) throw error;
      toast.success('Status atualizado');
      loadData();
    } catch (error: any) {
      toast.error(error.message || 'Erro ao atualizar status');
    }
  };

  const openEditPackage = (pkg: PhonePackage) => {
    setEditingPackage(pkg);
    setNewPackage({
      nome: pkg.nome,
      descricao: pkg.descricao || '',
      quantidade_numeros: pkg.quantidade_numeros,
      preco_mensal: pkg.preco_mensal,
      inclui_creditos: pkg.inclui_creditos,
      planos_permitidos: pkg.planos_permitidos,
      destaque: pkg.destaque,
      stripe_price_id: pkg.stripe_price_id || ''
    });
    setNewPackageDialog(true);
  };

  const sharedNumber = phoneNumbers.find(p => p.is_shared);

  if (loading) {
    return (
      <div className="flex items-center justify-center p-8">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <Tabs defaultValue="shared" className="space-y-4">
        <TabsList>
          <TabsTrigger value="shared" className="flex items-center gap-2">
            <Share2 className="h-4 w-4" />
            Número Compartilhado
          </TabsTrigger>
          <TabsTrigger value="numbers" className="flex items-center gap-2">
            <Phone className="h-4 w-4" />
            Números
          </TabsTrigger>
          <TabsTrigger value="packages" className="flex items-center gap-2">
            <Package className="h-4 w-4" />
            Pacotes
          </TabsTrigger>
          <TabsTrigger value="allocations" className="flex items-center gap-2">
            <Building2 className="h-4 w-4" />
            Alocações
          </TabsTrigger>
          <TabsTrigger value="providers" className="flex items-center gap-2">
            <Settings className="h-4 w-4" />
            Provedores
          </TabsTrigger>
        </TabsList>

        {/* Número Compartilhado (Free Plan) */}
        <TabsContent value="shared">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Share2 className="h-5 w-5" />
                Número Compartilhado para Plano Gratuito
              </CardTitle>
              <CardDescription>
                Este número é usado por todos os tenants do plano gratuito. A IA identifica automaticamente
                a origem e destino das mensagens baseado no contexto da conversa.
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              {sharedNumber ? (
                <div className="bg-muted/50 rounded-lg p-6 space-y-4">
                  <div className="flex items-center justify-between">
                    <div>
                      <p className="text-sm text-muted-foreground">Número Atual</p>
                      <p className="text-2xl font-bold">{sharedNumber.phone_number}</p>
                      <p className="text-muted-foreground">{sharedNumber.display_name}</p>
                    </div>
                    <Badge variant={sharedNumber.status === 'active' ? 'default' : 'secondary'}>
                      {sharedNumber.status === 'active' ? 'Ativo' : 'Inativo'}
                    </Badge>
                  </div>

                  <div className="flex items-center gap-2 text-sm text-muted-foreground">
                    <Brain className="h-4 w-4" />
                    Roteamento por IA: Identificação automática via contexto de conversa
                  </div>

                  <div className="flex gap-2">
                    <Dialog>
                      <DialogTrigger asChild>
                        <Button variant="outline" size="sm">
                          <Edit className="h-4 w-4 mr-2" />
                          Alterar Número
                        </Button>
                      </DialogTrigger>
                      <DialogContent>
                        <DialogHeader>
                          <DialogTitle>Alterar Número Compartilhado</DialogTitle>
                        </DialogHeader>
                        <div className="space-y-4">
                          <div>
                            <Label>Número de Telefone</Label>
                            <Input
                              placeholder="+5511999999999"
                              defaultValue={sharedNumber.phone_number}
                              onChange={(e) => {
                                // Update directly in state for this specific case
                              }}
                            />
                          </div>
                          <div>
                            <Label>Nome de Exibição</Label>
                            <Input
                              placeholder="CleanFlow Compartilhado"
                              defaultValue={sharedNumber.display_name}
                            />
                          </div>
                        </div>
                        <DialogFooter>
                          <Button onClick={async () => {
                            // Would update the shared number
                            toast.success('Número atualizado');
                          }}>
                            Salvar
                          </Button>
                        </DialogFooter>
                      </DialogContent>
                    </Dialog>

                    <Button
                      variant={sharedNumber.status === 'active' ? 'destructive' : 'default'}
                      size="sm"
                      onClick={() => handleToggleNumberStatus(sharedNumber.id, sharedNumber.status)}
                    >
                      {sharedNumber.status === 'active' ? 'Desativar' : 'Ativar'}
                    </Button>
                  </div>
                </div>
              ) : (
                <div className="text-center py-8 text-muted-foreground">
                  <Share2 className="h-12 w-12 mx-auto mb-4 opacity-50" />
                  <p>Nenhum número compartilhado configurado</p>
                  <Button
                    className="mt-4"
                    onClick={() => {
                      setNewNumber({ phone_number: '', display_name: '', is_shared: true, provider_id: '' });
                      setNewNumberDialog(true);
                    }}
                  >
                    <Plus className="h-4 w-4 mr-2" />
                    Configurar Número Compartilhado
                  </Button>
                </div>
              )}

              <div className="bg-blue-50 dark:bg-blue-950 p-4 rounded-lg">
                <h4 className="font-medium text-blue-900 dark:text-blue-100 mb-2">
                  Como funciona o roteamento por IA?
                </h4>
                <ul className="text-sm text-blue-800 dark:text-blue-200 space-y-1 list-disc list-inside">
                  <li>Quando uma mensagem chega, a IA analisa o contexto histórico da conversa</li>
                  <li>Cruza com os telefones cadastrados nos pacientes de cada tenant</li>
                  <li>Identifica o tenant correto e direciona a mensagem</li>
                  <li>Se não conseguir identificar, a mensagem fica pendente para triagem manual</li>
                </ul>
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        {/* Todos os Números */}
        <TabsContent value="numbers">
          <Card>
            <CardHeader className="flex flex-row items-center justify-between">
              <div>
                <CardTitle>Números de Telefone</CardTitle>
                <CardDescription>Gerencie todos os números WhatsApp do sistema</CardDescription>
              </div>
              <Button onClick={() => {
                setNewNumber({ phone_number: '', display_name: '', is_shared: false, provider_id: '' });
                setNewNumberDialog(true);
              }}>
                <Plus className="h-4 w-4 mr-2" />
                Novo Número
              </Button>
            </CardHeader>
            <CardContent>
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Número</TableHead>
                    <TableHead>Nome</TableHead>
                    <TableHead>Tipo</TableHead>
                    <TableHead>Provedor</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead className="text-right">Ações</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {phoneNumbers.map((number) => (
                    <TableRow key={number.id}>
                      <TableCell className="font-mono">{number.phone_number}</TableCell>
                      <TableCell>{number.display_name}</TableCell>
                      <TableCell>
                        <Badge variant={number.is_shared ? 'secondary' : 'outline'}>
                          {number.is_shared ? 'Compartilhado' : 'Exclusivo'}
                        </Badge>
                      </TableCell>
                      <TableCell>{number.provider?.nome || '-'}</TableCell>
                      <TableCell>
                        <Badge variant={number.status === 'active' ? 'default' : 'secondary'}>
                          {number.status}
                        </Badge>
                      </TableCell>
                      <TableCell className="text-right">
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleToggleNumberStatus(number.id, number.status)}
                        >
                          {number.status === 'active' ? (
                            <XCircle className="h-4 w-4 text-destructive" />
                          ) : (
                            <CheckCircle className="h-4 w-4 text-green-500" />
                          )}
                        </Button>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </CardContent>
          </Card>
        </TabsContent>

        {/* Pacotes */}
        <TabsContent value="packages">
          <Card>
            <CardHeader className="flex flex-row items-center justify-between">
              <div>
                <CardTitle>Pacotes de Números</CardTitle>
                <CardDescription>Configure os pacotes disponíveis para compra pelos tenants</CardDescription>
              </div>
              <Button onClick={() => {
                setEditingPackage(null);
                setNewPackage({
                  nome: '',
                  descricao: '',
                  quantidade_numeros: 1,
                  preco_mensal: 0,
                  inclui_creditos: 0,
                  planos_permitidos: ['pro', 'enterprise'],
                  destaque: false,
                  stripe_price_id: ''
                });
                setNewPackageDialog(true);
              }}>
                <Plus className="h-4 w-4 mr-2" />
                Novo Pacote
              </Button>
            </CardHeader>
            <CardContent>
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Nome</TableHead>
                    <TableHead>Números</TableHead>
                    <TableHead>Preço/mês</TableHead>
                    <TableHead>Créditos Inclusos</TableHead>
                    <TableHead>Planos</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead className="text-right">Ações</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {packages.map((pkg) => (
                    <TableRow key={pkg.id}>
                      <TableCell>
                        <div className="flex items-center gap-2">
                          {pkg.nome}
                          {pkg.destaque && (
                            <Badge variant="secondary" className="text-xs">Destaque</Badge>
                          )}
                        </div>
                      </TableCell>
                      <TableCell>{pkg.quantidade_numeros}</TableCell>
                      <TableCell>
                        {new Intl.NumberFormat('pt-BR', {
                          style: 'currency',
                          currency: pkg.moeda
                        }).format(pkg.preco_mensal)}
                      </TableCell>
                      <TableCell>{pkg.inclui_creditos.toLocaleString()}</TableCell>
                      <TableCell>
                        <div className="flex gap-1">
                          {pkg.planos_permitidos.map(p => (
                            <Badge key={p} variant="outline" className="text-xs">{p}</Badge>
                          ))}
                        </div>
                      </TableCell>
                      <TableCell>
                        <Switch
                          checked={pkg.ativo}
                          onCheckedChange={() => handleTogglePackageStatus(pkg.id, pkg.ativo)}
                        />
                      </TableCell>
                      <TableCell className="text-right">
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => openEditPackage(pkg)}
                        >
                          <Edit className="h-4 w-4" />
                        </Button>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </CardContent>
          </Card>
        </TabsContent>

        {/* Alocações */}
        <TabsContent value="allocations">
          <Card>
            <CardHeader>
              <CardTitle>Alocações Ativas</CardTitle>
              <CardDescription>Visualize quais tenants estão usando quais números</CardDescription>
            </CardHeader>
            <CardContent>
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Tenant</TableHead>
                    <TableHead>Número</TableHead>
                    <TableHead>Departamento</TableHead>
                    <TableHead>Tipo</TableHead>
                    <TableHead>Alocado em</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {allocations.length === 0 ? (
                    <TableRow>
                      <TableCell colSpan={5} className="text-center text-muted-foreground py-8">
                        Nenhuma alocação encontrada
                      </TableCell>
                    </TableRow>
                  ) : (
                    allocations.map((alloc) => (
                      <TableRow key={alloc.id}>
                        <TableCell>{alloc.tenant?.nome || alloc.tenant_id}</TableCell>
                        <TableCell className="font-mono">{alloc.phone_number?.phone_number}</TableCell>
                        <TableCell>
                          <Badge variant="outline">{alloc.departamento}</Badge>
                        </TableCell>
                        <TableCell>
                          {alloc.phone_number?.is_shared ? (
                            <Badge variant="secondary">Compartilhado</Badge>
                          ) : (
                            <Badge>Exclusivo</Badge>
                          )}
                        </TableCell>
                        <TableCell>
                          {new Date(alloc.alocado_em).toLocaleDateString('pt-BR')}
                        </TableCell>
                      </TableRow>
                    ))
                  )}
                </TableBody>
              </Table>
            </CardContent>
          </Card>
        </TabsContent>

        {/* Provedores */}
        <TabsContent value="providers">
          <Card>
            <CardHeader>
              <CardTitle>Provedores de Números Virtuais</CardTitle>
              <CardDescription>Configuração dos provedores integrados</CardDescription>
            </CardHeader>
            <CardContent>
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Provedor</TableHead>
                    <TableHead>API</TableHead>
                    <TableHead>Custo/Número/Mês</TableHead>
                    <TableHead>Custo/Mensagem</TableHead>
                    <TableHead>Status</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {providers.map((provider) => (
                    <TableRow key={provider.id}>
                      <TableCell className="font-medium">{provider.nome}</TableCell>
                      <TableCell className="text-xs text-muted-foreground truncate max-w-[200px]">{provider.api_base_url}</TableCell>
                      <TableCell>
                        {new Intl.NumberFormat('pt-BR', {
                          style: 'currency',
                          currency: provider.moeda
                        }).format(provider.custo_mensal_numero)}
                      </TableCell>
                      <TableCell>
                        {new Intl.NumberFormat('pt-BR', {
                          style: 'currency',
                          currency: provider.moeda
                        }).format(provider.custo_por_mensagem)}
                      </TableCell>
                      <TableCell>
                        <Badge variant={provider.ativo ? 'default' : 'secondary'}>
                          {provider.ativo ? 'Ativo' : 'Inativo'}
                        </Badge>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>

              <div className="mt-4 bg-amber-50 dark:bg-amber-950 p-4 rounded-lg">
                <h4 className="font-medium text-amber-900 dark:text-amber-100 mb-2">
                  Sobre os Provedores
                </h4>
                <p className="text-sm text-amber-800 dark:text-amber-200">
                  Os provedores são pré-configurados no sistema. Para adicionar novos provedores
                  ou alterar credenciais de API, entre em contato com a equipe de desenvolvimento.
                </p>
              </div>
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>

      {/* Dialog Novo Número */}
      <Dialog open={newNumberDialog} onOpenChange={setNewNumberDialog}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>
              {newNumber.is_shared ? 'Configurar Número Compartilhado' : 'Adicionar Novo Número'}
            </DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <Label>Número de Telefone *</Label>
              <Input
                placeholder="+5511999999999"
                value={newNumber.phone_number}
                onChange={(e) => setNewNumber({ ...newNumber, phone_number: e.target.value })}
              />
            </div>
            <div>
              <Label>Nome de Exibição *</Label>
              <Input
                placeholder="Ex: CleanFlow Atendimento"
                value={newNumber.display_name}
                onChange={(e) => setNewNumber({ ...newNumber, display_name: e.target.value })}
              />
            </div>
            <div>
              <Label>Provedor</Label>
              <Select
                value={newNumber.provider_id}
                onValueChange={(v) => setNewNumber({ ...newNumber, provider_id: v })}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Selecione um provedor" />
                </SelectTrigger>
                <SelectContent>
                  {providers.filter(p => p.ativo).map(p => (
                    <SelectItem key={p.id} value={p.id}>{p.nome}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="flex items-center gap-2">
              <Switch
                checked={newNumber.is_shared}
                onCheckedChange={(v) => setNewNumber({ ...newNumber, is_shared: v })}
              />
              <Label>Número compartilhado (para plano gratuito)</Label>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setNewNumberDialog(false)}>Cancelar</Button>
            <Button onClick={handleCreateNumber}>Criar Número</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Dialog Pacote */}
      <Dialog open={newPackageDialog} onOpenChange={(open) => {
        setNewPackageDialog(open);
        if (!open) setEditingPackage(null);
      }}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>
              {editingPackage ? 'Editar Pacote' : 'Novo Pacote'}
            </DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <Label>Nome *</Label>
              <Input
                placeholder="Ex: Pacote Profissional"
                value={newPackage.nome}
                onChange={(e) => setNewPackage({ ...newPackage, nome: e.target.value })}
              />
            </div>
            <div>
              <Label>Descrição</Label>
              <Input
                placeholder="Descrição do pacote"
                value={newPackage.descricao}
                onChange={(e) => setNewPackage({ ...newPackage, descricao: e.target.value })}
              />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <Label>Qtd. Números</Label>
                <Input
                  type="number"
                  min={1}
                  value={newPackage.quantidade_numeros}
                  onChange={(e) => setNewPackage({ ...newPackage, quantidade_numeros: parseInt(e.target.value) || 1 })}
                />
              </div>
              <div>
                <Label>Preço/Mês (R$)</Label>
                <Input
                  type="number"
                  min={0}
                  step={0.01}
                  value={newPackage.preco_mensal}
                  onChange={(e) => setNewPackage({ ...newPackage, preco_mensal: parseFloat(e.target.value) || 0 })}
                />
              </div>
            </div>
            <div>
              <Label>Créditos Inclusos</Label>
              <Input
                type="number"
                min={0}
                value={newPackage.inclui_creditos}
                onChange={(e) => setNewPackage({ ...newPackage, inclui_creditos: parseInt(e.target.value) || 0 })}
              />
            </div>
            <div>
              <Label>Stripe Price ID (opcional)</Label>
              <Input
                placeholder="price_xxxxx"
                value={newPackage.stripe_price_id}
                onChange={(e) => setNewPackage({ ...newPackage, stripe_price_id: e.target.value })}
              />
            </div>
            <div className="flex items-center gap-2">
              <Switch
                checked={newPackage.destaque}
                onCheckedChange={(v) => setNewPackage({ ...newPackage, destaque: v })}
              />
              <Label>Destacar este pacote</Label>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setNewPackageDialog(false)}>Cancelar</Button>
            <Button onClick={handleSavePackage}>
              {editingPackage ? 'Atualizar' : 'Criar'} Pacote
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { Button } from "@/components/ui/button";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { Shield, Trash2, CheckCircle2, XCircle, Clock } from "lucide-react";
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle, AlertDialogTrigger } from "@/components/ui/alert-dialog";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";

interface AnonymizationRequest {
  id: string;
  tenant_id: string;
  contact_type: 'paciente' | 'usuario' | 'tenant_contato';
  contact_id: string;
  status: 'pending' | 'processing' | 'completed' | 'failed';
  created_at: string;
  processed_at: string | null;
  error_message: string | null;
}

interface Patient {
  id: string;
  nome: string;
  email: string | null;
}

export const AnonymizationManager = () => {
  const [requests, setRequests] = useState<AnonymizationRequest[]>([]);
  const [patients, setPatients] = useState<Patient[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedPatient, setSelectedPatient] = useState<string>("");
  const [tenantId, setTenantId] = useState<string>("");
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const { toast } = useToast();

  useEffect(() => {
    loadRequests();
    loadTenantInfo();
  }, []);

  const loadTenantInfo = async () => {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      const { data: profile } = await supabase
        .from('profiles')
        .select('tenant_id')
        .eq('id', user.id)
        .maybeSingle();

      if (profile?.tenant_id) {
        setTenantId(profile.tenant_id);
        loadPatients(profile.tenant_id);
      }
    } catch (error: any) {
      console.error("Erro ao carregar tenant:", error);
    }
  };

  const loadPatients = async (tid: string) => {
    try {
      const { data, error } = await supabase
        .from('pacientes')
        .select('id, nome, email')
        .eq('tenant_id', tid)
        .order('nome');

      if (error) throw error;
      setPatients(data || []);
    } catch (error: any) {
      toast({
        title: "Erro ao carregar pacientes",
        description: error.message,
        variant: "destructive",
      });
    }
  };

  const loadRequests = async () => {
    try {
      const { data, error } = await supabase
        .from('anonymization_requests')
        .select('*')
        .order('created_at', { ascending: false });

      if (error) throw error;
      setRequests((data || []) as AnonymizationRequest[]);
    } catch (error: any) {
      toast({
        title: "Erro ao carregar solicitações",
        description: error.message,
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const handleCreateRequest = async () => {
    if (!selectedPatient || !tenantId) {
      toast({
        title: "Erro",
        description: "Selecione um paciente",
        variant: "destructive",
      });
      return;
    }

    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error("Usuário não autenticado");

      const { error } = await supabase
        .from('anonymization_requests')
        .insert({
          tenant_id: tenantId,
          contact_type: 'paciente',
          contact_id: selectedPatient,
          requested_by: user.id,
        });

      if (error) throw error;

      toast({
        title: "Solicitação criada",
        description: "A solicitação de anonimização foi criada com sucesso",
      });

      setIsDialogOpen(false);
      setSelectedPatient("");
      loadRequests();
    } catch (error: any) {
      toast({
        title: "Erro ao criar solicitação",
        description: error.message,
        variant: "destructive",
      });
    }
  };

  const handleProcessRequest = async (requestId: string) => {
    try {
      const { error } = await supabase.rpc('anonymize_contact_data', {
        p_request_id: requestId
      });

      if (error) throw error;

      toast({
        title: "Dados anonimizados",
        description: "Os dados foram anonimizados com sucesso",
      });

      loadRequests();
    } catch (error: any) {
      toast({
        title: "Erro ao anonimizar",
        description: error.message,
        variant: "destructive",
      });
    }
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'pending':
        return <Badge variant="outline"><Clock className="h-3 w-3 mr-1" />Pendente</Badge>;
      case 'processing':
        return <Badge><Clock className="h-3 w-3 mr-1" />Processando</Badge>;
      case 'completed':
        return <Badge variant="default" className="bg-green-500"><CheckCircle2 className="h-3 w-3 mr-1" />Concluído</Badge>;
      case 'failed':
        return <Badge variant="destructive"><XCircle className="h-3 w-3 mr-1" />Falhou</Badge>;
      default:
        return <Badge variant="outline">{status}</Badge>;
    }
  };

  if (loading) {
    return <div className="p-4">Carregando solicitações...</div>;
  }

  return (
    <Card>
      <CardHeader>
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Shield className="h-5 w-5" />
            <div>
              <CardTitle>Anonimização de Dados (LGPD)</CardTitle>
              <CardDescription>
                Gerenciar solicitações de anonimização de dados pessoais
              </CardDescription>
            </div>
          </div>
          <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
            <DialogTrigger asChild>
              <Button>
                <Trash2 className="h-4 w-4 mr-2" />
                Nova Solicitação
              </Button>
            </DialogTrigger>
            <DialogContent>
              <DialogHeader>
                <DialogTitle>Solicitar Anonimização</DialogTitle>
                <DialogDescription>
                  Selecione o paciente cujos dados deseja anonimizar. Esta ação não pode ser desfeita.
                </DialogDescription>
              </DialogHeader>
              <div className="space-y-4 py-4">
                <Select value={selectedPatient} onValueChange={setSelectedPatient}>
                  <SelectTrigger>
                    <SelectValue placeholder="Selecione um paciente" />
                  </SelectTrigger>
                  <SelectContent>
                    {patients.map((patient) => (
                      <SelectItem key={patient.id} value={patient.id}>
                        {patient.nome} {patient.email ? `(${patient.email})` : ''}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <DialogFooter>
                <Button variant="outline" onClick={() => setIsDialogOpen(false)}>
                  Cancelar
                </Button>
                <Button onClick={handleCreateRequest} variant="destructive">
                  Criar Solicitação
                </Button>
              </DialogFooter>
            </DialogContent>
          </Dialog>
        </div>
      </CardHeader>
      <CardContent>
        {requests.length === 0 ? (
          <div className="text-center text-muted-foreground py-8">
            Nenhuma solicitação de anonimização
          </div>
        ) : (
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Tipo</TableHead>
                <TableHead>Status</TableHead>
                <TableHead>Criado em</TableHead>
                <TableHead>Processado em</TableHead>
                <TableHead>Ações</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {requests.map((request) => (
                <TableRow key={request.id}>
                  <TableCell>
                    <Badge variant="outline">{request.contact_type}</Badge>
                  </TableCell>
                  <TableCell>{getStatusBadge(request.status)}</TableCell>
                  <TableCell className="text-sm">
                    {new Date(request.created_at).toLocaleString('pt-BR')}
                  </TableCell>
                  <TableCell className="text-sm">
                    {request.processed_at 
                      ? new Date(request.processed_at).toLocaleString('pt-BR')
                      : '-'}
                  </TableCell>
                  <TableCell>
                    {request.status === 'pending' && (
                      <AlertDialog>
                        <AlertDialogTrigger asChild>
                          <Button variant="destructive" size="sm">
                            <Trash2 className="h-4 w-4 mr-1" />
                            Processar
                          </Button>
                        </AlertDialogTrigger>
                        <AlertDialogContent>
                          <AlertDialogHeader>
                            <AlertDialogTitle>Confirmar anonimização</AlertDialogTitle>
                            <AlertDialogDescription>
                              Esta ação é irreversível. Os dados pessoais serão permanentemente anonimizados.
                              Deseja continuar?
                            </AlertDialogDescription>
                          </AlertDialogHeader>
                          <AlertDialogFooter>
                            <AlertDialogCancel>Cancelar</AlertDialogCancel>
                            <AlertDialogAction 
                              onClick={() => handleProcessRequest(request.id)}
                              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
                            >
                              Anonimizar
                            </AlertDialogAction>
                          </AlertDialogFooter>
                        </AlertDialogContent>
                      </AlertDialog>
                    )}
                    {request.status === 'failed' && request.error_message && (
                      <span className="text-xs text-destructive">{request.error_message}</span>
                    )}
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        )}
      </CardContent>
    </Card>
  );
};

import { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Label } from "@/components/ui/label";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { AlertTriangle, Loader2, Check } from "lucide-react";

interface ChangeSegmentDialogProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    tenantId: string;
    onSuccess: () => void;
}

const SEGMENTOS = [
    { codigo: 'saude', nome: 'Saúde' },
    { codigo: 'estetica', nome: 'Estética & Beleza' },
    { codigo: 'veterinaria', nome: 'Veterinária' },
    { codigo: 'odontologia', nome: 'Odontologia' },
    { codigo: 'educacao', nome: 'Educação & Cursos' },
    { codigo: 'oficina', nome: 'Oficina & Serviços' },
];

export const ChangeSegmentDialog = ({ open, onOpenChange, tenantId, onSuccess }: ChangeSegmentDialogProps) => {
    const [loading, setLoading] = useState(false);
    const [checkingData, setCheckingData] = useState(true);
    const [hasData, setHasData] = useState(false);
    const [currentSegment, setCurrentSegment] = useState("");
    const [newSegment, setNewSegment] = useState("");
    const [dataCheckDetails, setDataCheckDetails] = useState<string[]>([]);

    useEffect(() => {
        if (open && tenantId) {
            fetchCurrentSegment();
            checkTenantData();
        }
    }, [open, tenantId]);

    const fetchCurrentSegment = async () => {
        try {
            const { data, error } = await supabase
                .from('tenant_profile')
                .select('segmentos')
                .eq('tenant_id', tenantId)
                .single();

            if (error) throw error;

            const segmentos = data?.segmentos as Array<{ codigo: string }> | null;
            const codigo = segmentos?.[0]?.codigo || '';
            setCurrentSegment(codigo);
            setNewSegment(codigo);
        } catch (error) {
            console.error("Error fetching segment:", error);
            toast.error("Erro ao carregar segmento atual");
        }
    };

    const checkTenantData = async () => {
        setCheckingData(true);
        setHasData(false);
        setDataCheckDetails([]);

        try {
            const details: string[] = [];
            let foundData = false;

            // Check Pacientes
            const { count: pacientesCount, error: pacientesError } = await supabase
                .from('pacientes')
                .select('*', { count: 'exact', head: true })
                .eq('tenant_id', tenantId);

            if (pacientesError) throw pacientesError;
            if (pacientesCount && pacientesCount > 0) {
                foundData = true;
                details.push(`${pacientesCount} pacientes cadastrados`);
            }

            // Check Agendamentos
            const { count: agendamentosCount, error: agendamentosError } = await supabase
                .from('agendamentos')
                .select('*', { count: 'exact', head: true })
                .eq('tenant_id', tenantId);

            if (agendamentosError) throw agendamentosError;
            if (agendamentosCount && agendamentosCount > 0) {
                foundData = true;
                details.push(`${agendamentosCount} agendamentos registrados`);
            }

            // Check Prontuarios/Fichas (if table exists, assuming 'prontuarios' for now based on context)
            // We can add more checks here as needed.

            setHasData(foundData);
            setDataCheckDetails(details);

        } catch (error) {
            console.error("Error checking tenant data:", error);
            toast.error("Erro ao verificar dados do tenant");
        } finally {
            setCheckingData(false);
        }
    };

    const handleSave = async () => {
        if (newSegment === currentSegment) {
            onOpenChange(false);
            return;
        }

        setLoading(true);
        try {
            // Update tenant_profile
            // First get the current profile to preserve other fields if needed, 
            // but we are just updating the segments array.

            // We need to construct the segments array. Assuming single segment for now as per previous code.
            const newSegmentsArray = [{ codigo: newSegment }];

            const { error } = await supabase
                .from('tenant_profile')
                .update({ segments: newSegmentsArray } as any) // Type casting might be needed depending on generated types
                .eq('tenant_id', tenantId);

            if (error) throw error;

            // Log the action
            const { data: { user } } = await supabase.auth.getUser();
            if (user) {
                await supabase.from("support_actions_log").insert({
                    support_user_id: user.id,
                    action_type: "tenant_segment_change",
                    target_type: "tenant",
                    target_id: tenantId,
                    description: `Segmento alterado de ${currentSegment} para ${newSegment}`,
                });
            }

            toast.success("Segmento alterado com sucesso");
            onSuccess();
            onOpenChange(false);
        } catch (error) {
            console.error("Error changing segment:", error);
            toast.error("Erro ao alterar segmento");
        } finally {
            setLoading(false);
        }
    };

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="max-w-md">
                <DialogHeader>
                    <DialogTitle>Trocar Segmento do Tenant</DialogTitle>
                    <DialogDescription>
                        Alteração de segmento para correção de cadastro.
                    </DialogDescription>
                </DialogHeader>

                {checkingData ? (
                    <div className="flex items-center justify-center py-8">
                        <Loader2 className="h-8 w-8 animate-spin text-primary" />
                        <span className="ml-2">Verificando dados...</span>
                    </div>
                ) : hasData ? (
                    <div className="space-y-4">
                        <Alert variant="destructive">
                            <AlertTriangle className="h-4 w-4" />
                            <AlertTitle>Alteração Bloqueada</AlertTitle>
                            <AlertDescription>
                                Este tenant possui dados cadastrados e não pode trocar de segmento.
                                <ul className="list-disc list-inside mt-2">
                                    {dataCheckDetails.map((detail, index) => (
                                        <li key={index}>{detail}</li>
                                    ))}
                                </ul>
                            </AlertDescription>
                        </Alert>
                        <p className="text-sm text-muted-foreground">
                            Para realizar a troca, o tenant deve excluir todos os dados inseridos manualmente.
                        </p>
                        <DialogFooter>
                            <Button variant="outline" onClick={() => onOpenChange(false)}>Fechar</Button>
                        </DialogFooter>
                    </div>
                ) : (
                    <div className="space-y-4">
                        <div className="space-y-2">
                            <Label>Segmento Atual</Label>
                            <div className="p-2 border rounded bg-muted text-sm">
                                {SEGMENTOS.find(s => s.codigo === currentSegment)?.nome || currentSegment}
                            </div>
                        </div>

                        <div className="space-y-2">
                            <Label>Novo Segmento</Label>
                            <Select value={newSegment} onValueChange={setNewSegment}>
                                <SelectTrigger>
                                    <SelectValue placeholder="Selecione o novo segmento" />
                                </SelectTrigger>
                                <SelectContent>
                                    {SEGMENTOS.map((seg) => (
                                        <SelectItem key={seg.codigo} value={seg.codigo} disabled={seg.codigo === currentSegment}>
                                            {seg.nome}
                                        </SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                        </div>

                        <Alert>
                            <Check className="h-4 w-4" />
                            <AlertTitle>Pronto para alterar</AlertTitle>
                            <AlertDescription>
                                Nenhum dado impeditivo foi encontrado. A troca pode ser realizada.
                            </AlertDescription>
                        </Alert>

                        <DialogFooter>
                            <Button variant="outline" onClick={() => onOpenChange(false)}>Cancelar</Button>
                            <Button onClick={handleSave} disabled={loading || newSegment === currentSegment}>
                                {loading ? <Loader2 className="h-4 w-4 animate-spin mr-2" /> : null}
                                Confirmar Troca
                            </Button>
                        </DialogFooter>
                    </div>
                )}
            </DialogContent>
        </Dialog>
    );
};

import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { WhatsAppConversationList } from "./WhatsAppConversationList";
import { WhatsAppMessageView } from "./WhatsAppMessageView";

interface Conversation {
  id: string;
  telefone: string;
  paciente_nome?: string;
  status: string;
  ultima_mensagem?: string;
  ultima_mensagem_em?: string;
  mensagens_nao_lidas?: number;
  created_at: string;
  tenant_id: string;
}

export function ChatUnificado() {
  const [conversations, setConversations] = useState<Conversation[]>([]);
  const [selectedConversation, setSelectedConversation] = useState<Conversation | null>(null);

  useEffect(() => {
    loadConversations();
    subscribeToConversations();
  }, []);

  const loadConversations = async () => {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      const { data: profile } = await supabase
        .from("profiles")
        .select("tenant_id")
        .eq("id", user.id)
        .single();

      if (!profile?.tenant_id) return;

      const { data, error } = await supabase
        .from("whatsapp_conversations")
        .select(`
          *,
          pacientes:paciente_id(nome)
        `)
        .eq("tenant_id", profile.tenant_id)
        .in("status", ["aguardando", "em_atendimento"])
        .order("created_at", { ascending: false });

      if (error) throw error;

      const formattedData = data?.map(conv => ({
        ...conv,
        paciente_nome: conv.pacientes?.nome,
        tenant_id: profile.tenant_id
      })) || [];

      setConversations(formattedData);
    } catch (error) {
      console.error("Erro ao carregar conversas:", error);
      toast.error("Erro ao carregar conversas");
    }
  };

  const subscribeToConversations = () => {
    const channel = supabase
      .channel("whatsapp-conversations")
      .on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "whatsapp_conversations",
        },
        () => {
          loadConversations();
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  };

  const handleTakeConversation = async (conversationId: string) => {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error("Usuário não autenticado");

      const { error } = await supabase
        .from("whatsapp_conversations")
        .update({
          status: "em_atendimento",
          atendente_id: user.id,
        })
        .eq("id", conversationId);

      if (error) throw error;

      toast.success("Conversa assumida com sucesso");
      loadConversations();

      const conversation = conversations.find(c => c.id === conversationId);
      if (conversation) {
        setSelectedConversation({ ...conversation, status: "em_atendimento" });
      }
    } catch (error) {
      console.error("Erro ao assumir conversa:", error);
      toast.error("Erro ao assumir conversa");
    }
  };

  const handleResolveConversation = () => {
    setSelectedConversation(null);
    loadConversations();
  };

  if (selectedConversation) {
    return (
      <WhatsAppMessageView
        conversation={selectedConversation}
        onClose={() => setSelectedConversation(null)}
        onResolve={handleResolveConversation}
      />
    );
  }

  return (
    <div className="h-[calc(100vh-200px)]">
      <WhatsAppConversationList
        conversations={conversations}
        selectedConversationId={selectedConversation?.id}
        onSelectConversation={(id) => {
          const conv = conversations.find(c => c.id === id);
          if (conv) setSelectedConversation(conv);
        }}
        onTakeConversation={handleTakeConversation}
      />
    </div>
  );
}

import { useEffect, useState, useRef } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Sheet, SheetContent, SheetHeader, SheetTitle } from "@/components/ui/sheet";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Badge } from "@/components/ui/badge";
import { Card } from "@/components/ui/card";
import { useSupportChat, ChatSession, ChatMessage } from "@/hooks/useSupportChat";
import { ArrowLeft, Send, CheckCircle2, Ticket, Clock } from "lucide-react";
import { formatDistanceToNow } from "date-fns";
import { ptBR } from "date-fns/locale";
import { toast } from "sonner";
import { useNavigate } from "react-router-dom";

interface ChatWindowProps {
  sessionId: string;
  onClose: () => void;
}

export const ChatWindow = ({ sessionId, onClose }: ChatWindowProps) => {
  const navigate = useNavigate();
  const [session, setSession] = useState<ChatSession | null>(null);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [newMessage, setNewMessage] = useState("");
  const [sending, setSending] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const { sendMessage, resolveChat, elevateToTicket } = useSupportChat();

  useEffect(() => {
    loadSession();
    loadMessages();
    subscribeToMessages();
  }, [sessionId]);

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const loadSession = async () => {
    try {
      const { data, error } = await supabase
        .from('support_chat_sessions')
        .select('*')
        .eq('id', sessionId)
        .single();

      if (error) throw error;
      setSession(data as ChatSession);
    } catch (error) {
      console.error('Error loading session:', error);
      toast.error('Erro ao carregar sessão');
    }
  };

  const loadMessages = async () => {
    try {
      const { data, error } = await supabase
        .from('support_chat_messages')
        .select('*')
        .eq('session_id', sessionId)
        .order('created_at', { ascending: true });

      if (error) throw error;
      setMessages((data || []) as ChatMessage[]);
    } catch (error) {
      console.error('Error loading messages:', error);
    }
  };

  const subscribeToMessages = () => {
    const channel = supabase
      .channel(`chat-${sessionId}`)
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'support_chat_messages',
          filter: `session_id=eq.${sessionId}`
        },
        (payload) => {
          setMessages((prev) => [...prev, payload.new as ChatMessage]);
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  };

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  const handleSendMessage = async () => {
    if (!newMessage.trim() || sending) return;

    setSending(true);
    const success = await sendMessage(sessionId, newMessage);
    if (success) {
      setNewMessage("");
    }
    setSending(false);
  };

  const handleResolveChat = async () => {
    const success = await resolveChat(sessionId);
    if (success) {
      onClose();
    }
  };

  const handleElevateToTicket = async () => {
    const ticket = await elevateToTicket(sessionId);
    if (ticket) {
      onClose();
      navigate('/admin', { state: { openTicket: ticket.id } });
    }
  };

  const getWaitTime = () => {
    if (!session?.started_at) return '';
    return formatDistanceToNow(new Date(session.started_at), {
      addSuffix: false,
      locale: ptBR,
    });
  };

  if (!session) {
    return null;
  }

  return (
    <Sheet open={true} onOpenChange={onClose}>
      <SheetContent side="right" className="w-full sm:w-[600px] sm:max-w-[600px] flex flex-col p-0">
        <SheetHeader className="p-6 pb-4 border-b">
          <div className="flex items-center gap-2">
            <Button variant="ghost" size="icon" onClick={onClose}>
              <ArrowLeft className="h-4 w-4" />
            </Button>
            <div className="flex-1">
              <SheetTitle className="text-left">
                {session.client_name || "Cliente Anônimo"}
              </SheetTitle>
              {session.client_email && (
                <p className="text-sm text-muted-foreground">{session.client_email}</p>
              )}
            </div>
            <div className="flex items-center gap-2">
              <Badge variant="secondary" className="flex items-center gap-1">
                <Clock className="h-3 w-3" />
                {getWaitTime()}
              </Badge>
              {session.status === 'active' && (
                <Badge>Em andamento</Badge>
              )}
            </div>
          </div>
        </SheetHeader>

        <Card className="m-4 p-4 bg-muted/50">
          <div className="grid grid-cols-2 gap-4 text-sm">
            {session.client_phone && (
              <div>
                <span className="text-muted-foreground">Telefone:</span>
                <p className="font-medium">{session.client_phone}</p>
              </div>
            )}
            {session.started_at && (
              <div>
                <span className="text-muted-foreground">Iniciado:</span>
                <p className="font-medium">
                  {new Date(session.started_at).toLocaleString('pt-BR')}
                </p>
              </div>
            )}
          </div>
        </Card>

        <ScrollArea className="flex-1 px-6">
          <div className="space-y-4 pb-4">
            {messages.map((message) => (
              <div
                key={message.id}
                className={`flex ${
                  message.sender_type === 'agent' ? 'justify-end' : 'justify-start'
                }`}
              >
                <div
                  className={`max-w-[80%] rounded-lg px-4 py-2 ${
                    message.sender_type === 'agent'
                      ? 'bg-primary text-primary-foreground'
                      : message.sender_type === 'system'
                      ? 'bg-muted text-muted-foreground text-center'
                      : 'bg-muted'
                  }`}
                >
                  <p className="whitespace-pre-wrap break-words">{message.message}</p>
                  <p className="text-xs opacity-70 mt-1">
                    {new Date(message.created_at).toLocaleTimeString('pt-BR', {
                      hour: '2-digit',
                      minute: '2-digit',
                    })}
                  </p>
                </div>
              </div>
            ))}
            <div ref={messagesEndRef} />
          </div>
        </ScrollArea>

        <div className="p-4 border-t space-y-2">
          <div className="flex gap-2">
            <Button
              variant="outline"
              size="sm"
              onClick={handleResolveChat}
              disabled={session.status !== 'active'}
            >
              <CheckCircle2 className="h-4 w-4 mr-2" />
              Resolver
            </Button>
            <Button
              variant="outline"
              size="sm"
              onClick={handleElevateToTicket}
              disabled={session.status !== 'active'}
            >
              <Ticket className="h-4 w-4 mr-2" />
              Elevar a Ticket
            </Button>
          </div>

          <div className="flex gap-2">
            <Textarea
              value={newMessage}
              onChange={(e) => setNewMessage(e.target.value)}
              placeholder="Digite sua mensagem..."
              className="min-h-[60px] resize-none"
              onKeyDown={(e) => {
                if (e.key === 'Enter' && !e.shiftKey) {
                  e.preventDefault();
                  handleSendMessage();
                }
              }}
              disabled={session.status !== 'active'}
            />
            <Button
              onClick={handleSendMessage}
              disabled={!newMessage.trim() || sending || session.status !== 'active'}
              size="icon"
              className="h-[60px] w-[60px]"
            >
              <Send className="h-4 w-4" />
            </Button>
          </div>
        </div>
      </SheetContent>
    </Sheet>
  );
};

