                    {checkin.pronto_atendimento ? (
                      <Badge variant="default" className="bg-green-500">
                        <CheckCircle className="h-3 w-3 mr-1" />
                        Sim
                      </Badge>
                    ) : (
                      <Badge variant="outline">Não</Badge>
                    )}
                  </TableCell>
                  <TableCell>
                    <Button
                      variant="ghost"
                      size="icon"
                      onClick={() => setSelectedCheckin(checkin)}
                    >
                      <Eye className="h-4 w-4" />
                    </Button>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>

          {checkins.length === 0 && (
            <div className="text-center py-8 text-muted-foreground">
              Nenhum check-in registrado
            </div>
          )}
        </CardContent>
      </Card>

      {selectedCheckin && (
        <Dialog open={!!selectedCheckin} onOpenChange={() => setSelectedCheckin(null)}>
          <DialogContent className="max-w-2xl">
            <DialogHeader>
              <DialogTitle>Detalhes do Check-in</DialogTitle>
            </DialogHeader>
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <p className="text-sm font-medium">Paciente</p>
                  <p className="text-sm text-muted-foreground">
                    {selectedCheckin.pacientes?.nome}
                  </p>
                </div>
                <div>
                  <p className="text-sm font-medium">Telefone</p>
                  <p className="text-sm text-muted-foreground">
                    {selectedCheckin.pacientes?.telefone}
                  </p>
                </div>
                <div>
                  <p className="text-sm font-medium">Convênio</p>
                  <p className="text-sm text-muted-foreground">
                    {selectedCheckin.convenio || "-"}
                  </p>
                </div>
                <div>
                  <p className="text-sm font-medium">Nº Carteirinha</p>
                  <p className="text-sm text-muted-foreground">
                    {selectedCheckin.numero_carteirinha || "-"}
                  </p>
                </div>
              </div>

              {selectedCheckin.foto_frente_url && (
                <div>
                  <p className="text-sm font-medium mb-2">Foto Frente</p>
                  <img
                    src={selectedCheckin.foto_frente_url}
                    alt="Frente"
                    className="max-w-xs rounded border"
                  />
                </div>
              )}

              {selectedCheckin.foto_verso_url && (
                <div>
                  <p className="text-sm font-medium mb-2">Foto Verso</p>
                  <img
                    src={selectedCheckin.foto_verso_url}
                    alt="Verso"
                    className="max-w-xs rounded border"
                  />
                </div>
              )}

              <div>
                <p className="text-sm font-medium">Motivo da Consulta</p>
                <p className="text-sm text-muted-foreground">
                  {selectedCheckin.motivo_consulta || "-"}
                </p>
              </div>

              <div className="grid grid-cols-3 gap-4">
                <div>
                  <p className="text-sm font-medium">Consentimento LGPD</p>
                  <Badge variant={selectedCheckin.consentimento_lgpd ? "default" : "outline"}>
                    {selectedCheckin.consentimento_lgpd ? "Sim" : "Não"}
                  </Badge>
                </div>
                <div>
                  <p className="text-sm font-medium">Opt-in Lembretes</p>
                  <Badge variant={selectedCheckin.opt_in_lembretes ? "default" : "outline"}>
                    {selectedCheckin.opt_in_lembretes ? "Sim" : "Não"}
                  </Badge>
                </div>
                <div>
                  <p className="text-sm font-medium">Opt-in Promoções</p>
                  <Badge variant={selectedCheckin.opt_in_promocoes ? "default" : "outline"}>
                    {selectedCheckin.opt_in_promocoes ? "Sim" : "Não"}
                  </Badge>
                </div>
              </div>

              {selectedCheckin.ultimo_erro && (
                <div className="bg-destructive/10 p-3 rounded">
                  <p className="text-sm font-medium text-destructive">Último Erro</p>
                  <p className="text-sm text-destructive/80">
                    {selectedCheckin.ultimo_erro}
                  </p>
                </div>
              )}
            </div>
          </DialogContent>
        </Dialog>
      )}
    </>
  );
}

import { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { toast } from "sonner";
import { Shield, CheckCircle, XCircle, AlertTriangle } from "lucide-react";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";

interface ConsentRecord {
  id: string;
  contact_id: string;
  consent_type: string;
  status: string;
  origin: string;
  term_version: string;
  given_at: string;
  expires_at: string | null;
  revoked_at: string | null;
}

export function ConsentManagement() {
  const [consents, setConsents] = useState<ConsentRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [anonymizePatientId, setAnonymizePatientId] = useState<string | null>(null);

  useEffect(() => {
    loadConsents();
  }, []);

  const loadConsents = async () => {
    try {
      setLoading(true);

      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error('Não autenticado');

      const { data: profile } = await supabase
        .from('profiles')
        .select('tenant_id')
        .eq('id', user.id)
        .single();

      if (!profile?.tenant_id) throw new Error('Tenant não encontrado');

      const { data, error } = await supabase
        .from('consent_records' as any)
        .select('*')
        .eq('tenant_id', profile.tenant_id)
        .order('given_at', { ascending: false });

      if (error) throw error;
      setConsents((data as any) || []);
    } catch (error) {
      console.error('Erro ao carregar consentimentos:', error);
      toast.error('Erro ao carregar consentimentos');
    } finally {
      setLoading(false);
    }
  };

  const handleAnonymize = async () => {
    if (!anonymizePatientId) return;

    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error('Não autenticado');

      const { data: profile } = await supabase
        .from('profiles')
        .select('tenant_id')
        .eq('id', user.id)
        .single();

      if (!profile?.tenant_id) throw new Error('Tenant não encontrado');

      const { error } = await supabase.rpc('anonymize_patient_data', {
        p_tenant_id: profile.tenant_id,
        p_patient_id: anonymizePatientId
      });

      if (error) throw error;

      toast.success('Dados anonimizados com sucesso (LGPD)');
      setAnonymizePatientId(null);
      loadConsents();
    } catch (error) {
      console.error('Erro ao anonimizar:', error);
      toast.error('Erro ao anonimizar dados');
    }
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'opted_in':
        return <Badge className="bg-success"><CheckCircle className="w-3 h-3 mr-1" />Consentido</Badge>;
      case 'opted_out':
        return <Badge variant="destructive"><XCircle className="w-3 h-3 mr-1" />Revogado</Badge>;
      case 'pending':
        return <Badge variant="outline"><AlertTriangle className="w-3 h-3 mr-1" />Pendente</Badge>;
      default:
        return <Badge variant="secondary">{status}</Badge>;
    }
  };

  if (loading) {
    return <div>Carregando consentimentos...</div>;
  }

  return (
    <div className="space-y-6">
      <Card>
        <CardHeader>
          <div className="flex items-center gap-2">
            <Shield className="h-5 w-5 text-primary" />
            <CardTitle>Gestão de Consentimentos LGPD</CardTitle>
          </div>
          <CardDescription>
            Controle de opt-in/opt-out e trilhas de consentimento por contato
          </CardDescription>
        </CardHeader>
        <CardContent>
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Tipo</TableHead>
                <TableHead>Status</TableHead>
                <TableHead>Origem</TableHead>
                <TableHead>Versão Termo</TableHead>
                <TableHead>Data Consentimento</TableHead>
                <TableHead>Expira Em</TableHead>
                <TableHead>Ações</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {consents.map((consent) => (
                <TableRow key={consent.id}>
                  <TableCell className="font-medium">{consent.consent_type}</TableCell>
                  <TableCell>{getStatusBadge(consent.status)}</TableCell>
                  <TableCell>{consent.origin}</TableCell>
                  <TableCell>{consent.term_version}</TableCell>
                  <TableCell>{new Date(consent.given_at).toLocaleDateString()}</TableCell>
                  <TableCell>
                    {consent.expires_at 
                      ? new Date(consent.expires_at).toLocaleDateString()
                      : 'Sem expiração'}
                  </TableCell>
                  <TableCell>
                    <Button
                      variant="destructive"
                      size="sm"
                      onClick={() => setAnonymizePatientId(consent.contact_id)}
                    >
                      Anonimizar
                    </Button>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </CardContent>
      </Card>

      <AlertDialog open={!!anonymizePatientId} onOpenChange={() => setAnonymizePatientId(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Confirmar Anonimização (LGPD)</AlertDialogTitle>
            <AlertDialogDescription>
              Esta ação é irreversível. Todos os dados pessoais do paciente serão anonimizados
              e os consentimentos serão revogados. Deseja continuar?
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancelar</AlertDialogCancel>
            <AlertDialogAction onClick={handleAnonymize}>
              Confirmar Anonimização
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

import { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from "@/components/ui/table";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from "@/components/ui/dialog";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import { Plus, Trash2, Loader2, Tag } from "lucide-react";
import { toast } from "sonner";

interface Coupon {
    id: string;
    code: string;
    discount_type: 'percent' | 'fixed';
    value: number;
    start_date: string | null;
    end_date: string | null;
    active: boolean;
    usage_limit: number | null;
    times_redeemed: number;
}

export const CouponsManagement = () => {
    const [coupons, setCoupons] = useState<Coupon[]>([]);
    const [loading, setLoading] = useState(true);
    const [dialogOpen, setDialogOpen] = useState(false);
    const [creating, setCreating] = useState(false);

    const [formData, setFormData] = useState({
        code: "",
        discount_type: "percent",
        value: "",
        start_date: "",
        end_date: "",
        usage_limit: ""
    });

    useEffect(() => {
        loadCoupons();
    }, []);

    const loadCoupons = async () => {
        try {
            const { data, error } = await supabase
                .from("coupons")
                .select("*")
                .order("created_at", { ascending: false });

            if (error) throw error;
            setCoupons(data as any || []);
        } catch (error) {
            console.error("Error loading coupons:", error);
            toast.error("Erro ao carregar cupons");
        } finally {
            setLoading(false);
        }
    };

    const handleCreate = async (e: React.FormEvent) => {
        e.preventDefault();
        setCreating(true);

        try {
            const { data: { session } } = await supabase.auth.getSession();
            if (!session) {
                toast.error("Sessão inválida");
                return;
            }

            const response = await fetch(
                `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/manage-coupons`,
                {
                    method: "POST",
                    headers: {
                        "Content-Type": "application/json",
                        "Authorization": `Bearer ${session.access_token}`,
                    },
                    body: JSON.stringify({
                        action: "create",
                        couponData: {
                            code: formData.code.toUpperCase(),
                            discount_type: formData.discount_type,
                            value: parseFloat(formData.value),
                            start_date: formData.start_date || null,
                            end_date: formData.end_date || null,
                            usage_limit: formData.usage_limit ? parseInt(formData.usage_limit) : null
                        }
                    }),
                }
            );

            const result = await response.json();

            if (!response.ok) {
                throw new Error(result.error || "Erro ao criar cupom");
            }

            toast.success("Cupom criado com sucesso!");
            setDialogOpen(false);
            setFormData({
                code: "",
                discount_type: "percent",
                value: "",
                start_date: "",
                end_date: "",
                usage_limit: ""
            });
            loadCoupons();
        } catch (error: any) {
            console.error("Error creating coupon:", error);
            toast.error(error.message);
        } finally {
            setCreating(false);
        }
    };

    const handleDeactivate = async (id: string) => {
        if (!confirm("Tem certeza que deseja desativar este cupom?")) return;

        try {
            const { data: { session } } = await supabase.auth.getSession();
            if (!session) return;

            const response = await fetch(
                `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/manage-coupons`,
                {
                    method: "POST",
                    headers: {
                        "Content-Type": "application/json",
                        "Authorization": `Bearer ${session.access_token}`,
                    },
                    body: JSON.stringify({
                        action: "delete",
                        id
                    }),
                }
            );

            if (!response.ok) throw new Error("Erro ao desativar cupom");

            toast.success("Cupom desativado");
            loadCoupons();
        } catch (error) {
            console.error("Error deactivating coupon:", error);
            toast.error("Erro ao desativar cupom");
        }
    };

    return (
        <Card className="p-6">
            <div className="flex items-center justify-between mb-6">
                <div>
                    <h2 className="text-2xl font-bold">Cupons de Desconto</h2>
                    <p className="text-muted-foreground">Gerencie promoções e descontos de assinatura.</p>
                </div>

                <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
                    <DialogTrigger asChild>
                        <Button>
                            <Plus className="h-4 w-4 mr-2" />
                            Novo Cupom
                        </Button>
                    </DialogTrigger>
                    <DialogContent>
                        <DialogHeader>
                            <DialogTitle>Criar Novo Cupom</DialogTitle>
                        </DialogHeader>
                        <form onSubmit={handleCreate} className="space-y-4">
                            <div>
                                <Label htmlFor="code">Código do Cupom</Label>
                                <Input
                                    id="code"
                                    placeholder="EX: BLACKFRIDAY"
                                    value={formData.code}
                                    onChange={(e) => setFormData({ ...formData, code: e.target.value.toUpperCase() })}
                                    required
                                />
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <Label>Tipo de Desconto</Label>
                                    <Select
                                        value={formData.discount_type}
                                        onValueChange={(val) => setFormData({ ...formData, discount_type: val })}
                                    >
                                        <SelectTrigger>
                                            <SelectValue />
                                        </SelectTrigger>
                                        <SelectContent>
                                            <SelectItem value="percent">Porcentagem (%)</SelectItem>
                                            <SelectItem value="fixed">Valor Fixo (R$)</SelectItem>
                                        </SelectContent>
                                    </Select>
                                </div>
                                <div>
                                    <Label htmlFor="value">Valor</Label>
                                    <Input
                                        id="value"
                                        type="number"
                                        placeholder={formData.discount_type === 'percent' ? "10" : "50.00"}
                                        value={formData.value}
                                        onChange={(e) => setFormData({ ...formData, value: e.target.value })}
                                        required
                                    />
                                </div>
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <Label htmlFor="start_date">Início (Opcional)</Label>
                                    <Input
                                        id="start_date"
                                        type="datetime-local"
                                        value={formData.start_date}
                                        onChange={(e) => setFormData({ ...formData, start_date: e.target.value })}
                                    />
                                </div>
                                <div>
                                    <Label htmlFor="end_date">Fim (Opcional)</Label>
                                    <Input
                                        id="end_date"
                                        type="datetime-local"
                                        value={formData.end_date}
                                        onChange={(e) => setFormData({ ...formData, end_date: e.target.value })}
                                    />
                                </div>
                            </div>

                            <div>
                                <Label htmlFor="limit">Limite de Usos (Opcional)</Label>
                                <Input
                                    id="limit"
                                    type="number"
                                    placeholder="Ex: 100"
                                    value={formData.usage_limit}
                                    onChange={(e) => setFormData({ ...formData, usage_limit: e.target.value })}
                                />
                            </div>

                            <div className="flex justify-end pt-4">
                                <Button type="submit" disabled={creating}>
                                    {creating && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                                    Criar Cupom
                                </Button>
                            </div>
                        </form>
                    </DialogContent>
                </Dialog>
            </div>

            {loading ? (
                <div className="text-center py-8">Carregando...</div>
            ) : coupons.length === 0 ? (
                <div className="text-center py-8 text-muted-foreground">Nenhum cupom criado</div>
            ) : (
                <div className="rounded-md border">
                    <Table>
                        <TableHeader>
                            <TableRow>
                                <TableHead>Código</TableHead>
                                <TableHead>Desconto</TableHead>
                                <TableHead>Validade</TableHead>
                                <TableHead>Usos</TableHead>
                                <TableHead>Status</TableHead>
                                <TableHead className="text-right">Ações</TableHead>
                            </TableRow>
                        </TableHeader>
                        <TableBody>
                            {coupons.map((coupon) => (
                                <TableRow key={coupon.id}>
                                    <TableCell className="font-medium">
                                        <div className="flex items-center gap-2">
                                            <Tag className="h-4 w-4 text-primary" />
                                            {coupon.code}
                                        </div>
                                    </TableCell>
                                    <TableCell>
                                        {coupon.discount_type === 'percent'
                                            ? `${coupon.value}%`
                                            : `R$ ${coupon.value.toFixed(2)}`}
                                    </TableCell>
                                    <TableCell>
                                        <div className="text-xs">
                                            {coupon.start_date && <div>De: {new Date(coupon.start_date).toLocaleDateString()}</div>}
                                            {coupon.end_date && <div>Até: {new Date(coupon.end_date).toLocaleDateString()}</div>}
                                            {!coupon.start_date && !coupon.end_date && "Indeterminado"}
                                        </div>
                                    </TableCell>
                                    <TableCell>
                                        {coupon.times_redeemed}
                                        {coupon.usage_limit ? ` / ${coupon.usage_limit}` : ""}
                                    </TableCell>
                                    <TableCell>
                                        <Badge variant={coupon.active ? "default" : "secondary"}>
                                            {coupon.active ? "Ativo" : "Inativo"}
                                        </Badge>
                                    </TableCell>
                                    <TableCell className="text-right">
                                        {coupon.active && (
                                            <Button
                                                variant="ghost"
                                                size="icon"
                                                className="text-destructive hover:text-destructive"
                                                onClick={() => handleDeactivate(coupon.id)}
                                            >
                                                <Trash2 className="h-4 w-4" />
                                            </Button>
                                        )}
                                    </TableCell>
                                </TableRow>
                            ))}
                        </TableBody>
                    </Table>
                </div>
            )}
        </Card>
    );
};

import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Card } from "@/components/ui/card";
import { AlertTriangle, UserCheck, MessageSquare, AlertCircle } from "lucide-react";
import { Badge } from "@/components/ui/badge";

export const DashboardCards = () => {
  const [stats, setStats] = useState({
    pendingActions: 0,
    myTickets: 0,
    waitingChats: 0,
    recentAlerts: 0
  });

  useEffect(() => {
    loadStats();

    const channel = supabase
      .channel('dashboard_cards_changes')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'support_tickets' }, () => loadStats())
      .on('postgres_changes', { event: '*', schema: 'public', table: 'support_chat_sessions' }, () => loadStats())
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, []);

  const loadStats = async () => {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      // Ações pendentes: tickets novos + pendente_cliente + SLAs em risco
      const { count: newTickets } = await supabase
        .from('support_tickets')
        .select('id', { count: 'exact', head: true })
        .eq('status', 'open');

      // Tickets em risco de SLA
      const { data: ticketsAtRisk } = await supabase
        .from('support_tickets' as any)
        .select('id, sla')
        .in('status', ['open', 'in_progress']);

      const slaAtRisk = ticketsAtRisk?.filter((ticket: any) => {
        const sla = ticket.sla;
        if (!sla?.limite) return false;
        const limite = new Date(sla.limite);
        const now = new Date();
        const hoursUntilDeadline = (limite.getTime() - now.getTime()) / (1000 * 60 * 60);
        return hoursUntilDeadline <= 2 && hoursUntilDeadline > 0;
      }).length || 0;

      const pendingActions = (newTickets || 0) + slaAtRisk;

      // Meus tickets
      const { count: myTickets } = await supabase
        .from('support_tickets')
        .select('id', { count: 'exact', head: true })
        .eq('assigned_to', user.id)
        .in('status', ['open', 'in_progress']);

      // Chats aguardando
      const { count: waitingChats } = await supabase
        .from('support_chat_sessions' as any)
        .select('id', { count: 'exact', head: true })
        .eq('status', 'waiting');

      setStats({
        pendingActions,
        myTickets: myTickets || 0,
        waitingChats: waitingChats || 0,
        recentAlerts: 0 // Placeholder para alertas futuros
      });
    } catch (error) {
      console.error('Error loading stats:', error);
    }
  };

  const cards = [
    {
      title: "Ações Pendentes",
      value: stats.pendingActions,
      icon: AlertTriangle,
      description: "Tickets novos + SLAs em risco",
      color: "text-destructive"
    },
    {
      title: "Em Atendimento",
      value: stats.myTickets,
      icon: UserCheck,
      description: "Tickets atribuídos a mim",
      color: "text-primary"
    },
    {
      title: "Chats Aguardando",
      value: stats.waitingChats,
      icon: MessageSquare,
      description: "Fila atual de chats",
      color: "text-blue-500"
    },
    {
      title: "Alertas Recentes",
      value: stats.recentAlerts,
      icon: AlertCircle,
      description: "Falhas e erros recentes",
      color: "text-orange-500"
    }
  ];

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 mb-8">
      {cards.map((card) => (
        <Card key={card.title} className="p-6 hover:shadow-lg transition-shadow">
          <div className="flex items-center justify-between">
            <div className="flex-1">
              <p className="text-sm text-muted-foreground mb-1">{card.title}</p>
              <div className="flex items-baseline gap-2">
                <p className={`text-3xl font-bold ${card.color}`}>{card.value}</p>
                {card.value > 0 && card.title === "Ações Pendentes" && (
                  <Badge variant="destructive">Atenção</Badge>
                )}
              </div>
              <p className="text-xs text-muted-foreground mt-1">{card.description}</p>
            </div>
            <card.icon className={`h-8 w-8 ${card.color} opacity-50`} />
          </div>
        </Card>
      ))}
    </div>
  );
};

import React, { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { Loader2, AlertTriangle, Bell, Mail, MessageSquare, Shield } from "lucide-react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";

interface DunningConfig {
  id: string;
  dias_atraso: number;
  acao: string;
  canal_notificacao: string[];
  template_mensagem: string | null;
  ativo: boolean;
}

interface HistoricoDunning {
  id: string;
  tenant_id: string;
  dias_atraso: number;
  acao_tomada: string;
  canal: string;
  sucesso: boolean;
  created_at: string;
  tenants?: {
    nome: string;
  };
}

interface RestricaoTenant {
  id: string;
  tenant_id: string;
  tipo_restricao: string;
  motivo: string;
  iniciado_em: string;
  ativo: boolean;
  tenants?: {
    nome: string;
    email: string;
  };
}

export function DunningManagement() {
  const [configs, setConfigs] = useState<DunningConfig[]>([]);
  const [historico, setHistorico] = useState<HistoricoDunning[]>([]);
  const [restricoes, setRestricoes] = useState<RestricaoTenant[]>([]);
  const [loading, setLoading] = useState(true);
  const [editingConfig, setEditingConfig] = useState<DunningConfig | null>(null);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    try {
      setLoading(true);

      const [configsRes, historicoRes, restricoesRes] = await Promise.all([
        supabase.from("dunning_configs").select("*").order("dias_atraso"),
        supabase
          .from("historico_dunning")
          .select("*, tenants(nome)")
          .order("created_at", { ascending: false })
          .limit(20),
        supabase
          .from("restricoes_tenant")
          .select("*, tenants(nome, email)")
          .eq("ativo", true)
      ]);

      if (configsRes.error) throw configsRes.error;
      if (historicoRes.error) throw historicoRes.error;
      if (restricoesRes.error) throw restricoesRes.error;

      setConfigs(configsRes.data || []);
      setHistorico(historicoRes.data || []);
      setRestricoes(restricoesRes.data || []);
    } catch (error: any) {
      console.error("Erro ao carregar dados de dunning:", error);
      toast.error("Erro ao carregar dados de cobrança");
    } finally {
      setLoading(false);
    }
  };

  const handleToggleConfig = async (id: string, ativo: boolean) => {
    try {
      const { error } = await supabase
        .from("dunning_configs")
        .update({ ativo: !ativo })
        .eq("id", id);

      if (error) throw error;

      toast.success("Configuração atualizada!");
      loadData();
    } catch (error: any) {
      console.error("Erro ao atualizar configuração:", error);
      toast.error("Erro ao atualizar configuração");
    }
  };

  const handleRemoverRestricao = async (restricaoId: string, tenantId: string) => {
    try {
      const { error } = await supabase
        .from("restricoes_tenant")
        .update({
          ativo: false,
          removido_em: new Date().toISOString()
        })
        .eq("id", restricaoId);

      if (error) throw error;

      // Log na auditoria
      await supabase.from("support_actions_log").insert({
        support_user_id: (await supabase.auth.getUser()).data.user?.id,
        action_type: "restricao_removida",
        target_type: "restricao_tenant",
        target_id: restricaoId,
        description: `Restrição removida para tenant ${tenantId}`
      });

      toast.success("Restrição removida!");
      loadData();
    } catch (error: any) {
      console.error("Erro ao remover restrição:", error);
      toast.error("Erro ao remover restrição");
    }
  };

  const getAcaoIcon = (acao: string) => {
    const icons: Record<string, any> = {
      lembrete: Bell,
      restricao_marketing: AlertTriangle,
      restricao_outbound: Shield,
      suspensao_total: AlertTriangle
    };
    return icons[acao] || Bell;
  };

  const getRestricaoBadge = (tipo: string) => {
    const variants: Record<string, any> = {
      nenhuma: { variant: "default", label: "Sem Restrições" },
      soft_marketing: { variant: "outline", label: "Marketing Restrito" },
      soft_outbound: { variant: "destructive", label: "Outbound Restrito" },
      suspensao_total: { variant: "destructive", label: "Suspenso" }
    };

    const config = variants[tipo] || variants.nenhuma;

    return <Badge variant={config.variant}>{config.label}</Badge>;
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="h-8 w-8 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Configurações de Dunning */}
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div>
              <CardTitle className="flex items-center gap-2">
                <Bell className="h-5 w-5" />
                Regras de Cobrança (Dunning)
              </CardTitle>
              <CardDescription>Configure as ações automáticas para inadimplência</CardDescription>
            </div>
            <DunningConfigDialog onSave={loadData} />
          </div>
        </CardHeader>
        <CardContent>
          <div className="space-y-3">
            {configs.map((config) => {
              const Icon = getAcaoIcon(config.acao);
              return (
                <div
                  key={config.id}
                  className="flex items-center justify-between p-4 border rounded-lg"
                >
                  <div className="flex-1">
                    <div className="flex items-center gap-3 mb-2">
                      <Icon className="h-5 w-5 text-primary" />
                      <span className="font-semibold">
                        D+{config.dias_atraso}: {config.acao.replace(/_/g, " ").toUpperCase()}
                      </span>
                      <Badge variant={config.ativo ? "default" : "secondary"}>
                        {config.ativo ? "Ativo" : "Inativo"}
                      </Badge>
                    </div>
                    <div className="text-sm text-muted-foreground">
                      Canais: {config.canal_notificacao.join(", ")}
                    </div>
                    {config.template_mensagem && (
                      <div className="text-xs text-muted-foreground mt-1">
                        {config.template_mensagem}
                      </div>
                    )}
                  </div>
                  <div className="flex gap-2">
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => setEditingConfig(config)}
                    >
                      Editar
                    </Button>
                    <Button
                      variant={config.ativo ? "destructive" : "default"}
                      size="sm"
                      onClick={() => handleToggleConfig(config.id, config.ativo)}
                    >
                      {config.ativo ? "Desativar" : "Ativar"}
                    </Button>
                  </div>
                </div>
              );
            })}
          </div>
        </CardContent>
      </Card>

      {/* Restrições Ativas */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Shield className="h-5 w-5" />
            Restrições Ativas
          </CardTitle>
          <CardDescription>Clientes com restrições por inadimplência</CardDescription>
        </CardHeader>
        <CardContent>
          {restricoes.length === 0 ? (
            <div className="text-center py-8 text-muted-foreground">
              Nenhuma restrição ativa
            </div>
          ) : (
            <div className="space-y-3">
              {restricoes.map((restricao) => (
                <Card key={restricao.id} className="border-l-4 border-l-destructive">
                  <CardContent className="p-4">
                    <div className="flex items-center justify-between">
                      <div className="flex-1">
                        <div className="flex items-center gap-3 mb-2">
                          <span className="font-semibold">{restricao.tenants?.nome}</span>
                          {getRestricaoBadge(restricao.tipo_restricao)}
                        </div>
                        <div className="text-sm text-muted-foreground space-y-1">
                          <div>Motivo: {restricao.motivo}</div>
                          <div>
                            Desde: {new Date(restricao.iniciado_em).toLocaleDateString()}
                          </div>
                        </div>
                      </div>
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => handleRemoverRestricao(restricao.id, restricao.tenant_id)}
                      >
                        Remover Restrição
                      </Button>
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Histórico de Cobranças */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <MessageSquare className="h-5 w-5" />
            Histórico de Cobranças
          </CardTitle>
          <CardDescription>Últimas ações de cobrança realizadas</CardDescription>
        </CardHeader>
        <CardContent>
          <div className="space-y-2">
            {historico.map((item) => (
              <div
                key={item.id}
                className="flex items-center justify-between p-3 border rounded-lg text-sm"
              >
                <div className="flex-1">
                  <div className="font-medium">{item.tenants?.nome}</div>
                  <div className="text-muted-foreground">
                    D+{item.dias_atraso} - {item.acao_tomada} via {item.canal}
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  <Badge variant={item.sucesso ? "default" : "destructive"}>
                    {item.sucesso ? "Enviado" : "Falhou"}
                  </Badge>
                  <span className="text-xs text-muted-foreground">
                    {new Date(item.created_at).toLocaleDateString()}
                  </span>
                </div>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Dialog de edição */}
      {editingConfig && (
        <DunningConfigDialog
          config={editingConfig}
          onSave={loadData}
          onClose={() => setEditingConfig(null)}
        />
      )}
    </div>
  );
}

// Componente de diálogo para configuração de dunning
function DunningConfigDialog({ config, onSave, onClose }: any) {
  const [formData, setFormData] = useState(
    config || {
      dias_atraso: 1,
      acao: "lembrete",
      canal_notificacao: ["email"],
      template_mensagem: "",
      ativo: true
    }
  );
  const [open, setOpen] = useState(!!config);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const { error } = config
        ? await supabase.from("dunning_configs").update(formData).eq("id", config.id)
        : await supabase.from("dunning_configs").insert([formData]);

      if (error) throw error;

      toast.success("Configuração salva com sucesso!");
      if (onClose) onClose();
      setOpen(false);
      onSave();
    } catch (error: any) {
      console.error("Erro ao salvar configuração:", error);
      toast.error("Erro ao salvar configuração");
    }
  };

  return (
    <Dialog open={open} onOpenChange={(o) => { setOpen(o); if (!o && onClose) onClose(); }}>
      <DialogTrigger asChild>
        <Button>Nova Regra</Button>
      </DialogTrigger>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>{config ? "Editar" : "Nova"} Regra de Cobrança</DialogTitle>
        </DialogHeader>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <Label>Dias de Atraso</Label>
            <Input
              type="number"
              min="1"
              value={formData.dias_atraso}
              onChange={(e) => setFormData({ ...formData, dias_atraso: parseInt(e.target.value) })}
            />
          </div>
          <div>
            <Label>Ação</Label>
            <Select
              value={formData.acao}
              onValueChange={(v) => setFormData({ ...formData, acao: v })}
            >
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="lembrete">Lembrete</SelectItem>
                <SelectItem value="restricao_marketing">Restringir Marketing</SelectItem>
                <SelectItem value="restricao_outbound">Restringir Outbound</SelectItem>
                <SelectItem value="suspensao_total">Suspensão Total</SelectItem>
              </SelectContent>
            </Select>
          </div>
          <div>
            <Label>Template da Mensagem</Label>
            <Textarea
              value={formData.template_mensagem || ""}
              onChange={(e) => setFormData({ ...formData, template_mensagem: e.target.value })}
              rows={3}
            />
          </div>
          <Button type="submit" className="w-full">Salvar</Button>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Checkbox } from "@/components/ui/checkbox";
import { Switch } from "@/components/ui/switch";
import { Avatar, AvatarImage, AvatarFallback } from "@/components/ui/avatar";
import { toast } from "sonner";
import { Loader2, Upload, X } from "lucide-react";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";

interface EditSupportUserDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  userId: string;
  onSuccess: () => void;
}

interface SupportUser {
  id: string;
  nome: string;
  email: string;
  telefone?: string;
  status: string;
  funcoes: string[];
  foto_url?: string;
}

interface TenantBinding {
  id: string;
  tenant_id: string;
  papeis_no_tenant: string[];
  tenant?: {
    nome: string;
  };
}

const roleOptions = [
  { value: "leitura", label: "Leitura" },
  { value: "agente", label: "Agente" },
  { value: "financeiro", label: "Financeiro" },
  { value: "admin", label: "Admin" },
  { value: "master", label: "Master" }
];

export function EditSupportUserDialog({ open, onOpenChange, userId, onSuccess }: EditSupportUserDialogProps) {
  const [loading, setLoading] = useState(false);
  const [uploadingPhoto, setUploadingPhoto] = useState(false);
  const [user, setUser] = useState<SupportUser | null>(null);
  const [photoFile, setPhotoFile] = useState<File | null>(null);
  const [photoPreview, setPhotoPreview] = useState<string | null>(null);
  const [tenantBindings, setTenantBindings] = useState<TenantBinding[]>([]);
  const [availableTenants, setAvailableTenants] = useState<any[]>([]);

  useEffect(() => {
    if (open && userId) {
      loadUser();
      loadTenantBindings();
      loadAvailableTenants();
    }
  }, [open, userId]);

  const loadUser = async () => {
    try {
      const { data, error } = await supabase
        .from("usuarios_suporte")
        .select("*")
        .eq("id", userId)
        .single();

      if (error) throw error;
      setUser(data);
      if (data.foto_url) {
        setPhotoPreview(data.foto_url);
      }
    } catch (error) {
      console.error("Error loading user:", error);
      toast.error("Erro ao carregar usuário");
    }
  };

  const loadTenantBindings = async () => {
    try {
      const { data, error } = await supabase
        .from("vinculo_usuario_tenant")
        .select(`
          *,
          tenant:tenants(nome)
        `)
        .eq("usuario_id", userId);

      if (error) throw error;
      setTenantBindings(data || []);
    } catch (error) {
      console.error("Error loading tenant bindings:", error);
    }
  };

  const loadAvailableTenants = async () => {
    try {
      const { data, error } = await supabase
        .from("tenants")
        .select("id, nome, status")
        .eq("status", "ativo")
        .order("nome");

      if (error) throw error;
      setAvailableTenants(data || []);
    } catch (error) {
      console.error("Error loading tenants:", error);
    }
  };

  const handlePhotoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 2 * 1024 * 1024) {
        toast.error("Arquivo muito grande. Máximo 2MB");
        return;
      }
      setPhotoFile(file);
      const reader = new FileReader();
      reader.onloadend = () => {
        setPhotoPreview(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleUploadPhoto = async () => {
    if (!photoFile || !user) return;

    setUploadingPhoto(true);
    try {
      const fileExt = photoFile.name.split('.').pop();
      const fileName = `${userId}-${Date.now()}.${fileExt}`;
      const filePath = `${fileName}`;

      const { error: uploadError } = await supabase.storage
        .from('avatars')
        .upload(filePath, photoFile, { upsert: true });

      if (uploadError) throw uploadError;

      const { data: { publicUrl } } = supabase.storage
        .from('avatars')
        .getPublicUrl(filePath);

      const { error: updateError } = await supabase
        .from("usuarios_suporte")
        .update({ foto_url: publicUrl })
        .eq("id", userId);

      if (updateError) throw updateError;

      setUser({ ...user, foto_url: publicUrl });
      toast.success("Foto atualizada com sucesso");
    } catch (error: any) {
      console.error("Error uploading photo:", error);
      toast.error("Erro ao fazer upload da foto");
    } finally {
      setUploadingPhoto(false);
    }
  };

  const handleRemovePhoto = () => {
    setPhotoFile(null);
    setPhotoPreview(user?.foto_url || null);
  };

  const handleRoleToggle = (role: string) => {
    if (!user) return;
    setUser({
      ...user,
      funcoes: user.funcoes.includes(role)
        ? user.funcoes.filter(r => r !== role)
        : [...user.funcoes, role]
    });
  };

  const handleAddTenantBinding = async (tenantId: string) => {
    try {
      const { error } = await supabase
        .from("vinculo_usuario_tenant")
        .insert({
          usuario_id: userId,
          tenant_id: tenantId,
          papeis_no_tenant: ['leitura']
        });

      if (error) throw error;
      toast.success("Tenant vinculado com sucesso");
      loadTenantBindings();
    } catch (error) {
      console.error("Error adding tenant binding:", error);
      toast.error("Erro ao vincular tenant");
    }
  };

  const handleRemoveTenantBinding = async (bindingId: string) => {
    try {
      const { error } = await supabase
        .from("vinculo_usuario_tenant")
        .delete()
        .eq("id", bindingId);

      if (error) throw error;
      toast.success("Vínculo removido com sucesso");
      loadTenantBindings();
    } catch (error) {
      console.error("Error removing tenant binding:", error);
      toast.error("Erro ao remover vínculo");
    }
  };

  const handleUpdateTenantRoles = async (bindingId: string, roles: string[]) => {
    try {
      const { error } = await supabase
        .from("vinculo_usuario_tenant")
        .update({ papeis_no_tenant: roles as any })
        .eq("id", bindingId);

      if (error) throw error;
      toast.success("Papéis atualizados com sucesso");
      loadTenantBindings();
    } catch (error) {
      console.error("Error updating roles:", error);
      toast.error("Erro ao atualizar papéis");
    }
  };

  const handleSubmit = async () => {
    if (!user) return;

    if (user.funcoes.length === 0) {
      toast.error("Selecione pelo menos uma função");
      return;
    }

    setLoading(true);
    try {
      const { error } = await supabase
        .from("usuarios_suporte")
        .update({
          nome: user.nome,
          telefone: user.telefone,
          status: user.status as any,
          funcoes: user.funcoes as any
        })
        .eq("id", userId);

      if (error) throw error;

      const { data: { user: currentUser } } = await supabase.auth.getUser();
      if (currentUser) {
        await supabase.from("support_actions_log").insert({
          support_user_id: currentUser.id,
          action_type: "usuario_editado",
          target_type: "usuarios_suporte",
          target_id: userId,
          description: `Usuário de suporte atualizado: ${user.nome}`,
        });
      }

      toast.success("Usuário atualizado com sucesso");
      onSuccess();
      onOpenChange(false);
    } catch (error: any) {
      console.error("Error updating user:", error);
      toast.error("Erro ao atualizar usuário");
    } finally {
      setLoading(false);
    }
  };

  if (!user) {
    return null;
  }

  const unboundTenants = availableTenants.filter(
    t => !tenantBindings.some(b => b.tenant_id === t.id)
  );

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>Editar Usuário de Suporte</DialogTitle>
        </DialogHeader>

        <Tabs defaultValue="info" className="w-full">
          <TabsList className="grid w-full grid-cols-3">
            <TabsTrigger value="info">Informações</TabsTrigger>
            <TabsTrigger value="photo">Foto de Perfil</TabsTrigger>
            <TabsTrigger value="tenants">Tenants</TabsTrigger>
          </TabsList>

          <TabsContent value="info" className="space-y-4">
            <div>
              <Label htmlFor="nome">Nome *</Label>
              <Input
                id="nome"
                value={user.nome}
                onChange={(e) => setUser({ ...user, nome: e.target.value })}
              />
            </div>

            <div>
              <Label htmlFor="email">Email</Label>
              <Input
                id="email"
                type="email"
                value={user.email}
                disabled
              />
            </div>

            <div>
              <Label htmlFor="telefone">Telefone</Label>
              <Input
                id="telefone"
                value={user.telefone || ""}
                onChange={(e) => setUser({ ...user, telefone: e.target.value })}
              />
            </div>

            <div className="space-y-2">
              <Label>Funções *</Label>
              <div className="grid grid-cols-2 gap-3">
                {roleOptions.map((role) => (
                  <div key={role.value} className="flex items-center space-x-2">
                    <Checkbox
                      id={`role-${role.value}`}
                      checked={user.funcoes.includes(role.value)}
                      onCheckedChange={() => handleRoleToggle(role.value)}
                    />
                    <label
                      htmlFor={`role-${role.value}`}
