                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="meta_access_token">Access Token (Permanente)</Label>
                <SecretInput
                  id="meta_access_token"
                  value={metaConfig.access_token}
                  onChange={(v) => setMetaConfig({ ...metaConfig, access_token: v })}
                  placeholder="EAAxxxxxxxxxxxxxxx"
                />
                <p className="text-xs text-muted-foreground">
                  Use um token de acesso permanente do Sistema do Usuário com permissões whatsapp_business_messaging
                </p>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label htmlFor="meta_phone_number_id">Phone Number ID</Label>
                  <Input
                    id="meta_phone_number_id"
                    value={metaConfig.phone_number_id}
                    onChange={(e) => setMetaConfig({ ...metaConfig, phone_number_id: e.target.value })}
                    placeholder="123456789012345"
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="meta_business_account_id">Business Account ID</Label>
                  <Input
                    id="meta_business_account_id"
                    value={metaConfig.business_account_id}
                    onChange={(e) => setMetaConfig({ ...metaConfig, business_account_id: e.target.value })}
                    placeholder="123456789012345"
                  />
                </div>
              </div>

              <div className="space-y-2">
                <Label htmlFor="meta_webhook_verify_token">Webhook Verify Token</Label>
                <SecretInput
                  id="meta_webhook_verify_token"
                  value={metaConfig.webhook_verify_token}
                  onChange={(v) => setMetaConfig({ ...metaConfig, webhook_verify_token: v })}
                  placeholder="seu_token_secreto"
                />
                <p className="text-xs text-muted-foreground">
                  Token usado para verificar o webhook. Use algo único e seguro.
                </p>
              </div>

              <div className="bg-muted/50 p-4 rounded-lg">
                <h4 className="font-medium mb-2 flex items-center gap-2">
                  <Shield className="h-4 w-4" />
                  Webhook URL
                </h4>
                <code className="text-sm bg-background px-2 py-1 rounded block overflow-x-auto">
                  {`${import.meta.env.VITE_SUPABASE_URL}/functions/v1/whatsapp-webhook`}
                </code>
                <p className="text-xs text-muted-foreground mt-2">
                  Configure esta URL no Console Meta → WhatsApp → Configuração → Webhook
                </p>
              </div>

              <div className="flex gap-2">
                <Button onClick={handleSaveMeta} disabled={saving}>
                  {saving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
                  Salvar Configurações
                </Button>
                {status.meta_whatsapp && !status.meta_verified && (
                  <Button variant="outline" onClick={handleVerifyMeta} disabled={saving}>
                    <RefreshCw className="h-4 w-4 mr-2" />
                    Verificar Credenciais
                  </Button>
                )}
