            </div>
          </DialogContent>
        </Dialog>
      )}
    </div>
  );
}

import { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { toast } from "sonner";
import { Plus, TrendingUp, TrendingDown, Pause, Play, Edit, Trash2 } from "lucide-react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";

interface Template {
  id: string;
  titulo: string;
  corpo_mensagem: string;
  janela_horas: number;
  tipo_servico: string;
  variante: string;
  ativo: boolean;
  score: number;
  taxa_confirmacao: number;
  total_envios: number;
  total_confirmacoes: number;
  recomendacao: string;
}

export function LembreteTemplateManager() {
  const [templates, setTemplates] = useState<Template[]>([]);
  const [loading, setLoading] = useState(true);
  const [editingTemplate, setEditingTemplate] = useState<Template | null>(null);
  const [isDialogOpen, setIsDialogOpen] = useState(false);

  const loadTemplates = async () => {
    try {
      const { data: profile } = await supabase
        .from("profiles")
        .select("tenant_id")
        .single();

      if (!profile?.tenant_id) return;

      const { data, error } = await supabase
        .from("lembrete_templates" as any)
        .select("*")
        .eq("tenant_id", profile.tenant_id)
        .order("score", { ascending: false });

      if (error) throw error;
      setTemplates((data as any) || []);
    } catch (error) {
      console.error("Erro ao carregar templates:", error);
      toast.error("Erro ao carregar templates");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadTemplates();
  }, []);

  const handleSaveTemplate = async (template: Partial<Template>) => {
    try {
      const { data: profile } = await supabase
        .from("profiles")
        .select("tenant_id")
        .single();

      if (!profile?.tenant_id) return;

      if (template.id) {
        const { error } = await supabase
          .from("lembrete_templates" as any)
          .update(template)
          .eq("id", template.id);
        if (error) throw error;
        toast.success("Template atualizado!");
      } else {
        const { error } = await supabase
          .from("lembrete_templates" as any)
          .insert({ ...template, tenant_id: profile.tenant_id });
        if (error) throw error;
        toast.success("Template criado!");
      }

      loadTemplates();
      setIsDialogOpen(false);
      setEditingTemplate(null);
    } catch (error) {
      console.error("Erro ao salvar template:", error);
      toast.error("Erro ao salvar template");
    }
  };

  const toggleTemplateStatus = async (template: Template) => {
    try {
      const { error } = await supabase
        .from("lembrete_templates" as any)
        .update({ ativo: !template.ativo })
        .eq("id", template.id);

      if (error) throw error;
      toast.success(template.ativo ? "Template pausado" : "Template ativado");
      loadTemplates();
    } catch (error) {
      console.error("Erro ao alterar status:", error);
      toast.error("Erro ao alterar status");
    }
  };

  const getRecommendationBadge = (recomendacao: string) => {
    const config = {
      promover: { label: "Promover", variant: "default" as const, icon: TrendingUp },
      pausar: { label: "Pausar", variant: "destructive" as const, icon: TrendingDown },
      manter: { label: "Manter", variant: "secondary" as const, icon: Play },
      testar: { label: "Em Teste", variant: "outline" as const, icon: Play },
    };

    const rec = config[recomendacao as keyof typeof config] || config.testar;
    const Icon = rec.icon;

    return (
      <Badge variant={rec.variant} className="gap-1">
        <Icon className="h-3 w-3" />
        {rec.label}
      </Badge>
    );
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold">Templates de Lembretes</h2>
          <p className="text-muted-foreground">
            Gerencie templates com A/B testing e visualize performance
          </p>
        </div>
        <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
          <DialogTrigger asChild>
            <Button onClick={() => setEditingTemplate(null)}>
              <Plus className="h-4 w-4 mr-2" />
              Novo Template
            </Button>
          </DialogTrigger>
          <DialogContent className="max-w-2xl">
            <DialogHeader>
              <DialogTitle>
                {editingTemplate ? "Editar Template" : "Novo Template"}
              </DialogTitle>
            </DialogHeader>
            <TemplateForm
              template={editingTemplate}
              onSave={handleSaveTemplate}
              onCancel={() => {
                setIsDialogOpen(false);
                setEditingTemplate(null);
              }}
            />
          </DialogContent>
        </Dialog>
      </div>

      {loading ? (
        <Card>
          <CardContent className="py-8 text-center text-muted-foreground">
            Carregando templates...
          </CardContent>
        </Card>
      ) : templates.length === 0 ? (
        <Card>
          <CardContent className="py-8 text-center text-muted-foreground">
            Nenhum template cadastrado. Crie seu primeiro template!
          </CardContent>
        </Card>
      ) : (
        <div className="grid gap-4">
          {templates.map((template) => (
            <Card key={template.id}>
              <CardHeader>
                <div className="flex items-start justify-between">
                  <div className="space-y-1 flex-1">
                    <div className="flex items-center gap-2">
                      <CardTitle>{template.titulo}</CardTitle>
                      {getRecommendationBadge(template.recomendacao)}
                      <Badge variant={template.ativo ? "default" : "secondary"}>
                        {template.ativo ? "Ativo" : "Pausado"}
                      </Badge>
                    </div>
                    <CardDescription>
                      Janela: {template.janela_horas}h | Tipo: {template.tipo_servico} | 
                      Variante: {template.variante}
                    </CardDescription>
                  </div>
                  <div className="flex gap-2">
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => {
                        setEditingTemplate(template);
                        setIsDialogOpen(true);
                      }}
                    >
                      <Edit className="h-4 w-4" />
                    </Button>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => toggleTemplateStatus(template)}
                    >
                      {template.ativo ? <Pause className="h-4 w-4" /> : <Play className="h-4 w-4" />}
                    </Button>
                  </div>
                </div>
              </CardHeader>
              <CardContent>
                <div className="space-y-4">
                  <div className="p-3 bg-muted rounded-lg text-sm">
                    {template.corpo_mensagem}
                  </div>

                  {template.total_envios >= 30 && (
                    <div className="grid grid-cols-4 gap-4 text-sm">
                      <div>
                        <div className="text-muted-foreground">Score</div>
                        <div className="text-2xl font-bold">{template.score.toFixed(1)}</div>
                      </div>
                      <div>
                        <div className="text-muted-foreground">Taxa Confirmação</div>
                        <div className="text-2xl font-bold">{template.taxa_confirmacao.toFixed(1)}%</div>
                      </div>
                      <div>
                        <div className="text-muted-foreground">Total Envios</div>
                        <div className="text-2xl font-bold">{template.total_envios}</div>
                      </div>
                      <div>
                        <div className="text-muted-foreground">Confirmações</div>
                        <div className="text-2xl font-bold">{template.total_confirmacoes}</div>
                      </div>
                    </div>
                  )}

                  {template.total_envios < 30 && (
                    <div className="text-sm text-muted-foreground">
                      📊 Amostra em coleta: {template.total_envios}/30 envios necessários para análise completa
                    </div>
                  )}
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}
    </div>
  );
}

function TemplateForm({ 
  template, 
  onSave, 
  onCancel 
}: { 
  template: Template | null; 
  onSave: (t: Partial<Template>) => void;
  onCancel: () => void;
}) {
  const [formData, setFormData] = useState({
    titulo: template?.titulo || "",
    corpo_mensagem: template?.corpo_mensagem || "",
    janela_horas: template?.janela_horas || 24,
    tipo_servico: template?.tipo_servico || "geral",
    variante: template?.variante || "A",
    ativo: template?.ativo ?? true,
  });

  return (
    <div className="space-y-4">
      <div>
        <Label>Título</Label>
        <Input
          value={formData.titulo}
          onChange={(e) => setFormData({ ...formData, titulo: e.target.value })}
          placeholder="Ex: Lembrete Padrão 24h"
        />
      </div>

      <div>
        <Label>Corpo da Mensagem</Label>
        <Textarea
          value={formData.corpo_mensagem}
          onChange={(e) => setFormData({ ...formData, corpo_mensagem: e.target.value })}
          placeholder="Use: {{nome_paciente}}, {{data}}, {{hora}}, {{servico}}"
          rows={4}
        />
        <p className="text-xs text-muted-foreground mt-1">
          Variáveis disponíveis: nome_paciente, data, hora, servico
        </p>
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div>
          <Label>Janela (horas)</Label>
          <Select
            value={formData.janela_horas.toString()}
            onValueChange={(v) => setFormData({ ...formData, janela_horas: parseInt(v) })}
          >
            <SelectTrigger>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="1">1 hora</SelectItem>
              <SelectItem value="24">24 horas</SelectItem>
              <SelectItem value="72">72 horas</SelectItem>
            </SelectContent>
          </Select>
        </div>

        <div>
          <Label>Tipo de Serviço</Label>
          <Input
            value={formData.tipo_servico}
            onChange={(e) => setFormData({ ...formData, tipo_servico: e.target.value })}
            placeholder="geral, consulta, exame..."
          />
        </div>
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div>
          <Label>Variante (A/B)</Label>
          <Input
            value={formData.variante}
            onChange={(e) => setFormData({ ...formData, variante: e.target.value })}
            placeholder="A, B, C..."
            maxLength={1}
          />
        </div>

        <div className="flex items-center gap-2">
          <Switch
            checked={formData.ativo}
            onCheckedChange={(checked) => setFormData({ ...formData, ativo: checked })}
          />
          <Label>Template Ativo</Label>
        </div>
      </div>

      <div className="flex gap-2 justify-end">
        <Button variant="outline" onClick={onCancel}>
          Cancelar
        </Button>
        <Button onClick={() => onSave({ ...template, ...formData })}>
          Salvar
        </Button>
      </div>
    </div>
  );
}

import { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { useToast } from "@/hooks/use-toast";
import { Users, Plus, Trash2, Clock, TrendingUp } from "lucide-react";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { Switch } from "@/components/ui/switch";

export function ListaEsperaPanel() {
  const [listaEspera, setListaEspera] = useState<any[]>([]);
  const [pacientes, setPacientes] = useState<any[]>([]);
  const [servicos, setServicos] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const { toast } = useToast();

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    try {
      const { data: profile } = await supabase
        .from("profiles")
        .select("tenant_id")
        .eq("id", (await supabase.auth.getUser()).data.user?.id)
        .single();

      if (!profile?.tenant_id) return;

      const [listaRes, pacientesRes, servicosRes] = await Promise.all([
        supabase
          .from("lista_espera" as any)
          .select("*, pacientes(nome, telefone), procedimentos:servico_id(nome)")
          .eq("tenant_id", profile.tenant_id)
          .eq("status", "ativo")
          .order("score_total", { ascending: false }),
        supabase
          .from("pacientes")
          .select("id, nome, telefone")
          .eq("tenant_id", profile.tenant_id),
        supabase
          .from("procedimentos")
          .select("id, nome")
          .eq("tenant_id", profile.tenant_id)
          .order("nome"),
      ]);

      if (listaRes.data) setListaEspera(listaRes.data);
      if (pacientesRes.data) setPacientes(pacientesRes.data);
      if (servicosRes.data) setServicos(servicosRes.data);
    } catch (error: any) {
      toast({
        title: "Erro",
        description: error.message,
        variant: "destructive",
      });
    } finally {
      setIsLoading(false);
    }
  };

  const handleAdd = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);

    try {
      const { data: profile } = await supabase
        .from("profiles")
        .select("tenant_id")
        .eq("id", (await supabase.auth.getUser()).data.user?.id)
        .single();

      const { error } = await supabase.from("lista_espera" as any).insert({
        tenant_id: profile?.tenant_id,
        paciente_id: formData.get("paciente_id"),
        servico_id: formData.get("servico_id") || null,
        prioridade_clinica: formData.get("prioridade_clinica"),
        proximidade_score: parseInt(formData.get("proximidade_score") as string),
        probabilidade_comparecimento: parseInt(formData.get("probabilidade_comparecimento") as string),
        notas: formData.get("notas"),
        consentimento_ofertas: formData.get("consentimento_ofertas") === "on",
        data_consentimento: formData.get("consentimento_ofertas") === "on" ? new Date().toISOString() : null,
      });

      if (error) throw error;

      toast({
        title: "Sucesso",
        description: "Paciente adicionado à lista de espera",
      });

      setIsDialogOpen(false);
      loadData();
    } catch (error: any) {
      toast({
        title: "Erro",
        description: error.message,
        variant: "destructive",
      });
    }
  };

  const handleRemove = async (id: string) => {
    try {
      const { error } = await supabase
        .from("lista_espera" as any)
        .update({ status: "removido" })
        .eq("id", id);

      if (error) throw error;

      toast({
        title: "Sucesso",
        description: "Paciente removido da lista",
      });

      loadData();
    } catch (error: any) {
      toast({
        title: "Erro",
        description: error.message,
        variant: "destructive",
      });
    }
  };

  const getPrioridadeBadge = (prioridade: string) => {
    const colors: Record<string, string> = {
      urgente: "destructive",
      alta: "default",
      media: "secondary",
      baixa: "outline",
    };
    return <Badge variant={colors[prioridade] as any}>{prioridade.toUpperCase()}</Badge>;
  };

  if (isLoading) {
    return <div>Carregando...</div>;
  }

  return (
    <Card>
      <CardHeader>
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Users className="h-5 w-5" />
            <CardTitle>Lista de Espera Inteligente</CardTitle>
          </div>
          <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
            <DialogTrigger asChild>
              <Button>
                <Plus className="h-4 w-4 mr-2" />
                Adicionar Paciente
              </Button>
            </DialogTrigger>
            <DialogContent className="max-w-2xl">
              <DialogHeader>
                <DialogTitle>Adicionar à Lista de Espera</DialogTitle>
              </DialogHeader>
              <form onSubmit={handleAdd} className="space-y-4">
                <div>
                  <Label>Paciente *</Label>
                  <Select name="paciente_id" required>
                    <SelectTrigger>
                      <SelectValue placeholder="Selecione..." />
                    </SelectTrigger>
                    <SelectContent>
                      {pacientes.map((p) => (
                        <SelectItem key={p.id} value={p.id}>
                          {p.nome}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>

                <div>
                  <Label>Serviço</Label>
                  <Select name="servico_id">
                    <SelectTrigger>
                      <SelectValue placeholder="Qualquer serviço" />
                    </SelectTrigger>
                    <SelectContent>
                      {servicos.map((s) => (
                        <SelectItem key={s.id} value={s.id}>
                          {s.nome}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>

                <div>
                  <Label>Prioridade Clínica *</Label>
                  <Select name="prioridade_clinica" required>
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="baixa">Baixa</SelectItem>
                      <SelectItem value="media">Média</SelectItem>
                      <SelectItem value="alta">Alta</SelectItem>
                      <SelectItem value="urgente">Urgente</SelectItem>
                    </SelectContent>
                  </Select>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <Label>Score Proximidade (0-100)</Label>
                    <Input type="number" name="proximidade_score" defaultValue="50" min="0" max="100" />
                  </div>
                  <div>
                    <Label>Probabilidade Comparecimento (0-100)</Label>
                    <Input type="number" name="probabilidade_comparecimento" defaultValue="70" min="0" max="100" />
                  </div>
                </div>

                <div>
                  <Label>Notas</Label>
                  <Textarea name="notas" placeholder="Observações clínicas..." />
                </div>

                <div className="flex items-center space-x-2">
                  <Switch name="consentimento_ofertas" id="consentimento" />
                  <Label htmlFor="consentimento">
                    Paciente consentiu receber ofertas de vagas via WhatsApp (LGPD)
                  </Label>
                </div>

                <div className="flex gap-2 justify-end">
                  <Button type="button" variant="outline" onClick={() => setIsDialogOpen(false)}>
                    Cancelar
                  </Button>
                  <Button type="submit">Adicionar</Button>
                </div>
              </form>
            </DialogContent>
          </Dialog>
        </div>
      </CardHeader>
      <CardContent>
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Paciente</TableHead>
              <TableHead>Telefone</TableHead>
              <TableHead>Serviço</TableHead>
              <TableHead>Prioridade</TableHead>
              <TableHead>Score Total</TableHead>
              <TableHead>Consentimento</TableHead>
              <TableHead>Ações</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {listaEspera.map((item) => (
              <TableRow key={item.id}>
                <TableCell className="font-medium">{item.pacientes?.nome}</TableCell>
                <TableCell>{item.pacientes?.telefone}</TableCell>
                <TableCell>{item.servicos?.nome || "Qualquer"}</TableCell>
                <TableCell>{getPrioridadeBadge(item.prioridade_clinica)}</TableCell>
                <TableCell>
                  <div className="flex items-center gap-1">
                    <TrendingUp className="h-4 w-4 text-primary" />
                    <span className="font-semibold">{item.score_total}</span>
                  </div>
                </TableCell>
                <TableCell>
                  {item.consentimento_ofertas ? (
                    <Badge variant="outline" className="bg-green-50">
                      ✓ Sim
                    </Badge>
                  ) : (
                    <Badge variant="outline" className="bg-red-50">
                      ✗ Não
                    </Badge>
                  )}
                </TableCell>
                <TableCell>
                  <Button
                    variant="ghost"
                    size="icon"
                    onClick={() => handleRemove(item.id)}
                  >
                    <Trash2 className="h-4 w-4 text-destructive" />
                  </Button>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>

        {listaEspera.length === 0 && (
          <div className="text-center py-8 text-muted-foreground">
            Nenhum paciente na lista de espera
          </div>
        )}
      </CardContent>
    </Card>
  );
}

import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Plus, Edit, Trash2 } from "lucide-react";
import { toast } from "sonner";

interface Macro {
  id: string;
  nome: string;
  conteudo: string;
  visibilidade: string;
  categoria: string;
  variaveis_exemplo: any;
  ativo: boolean;
}

export const MacroManager = () => {
  const [macros, setMacros] = useState<Macro[]>([]);
  const [loading, setLoading] = useState(true);
  const [editingMacro, setEditingMacro] = useState<Macro | null>(null);
  const [isDialogOpen, setIsDialogOpen] = useState(false);

  const [formData, setFormData] = useState({
    nome: "",
    conteudo: "",
    visibilidade: "global",
    categoria: "",
    variaveis_exemplo: "{}"
  });

  const AVAILABLE_VARIABLES = [
    { label: "Nome do Cliente", value: "{{nome_cliente}}" },
    { label: "Email do Cliente", value: "{{email_cliente}}" },
    { label: "Telefone do Cliente", value: "{{telefone_cliente}}" },
    { label: "Número do Ticket", value: "{{numero_ticket}}" },
    { label: "Título do Ticket", value: "{{titulo_ticket}}" },
    { label: "Descrição do Ticket", value: "{{descricao_ticket}}" },
    { label: "Status", value: "{{status}}" },
    { label: "Prioridade", value: "{{prioridade}}" },
    { label: "Data de Criação", value: "{{data_criacao}}" },
    { label: "Nome do Agente", value: "{{nome_agente}}" },
    { label: "Email do Agente", value: "{{email_agente}}" },
    { label: "Saudação (Bom dia/tarde)", value: "{{saudacao_horario}}" },
    { label: "Data Atual", value: "{{data_atual}}" },
  ];

  const insertVariable = (variable: string) => {
    const textarea = document.getElementById('conteudo') as HTMLTextAreaElement;
    if (textarea) {
      const start = textarea.selectionStart;
      const end = textarea.selectionEnd;
      const text = formData.conteudo;
      const newText = text.substring(0, start) + variable + text.substring(end);

      setFormData({ ...formData, conteudo: newText });

      setTimeout(() => {
        textarea.focus();
        textarea.setSelectionRange(start + variable.length, start + variable.length);
      }, 0);
    } else {
      setFormData({ ...formData, conteudo: formData.conteudo + variable });
    }
  };

  useEffect(() => {
    loadMacros();
  }, []);

  const loadMacros = async () => {
    try {
      const { data, error } = await supabase
        .from("support_ticket_macros")
        .select("*")
        .order("categoria", { ascending: true });

      if (error) throw error;
      setMacros(data || []);
    } catch (error) {
      console.error("Error loading macros:", error);
      toast.error("Erro ao carregar macros");
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error("Usuário não autenticado");

      const macroData = {
        ...formData,
        variaveis_exemplo: JSON.parse(formData.variaveis_exemplo),
        created_by: user.id
      };

      if (editingMacro) {
        const { error } = await supabase
          .from("support_ticket_macros")
          .update(macroData)
          .eq("id", editingMacro.id);

        if (error) throw error;
        toast.success("Macro atualizada com sucesso");
      } else {
        const { error } = await supabase
          .from("support_ticket_macros")
          .insert([macroData]);

        if (error) throw error;
        toast.success("Macro criada com sucesso");
      }

      setIsDialogOpen(false);
      resetForm();
      loadMacros();
    } catch (error: any) {
      console.error("Error saving macro:", error);
      toast.error(error.message || "Erro ao salvar macro");
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Tem certeza que deseja excluir esta macro?")) return;

    try {
      const { error } = await supabase
        .from("support_ticket_macros")
        .delete()
        .eq("id", id);

      if (error) throw error;
      toast.success("Macro excluída com sucesso");
      loadMacros();
    } catch (error) {
      console.error("Error deleting macro:", error);
      toast.error("Erro ao excluir macro");
    }
  };

  const handleEdit = (macro: Macro) => {
    setEditingMacro(macro);
    setFormData({
      nome: macro.nome,
      conteudo: macro.conteudo,
      visibilidade: macro.visibilidade,
      categoria: macro.categoria || "",
      variaveis_exemplo: JSON.stringify(macro.variaveis_exemplo || {}, null, 2)
    });
    setIsDialogOpen(true);
  };

  const resetForm = () => {
    setEditingMacro(null);
    setFormData({
      nome: "",
      conteudo: "",
      visibilidade: "global",
      categoria: "",
      variaveis_exemplo: "{}"
    });
  };

  if (loading) {
    return <div className="text-center py-8">Carregando macros...</div>;
  }

  return (
    <Card className="p-6">
      <div className="flex items-center justify-between mb-6">
        <h2 className="text-2xl font-bold">Macros de Resposta</h2>
        <Dialog open={isDialogOpen} onOpenChange={(open) => {
          setIsDialogOpen(open);
          if (!open) resetForm();
        }}>
          <DialogTrigger asChild>
            <Button>
              <Plus className="h-4 w-4 mr-2" />
              Nova Macro
            </Button>
          </DialogTrigger>
          <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
            <DialogHeader>
              <DialogTitle>{editingMacro ? "Editar" : "Nova"} Macro</DialogTitle>
            </DialogHeader>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <Label htmlFor="nome">Nome da Macro</Label>
                <Input
                  id="nome"
                  value={formData.nome}
                  onChange={(e) => setFormData({ ...formData, nome: e.target.value })}
                  required
                />
              </div>

              <div>
                <Label htmlFor="categoria">Categoria</Label>
                <Input
                  id="categoria"
                  value={formData.categoria}
                  onChange={(e) => setFormData({ ...formData, categoria: e.target.value })}
                  placeholder="Ex: Saudações, Resoluções"
                />
              </div>

              <div>
                <Label htmlFor="visibilidade">Visibilidade</Label>
                <Select value={formData.visibilidade} onValueChange={(value) => setFormData({ ...formData, visibilidade: value })}>
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="global">Global</SelectItem>
                    <SelectItem value="tenant">Tenant Específico</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              <div>
                <Label htmlFor="conteudo">Conteúdo</Label>
                <div className="space-y-2">
                  <Textarea
                    id="conteudo"
                    value={formData.conteudo}
                    onChange={(e) => setFormData({ ...formData, conteudo: e.target.value })}
                    rows={8}
                    required
                    placeholder="Use {{variavel}} para placeholders"
                  />
                  <div className="flex flex-wrap gap-2">
                    {AVAILABLE_VARIABLES.map((v) => (
                      <Badge
                        key={v.value}
                        variant="outline"
                        className="cursor-pointer hover:bg-secondary transition-colors"
                        onClick={() => insertVariable(v.value)}
                      >
                        {v.label}
                      </Badge>
                    ))}
                  </div>
                  <p className="text-xs text-muted-foreground">
                    Clique nas variáveis acima para inseri-las no texto.
                  </p>
                </div>
              </div>

              <div>
                <Label htmlFor="variaveis">Variáveis de Exemplo (JSON)</Label>
                <p className="text-xs text-muted-foreground mb-2">
                  Use este campo apenas para documentar exemplos de valores para as variáveis. Isso não afeta a substituição real.
                </p>
                <Textarea
                  id="variaveis"
                  value={formData.variaveis_exemplo}
                  onChange={(e) => setFormData({ ...formData, variaveis_exemplo: e.target.value })}
                  rows={4}
                  placeholder='{"nome_cliente": "Exemplo", "numero_ticket": "123"}'
                />
              </div>

              <div className="flex gap-2 justify-end">
                <Button type="button" variant="outline" onClick={() => setIsDialogOpen(false)}>
                  Cancelar
                </Button>
                <Button type="submit">
                  {editingMacro ? "Atualizar" : "Criar"}
                </Button>
              </div>
            </form>
          </DialogContent>
        </Dialog>
      </div>

      <div className="space-y-4">
        {macros.length === 0 ? (
          <p className="text-center py-8 text-muted-foreground">Nenhuma macro cadastrada</p>
        ) : (
          macros.map((macro) => (
            <Card key={macro.id} className="p-4">
              <div className="flex items-start justify-between">
                <div className="flex-1">
                  <div className="flex items-center gap-2 mb-2">
                    <h3 className="font-semibold">{macro.nome}</h3>
                    {macro.categoria && <Badge variant="outline">{macro.categoria}</Badge>}
                    <Badge variant={macro.visibilidade === 'global' ? 'default' : 'secondary'}>
                      {macro.visibilidade}
                    </Badge>
                  </div>
                  <p className="text-sm text-muted-foreground line-clamp-3 whitespace-pre-wrap">
                    {macro.conteudo}
                  </p>
                </div>
                <div className="flex gap-2 ml-4">
                  <Button variant="ghost" size="sm" onClick={() => handleEdit(macro)}>
                    <Edit className="h-4 w-4" />
                  </Button>
                  <Button variant="ghost" size="sm" onClick={() => handleDelete(macro.id)}>
                    <Trash2 className="h-4 w-4" />
                  </Button>
                </div>
              </div>
            </Card>
          ))
        )}
      </div>
    </Card>
  );
};

import { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { ScrollArea } from "@/components/ui/scroll-area";
import { toast } from "sonner";
import { Search, Eye, Hash } from "lucide-react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";

interface MessageAudit {
  id: string;
  rota: string;
  actor_type: string;
  ip_address: string;
  timestamp: string;
  payload_hash: string;
  status: string;
  error_message: string | null;
}

export function MessageAuditViewer() {
  const [audits, setAudits] = useState<MessageAudit[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedAudit, setSelectedAudit] = useState<MessageAudit | null>(null);

  useEffect(() => {
    loadAudits();
  }, []);

  const loadAudits = async () => {
    try {
      setLoading(true);

      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error('Não autenticado');

      const { data: profile } = await supabase
        .from('profiles')
        .select('tenant_id')
        .eq('id', user.id)
        .single();

      if (!profile?.tenant_id) throw new Error('Tenant não encontrado');

      const { data, error } = await supabase
        .from('message_audit' as any)
        .select('*')
        .eq('tenant_id', profile.tenant_id)
        .order('timestamp', { ascending: false })
        .limit(100);

      if (error) throw error;
      setAudits((data as any) || []);
    } catch (error) {
      console.error('Erro ao carregar auditoria:', error);
      toast.error('Erro ao carregar auditoria de mensagens');
    } finally {
      setLoading(false);
    }
  };

  const handleReplay = async (messageId: string) => {
    try {
      const { data, error } = await supabase.functions.invoke('replay-message', {
        body: { message_id: messageId }
      });

      if (error) throw error;

      toast.success('Replay recuperado com sucesso');
      console.log('Replay data:', data);
    } catch (error) {
      console.error('Erro ao fazer replay:', error);
      toast.error('Erro ao fazer replay da mensagem');
    }
  };

  const filteredAudits = audits.filter(audit =>
    audit.rota.toLowerCase().includes(searchTerm.toLowerCase()) ||
    audit.actor_type.toLowerCase().includes(searchTerm.toLowerCase()) ||
    audit.payload_hash.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'sent':
        return <Badge className="bg-success">Enviado</Badge>;
      case 'failed':
        return <Badge variant="destructive">Falhou</Badge>;
      case 'pending':
        return <Badge variant="outline">Pendente</Badge>;
      default:
        return <Badge variant="secondary">{status}</Badge>;
    }
  };

  if (loading) {
    return <div>Carregando auditoria...</div>;
  }

  return (
    <>
      <Card>
        <CardHeader>
          <div className="flex items-center gap-2">
            <Hash className="h-5 w-5 text-primary" />
            <CardTitle>Auditoria Detalhada de Mensagens</CardTitle>
          </div>
          <CardDescription>
            Rastreamento completo: rota, ator, IP, timestamp e hash do payload
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="mb-4">
            <div className="relative">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-muted-foreground h-4 w-4" />
              <Input
                placeholder="Buscar por rota, tipo de ator ou hash..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pl-10"
              />
            </div>
          </div>

          <ScrollArea className="h-[600px]">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Timestamp</TableHead>
                  <TableHead>Rota</TableHead>
                  <TableHead>Ator</TableHead>
                  <TableHead>IP</TableHead>
                  <TableHead>Hash</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead>Ações</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {filteredAudits.map((audit) => (
                  <TableRow key={audit.id}>
                    <TableCell className="font-mono text-xs">
                      {new Date(audit.timestamp).toLocaleString()}
                    </TableCell>
                    <TableCell className="font-medium">{audit.rota}</TableCell>
                    <TableCell>
                      <Badge variant="outline">{audit.actor_type}</Badge>
                    </TableCell>
                    <TableCell className="font-mono text-xs">{audit.ip_address}</TableCell>
                    <TableCell className="font-mono text-xs">
                      {audit.payload_hash.substring(0, 12)}...
                    </TableCell>
                    <TableCell>{getStatusBadge(audit.status)}</TableCell>
                    <TableCell>
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => setSelectedAudit(audit)}
                      >
                        <Eye className="h-4 w-4" />
                      </Button>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </ScrollArea>
        </CardContent>
      </Card>

      <Dialog open={!!selectedAudit} onOpenChange={() => setSelectedAudit(null)}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle>Detalhes da Auditoria</DialogTitle>
            <DialogDescription>Informações completas do registro de auditoria</DialogDescription>
          </DialogHeader>
          {selectedAudit && (
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <p className="text-sm font-medium text-muted-foreground">Timestamp</p>
                  <p className="font-mono text-sm">{new Date(selectedAudit.timestamp).toLocaleString()}</p>
                </div>
                <div>
                  <p className="text-sm font-medium text-muted-foreground">Status</p>
                  {getStatusBadge(selectedAudit.status)}
                </div>
                <div>
                  <p className="text-sm font-medium text-muted-foreground">Rota</p>
                  <p className="font-medium">{selectedAudit.rota}</p>
                </div>
                <div>
                  <p className="text-sm font-medium text-muted-foreground">Tipo de Ator</p>
                  <Badge variant="outline">{selectedAudit.actor_type}</Badge>
                </div>
                <div>
                  <p className="text-sm font-medium text-muted-foreground">IP Address</p>
                  <p className="font-mono text-sm">{selectedAudit.ip_address}</p>
                </div>
                <div>
                  <p className="text-sm font-medium text-muted-foreground">Payload Hash</p>
                  <p className="font-mono text-xs break-all">{selectedAudit.payload_hash}</p>
                </div>
              </div>
              {selectedAudit.error_message && (
                <div>
                  <p className="text-sm font-medium text-muted-foreground mb-2">Mensagem de Erro</p>
                  <div className="bg-destructive/10 border border-destructive/20 rounded p-3">
                    <p className="text-sm text-destructive">{selectedAudit.error_message}</p>
                  </div>
                </div>
              )}
            </div>
          )}
        </DialogContent>
      </Dialog>
    </>
  );
}

import { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { TrendingUp, Clock, CheckCircle, Users } from "lucide-react";

export function MetricasListaEspera() {
  const [metricas, setMetricas] = useState<any>(null);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    loadMetricas();
  }, []);

  const loadMetricas = async () => {
    try {
      const { data: profile } = await supabase
        .from("profiles")
        .select("tenant_id")
        .eq("id", (await supabase.auth.getUser()).data.user?.id)
        .single();

      if (!profile?.tenant_id) return;

      // Métricas do último mês
      const { data } = await supabase
        .from("metricas_lista_espera" as any)
        .select("*")
        .eq("tenant_id", profile.tenant_id)
        .gte("data", new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString())
        .order("data", { ascending: false });

      if (data && data.length > 0) {
        // Calcular totais
        const totais = (data as any[]).reduce(
          (acc, m: any) => ({
            ofertas_enviadas: acc.ofertas_enviadas + (m.ofertas_enviadas || 0),
            ofertas_aceitas: acc.ofertas_aceitas + (m.ofertas_aceitas || 0),
            ofertas_recusadas: acc.ofertas_recusadas + (m.ofertas_recusadas || 0),
            ofertas_expiradas: acc.ofertas_expiradas + (m.ofertas_expiradas || 0),
            vagas_salvas: acc.vagas_salvas + (m.vagas_salvas || 0),
            tempo_medio_resposta: acc.tempo_medio_resposta + (m.tempo_medio_resposta_minutos || 0),
          }),
          {
            ofertas_enviadas: 0,
            ofertas_aceitas: 0,
            ofertas_recusadas: 0,
            ofertas_expiradas: 0,
            vagas_salvas: 0,
            tempo_medio_resposta: 0,
          }
        );

        const taxaAceitacao = totais.ofertas_enviadas > 0
          ? ((totais.ofertas_aceitas / totais.ofertas_enviadas) * 100).toFixed(1)
          : 0;

        const tempoMedioResposta = data.length > 0
          ? Math.round(totais.tempo_medio_resposta / data.length)
          : 0;

        setMetricas({
          ...totais,
          taxa_aceitacao: taxaAceitacao,
          tempo_medio_resposta_minutos: tempoMedioResposta,
          pacientes_em_fila: (data[0] as any)?.pacientes_em_fila || 0,
        });
      }
    } catch (error) {
      console.error("Erro ao carregar métricas:", error);
    } finally {
      setIsLoading(false);
    }
  };

  if (isLoading || !metricas) {
    return <div>Carregando métricas...</div>;
  }

  return (
    <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
      <Card>
        <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
          <CardTitle className="text-sm font-medium">Taxa de Aceitação</CardTitle>
          <TrendingUp className="h-4 w-4 text-muted-foreground" />
        </CardHeader>
        <CardContent>
          <div className="text-2xl font-bold">{metricas.taxa_aceitacao}%</div>
          <p className="text-xs text-muted-foreground">
            {metricas.ofertas_aceitas} de {metricas.ofertas_enviadas} ofertas
          </p>
        </CardContent>
      </Card>

      <Card>
        <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
          <CardTitle className="text-sm font-medium">Tempo Médio de Resposta</CardTitle>
          <Clock className="h-4 w-4 text-muted-foreground" />
        </CardHeader>
        <CardContent>
          <div className="text-2xl font-bold">{metricas.tempo_medio_resposta_minutos} min</div>
          <p className="text-xs text-muted-foreground">Tempo para responder</p>
        </CardContent>
      </Card>

      <Card>
        <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
          <CardTitle className="text-sm font-medium">Vagas Salvas</CardTitle>
          <CheckCircle className="h-4 w-4 text-muted-foreground" />
        </CardHeader>
        <CardContent>
          <div className="text-2xl font-bold">{metricas.vagas_salvas}</div>
          <p className="text-xs text-muted-foreground">Vagas que não ficaram vazias</p>
        </CardContent>
      </Card>

      <Card>
        <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
          <CardTitle className="text-sm font-medium">Pacientes em Fila</CardTitle>
          <Users className="h-4 w-4 text-muted-foreground" />
        </CardHeader>
        <CardContent>
          <div className="text-2xl font-bold">{metricas.pacientes_em_fila}</div>
          <p className="text-xs text-muted-foreground">Aguardando vaga</p>
        </CardContent>
      </Card>
    </div>
  );
}

import { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
