import { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Clock, CheckCircle, XCircle, AlertCircle } from "lucide-react";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { formatDistanceToNow } from "date-fns";
import { ptBR } from "date-fns/locale";

export function OfertasVagaMonitor() {
  const [ofertas, setOfertas] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    loadOfertas();

    // Atualizar em tempo real
    const channel = supabase
      .channel('ofertas_vaga_changes')
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'ofertas_vaga'
        },
        () => loadOfertas()
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, []);

  const loadOfertas = async () => {
    try {
      const { data: profile } = await supabase
        .from("profiles")
        .select("tenant_id")
        .eq("id", (await supabase.auth.getUser()).data.user?.id)
        .single();

      if (!profile?.tenant_id) return;

      const { data } = await supabase
        .from("ofertas_vaga" as any)
        .select("*, pacientes(nome, telefone)")
        .eq("tenant_id", profile.tenant_id)
        .order("enviado_em", { ascending: false })
        .limit(50);

      if (data) setOfertas(data);
    } catch (error) {
      console.error("Erro ao carregar ofertas:", error);
    } finally {
      setIsLoading(false);
    }
  };

  const getStatusBadge = (status: string) => {
    const config: Record<string, { label: string; variant: any; icon: any }> = {
      pendente: { label: "Pendente", variant: "default", icon: Clock },
      aceito: { label: "Aceito ✓", variant: "default", icon: CheckCircle },
      recusado: { label: "Recusado", variant: "secondary", icon: XCircle },
      expirado: { label: "Expirado", variant: "outline", icon: AlertCircle },
      preenchido_outro: { label: "Preenchido", variant: "outline", icon: CheckCircle },
    };

    const { label, variant, icon: Icon } = config[status] || config.pendente;

    return (
      <Badge variant={variant} className="gap-1">
        <Icon className="h-3 w-3" />
        {label}
      </Badge>
    );
  };

  const getTempoRestante = (expiraEm: string) => {
    const expira = new Date(expiraEm);
    const agora = new Date();
    const diff = expira.getTime() - agora.getTime();

    if (diff <= 0) return "Expirado";

    const minutos = Math.floor(diff / 60000);
    return `${minutos} min restantes`;
  };

  if (isLoading) {
    return <div>Carregando...</div>;
  }

  return (
    <Card>
      <CardHeader>
        <div className="flex items-center gap-2">
          <Clock className="h-5 w-5" />
          <CardTitle>Monitor de Ofertas em Tempo Real</CardTitle>
        </div>
      </CardHeader>
      <CardContent>
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Paciente</TableHead>
              <TableHead>Telefone</TableHead>
              <TableHead>Data/Hora Oferecida</TableHead>
              <TableHead>Status</TableHead>
              <TableHead>Enviado</TableHead>
              <TableHead>Tempo Restante</TableHead>
              <TableHead>Resposta</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {ofertas.map((oferta) => (
              <TableRow key={oferta.id}>
                <TableCell className="font-medium">
                  {oferta.pacientes?.nome}
                </TableCell>
                <TableCell>{oferta.pacientes?.telefone}</TableCell>
                <TableCell>
                  {new Date(oferta.data_hora_oferecida).toLocaleString('pt-BR')}
                </TableCell>
                <TableCell>{getStatusBadge(oferta.status)}</TableCell>
                <TableCell>
                  {formatDistanceToNow(new Date(oferta.enviado_em), {
                    addSuffix: true,
                    locale: ptBR,
                  })}
                </TableCell>
                <TableCell>
                  {oferta.status === 'pendente' ? (
                    <span className="text-sm text-orange-600 font-medium">
                      {getTempoRestante(oferta.expira_em)}
                    </span>
                  ) : (
                    <span className="text-sm text-muted-foreground">-</span>
                  )}
                </TableCell>
                <TableCell>
                  {oferta.respondido_em ? (
                    <span className="text-xs text-muted-foreground">
                      {formatDistanceToNow(new Date(oferta.respondido_em), {
                        addSuffix: true,
                        locale: ptBR,
                      })}
                    </span>
                  ) : (
                    <span className="text-xs text-muted-foreground">Aguardando...</span>
                  )}
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>

        {ofertas.length === 0 && (
          <div className="text-center py-8 text-muted-foreground">
            Nenhuma oferta no momento
          </div>
        )}
      </CardContent>
    </Card>
  );
}

import React, { useEffect, useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Progress } from "@/components/ui/progress";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { useBilling } from "@/hooks/useBilling";
import { supabase } from "@/integrations/supabase/client";
import { Loader2, Zap, Users, MessageSquare } from "lucide-react";
import { useNavigate } from 'react-router-dom';

export function PlanChecklist() {
    const { planCode, loading: billingLoading } = useBilling();
    const navigate = useNavigate();
    const [usage, setUsage] = useState({
        clients: 0,
        professionals: 0,
        messages: 0
    });
    const [limits, setLimits] = useState({
        clients: Infinity,
        professionals: 1,
        messages: 0
    });
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        if (planCode) {
            fetchUsageAndLimits();
        }
    }, [planCode]);

    const fetchUsageAndLimits = async () => {
        setLoading(true);
        try {
            // Fetch Usage
            // Mocking usage fetch for now, ideally this comes from a view or rpc
            const { count: clientCount } = await supabase.from('pacientes').select('*', { count: 'exact', head: true });
            const { count: profCount } = await supabase.from('profiles').select('*', { count: 'exact', head: true }).eq('role', 'profissional');

            // Mock message usage (would come from a message_logs table)
            const messageCount = 120;

            setUsage({
                clients: clientCount || 0,
                professionals: profCount || 1,
                messages: messageCount
            });

            // Set Limits based on Plan Code
            // This should ideally come from the plans table or a config
            let newLimits = { clients: Infinity, professionals: 1, messages: 0 };

            if (planCode === 'free_solo') {
                newLimits = { clients: 50, professionals: 1, messages: 0 };
            } else if (planCode === 'pro_solo') {
                newLimits = { clients: Infinity, professionals: 1, messages: 500 };
            } else if (planCode === 'clinic') {
                newLimits = { clients: Infinity, professionals: 5, messages: 2000 };
            }

            setLimits(newLimits);

        } catch (error) {
            console.error("Error fetching usage:", error);
        } finally {
            setLoading(false);
        }
    };

    if (billingLoading || loading) {
        return <Card><CardContent className="p-6"><Loader2 className="animate-spin" /></CardContent></Card>;
    }

    const getPlanName = (code: string | null) => {
        switch (code) {
            case 'free_solo': return 'Free Solo';
            case 'pro_solo': return 'Pro Solo';
            case 'clinic': return 'Clínica';
            case 'multi_unit': return 'Multiunidades';
            default: return 'Desconhecido';
        }
    };

    return (
        <Card>
            <CardHeader className="pb-2">
                <div className="flex justify-between items-center">
                    <CardTitle className="text-lg font-semibold flex items-center gap-2">
                        <Zap className="h-4 w-4 text-yellow-500" />
                        Resumo do Plano
                    </CardTitle>
                    <Badge variant={planCode === 'free_solo' ? 'secondary' : 'default'}>
                        {getPlanName(planCode)}
                    </Badge>
                </div>
            </CardHeader>
            <CardContent className="space-y-4">
                {/* Professionals */}
                <div className="space-y-1">
                    <div className="flex justify-between text-sm">
                        <span className="flex items-center gap-2 text-muted-foreground">
                            <Users className="h-3 w-3" /> Profissionais
                        </span>
                        <span className="font-medium">
                            {usage.professionals} / {limits.professionals === Infinity ? '∞' : limits.professionals}
                        </span>
                    </div>
                    {limits.professionals !== Infinity && (
                        <Progress value={(usage.professionals / limits.professionals) * 100} />
                    )}
                </div>

                {/* Clients */}
                <div className="space-y-1">
                    <div className="flex justify-between text-sm">
                        <span className="text-muted-foreground">Clientes</span>
                        <span className="font-medium">
                            {usage.clients} / {limits.clients === Infinity ? '∞' : limits.clients}
                        </span>
                    </div>
                    {limits.clients !== Infinity && (
                        <Progress value={(usage.clients / limits.clients) * 100} className={usage.clients >= limits.clients ? "bg-red-100" : ""} />
                    )}
                </div>

                {/* Messages */}
                {limits.messages > 0 && (
                    <div className="space-y-1">
                        <div className="flex justify-between text-sm">
                            <span className="flex items-center gap-2 text-muted-foreground">
                                <MessageSquare className="h-3 w-3" /> Mensagens WhatsApp
                            </span>
                            <span className="font-medium">
                                {usage.messages} / {limits.messages}
                            </span>
                        </div>
                        <Progress value={(usage.messages / limits.messages) * 100} />
                    </div>
                )}

                {/* Upgrade Call to Action */}
                {planCode === 'free_solo' && (
                    <div className="pt-2">
                        <Button
                            variant="outline"
                            className="w-full border-primary text-primary hover:bg-primary hover:text-white transition-colors"
                            onClick={() => navigate('/admin/planos')}
                        >
                            Fazer Upgrade
                        </Button>
                    </div>
                )}
            </CardContent>
        </Card>
    );
}

import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Plus, Edit } from "lucide-react";
import { toast } from "sonner";
import { NewPlanDialog } from "./NewPlanDialog";

interface Plan {
  id: string;
  name: string;
  slug: string;
  price_monthly: number;
  price_annual: number;
  description: string;
  active: boolean;
  features: any;
}

export const PlanManagement = () => {
  const [plans, setPlans] = useState<Plan[]>([]);
  const [loading, setLoading] = useState(true);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingPlan, setEditingPlan] = useState<Plan | null>(null);

  useEffect(() => {
    loadPlans();
  }, []);

  const loadPlans = async () => {
    try {
      const { data, error } = await supabase
        .from("plans")
        .select("*")
        .order("display_order", { ascending: true });

      if (error) throw error;
      setPlans(data || []);
    } catch (error) {
      console.error("Error loading plans:", error);
      toast.error("Erro ao carregar planos");
    } finally {
      setLoading(false);
    }
  };

  const togglePlanStatus = async (planId: string, currentStatus: boolean) => {
    try {
      const { error } = await supabase
        .from("plans")
        .update({ active: !currentStatus })
        .eq("id", planId);

      if (error) throw error;

      const { data: { user } } = await supabase.auth.getUser();
      if (user) {
        await supabase.from("support_actions_log").insert({
          support_user_id: user.id,
          action_type: "plan_status_change",
          target_type: "plan",
          target_id: planId,
          description: `Plano ${!currentStatus ? 'ativado' : 'desativado'}`,
        });
      }

      toast.success("Status do plano atualizado");
      loadPlans();
    } catch (error) {
      console.error("Error toggling plan status:", error);
      toast.error("Erro ao atualizar status do plano");
    }
  };

  return (
    <>
      <NewPlanDialog
        open={dialogOpen}
        onOpenChange={setDialogOpen}
        onSuccess={loadPlans}
        editingPlan={editingPlan}
      />
      <Card className="p-6">
        <div className="flex items-center justify-between mb-6">
          <h2 className="text-2xl font-bold">Gerenciar Planos</h2>
          <Button onClick={() => {
            setEditingPlan(null);
            setDialogOpen(true);
          }}>
            <Plus className="h-4 w-4 mr-2" />
            Novo Plano
          </Button>
        </div>

      {loading ? (
        <p className="text-center py-8 text-muted-foreground">Carregando...</p>
      ) : plans.length === 0 ? (
        <p className="text-center py-8 text-muted-foreground">Nenhum plano encontrado</p>
      ) : (
        <div className="grid gap-4">
          {plans.map((plan) => (
            <Card key={plan.id} className="p-6">
              <div className="flex items-start justify-between">
                <div className="flex-1">
                  <div className="flex items-center gap-2 mb-2">
                    <h3 className="text-xl font-bold">{plan.name}</h3>
                    <Badge variant={plan.active ? "default" : "secondary"}>
                      {plan.active ? "Ativo" : "Inativo"}
                    </Badge>
                  </div>
                  <p className="text-muted-foreground mb-4">{plan.description}</p>
                  <div className="flex gap-6 text-sm">
                    <div>
                      <span className="font-semibold">Mensal:</span> R$ {plan.price_monthly}
                    </div>
                    <div>
                      <span className="font-semibold">Anual:</span> R$ {plan.price_annual}
                    </div>
                  </div>
                </div>
                <div className="flex gap-2">
                  <Button 
                    variant="outline" 
                    size="sm"
                    onClick={() => {
                      setEditingPlan(plan);
                      setDialogOpen(true);
                    }}
                  >
                    <Edit className="h-4 w-4" />
                  </Button>
                  <Button
                    variant={plan.active ? "destructive" : "default"}
                    size="sm"
                    onClick={() => togglePlanStatus(plan.id, plan.active)}
                  >
                    {plan.active ? "Desativar" : "Ativar"}
                  </Button>
                </div>
              </div>
            </Card>
          ))}
        </div>
      )}
      </Card>
    </>
  );
};

import React, { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
