import { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { toast } from "sonner";
import { Clock, Play, Plus, Edit2, Trash2 } from "lucide-react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Switch } from "@/components/ui/switch";
import { Textarea } from "@/components/ui/textarea";

interface RetentionPolicy {
  id: string;
  policy_name: string;
  target_table: string;
  retention_months: number;
  description: string;
  active: boolean;
  last_applied_at: string | null;
}

export function RetentionPolicyManager() {
  const [policies, setPolicies] = useState<RetentionPolicy[]>([]);
  const [loading, setLoading] = useState(true);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingPolicy, setEditingPolicy] = useState<RetentionPolicy | null>(null);
  const [formData, setFormData] = useState({
    policy_name: "",
    target_table: "",
    retention_months: 24,
    description: "",
    active: true,
  });

  useEffect(() => {
    loadPolicies();
  }, []);

  const loadPolicies = async () => {
    try {
      setLoading(true);
      const { data, error } = await supabase
        .from('retention_policies_detailed' as any)
        .select('*')
        .order('policy_name');

      if (error) throw error;
      setPolicies((data as any) || []);
    } catch (error) {
      console.error('Erro ao carregar políticas:', error);
      toast.error('Erro ao carregar políticas de retenção');
    } finally {
      setLoading(false);
    }
  };

  const handleSave = async () => {
    try {
      if (editingPolicy) {
        const { error } = await supabase
          .from('retention_policies_detailed' as any)
          .update(formData)
          .eq('id', editingPolicy.id);

        if (error) throw error;
        toast.success('Política atualizada com sucesso');
      } else {
        const { error } = await supabase
          .from('retention_policies_detailed' as any)
          .insert(formData);

        if (error) throw error;
        toast.success('Política criada com sucesso');
      }

      setDialogOpen(false);
      setEditingPolicy(null);
      setFormData({
        policy_name: "",
        target_table: "",
        retention_months: 24,
        description: "",
        active: true,
      });
      loadPolicies();
    } catch (error: any) {
      console.error('Erro ao salvar política:', error);
      toast.error(error.message || 'Erro ao salvar política');
    }
  };

  const handleApplyPolicies = async () => {
    try {
      toast.info('Aplicando políticas de retenção...');

      const { data, error } = await supabase.functions.invoke('apply-retention-policies');

      if (error) throw error;

      toast.success('Políticas de retenção aplicadas com sucesso');
      console.log('Resultado:', data);
      loadPolicies();
    } catch (error: any) {
      console.error('Erro ao aplicar políticas:', error);
      toast.error('Erro ao aplicar políticas de retenção');
    }
  };

  const handleToggleActive = async (policy: RetentionPolicy) => {
    try {
      const { error } = await supabase
        .from('retention_policies_detailed' as any)
        .update({ active: !policy.active })
        .eq('id', policy.id);

      if (error) throw error;
      toast.success('Status atualizado');
      loadPolicies();
    } catch (error: any) {
      console.error('Erro ao atualizar status:', error);
      toast.error('Erro ao atualizar status');
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Tem certeza que deseja excluir esta política?')) return;

    try {
      const { error } = await supabase
        .from('retention_policies_detailed' as any)
        .delete()
        .eq('id', id);

      if (error) throw error;
      toast.success('Política excluída');
      loadPolicies();
    } catch (error: any) {
      console.error('Erro ao excluir política:', error);
      toast.error('Erro ao excluir política');
    }
  };

  if (loading) {
    return <div>Carregando políticas de retenção...</div>;
  }

  return (
    <div className="space-y-6">
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Clock className="h-5 w-5 text-primary" />
              <div>
                <CardTitle>Políticas de Retenção de Dados</CardTitle>
                <CardDescription>
                  Configuração de períodos de retenção: 24 meses mensagens, 36 meses auditoria
                </CardDescription>
              </div>
            </div>
            <div className="flex gap-2">
              <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
                <DialogTrigger asChild>
                  <Button onClick={() => {
                    setEditingPolicy(null);
                    setFormData({
                      policy_name: "",
                      target_table: "",
                      retention_months: 24,
                      description: "",
                      active: true,
                    });
                  }}>
                    <Plus className="h-4 w-4 mr-2" />
                    Nova Política
                  </Button>
                </DialogTrigger>
                <DialogContent>
                  <DialogHeader>
                    <DialogTitle>
                      {editingPolicy ? 'Editar Política' : 'Nova Política de Retenção'}
                    </DialogTitle>
                    <DialogDescription>
                      Configure o período de retenção de dados para uma tabela específica
                    </DialogDescription>
                  </DialogHeader>
                  <div className="space-y-4">
                    <div className="space-y-2">
                      <Label>Nome da Política</Label>
                      <Input
                        value={formData.policy_name}
                        onChange={(e) => setFormData({ ...formData, policy_name: e.target.value })}
                        placeholder="Ex: Retenção de Mensagens"
                      />
                    </div>
                    <div className="space-y-2">
                      <Label>Tabela Alvo</Label>
                      <Input
                        value={formData.target_table}
                        onChange={(e) => setFormData({ ...formData, target_table: e.target.value })}
                        placeholder="Ex: log_mensagens"
                      />
                    </div>
                    <div className="space-y-2">
                      <Label>Período de Retenção (meses)</Label>
                      <Input
                        type="number"
                        value={formData.retention_months}
                        onChange={(e) => setFormData({ ...formData, retention_months: parseInt(e.target.value) })}
                        min={1}
                      />
                    </div>
                    <div className="space-y-2">
                      <Label>Descrição</Label>
                      <Textarea
                        value={formData.description}
                        onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                        placeholder="Descreva o propósito desta política..."
                      />
                    </div>
                    <div className="flex items-center space-x-2">
                      <Switch
                        checked={formData.active}
                        onCheckedChange={(checked) => setFormData({ ...formData, active: checked })}
                      />
                      <Label>Ativa</Label>
                    </div>
                    <Button onClick={handleSave} className="w-full">
                      Salvar Política
                    </Button>
                  </div>
                </DialogContent>
              </Dialog>
              <Button onClick={handleApplyPolicies} variant="outline">
                <Play className="h-4 w-4 mr-2" />
                Aplicar Agora
              </Button>
            </div>
          </div>
        </CardHeader>
        <CardContent>
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Nome</TableHead>
                <TableHead>Tabela</TableHead>
                <TableHead>Retenção</TableHead>
                <TableHead>Última Aplicação</TableHead>
                <TableHead>Status</TableHead>
                <TableHead>Ações</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {policies.map((policy) => (
                <TableRow key={policy.id}>
                  <TableCell>
                    <div>
                      <p className="font-medium">{policy.policy_name}</p>
                      <p className="text-xs text-muted-foreground">{policy.description}</p>
                    </div>
                  </TableCell>
                  <TableCell>
                    <code className="text-xs bg-muted px-2 py-1 rounded">{policy.target_table}</code>
                  </TableCell>
                  <TableCell>{policy.retention_months} meses</TableCell>
                  <TableCell className="text-xs">
                    {policy.last_applied_at 
                      ? new Date(policy.last_applied_at).toLocaleString('pt-BR')
                      : 'Nunca aplicada'}
                  </TableCell>
                  <TableCell>
                    <Badge variant={policy.active ? "default" : "secondary"}>
                      {policy.active ? 'Ativa' : 'Inativa'}
                    </Badge>
                  </TableCell>
                  <TableCell>
                    <div className="flex gap-2">
                      <Button
                        size="sm"
                        variant="ghost"
                        onClick={() => {
                          setEditingPolicy(policy);
                          setFormData({
                            policy_name: policy.policy_name,
                            target_table: policy.target_table,
                            retention_months: policy.retention_months,
                            description: policy.description,
                            active: policy.active,
                          });
                          setDialogOpen(true);
                        }}
                      >
                        <Edit2 className="h-4 w-4" />
                      </Button>
                      <Button
                        size="sm"
                        variant="ghost"
                        onClick={() => handleToggleActive(policy)}
                      >
                        <Switch checked={policy.active} />
                      </Button>
                      <Button
                        size="sm"
                        variant="ghost"
                        onClick={() => handleDelete(policy.id)}
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    </div>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </CardContent>
      </Card>
    </div>
  );
}

import { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";
import { AlertTriangle, TrendingUp, CheckCircle, MapPin, Calendar } from "lucide-react";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";

interface AgendamentoRisco {
  id: string;
  inicio: string;
  paciente: { nome: string; telefone: string };
  servico: { nome: string };
  score: number;
  acoes_tomadas: string[];
}

export function RiscoNoShowDashboard() {
  const [agendamentosRisco, setAgendamentosRisco] = useState<AgendamentoRisco[]>([]);
  const [loading, setLoading] = useState(true);
  const [calculando, setCalculando] = useState<string | null>(null);

  const loadAgendamentosRisco = async () => {
    try {
      const { data: profile } = await supabase
        .from("profiles")
        .select("tenant_id")
        .single();

      if (!profile?.tenant_id) return;

      // Buscar agendamentos com alto risco
      const { data, error } = await supabase
        .from("risco_no_show_scores" as any)
        .select(`
          *,
          agenda!inner(
            id,
            inicio,
            pacientes(nome, telefone),
            procedimentos:servico_id(nome)
          )
        `)
        .eq("tenant_id", profile.tenant_id)
        .gte("score", 60)
        .order("score", { ascending: false })
        .limit(20);

      if (error) throw error;

      const formatted = (data as any[] || []).map((item: any) => ({
        id: item.agendamento_id,
        inicio: item.agenda.inicio,
        paciente: item.agenda.pacientes,
        servico: item.agenda.servicos,
        score: item.score,
        acoes_tomadas: item.acoes_tomadas || []
      }));

      setAgendamentosRisco(formatted);
    } catch (error) {
      console.error("Erro ao carregar agendamentos de risco:", error);
      toast.error("Erro ao carregar dados");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadAgendamentosRisco();
  }, []);

  const calcularRisco = async (agendamentoId: string) => {
    setCalculando(agendamentoId);
    try {
      const { error } = await supabase.functions.invoke("calcular-risco-no-show", {
        body: { agendamento_id: agendamentoId }
      });

      if (error) throw error;

      toast.success("Score recalculado e ações tomadas!");
      loadAgendamentosRisco();
    } catch (error) {
      console.error("Erro ao calcular risco:", error);
      toast.error("Erro ao calcular risco");
    } finally {
      setCalculando(null);
    }
  };

  const getScoreBadge = (score: number) => {
    if (score >= 85) {
      return <Badge variant="destructive" className="gap-1">
        <AlertTriangle className="h-3 w-3" />
        Crítico ({score})
      </Badge>;
    }
    if (score >= 70) {
      return <Badge variant="default" className="gap-1 bg-orange-500">
        <TrendingUp className="h-3 w-3" />
        Alto ({score})
      </Badge>;
    }
    return <Badge variant="secondary" className="gap-1">
      Moderado ({score})
    </Badge>;
  };

  const getAcaoLabel = (acao: string) => {
    const labels: Record<string, string> = {
      lembrete_extra: "Lembrete Extra Enviado",
      oferta_rota: "Rota Google Maps Enviada"
    };
    return labels[acao] || acao;
  };

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-2xl font-bold">Risco de No-Show</h2>
        <p className="text-muted-foreground">
          Monitore agendamentos com alta probabilidade de falta e tome ações preventivas
        </p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <Card>
          <CardHeader className="pb-3">
            <CardTitle className="text-sm font-medium text-muted-foreground">
              Alto Risco (≥70)
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-3xl font-bold text-orange-500">
              {agendamentosRisco.filter(a => a.score >= 70 && a.score < 85).length}
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="pb-3">
            <CardTitle className="text-sm font-medium text-muted-foreground">
              Crítico (≥85)
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-3xl font-bold text-destructive">
              {agendamentosRisco.filter(a => a.score >= 85).length}
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="pb-3">
            <CardTitle className="text-sm font-medium text-muted-foreground">
              Com Ações
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="flex items-center gap-2">
              <CheckCircle className="h-5 w-5 text-green-500" />
              <span className="text-3xl font-bold">
                {agendamentosRisco.filter(a => a.acoes_tomadas?.length > 0).length}
              </span>
            </div>
          </CardContent>
        </Card>
      </div>

      {loading ? (
        <Card>
          <CardContent className="py-8 text-center text-muted-foreground">
            Carregando agendamentos...
          </CardContent>
        </Card>
      ) : agendamentosRisco.length === 0 ? (
        <Card>
          <CardContent className="py-8 text-center text-muted-foreground">
            Nenhum agendamento de risco no momento
          </CardContent>
        </Card>
      ) : (
        <div className="space-y-3">
          {agendamentosRisco.map((agendamento) => (
            <Card key={agendamento.id}>
              <CardContent className="py-4">
                <div className="flex items-start justify-between">
                  <div className="space-y-2 flex-1">
                    <div className="flex items-center gap-2">
                      {getScoreBadge(agendamento.score)}
                      <span className="font-medium">{agendamento.paciente?.nome}</span>
                    </div>

                    <div className="text-sm text-muted-foreground space-y-1">
                      <div className="flex items-center gap-2">
                        <Calendar className="h-4 w-4" />
                        {format(new Date(agendamento.inicio), "dd/MM/yyyy 'às' HH:mm", { locale: ptBR })}
                      </div>
                      <div>{agendamento.servico?.nome}</div>
                    </div>

                    {agendamento.acoes_tomadas && agendamento.acoes_tomadas.length > 0 && (
                      <div className="flex gap-2 flex-wrap">
                        {agendamento.acoes_tomadas.map((acao, idx) => (
                          <Badge key={idx} variant="outline" className="gap-1">
                            <CheckCircle className="h-3 w-3" />
                            {getAcaoLabel(acao)}
                          </Badge>
                        ))}
                      </div>
                    )}
                  </div>

                  <Button
                    size="sm"
                    onClick={() => calcularRisco(agendamento.id)}
                    disabled={calculando === agendamento.id}
                  >
                    {calculando === agendamento.id ? "Calculando..." : "Recalcular"}
                  </Button>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import { Loader2, Activity, Scale, Wrench, Scissors } from 'lucide-react';
import { useToast } from "@/components/ui/use-toast";

interface SegmentConfig {
    id: string;
    name: string;
    active: boolean;
    terminology: any;
}

export function SegmentManager() {
    const [segments, setSegments] = useState<SegmentConfig[]>([]);
    const [loading, setLoading] = useState(true);
    const { toast } = useToast();

    useEffect(() => {
        fetchSegments();
    }, []);

    const fetchSegments = async () => {
        setLoading(true);
        try {
            const { data, error } = await supabase
                .from('segment_configs')
                .select('*')
                .order('name');

            if (error) throw error;
            setSegments(data || []);
        } catch (error) {
            console.error("Error fetching segments:", error);
        } finally {
            setLoading(false);
        }
    };

    const toggleSegment = async (id: string, currentStatus: boolean) => {
        try {
            const { error } = await supabase
                .from('segment_configs')
                .update({ active: !currentStatus })
                .eq('id', id);

            if (error) throw error;

            setSegments(prev => prev.map(s => s.id === id ? { ...s, active: !currentStatus } : s));
            toast({
                title: !currentStatus ? "Segmento Ativado" : "Segmento Desativado",
                description: `O segmento agora está ${!currentStatus ? 'disponível' : 'indisponível'} para novos cadastros.`
            });
        } catch (error) {
            toast({
                title: "Erro ao atualizar",
                variant: "destructive"
            });
        }
    };

    const getIcon = (id: string) => {
        switch (id) {
            case 'saude': return <Activity className="h-5 w-5" />;
            case 'juridico': return <Scale className="h-5 w-5" />;
            case 'oficina': return <Wrench className="h-5 w-5" />;
            case 'beleza': return <Scissors className="h-5 w-5" />;
            default: return <Activity className="h-5 w-5" />;
        }
    };

    if (loading) return <div className="flex justify-center p-8"><Loader2 className="animate-spin" /></div>;

    return (
        <div className="space-y-6">
            <div>
                <h2 className="text-2xl font-bold">Gerenciar Segmentos de Atuação</h2>
                <p className="text-muted-foreground">Ative ou desative os ramos de atividade disponíveis na plataforma.</p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {segments.map(segment => (
                    <Card key={segment.id} className={!segment.active ? 'opacity-70 bg-muted/30' : ''}>
                        <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                            <div className="flex items-center gap-2">
                                {getIcon(segment.id)}
                                <CardTitle className="text-base font-medium">
                                    {segment.name}
                                </CardTitle>
                            </div>
                            <Switch
                                checked={segment.active}
                                onCheckedChange={() => toggleSegment(segment.id, segment.active)}
                            />
                        </CardHeader>
                        <CardContent>
                            <div className="flex items-center justify-between mt-2">
                                <Badge variant={segment.active ? 'default' : 'secondary'}>
                                    {segment.active ? 'Ativo' : 'Inativo'}
                                </Badge>
                                <span className="text-xs text-muted-foreground">ID: {segment.id}</span>
                            </div>
                            <CardDescription className="mt-2 text-xs">
                                Terminologia: {segment.terminology?.client_label} / {segment.terminology?.file_label}
                            </CardDescription>
                        </CardContent>
                    </Card>
                ))}
            </div>
        </div>
    );
}

import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
