import { Input } from "@/components/ui/input";
import { Plus, Edit, Search, UserPlus, KeyRound } from "lucide-react";
import { toast } from "sonner";
import { NewSupportUserDialog } from "./NewSupportUserDialog";
import { EditSupportUserDialog } from "./EditSupportUserDialog";

interface SupportUser {
  id: string;
  nome: string;
  email: string;
  telefone?: string;
  status: string;
  funcoes: string[];
  foto_url?: string;
  forcar_troca_senha: boolean;
  created_at: string;
}

export const SupportTeamManagement = () => {
  const [supportUsers, setSupportUsers] = useState<SupportUser[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [newDialogOpen, setNewDialogOpen] = useState(false);
  const [editDialogOpen, setEditDialogOpen] = useState(false);
  const [editingUserId, setEditingUserId] = useState<string | null>(null);

  useEffect(() => {
    loadSupportUsers();
  }, []);

  const loadSupportUsers = async () => {
    try {
      const { data, error } = await supabase
        .from("usuarios_suporte")
        .select("*")
        .order("created_at", { ascending: false });

      if (error) throw error;
      setSupportUsers(data || []);
    } catch (error) {
      console.error("Error loading support users:", error);
      toast.error("Erro ao carregar equipe de suporte");
    } finally {
      setLoading(false);
    }
  };

  const handleResetPassword = async (userId: string) => {
    try {
      await supabase.rpc("reset_support_user_password", {
        p_usuario_id: userId
      });

      toast.success("Instruções de reset de senha enviadas por email");
      loadSupportUsers();
    } catch (error: any) {
      console.error("Error resetting password:", error);
      toast.error(error.message || "Erro ao resetar senha");
    }
  };

  const toggleUserStatus = async (userId: string, currentStatus: string) => {
    try {
      const newStatus = currentStatus === 'ativo' ? 'suspenso' : 'ativo';
      const { error } = await supabase
        .from("usuarios_suporte")
        .update({ status: newStatus })
        .eq("id", userId);

      if (error) throw error;

      const { data: { user } } = await supabase.auth.getUser();
      if (user) {
        await supabase.from("support_actions_log").insert({
          support_user_id: user.id,
          action_type: "usuario_editado",
          target_type: "usuarios_suporte",
          target_id: userId,
          description: `Status do usuário alterado para ${newStatus}`,
        });
      }

      toast.success("Status atualizado com sucesso");
      loadSupportUsers();
    } catch (error) {
      console.error("Error updating status:", error);
      toast.error("Erro ao atualizar status");
    }
  };

  const filteredUsers = supportUsers.filter(user => 
    user.nome?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    user.email?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      <NewSupportUserDialog
        open={newDialogOpen}
        onOpenChange={setNewDialogOpen}
        onSuccess={loadSupportUsers}
      />

      <EditSupportUserDialog
        open={editDialogOpen}
        onOpenChange={setEditDialogOpen}
        userId={editingUserId || ""}
        onSuccess={loadSupportUsers}
      />

      <Card className="p-6">
        <div className="flex items-center justify-between mb-6">
          <h2 className="text-2xl font-bold">Usuários de Suporte</h2>
          <Button onClick={() => setNewDialogOpen(true)}>
            <UserPlus className="h-4 w-4 mr-2" />
            Novo Usuário
          </Button>
        </div>

        <div className="mb-4">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
            <Input
              placeholder="Buscar por nome ou email..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="pl-10"
            />
          </div>
        </div>

        {loading ? (
          <p className="text-center py-8 text-muted-foreground">Carregando...</p>
        ) : filteredUsers.length === 0 ? (
          <p className="text-center py-8 text-muted-foreground">Nenhum membro encontrado</p>
        ) : (
          <div className="space-y-2">
            {filteredUsers.map((user) => (
              <Card key={user.id} className="p-4">
                <div className="flex items-center justify-between">
                  <div className="flex-1">
                    <div className="flex items-center gap-2 mb-1">
                      <h3 className="font-semibold">{user.nome}</h3>
                      <Badge variant="outline">{user.funcoes.join(", ")}</Badge>
                      <Badge variant={user.status === 'ativo' ? "default" : "secondary"}>
                        {user.status}
                      </Badge>
                      {user.forcar_troca_senha && (
                        <Badge variant="destructive">Trocar Senha</Badge>
                      )}
                    </div>
                    <p className="text-sm text-muted-foreground">{user.email}</p>
                    {user.telefone && (
                      <p className="text-sm text-muted-foreground">{user.telefone}</p>
                    )}
                  </div>
                  <div className="flex gap-2">
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => handleResetPassword(user.id)}
                    >
                      <KeyRound className="h-4 w-4 mr-2" />
                      Reset Senha
                    </Button>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => {
                        setEditingUserId(user.id);
                        setEditDialogOpen(true);
                      }}
                    >
                      <Edit className="h-4 w-4 mr-2" />
                      Editar
                    </Button>
                    <Button
                      variant={user.status === 'ativo' ? "destructive" : "default"}
                      size="sm"
                      onClick={() => toggleUserStatus(user.id, user.status)}
                    >
                      {user.status === 'ativo' ? "Desativar" : "Ativar"}
                    </Button>
                  </div>
                </div>
              </Card>
            ))}
          </div>
        )}
      </Card>
    </>
  );
};

import { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Search, AlertCircle, Info, AlertTriangle, XCircle } from "lucide-react";

interface SystemLog {
  id: string;
  request_id: string;
  created_at: string;
  level: 'debug' | 'info' | 'warn' | 'error' | 'fatal';
  message: string;
  context: any;
  status_code: number | null;
  duration_ms: number | null;
  service: string | null;
}

export const SystemLogsViewer = () => {
  const [logs, setLogs] = useState<SystemLog[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [levelFilter, setLevelFilter] = useState<string>("all");
  const { toast } = useToast();

  useEffect(() => {
    loadLogs();

    // Refresh a cada 10 segundos
    const interval = setInterval(loadLogs, 10000);
    return () => clearInterval(interval);
  }, [levelFilter]);

  const loadLogs = async () => {
    try {
      let query = supabase
        .from('system_logs')
        .select('*')
        .order('created_at', { ascending: false })
        .limit(100);

      if (levelFilter !== 'all') {
        query = query.eq('level', levelFilter);
      }

      const { data, error } = await query;

      if (error) throw error;
      setLogs((data || []) as SystemLog[]);
    } catch (error: any) {
      toast({
        title: "Erro ao carregar logs",
        description: error.message,
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const getLevelIcon = (level: string) => {
    switch (level) {
      case 'debug':
      case 'info':
        return <Info className="h-4 w-4" />;
      case 'warn':
        return <AlertTriangle className="h-4 w-4" />;
      case 'error':
      case 'fatal':
        return <XCircle className="h-4 w-4" />;
      default:
        return <AlertCircle className="h-4 w-4" />;
    }
  };

  const getLevelVariant = (level: string): "default" | "secondary" | "destructive" | "outline" => {
    switch (level) {
      case 'error':
      case 'fatal':
        return 'destructive';
      case 'warn':
        return 'outline';
      case 'info':
        return 'default';
      default:
        return 'secondary';
    }
  };

  const filteredLogs = logs.filter(log =>
    log.message.toLowerCase().includes(searchTerm.toLowerCase()) ||
    log.request_id.toLowerCase().includes(searchTerm.toLowerCase()) ||
    (log.service && log.service.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  return (
    <Card>
      <CardHeader>
        <CardTitle>Logs do Sistema</CardTitle>
        <CardDescription>Logs estruturados com request-id para rastreamento</CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="flex gap-2">
          <div className="relative flex-1">
            <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
            <Input
              placeholder="Buscar logs..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="pl-8"
            />
          </div>
          <Select value={levelFilter} onValueChange={setLevelFilter}>
            <SelectTrigger className="w-[180px]">
              <SelectValue placeholder="Nível" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">Todos os níveis</SelectItem>
              <SelectItem value="debug">Debug</SelectItem>
              <SelectItem value="info">Info</SelectItem>
              <SelectItem value="warn">Warning</SelectItem>
              <SelectItem value="error">Error</SelectItem>
              <SelectItem value="fatal">Fatal</SelectItem>
            </SelectContent>
          </Select>
        </div>

        <ScrollArea className="h-[600px] w-full rounded-md border">
          <div className="space-y-2 p-4">
            {loading ? (
              <div className="text-center text-muted-foreground">Carregando logs...</div>
            ) : filteredLogs.length === 0 ? (
              <div className="text-center text-muted-foreground">Nenhum log encontrado</div>
            ) : (
              filteredLogs.map((log) => (
                <div
                  key={log.id}
                  className="rounded-lg border p-3 space-y-2 hover:bg-accent transition-colors"
                >
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                      {getLevelIcon(log.level)}
                      <Badge variant={getLevelVariant(log.level)}>
                        {log.level.toUpperCase()}
                      </Badge>
                      {log.service && (
                        <Badge variant="outline">{log.service}</Badge>
                      )}
                      {log.status_code && (
                        <Badge variant={log.status_code >= 400 ? 'destructive' : 'default'}>
                          {log.status_code}
                        </Badge>
                      )}
                    </div>
                    <div className="text-xs text-muted-foreground">
                      {new Date(log.created_at).toLocaleString('pt-BR')}
                    </div>
                  </div>

                  <div className="text-sm">{log.message}</div>

                  <div className="flex items-center gap-4 text-xs text-muted-foreground">
                    <span className="font-mono">Request ID: {log.request_id.substring(0, 8)}...</span>
                    {log.duration_ms && (
                      <span>Duração: {log.duration_ms}ms</span>
                    )}
                  </div>

                  {log.context && Object.keys(log.context).length > 0 && (
                    <details className="text-xs">
                      <summary className="cursor-pointer text-muted-foreground hover:text-foreground">
                        Ver contexto
                      </summary>
                      <pre className="mt-2 rounded bg-muted p-2 overflow-auto">
                        {JSON.stringify(log.context, null, 2)}
                      </pre>
                    </details>
                  )}
                </div>
              ))
            )}
          </div>
        </ScrollArea>
      </CardContent>
    </Card>
  );
};

import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Search, Eye, Edit, Plus, XCircle, CheckCircle, RefreshCw, ExternalLink } from "lucide-react";
import { toast } from "sonner";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { EditTenantDialog } from "./EditTenantDialog";
import { NewTenantDialog } from "./NewTenantDialog";
import { ChangeSegmentDialog } from "./ChangeSegmentDialog";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";

interface Tenant {
  id: string;
  nome: string;
  email: string;
  telefone: string;
  tipo: string;
  status?: string;
  created_at: string;
}

export const TenantManagement = () => {
  const [tenants, setTenants] = useState<Tenant[]>([]);
  const [filteredTenants, setFilteredTenants] = useState<Tenant[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [selectedTenant, setSelectedTenant] = useState<Tenant | null>(null);
  const [loading, setLoading] = useState(true);
  const [editDialogOpen, setEditDialogOpen] = useState(false);
  const [newDialogOpen, setNewDialogOpen] = useState(false);
  const [editingTenantId, setEditingTenantId] = useState<string | null>(null);
  const [suspendDialogOpen, setSuspendDialogOpen] = useState(false);
  const [suspendTenant, setSuspendTenant] = useState<Tenant | null>(null);
  const [suspendReason, setSuspendReason] = useState("");
  const [changeSegmentOpen, setChangeSegmentOpen] = useState(false);

  useEffect(() => {
    loadTenants();
  }, []);

  useEffect(() => {
    filterTenants();
  }, [tenants, searchTerm, statusFilter]);

  const loadTenants = async () => {
    try {
      const { data, error } = await supabase
        .from("tenants")
        .select("*")
        .order("created_at", { ascending: false });

      if (error) throw error;
      setTenants(data || []);
    } catch (error) {
      console.error("Error loading tenants:", error);
      toast.error("Erro ao carregar tenants");
    } finally {
      setLoading(false);
    }
  };

  const filterTenants = () => {
    let filtered = tenants;

    // Filter by status
    if (statusFilter !== "all") {
      filtered = filtered.filter(tenant => tenant.status === statusFilter);
    }

    // Filter by search term
    if (searchTerm) {
      filtered = filtered.filter(
        (tenant) =>
          tenant.nome.toLowerCase().includes(searchTerm.toLowerCase()) ||
          tenant.email?.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    setFilteredTenants(filtered);
  };

  const handleSuspendTenant = async () => {
    if (!suspendTenant || !suspendReason.trim()) {
      toast.error("Por favor, informe o motivo da suspensão");
      return;
    }

    try {
      const newStatus = suspendTenant.status === 'ativo' ? 'suspenso' : 'ativo';

      const { error } = await supabase
        .from("tenants")
        .update({ status: newStatus })
        .eq("id", suspendTenant.id);

      if (error) throw error;

      await logAction(
        "tenant_status_alterado",
        suspendTenant.id,
        `Tenant ${newStatus}: ${suspendReason}`
      );

      toast.success(`Tenant ${newStatus === 'ativo' ? 'reativado' : 'suspenso'} com sucesso`);
      setSuspendDialogOpen(false);
      setSuspendTenant(null);
      setSuspendReason("");
      loadTenants();
    } catch (error: any) {
      console.error("Error updating tenant status:", error);
      toast.error(error.message || "Erro ao atualizar status do tenant");
    }
  };

  const logAction = async (action: string, tenantId: string, description: string) => {
    const { data: { user } } = await supabase.auth.getUser();
    if (user) {
      await supabase.from("support_actions_log").insert({
        support_user_id: user.id,
        action_type: action,
        target_type: "tenant",
        target_id: tenantId,
        description,
      });
    }
  };

  return (
    <>
      <NewTenantDialog
        open={newDialogOpen}
        onOpenChange={setNewDialogOpen}
        onSuccess={loadTenants}
      />

      {editingTenantId && (
        <EditTenantDialog
          open={editDialogOpen}
          onOpenChange={setEditDialogOpen}
          tenantId={editingTenantId}
          onSuccess={loadTenants}
        />
      )}

      {selectedTenant && (
        <ChangeSegmentDialog
          open={changeSegmentOpen}
          onOpenChange={setChangeSegmentOpen}
          tenantId={selectedTenant.id}
          onSuccess={() => {
            loadTenants();
            setSelectedTenant(null);
          }}
        />
      )}

      {/* Suspend/Reactivate Dialog */}
      <Dialog open={suspendDialogOpen} onOpenChange={setSuspendDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>
              {suspendTenant?.status === 'ativo' ? 'Suspender' : 'Reativar'} Tenant
            </DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <Label>Tenant</Label>
              <p className="text-sm text-muted-foreground">{suspendTenant?.nome}</p>
            </div>
            <div>
              <Label htmlFor="reason">Motivo *</Label>
              <Textarea
                id="reason"
                value={suspendReason}
                onChange={(e) => setSuspendReason(e.target.value)}
                placeholder={`Informe o motivo da ${suspendTenant?.status === 'ativo' ? 'suspensão' : 'reativação'}...`}
                rows={4}
              />
            </div>
            <div className="flex justify-end gap-2">
              <Button variant="outline" onClick={() => setSuspendDialogOpen(false)}>
                Cancelar
              </Button>
              <Button
                variant={suspendTenant?.status === 'ativo' ? 'destructive' : 'default'}
                onClick={handleSuspendTenant}
              >
                {suspendTenant?.status === 'ativo' ? 'Suspender' : 'Reativar'}
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>

      <Card className="p-6">
        <div className="space-y-4">
          <div className="flex justify-between items-center">
            <h2 className="text-2xl font-bold">Tenants</h2>
            <Button onClick={() => setNewDialogOpen(true)}>
              <Plus className="h-4 w-4 mr-2" />
              Novo Tenant
            </Button>
          </div>

          <Tabs value={statusFilter} onValueChange={setStatusFilter} className="w-full">
            <TabsList>
              <TabsTrigger value="all">Todos</TabsTrigger>
              <TabsTrigger value="ativo">Ativos</TabsTrigger>
              <TabsTrigger value="suspenso">Suspensos</TabsTrigger>
              <TabsTrigger value="trial">Trial</TabsTrigger>
            </TabsList>
          </Tabs>

          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
            <Input
              placeholder="Buscar tenants..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="pl-10"
            />
          </div>

          {loading ? (
            <p className="text-center py-8 text-muted-foreground">Carregando...</p>
          ) : filteredTenants.length === 0 ? (
            <p className="text-center py-8 text-muted-foreground">Nenhum tenant encontrado</p>
          ) : (
            <div className="space-y-2">
              {filteredTenants.map((tenant) => (
                <Card key={tenant.id} className="p-4">
                  <div className="flex items-center justify-between">
                    <div className="flex-1">
                      <div className="flex items-center gap-2 mb-1">
                        <h3 className="font-semibold">{tenant.nome}</h3>
                        <Badge variant="outline">{tenant.tipo}</Badge>
                        <Badge variant={
                          tenant.status === 'ativo' ? 'default' :
                            tenant.status === 'suspenso' ? 'destructive' : 'secondary'
                        }>
                          {tenant.status || 'ativo'}
                        </Badge>
                      </div>
                      <p className="text-sm text-muted-foreground">{tenant.email}</p>
                      <p className="text-xs text-muted-foreground mt-1">
                        Criado em: {new Date(tenant.created_at).toLocaleDateString("pt-BR")}
                      </p>
                    </div>
                    <div className="flex gap-2">
                      <Button variant="outline" size="sm" onClick={() => setSelectedTenant(tenant)}>
                        <Eye className="h-4 w-4 mr-2" />
                        Detalhes
                      </Button>
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => {
                          setEditingTenantId(tenant.id);
                          setEditDialogOpen(true);
                        }}
                      >
                        <Edit className="h-4 w-4 mr-2" />
                        Editar
                      </Button>
                      <Button
                        variant={tenant.status === 'ativo' ? 'destructive' : 'default'}
                        size="sm"
                        onClick={() => {
                          setSuspendTenant(tenant);
                          setSuspendDialogOpen(true);
                        }}
                      >
                        {tenant.status === 'ativo' ? (
                          <><XCircle className="h-4 w-4 mr-2" />Suspender</>
                        ) : (
                          <><CheckCircle className="h-4 w-4 mr-2" />Reativar</>
                        )}
                      </Button>
                    </div>
                  </div>
                </Card>
              ))}
            </div>
          )}
        </div>
      </Card>

      <Dialog open={!!selectedTenant} onOpenChange={() => setSelectedTenant(null)}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle>Detalhes do Tenant</DialogTitle>
          </DialogHeader>
          {selectedTenant && (
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-sm font-medium">Nome</label>
                  <p className="text-sm text-muted-foreground">{selectedTenant.nome}</p>
                </div>
                <div>
                  <label className="text-sm font-medium">Tipo</label>
                  <p className="text-sm text-muted-foreground">{selectedTenant.tipo}</p>
                </div>
                <div>
                  <label className="text-sm font-medium">Email</label>
                  <p className="text-sm text-muted-foreground">{selectedTenant.email}</p>
                </div>
                <div>
                  <label className="text-sm font-medium">Telefone</label>
                  <p className="text-sm text-muted-foreground">{selectedTenant.telefone}</p>
                </div>
              </div>

              <div className="pt-4 border-t flex justify-end gap-2">
                <Button
                  variant="outline"
                  onClick={() => {
                    localStorage.setItem('support_impersonation_tenant_id', selectedTenant.id);
                    window.location.href = '/dashboard';
