              <SelectContent>
                <SelectItem value="all">Todas Origens</SelectItem>
                <SelectItem value="chat">Chat</SelectItem>
                <SelectItem value="email">Email</SelectItem>
                <SelectItem value="whatsapp">WhatsApp</SelectItem>
                <SelectItem value="manual">Manual</SelectItem>
              </SelectContent>
            </Select>
          </div>
        </div>

        {loading ? (
          <p className="text-center py-8 text-muted-foreground">Carregando...</p>
        ) : filteredTickets.length === 0 ? (
          <p className="text-center py-8 text-muted-foreground">Nenhum ticket encontrado</p>
        ) : (
          <div className="space-y-3">
            {filteredTickets.map((ticket) => (
              <Card key={ticket.id} className="p-4 hover:bg-muted/50 transition-colors cursor-pointer" onClick={() => setSelectedTicket(ticket)}>
                <div className="flex items-start justify-between gap-4">
                  <div className="flex-1">
                    <div className="flex items-center gap-2 mb-2 flex-wrap">
                      <Badge variant="outline">#{ticket.numero || ticket.id.slice(0, 8)}</Badge>
                      <h3 className="font-semibold">{ticket.titulo}</h3>
                      <Badge variant={getPriorityColor(ticket.prioridade)}>{ticket.prioridade}</Badge>
                      <Badge variant={getStatusColor(ticket.status)}>{ticket.status}</Badge>
                      {ticket.origem && <Badge variant="secondary">{ticket.origem}</Badge>}
                      <SLAIndicator sla={ticket.sla || {}} status={ticket.status} />
                    </div>
                    <p className="text-sm text-muted-foreground line-clamp-2">{ticket.descricao}</p>

                    {ticket.tags && ticket.tags.length > 0 && (
                      <div className="flex items-center gap-2 mt-2 flex-wrap">
                        {ticket.tags.map((tag) => (
                          <Badge key={tag} variant="outline" className="text-xs">
                            <Tag className="h-3 w-3 mr-1" />
                            {tag}
                          </Badge>
                        ))}
                      </div>
                    )}

                    <p className="text-xs text-muted-foreground mt-2">
                      {new Date(ticket.created_at).toLocaleString("pt-BR")}
                    </p>
                  </div>
                  <Button variant="ghost" size="sm">
                    <MessageSquare className="h-4 w-4" />
                  </Button>
                </div>
              </Card>
            ))}
          </div>
        )}
      </div>
    </Card>
  );
};

import { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { Button } from "@/components/ui/button";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import { Shield, CheckCircle2, XCircle } from "lucide-react";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";

interface TwoFactorSettings {
  id: string;
  enabled: boolean;
  method: 'totp' | 'sms' | 'email' | null;
  verified_at: string | null;
}

export const TwoFactorSettings = () => {
  const [settings, setSettings] = useState<TwoFactorSettings | null>(null);
  const [loading, setLoading] = useState(true);
  const [updating, setUpdating] = useState(false);
  const { toast } = useToast();

  useEffect(() => {
    loadSettings();
  }, []);

  const loadSettings = async () => {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      const { data, error } = await supabase
        .from('user_2fa_settings')
        .select('*')
        .eq('user_id', user.id)
        .maybeSingle();

      if (error) throw error;

      if (data) {
        setSettings(data as TwoFactorSettings);
      } else {
        // Criar configuração padrão (usando upsert para evitar duplicidade)
        const { data: newSettings, error: insertError } = await supabase
          .from('user_2fa_settings')
          .upsert({
            user_id: user.id,
            enabled: false,
            method: null,
          }, { onConflict: 'user_id' })
          .select()
          .single();

        if (insertError) throw insertError;
        setSettings(newSettings as TwoFactorSettings);
      }
    } catch (error: any) {
      toast({
        title: "Erro ao carregar configurações",
        description: error.message,
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const handleToggle2FA = async (enabled: boolean) => {
    if (!settings) return;

    try {
      setUpdating(true);

      // Verificar se usuário é master ou admin
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error("Usuário não autenticado");

      const { data: systemUser } = await supabase
        .from('system_users')
        .select('system_role')
        .eq('id', user.id)
        .maybeSingle();

      if (!systemUser || !['master', 'support'].includes(systemUser.system_role)) {
        toast({
          title: "Acesso negado",
          description: "2FA está disponível apenas para usuários Master e Admin",
          variant: "destructive",
        });
        return;
      }

      const { error } = await supabase
        .from('user_2fa_settings')
        .update({
          enabled,
          method: enabled ? 'totp' : null,
          verified_at: enabled ? new Date().toISOString() : null,
        })
        .eq('id', settings.id);

      if (error) throw error;

      toast({
        title: enabled ? "2FA Ativado" : "2FA Desativado",
        description: enabled
          ? "Autenticação de dois fatores foi ativada com sucesso"
          : "Autenticação de dois fatores foi desativada",
      });

      loadSettings();
    } catch (error: any) {
      toast({
        title: "Erro ao atualizar 2FA",
        description: error.message,
        variant: "destructive",
      });
    } finally {
      setUpdating(false);
    }
  };

  if (loading) {
    return <div className="p-4">Carregando configurações...</div>;
  }

  return (
    <Card>
      <CardHeader>
        <div className="flex items-center gap-2">
          <Shield className="h-5 w-5" />
          <CardTitle>Autenticação de Dois Fatores (2FA)</CardTitle>
        </div>
        <CardDescription>
          Adicione uma camada extra de segurança à sua conta
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-6">
        <Alert>
          <Shield className="h-4 w-4" />
          <AlertTitle>Segurança Avançada</AlertTitle>
          <AlertDescription>
            A autenticação de dois fatores está disponível para usuários Master e Admin.
            Quando ativada, será necessário um código adicional para fazer login.
          </AlertDescription>
        </Alert>

        <div className="flex items-center justify-between space-x-2">
          <div className="flex-1 space-y-1">
            <Label htmlFor="2fa-toggle" className="text-base">
              Ativar 2FA
            </Label>
            <p className="text-sm text-muted-foreground">
              {settings?.enabled
                ? "2FA está ativo e protegendo sua conta"
                : "2FA está desativado"}
            </p>
          </div>
          <Switch
            id="2fa-toggle"
            checked={settings?.enabled || false}
            onCheckedChange={handleToggle2FA}
            disabled={updating}
          />
        </div>

        {settings?.enabled && (
          <div className="space-y-4">
            <div className="flex items-center gap-2 text-sm">
              <CheckCircle2 className="h-4 w-4 text-green-500" />
              <span className="text-green-600 dark:text-green-400">
                Verificado em: {new Date(settings.verified_at!).toLocaleString('pt-BR')}
              </span>
            </div>

            <div className="rounded-lg border p-4 space-y-2">
              <h4 className="font-semibold">Método: TOTP (Time-based One-Time Password)</h4>
              <p className="text-sm text-muted-foreground">
                Use um aplicativo autenticador como Google Authenticator ou Authy para gerar códigos.
              </p>
            </div>
          </div>
        )}

        {!settings?.enabled && (
          <Alert>
            <XCircle className="h-4 w-4" />
            <AlertTitle>2FA Desativado</AlertTitle>
            <AlertDescription>
              Recomendamos fortemente ativar a autenticação de dois fatores para proteger sua conta.
            </AlertDescription>
          </Alert>
        )}
      </CardContent>
    </Card>
  );
};

import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Plus, Edit, Trash2 } from "lucide-react";
import { toast } from "sonner";
import { ProviderDialog } from "./ProviderDialog";
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from "@/components/ui/table";

interface Provider {
    id: string;
    name: string;
    api_config: any;
    cost_per_number_monthly: number;
    cost_per_message: number;
    status: string;
    updated_at: string;
}

interface VirtualNumberProvidersProps {
    isMaster: boolean;
}

export const VirtualNumberProviders = ({ isMaster }: VirtualNumberProvidersProps) => {
    const [providers, setProviders] = useState<Provider[]>([]);
    const [loading, setLoading] = useState(true);
    const [dialogOpen, setDialogOpen] = useState(false);
    const [editingProvider, setEditingProvider] = useState<Provider | null>(null);

    useEffect(() => {
        loadProviders();
    }, []);

    const loadProviders = async () => {
        try {
            const { data, error } = await supabase
                .from("virtual_number_providers")
                .select("*")
                .order("name");

            if (error) throw error;
            setProviders(data || []);
        } catch (error) {
            console.error("Error loading providers:", error);
            toast.error("Erro ao carregar provedores");
        } finally {
            setLoading(false);
        }
    };

    const handleDelete = async (id: string) => {
        if (!isMaster) {
            toast.error("Apenas usuários Master podem excluir provedores.");
            return;
        }
        if (!confirm("Tem certeza que deseja excluir este provedor?")) return;

        try {
            const { error } = await supabase
                .from("virtual_number_providers")
                .delete()
                .eq("id", id);

            if (error) throw error;
            toast.success("Provedor excluído com sucesso");
            loadProviders();
        } catch (error) {
            console.error("Error deleting provider:", error);
            toast.error("Erro ao excluir provedor");
        }
    };

    return (
        <>
            <ProviderDialog
                open={dialogOpen}
                onOpenChange={setDialogOpen}
                onSuccess={loadProviders}
                editingProvider={editingProvider}
                isMaster={isMaster}
            />

            <Card className="p-6">
                <div className="flex items-center justify-between mb-6">
                    <div>
                        <h2 className="text-2xl font-bold">Provedores de Números Virtuais</h2>
                        <p className="text-muted-foreground">Gerencie as integrações e custos dos provedores.</p>
                    </div>
                    <Button onClick={() => {
                        setEditingProvider(null);
                        setDialogOpen(true);
                    }}>
                        <Plus className="h-4 w-4 mr-2" />
                        Novo Provedor
                    </Button>
                </div>

                {loading ? (
                    <p className="text-center py-8 text-muted-foreground">Carregando...</p>
                ) : providers.length === 0 ? (
                    <p className="text-center py-8 text-muted-foreground">Nenhum provedor cadastrado</p>
                ) : (
                    <div className="rounded-md border">
                        <Table>
                            <TableHeader>
                                <TableRow>
                                    <TableHead>Provedor</TableHead>
                                    <TableHead>Custo/Número/Mês</TableHead>
                                    <TableHead>Custo/Mensagem</TableHead>
                                    <TableHead>Status</TableHead>
                                    <TableHead className="text-right">Ações</TableHead>
                                </TableRow>
                            </TableHeader>
                            <TableBody>
                                {providers.map((provider) => (
                                    <TableRow key={provider.id}>
                                        <TableCell className="font-medium">{provider.name}</TableCell>
                                        <TableCell>R$ {provider.cost_per_number_monthly.toFixed(2)}</TableCell>
                                        <TableCell>R$ {provider.cost_per_message.toFixed(4)}</TableCell>
                                        <TableCell>
                                            <Badge variant={provider.status === 'active' ? 'default' : 'secondary'}>
                                                {provider.status === 'active' ? 'Ativo' : 'Inativo'}
                                            </Badge>
                                        </TableCell>
                                        <TableCell className="text-right">
                                            <div className="flex justify-end gap-2">
                                                <Button
                                                    variant="ghost"
                                                    size="icon"
                                                    onClick={() => {
                                                        setEditingProvider(provider);
                                                        setDialogOpen(true);
                                                    }}
                                                >
                                                    <Edit className="h-4 w-4" />
                                                </Button>
                                                <Button
                                                    variant="ghost"
                                                    size="icon"
                                                    className="text-destructive hover:text-destructive"
                                                    onClick={() => handleDelete(provider.id)}
                                                >
                                                    <Trash2 className="h-4 w-4" />
                                                </Button>
                                            </div>
                                        </TableCell>
                                    </TableRow>
                                ))}
                            </TableBody>
                        </Table>
                    </div>
                )}
            </Card>
        </>
    );
};

import { useState, useEffect } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { AlertTriangle, Bell, CheckCircle, XCircle } from 'lucide-react';
import { toast } from 'sonner';
import { formatDistanceToNow } from 'date-fns';
import { ptBR } from 'date-fns/locale';

interface WhatsAppAlarm {
  id: string;
  tenant_id: string | null;
  alarm_type: string;
  threshold_value: number;
  current_value: number;
  status: 'active' | 'acknowledged' | 'resolved';
  triggered_at: string;
  acknowledged_at: string | null;
  resolved_at: string | null;
  message: string;
  severity: 'warning' | 'error' | 'critical';
  metadata: any;
}

export function WhatsAppAlarms() {
  const [alarms, setAlarms] = useState<WhatsAppAlarm[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadAlarms();
    // Atualizar a cada 15 segundos
    const interval = setInterval(loadAlarms, 15000);
    return () => clearInterval(interval);
  }, []);

  const loadAlarms = async () => {
    try {
      const { data, error } = await supabase
        .from('whatsapp_alarms' as any)
        .select('*')
        .order('triggered_at', { ascending: false })
        .limit(50);

      if (error) throw error;
      setAlarms(data as any || []);
    } catch (error: any) {
      console.error('Error loading alarms:', error);
      toast.error('Erro ao carregar alarmes');
    } finally {
      setLoading(false);
    }
  };

  const handleAcknowledge = async (alarmId: string) => {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error('Not authenticated');

      const { data: supportUser } = await supabase
        .from('usuarios_suporte' as any)
        .select('id')
        .eq('auth_user_id', user.id)
        .single() as any;

      const { error } = await supabase
        .from('whatsapp_alarms' as any)
        .update({
          status: 'acknowledged',
          acknowledged_at: new Date().toISOString(),
          acknowledged_by: supportUser?.id
        })
        .eq('id', alarmId);

      if (error) throw error;

      toast.success('Alarme reconhecido');
      loadAlarms();
    } catch (error: any) {
      console.error('Error acknowledging alarm:', error);
      toast.error('Erro ao reconhecer alarme');
    }
  };

  const handleResolve = async (alarmId: string) => {
    try {
      const { error } = await supabase
        .from('whatsapp_alarms' as any)
        .update({
          status: 'resolved',
          resolved_at: new Date().toISOString()
        })
        .eq('id', alarmId);

      if (error) throw error;

      toast.success('Alarme resolvido');
      loadAlarms();
    } catch (error: any) {
      console.error('Error resolving alarm:', error);
      toast.error('Erro ao resolver alarme');
    }
  };

  const getSeverityBadge = (severity: string) => {
    const variants = {
      warning: 'secondary',
      error: 'destructive',
      critical: 'destructive'
    };

    const icons = {
      warning: AlertTriangle,
      error: XCircle,
      critical: Bell
    };

    const Icon = icons[severity as keyof typeof icons];

    return (
      <Badge variant={variants[severity as keyof typeof variants] as any} className="flex items-center gap-1">
        <Icon className="h-3 w-3" />
        {severity.toUpperCase()}
      </Badge>
    );
  };

  const getStatusBadge = (status: string) => {
    const variants = {
      active: 'destructive',
      acknowledged: 'secondary',
      resolved: 'default'
    };

    return (
      <Badge variant={variants[status as keyof typeof variants] as any}>
        {status === 'active' && 'Ativo'}
        {status === 'acknowledged' && 'Reconhecido'}
        {status === 'resolved' && 'Resolvido'}
      </Badge>
    );
  };

  const getAlarmTypeLabel = (type: string) => {
    const labels: Record<string, string> = {
      error_rate: 'Taxa de Erro',
      template_rejection: 'Rejeição de Template',
      quality_rating: 'Quality Rating',
      rate_limit: 'Rate Limit',
      delivery_failure: 'Falha de Entrega'
    };
    return labels[type] || type;
  };

  if (loading) {
    return <div>Carregando alarmes...</div>;
  }

  const activeAlarms = alarms.filter(a => a.status === 'active').length;

  return (
    <div className="space-y-6">
      <div className="grid gap-4 md:grid-cols-3">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Alarmes Ativos</CardTitle>
            <Bell className="h-4 w-4 text-destructive" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{activeAlarms}</div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Reconhecidos</CardTitle>
            <CheckCircle className="h-4 w-4 text-secondary" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">
              {alarms.filter(a => a.status === 'acknowledged').length}
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Resolvidos (24h)</CardTitle>
            <CheckCircle className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">
              {alarms.filter(a => a.status === 'resolved').length}
            </div>
          </CardContent>
        </Card>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Lista de Alarmes</CardTitle>
          <CardDescription>Monitoramento em tempo real de alarmes do WhatsApp</CardDescription>
        </CardHeader>
        <CardContent>
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Tipo</TableHead>
                <TableHead>Mensagem</TableHead>
                <TableHead>Severidade</TableHead>
                <TableHead>Status</TableHead>
                <TableHead>Disparado</TableHead>
                <TableHead>Ações</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {alarms.map((alarm) => (
                <TableRow key={alarm.id}>
                  <TableCell>{getAlarmTypeLabel(alarm.alarm_type)}</TableCell>
                  <TableCell className="max-w-xs">
                    <div>{alarm.message}</div>
                    <div className="text-xs text-muted-foreground mt-1">
                      Limite: {alarm.threshold_value} | Atual: {alarm.current_value}
                    </div>
                  </TableCell>
                  <TableCell>{getSeverityBadge(alarm.severity)}</TableCell>
                  <TableCell>{getStatusBadge(alarm.status)}</TableCell>
                  <TableCell>
                    {formatDistanceToNow(new Date(alarm.triggered_at), {
                      addSuffix: true,
                      locale: ptBR
                    })}
                  </TableCell>
                  <TableCell>
                    <div className="flex gap-2">
                      {alarm.status === 'active' && (
                        <Button
                          size="sm"
                          variant="outline"
                          onClick={() => handleAcknowledge(alarm.id)}
                        >
                          Reconhecer
                        </Button>
                      )}
                      {alarm.status !== 'resolved' && (
                        <Button
                          size="sm"
                          onClick={() => handleResolve(alarm.id)}
                        >
                          Resolver
                        </Button>
                      )}
                    </div>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </CardContent>
      </Card>
    </div>
  );
}

