          <ol className="text-sm text-blue-800 dark:text-blue-200 space-y-1 list-decimal list-inside">
            <li>Acesse o Meta Business Suite</li>
            <li>Vá em WhatsApp Manager</li>
            <li>Selecione seu número de telefone</li>
            <li>Copie o Phone Number ID e Business Account ID</li>
            <li>Cole aqui e clique em Salvar</li>
          </ol>
        </div>
      </CardContent>
    </Card>
  );
}

import { useState } from "react";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Button } from "@/components/ui/button";
import { Phone, Clock, MessageSquare } from "lucide-react";
import { formatDistanceToNow } from "date-fns";
import { ptBR } from "date-fns/locale";

interface Conversation {
  id: string;
  telefone: string;
  paciente_nome?: string;
  status: string;
  ultima_mensagem?: string;
  ultima_mensagem_em?: string;
  mensagens_nao_lidas?: number;
  created_at: string;
}

interface WhatsAppConversationListProps {
  conversations: Conversation[];
  selectedConversationId?: string;
  onSelectConversation: (conversationId: string) => void;
  onTakeConversation?: (conversationId: string) => void;
}

export function WhatsAppConversationList({
  conversations,
  selectedConversationId,
  onSelectConversation,
  onTakeConversation,
}: WhatsAppConversationListProps) {
  const [statusFilter, setStatusFilter] = useState<string>("all");

  const filteredConversations = conversations.filter((conv) => {
    if (statusFilter === "all") return true;
    return conv.status === statusFilter;
  });

  const getStatusBadge = (status: string) => {
    const variants: Record<string, { variant: any; label: string }> = {
      aguardando: { variant: "default", label: "Aguardando" },
      em_atendimento: { variant: "secondary", label: "Em Atendimento" },
      resolvido: { variant: "outline", label: "Resolvido" },
    };

    const config = variants[status] || { variant: "outline", label: status };
    return (
      <Badge variant={config.variant} className="text-xs">
        {config.label}
      </Badge>
    );
  };

  return (
    <div className="flex flex-col h-full">
      <div className="p-4 border-b">
        <h3 className="font-semibold mb-3">Conversas WhatsApp</h3>
        <div className="flex gap-2">
          <Button
            size="sm"
            variant={statusFilter === "all" ? "default" : "outline"}
            onClick={() => setStatusFilter("all")}
          >
            Todas
          </Button>
          <Button
            size="sm"
            variant={statusFilter === "aguardando" ? "default" : "outline"}
            onClick={() => setStatusFilter("aguardando")}
          >
            Aguardando
          </Button>
          <Button
            size="sm"
            variant={statusFilter === "em_atendimento" ? "default" : "outline"}
            onClick={() => setStatusFilter("em_atendimento")}
          >
            Ativas
          </Button>
        </div>
      </div>

      <ScrollArea className="flex-1">
        <div className="p-2 space-y-2">
          {filteredConversations.map((conversation) => (
            <Card
              key={conversation.id}
              className={`p-4 cursor-pointer transition-all hover:shadow-md ${
                selectedConversationId === conversation.id
                  ? "border-primary bg-accent"
                  : ""
              }`}
              onClick={() => onSelectConversation(conversation.id)}
            >
              <div className="flex items-start justify-between mb-2">
                <div className="flex items-center gap-2">
                  <Phone className="h-4 w-4 text-muted-foreground" />
                  <div>
                    <p className="font-medium">
                      {conversation.paciente_nome || conversation.telefone}
                    </p>
                    {conversation.paciente_nome && (
                      <p className="text-xs text-muted-foreground">
                        {conversation.telefone}
                      </p>
                    )}
                  </div>
                </div>
                {getStatusBadge(conversation.status)}
              </div>

              {conversation.ultima_mensagem && (
                <p className="text-sm text-muted-foreground line-clamp-2 mb-2">
                  {conversation.ultima_mensagem}
                </p>
              )}

              <div className="flex items-center justify-between text-xs text-muted-foreground">
                <div className="flex items-center gap-1">
                  <Clock className="h-3 w-3" />
                  {conversation.ultima_mensagem_em
                    ? formatDistanceToNow(new Date(conversation.ultima_mensagem_em), {
                        addSuffix: true,
                        locale: ptBR,
                      })
                    : formatDistanceToNow(new Date(conversation.created_at), {
                        addSuffix: true,
                        locale: ptBR,
                      })}
                </div>
                {conversation.mensagens_nao_lidas > 0 && (
                  <Badge variant="destructive" className="h-5 w-5 p-0 flex items-center justify-center">
                    {conversation.mensagens_nao_lidas}
                  </Badge>
                )}
              </div>

              {conversation.status === "aguardando" && onTakeConversation && (
                <Button
                  size="sm"
                  className="w-full mt-3"
                  onClick={(e) => {
                    e.stopPropagation();
                    onTakeConversation(conversation.id);
                  }}
                >
                  <MessageSquare className="h-4 w-4 mr-2" />
                  Assumir Conversa
                </Button>
              )}
            </Card>
          ))}

          {filteredConversations.length === 0 && (
            <div className="text-center py-8 text-muted-foreground">
              <MessageSquare className="h-12 w-12 mx-auto mb-2 opacity-50" />
              <p>Nenhuma conversa encontrada</p>
            </div>
          )}
        </div>
      </ScrollArea>
    </div>
  );
}

import { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";
import { CreditCard, AlertTriangle, CheckCircle, TrendingUp } from "lucide-react";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";

interface CreditPackage {
  id: string;
  nome: string;
  descricao: string;
  quantidade_creditos: number;
  preco_venda: number;
  markup_percentual: number;
  destaque: boolean;
}

export function WhatsAppCredits() {
  const [credits, setCredits] = useState<any>(null);
  const [packages, setPackages] = useState<CreditPackage[]>([]);
  const [loading, setLoading] = useState(false);
  const [selectedPackage, setSelectedPackage] = useState<CreditPackage | null>(null);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      const { data: profile } = await supabase
        .from('profiles')
        .select('tenant_id')
        .eq('id', user.id)
        .single();

      if (!profile) return;

      // Carregar saldo de créditos
      const { data: creditsData } = await supabase
        .from('tenant_whatsapp_credits' as any)
        .select('*')
        .eq('tenant_id', profile.tenant_id)
        .single();

      setCredits(creditsData);

      // Carregar pacotes disponíveis
      const { data: packagesData } = await supabase
        .from('credit_packages' as any)
        .select('*')
        .eq('ativo', true)
        .order('quantidade_creditos', { ascending: true });

      setPackages((packagesData || []) as any);
    } catch (error) {
      console.error('Erro ao carregar dados:', error);
    }
  };

  const handlePurchase = async (packageId: string) => {
    setLoading(true);
    try {
      const { data, error } = await supabase.functions.invoke('comprar-creditos-stripe', {
        body: { package_id: packageId }
      });

      if (error) throw error;

      if (data?.url) {
        window.open(data.url, '_blank');
        toast.success("Redirecionando para o pagamento...");
        setSelectedPackage(null);
      }
    } catch (error: any) {
      toast.error('Erro na compra: ' + error.message);
    } finally {
      setLoading(false);
    }
  };

  const getCreditStatus = () => {
    if (!credits) return 'unknown';
    if (credits.saldo_creditos === 0) return 'empty';
    if (credits.saldo_creditos <= credits.limiar_alerta) return 'low';
    return 'good';
  };

  const statusConfig = {
    good: { color: 'bg-green-500', icon: CheckCircle, text: 'Saldo adequado' },
    low: { color: 'bg-yellow-500', icon: AlertTriangle, text: 'Saldo baixo' },
    empty: { color: 'bg-red-500', icon: AlertTriangle, text: 'Sem créditos' },
    unknown: { color: 'bg-gray-500', icon: CreditCard, text: 'Carregando...' }
  };

  const status = getCreditStatus();
  const StatusIcon = statusConfig[status].icon;

  return (
    <div className="space-y-6">
      {/* Saldo Atual */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <CreditCard className="h-5 w-5" />
            Créditos WhatsApp
          </CardTitle>
          <CardDescription>
            Seu saldo atual de mensagens
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="flex items-center justify-between">
            <div>
              <div className="text-4xl font-bold">
                {credits?.saldo_creditos?.toLocaleString('pt-BR') || '0'}
              </div>
              <p className="text-sm text-muted-foreground mt-1">
                mensagens disponíveis
              </p>
            </div>
            <div className="flex items-center gap-2">
              <StatusIcon className={`h-8 w-8 ${statusConfig[status].color.replace('bg-', 'text-')}`} />
              <span className="text-sm">{statusConfig[status].text}</span>
            </div>
          </div>

          {credits && (
            <div className="mt-4 grid grid-cols-2 gap-4 text-sm">
              <div>
                <span className="text-muted-foreground">Total consumido:</span>
                <span className="ml-2 font-medium">
                  {credits.creditos_consumidos.toLocaleString('pt-BR')}
                </span>
              </div>
              <div>
                <span className="text-muted-foreground">Último uso:</span>
                <span className="ml-2 font-medium">
                  {credits.ultimo_consumo_at 
                    ? new Date(credits.ultimo_consumo_at).toLocaleDateString('pt-BR')
                    : 'Nunca'
                  }
                </span>
              </div>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Pacotes Disponíveis */}
      <div>
        <h3 className="text-lg font-semibold mb-4">Comprar Créditos</h3>
        <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
          {packages.map((pkg) => (
            <Card key={pkg.id} className={pkg.destaque ? 'border-primary' : ''}>
              <CardHeader>
                <div className="flex items-center justify-between">
                  <CardTitle className="text-lg">{pkg.nome}</CardTitle>
                  {pkg.destaque && (
                    <Badge variant="default">
                      <TrendingUp className="h-3 w-3 mr-1" />
                      Popular
                    </Badge>
                  )}
                </div>
                <CardDescription>{pkg.descricao}</CardDescription>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="text-center">
                  <div className="text-3xl font-bold">
                    {pkg.quantidade_creditos.toLocaleString('pt-BR')}
                  </div>
                  <p className="text-sm text-muted-foreground">mensagens</p>
                </div>

                <div className="text-center">
                  <div className="text-2xl font-bold text-primary">
                    R$ {pkg.preco_venda.toFixed(2)}
                  </div>
                  <p className="text-xs text-muted-foreground">
                    R$ {(pkg.preco_venda / pkg.quantidade_creditos).toFixed(4)} por mensagem
                  </p>
                </div>

                <Dialog>
                  <DialogTrigger asChild>
                    <Button 
                      className="w-full"
                      variant={pkg.destaque ? 'default' : 'outline'}
                      onClick={() => setSelectedPackage(pkg)}
                    >
                      Comprar Agora
                    </Button>
                  </DialogTrigger>
                  <DialogContent>
                    <DialogHeader>
                      <DialogTitle>Confirmar Compra</DialogTitle>
                      <DialogDescription>
                        Você está prestes a comprar {pkg.quantidade_creditos.toLocaleString('pt-BR')} créditos
                      </DialogDescription>
                    </DialogHeader>
                    <div className="space-y-4">
                      <div className="bg-muted p-4 rounded-lg">
                        <div className="flex justify-between mb-2">
                          <span>Pacote:</span>
                          <span className="font-medium">{pkg.nome}</span>
                        </div>
                        <div className="flex justify-between mb-2">
                          <span>Créditos:</span>
                          <span className="font-medium">
                            {pkg.quantidade_creditos.toLocaleString('pt-BR')}
                          </span>
                        </div>
                        <div className="flex justify-between text-lg font-bold border-t pt-2 mt-2">
                          <span>Total:</span>
                          <span>R$ {pkg.preco_venda.toFixed(2)}</span>
                        </div>
                      </div>
                      <Button 
                        className="w-full" 
                        onClick={() => handlePurchase(pkg.id)}
                        disabled={loading}
                      >
                        {loading ? 'Processando...' : 'Confirmar Compra'}
                      </Button>
                    </div>
                  </DialogContent>
                </Dialog>
              </CardContent>
            </Card>
          ))}
        </div>
      </div>
    </div>
  );
}

import { useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { whatsappService } from "@/domain/whatsapp/whatsappService";

interface ProcessedIntent {
  type: "confirmacao" | "cancelamento" | "remarcacao" | "duvida" | "outro";
  confidence: number;
  agendamento_id?: string;
}

export function useWhatsAppIntentProcessor() {
  const detectIntent = (mensagem: string): ProcessedIntent => {
    const texto = mensagem.toLowerCase().trim();

    // Palavras-chave para confirmação
    const confirmacoesKeywords = [
      "sim", "confirmo", "confirmado", "ok", "tudo bem", "pode ser",
      "beleza", "confirmar", "estarei lá", "vou sim", "presente"
    ];

    // Palavras-chave para cancelamento
    const cancelamentosKeywords = [
      "não", "cancelar", "desmarcar", "não posso", "não vou",
      "não consigo", "preciso cancelar", "desejo cancelar"
    ];

    // Palavras-chave para remarcação
    const remarcacaoKeywords = [
      "remarcar", "trocar", "mudar", "outro dia", "outra data",
      "outro horário", "transferir"
    ];

    // Detecção de confirmação
    if (confirmacoesKeywords.some(keyword => texto.includes(keyword))) {
      return {
        type: "confirmacao",
        confidence: 0.9,
      };
    }

    // Detecção de cancelamento
    if (cancelamentosKeywords.some(keyword => texto.includes(keyword))) {
      return {
        type: "cancelamento",
        confidence: 0.85,
      };
    }

    // Detecção de remarcação
    if (remarcacaoKeywords.some(keyword => texto.includes(keyword))) {
      return {
        type: "remarcacao",
        confidence: 0.8,
      };
    }

    // Detecção de dúvida
    if (texto.includes("?") || texto.includes("dúvida") || texto.includes("informação")) {
      return {
        type: "duvida",
        confidence: 0.7,
      };
    }

    return {
      type: "outro",
      confidence: 0.5,
    };
  };

  const processIntent = async (
    conversationId: string,
    mensagem: string,
    tenantId: string
  ) => {
    const intent = detectIntent(mensagem);

    // Buscar agendamento relacionado
    const { data: conversation } = await supabase
      .from("whatsapp_conversations")
      .select(`
        paciente_id,
        metadata
      `)
      .eq("id", conversationId)
      .single();

    if (!conversation) return;

    const agendamentoId = (conversation.metadata as any)?.agendamento_id;

    // Processar baseado na intenção
    switch (intent.type) {
      case "confirmacao":
        if (agendamentoId) {
          await handleConfirmacao(agendamentoId, conversationId, tenantId);
        }
        break;

      case "cancelamento":
        if (agendamentoId) {
          await handleCancelamento(agendamentoId, conversationId, tenantId);
        }
        break;

      case "remarcacao":
        if (agendamentoId) {
          await handleRemarcacao(agendamentoId, conversationId, tenantId);
        }
        break;

      case "duvida":
        await handleDuvida(conversationId, tenantId);
        break;
    }

    return intent;
  };

  const handleConfirmacao = async (
    agendamentoId: string,
    conversationId: string,
    tenantId: string
  ) => {
    try {
      // Atualizar agendamento
      const { error } = await supabase
        .from("agenda")
        .update({
          confirmado: true,
          confirmado_em: new Date().toISOString(),
        })
        .eq("id", agendamentoId);

      if (error) throw error;

      // Enviar mensagem de resposta automática
      await enviarRespostaAutomatica(
        conversationId,
        "✅ Sua consulta foi confirmada com sucesso! Aguardamos você no dia e horário agendados.",
        tenantId
      );

      toast.success("Consulta confirmada automaticamente");
    } catch (error) {
      console.error("Erro ao processar confirmação:", error);
    }
  };

  const handleCancelamento = async (
    agendamentoId: string,
    conversationId: string,
    tenantId: string
  ) => {
    try {
      // Atualizar status do agendamento
      const { error } = await supabase
        .from("agenda")
        .update({
          status: "cancelado",
        })
        .eq("id", agendamentoId);

      if (error) throw error;

      await enviarRespostaAutomatica(
        conversationId,
        "Sua consulta foi cancelada. Se precisar reagendar, entre em contato conosco.",
        tenantId
      );

      toast.info("Consulta cancelada automaticamente");
    } catch (error) {
      console.error("Erro ao processar cancelamento:", error);
    }
  };

  const handleRemarcacao = async (
    agendamentoId: string,
    conversationId: string,
    tenantId: string
  ) => {
    try {
      await enviarRespostaAutomatica(
        conversationId,
        "Entendo que você precisa remarcar. Nossa equipe entrará em contato em breve para agendar uma nova data. 📅",
        tenantId
      );

      // Criar alerta para equipe (atualizar metadata da conversa)
      const { data: conv } = await supabase
        .from("whatsapp_conversations")
        .select("metadata")
        .eq("id", conversationId)
        .single();

      await supabase.from("whatsapp_conversations").update({
        metadata: { ...(conv?.metadata as any), remarcacao_solicitada: true },
      }).eq("id", conversationId);

      toast.info("Solicitação de remarcação registrada");
    } catch (error) {
      console.error("Erro ao processar remarcação:", error);
    }
  };

  const handleDuvida = async (conversationId: string, tenantId: string) => {
    await enviarRespostaAutomatica(
      conversationId,
      "Recebi sua dúvida! Um membro da nossa equipe responderá em breve. 😊",
      tenantId
    );
  };

  const enviarRespostaAutomatica = async (
    conversationId: string,
    mensagem: string,
    tenantId: string
  ) => {
    try {
      // Buscar telefone antes (se já não tiver)
      const { data: conversation } = await supabase
        .from("whatsapp_conversations")
        .select("telefone")
        .eq("id", conversationId)
        .single();

      if (!conversation?.telefone) {
        throw new Error("Telefone não encontrado para esta conversa");
      }

      // Usar serviço centralizado
      await whatsappService.enfileirarMensagemOperacional(tenantId, {
        telefone: conversation.telefone,
        conteudo: mensagem,
        metadata: {
          conversation_id: conversationId,
          sender_type: "sistema",
          direcao: "saida"
        }
      });

    } catch (error) {
      console.error("Erro ao enviar resposta automática:", error);
    }
  };

  return {
    detectIntent,
    processIntent,
  };
}

import { useState, useEffect, useRef } from "react";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Badge } from "@/components/ui/badge";
import { Send, Phone, CheckCheck, Check, Clock, X, Image as ImageIcon } from "lucide-react";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { WhatsAppMediaUpload } from "./WhatsAppMediaUpload";
import { useWhatsAppIntentProcessor } from "./WhatsAppIntentProcessor";

interface Message {
  id: string;
  conversation_id: string;
  sender_type: string;
  sender_name?: string;
  conteudo: string;
  tipo_mensagem: string;
  status: string;
  timestamp: string;
  created_at: string;
}

interface Conversation {
  id: string;
  telefone: string;
  paciente_nome?: string;
  status: string;
  tenant_id: string;
}

interface WhatsAppMessageViewProps {
  conversation: Conversation;
  onClose: () => void;
  onResolve: (conversationId: string) => void;
}

export function WhatsAppMessageView({
  conversation,
  onClose,
  onResolve,
}: WhatsAppMessageViewProps) {
  const [messages, setMessages] = useState<Message[]>([]);
  const [newMessage, setNewMessage] = useState("");
  const [sending, setSending] = useState(false);
  const [loading, setLoading] = useState(true);
  const scrollRef = useRef<HTMLDivElement>(null);
  const { processIntent } = useWhatsAppIntentProcessor();

  useEffect(() => {
    loadMessages();
    subscribeToMessages();
  }, [conversation.id]);

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const loadMessages = async () => {
    try {
      const { data, error } = await supabase
        .from("whatsapp_messages")
        .select("*")
        .eq("conversation_id", conversation.id)
        .order("timestamp", { ascending: true });

      if (error) throw error;
      setMessages(data || []);
    } catch (error) {
      console.error("Erro ao carregar mensagens:", error);
      toast.error("Erro ao carregar mensagens");
    } finally {
      setLoading(false);
    }
  };

  const subscribeToMessages = () => {
    const channel = supabase
      .channel(`messages:${conversation.id}`)
      .on(
        "postgres_changes",
        {
          event: "INSERT",
          schema: "public",
          table: "whatsapp_messages",
          filter: `conversation_id=eq.${conversation.id}`,
        },
        async (payload) => {
          const newMsg = payload.new as Message;
          setMessages((prev) => [...prev, newMsg]);

          // Processar intenção se for mensagem do cliente
          if (newMsg.sender_type === "cliente") {
            await processIntent(conversation.id, newMsg.conteudo, conversation.tenant_id);
          }
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  };

  const scrollToBottom = () => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  };

  const handleSendMediaMessage = async (content: string) => {
    if (sending) return;

    setSending(true);
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error("Usuário não autenticado");

      // Inserir mensagem no banco
      const { error: insertError } = await supabase
        .from("whatsapp_messages")
        .insert({
          conversation_id: conversation.id,
          sender_type: "agente",
          sender_id: user.id,
          conteudo: content,
          tipo_mensagem: "text",
          direcao: "saida",
          status: "pendente",
          timestamp: new Date().toISOString(),
        });

      if (insertError) throw insertError;

      // Chamar edge function para enviar via WhatsApp
      const { error: sendError } = await supabase.functions.invoke("enviar-whatsapp", {
        body: {
          telefone: conversation.telefone,
          mensagem: content,
          tenant_id: conversation.tenant_id,
          conversation_id: conversation.id,
        },
      });

      if (sendError) throw sendError;

      toast.success("Mensagem enviada");
    } catch (error) {
      console.error("Erro ao enviar mensagem:", error);
      toast.error("Erro ao enviar mensagem");
    } finally {
      setSending(false);
    }
  };

  const handleResolve = async () => {
    try {
      const { error } = await supabase
        .from("whatsapp_conversations")
        .update({ status: "resolvido" })
        .eq("id", conversation.id);

      if (error) throw error;

      toast.success("Conversa encerrada");
      onResolve(conversation.id);
    } catch (error) {
      console.error("Erro ao encerrar conversa:", error);
      toast.error("Erro ao encerrar conversa");
    }
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case "entregue":
        return <CheckCheck className="h-3 w-3 text-blue-500" />;
      case "lido":
        return <CheckCheck className="h-3 w-3 text-green-500" />;
      case "enviado":
        return <Check className="h-3 w-3 text-muted-foreground" />;
      case "falha":
        return <X className="h-3 w-3 text-destructive" />;
      default:
        return <Clock className="h-3 w-3 text-muted-foreground" />;
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-full">
        <p className="text-muted-foreground">Carregando mensagens...</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full">
      {/* Header */}
      <div className="p-4 border-b flex items-center justify-between">
        <div className="flex items-center gap-3">
          <Phone className="h-5 w-5 text-muted-foreground" />
          <div>
            <h3 className="font-semibold">
              {conversation.paciente_nome || conversation.telefone}
            </h3>
            {conversation.paciente_nome && (
              <p className="text-sm text-muted-foreground">{conversation.telefone}</p>
            )}
          </div>
        </div>
        <div className="flex items-center gap-2">
          {conversation.status === "em_atendimento" && (
            <Button size="sm" variant="outline" onClick={handleResolve}>
              Encerrar Conversa
            </Button>
          )}
          <Button size="sm" variant="ghost" onClick={onClose}>
            Fechar
          </Button>
        </div>
      </div>

      {/* Messages */}
      <ScrollArea className="flex-1 p-4" ref={scrollRef}>
        <div className="space-y-4">
          {messages.map((message) => (
            <div
              key={message.id}
              className={`flex ${
                message.sender_type === "cliente" ? "justify-start" : "justify-end"
              }`}
            >
              <Card
                className={`max-w-[70%] p-3 ${
                  message.sender_type === "cliente"
                    ? "bg-muted"
                    : "bg-primary text-primary-foreground"
                }`}
              >
                <p className="text-sm whitespace-pre-wrap">{message.conteudo}</p>
                <div className="flex items-center justify-end gap-1 mt-1">
                  <span className="text-xs opacity-70">
                    {format(new Date(message.timestamp), "HH:mm", { locale: ptBR })}
                  </span>
                  {message.sender_type === "agente" && getStatusIcon(message.status)}
                </div>
              </Card>
            </div>
          ))}
        </div>
      </ScrollArea>

      {/* Input */}
      {conversation.status !== "resolvido" && (
        <div className="p-4 border-t">
          <div className="flex gap-2 mb-2">
            <WhatsAppMediaUpload
              conversationId={conversation.id}
              onMediaUploaded={(url, type) => {
                handleSendMediaMessage(`[${type.startsWith('image/') ? 'Imagem' : 'Arquivo'}] ${url}`);
              }}
            />
            <Textarea
              value={newMessage}
              onChange={(e) => setNewMessage(e.target.value)}
              placeholder="Digite sua mensagem..."
              className="min-h-[80px] resize-none flex-1"
              onKeyDown={(e) => {
                if (e.key === "Enter" && !e.shiftKey) {
                  e.preventDefault();
                  handleSendMediaMessage(newMessage);
                  setNewMessage("");
                }
              }}
            />
            <Button
              onClick={() => {
                handleSendMediaMessage(newMessage);
                setNewMessage("");
              }}
              disabled={!newMessage.trim() || sending}
              size="icon"
              className="self-end"
            >
              <Send className="h-4 w-4" />
            </Button>
          </div>
          <p className="text-xs text-muted-foreground">
            Pressione Enter para enviar, Shift+Enter para nova linha
          </p>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
