import { AlertCircle, CheckCircle, Clock, Send, TrendingUp, Activity } from 'lucide-react';
import { toast } from 'sonner';

interface WhatsAppMetric {
  id: string;
  tenant_id: string;
  periodo: string;
  mensagens_enviadas: number;
  mensagens_entregues: number;
  mensagens_lidas: number;
  mensagens_falhadas: number;
  erros_rede: number;
  erros_template: number;
  erros_numero_invalido: number;
  erros_bloqueio: number;
  erros_outros: number;
  latencia_p50: number;
  latencia_p95: number;
  latencia_p99: number;
  tps_medio: number;
  tps_pico: number;
  quality_rating: 'green' | 'yellow' | 'red' | 'unknown';
  optout_rate: number;
  block_rate: number;
}

export function WhatsAppMetrics() {
  const [metrics, setMetrics] = useState<WhatsAppMetric[]>([]);
  const [loading, setLoading] = useState(true);
  const [currentMetrics, setCurrentMetrics] = useState<WhatsAppMetric | null>(null);

  useEffect(() => {
    loadMetrics();
    // Atualizar a cada 30 segundos
    const interval = setInterval(loadMetrics, 30000);
    return () => clearInterval(interval);
  }, []);

  const loadMetrics = async () => {
    try {
      const { data, error } = await supabase
        .from('whatsapp_metrics' as any)
        .select('*')
        .order('periodo', { ascending: false })
        .limit(24); // Últimas 24 horas

      if (error) throw error;

      setMetrics(data as any || []);
      if (data && data.length > 0) {
        setCurrentMetrics(data[0] as any);
      }
    } catch (error: any) {
      console.error('Error loading metrics:', error);
      toast.error('Erro ao carregar métricas');
    } finally {
      setLoading(false);
    }
  };

  const getQualityBadge = (rating: string) => {
    const variants = {
      green: 'default',
      yellow: 'secondary',
      red: 'destructive',
      unknown: 'outline'
    };

    return (
      <Badge variant={variants[rating as keyof typeof variants] as any}>
        {rating.toUpperCase()}
      </Badge>
    );
  };

  const calculateErrorRate = (metric: WhatsAppMetric) => {
    if (!metric.mensagens_enviadas) return 0;
    return ((metric.mensagens_falhadas / metric.mensagens_enviadas) * 100).toFixed(2);
  };

  const calculateDeliveryRate = (metric: WhatsAppMetric) => {
    if (!metric.mensagens_enviadas) return 0;
    return ((metric.mensagens_entregues / metric.mensagens_enviadas) * 100).toFixed(2);
  };

  if (loading) {
    return <div>Carregando métricas...</div>;
  }

  if (!currentMetrics) {
    return (
      <Card>
        <CardHeader>
          <CardTitle>Métricas WhatsApp</CardTitle>
          <CardDescription>Nenhuma métrica disponível</CardDescription>
        </CardHeader>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      {/* Cards principais */}
      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Mensagens Enviadas</CardTitle>
            <Send className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{currentMetrics.mensagens_enviadas}</div>
            <p className="text-xs text-muted-foreground">
              TPS médio: {currentMetrics.tps_medio.toFixed(2)}/s
            </p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Taxa de Entrega</CardTitle>
            <CheckCircle className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{calculateDeliveryRate(currentMetrics)}%</div>
            <p className="text-xs text-muted-foreground">
              {currentMetrics.mensagens_entregues} entregues
            </p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Taxa de Erro</CardTitle>
            <AlertCircle className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{calculateErrorRate(currentMetrics)}%</div>
            <p className="text-xs text-muted-foreground">
              {currentMetrics.mensagens_falhadas} falhas
            </p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Quality Rating</CardTitle>
            <Activity className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="flex items-center gap-2">
              {getQualityBadge(currentMetrics.quality_rating)}
            </div>
            <p className="text-xs text-muted-foreground mt-2">
              Opt-out: {(currentMetrics.optout_rate * 100).toFixed(2)}%
            </p>
          </CardContent>
        </Card>
      </div>

      {/* Latência */}
      <Card>
        <CardHeader>
          <CardTitle>Latência (Webhooks/Entrega)</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid gap-4 md:grid-cols-3">
            <div>
              <div className="flex items-center gap-2 mb-2">
                <Clock className="h-4 w-4 text-muted-foreground" />
                <span className="text-sm font-medium">P50</span>
              </div>
              <div className="text-2xl font-bold">{currentMetrics.latencia_p50}ms</div>
            </div>
            <div>
              <div className="flex items-center gap-2 mb-2">
                <Clock className="h-4 w-4 text-muted-foreground" />
                <span className="text-sm font-medium">P95</span>
              </div>
              <div className="text-2xl font-bold">{currentMetrics.latencia_p95}ms</div>
            </div>
            <div>
              <div className="flex items-center gap-2 mb-2">
                <Clock className="h-4 w-4 text-muted-foreground" />
                <span className="text-sm font-medium">P99</span>
              </div>
              <div className="text-2xl font-bold">{currentMetrics.latencia_p99}ms</div>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Erros por categoria */}
      <Card>
        <CardHeader>
          <CardTitle>Erros por Categoria</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <span className="text-sm">Erro de Rede</span>
              <div className="flex items-center gap-2">
                <div className="h-2 bg-red-500 rounded" style={{ width: `${(currentMetrics.erros_rede / currentMetrics.mensagens_falhadas || 0) * 100}px` }}></div>
                <span className="text-sm font-medium">{currentMetrics.erros_rede}</span>
              </div>
            </div>
            <div className="flex items-center justify-between">
              <span className="text-sm">Template Rejeitado</span>
              <div className="flex items-center gap-2">
                <div className="h-2 bg-red-500 rounded" style={{ width: `${(currentMetrics.erros_template / currentMetrics.mensagens_falhadas || 0) * 100}px` }}></div>
                <span className="text-sm font-medium">{currentMetrics.erros_template}</span>
              </div>
            </div>
            <div className="flex items-center justify-between">
              <span className="text-sm">Número Inválido</span>
              <div className="flex items-center gap-2">
                <div className="h-2 bg-red-500 rounded" style={{ width: `${(currentMetrics.erros_numero_invalido / currentMetrics.mensagens_falhadas || 0) * 100}px` }}></div>
                <span className="text-sm font-medium">{currentMetrics.erros_numero_invalido}</span>
              </div>
            </div>
            <div className="flex items-center justify-between">
              <span className="text-sm">Bloqueio</span>
              <div className="flex items-center gap-2">
                <div className="h-2 bg-red-500 rounded" style={{ width: `${(currentMetrics.erros_bloqueio / currentMetrics.mensagens_falhadas || 0) * 100}px` }}></div>
                <span className="text-sm font-medium">{currentMetrics.erros_bloqueio}</span>
              </div>
            </div>
            <div className="flex items-center justify-between">
              <span className="text-sm">Outros</span>
              <div className="flex items-center gap-2">
                <div className="h-2 bg-red-500 rounded" style={{ width: `${(currentMetrics.erros_outros / currentMetrics.mensagens_falhadas || 0) * 100}px` }}></div>
                <span className="text-sm font-medium">{currentMetrics.erros_outros}</span>
              </div>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

import { useEffect, useState, useMemo } from "react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Clock, User, CheckCircle2, Circle, AlertCircle, Search, Filter } from "lucide-react";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";

interface PacientesDoDiaProps {
  onSelectPaciente: (agendamento: any) => void;
}

export function PacientesDoDia({ onSelectPaciente }: PacientesDoDiaProps) {
  const [agendamentos, setAgendamentos] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [statusFilter, setStatusFilter] = useState<string>("todos");
  const [salaFilter, setSalaFilter] = useState<string>("todas");
  const [servicoFilter, setServicoFilter] = useState<string>("todos");

  useEffect(() => {
    loadAgendamentos();
  }, []);

  const loadAgendamentos = async () => {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      const hoje = new Date();
      hoje.setHours(0, 0, 0, 0);
      const amanha = new Date(hoje);
      amanha.setDate(amanha.getDate() + 1);

      const { data, error } = await supabase
        .from('agenda')
        .select(`
          *,
          pacientes(id, nome, telefone, email),
          servicos(nome, duracao_minutos)
        `)
        .eq('profissional_id', user.id)
        .gte('inicio', hoje.toISOString())
        .lt('inicio', amanha.toISOString())
        .neq('status', 'cancelado')
        .order('inicio', { ascending: true });

      if (error) throw error;

      setAgendamentos(data || []);
    } catch (error: any) {
      console.error('Erro ao carregar agendamentos:', error);
      toast.error('Erro ao carregar lista de pacientes');
    } finally {
      setLoading(false);
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'concluido':
        return 'bg-success/10 text-success border-success/20';
      case 'em_atendimento':
        return 'bg-primary/10 text-primary border-primary/20';
      case 'agendado':
        return 'bg-muted/50 text-muted-foreground border-border';
      default:
        return 'bg-muted text-muted-foreground';
    }
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'concluido':
        return <CheckCircle2 className="h-5 w-5" />;
      case 'em_atendimento':
        return <AlertCircle className="h-5 w-5" />;
      default:
        return <Circle className="h-5 w-5" />;
    }
  };

  const getStatusLabel = (status: string) => {
    const labels: Record<string, string> = {
      agendado: 'Aguardando',
      em_atendimento: 'Em Atendimento',
      concluido: 'Atendido',
    };
    return labels[status] || status;
  };

  // Extrair salas e serviços únicos
  const salas = useMemo(() => {
    const uniqueSalas = [...new Set(agendamentos.map(a => a.sala).filter(Boolean))];
    return uniqueSalas;
  }, [agendamentos]);

  const servicos = useMemo(() => {
    const uniqueServicos = [...new Set(agendamentos.map(a => a.servicos?.nome).filter(Boolean))];
    return uniqueServicos;
  }, [agendamentos]);

  // Filtrar agendamentos
  const agendamentosFiltrados = useMemo(() => {
    return agendamentos.filter(agendamento => {
      // Filtro de busca por nome
      if (searchTerm && !agendamento.pacientes?.nome.toLowerCase().includes(searchTerm.toLowerCase())) {
        return false;
      }

      // Filtro de status
      if (statusFilter !== "todos" && agendamento.status !== statusFilter) {
        return false;
      }

      // Filtro de sala
      if (salaFilter !== "todas" && agendamento.sala !== salaFilter) {
        return false;
      }

      // Filtro de serviço
      if (servicoFilter !== "todos" && agendamento.servicos?.nome !== servicoFilter) {
        return false;
      }

      return true;
    });
  }, [agendamentos, searchTerm, statusFilter, salaFilter, servicoFilter]);

  // Contadores por status
  const contadores = useMemo(() => {
    return {
      aguardando: agendamentos.filter(a => a.status === 'agendado').length,
      em_atendimento: agendamentos.filter(a => a.status === 'em_atendimento').length,
      atendido: agendamentos.filter(a => a.status === 'concluido').length,
      total: agendamentos.length
    };
  }, [agendamentos]);

  if (loading) {
    return (
      <div className="space-y-3">
        {[1, 2, 3].map((i) => (
          <Card key={i}>
            <CardContent className="p-6">
              <Skeleton className="h-20 w-full" />
            </CardContent>
          </Card>
        ))}
      </div>
    );
  }

  if (agendamentos.length === 0) {
    return (
      <Card>
        <CardContent className="py-12">
          <div className="text-center text-muted-foreground">
            <User className="h-12 w-12 mx-auto mb-4 opacity-50" />
            <p className="text-lg font-medium">Nenhum paciente agendado para hoje</p>
            <p className="text-sm mt-2">Sua agenda está livre</p>
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      {/* Contadores de Status */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <Card className="bg-muted/30">
          <CardContent className="p-4">
            <div className="flex items-center gap-3">
              <div className="h-10 w-10 rounded-lg bg-primary/10 flex items-center justify-center">
                <Circle className="h-5 w-5 text-primary" />
              </div>
              <div>
                <p className="text-sm text-muted-foreground">Aguardando</p>
                <p className="text-2xl font-bold">{contadores.aguardando}</p>
              </div>
            </div>
          </CardContent>
        </Card>

        <Card className="bg-muted/30">
          <CardContent className="p-4">
            <div className="flex items-center gap-3">
              <div className="h-10 w-10 rounded-lg bg-primary/10 flex items-center justify-center">
                <AlertCircle className="h-5 w-5 text-primary" />
              </div>
              <div>
                <p className="text-sm text-muted-foreground">Em Atendimento</p>
                <p className="text-2xl font-bold">{contadores.em_atendimento}</p>
              </div>
            </div>
          </CardContent>
        </Card>

        <Card className="bg-success/5 border-success/20">
          <CardContent className="p-4">
            <div className="flex items-center gap-3">
              <div className="h-10 w-10 rounded-lg bg-success/10 flex items-center justify-center">
                <CheckCircle2 className="h-5 w-5 text-success" />
              </div>
              <div>
                <p className="text-sm text-muted-foreground">Atendidos</p>
                <p className="text-2xl font-bold text-success">{contadores.atendido}</p>
              </div>
            </div>
          </CardContent>
        </Card>

        <Card className="bg-muted/30">
          <CardContent className="p-4">
            <div className="flex items-center gap-3">
              <div className="h-10 w-10 rounded-lg bg-primary/10 flex items-center justify-center">
                <User className="h-5 w-5 text-primary" />
              </div>
              <div>
                <p className="text-sm text-muted-foreground">Total</p>
                <p className="text-2xl font-bold">{contadores.total}</p>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Filtros */}
      <Card>
        <CardContent className="p-6">
          <div className="flex items-center gap-2 mb-4">
            <Filter className="h-5 w-5 text-muted-foreground" />
            <h3 className="font-semibold">Filtros</h3>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            {/* Busca por nome */}
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <Input
                placeholder="Buscar por nome..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pl-9"
              />
            </div>

            {/* Filtro de Status */}
            <Select value={statusFilter} onValueChange={setStatusFilter}>
              <SelectTrigger>
                <SelectValue placeholder="Status" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="todos">Todos os status</SelectItem>
                <SelectItem value="agendado">Aguardando</SelectItem>
                <SelectItem value="em_atendimento">Em Atendimento</SelectItem>
                <SelectItem value="concluido">Atendido</SelectItem>
              </SelectContent>
            </Select>

            {/* Filtro de Sala */}
            <Select value={salaFilter} onValueChange={setSalaFilter}>
              <SelectTrigger>
                <SelectValue placeholder="Sala" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="todas">Todas as salas</SelectItem>
                {salas.map(sala => (
                  <SelectItem key={sala} value={sala}>{sala}</SelectItem>
                ))}
              </SelectContent>
            </Select>

            {/* Filtro de Serviço */}
            <Select value={servicoFilter} onValueChange={setServicoFilter}>
              <SelectTrigger>
                <SelectValue placeholder="Serviço" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="todos">Todos os serviços</SelectItem>
                {servicos.map(servico => (
                  <SelectItem key={servico} value={servico}>{servico}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* Botão para limpar filtros */}
          {(searchTerm || statusFilter !== "todos" || salaFilter !== "todas" || servicoFilter !== "todos") && (
            <div className="mt-4">
              <Button
                variant="ghost"
                size="sm"
                onClick={() => {
                  setSearchTerm("");
                  setStatusFilter("todos");
                  setSalaFilter("todas");
                  setServicoFilter("todos");
                }}
              >
                Limpar filtros
              </Button>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Lista de Pacientes */}
      {agendamentosFiltrados.length === 0 ? (
        <Card>
          <CardContent className="py-12">
            <div className="text-center text-muted-foreground">
              <Search className="h-12 w-12 mx-auto mb-4 opacity-50" />
              <p className="text-lg font-medium">Nenhum paciente encontrado</p>
              <p className="text-sm mt-2">Tente ajustar os filtros</p>
            </div>
          </CardContent>
        </Card>
      ) : (
        <div className="space-y-3">
          {agendamentosFiltrados.map((agendamento) => (
            <Card
              key={agendamento.id}
              className={`transition-all hover:shadow-lg cursor-pointer ${
                agendamento.status === 'concluido' ? 'opacity-75' : ''
              }`}
              onClick={() => onSelectPaciente(agendamento)}
            >
              <CardContent className="p-6">
                <div className="flex items-start justify-between gap-4">
                  <div className="flex-1 space-y-3">
                    <div className="flex items-center gap-3">
                      <div className={`p-2 rounded-lg ${getStatusColor(agendamento.status)}`}>
                        {getStatusIcon(agendamento.status)}
                      </div>
                      <div>
                        <h3 className="font-semibold text-lg">
                          {agendamento.pacientes?.nome}
                        </h3>
                        <p className="text-sm text-muted-foreground">
                          {agendamento.servicos?.nome}
                        </p>
                      </div>
                    </div>

                    <div className="flex items-center gap-4 text-sm text-muted-foreground">
                      <div className="flex items-center gap-2">
                        <Clock className="h-4 w-4" />
                        <span>
                          {format(new Date(agendamento.inicio), "HH:mm", { locale: ptBR })}
                          {agendamento.servicos?.duracao_minutos && 
                            ` (${agendamento.servicos.duracao_minutos}min)`
                          }
                        </span>
                      </div>
                      {agendamento.sala && (
                        <Badge variant="outline">Sala: {agendamento.sala}</Badge>
                      )}
                    </div>

                    {agendamento.notas && (
                      <p className="text-sm text-muted-foreground line-clamp-2">
                        {agendamento.notas}
                      </p>
                    )}
                  </div>

                  <div className="flex flex-col items-end gap-2">
                    <Badge className={getStatusColor(agendamento.status)}>
                      {getStatusLabel(agendamento.status)}
                    </Badge>
                    <Button size="sm" variant="default">
                      {agendamento.status === 'concluido' ? 'Ver Prontuário' : 'Iniciar Atendimento'}
                    </Button>
                  </div>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}
    </div>
  );
}

import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { ScrollArea } from "@/components/ui/scroll-area";
import { 
  ArrowLeft, 
  Save, 
  FileCheck, 
  Clock, 
  Activity,
  Stethoscope,
  ClipboardList,
  History
} from "lucide-react";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";
import { AtendimentoTimer } from "./AtendimentoTimer";

interface ProntuarioAtendimentoProps {
  agendamento: any;
  onClose: () => void;
}

export function ProntuarioAtendimento({ agendamento, onClose }: ProntuarioAtendimentoProps) {
  const [loading, setLoading] = useState(false);
  const [historicoLoading, setHistoricoLoading] = useState(true);
  const [historico, setHistorico] = useState<any[]>([]);
  const [pacienteInfo, setPacienteInfo] = useState<any>(null);
  const [prontuarioAtual, setProntuarioAtual] = useState<any>(null);
  const [proximoAgendamento, setProximoAgendamento] = useState<Date | undefined>(undefined);
  const [formData, setFormData] = useState({
    // Anamnese (primeira consulta)
    queixa_principal: '',
    historia_doenca_atual: '',
    historia_pregressa: '',
    alergias: [] as string[],
    medicamentos_uso: [] as string[],
    historia_familiar: '',
    historia_social: '',

    // SOAP
    subjetivo: '',
    objetivo: '',
    avaliacao: '',
    plano: '',

    // Sinais Vitais
    pressao_arterial: '',
    frequencia_cardiaca: '',
    temperatura: '',
    peso: '',
    altura: '',
    saturacao_o2: '',

    // Diagnóstico
    cid10_principal: '',
    hipotese_diagnostica: '',

    // Observações
    observacoes: '',
    evolucao: '',
  });

  useEffect(() => {
    loadPacienteInfo();
    loadHistorico();
    checkProntuarioExistente();
    loadProximoAgendamento();
  }, [agendamento]);

  const loadPacienteInfo = async () => {
    try {
      const { data, error } = await supabase
        .from('pacientes')
        .select('*')
        .eq('id', agendamento.paciente_id)
        .single();

      if (error) throw error;
      setPacienteInfo(data);
    } catch (error: any) {
      console.error('Erro ao carregar dados do paciente:', error);
    }
  };

  const loadProximoAgendamento = async () => {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      const { data, error } = await supabase
        .from('agenda')
        .select('inicio')
        .eq('profissional_id', user.id)
        .gt('inicio', agendamento.inicio)
        .neq('status', 'cancelado')
        .order('inicio', { ascending: true })
        .limit(1)
        .maybeSingle();

      if (data) {
        setProximoAgendamento(new Date(data.inicio));
      }
    } catch (error: any) {
      console.error('Erro ao carregar próximo agendamento:', error);
    }
  };

  const loadHistorico = async () => {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      const { data, error } = await supabase
        .from('prontuarios' as any)
        .select('*')
        .eq('paciente_id', agendamento.paciente_id)
        .eq('profissional_id', user.id)
        .order('data_atendimento', { ascending: false });

      if (error) throw error;
      setHistorico(data || []);
    } catch (error: any) {
      console.error('Erro ao carregar histórico:', error);
    } finally {
      setHistoricoLoading(false);
    }
  };

  const checkProntuarioExistente = async () => {
    try {
      const { data, error } = await supabase
        .from('prontuarios' as any)
        .select('*')
        .eq('agendamento_id', agendamento.id)
        .maybeSingle();

      if (error && error.code !== 'PGRST116') throw error;

      if (data) {
        setProntuarioAtual(data);
        const prontuario = data as any;
        setFormData({
          queixa_principal: prontuario.queixa_principal || '',
          historia_doenca_atual: prontuario.historia_doenca_atual || '',
          historia_pregressa: prontuario.historia_pregressa || '',
          alergias: prontuario.alergias || [],
          medicamentos_uso: prontuario.medicamentos_uso || [],
          historia_familiar: prontuario.historia_familiar || '',
          historia_social: prontuario.historia_social || '',
          subjetivo: prontuario.subjetivo || '',
          objetivo: prontuario.objetivo || '',
          avaliacao: prontuario.avaliacao || '',
          plano: prontuario.plano || '',
          pressao_arterial: prontuario.pressao_arterial || '',
          frequencia_cardiaca: prontuario.frequencia_cardiaca?.toString() || '',
          temperatura: prontuario.temperatura?.toString() || '',
          peso: prontuario.peso?.toString() || '',
          altura: prontuario.altura?.toString() || '',
          saturacao_o2: prontuario.saturacao_o2?.toString() || '',
          cid10_principal: prontuario.cid10_principal || '',
          hipotese_diagnostica: prontuario.hipotese_diagnostica || '',
          observacoes: prontuario.observacoes || '',
          evolucao: prontuario.evolucao || '',
        });
      }
    } catch (error: any) {
      console.error('Erro ao verificar prontuário:', error);
    }
  };

  const handleInputChange = (field: string, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const calcularIMC = () => {
    const peso = parseFloat(formData.peso);
    const altura = parseFloat(formData.altura);
    if (peso && altura && altura > 0) {
      return (peso / (altura * altura)).toFixed(2);
    }
    return null;
  };

  const handleSave = async (finalizar: boolean = false) => {
    try {
      setLoading(true);

      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      const { data: profile } = await supabase
        .from('profiles')
        .select('tenant_id')
        .eq('id', user.id)
        .single();

      if (!profile) return;

      const imc = calcularIMC();
      const prontuarioData = {
        tenant_id: profile.tenant_id,
        paciente_id: agendamento.paciente_id,
        profissional_id: user.id,
        agendamento_id: agendamento.id,
        data_atendimento: new Date().toISOString(),

        queixa_principal: formData.queixa_principal || null,
        historia_doenca_atual: formData.historia_doenca_atual || null,
        historia_pregressa: formData.historia_pregressa || null,
        alergias: formData.alergias.length > 0 ? formData.alergias : null,
        medicamentos_uso: formData.medicamentos_uso.length > 0 ? formData.medicamentos_uso : null,
        historia_familiar: formData.historia_familiar || null,
        historia_social: formData.historia_social || null,

        subjetivo: formData.subjetivo || null,
        objetivo: formData.objetivo || null,
        avaliacao: formData.avaliacao || null,
        plano: formData.plano || null,

        pressao_arterial: formData.pressao_arterial || null,
        frequencia_cardiaca: formData.frequencia_cardiaca ? parseInt(formData.frequencia_cardiaca) : null,
        temperatura: formData.temperatura ? parseFloat(formData.temperatura) : null,
        peso: formData.peso ? parseFloat(formData.peso) : null,
        altura: formData.altura ? parseFloat(formData.altura) : null,
        imc: imc ? parseFloat(imc) : null,
        saturacao_o2: formData.saturacao_o2 ? parseInt(formData.saturacao_o2) : null,

        cid10_principal: formData.cid10_principal || null,
        hipotese_diagnostica: formData.hipotese_diagnostica || null,

        observacoes: formData.observacoes || null,
        evolucao: formData.evolucao || null,

        status: finalizar ? 'finalizado' : 'rascunho',
        finalizado_em: finalizar ? new Date().toISOString() : null,
      };

      let result;
      if (prontuarioAtual) {
        result = await supabase
          .from('prontuarios' as any)
          .update(prontuarioData)
          .eq('id', prontuarioAtual.id)
          .select()
          .single();
      } else {
        result = await supabase
          .from('prontuarios' as any)
          .insert(prontuarioData)
          .select()
          .single();
      }

      if (result.error) throw result.error;

      // Atualizar status do agendamento
      if (finalizar) {
        await supabase
          .from('agenda')
          .update({ status: 'concluido' })
          .eq('id', agendamento.id);
      } else {
        await supabase
          .from('agenda')
          .update({ status: 'em_atendimento' })
          .eq('id', agendamento.id);
      }

      toast.success(finalizar ? 'Prontuário finalizado com sucesso' : 'Rascunho salvo');

      if (finalizar) {
        onClose();
      } else {
        setProntuarioAtual(result.data);
      }
    } catch (error: any) {
      console.error('Erro ao salvar prontuário:', error);
      toast.error('Erro ao salvar prontuário');
    } finally {
      setLoading(false);
    }
  };

  const isPrimeiraConsulta = historico.length === 0;

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Button variant="ghost" size="icon" onClick={onClose}>
            <ArrowLeft className="h-4 w-4" />
          </Button>
          <div>
            <h2 className="text-2xl font-bold">{pacienteInfo?.nome}</h2>
            <p className="text-sm text-muted-foreground">
              {format(new Date(agendamento.inicio), "dd 'de' MMMM 'de' yyyy 'às' HH:mm", { locale: ptBR })}
            </p>
          </div>
        </div>
        <div className="flex gap-2">
          <Button 
            variant="outline" 
            onClick={() => handleSave(false)}
            disabled={loading}
          >
            <Save className="h-4 w-4 mr-2" />
            Salvar Rascunho
          </Button>
          <Button 
            onClick={() => handleSave(true)}
            disabled={loading}
          >
            <FileCheck className="h-4 w-4 mr-2" />
            Finalizar Atendimento
          </Button>
        </div>
      </div>

      {/* Temporizador de Atendimento */}
      <AtendimentoTimer 
        inicioAtendimento={new Date(agendamento.inicio)}
        duracaoMinutos={agendamento.servicos?.duracao_minutos || 60}
        proximoAtendimento={proximoAgendamento}
      />

      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Activity className="h-5 w-5" />
            Dados Vitais
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div>
              <Label>Pressão Arterial</Label>
              <Input
                placeholder="120/80"
                value={formData.pressao_arterial}
                onChange={(e) => handleInputChange('pressao_arterial', e.target.value)}
              />
            </div>
            <div>
              <Label>FC (bpm)</Label>
              <Input
                type="number"
                placeholder="72"
                value={formData.frequencia_cardiaca}
                onChange={(e) => handleInputChange('frequencia_cardiaca', e.target.value)}
              />
            </div>
            <div>
              <Label>Temperatura (°C)</Label>
              <Input
                type="number"
                step="0.1"
                placeholder="36.5"
                value={formData.temperatura}
                onChange={(e) => handleInputChange('temperatura', e.target.value)}
              />
            </div>
            <div>
              <Label>SpO2 (%)</Label>
              <Input
                type="number"
                placeholder="98"
                value={formData.saturacao_o2}
                onChange={(e) => handleInputChange('saturacao_o2', e.target.value)}
              />
            </div>
            <div>
              <Label>Peso (kg)</Label>
              <Input
                type="number"
                step="0.01"
                placeholder="70"
                value={formData.peso}
                onChange={(e) => handleInputChange('peso', e.target.value)}
              />
            </div>
            <div>
              <Label>Altura (m)</Label>
              <Input
                type="number"
                step="0.01"
                placeholder="1.75"
                value={formData.altura}
                onChange={(e) => handleInputChange('altura', e.target.value)}
              />
            </div>
            <div>
              <Label>IMC</Label>
              <Input
                value={calcularIMC() || '—'}
                disabled
                className="bg-muted"
              />
            </div>
          </div>
        </CardContent>
      </Card>

      <Tabs defaultValue={isPrimeiraConsulta ? "anamnese" : "soap"}>
        <TabsList className="grid w-full grid-cols-3">
          {isPrimeiraConsulta && (
            <TabsTrigger value="anamnese">
              <ClipboardList className="h-4 w-4 mr-2" />
              Anamnese
            </TabsTrigger>
          )}
          <TabsTrigger value="soap">
            <Stethoscope className="h-4 w-4 mr-2" />
            SOAP
          </TabsTrigger>
          <TabsTrigger value="historico">
            <History className="h-4 w-4 mr-2" />
            Histórico ({historico.length})
          </TabsTrigger>
        </TabsList>

        {isPrimeiraConsulta && (
          <TabsContent value="anamnese" className="space-y-4">
            <Card>
              <CardHeader>
                <CardTitle>Anamnese - Primeira Consulta</CardTitle>
              </CardHeader>
