                    </div>
                </div>
            )}

            {/* SAUDE (Default) */}
            {features.includes('anamnese') && (
                <div>
                    <Label>Queixa Principal / Observações Iniciais</Label>
                    <Textarea
                        value={data.queixa_principal || ''}
                        onChange={(e) => onChange('queixa_principal', e.target.value)}
                        placeholder="Descreva o motivo da consulta..."
                    />
                </div>
            )}
        </div>
    );
}

