        .eq("id", user.id)
        .maybeSingle();

      if (!profile?.tenant_id) throw new Error("Tenant não encontrado");

      const { data, error } = await (supabase as any)
        .from("configuracoes_felicitacoes")
        .select("*")
        .eq("tenant_id", profile.tenant_id)
        .maybeSingle();

      if (error) throw error;

      if (data) {
        setConfig({
          felicitar_pacientes: data.felicitar_pacientes,
          felicitar_profissionais: data.felicitar_profissionais,
          mensagem_paciente: data.mensagem_paciente,
          mensagem_profissional: data.mensagem_profissional,
          horario_envio: data.horario_envio?.substring(0, 5) || "09:00",
          canal_envio: data.canal_envio || ["whatsapp", "email"]
        });
      }
    } catch (error: any) {
      console.error("Erro ao buscar configurações:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleSave = async () => {
    try {
      setSaving(true);

      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error("Usuário não autenticado");

      const { data: profile } = await supabase
        .from("profiles")
        .select("tenant_id")
        .eq("id", user.id)
        .maybeSingle();

      if (!profile?.tenant_id) throw new Error("Tenant não encontrado");

      const { error } = await (supabase as any)
        .from("configuracoes_felicitacoes")
        .upsert({
          tenant_id: profile.tenant_id,
          ...config
        }, {
          onConflict: "tenant_id"
        });

      if (error) throw error;

      toast({
        title: "Sucesso!",
        description: "Configurações salvas com sucesso."
      });
    } catch (error: any) {
      console.error("Erro ao salvar:", error);
      toast({
        title: "Erro",
        description: error.message || "Não foi possível salvar as configurações.",
        variant: "destructive"
      });
    } finally {
      setSaving(false);
    }
  };

  const toggleCanal = (canal: string) => {
    const novosCanais = config.canal_envio.includes(canal)
      ? config.canal_envio.filter(c => c !== canal)
      : [...config.canal_envio, canal];

    setConfig({ ...config, canal_envio: novosCanais });
  };

  if (loading) {
    return <div className="text-center py-8">Carregando...</div>;
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <Cake className="h-5 w-5" />
          Felicitações de Aniversário
        </CardTitle>
        <CardDescription>
          Configure mensagens automáticas para aniversariantes
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-6">
        {/* Pacientes */}
        <div className="space-y-4">
          <div className="flex items-center justify-between">
            <div>
              <Label htmlFor="felicitar_pacientes" className="text-base">
                Felicitar Pacientes
              </Label>
              <p className="text-sm text-muted-foreground">
                Enviar mensagem automática no aniversário dos pacientes
              </p>
            </div>
            <Switch
              id="felicitar_pacientes"
              checked={config.felicitar_pacientes}
              onCheckedChange={(checked) => 
                setConfig({ ...config, felicitar_pacientes: checked })
              }
            />
          </div>

          {config.felicitar_pacientes && (
            <div className="space-y-2 pl-4 border-l-2">
              <Label>Mensagem para Pacientes</Label>
              <Textarea
                value={config.mensagem_paciente}
                onChange={(e) => setConfig({ ...config, mensagem_paciente: e.target.value })}
                rows={3}
                placeholder="Mensagem de aniversário para pacientes"
              />
            </div>
          )}
        </div>

        {/* Profissionais */}
        <div className="space-y-4">
          <div className="flex items-center justify-between">
            <div>
              <Label htmlFor="felicitar_profissionais" className="text-base">
                Felicitar Profissionais
              </Label>
              <p className="text-sm text-muted-foreground">
                Enviar mensagem automática no aniversário dos profissionais
              </p>
            </div>
            <Switch
              id="felicitar_profissionais"
              checked={config.felicitar_profissionais}
              onCheckedChange={(checked) => 
                setConfig({ ...config, felicitar_profissionais: checked })
              }
            />
          </div>

          {config.felicitar_profissionais && (
            <div className="space-y-2 pl-4 border-l-2">
              <Label>Mensagem para Profissionais</Label>
              <Textarea
                value={config.mensagem_profissional}
                onChange={(e) => setConfig({ ...config, mensagem_profissional: e.target.value })}
                rows={3}
                placeholder="Mensagem de aniversário para profissionais"
              />
            </div>
          )}
        </div>

        {/* Horário e Canal */}
        <div className="grid gap-4 md:grid-cols-2">
          <div className="space-y-2">
            <Label htmlFor="horario_envio">Horário de Envio</Label>
            <Input
              id="horario_envio"
              type="time"
              value={config.horario_envio}
              onChange={(e) => setConfig({ ...config, horario_envio: e.target.value })}
            />
          </div>

          <div className="space-y-2">
            <Label>Canais de Envio</Label>
            <div className="flex gap-2 flex-wrap">
              <Badge
                variant={config.canal_envio.includes("whatsapp") ? "default" : "outline"}
                className="cursor-pointer"
                onClick={() => toggleCanal("whatsapp")}
              >
                WhatsApp
              </Badge>
              <Badge
                variant={config.canal_envio.includes("email") ? "default" : "outline"}
                className="cursor-pointer"
                onClick={() => toggleCanal("email")}
              >
                E-mail
              </Badge>
              <Badge
                variant={config.canal_envio.includes("sms") ? "default" : "outline"}
                className="cursor-pointer"
                onClick={() => toggleCanal("sms")}
              >
                SMS
              </Badge>
            </div>
          </div>
        </div>

        <div className="flex justify-end pt-4">
          <Button onClick={handleSave} disabled={saving}>
            {saving && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
            Salvar Configurações
          </Button>
        </div>
      </CardContent>
    </Card>
  );
}

import React, { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useToast } from "@/hooks/use-toast";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { Check, Loader2, AlertTriangle } from "lucide-react";

interface Plan {
    codigo_plano: string;
    descricao: string;
    preco_mensal_brl: number;
    moeda: string;
    ativo: boolean;
    features: string[]; // Mocked for now
}

interface Subscription {
    id: string;
    codigo_plano: string;
    status: string;
    ciclo_fim: string;
    edition: string;
}

interface PreviewData {
    current_plan: { name: string; price: number };
    new_plan: { name: string; price: number };
    prorata_amount: number;
    total_now: number;
    next_cycle_total: number;
    effective_date: string;
}

const PlanosConfig = () => {
    const { profile } = useAuth();
    const { toast } = useToast();
    const [loading, setLoading] = useState(true);
    const [subscription, setSubscription] = useState<Subscription | null>(null);
    const [plans, setPlans] = useState<Plan[]>([]);

    const [selectedPlan, setSelectedPlan] = useState<Plan | null>(null);
    const [isDialogOpen, setIsDialogOpen] = useState(false);
    const [previewData, setPreviewData] = useState<PreviewData | null>(null);
    const [loadingPreview, setLoadingPreview] = useState(false);
    const [processingChange, setProcessingChange] = useState(false);

    const [companySeats, setCompanySeats] = useState(5); // Default included

    useEffect(() => {
        fetchData();
    }, [profile?.tenant_id]);

    const fetchData = async () => {
        if (!profile?.tenant_id) return;
        try {
            setLoading(true);

            // Fetch Plans
            const { data: plansData } = await supabase
                .from('planos_precos')
                .select('*')
                .eq('ativo', true)
                .order('preco_mensal_brl');

            // Add mock features
            const plansWithFeatures = plansData?.map(p => ({
                ...p,
                features: getFeaturesForPlan(p.codigo_plano)
            })) || [];

            setPlans(plansWithFeatures);

            // Fetch Subscription
            const { data: subData } = await supabase
                .from('assinaturas')
                .select('*')
                .eq('tenant_id', profile.tenant_id)
                .in('status', ['active', 'trialing', 'past_due'])
                .single();

            setSubscription(subData);

            // If company plan, fetch current seats
            if (subData?.codigo_plano === 'company_base') {
                const { data: seatData } = await supabase
                    .from('assinatura_seats')
                    .select('quantidade')
                    .eq('assinatura_id', subData.id)
                    .eq('tipo', 'profissional')
                    .single();

                if (seatData) setCompanySeats(seatData.quantidade);
            }

        } catch (error) {
            console.error("Error fetching billing data:", error);
        } finally {
            setLoading(false);
        }
    };

    const getFeaturesForPlan = (code: string) => {
        switch (code) {
            case 'free_solo': return ['1 Profissional', 'Até 50 Clientes', 'Agendamento Manual'];
            case 'pro_solo': return ['1 Profissional', 'Clientes Ilimitados', 'WhatsApp Automático', 'Agendamento Online'];
            case 'company_base': return ['Até 5 Profissionais (Inclusos)', '3 Secretárias', 'Multi-usuário', 'Relatórios Avançados'];
            default: return [];
        }
    };

    const handleSelectPlan = (plan: Plan) => {
        setSelectedPlan(plan);
        setIsDialogOpen(true);
        // If selecting company, reset seats to min or current if already company
        if (plan.codigo_plano === 'company_base') {
            // If already company, keep current seats, else default to 5
            if (subscription?.codigo_plano === 'company_base') {
                // Keep current (already in state)
            } else {
                setCompanySeats(5);
            }
        }
        fetchPreview(plan, plan.codigo_plano === 'company_base' ? companySeats : undefined);
    };

    const fetchPreview = async (plan: Plan, seats?: number) => {
        if (!subscription) return;

        // Determine if downgrade
        const currentPlanPrice = plans.find(p => p.codigo_plano === subscription.codigo_plano)?.preco_mensal_brl || 0;
        const isDowngrade = plan.preco_mensal_brl < currentPlanPrice;
        const effective = isDowngrade ? 'next_cycle' : 'immediate';

        setLoadingPreview(true);
        try {
            const { data, error } = await supabase.functions.invoke('billing-ops', {
                body: {
                    action: 'preview_change',
                    tenantId: profile?.tenant_id,
                    subscriptionId: subscription.id,
                    newPlanCode: plan.codigo_plano,
                    newSeats: seats ? { profissional: seats } : {},
                    effective: effective
                }
            });

            if (error) throw error;
            setPreviewData(data);
        } catch (error) {
            console.error("Error fetching preview:", error);
            toast({
                title: "Erro ao calcular valores",
                description: "Tente novamente mais tarde.",
                variant: "destructive"
            });
        } finally {
            setLoadingPreview(false);
        }
    };

    const handleConfirmChange = async () => {
        if (!subscription || !selectedPlan || !previewData) return;
        setProcessingChange(true);
        try {
            // If changing plan
            if (selectedPlan.codigo_plano !== subscription.codigo_plano) {
                const currentPlanPrice = plans.find(p => p.codigo_plano === subscription.codigo_plano)?.preco_mensal_brl || 0;
                const isDowngrade = selectedPlan.preco_mensal_brl < currentPlanPrice;
                const effective = isDowngrade ? 'next_cycle' : 'immediate';

                const { error } = await supabase.functions.invoke('billing-ops', {
                    body: {
                        action: 'change_plan',
                        tenantId: profile?.tenant_id,
                        subscriptionId: subscription.id,
                        newPlanCode: selectedPlan.codigo_plano,
                        effective: effective
                    }
                });
                if (error) throw error;
            }

            // If company plan and seats changed (or just switched to company)
            if (selectedPlan.codigo_plano === 'company_base') {
                const { error } = await supabase.functions.invoke('billing-ops', {
                    body: {
                        action: 'change_seats',
                        tenantId: profile?.tenant_id,
                        subscriptionId: subscription.id,
                        type: 'profissional',
                        newQuantity: companySeats
                    }
                });
                if (error) throw error;
            }

            toast({
                title: "Plano alterado com sucesso!",
                description: "As alterações já estão em vigor."
            });
            setIsDialogOpen(false);
            fetchData(); // Refresh
        } catch (error) {
            console.error("Error changing plan:", error);
            toast({
                title: "Erro ao alterar plano",
                description: "Não foi possível processar a alteração.",
                variant: "destructive"
            });
        } finally {
            setProcessingChange(false);
        }
    };

    if (loading) {
        return <div className="flex justify-center p-8"><Loader2 className="animate-spin" /></div>;
    }

    return (
        <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                {plans.map((plan) => {
                    const isCurrent = subscription?.codigo_plano === plan.codigo_plano;
                    return (
                        <Card key={plan.codigo_plano} className={`p-6 flex flex-col ${isCurrent ? 'border-primary ring-1 ring-primary' : ''}`}>
                            <div className="flex justify-between items-start mb-4">
                                <div>
                                    <h3 className="text-xl font-bold">{plan.descricao}</h3>
                                    <p className="text-2xl font-bold mt-2">
                                        R$ {plan.preco_mensal_brl.toFixed(2)}
                                        <span className="text-sm font-normal text-muted-foreground">/mês</span>
                                    </p>
                                </div>
                                {isCurrent && <Badge>Atual</Badge>}
                            </div>

                            <ul className="space-y-2 mb-6 flex-1">
                                {plan.features.map((feature, idx) => (
                                    <li key={idx} className="flex items-center text-sm">
                                        <Check className="h-4 w-4 text-green-500 mr-2" />
                                        {feature}
                                    </li>
                                ))}
                            </ul>

                            <Button
                                variant={isCurrent ? "outline" : "default"}
                                className="w-full"
                                onClick={() => handleSelectPlan(plan)}
                                disabled={isCurrent && plan.codigo_plano !== 'company_base'} // Allow clicking current if company (to change seats)
                            >
                                {isCurrent ? (plan.codigo_plano === 'company_base' ? "Gerenciar Seats" : "Plano Atual") : "Selecionar Plano"}
                            </Button>
                        </Card>
                    );
                })}
            </div>

            <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
                <DialogContent className="sm:max-w-[500px]">
                    <DialogHeader>
                        <DialogTitle>Confirmar Alteração de Plano</DialogTitle>
                        <DialogDescription>
                            Revise os detalhes da alteração antes de confirmar.
                        </DialogDescription>
                    </DialogHeader>

                    {selectedPlan?.codigo_plano === 'company_base' && (
                        <div className="py-4 border-b">
                            <Label>Número de Profissionais</Label>
                            <div className="flex items-center gap-4 mt-2">
                                <Button
                                    variant="outline"
                                    size="sm"
                                    onClick={() => {
                                        const newVal = Math.max(1, companySeats - 1);
                                        setCompanySeats(newVal);
                                        fetchPreview(selectedPlan, newVal);
                                    }}
                                >-</Button>
                                <span className="text-lg font-bold">{companySeats}</span>
                                <Button
                                    variant="outline"
                                    size="sm"
                                    onClick={() => {
                                        const newVal = companySeats + 1;
                                        setCompanySeats(newVal);
                                        fetchPreview(selectedPlan, newVal);
                                    }}
                                >+</Button>
                            </div>
                            <p className="text-sm text-muted-foreground mt-2">
                                {companySeats <= 5 ? "Incluso no plano (até 5)" : `${companySeats - 5} profissional(is) extra(s)`}
                            </p>
                        </div>
                    )}

                    {loadingPreview ? (
                        <div className="py-8 flex justify-center"><Loader2 className="animate-spin" /></div>
                    ) : previewData ? (
                        <div className="space-y-4 py-4">
                            <div className="flex justify-between text-sm">
                                <span>Plano Atual:</span>
                                <span className="font-medium">{previewData.current_plan.name}</span>
                            </div>
                            <div className="flex justify-between text-sm">
                                <span>Novo Plano:</span>
                                <span className="font-medium">{previewData.new_plan.name}</span>
                            </div>

                            <div className="border-t pt-2 mt-2">
                                <div className="flex justify-between text-sm">
                                    <span>Valor Pró-rata (Hoje):</span>
                                    <span className="font-bold text-primary">R$ {previewData.total_now.toFixed(2)}</span>
                                </div>
                                <p className="text-xs text-muted-foreground">Cobrado imediatamente no cartão cadastrado.</p>
                            </div>

                            <div className="bg-muted p-3 rounded-md mt-2">
                                <div className="flex justify-between text-sm font-medium">
                                    <span>Próxima Mensalidade:</span>
                                    <span>R$ {previewData.next_cycle_total.toFixed(2)}</span>
                                </div>
                                <p className="text-xs text-muted-foreground mt-1">A partir de {new Date(previewData.effective_date).toLocaleDateString()}</p>
                            </div>
                        </div>
                    ) : (
                        <div className="py-4 text-center text-red-500">Erro ao carregar preview.</div>
                    )}

                    <DialogFooter>
                        <Button variant="outline" onClick={() => setIsDialogOpen(false)}>Cancelar</Button>
                        <Button onClick={handleConfirmChange} disabled={processingChange || loadingPreview}>
                            {processingChange ? <Loader2 className="animate-spin mr-2" /> : null}
                            Confirmar Alteração
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>
        </div>
    );
};

export default PlanosConfig;

import { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import {
  Stethoscope,
  Sparkles,
  Dog,
  Scissors,
  GraduationCap,
  Wrench,
  Loader2,
  Info,
  Lock
} from 'lucide-react';
import { supabase } from '@/integrations/supabase/client';
import { useAuth } from '@/hooks/useAuth';

const SEGMENTOS = [
  { codigo: 'saude', nome: 'Saúde', icone: Stethoscope, descricao: 'Clínicas, consultórios médicos' },
  { codigo: 'estetica', nome: 'Estética & Beleza', icone: Sparkles, descricao: 'Estúdios, SPAs, salões' },
  { codigo: 'veterinaria', nome: 'Veterinária', icone: Dog, descricao: 'Clínicas veterinárias, pet shops' },
  { codigo: 'odontologia', nome: 'Odontologia', icone: Scissors, descricao: 'Consultórios odontológicos' },
  { codigo: 'educacao', nome: 'Educação & Cursos', icone: GraduationCap, descricao: 'Escolas, cursos, treinamentos' },
  { codigo: 'oficina', nome: 'Oficina & Serviços', icone: Wrench, descricao: 'Mecânicas, assistências técnicas' },
];

export default function SegmentoConfig() {
  const { profile } = useAuth();
  const [segmentoAtual, setSegmentoAtual] = useState<string>('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchCurrentSegment();
  }, [profile?.tenant_id]);

  const fetchCurrentSegment = async () => {
    if (!profile?.tenant_id) return;

    try {
      const { data, error } = await supabase
        .from('tenant_profile')
        .select('segmentos')
        .eq('tenant_id', profile.tenant_id)
        .single();

      if (error) throw error;

      const segmentos = data?.segmentos as Array<{ codigo: string }> | null;
      const codigo = segmentos?.[0]?.codigo || '';
      setSegmentoAtual(codigo);
    } catch (error) {
      console.error('Error fetching segment:', error);
    } finally {
      setLoading(false);
    }
  };

  const segmentoInfo = SEGMENTOS.find(s => s.codigo === segmentoAtual);

  if (loading) {
    return (
      <Card>
        <CardContent className="flex items-center justify-center py-8">
          <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      <Alert>
        <Info className="h-4 w-4" />
        <AlertTitle>Configuração Permanente</AlertTitle>
        <AlertDescription>
          O segmento de atuação define a estrutura de dados e terminologias do sistema.
          Para garantir a integridade das suas informações, ele não pode ser alterado após a criação da conta.
        </AlertDescription>
      </Alert>

      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            {segmentoInfo && <segmentoInfo.icone className="h-5 w-5" />}
            Segmento do Negócio
          </CardTitle>
          <CardDescription>
            Seu ambiente está configurado para o seguinte segmento:
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
            {SEGMENTOS.map(seg => {
              const Icon = seg.icone;
              const isCurrent = segmentoAtual === seg.codigo;

              return (
                <div
                  key={seg.codigo}
                  className={`p-4 rounded-lg border-2 transition-all relative ${isCurrent
                      ? 'border-primary bg-primary/5'
                      : 'border-border opacity-50 grayscale'
                    }`}
                >
                  {!isCurrent && (
                    <div className="absolute top-2 right-2">
                      <Lock className="h-4 w-4 text-muted-foreground" />
                    </div>
                  )}

                  <div className="flex items-start gap-3">
                    <div className={`p-2 rounded-lg ${isCurrent ? 'bg-primary text-primary-foreground' : 'bg-muted'}`}>
                      <Icon className="h-5 w-5" />
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2">
                        <h4 className="font-medium truncate">{seg.nome}</h4>
                        {isCurrent && <Badge variant="default" className="text-xs">Atual</Badge>}
                      </div>
                      <p className="text-sm text-muted-foreground truncate">{seg.descricao}</p>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

import React, { useState, useEffect } from "react";
import { StatsCard } from "./StatsCard";
import { AppointmentCard } from "./AppointmentCard";
import { WhatsAppCreditsWidget } from "./WhatsAppCreditsWidget";
import {
  Calendar,
  Users,
  CheckCircle,
  AlertTriangle,
  Clock,
  MessageSquare
} from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { format, startOfDay, endOfDay, addHours } from "date-fns";

export function DashboardOverview() {
  const [todayStats, setTodayStats] = useState({
    totalAppointments: 0,
    confirmed: 0,
    pending: 0,
    completed: 0,
    noShows: 0,
    waitingList: 0
  });
  const [upcomingAppointments, setUpcomingAppointments] = useState<any[]>([]);
  const [alerts, setAlerts] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    fetchDashboardData();

    // Realtime subscription
    const channel = supabase
      .channel('dashboard-updates')
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'agenda'
        },
        () => {
          fetchDashboardData();
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, []);

  const fetchDashboardData = async () => {
    try {
      setIsLoading(true);
      const now = new Date();
      const dayStart = startOfDay(now);
      const dayEnd = endOfDay(now);
      const nextTwoHours = addHours(now, 2);

      // Buscar agendamentos de hoje
      const { data: todayAppointments, error: todayError } = await supabase
        .from('agenda')
        .select(`
          id,
          status,
          confirmado,
          inicio,
          fim,
          pacientes (
            nome,
            telefone,
            historico_faltas,
            risco_no_show
          ),
          profiles:profissional_id (
            nome
          )
        `)
        .gte('inicio', dayStart.toISOString())
        .lte('inicio', dayEnd.toISOString())
        .order('inicio');

      if (todayError) throw todayError;

      // Calcular estatísticas
      const stats = {
        totalAppointments: todayAppointments?.length || 0,
        confirmed: todayAppointments?.filter(apt => apt.confirmado).length || 0,
        pending: todayAppointments?.filter(apt => !apt.confirmado && apt.status === 'agendado').length || 0,
        completed: todayAppointments?.filter(apt => apt.status === 'concluido').length || 0,
        noShows: todayAppointments?.filter(apt => apt.status === 'falta').length || 0,
        waitingList: 0 // Será atualizado depois com tabela lista_espera
      };

      setTodayStats(stats);

      // Buscar próximas consultas (próximas 2 horas)
      const { data: upcoming, error: upcomingError } = await supabase
        .from('agenda')
        .select(`
          id,
          inicio,
          status,
          confirmado,
          pacientes (
            nome,
            telefone,
            historico_faltas,
            risco_no_show
          ),
          profiles:profissional_id (
            nome
          )
        `)
        .gte('inicio', now.toISOString())
        .lte('inicio', nextTwoHours.toISOString())
        .eq('status', 'agendado')
        .order('inicio')
        .limit(4);

      if (upcomingError) throw upcomingError;

      // Formatar dados para o componente
      const formattedUpcoming = (upcoming || []).map((apt: any) => {
        const risco = apt.pacientes?.risco_no_show || 0;
        let status: "confirmed" | "pending" | "risk-high" | "risk-medium" = "pending";

        if (apt.confirmado) {
          status = "confirmed";
        } else if (risco > 70) {
          status = "risk-high";
        } else if (risco > 30) {
          status = "risk-medium";
        }

        return {
          id: apt.id,
          patientName: apt.pacientes?.nome || "Paciente",
          time: format(new Date(apt.inicio), 'HH:mm'),
          doctor: apt.profiles?.nome || "Profissional",
          status,
          phone: apt.pacientes?.telefone || ""
        };
      });

      setUpcomingAppointments(formattedUpcoming);

      // Buscar lista de espera
      const { data: waitingList, error: waitingError } = await supabase
        .from('lista_espera')
        .select('id')
        .eq('ativo', true);

      if (!waitingError && waitingList) {
        setTodayStats(prev => ({ ...prev, waitingList: waitingList.length }));
      }

      // Gerar alertas dinâmicos
      const generatedAlerts = [];

      // Alerta de alto risco
      const highRiskApt = upcoming?.find((apt: any) => apt.pacientes?.risco_no_show > 70);
      if (highRiskApt) {
        generatedAlerts.push({
          type: 'risk-high',
          title: 'Alto Risco de Falta',
          message: `${highRiskApt.pacientes?.nome} (${format(new Date(highRiskApt.inicio), 'HH:mm')}) tem histórico de ${highRiskApt.pacientes?.historico_faltas || 0} faltas recentes.`,
          actions: ['Ligar Agora', 'Enviar WhatsApp']
        });
      }

      // Alerta de confirmações pendentes
      if (stats.pending > 0) {
        generatedAlerts.push({
          type: 'pending',
          title: 'Confirmações Pendentes',
          message: `${stats.pending} pacientes ainda não confirmaram presença para hoje.`,
          actions: ['Enviar Lembretes']
        });
      }

      // Alerta de sucesso se não houver faltas
      if (stats.noShows === 0 && stats.completed > 0) {
        generatedAlerts.push({
          type: 'success',
          title: 'Desempenho Excelente',
          message: 'Nenhuma falta registrada hoje! Continue o bom trabalho.',
          actions: []
        });
      }

      setAlerts(generatedAlerts);

    } catch (error) {
      console.error('Erro ao buscar dados do dashboard:', error);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="space-y-6">
      {/* Stats Grid - Only show when there's data */}
      {todayStats.totalAppointments > 0 && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-4" data-tour="dashboard-stats">
          <StatsCard
            title="Total Hoje"
            value={todayStats.totalAppointments}
            icon={Calendar}
            variant="default"
          />
          <StatsCard
            title="Confirmados"
            value={todayStats.confirmed}
            icon={CheckCircle}
            variant="success"
          />
          <StatsCard
            title="Pendentes"
            value={todayStats.pending}
            icon={Clock}
            variant="warning"
          />
          <StatsCard
            title="Realizados"
            value={todayStats.completed}
            icon={Users}
            variant="success"
          />
          <StatsCard
            title="Faltas"
            value={todayStats.noShows}
            icon={AlertTriangle}
            variant="destructive"
          />
          <StatsCard
            title="Lista Espera"
            value={todayStats.waitingList}
            icon={MessageSquare}
            variant="default"
          />
        </div>
      )}

      {/* Próximas Consultas e WhatsApp Credits */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2">
          <h3 className="text-lg font-semibold text-foreground mb-4">
            Próximas Consultas (Próximas 2h)
          </h3>
          {isLoading ? (
            <div className="text-center py-8">
              <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary mx-auto"></div>
            </div>
          ) : upcomingAppointments.length === 0 ? (
            <div className="p-4 bg-muted rounded-lg text-center">
              <p className="text-sm text-muted-foreground">Nenhuma consulta nas próximas 2 horas</p>
            </div>
          ) : (
            <div className="space-y-3">
              {upcomingAppointments.map((appointment) => (
                <AppointmentCard
                  key={appointment.id}
                  {...appointment}
                />
              ))}
            </div>
          )}
        </div>

        {/* Widget de Créditos WhatsApp */}
        <div>
          <WhatsAppCreditsWidget />
        </div>
      </div>

      {/* Painel de Alertas */}
      <div>
        <h3 className="text-lg font-semibold text-foreground mb-4">
          Alertas e Ações Recomendadas
        </h3>
        {isLoading ? (
          <div className="text-center py-8">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary mx-auto"></div>
          </div>
        ) : alerts.length === 0 ? (
          <div className="p-4 bg-muted rounded-lg text-center">
            <p className="text-sm text-muted-foreground">Nenhum alerta no momento</p>
          </div>
        ) : (
          <div className="space-y-3">
            {alerts.map((alert, index) => (
              <div
                key={index}
                className={`p-4 rounded-lg border ${alert.type === 'risk-high'
                    ? 'bg-destructive-light border-destructive/20'
                    : alert.type === 'pending'
                      ? 'bg-warning-light border-warning/20'
                      : 'bg-success-light border-success/20'
                  }`}
              >
                <div className="flex items-center gap-2 mb-2">
                  {alert.type === 'risk-high' && <AlertTriangle className="h-5 w-5 text-destructive" />}
                  {alert.type === 'pending' && <Clock className="h-5 w-5 text-warning" />}
                  {alert.type === 'success' && <CheckCircle className="h-5 w-5 text-success" />}
                  <h4 className={`font-medium ${alert.type === 'risk-high'
                      ? 'text-destructive'
                      : alert.type === 'pending'
                        ? 'text-warning'
                        : 'text-success'
                    }`}>
                    {alert.title}
                  </h4>
                </div>
                <p className="text-sm text-muted-foreground mb-3">
                  {alert.message}
                </p>
                {alert.actions.length > 0 && (
                  <div className="flex gap-2">
                    {alert.actions.map((action: string, i: number) => (
                      <button
                        key={i}
                        className={`px-3 py-1 text-xs rounded ${i === 0
                            ? alert.type === 'risk-high'
                              ? 'bg-destructive text-destructive-foreground'
                              : 'bg-warning text-warning-foreground'
                            : 'bg-background border border-current'
                          }`}
                      >
                        {action}
                      </button>
                    ))}
                  </div>
                )}
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

import { useEffect, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { MessageSquare, TrendingUp, AlertCircle } from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { useNavigate } from "react-router-dom";
import { toast } from "sonner";

export const WhatsAppCreditsWidget = () => {
  const [credits, setCredits] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    loadCredits();
  }, []);

  const loadCredits = async () => {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      const { data: profile } = await supabase
        .from("profiles")
        .select("tenant_id")
        .eq("id", user.id)
        .single();

      if (!profile?.tenant_id) return;

      const { data, error } = await supabase
        .from("tenant_whatsapp_credits")
        .select("*")
        .eq("tenant_id", profile.tenant_id)
        .single();

      if (error && error.code !== "PGRST116") throw error;
      setCredits(data);
    } catch (error: any) {
      console.error("Erro ao carregar créditos:", error);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <MessageSquare className="h-5 w-5" />
            Créditos WhatsApp
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="animate-pulse space-y-3">
            <div className="h-8 bg-muted rounded"></div>
            <div className="h-4 bg-muted rounded w-2/3"></div>
          </div>
        </CardContent>
      </Card>
    );
  }

  const saldoCreditos = credits?.saldo_creditos || 0;
  const creditosConsumidos = credits?.creditos_consumidos || 0;
  const limiarAlerta = credits?.limiar_alerta || 100;
  
  const percentualUsado = creditosConsumidos > 0 
    ? ((creditosConsumidos / (creditosConsumidos + saldoCreditos)) * 100).toFixed(1)
    : "0";

  const status = saldoCreditos <= 0 
    ? "critical" 
    : saldoCreditos <= limiarAlerta 
    ? "warning" 
    : "good";

  const statusConfig = {
    good: { color: "bg-green-500", text: "Saldo Bom", icon: TrendingUp },
    warning: { color: "bg-yellow-500", text: "Saldo Baixo", icon: AlertCircle },
    critical: { color: "bg-red-500", text: "Sem Créditos", icon: AlertCircle },
  };

  const config = statusConfig[status];
  const StatusIcon = config.icon;

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <MessageSquare className="h-5 w-5" />
            Créditos WhatsApp
          </div>
          <Badge variant={status === "good" ? "default" : "destructive"}>
            <StatusIcon className="h-3 w-3 mr-1" />
            {config.text}
          </Badge>
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="space-y-2">
          <div className="flex justify-between items-center">
            <span className="text-sm text-muted-foreground">Saldo Disponível</span>
            <span className="text-2xl font-bold">{saldoCreditos.toLocaleString()}</span>
          </div>
          <div className="flex justify-between items-center text-sm">
            <span className="text-muted-foreground">Consumidos no Mês</span>
            <span className="font-medium">{creditosConsumidos.toLocaleString()}</span>
          </div>
          <div className="flex justify-between items-center text-sm">
            <span className="text-muted-foreground">Taxa de Uso</span>
            <span className="font-medium">{percentualUsado}%</span>
          </div>
        </div>

        <div className="w-full bg-muted rounded-full h-2">
          <div
            className={`h-2 rounded-full transition-all ${config.color}`}
            style={{ width: `${Math.min(100, parseFloat(percentualUsado))}%` }}
          />
        </div>

        <Button
          onClick={() => navigate("/configuracoes-whatsapp")}
          className="w-full"
          variant={status === "critical" ? "destructive" : "default"}
        >
          {status === "critical" ? "Comprar Créditos Agora" : "Gerenciar Créditos"}
        </Button>
      </CardContent>
    </Card>
  );
};

import { useState, useEffect } from 'react';
import { supabase } from "@/integrations/supabase/client";
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { useToast } from '@/components/ui/use-toast';
import { Card } from '@/components/ui/card';
import { Loader2 } from 'lucide-react';

interface Professional {
    id: string;
    nome: string;
    email: string;
}

interface CommissionConfig {
    id?: string;
    professional_id: string;
    percentage: number;
    fixed_value: number;
}

export function CommissionSettings() {
    const [professionals, setProfessionals] = useState<Professional[]>([]);
    const [configs, setConfigs] = useState<Record<string, CommissionConfig>>({});
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const { toast } = useToast();

    useEffect(() => {
        fetchData();
    }, []);

    const fetchData = async () => {
        setLoading(true);
        try {
            // 1. Fetch professionals linked to this tenant
            // Assuming we can get profiles with role 'professional' and same tenant
            const { data: profiles, error: profilesError } = await supabase
                .from('profiles')
                .select('id, nome, email')
                .eq('role', 'professional'); // Filter by tenant_id is handled by RLS usually, but let's be safe if needed

            if (profilesError) throw profilesError;

            // 2. Fetch existing commission configs
            const { data: commissionConfigs, error: configError } = await supabase
                .from('professional_commissions')
                .select('*');

            if (configError) throw configError;

            const configMap: Record<string, CommissionConfig> = {};
            commissionConfigs?.forEach((c: CommissionConfig) => {
                configMap[c.professional_id] = c;
            });

            setProfessionals(profiles || []);
            setConfigs(configMap);

        } catch (error) {
            console.error("Error fetching commission data:", error);
            toast({
                title: "Erro ao carregar dados",
                description: "Não foi possível carregar as configurações de comissão.",
                variant: "destructive"
            });
        } finally {
            setLoading(false);
        }
    };

    const handleSave = async (professionalId: string) => {
        setSaving(true);
        try {
            const config = configs[professionalId];
            if (!config) return;

            const { data: { user } } = await supabase.auth.getUser();
            if (!user) return;

            // Get tenant_id from profile
            const { data: profile } = await supabase
                .from('profiles')
                .select('tenant_id')
                .eq('id', user.id)
                .single();

            if (!profile) throw new Error("Profile not found");

            const payload = {
                tenant_id: profile.tenant_id,
                professional_id: professionalId,
                percentage: config.percentage || 0,
                fixed_value: config.fixed_value || 0
            };

            const { error } = await supabase
                .from('professional_commissions')
                .upsert(payload, { onConflict: 'tenant_id, professional_id' });

            if (error) throw error;

            toast({
                title: "Sucesso",
                description: "Comissão atualizada com sucesso."
            });

        } catch (error) {
            console.error("Error saving commission:", error);
            toast({
                title: "Erro ao salvar",
                description: "Não foi possível salvar a comissão.",
                variant: "destructive"
            });
        } finally {
            setSaving(false);
        }
    };

    const handleChange = (professionalId: string, field: 'percentage' | 'fixed_value', value: string) => {
        const numValue = parseFloat(value) || 0;
        setConfigs(prev => ({
            ...prev,
            [professionalId]: {
                ...prev[professionalId],
                professional_id: professionalId,
                [field]: numValue
            }
        }));
    };

    if (loading) return <div className="flex justify-center p-8"><Loader2 className="animate-spin" /></div>;

    return (
        <div className="space-y-6">
            <h3 className="text-lg font-semibold">Configuração de Comissões</h3>
            <p className="text-sm text-muted-foreground">Defina a porcentagem ou valor fixo que cada profissional recebe por atendimento.</p>

            <div className="grid gap-4">
                {professionals.map(prof => (
                    <Card key={prof.id} className="p-4 flex items-center justify-between gap-4">
                        <div className="flex-1">
                            <p className="font-medium">{prof.nome || prof.email}</p>
                            <p className="text-xs text-muted-foreground">{prof.email}</p>
                        </div>

                        <div className="flex items-end gap-2">
                            <div>
                                <Label className="text-xs">Porcentagem (%)</Label>
                                <Input
                                    type="number"
                                    className="w-24"
                                    value={configs[prof.id]?.percentage ?? ''}
                                    onChange={(e) => handleChange(prof.id, 'percentage', e.target.value)}
                                    placeholder="0%"
                                />
                            </div>
                            <div>
                                <Label className="text-xs">Valor Fixo (R$)</Label>
                                <Input
                                    type="number"
                                    className="w-24"
                                    value={configs[prof.id]?.fixed_value ?? ''}
                                    onChange={(e) => handleChange(prof.id, 'fixed_value', e.target.value)}
                                    placeholder="R$ 0,00"
                                />
                            </div>
                            <Button
                                size="sm"
                                onClick={() => handleSave(prof.id)}
                                disabled={saving}
                            >
                                Salvar
                            </Button>
                        </div>
                    </Card>
                ))}
                {professionals.length === 0 && (
                    <p className="text-sm text-muted-foreground text-center py-8">Nenhum profissional encontrado nesta clínica.</p>
                )}
            </div>
        </div>
    );
}

import React, { useState, useEffect } from "react";
import { Bell, CheckCheck, AlertCircle, Clock, XCircle } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { ScrollArea } from "@/components/ui/scroll-area";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { toast } from "@/hooks/use-toast";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";

interface Alert {
  id: string;
  tipo: string;
  prioridade: string;
  titulo: string;
  descricao: string;
  created_at: string;
  lido: boolean;
  paciente_id: string;
  agendamento_id: string | null;
}

export function AlertsPopover() {
  const { profile } = useAuth();
  const [alerts, setAlerts] = useState<Alert[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [isOpen, setIsOpen] = useState(false);

  useEffect(() => {
    fetchAlerts();

    // Subscribe to realtime updates
    const channel = supabase
      .channel('alertas-changes')
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'alertas_risco',
          filter: `tenant_id=eq.${profile?.tenant_id}`
        },
        () => {
          fetchAlerts();
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [profile?.tenant_id]);

  const fetchAlerts = async () => {
    if (!profile?.tenant_id) return;

    try {
      const { data, error } = await supabase
        .from('alertas_risco')
        .select('*')
        .eq('tenant_id', profile.tenant_id)
        .eq('resolvido', false)
        .order('created_at', { ascending: false })
        .limit(20);

      if (error) throw error;

      setAlerts(data || []);
      setUnreadCount(data?.filter(a => !a.lido).length || 0);
    } catch (error) {
      console.error('Erro ao buscar alertas:', error);
    }
  };

  const markAsRead = async (alertId: string) => {
    try {
      const { error } = await supabase
        .from('alertas_risco')
        .update({
          lido: true,
          lido_em: new Date().toISOString(),
          lido_por: profile?.id
        })
        .eq('id', alertId);

      if (error) throw error;

      setAlerts(prev => 
        prev.map(a => a.id === alertId ? { ...a, lido: true } : a)
      );
      setUnreadCount(prev => Math.max(0, prev - 1));
    } catch (error) {
      console.error('Erro ao marcar alerta como lido:', error);
      toast({
        title: "Erro",
        description: "Não foi possível marcar o alerta como lido",
        variant: "destructive"
      });
    }
  };

  const markAllAsRead = async () => {
    if (!profile?.tenant_id) return;

    try {
      const { error } = await supabase
        .from('alertas_risco')
        .update({
          lido: true,
          lido_em: new Date().toISOString(),
          lido_por: profile?.id
        })
        .eq('tenant_id', profile.tenant_id)
        .eq('lido', false)
        .eq('resolvido', false);

      if (error) throw error;

      setAlerts(prev => prev.map(a => ({ ...a, lido: true })));
      setUnreadCount(0);

      toast({
        title: "Sucesso",
        description: "Todos os alertas foram marcados como lidos"
      });
    } catch (error) {
      console.error('Erro ao marcar todos como lidos:', error);
      toast({
        title: "Erro",
        description: "Não foi possível marcar todos os alertas como lidos",
        variant: "destructive"
      });
    }
  };

  const getAlertIcon = (tipo: string) => {
    switch (tipo) {
      case 'risco_no_show':
        return <XCircle className="h-4 w-4 text-destructive" />;
      case 'confirmacao_pendente':
        return <Clock className="h-4 w-4 text-warning" />;
      case 'atraso':
        return <AlertCircle className="h-4 w-4 text-warning" />;
      default:
        return <AlertCircle className="h-4 w-4 text-muted-foreground" />;
    }
  };

  const getPriorityColor = (prioridade: string) => {
    switch (prioridade) {
      case 'alta':
        return 'border-l-destructive bg-destructive-light';
      case 'media':
        return 'border-l-warning bg-warning-light';
      case 'baixa':
        return 'border-l-success bg-success-light';
      default:
        return 'border-l-muted';
    }
  };

  return (
    <Popover open={isOpen} onOpenChange={setIsOpen}>
      <PopoverTrigger asChild>
        <Button variant="ghost" size="icon" className="relative">
          <Bell className="h-5 w-5" />
          {unreadCount > 0 && (
            <Badge 
              variant="destructive" 
