            >
              {unreadCount > 9 ? '9+' : unreadCount}
            </Badge>
          )}
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-96 p-0" align="end">
        <div className="flex items-center justify-between p-4 border-b">
          <h3 className="font-semibold text-foreground">Alertas</h3>
          {unreadCount > 0 && (
            <Button 
              variant="ghost" 
              size="sm" 
              onClick={markAllAsRead}
              className="h-8 text-xs"
            >
              <CheckCheck className="h-4 w-4 mr-1" />
              Marcar todos como lidos
            </Button>
          )}
        </div>

        <ScrollArea className="h-[400px]">
          {alerts.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-12 px-4 text-center">
              <Bell className="h-12 w-12 text-muted-foreground/50 mb-3" />
              <p className="text-sm text-muted-foreground">
                Nenhum alerta no momento
              </p>
            </div>
          ) : (
            <div className="divide-y">
              {alerts.map((alert) => (
                <div
                  key={alert.id}
                  className={`p-4 border-l-4 transition-colors hover:bg-accent/50 ${
                    !alert.lido ? 'bg-accent/20' : ''
                  } ${getPriorityColor(alert.prioridade)}`}
                >
                  <div className="flex items-start gap-3">
                    <div className="mt-1">{getAlertIcon(alert.tipo)}</div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-start justify-between gap-2">
                        <h4 className="text-sm font-medium text-foreground">
                          {alert.titulo}
                        </h4>
                        {!alert.lido && (
                          <Badge variant="secondary" className="shrink-0 text-xs">
                            Novo
                          </Badge>
                        )}
                      </div>
                      <p className="text-xs text-muted-foreground mt-1">
                        {alert.descricao}
                      </p>
                      <div className="flex items-center justify-between mt-2">
                        <span className="text-xs text-muted-foreground">
                          {format(new Date(alert.created_at), "dd/MM 'às' HH:mm", { locale: ptBR })}
                        </span>
                        {!alert.lido && (
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => markAsRead(alert.id)}
                            className="h-6 text-xs"
                          >
                            Marcar como lido
                          </Button>
                        )}
                      </div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </ScrollArea>
      </PopoverContent>
    </Popover>
  );
}

import { useState, useEffect } from 'react';
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { useToast } from "@/components/ui/use-toast";
import { Scale, Plus, FileText, Calendar, Gavel } from 'lucide-react';
import { format } from 'date-fns';

interface LegalCase {
    id: string;
    title: string; // "Processo vs Empresa X"
    status: 'open' | 'in_progress' | 'waiting_hearing' | 'closed';
    customer_id: string;
    customer_name?: string;
    process_number?: string;
    court?: string; // Tribunal
    next_deadline?: string;
    created_at: string;
}

export function LegalDashboard() {
    const [cases, setCases] = useState<LegalCase[]>([]);
    const [loading, setLoading] = useState(true);
    const { toast } = useToast();

    useEffect(() => {
        fetchCases();
    }, []);

    const fetchCases = async () => {
        setLoading(true);
        try {
            const { data, error } = await supabase
                .from('service_files')
                .select(`
                    *,
                    pacientes (nome)
                `)
                .eq('type', 'processo')
                .order('created_at', { ascending: false });

            if (error) throw error;

            const formattedCases: LegalCase[] = data.map(item => ({
                id: item.id,
                title: item.title,
                status: item.status as any,
                customer_id: item.customer_id,
                customer_name: item.pacientes?.nome,
                process_number: item.content?.process_number,
                court: item.content?.court,
                next_deadline: item.content?.next_deadline,
                created_at: item.created_at
            }));

            setCases(formattedCases);
        } catch (error) {
            console.error("Error fetching cases:", error);
        } finally {
            setLoading(false);
        }
    };

    const getStatusLabel = (status: string) => {
        switch (status) {
            case 'open': return 'Inicial';
            case 'in_progress': return 'Em Andamento';
            case 'waiting_hearing': return 'Aguardando Audiência';
            case 'closed': return 'Encerrado';
            default: return status;
        }
    };

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <h2 className="text-2xl font-bold flex items-center gap-2">
                    <Scale className="h-6 w-6" />
                    Gestão de Processos
                </h2>
                <NewCaseDialog onSuccess={fetchCases} />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                {cases.map(legalCase => (
                    <Card key={legalCase.id} className="hover:shadow-md transition-shadow">
                        <CardHeader className="pb-2">
                            <div className="flex justify-between items-start">
                                <CardTitle className="text-lg font-medium truncate" title={legalCase.title}>
                                    {legalCase.title}
                                </CardTitle>
                                <Badge variant={legalCase.status === 'closed' ? 'secondary' : 'default'}>
                                    {getStatusLabel(legalCase.status)}
                                </Badge>
                            </div>
                            <p className="text-sm text-muted-foreground">{legalCase.customer_name}</p>
                        </CardHeader>
                        <CardContent className="space-y-3">
                            <div className="flex items-center gap-2 text-sm">
                                <Gavel className="h-4 w-4 text-muted-foreground" />
                                <span className="font-mono">{legalCase.process_number || 'N/A'}</span>
                            </div>
                            <div className="flex items-center gap-2 text-sm">
                                <FileText className="h-4 w-4 text-muted-foreground" />
                                <span>{legalCase.court || 'Tribunal não informado'}</span>
                            </div>
                            {legalCase.next_deadline && (
                                <div className="flex items-center gap-2 text-sm text-red-600 font-medium">
                                    <Calendar className="h-4 w-4" />
                                    <span>Prazo: {format(new Date(legalCase.next_deadline), 'dd/MM/yyyy')}</span>
                                </div>
                            )}
                        </CardContent>
                    </Card>
                ))}
                {cases.length === 0 && (
                    <div className="col-span-3 text-center py-12 text-muted-foreground">
                        Nenhum processo cadastrado.
                    </div>
                )}
            </div>
        </div>
    );
}

function NewCaseDialog({ onSuccess }: { onSuccess: () => void }) {
    const [open, setOpen] = useState(false);
    const [loading, setLoading] = useState(false);
    const [customers, setCustomers] = useState<any[]>([]);
    const [formData, setFormData] = useState({
        customer_id: '',
        title: '',
        process_number: '',
        court: '',
        next_deadline: ''
    });

    useEffect(() => {
        if (open) fetchCustomers();
    }, [open]);

    const fetchCustomers = async () => {
        const { data } = await supabase.from('pacientes').select('id, nome').order('nome');
        setCustomers(data || []);
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        try {
            const { data: { user } } = await supabase.auth.getUser();
            const { data: profile } = await supabase.from('profiles').select('tenant_id').eq('id', user?.id).single();

            await supabase.from('service_files').insert({
                tenant_id: profile?.tenant_id,
                customer_id: formData.customer_id,
                type: 'processo',
                title: formData.title,
                status: 'open',
                content: {
                    process_number: formData.process_number,
                    court: formData.court,
                    next_deadline: formData.next_deadline
                }
            });

            setOpen(false);
            onSuccess();
        } catch (error) {
            console.error(error);
        } finally {
            setLoading(false);
        }
    };

    return (
        <Dialog open={open} onOpenChange={setOpen}>
            <DialogTrigger asChild>
                <Button><Plus className="mr-2 h-4 w-4" /> Novo Processo</Button>
            </DialogTrigger>
            <DialogContent>
                <DialogHeader>
                    <DialogTitle>Cadastrar Processo</DialogTitle>
                </DialogHeader>
                <form onSubmit={handleSubmit} className="space-y-4">
                    <div>
                        <Label>Cliente</Label>
                        <select
                            className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background file:border-0 file:bg-transparent file:text-sm file:font-medium placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
                            value={formData.customer_id}
                            onChange={e => setFormData({ ...formData, customer_id: e.target.value })}
                            required
                        >
                            <option value="">Selecione...</option>
                            {customers.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
                        </select>
                    </div>
                    <div>
                        <Label>Título do Caso (Ex: Ação Trabalhista)</Label>
                        <Input
                            value={formData.title}
                            onChange={e => setFormData({ ...formData, title: e.target.value })}
                            required
                        />
                    </div>
                    <div>
                        <Label>Número do Processo (CNJ)</Label>
                        <Input
                            value={formData.process_number}
                            onChange={e => setFormData({ ...formData, process_number: e.target.value })}
                            placeholder="0000000-00.0000.0.00.0000"
                        />
                    </div>
                    <div>
                        <Label>Vara / Tribunal</Label>
                        <Input
                            value={formData.court}
                            onChange={e => setFormData({ ...formData, court: e.target.value })}
                            placeholder="Ex: 1ª Vara Cível de SP"
                        />
                    </div>
                    <div>
                        <Label>Próximo Prazo / Audiência</Label>
                        <Input
                            type="date"
                            value={formData.next_deadline}
                            onChange={e => setFormData({ ...formData, next_deadline: e.target.value })}
                        />
                    </div>
                    <Button type="submit" className="w-full" disabled={loading}>Cadastrar Processo</Button>
                </form>
            </DialogContent>
        </Dialog>
    );
}

import { useEffect, useState } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useAuth } from '@/hooks/useAuth';
import { Bell } from 'lucide-react';
import { Button } from '@/components/ui/button';
import {
    Popover,
    PopoverContent,
    PopoverTrigger,
} from '@/components/ui/popover';
import { Badge } from '@/components/ui/badge';
import { ScrollArea } from '@/components/ui/scroll-area';
import { format } from 'date-fns';
import { ptBR } from 'date-fns/locale';
import { toast } from 'sonner';
import { playNotificationSound, playUrgentNotificationSound } from '@/utils/notificationSound';

interface Alarme {
    id: string;
    titulo: string;
    descricao: string;
    tipo: 'alarme' | 'lembrete' | 'tarefa';
    prioridade: 'baixa' | 'media' | 'alta' | 'urgente';
    data_hora: string;
    concluido: boolean;
}

export function AlarmNotificationBell() {
    const { profile } = useAuth();
    const [alarmes, setAlarmes] = useState<Alarme[]>([]);
    const [unreadCount, setUnreadCount] = useState(0);

    useEffect(() => {
        if (!profile?.id) return;

        loadAlarmes();

        // Verificar alarmes a cada minuto
        const interval = setInterval(() => {
            checkForTriggeredAlarms();
        }, 60000); // 1 minuto

        // Subscription em tempo real
        const channel = supabase
            .channel('alarmes_changes')
            .on(
                'postgres_changes',
                {
                    event: '*',
                    schema: 'public',
                    table: 'alarmes_lembretes',
                    filter: `usuario_id=eq.${profile.id}`
                },
                () => {
                    loadAlarmes();
                }
            )
            .subscribe();

        return () => {
            clearInterval(interval);
            channel.unsubscribe();
        };
    }, [profile?.id]);

    const loadAlarmes = async () => {
        if (!profile?.id) return;

        try {
            const now = new Date();
            const { data, error } = await supabase
                .from('alarmes_lembretes')
                .select('*')
                .eq('usuario_id', profile.id)
                .eq('concluido', false)
                .eq('ativo', true)
                .lte('data_hora', now.toISOString())
                .order('data_hora', { ascending: false })
                .limit(10);

            if (error) throw error;

            setAlarmes(data || []);
            setUnreadCount(data?.length || 0);
        } catch (error) {
            console.error('Erro ao carregar alarmes:', error);
        }
    };

    const checkForTriggeredAlarms = async () => {
        if (!profile?.id) return;

        try {
            const now = new Date();
            const oneMinuteAgo = new Date(now.getTime() - 60000);

            const { data, error } = await supabase
                .from('alarmes_lembretes')
                .select('*')
                .eq('usuario_id', profile.id)
                .eq('concluido', false)
                .eq('ativo', true)
                .gte('data_hora', oneMinuteAgo.toISOString())
                .lte('data_hora', now.toISOString());

            if (error) throw error;

            // Se houver novos alarmes disparados
            if (data && data.length > 0) {
                data.forEach((alarme: any) => {
                    // Som diferente para urgente
                    if (alarme.prioridade === 'urgente') {
                        playUrgentNotificationSound();
                    } else {
                        playNotificationSound();
                    }
                    showNotification(alarme);
                });
                loadAlarmes();
            }
        } catch (error) {
            console.error('Erro ao verificar alarmes disparados:', error);
        }
    };

    const showNotification = (alarme: Alarme) => {
        const prioridadeEmoji = {
            baixa: '📌',
            media: '⚠️',
            alta: '🔔',
            urgente: '🚨'
        };

        toast.warning(
            `${prioridadeEmoji[alarme.prioridade]} ${alarme.titulo}`,
            {
                description: alarme.descricao,
                duration: 10000,
                action: {
                    label: 'Ver',
                    onClick: () => window.location.href = '/alarmes-lembretes'
                }
            }
        );
    };

    const marcarComoConcluido = async (id: string) => {
        try {
            const { error } = await supabase
                .from('alarmes_lembretes')
                .update({ concluido: true })
                .eq('id', id);

            if (error) throw error;

            toast.success('Alarme marcado como concluído');
            loadAlarmes();
        } catch (error) {
            console.error('Erro ao marcar alarme:', error);
            toast.error('Erro ao marcar alarme como concluído');
        }
    };

    const getPrioridadeColor = (prioridade: string) => {
        const colors = {
            baixa: 'bg-gray-100 text-gray-800',
            media: 'bg-yellow-100 text-yellow-800',
            alta: 'bg-orange-100 text-orange-800',
            urgente: 'bg-red-100 text-red-800'
        };
        return colors[prioridade as keyof typeof colors] || colors.media;
    };

    return (
        <Popover>
            <PopoverTrigger asChild>
                <Button variant="ghost" size="icon" className="relative">
                    <Bell className="h-5 w-5" />
                    {unreadCount > 0 && (
                        <Badge
                            variant="destructive"
                            className="absolute -top-1 -right-1 h-5 w-5 flex items-center justify-center p-0 text-xs"
                        >
                            {unreadCount > 9 ? '9+' : unreadCount}
                        </Badge>
                    )}
                </Button>
            </PopoverTrigger>
            <PopoverContent className="w-80" align="end">
                <div className="space-y-4">
                    <div className="flex items-center justify-between">
                        <h4 className="font-semibold">Alarmes Ativos</h4>
                        {unreadCount > 0 && (
                            <Badge variant="secondary">{unreadCount}</Badge>
                        )}
                    </div>

                    <ScrollArea className="h-[400px]">
                        {alarmes.length === 0 ? (
                            <div className="text-center py-8 text-muted-foreground">
                                <Bell className="h-12 w-12 mx-auto mb-2 opacity-50" />
                                <p>Nenhum alarme ativo</p>
                            </div>
                        ) : (
                            <div className="space-y-3">
                                {alarmes.map((alarme) => (
                                    <div
                                        key={alarme.id}
                                        className="p-3 border rounded-lg space-y-2 hover:bg-accent transition-colors"
                                    >
                                        <div className="flex items-start justify-between gap-2">
                                            <div className="flex-1">
                                                <h5 className="font-medium text-sm">{alarme.titulo}</h5>
                                                {alarme.descricao && (
                                                    <p className="text-xs text-muted-foreground mt-1">
                                                        {alarme.descricao}
                                                    </p>
                                                )}
                                            </div>
                                            <Badge className={getPrioridadeColor(alarme.prioridade)}>
                                                {alarme.prioridade}
                                            </Badge>
                                        </div>

                                        <div className="flex items-center justify-between">
                                            <span className="text-xs text-muted-foreground">
                                                {format(new Date(alarme.data_hora), "dd/MM/yyyy 'às' HH:mm", {
                                                    locale: ptBR
                                                })}
                                            </span>
                                            <Button
                                                size="sm"
                                                variant="outline"
                                                onClick={() => marcarComoConcluido(alarme.id)}
                                            >
                                                Concluir
                                            </Button>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}
                    </ScrollArea>

                    {alarmes.length > 0 && (
                        <Button
                            variant="outline"
                            className="w-full"
                            onClick={() => window.location.href = '/alarmes-lembretes'}
                        >
                            Ver Todos os Alarmes
                        </Button>
                    )}
                </div>
            </PopoverContent>
        </Popover>
    );
}

import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card } from "@/components/ui/card";
import { Checkbox } from "@/components/ui/checkbox";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { ArrowLeft, Plus, Trash2 } from "lucide-react";
import { useToast } from "@/hooks/use-toast";

interface OnboardingClinicaProps {
  onBack: () => void;
}

const SEGMENTS = [
  "Advocacia",
  "Aula Particular",
  "Consultoria",
  "Estética",
  "Fisioterapia",
  "Laboratório",
  "Lava-rápido",
  "Marcenaria",
  "Medicina",
  "Nutrição",
  "Odontologia",
  "Oficina",
  "Podologia",
  "Psicologia",
];

import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { PlanSelection } from "@/components/onboarding/PlanSelection";
import { fetchAddressByCEP } from "@/lib/cep";
import { toast as sonnerToast } from "sonner";

export function OnboardingClinica({ onBack }: OnboardingClinicaProps) {
  const navigate = useNavigate();
  const { toast } = useToast();
  const { user } = useAuth();
  const [step, setStep] = useState(1);
  const [planData, setPlanData] = useState<{ planCode: string; price: number; priceId?: string; seats?: number; couponCode?: string } | null>(null);
  const [formData, setFormData] = useState({
    name: "",
    razaoSocial: "",
    phone: "",
    cep: "",
    address: "",
    neighborhood: "",
    number: "",
    complement: "",
    city: "",
    state: "",
    segment: "",
    otherSegment: "",
    hasOtherSegment: false,
    scheduleMode: "professional",
    services: [{ name: "", duration: "", price: "", requiresConfirmation: false }],
    professionals: [{ name: "", phone: "" }],
    rooms: [{ name: "" }],
    primaryColor: "#016CA5",
    lgpdAccepted: false,
  });

  const handleCepBlur = async () => {
    if (formData.cep.length >= 8) {
      const address = await fetchAddressByCEP(formData.cep);
      if (address) {
        setFormData(prev => ({
          ...prev,
          address: address.logradouro,
          neighborhood: address.bairro,
          city: address.localidade,
          state: address.uf
        }));
      }
    }
  };

  const handleSegmentSelect = (value: string) => {
    setFormData((prev) => ({
      ...prev,
      segment: value,
      hasOtherSegment: false,
      otherSegment: ""
    }));
  };

  const handleOtherSegmentSelect = (checked: boolean) => {
    setFormData((prev) => ({
      ...prev,
      hasOtherSegment: checked,
      segment: checked ? "" : prev.segment,
      otherSegment: checked ? prev.otherSegment : ""
    }));
  };

  const addService = () => {
    setFormData((prev) => ({
      ...prev,
      services: [...prev.services, { name: "", duration: "", price: "", requiresConfirmation: false }],
    }));
  };

  const removeService = (index: number) => {
    setFormData((prev) => ({
      ...prev,
      services: prev.services.filter((_, i) => i !== index),
    }));
  };

  const handleServiceChange = (index: number, field: string, value: any) => {
    setFormData((prev) => ({
      ...prev,
      services: prev.services.map((service, i) =>
        i === index ? { ...service, [field]: value } : service
      ),
    }));
  };

  const addProfessional = () => {
    setFormData((prev) => ({
      ...prev,
      professionals: [...prev.professionals, { name: "", phone: "" }],
    }));
  };

  const addRoom = () => {
    setFormData((prev) => ({
      ...prev,
      rooms: [...prev.rooms, { name: "" }],
    }));
  };

  const handlePlanSelect = (selection: { planCode: string; price: number; priceId?: string; seats?: number; couponCode?: string }) => {
    setPlanData(selection);
    setStep(2);
  };

  const handleSubmit = async () => {
    if (!formData.lgpdAccepted) {
      toast({
        title: "Aceite necessário",
        description: "Você precisa aceitar os termos da LGPD para continuar.",
        variant: "destructive",
      });
      return;
    }

    if (!planData) {
      toast({
        title: "Plano não selecionado",
        description: "Por favor, selecione um plano.",
        variant: "destructive"
      });
      return;
    }

    try {
      console.log("[Onboarding] Iniciando cadastro de clínica...");
      let currentUser = user;

      if (!currentUser) {
        const { data: { user: fetchedUser }, error: userError } = await supabase.auth.getUser();
        if (userError || !fetchedUser) {
          sonnerToast.error("Sessão expirada. Faça login novamente.");
          return;
        }
        currentUser = fetchedUser;
      }

      // Check existing
      const { data: existingProfile } = await supabase
        .from("profiles")
        .select("tenant_id")
        .eq("id", currentUser.id)
        .single();

      if (existingProfile?.tenant_id) {
        navigate("/dashboard");
        return;
      }

      // Create Tenant
      const { data: tenant, error: tenantError } = await (supabase as any)
        .from("tenants")
        .insert({
          nome: formData.name,
          razao_social: formData.razaoSocial,
          tipo: "clinica",
          telefone: formData.phone,
          email: currentUser.email,
          cidade: formData.city,
          uf: formData.state,
          cep: formData.cep,
          logradouro: formData.address,
          bairro: formData.neighborhood,
          numero: formData.number,
          complemento: formData.complement,

          segmentos: formData.hasOtherSegment && formData.otherSegment
            ? [formData.otherSegment]
            : [formData.segment],
          modo_agendamento: formData.scheduleMode === "professional" ? "por_profissional" : "por_clinica_sala",
        })
        .select()
        .single();

      if (tenantError) throw tenantError;

      // Create Profile
      const { error: profileError } = await (supabase as any)
        .from("profiles")
        .insert({
          id: currentUser.id,
          nome: formData.name, // Using clinic name as admin name for now if not asked
          telefone: formData.phone,
          email: currentUser.email,
          cidade: formData.city,
          uf: formData.state,
          role: "manager", // Using 'manager' as the owner role for clinics
          tenant_id: tenant.id,
        });

      if (profileError) {
        await supabase.from("tenants").delete().eq("id", tenant.id);
        throw profileError;
      }

      // Create Subscription
      const extraSeats = planData.seats ? Math.max(0, planData.seats - 5) : 0;

      if (planData.price > 0) {
        if (!planData.priceId) {
          sonnerToast.error("Erro de configuração: ID do preço não encontrado. Contate o suporte.");
          return;
        }

        const { data: checkoutData, error: checkoutError } = await supabase.functions.invoke('create-checkout', {
          body: {
            priceId: planData.priceId,
            planSlug: planData.planCode,
            billingCycle: 'monthly',
          }
        });

        if (checkoutError) {
          console.error("Erro ao criar checkout:", checkoutError);
          sonnerToast.error("Erro ao iniciar pagamento.");
          return;
        }

        if (checkoutData?.url) {
          window.location.href = checkoutData.url;
          return;
        }
      } else {
        const { error: subError } = await supabase.functions.invoke('billing-ops', {
          body: {
            action: 'start_subscription',
            tenantId: tenant.id,
            planCode: planData.planCode,
            edition: 'company',
            extraSeats: { profissional: extraSeats },
            couponCode: planData.couponCode
          }
        });

        if (subError) console.error("Erro ao criar assinatura:", subError);
      }

      toast({
        title: "Cadastro concluído!",
        description: "Bem-vindo ao CleanFlow.",
      });

      setTimeout(() => {
        navigate("/dashboard");
      }, 1500);

    } catch (error: any) {
      console.error("Erro no cadastro:", error);
      sonnerToast.error("Erro ao completar cadastro.");
    }
  };

  return (
    <div className="min-h-screen bg-background py-8 px-4">
      <div className="container mx-auto max-w-3xl">
        <div className="mb-8">
          <Button variant="ghost" onClick={step === 1 ? onBack : () => setStep(step - 1)} className="mb-4">
            <ArrowLeft className="h-4 w-4 mr-2" />
            Voltar
          </Button>
          <div className="flex items-center justify-between mb-4">
            <h1 className="text-3xl font-bold text-foreground">
              Cadastro de Clínica/Empresa
            </h1>
            <span className="text-sm text-muted-foreground">
              Passo {step} de 3
            </span>
          </div>
          <div className="h-2 bg-muted rounded-full overflow-hidden">
            <div
              className="h-full bg-primary transition-all"
              style={{ width: `${(step / 3) * 100}%` }}
            />
          </div>
        </div>

        {step === 1 && (
          <PlanSelection
            edition="company"
            onSelect={handlePlanSelect}
            onBack={onBack}
          />
        )}

        {step === 2 && (
          <Card className="p-6 space-y-6">
            <div className="space-y-4">
              <div>
                <Label htmlFor="razaoSocial">Razão Social *</Label>
                <Input
                  id="razaoSocial"
                  placeholder="Razão Social da empresa"
                  value={formData.razaoSocial}
                  onChange={(e) =>
                    setFormData({ ...formData, razaoSocial: e.target.value })
                  }
                />
              </div>
              <div>
                <Label htmlFor="name">Nome Fantasia *</Label>
                <Input
                  id="name"
                  placeholder="Nome fantasia"
                  value={formData.name}
                  onChange={(e) =>
                    setFormData({ ...formData, name: e.target.value })
                  }
                />
              </div>
              <div>
                <Label htmlFor="phone">Telefone principal *</Label>
                <Input
                  id="phone"
                  placeholder="+55 99 99999-9999"
                  value={formData.phone}
                  onChange={(e) =>
                    setFormData({ ...formData, phone: e.target.value })
                  }
                />
              </div>

              <div className="grid grid-cols-3 gap-4">
                <div className="col-span-1">
                  <Label htmlFor="cep">CEP *</Label>
                  <Input
                    id="cep"
                    value={formData.cep}
                    onChange={(e) =>
                      setFormData({ ...formData, cep: e.target.value })
                    }
                    onBlur={handleCepBlur}
                    placeholder="00000-000"
                  />
                </div>
                <div className="col-span-2">
                  <Label htmlFor="address">Endereço</Label>
                  <Input
                    id="address"
                    value={formData.address}
                    readOnly
                    className="bg-muted"
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label htmlFor="number">Número *</Label>
                  <Input
                    id="number"
                    value={formData.number}
                    onChange={(e) =>
                      setFormData({ ...formData, number: e.target.value })
                    }
                    placeholder="123"
                  />
                </div>
                <div>
                  <Label htmlFor="complement">Complemento</Label>
                  <Input
                    id="complement"
                    value={formData.complement}
                    onChange={(e) =>
                      setFormData({ ...formData, complement: e.target.value })
                    }
                    placeholder="Apto 101"
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label htmlFor="neighborhood">Bairro</Label>
                  <Input
                    id="neighborhood"
                    value={formData.neighborhood}
                    readOnly
                    className="bg-muted"
                  />
                </div>
                <div className="grid grid-cols-3 gap-2">
                  <div className="col-span-2">
                    <Label htmlFor="city">Cidade</Label>
                    <Input
                      id="city"
                      value={formData.city}
                      readOnly
                      className="bg-muted"
                    />
                  </div>
                  <div>
                    <Label htmlFor="state">UF</Label>
                    <Input
                      id="state"
                      value={formData.state}
                      readOnly
                      className="bg-muted"
                    />
                  </div>
                </div>
              </div>
            </div>
            <div className="flex justify-end">
              <Button
                onClick={() => setStep(3)}
                disabled={!formData.name || !formData.phone || !formData.city}
              >
                Próximo
              </Button>
            </div>
          </Card>
        )}

        {step === 3 && (
          <Card className="p-6 space-y-6">
            <div>
              <h2 className="text-xl font-semibold mb-4">
                Segmentos, Serviços e Recursos
              </h2>

              <div className="space-y-6">
                <div>
                  <Label className="mb-3 block">Segmentos de atividade *</Label>
                  <div className="grid grid-cols-3 gap-3">
                    {SEGMENTS.map((segmentItem) => (
                      <div key={segmentItem} className="flex items-center space-x-2">
                        <Checkbox
                          id={segmentItem}
                          checked={formData.segment === segmentItem}
                          onCheckedChange={() => handleSegmentSelect(segmentItem)}
                        />
                        <Label htmlFor={segmentItem} className="text-sm cursor-pointer">
                          {segmentItem}
                        </Label>
                      </div>
                    ))}
                    <div className="flex items-center space-x-2 col-span-3">
                      <Checkbox
                        id="other_segment"
                        checked={formData.hasOtherSegment}
                        onCheckedChange={(checked) => handleOtherSegmentSelect(checked as boolean)}
                      />
                      <Label
                        htmlFor="other_segment"
                        className="text-sm cursor-pointer whitespace-nowrap"
                      >
                        Outro
                      </Label>
                      {formData.hasOtherSegment && (
                        <Input
                          className="h-8 flex-1 ml-2"
                          placeholder="Especifique o outro segmento"
                          value={formData.otherSegment}
                          onChange={(e) =>
                            setFormData({ ...formData, otherSegment: e.target.value })
                          }
                          autoFocus
                        />
                      )}
                    </div>
                  </div>
                </div>

                <div>
                  <Label className="mb-3 block">Modo de agendamento *</Label>
                  <RadioGroup
                    value={formData.scheduleMode}
                    onValueChange={(value) =>
                      setFormData({ ...formData, scheduleMode: value })
                    }
                  >
                    <div className="flex items-center space-x-2 p-3 border rounded-lg">
                      <RadioGroupItem value="professional" id="mode-prof" />
                      <Label htmlFor="mode-prof" className="cursor-pointer">
                        Por Profissional (calendário por pessoa)
                      </Label>
                    </div>
                    <div className="flex items-center space-x-2 p-3 border rounded-lg">
                      <RadioGroupItem value="room" id="mode-room" />
                      <Label htmlFor="mode-room" className="cursor-pointer">
                        Por Consultório/Sala/Box (calendário por recurso)
                      </Label>
                    </div>
                  </RadioGroup>
                </div>

                {formData.scheduleMode === "professional" && (
                  <div>
                    <Label className="mb-3 block">Profissionais (opcional)</Label>
                    {formData.professionals.map((prof, index) => (
                      <div key={index} className="mb-3 grid grid-cols-2 gap-3">
                        <Input placeholder="Nome" value={prof.name} />
                        <Input placeholder="WhatsApp" value={prof.phone} />
                      </div>
                    ))}
                    <Button variant="outline" onClick={addProfessional} className="w-full">
                      <Plus className="h-4 w-4 mr-2" />
                      Adicionar profissional
                    </Button>
                  </div>
                )}

                {formData.scheduleMode === "room" && (
                  <div>
                    <Label className="mb-3 block">Salas/Boxes (opcional)</Label>
                    {formData.rooms.map((room, index) => (
                      <div key={index} className="mb-3">
                        <Input placeholder="Nome da sala/box" value={room.name} />
                      </div>
                    ))}
                    <Button variant="outline" onClick={addRoom} className="w-full">
                      <Plus className="h-4 w-4 mr-2" />
                      Adicionar sala
                    </Button>
                  </div>
                )}
              </div>
            </div>

            <div className="flex justify-between">
              <Button variant="outline" onClick={() => setStep(2)}>
                Voltar
              </Button>
              <Button onClick={() => setStep(4)} disabled={!formData.segment && !formData.hasOtherSegment}>
                Próximo
              </Button>
            </div>
          </Card>
        )}

        {step === 4 && (
          <Card className="p-6 space-y-6">
            <div>
              <h2 className="text-xl font-semibold mb-4">Confirmação</h2>
              <div className="space-y-4">
                <div className="p-4 bg-muted rounded-lg space-y-3">
                  <h3 className="font-medium">Resumo do Cadastro</h3>
                  <div className="text-sm space-y-1">
                    <p>
                      <strong>Plano:</strong> {planData?.planCode === 'company_base' ? 'Empresa' : planData?.planCode}
                    </p>
                    <p>
                      <strong>Profissionais Contratados:</strong> {planData?.seats || 5}
                    </p>
                    <p>
                      <strong>Nome da Clínica:</strong> {formData.name}
                    </p>
                    <p>
                      <strong>Segmento:</strong> {formData.hasOtherSegment ? formData.otherSegment : formData.segment}
                    </p>
                    <p>
                      <strong>Telefone:</strong> {formData.phone}
                    </p>
                    <p>
                      <strong>Cidade/UF:</strong> {formData.city}/{formData.state}
                    </p>
                  </div>
                </div>

                <div className="flex items-start space-x-2">
                  <Checkbox
                    id="lgpd"
                    checked={formData.lgpdAccepted}
                    onCheckedChange={(checked) =>
                      setFormData({ ...formData, lgpdAccepted: checked as boolean })
                    }
                  />
                  <Label htmlFor="lgpd" className="text-sm cursor-pointer">
                    Aceito os termos da{" "}
                    <a href="#" className="text-primary hover:underline">
                      Política de Privacidade
                    </a>{" "}
                    e{" "}
                    <a href="#" className="text-primary hover:underline">
                      Termos de Uso
                    </a>{" "}
                    em conformidade com a LGPD.
                  </Label>
                </div>
              </div>
            </div>

            <div className="flex justify-between">
              <Button variant="outline" onClick={() => setStep(3)}>
                Voltar
              </Button>
              <Button onClick={handleSubmit} disabled={!formData.lgpdAccepted}>
                Concluir Cadastro
              </Button>
            </div>
          </Card>
        )}
      </div>
    </div>
  );
}

import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card } from "@/components/ui/card";
import { Checkbox } from "@/components/ui/checkbox";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { ArrowLeft, Plus, Trash2 } from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { supabase } from "@/integrations/supabase/client";
import { toast as sonnerToast } from "sonner";
import { useAuth } from "@/hooks/useAuth";
import { PlanSelection } from "@/components/onboarding/PlanSelection";
import { fetchAddressByCEP } from "@/lib/cep";

interface OnboardingProfessionalProps {
  onBack: () => void;
}

const SEGMENTS = [
  "Advocacia",
  "Aula Particular",
  "Consultoria",
  "Estética",
  "Fisioterapia",
  "Laboratório",
  "Lava-rápido",
  "Marcenaria",
  "Medicina",
  "Nutrição",
  "Odontologia",
  "Oficina",
  "Personal Trainer",
  "Podologia",
  "Psicologia",
  "Outro"
];

export function OnboardingProfessional({ onBack }: OnboardingProfessionalProps) {
  const navigate = useNavigate();
  const { toast } = useToast();
  const { user } = useAuth();
  const [step, setStep] = useState(1);
  const [planData, setPlanData] = useState<{ planCode: string; price: number; priceId?: string; couponCode?: string } | null>(null);
  const [formData, setFormData] = useState({
    name: "",
    phone: "",
    cep: "",
    address: "",
    neighborhood: "",
    number: "",
    complement: "",
    city: "",
    state: "",
    segment: "",
    otherSegment: "",
    hasOtherSegment: false,
    services: [{ name: "", duration: "", price: "" }],
    scheduleMode: "professional",
    lgpdAccepted: false,
  });

  const handleCepBlur = async () => {
    if (formData.cep.length >= 8) {
      const address = await fetchAddressByCEP(formData.cep);
      if (address) {
        setFormData(prev => ({
          ...prev,
          address: address.logradouro,
          neighborhood: address.bairro,
          city: address.localidade,
          state: address.uf
        }));
      }
    }
  };

  const handleSegmentSelect = (value: string) => {
    if (value === "Outro") {
      setFormData((prev) => ({
        ...prev,
        segment: "",
        hasOtherSegment: true,
        otherSegment: ""
      }));
    } else {
      setFormData((prev) => ({
        ...prev,
        segment: value,
        hasOtherSegment: false,
        otherSegment: ""
      }));
    }
  };

  const addService = () => {
    setFormData((prev) => ({
      ...prev,
      services: [...prev.services, { name: "", duration: "", price: "" }],
    }));
  };

  const removeService = (index: number) => {
    setFormData((prev) => ({
      ...prev,
      services: prev.services.filter((_, i) => i !== index),
    }));
  };

  const handleServiceChange = (index: number, field: string, value: string) => {
    setFormData((prev) => ({
      ...prev,
      services: prev.services.map((service, i) =>
        i === index ? { ...service, [field]: value } : service
      ),
    }));
  };

  const handlePriceBlur = (index: number) => {
    const service = formData.services[index];
    if (!service.price) return;

    let valStr = service.price;
    valStr = valStr.replace(/\./g, '');
    valStr = valStr.replace(',', '.');

    const val = parseFloat(valStr);

    if (!isNaN(val)) {
      const formatted = val.toLocaleString("pt-BR", {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
      });
      handleServiceChange(index, "price", formatted);
    }
  };

  const handlePlanSelect = (selection: { planCode: string; price: number; priceId?: string; couponCode?: string }) => {
    setPlanData(selection);
    setStep(4);
  };

  const handleSubmit = async () => {
    if (!formData.lgpdAccepted) {
      toast({
        title: "Aceite necessário",
        description: "Você precisa aceitar os termos da LGPD para continuar.",
        variant: "destructive",
      });
      return;
    }

    if (!planData) {
      toast({
        title: "Plano não selecionado",
        description: "Por favor, selecione um plano.",
        variant: "destructive"
      });
      return;
    }

    try {
      console.log("[Onboarding] Iniciando processo de cadastro...");

      let currentUser = user;

      if (!currentUser) {
        const { data: { user: fetchedUser }, error: userError } = await supabase.auth.getUser();

        if (userError || !fetchedUser) {
          sonnerToast.error("Sessão expirada. Por favor, faça login novamente.");
          return;
        }
        currentUser = fetchedUser;
      }

      const { data: existingProfile } = await supabase
        .from("profiles")
        .select("id, tenant_id")
        .eq("id", currentUser.id)
        .single();

      if (existingProfile?.tenant_id) {
        navigate("/dashboard");
        return;
      }

      const segmentsArray = formData.hasOtherSegment && formData.otherSegment
        ? [formData.otherSegment]
        : [formData.segment];

      const { data: tenant, error: tenantError } = await (supabase as any)
        .from("tenants")
        .insert({
          nome: formData.name,
          tipo: "profissional",
          telefone: formData.phone,
          email: currentUser.email,
          cidade: formData.city,
          uf: formData.state,
          cep: formData.cep,
          logradouro: formData.address,
          bairro: formData.neighborhood,
          numero: formData.number,
          complemento: formData.complement,
          segmentos: segmentsArray,
          modo_agendamento: formData.scheduleMode === "professional"
            ? "por_profissional"
            : "por_clinica_sala",
        })
        .select()
        .single();

      if (tenantError) {
        await supabase.auth.signOut();
        throw tenantError;
      }

      const { error: profileError } = await (supabase as any)
        .from("profiles")
        .insert({
          id: currentUser.id,
          nome: formData.name,
          telefone: formData.phone,
          email: currentUser.email,
          cidade: formData.city,
          uf: formData.state,
          role: "professional",
          tenant_id: tenant.id,
        });

      if (profileError) {
        await supabase.from("tenants").delete().eq("id", tenant.id);
        await supabase.auth.signOut();
        throw profileError;
      }

      const validServices = formData.services.filter(s => s.name && s.duration);
      if (validServices.length > 0) {
        await (supabase as any)
          .from("servicos")
          .insert(
            validServices.map((s) => ({
              tenant_id: tenant?.id,
              nome: s.name,
              duracao_minutos: parseInt(s.duration),
              preco: s.price ? parseFloat(s.price.replace(/\./g, '').replace(',', '.')) : null,
            }))
          );
      }

      if (planData.price > 0) {
        if (!planData.priceId) {
          sonnerToast.error("Erro de configuração: ID do preço não encontrado.");
          return;
        }

        const { data: checkoutData, error: checkoutError } = await supabase.functions.invoke('create-checkout', {
          body: {
            priceId: planData.priceId,
            planSlug: planData.planCode,
            billingCycle: 'monthly',
          }
        });

        if (checkoutError) {
          sonnerToast.error("Erro ao iniciar pagamento.");
          return;
        }

        if (checkoutData?.url) {
          window.location.href = checkoutData.url;
          return;
        }
      } else {
        const { error: subError } = await supabase.functions.invoke('billing-ops', {
          body: {
            action: 'start_subscription',
            tenantId: tenant.id,
            planCode: planData.planCode,
            edition: 'solo',
            couponCode: planData.couponCode
          }
        });

        if (subError) {
          sonnerToast.error("Erro ao criar assinatura.");
        }
      }

      toast({
        title: "Cadastro concluído!",
        description: "Bem-vindo ao CleanFlow. Preparando seu painel...",
      });

      setTimeout(() => {
        navigate("/dashboard");
      }, 1500);
    } catch (error: any) {
      console.error("[Onboarding] Erro no processo de cadastro:", error);
      sonnerToast.error("Erro ao completar cadastro.");
    }
  };

  return (
    <div className="min-h-screen bg-background py-8 px-4">
      <div className="container mx-auto max-w-3xl">
        <div className="mb-8">
          <Button variant="ghost" onClick={step === 1 ? onBack : () => setStep(step - 1)} className="mb-4">
            <ArrowLeft className="h-4 w-4 mr-2" />
            Voltar
          </Button>
          <div className="flex items-center justify-between mb-4">
            <h1 className="text-3xl font-bold text-foreground">
              Cadastro de Profissional
            </h1>
            <span className="text-sm text-muted-foreground">
              Passo {step} de 4
            </span>
          </div>
          <div className="h-2 bg-muted rounded-full overflow-hidden">
            <div
              className="h-full bg-primary transition-all"
              style={{ width: `${(step / 4) * 100}%` }}
            />
          </div>
        </div>

        {/* STEP 1: Basic Data */}
        {step === 1 && (
          <Card className="p-6 space-y-6">
            <div>
              <h2 className="text-xl font-semibold mb-4">Dados Básicos</h2>
              <div className="space-y-4">
                <div>
                  <Label htmlFor="name">Nome completo *</Label>
                  <Input
                    id="name"
                    value={formData.name}
                    onChange={(e) =>
                      setFormData({ ...formData, name: e.target.value })
                    }
                    placeholder="Seu nome completo"
                  />
                </div>

                <div>
                  <Label htmlFor="phone">Telefone com WhatsApp *</Label>
                  <Input
                    id="phone"
                    value={formData.phone}
                    onChange={(e) =>
                      setFormData({ ...formData, phone: e.target.value })
                    }
                    placeholder="+55 99 99999-9999"
                  />
                </div>

                <div className="grid grid-cols-3 gap-4">
                  <div className="col-span-1">
                    <Label htmlFor="cep">CEP *</Label>
                    <Input
                      id="cep"
                      value={formData.cep}
                      onChange={(e) =>
                        setFormData({ ...formData, cep: e.target.value })
                      }
                      onBlur={handleCepBlur}
                      placeholder="00000-000"
                    />
                  </div>
                  <div className="col-span-2">
                    <Label htmlFor="address">Endereço</Label>
                    <Input
                      id="address"
                      value={formData.address}
                      readOnly
                      className="bg-muted"
                    />
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <Label htmlFor="number">Número *</Label>
                    <Input
                      id="number"
                      value={formData.number}
                      onChange={(e) =>
                        setFormData({ ...formData, number: e.target.value })
                      }
                      placeholder="123"
                    />
                  </div>
                  <div>
                    <Label htmlFor="complement">Complemento</Label>
                    <Input
                      id="complement"
                      value={formData.complement}
                      onChange={(e) =>
                        setFormData({ ...formData, complement: e.target.value })
                      }
                      placeholder="Apto 101"
                    />
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <Label htmlFor="neighborhood">Bairro</Label>
                    <Input
                      id="neighborhood"
                      value={formData.neighborhood}
                      readOnly
                      className="bg-muted"
                    />
                  </div>
                  <div className="grid grid-cols-3 gap-2">
                    <div className="col-span-2">
                      <Label htmlFor="city">Cidade</Label>
                      <Input
                        id="city"
                        value={formData.city}
                        readOnly
                        className="bg-muted"
                      />
                    </div>
                    <div>
                      <Label htmlFor="state">UF</Label>
                      <Input
                        id="state"
                        value={formData.state}
                        readOnly
                        className="bg-muted"
                      />
                    </div>
                  </div>
                </div>
              </div>
            </div>

            <div className="flex justify-end">
              <Button
                onClick={() => setStep(2)}
                disabled={!formData.name || !formData.phone || !formData.city}
              >
                Próximo
              </Button>
            </div>
          </Card>
        )}

        {/* STEP 2: Segments and Services */}
        {step === 2 && (
          <Card className="p-6 space-y-6">
            <div>
              <h2 className="text-xl font-semibold mb-4">
                Segmentos e Serviços
              </h2>

              <div className="space-y-6">
                <div>
                  <Label className="mb-3 block">
                    Segmentos de atividade *
                  </Label>
                  <div className="grid grid-cols-3 gap-3">
                    {SEGMENTS.map((segmentItem) => (
                      <div key={segmentItem} className="flex items-center space-x-2">
                        <Checkbox
                          id={segmentItem}
                          checked={formData.segment === segmentItem || (segmentItem === "Outro" && formData.hasOtherSegment)}
                          onCheckedChange={() => handleSegmentSelect(segmentItem)}
                        />
                        <Label
                          htmlFor={segmentItem}
                          className="text-sm cursor-pointer"
                        >
                          {segmentItem}
                        </Label>
                      </div>
                    ))}
                    {formData.hasOtherSegment && (
                      <div className="col-span-3 mt-2">
                        <Input
                          placeholder="Especifique o segmento"
                          value={formData.otherSegment}
                          onChange={(e) => setFormData({ ...formData, otherSegment: e.target.value })}
                          autoFocus
                        />
                      </div>
                    )}
                  </div>
                </div>

                <div>
                  <Label className="mb-3 block">Serviços oferecidos *</Label>
                  {formData.services.map((service, index) => (
                    <div key={index} className="mb-3 flex gap-3 items-end">
                      <div className="flex-1">
                        <Label className="text-xs mb-1 block">Nome do Serviço</Label>
                        <Input
                          placeholder="Ex: Consulta"
                          value={service.name}
                          onChange={(e) =>
                            handleServiceChange(index, "name", e.target.value)
                          }
                        />
                      </div>
                      <div className="w-24">
                        <Label className="text-xs mb-1 block">Duração (min)</Label>
                        <Input
                          type="number"
                          placeholder="30"
                          value={service.duration}
                          onChange={(e) =>
                            handleServiceChange(index, "duration", e.target.value)
                          }
                        />
                      </div>
                      <div className="w-32">
                        <Label className="text-xs mb-1 block">Preço (R$)</Label>
                        <Input
                          placeholder="0,00"
                          value={service.price}
                          onChange={(e) =>
                            handleServiceChange(index, "price", e.target.value)
                          }
                          onBlur={() => handlePriceBlur(index)}
                        />
                      </div>
                      <Button
                        variant="ghost"
                        size="icon"
                        onClick={() => removeService(index)}
                        disabled={formData.services.length === 1}
                        className="mb-[2px]"
                      >
                        <Trash2 className="h-4 w-4 text-destructive" />
                      </Button>
                    </div>
                  ))}
                  <Button variant="outline" onClick={addService} className="w-full mt-2">
                    <Plus className="h-4 w-4 mr-2" />
                    Adicionar outro serviço
                  </Button>
                </div>

                <div className="flex justify-between">
                  <Button variant="outline" onClick={() => setStep(1)}>
                    Voltar
                  </Button>
                  <Button
                    onClick={() => setStep(3)}
                    disabled={
                      (!formData.segment && !formData.hasOtherSegment) ||
                      (formData.hasOtherSegment && !formData.otherSegment.trim()) ||
                      !formData.services[0].name
                    }
                  >
                    Próximo
                  </Button>
                </div>
              </div>
            </div>
          </Card>
        )}

        {/* STEP 3: Plan Selection */}
        {step === 3 && (
          <PlanSelection
            edition="solo"
            onSelect={handlePlanSelect}
            onBack={() => setStep(2)}
          />
        )}

        {/* STEP 4: Confirmation */}
        {step === 4 && (
          <Card className="p-6 space-y-6">
            <div>
              <h2 className="text-xl font-semibold mb-4">
                Preferências e Confirmação
              </h2>

              <div className="space-y-4">
                <div className="p-4 bg-muted rounded-lg space-y-3">
                  <h3 className="font-medium">Resumo do Cadastro</h3>
                  <div className="text-sm space-y-1">
                    <p>
                      <strong>Plano:</strong> {planData?.planCode === 'free_solo' ? 'Free Solo' : 'Pro Solo'}
                    </p>
                    <p>
                      <strong>Nome:</strong> {formData.name}
                    </p>
                    <p>
                      <strong>Telefone:</strong> {formData.phone}
                    </p>
                    <p>
                      <strong>Cidade/UF:</strong> {formData.city}/{formData.state}
                    </p>
                    <p>
                      <strong>Segmento:</strong> {formData.hasOtherSegment ? formData.otherSegment : formData.segment}
                    </p>
                    <p>
                      <strong>Serviços:</strong>{" "}
                      {formData.services.map((s) => s.name).join(", ")}
                    </p>
                  </div>
                </div>

                <div className="flex items-start space-x-2">
                  <Checkbox
                    id="lgpd"
                    checked={formData.lgpdAccepted}
                    onCheckedChange={(checked) =>
                      setFormData({ ...formData, lgpdAccepted: checked as boolean })
                    }
                  />
                  <Label htmlFor="lgpd" className="text-sm cursor-pointer">
                    Aceito os termos da{" "}
                    <a href="#" className="text-primary hover:underline">
                      Política de Privacidade
                    </a>{" "}
                    e{" "}
                    <a href="#" className="text-primary hover:underline">
                      Termos de Uso
                    </a>{" "}
                    em conformidade com a LGPD.
                  </Label>
                </div>
              </div>
            </div>

            <div className="flex justify-between">
              <Button variant="outline" onClick={() => setStep(3)}>
                Voltar
              </Button>
              <Button onClick={handleSubmit} disabled={!formData.lgpdAccepted}>
                Concluir Cadastro
              </Button>
            </div>
          </Card>
        )}
      </div>
    </div >
  );
}

