import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { RadioGroup, RadioGroupItem } from '@/components/ui/radio-group';
import { Checkbox } from '@/components/ui/checkbox';
import { Switch } from '@/components/ui/switch';
import { Badge } from '@/components/ui/badge';
import { Progress } from '@/components/ui/progress';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import {
  ArrowLeft,
  ArrowRight,
  Check,
  Building2,
  Calendar,
  Package,
  CreditCard,
  MessageSquare,
  Stethoscope,
  Sparkles,
  Dog,
  Scissors,
  GraduationCap,
  Wrench,
  Users,
  MapPin,
  Truck,
  Layers,
  Eye,
  Menu,
  ToggleLeft,
  AlertCircle,
  Loader2,
  Scale
} from 'lucide-react';
import { toast } from 'sonner';
import { supabase } from '@/integrations/supabase/client';
import { useAuth } from '@/hooks/useAuth';

interface OnboardingSegmentoProps {
  onComplete?: () => void;
  onBack?: () => void;
}

interface SegmentPreview {
  segmento: string;
  features: Array<{
    recurso: string;
    descricao: string;
    categoria: string;
    habilitado: boolean;
  }>;
  menu: Array<{
    chave: string;
    label: string;
    icone: string;
    rota: string;
  }>;
  total_features: number;
}

const SEGMENTOS = [
  { codigo: 'saude', nome: 'Saúde', icone: Stethoscope, descricao: 'Clínicas, consultórios médicos' },
  { codigo: 'estetica', nome: 'Estética & Beleza', icone: Sparkles, descricao: 'Estúdios, SPAs, salões' },
  { codigo: 'veterinaria', nome: 'Veterinária', icone: Dog, descricao: 'Clínicas veterinárias, pet shops' },
  { codigo: 'odontologia', nome: 'Odontologia', icone: Scissors, descricao: 'Consultórios odontológicos' },
  { codigo: 'educacao', nome: 'Educação & Cursos', icone: GraduationCap, descricao: 'Escolas, cursos, treinamentos' },
  { codigo: 'oficina', nome: 'Oficina & Serviços', icone: Wrench, descricao: 'Mecânicas, assistências técnicas' },
];

const MODOS_AGENDA = [
  {
    valor: 'profissional',
    nome: 'Por Profissional',
    icone: Users,
    descricao: 'Cada profissional tem sua própria agenda'
  },
  {
    valor: 'recurso',
    nome: 'Por Recurso',
    icone: Package,
    descricao: 'Salas, equipamentos ou boxes disponíveis'
  },
  {
    valor: 'local',
    nome: 'Por Local/Unidade',
    icone: MapPin,
    descricao: 'Múltiplas unidades ou locais de atendimento'
  },
  {
    valor: 'externo',
    nome: 'Atendimento Externo',
    icone: Truck,
    descricao: 'Atendimento em campo, domiciliar'
  },
  {
    valor: 'misto',
    nome: 'Misto',
    icone: Layers,
    descricao: 'Combinação de profissionais e recursos'
  },
];

const MEIOS_PAGAMENTO = [
  { id: 'dinheiro', nome: 'Dinheiro' },
  { id: 'pix', nome: 'PIX' },
  { id: 'cartao_debito', nome: 'Cartão de Débito' },
  { id: 'cartao_credito', nome: 'Cartão de Crédito' },
  { id: 'convenio', nome: 'Convênio/Plano de Saúde' },
  { id: 'boleto', nome: 'Boleto' },
  { id: 'transferencia', nome: 'Transferência Bancária' },
];

const LEMBRETES_OPTIONS = [
  { id: 'confirmacao', nome: 'Confirmação de Agendamento', descricao: 'Solicitar confirmação 24h antes' },
  { id: 'lembrete', nome: 'Lembrete', descricao: 'Lembrar sobre o compromisso' },
  { id: 'chegada', nome: 'Check-in de Chegada', descricao: 'Confirmar chegada no local' },
  { id: 'pos_atendimento', nome: 'Pós-Atendimento', descricao: 'Agradecer e solicitar feedback' },
];

export default function OnboardingSegmento({ onComplete, onBack }: OnboardingSegmentoProps) {
  const navigate = useNavigate();
  const { profile } = useAuth();
  const [step, setStep] = useState(1);
  const [loading, setLoading] = useState(false);
  const [previewLoading, setPreviewLoading] = useState(false);
  const [previewData, setPreviewData] = useState<SegmentPreview | null>(null);

  // Step 1: Sobre seu negócio
  const [segmentoSelecionado, setSegmentoSelecionado] = useState<string>('');
  const [cidade, setCidade] = useState('');
  const [estado, setEstado] = useState('');
  const [activeSegments, setActiveSegments] = useState<any[]>([]);
  const [loadingSegments, setLoadingSegments] = useState(true);

  useEffect(() => {
    const fetchActiveSegments = async () => {
      try {
        const { data } = await supabase
          .from('segment_configs')
          .select('*')
          .eq('active', true)
          .order('name');
        setActiveSegments(data || []);
      } catch (error) {
        console.error(error);
      } finally {
        setLoadingSegments(false);
      }
    };
    fetchActiveSegments();
  }, []);

  const getSegmentIcon = (id: string) => {
    switch (id) {
      case 'saude': return Stethoscope;
      case 'juridico': return Scale;
      case 'oficina': return Wrench;
      case 'beleza': return Scissors;
      default: return Building2;
    }
  };

  // Step 2: Modo de agenda
  const [modoAgenda, setModoAgenda] = useState<string>('profissional');

  // Step 3: Meios de pagamento
  const [meiosPagamento, setMeiosPagamento] = useState<string[]>(['dinheiro', 'pix', 'cartao_credito']);
  const [exigirSinal, setExigirSinal] = useState(false);
  const [taxaCancelamento, setTaxaCancelamento] = useState(false);

  // Step 4: Lembretes
  const [lembretesAtivos, setLembretesAtivos] = useState<string[]>(['confirmacao', 'lembrete']);

  const totalSteps = 6; // Adicionado step de preview
  const progress = (step / totalSteps) * 100;

  // Buscar preview quando segmento mudar
  useEffect(() => {
    if (segmentoSelecionado) {
      fetchPreview(segmentoSelecionado);
    }
  }, [segmentoSelecionado]);

  const fetchPreview = async (segmento: string) => {
    setPreviewLoading(true);
    try {
      const { data, error } = await supabase.rpc('preview_segment_config', {
        p_segmento: segmento
      });
      if (error) throw error;
      setPreviewData(data as unknown as SegmentPreview);
    } catch (error) {
      console.error('Error fetching preview:', error);
    } finally {
      setPreviewLoading(false);
    }
  };

  const toggleMeioPagamento = (id: string) => {
    setMeiosPagamento(prev =>
      prev.includes(id) ? prev.filter(m => m !== id) : [...prev, id]
    );
  };

  const toggleLembrete = (id: string) => {
    setLembretesAtivos(prev =>
      prev.includes(id) ? prev.filter(l => l !== id) : [...prev, id]
    );
  };

  const handleNext = () => {
    if (step === 1 && !segmentoSelecionado) {
      toast.error('Selecione um segmento para continuar');
      return;
    }
    setStep(s => Math.min(s + 1, totalSteps));
  };

  const handleBack = () => {
    if (step === 1) {
      onBack?.();
    } else {
      setStep(s => Math.max(s - 1, 1));
    }
  };

  const handleComplete = async () => {
    if (!profile?.tenant_id) {
      toast.error('Erro: Tenant não encontrado');
      return;
    }

    setLoading(true);
    try {
      // 1. Criar/atualizar tenant_profile
      const { error: profileError } = await supabase
        .from('tenant_profile')
        .upsert({
          tenant_id: profile.tenant_id,
          segmentos: [{ codigo: segmentoSelecionado, nome: activeSegments.find(s => s.id === segmentoSelecionado)?.name || '' }],
          modo_agenda: modoAgenda,
          pais: 'BR',
          moeda: 'BRL',
          idioma: 'pt-BR',
          status_onboarding: 'concluido',
          meios_pagamento: meiosPagamento,
          politicas_cobranca: { exigir_sinal: exigirSinal, taxa_cancelamento: taxaCancelamento },
          lembretes_config: { ativos: lembretesAtivos },
        }, { onConflict: 'tenant_id' });

      if (profileError) throw profileError;

      // 2. Aplicar flags do segmento
      const { error: flagsError } = await supabase.rpc('apply_segment_flags', {
        p_tenant_id: profile.tenant_id,
        p_segmento: segmentoSelecionado
      });

      if (flagsError) throw flagsError;

      // 3. Atualizar cidade/estado no tenant se necessário
      if (cidade || estado) {
        await supabase
          .from('tenants')
          .update({
            cidade: cidade || undefined,
            estado: estado || undefined
          })
          .eq('id', profile.tenant_id);
      }

      toast.success('Configurações aplicadas com sucesso!');

      if (onComplete) {
        onComplete();
      } else {
        navigate('/');
      }
    } catch (error) {
      console.error('Error completing onboarding:', error);
      toast.error('Erro ao salvar configurações');
    } finally {
      setLoading(false);
    }
  };

  const renderStepContent = () => {
    switch (step) {
      case 1:
        return (
          <div className="space-y-6">
            <div>
              <h3 className="text-lg font-medium mb-4">Qual é o segmento do seu negócio?</h3>
              {loadingSegments ? (
                <div className="flex justify-center p-4"><Loader2 className="animate-spin" /></div>
              ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                  {activeSegments.map(seg => {
                    // Tentar mapear ícone do banco ou usar fallback
                    let Icon = Building2;
                    if (seg.icon) {
                      const iconName = seg.icon;
                      if (iconName === 'Stethoscope') Icon = Stethoscope;
                      else if (iconName === 'Sparkles') Icon = Sparkles;
                      else if (iconName === 'Dog') Icon = Dog;
                      else if (iconName === 'Scissors') Icon = Scissors;
                      else if (iconName === 'GraduationCap') Icon = GraduationCap;
                      else if (iconName === 'Wrench') Icon = Wrench;
                      else if (iconName === 'Scale') Icon = Scale;
                    } else {
                      Icon = getSegmentIcon(seg.id);
                    }

                    const isSelected = segmentoSelecionado === seg.id;
                    return (
                      <div
                        key={seg.id}
                        onClick={() => setSegmentoSelecionado(seg.id)}
                        className={`p-4 rounded-lg border-2 cursor-pointer transition-all ${isSelected
                          ? 'border-primary bg-primary/5'
                          : 'border-border hover:border-primary/50'
                          }`}
                      >
                        <div className="flex items-start gap-3">
                          <div className={`p-2 rounded-lg ${isSelected ? 'bg-primary text-primary-foreground' : 'bg-muted'}`}>
                            <Icon className="h-5 w-5" />
                          </div>
                          <div className="flex-1">
                            <h4 className="font-medium">{seg.name}</h4>
                            <p className="text-sm text-muted-foreground">
                              {seg.description || 'Segmento especializado'}
                            </p>
                          </div>
                          {isSelected && (
                            <Check className="h-5 w-5 text-primary" />
                          )}
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <Label htmlFor="cidade">Cidade</Label>
                <Input
                  id="cidade"
                  value={cidade}
                  onChange={e => setCidade(e.target.value)}
                  placeholder="Sua cidade"
                />
              </div>
              <div>
                <Label htmlFor="estado">Estado</Label>
                <Input
                  id="estado"
                  value={estado}
                  onChange={e => setEstado(e.target.value)}
                  placeholder="UF"
                  maxLength={2}
                />
              </div>
            </div>
          </div>
        );

      case 2:
        return (
          <div className="space-y-6">
            <div>
              <h3 className="text-lg font-medium mb-4">Como você organiza sua agenda?</h3>
              <RadioGroup value={modoAgenda} onValueChange={setModoAgenda} className="space-y-3">
                {MODOS_AGENDA.map(modo => {
                  const Icon = modo.icone;
                  return (
                    <div
                      key={modo.valor}
                      className={`flex items-center space-x-3 p-4 rounded-lg border transition-all ${modoAgenda === modo.valor
                        ? 'border-primary bg-primary/5'
                        : 'border-border hover:border-primary/50'
                        }`}
                    >
                      <RadioGroupItem value={modo.valor} id={modo.valor} />
                      <div className={`p-2 rounded-lg ${modoAgenda === modo.valor ? 'bg-primary text-primary-foreground' : 'bg-muted'}`}>
                        <Icon className="h-4 w-4" />
                      </div>
                      <div className="flex-1">
                        <Label htmlFor={modo.valor} className="font-medium cursor-pointer">
                          {modo.nome}
                        </Label>
                        <p className="text-sm text-muted-foreground">{modo.descricao}</p>
                      </div>
                    </div>
                  );
                })}
              </RadioGroup>
            </div>
          </div>
        );

      case 3:
        return (
          <div className="space-y-6">
            <div>
              <h3 className="text-lg font-medium mb-4">Quais formas de pagamento você aceita?</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                {MEIOS_PAGAMENTO.map(meio => {
                  // Esconder convênio para segmentos que não usam
                  if (meio.id === 'convenio' && !['saude', 'odontologia'].includes(segmentoSelecionado)) {
                    return null;
                  }
                  const isSelected = meiosPagamento.includes(meio.id);
                  return (
                    <div
                      key={meio.id}
                      onClick={() => toggleMeioPagamento(meio.id)}
                      className={`p-3 rounded-lg border cursor-pointer transition-all flex items-center gap-3 ${isSelected
                        ? 'border-primary bg-primary/5'
                        : 'border-border hover:border-primary/50'
                        }`}
                    >
                      <Checkbox checked={isSelected} />
                      <span className="font-medium">{meio.nome}</span>
                    </div>
                  );
                })}
              </div>
            </div>

            <div className="space-y-4 pt-4 border-t">
              <h4 className="font-medium">Políticas de Cobrança</h4>
              <div className="flex items-center justify-between p-3 rounded-lg border">
                <div>
                  <p className="font-medium">Exigir sinal no agendamento</p>
                  <p className="text-sm text-muted-foreground">Solicitar pagamento antecipado</p>
                </div>
                <Switch checked={exigirSinal} onCheckedChange={setExigirSinal} />
              </div>
              <div className="flex items-center justify-between p-3 rounded-lg border">
                <div>
                  <p className="font-medium">Taxa de cancelamento</p>
                  <p className="text-sm text-muted-foreground">Cobrar taxa em cancelamentos tardios</p>
                </div>
                <Switch checked={taxaCancelamento} onCheckedChange={setTaxaCancelamento} />
              </div>
            </div>
          </div>
        );

      case 4:
        return (
          <div className="space-y-6">
            <div>
              <h3 className="text-lg font-medium mb-4">Configure seus lembretes automáticos</h3>
              <div className="space-y-3">
                {LEMBRETES_OPTIONS.map(lembrete => {
                  const isActive = lembretesAtivos.includes(lembrete.id);
                  return (
                    <div
                      key={lembrete.id}
                      className={`p-4 rounded-lg border transition-all ${isActive ? 'border-primary bg-primary/5' : 'border-border'
                        }`}
                    >
                      <div className="flex items-center justify-between">
                        <div>
                          <p className="font-medium">{lembrete.nome}</p>
                          <p className="text-sm text-muted-foreground">{lembrete.descricao}</p>
                        </div>
                        <Switch
                          checked={isActive}
                          onCheckedChange={() => toggleLembrete(lembrete.id)}
                        />
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          </div>
        );

      case 5:
        // Preview step - mostra o que será ativado
        return (
          <div className="space-y-6">
            <div className="flex items-center gap-2 p-3 bg-muted/50 rounded-lg">
              <Eye className="h-5 w-5 text-primary" />
              <div>
                <h3 className="font-medium">Pré-visualização</h3>
                <p className="text-sm text-muted-foreground">Veja o que será ativado para o segmento selecionado</p>
              </div>
            </div>

            {previewLoading ? (
              <div className="flex items-center justify-center py-8">
                <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
                <span className="ml-2 text-muted-foreground">Carregando preview...</span>
              </div>
            ) : previewData ? (
              <Tabs defaultValue="features" className="w-full">
                <TabsList className="grid w-full grid-cols-2">
                  <TabsTrigger value="features" className="flex items-center gap-2">
                    <ToggleLeft className="h-4 w-4" />
                    Recursos ({previewData.total_features})
                  </TabsTrigger>
                  <TabsTrigger value="menu" className="flex items-center gap-2">
                    <Menu className="h-4 w-4" />
                    Menu ({previewData.menu?.length || 0})
                  </TabsTrigger>
                </TabsList>

                <TabsContent value="features" className="mt-4">
                  <ScrollArea className="h-[280px] rounded-md border p-4">
                    <div className="space-y-3">
                      {previewData.features?.map((feature, idx) => (
                        <div
                          key={idx}
                          className={`flex items-center justify-between p-3 rounded-lg border ${feature.habilitado ? 'bg-primary/5 border-primary/20' : 'bg-muted/30'
                            }`}
                        >
                          <div className="flex-1">
                            <div className="flex items-center gap-2">
                              <span className="font-medium capitalize">{feature.recurso.replace(/_/g, ' ')}</span>
                              <Badge variant="outline" className="text-xs">{feature.categoria}</Badge>
                            </div>
                            {feature.descricao && (
                              <p className="text-sm text-muted-foreground mt-1">{feature.descricao}</p>
                            )}
                          </div>
                          <Badge variant={feature.habilitado ? "default" : "secondary"}>
                            {feature.habilitado ? 'Ativo' : 'Inativo'}
                          </Badge>
                        </div>
                      ))}
                    </div>
                  </ScrollArea>
                </TabsContent>

                <TabsContent value="menu" className="mt-4">
                  <ScrollArea className="h-[280px] rounded-md border p-4">
                    <div className="space-y-2">
                      {previewData.menu?.map((item, idx) => (
                        <div
                          key={idx}
                          className="flex items-center gap-3 p-3 rounded-lg border hover:bg-muted/50 transition-colors"
                        >
                          <div className="w-8 h-8 rounded-lg bg-primary/10 flex items-center justify-center">
                            <Menu className="h-4 w-4 text-primary" />
                          </div>
                          <div className="flex-1">
                            <span className="font-medium">{item.label}</span>
                            <p className="text-xs text-muted-foreground">{item.rota}</p>
                          </div>
                        </div>
                      ))}
                    </div>
                  </ScrollArea>
                </TabsContent>
              </Tabs>
            ) : (
              <div className="flex items-center gap-2 p-4 rounded-lg border border-yellow-500/30 bg-yellow-500/10">
                <AlertCircle className="h-5 w-5 text-yellow-600" />
                <span className="text-sm">Selecione um segmento para ver a pré-visualização</span>
              </div>
            )}
          </div>
        );

      case 6:
        const segmento = SEGMENTOS.find(s => s.codigo === segmentoSelecionado);
        const modo = MODOS_AGENDA.find(m => m.valor === modoAgenda);
        return (
          <div className="space-y-6">
            <div>
              <h3 className="text-lg font-medium mb-4">Resumo das suas configurações</h3>

              <div className="space-y-4">
                <Card>
                  <CardHeader className="pb-2">
                    <CardTitle className="text-sm font-medium text-muted-foreground">Segmento</CardTitle>
                  </CardHeader>
                  <CardContent>
                    <div className="flex items-center gap-2">
                      {segmento && <segmento.icone className="h-5 w-5 text-primary" />}
                      <span className="font-medium">{segmento?.nome}</span>
                      <Badge variant="outline">{previewData?.total_features || 0} recursos</Badge>
                    </div>
                    {(cidade || estado) && (
                      <p className="text-sm text-muted-foreground mt-1">
                        {cidade}{cidade && estado ? ', ' : ''}{estado}
                      </p>
                    )}
                  </CardContent>
                </Card>

                <Card>
                  <CardHeader className="pb-2">
                    <CardTitle className="text-sm font-medium text-muted-foreground">Modo de Agenda</CardTitle>
                  </CardHeader>
                  <CardContent>
                    <div className="flex items-center gap-2">
                      {modo && <modo.icone className="h-5 w-5 text-primary" />}
                      <span className="font-medium">{modo?.nome}</span>
                    </div>
                  </CardContent>
                </Card>

                <Card>
                  <CardHeader className="pb-2">
                    <CardTitle className="text-sm font-medium text-muted-foreground">Meios de Pagamento</CardTitle>
                  </CardHeader>
                  <CardContent>
                    <div className="flex flex-wrap gap-2">
                      {meiosPagamento.map(id => {
                        const meio = MEIOS_PAGAMENTO.find(m => m.id === id);
                        return meio && (
                          <Badge key={id} variant="secondary">{meio.nome}</Badge>
                        );
                      })}
                    </div>
                    {(exigirSinal || taxaCancelamento) && (
                      <div className="mt-2 text-sm text-muted-foreground">
                        {exigirSinal && <span className="block">• Sinal no agendamento ativo</span>}
                        {taxaCancelamento && <span className="block">• Taxa de cancelamento ativa</span>}
                      </div>
                    )}
                  </CardContent>
                </Card>

                <Card>
                  <CardHeader className="pb-2">
                    <CardTitle className="text-sm font-medium text-muted-foreground">Lembretes Ativos</CardTitle>
                  </CardHeader>
                  <CardContent>
                    <div className="flex flex-wrap gap-2">
                      {lembretesAtivos.map(id => {
                        const lembrete = LEMBRETES_OPTIONS.find(l => l.id === id);
                        return lembrete && (
                          <Badge key={id} variant="outline">{lembrete.nome}</Badge>
                        );
                      })}
                      {lembretesAtivos.length === 0 && (
                        <span className="text-sm text-muted-foreground">Nenhum lembrete ativado</span>
                      )}
                    </div>
                  </CardContent>
                </Card>
              </div>
            </div>
          </div>
        );

      default:
        return null;
    }
  };

  const getStepIcon = (stepNum: number) => {
    switch (stepNum) {
      case 1: return Building2;
      case 2: return Calendar;
      case 3: return CreditCard;
      case 4: return MessageSquare;
      case 5: return Eye;
      case 6: return Check;
      default: return Building2;
    }
  };

  const getStepTitle = (stepNum: number) => {
    switch (stepNum) {
      case 1: return 'Sobre seu negócio';
      case 2: return 'Modo de agenda';
      case 3: return 'Pagamentos';
      case 4: return 'Lembretes';
      case 5: return 'Pré-visualização';
      case 6: return 'Confirmar';
      default: return '';
    }
  };

  return (
    <div className="min-h-screen bg-background flex items-center justify-center p-4">
      <Card className="w-full max-w-2xl">
        <CardHeader>
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-2">
              {Array.from({ length: totalSteps }).map((_, i) => {
                const stepNum = i + 1;
                const Icon = getStepIcon(stepNum);
                const isActive = step === stepNum;
                const isComplete = step > stepNum;
                return (
                  <div key={i} className="flex items-center">
                    <div
                      className={`w-8 h-8 rounded-full flex items-center justify-center text-sm ${isComplete
                        ? 'bg-primary text-primary-foreground'
                        : isActive
                          ? 'bg-primary text-primary-foreground'
                          : 'bg-muted text-muted-foreground'
                        }`}
                    >
                      {isComplete ? <Check className="h-4 w-4" /> : <Icon className="h-4 w-4" />}
                    </div>
                    {i < totalSteps - 1 && (
                      <div className={`w-6 h-0.5 ${step > stepNum ? 'bg-primary' : 'bg-muted'}`} />
                    )}
                  </div>
                );
              })}
            </div>
            <Badge variant="outline">
              {step} de {totalSteps}
            </Badge>
          </div>
          <Progress value={progress} className="h-1" />
          <CardTitle className="mt-4">{getStepTitle(step)}</CardTitle>
          <CardDescription>
            {step === 1 && 'Conte-nos sobre o seu negócio para personalizarmos sua experiência'}
            {step === 2 && 'Defina como você organiza seus atendimentos'}
            {step === 3 && 'Configure suas formas de pagamento e políticas'}
            {step === 4 && 'Automatize a comunicação com seus clientes'}
            {step === 5 && 'Veja os recursos e menus que serão ativados para seu segmento'}
            {step === 6 && 'Revise todas as configurações antes de finalizar'}
          </CardDescription>
        </CardHeader>

        <CardContent>
          {renderStepContent()}

          <div className="flex justify-between mt-8 pt-6 border-t">
            <Button
              variant="outline"
              onClick={handleBack}
              disabled={loading}
            >
              <ArrowLeft className="h-4 w-4 mr-2" />
              {step === 1 ? 'Voltar' : 'Anterior'}
            </Button>

            {step < totalSteps ? (
              <Button onClick={handleNext}>
                Próximo
                <ArrowRight className="h-4 w-4 ml-2" />
              </Button>
            ) : (
              <Button onClick={handleComplete} disabled={loading}>
                {loading ? 'Aplicando...' : 'Aplicar Configurações'}
                <Check className="h-4 w-4 ml-2" />
              </Button>
            )}
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

import React, { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Slider } from "@/components/ui/slider";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Check, Loader2, ArrowLeft, Tag } from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";

interface Plan {
    id: string;
    name: string;
    slug: string;
    description: string;
    price_monthly: number;
    stripe_price_id: string | null;
    features: string[];
    metadata: {
        type: 'professional' | 'clinic' | 'multi_unit';
        recommended?: boolean;
        extra_seat_price?: number;
    };
}

interface PlanSelectionProps {
    edition: 'solo' | 'company' | 'org';
    onSelect: (selection: { planCode: string; price: number; priceId?: string; seats?: number; units?: number; couponCode?: string }) => void;
    onBack: () => void;
}

export function PlanSelection({ edition, onSelect, onBack }: PlanSelectionProps) {
    const formatCurrency = (value: number) => {
        return value.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    };
    const [plans, setPlans] = useState<Plan[]>([]);
    const [loading, setLoading] = useState(true);

    // State for selections
    const [selectedPlanId, setSelectedPlanId] = useState<string>("");
    const [companySeats, setCompanySeats] = useState(5);
    const [orgUnits, setOrgUnits] = useState(2);

    // Coupon state
    const [couponCode, setCouponCode] = useState("");
    const [validatingCoupon, setValidatingCoupon] = useState(false);
    const [appliedCoupon, setAppliedCoupon] = useState<{ code: string; type: 'percent' | 'fixed'; value: number } | null>(null);

    useEffect(() => {
        fetchPlans();
    }, [edition]);

    const fetchPlans = async () => {
        setLoading(true);
        try {
            let typeFilter = '';
            if (edition === 'solo') typeFilter = 'professional';
            if (edition === 'company') typeFilter = 'clinic';
            if (edition === 'org') typeFilter = 'multi_unit';

            const { data, error } = await supabase
                .from('plans')
                .select('*')
                .eq('active', true)
                .order('price_monthly');

            if (error) throw error;

            if (data) {
                const typedData = data as any[];
                const filteredPlans = typedData.filter(p => p.metadata?.type === typeFilter);

                setPlans(filteredPlans as Plan[]);

                if (filteredPlans.length > 0) {
                    if (edition === 'solo') {
                        const recommended = filteredPlans.find(p => p.metadata?.recommended);
                        setSelectedPlanId(recommended ? recommended.id : filteredPlans[0].id);
                    } else {
                        setSelectedPlanId(filteredPlans[0].id);
                    }
                }
            }
        } catch (error) {
            console.error("Error fetching plans:", error);
        } finally {
            setLoading(false);
        }
    };

    const validateCoupon = async () => {
        if (!couponCode.trim()) return;
        setValidatingCoupon(true);

        try {
            const { data, error } = await supabase
                .from('coupons')
                .select('*')
                .eq('code', couponCode.toUpperCase())
                .eq('active', true)
                .single();

            if (error || !data) {
                toast.error("Cupom inválido ou expirado");
                setAppliedCoupon(null);
                return;
            }

            // Check dates
            const now = new Date();
            if (data.start_date && new Date(data.start_date) > now) {
                toast.error("Cupom ainda não é válido");
                return;
            }
            if (data.end_date && new Date(data.end_date) < now) {
                toast.error("Cupom expirado");
                return;
            }

            // Check usage limit
            if (data.usage_limit && data.times_redeemed >= data.usage_limit) {
                toast.error("Limite de uso do cupom atingido");
                return;
            }

            setAppliedCoupon({
                code: data.code,
                type: data.discount_type as 'percent' | 'fixed',
                value: data.value
            });
            toast.success("Cupom aplicado com sucesso!");
        } catch (error) {
            console.error("Error validating coupon:", error);
            toast.error("Erro ao validar cupom");
        } finally {
            setValidatingCoupon(false);
        }
    };

    const calculateTotal = () => {
        const plan = plans.find(p => p.id === selectedPlanId);
        if (!plan) return 0;

        let total = plan.price_monthly;

        if (edition === 'company') {
            const extraSeats = Math.max(0, companySeats - 5);
            const extraPrice = plan.metadata?.extra_seat_price || 0;
            total = plan.price_monthly + (extraSeats * extraPrice);
        }

        if (edition === 'org') {
            const discount = orgUnits >= 2 ? 0.9 : 1;
            total = plan.price_monthly * orgUnits * discount;
        }

        // Apply coupon
        if (appliedCoupon) {
            if (appliedCoupon.type === 'percent') {
                total = total * (1 - appliedCoupon.value / 100);
            } else {
                total = Math.max(0, total - appliedCoupon.value);
            }
        }

        return total;
    };

    const handleContinue = () => {
        const plan = plans.find(p => p.id === selectedPlanId);
        if (!plan) return;

        onSelect({
            planCode: plan.slug,
            price: calculateTotal(),
            priceId: plan.stripe_price_id || undefined,
            seats: edition === 'company' ? companySeats : undefined,
            units: edition === 'org' ? orgUnits : undefined,
            couponCode: appliedCoupon?.code
        });
    };

    if (loading) {
        return <div className="flex justify-center p-12"><Loader2 className="h-8 w-8 animate-spin text-primary" /></div>;
    }

    return (
        <div className="space-y-6 animate-in fade-in duration-500">
            <div className="flex items-center gap-4 mb-6">
                <Button variant="ghost" size="icon" onClick={onBack}>
                    <ArrowLeft className="h-4 w-4" />
                </Button>
                <div>
                    <h2 className="text-2xl font-bold">Escolha seu Plano</h2>
                    <p className="text-muted-foreground">Selecione o plano ideal para o seu negócio</p>
                </div>
            </div>

            <div className={`grid gap-6 ${edition === 'solo' ? 'grid-cols-1 md:grid-cols-2' : 'grid-cols-1'}`}>
                {plans.map((plan) => {
                    const isSelected = selectedPlanId === plan.id;
                    return (
                        <Card
                            key={plan.id}
                            className={`p-6 cursor-pointer transition-all border-2 ${isSelected ? 'border-primary ring-2 ring-primary/20' : 'border-border hover:border-primary/50'}`}
                            onClick={() => setSelectedPlanId(plan.id)}
                        >
                            <div className="flex justify-between items-start mb-4">
                                <div>
                                    <h3 className="text-xl font-bold">{plan.name}</h3>
                                    <p className="text-sm text-muted-foreground mt-1">{plan.description}</p>
                                    {edition === 'company' && <Badge variant="secondary" className="mt-2">5 Profissionais Inclusos</Badge>}
                                </div>
                                <div className="text-right">
                                    <span className="text-2xl font-bold">
                                        {plan.price_monthly === 0 ? 'Grátis' : `R$ ${formatCurrency(plan.price_monthly)}`}
                                    </span>
                                    {plan.price_monthly > 0 && <p className="text-xs text-muted-foreground">/mês</p>}
                                </div>
                            </div>

                            <ul className="space-y-3 mb-6">
                                {plan.features && plan.features.map((feature, idx) => (
                                    <li key={idx} className="flex items-center text-sm">
                                        <Check className="h-4 w-4 text-primary mr-2 flex-shrink-0" />
                                        {feature}
                                    </li>
                                ))}
                            </ul>

                            {edition === 'company' && isSelected && (
                                <div className="mt-6 pt-6 border-t space-y-4">
                                    <div className="flex justify-between items-center">
                                        <Label>Número de Profissionais</Label>
                                        <span className="font-bold text-lg">{companySeats}</span>
                                    </div>
                                    <Slider
                                        value={[companySeats]}
                                        min={1}
                                        max={50}
                                        step={1}
                                        onValueChange={(vals) => setCompanySeats(vals[0])}
                                    />
                                    <div className="text-sm text-muted-foreground flex justify-between">
                                        <span>5 inclusos</span>
                                        {companySeats > 5 && (
                                            <span className="text-primary font-medium">
                                                +{companySeats - 5} extras (+ R$ {formatCurrency((companySeats - 5) * (plan.metadata?.extra_seat_price || 0))}/mês)
                                            </span>
                                        )}
                                    </div>
                                </div>
                            )}

                            {edition === 'org' && isSelected && (
                                <div className="mt-6 pt-6 border-t space-y-4">
                                    <div className="flex justify-between items-center">
                                        <Label>Número de Unidades</Label>
                                        <div className="flex items-center gap-2">
                                            <Button variant="outline" size="sm" onClick={(e) => { e.stopPropagation(); setOrgUnits(Math.max(2, orgUnits - 1)); }}>-</Button>
                                            <span className="font-bold text-lg w-8 text-center">{orgUnits}</span>
                                            <Button variant="outline" size="sm" onClick={(e) => { e.stopPropagation(); setOrgUnits(orgUnits + 1); }}>+</Button>
                                        </div>
                                    </div>
                                    {orgUnits >= 2 && (
                                        <p className="text-sm text-green-600 font-medium flex items-center">
                                            <Check className="h-3 w-3 mr-1" />
                                            Desconto de 10% aplicado por múltiplas unidades
                                        </p>
                                    )}
                                </div>
                            )}
                        </Card>
                    );
                })}
            </div>

            <div className="flex flex-col gap-4 pt-6 border-t">
                {/* Coupon Section */}
                <div className="flex items-end gap-2 max-w-sm">
                    <div className="flex-1 space-y-2">
                        <Label htmlFor="coupon">Cupom de Desconto</Label>
                        <div className="relative">
                            <Tag className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
                            <Input
                                id="coupon"
                                placeholder="Código do cupom"
                                className="pl-8"
                                value={couponCode}
                                onChange={(e) => setCouponCode(e.target.value)}
                                disabled={!!appliedCoupon}
                            />
                        </div>
                    </div>
                    {appliedCoupon ? (
                        <Button variant="outline" onClick={() => { setAppliedCoupon(null); setCouponCode(""); }}>
                            Remover
                        </Button>
                    ) : (
                        <Button variant="secondary" onClick={validateCoupon} disabled={validatingCoupon || !couponCode}>
                            {validatingCoupon ? <Loader2 className="h-4 w-4 animate-spin" /> : "Aplicar"}
                        </Button>
                    )}
                </div>

                {appliedCoupon && (
                    <div className="text-sm text-green-600 font-medium flex items-center">
                        <Check className="h-3 w-3 mr-1" />
                        Cupom {appliedCoupon.code} aplicado:
                        {appliedCoupon.type === 'percent' ? ` ${appliedCoupon.value}% de desconto` : ` R$ ${appliedCoupon.value} de desconto`}
                    </div>
                )}

                <div className="flex items-center justify-between mt-4">
                    <div className="text-lg">
                        Total estimado: <span className="font-bold text-2xl text-primary">R$ {formatCurrency(calculateTotal())}</span>
                        <span className="text-sm text-muted-foreground">/mês</span>
                    </div>
                    <Button size="lg" onClick={handleContinue} disabled={!selectedPlanId}>
                        Continuar
                    </Button>
                </div>
            </div>
        </div>
    );
}

import React, { useState, useEffect } from 'react';
import { useForm } from "react-hook-form";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Switch } from "@/components/ui/switch";
import { toast } from "sonner";
import { Loader2, Save } from "lucide-react";

interface OrgSettingsFormProps {
    organizationId: string;
}

export function OrgSettingsForm({ organizationId }: OrgSettingsFormProps) {
    const [loading, setLoading] = useState(false);
    const [saving, setSaving] = useState(false);

    const { register, handleSubmit, setValue, watch } = useForm({
        defaultValues: {
            horarios_padrao: {
                start: "09:00",
                end: "18:00",
                weekend: false
            },
            politica_cancelamento: {
                antecedencia_horas: 24,
                multa_percentual: 0
            }
        }
    });

    useEffect(() => {
        loadSettings();
    }, [organizationId]);

    const loadSettings = async () => {
        setLoading(true);
        try {
            const { data, error } = await supabase
                .from('org_settings')
                .select('*')
                .eq('organization_id', organizationId)
                .maybeSingle();

            if (error) throw error;

            if (data) {
                if (data.horarios_padrao) setValue('horarios_padrao', data.horarios_padrao as any);
                if (data.politica_cancelamento) setValue('politica_cancelamento', data.politica_cancelamento as any);
            } else {
                // Create default settings if not exists
                const { error: insertError } = await supabase
                    .from('org_settings')
                    .insert({ organization_id: organizationId });

                if (insertError) throw insertError;
            }
        } catch (error) {
            console.error('Error loading org settings:', error);
            toast.error("Erro ao carregar configurações.");
        } finally {
            setLoading(false);
        }
    };

    const onSubmit = async (data: any) => {
        setSaving(true);
        try {
            const { error } = await supabase
                .from('org_settings')
                .update({
                    horarios_padrao: data.horarios_padrao,
                    politica_cancelamento: data.politica_cancelamento,
                    updated_at: new Date().toISOString()
                })
                .eq('organization_id', organizationId);

            if (error) throw error;
            toast.success("Configurações salvas com sucesso!");
        } catch (error) {
            console.error('Error saving org settings:', error);
            toast.error("Erro ao salvar configurações.");
        } finally {
            setSaving(false);
        }
    };

    if (loading) {
        return <div className="flex justify-center p-8"><Loader2 className="h-8 w-8 animate-spin text-muted-foreground" /></div>;
    }

    return (
        <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
            <Card>
                <CardHeader>
                    <CardTitle>Horários de Funcionamento Padrão</CardTitle>
                    <CardDescription>Estes horários serão aplicados a todas as novas unidades por padrão.</CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                    <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-2">
                            <Label>Abertura</Label>
                            <Input type="time" {...register("horarios_padrao.start")} />
                        </div>
                        <div className="space-y-2">
                            <Label>Fechamento</Label>
                            <Input type="time" {...register("horarios_padrao.end")} />
                        </div>
                    </div>
                    <div className="flex items-center space-x-2">
                        <Switch
                            id="weekend"
                            checked={watch("horarios_padrao.weekend")}
                            onCheckedChange={(checked) => setValue("horarios_padrao.weekend", checked)}
                        />
                        <Label htmlFor="weekend">Funciona aos finais de semana?</Label>
                    </div>
                </CardContent>
            </Card>

            <Card>
                <CardHeader>
                    <CardTitle>Política de Cancelamento</CardTitle>
                    <CardDescription>Regras para cancelamento de agendamentos.</CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                    <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-2">
                            <Label>Antecedência Mínima (horas)</Label>
                            <Input type="number" {...register("politica_cancelamento.antecedencia_horas")} />
                        </div>
                        <div className="space-y-2">
                            <Label>Multa por Cancelamento Tardio (%)</Label>
                            <Input type="number" {...register("politica_cancelamento.multa_percentual")} />
                        </div>
                    </div>
                </CardContent>
            </Card>

            <div className="flex justify-end">
                <Button type="submit" disabled={saving}>
                    {saving && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                    <Save className="mr-2 h-4 w-4" />
                    Salvar Configurações Globais
                </Button>
            </div>
        </form>
    );
}

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { 
  Building2, 
  Users, 
  Calendar, 
  DollarSign, 
  TrendingUp, 
  TrendingDown,
  BarChart3,
  PieChart,
  Activity,
  ArrowUpRight,
  ArrowDownRight
} from 'lucide-react';
import { useOrganizationContext } from '@/hooks/useOrganizationContext';
import { supabase } from '@/integrations/supabase/client';

interface UnitMetrics {
  unit_id: string;
  unit_name: string;
  is_matriz: boolean;
  appointments_count: number;
  patients_count: number;
  revenue: number;
  occupancy_rate: number;
  no_show_rate: number;
}

export function OrganizationDashboard() {
  const { organization, units, isOrgAdmin } = useOrganizationContext();
  const [viewMode, setViewMode] = useState<'consolidated' | 'per_unit'>('consolidated');
  const [selectedPeriod, setSelectedPeriod] = useState('month');
  const [metrics, setMetrics] = useState<UnitMetrics[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (organization?.id) {
      fetchMetrics();
    }
  }, [organization?.id, selectedPeriod]);

  const fetchMetrics = async () => {
    setLoading(true);
    try {
      // Buscar métricas por unidade
      const unitMetrics: UnitMetrics[] = [];

      for (const unit of units) {
        // Contagem de agendamentos
        const { count: appointmentsCount } = await supabase
          .from('agenda')
          .select('*', { count: 'exact', head: true })
          .eq('unit_id', unit.id);

        // Contagem de pacientes
        const { count: patientsCount } = await supabase
          .from('pacientes')
          .select('*', { count: 'exact', head: true })
          .eq('organization_id', organization?.id);

        // Receita (soma do caixa diário)
        const { data: revenueData } = await supabase
          .from('caixa_diario')
          .select('valor')
          .eq('unit_id', unit.id)
          .eq('tipo_lancamento', 'entrada');

        const revenue = revenueData?.reduce((sum, r) => sum + (r.valor || 0), 0) || 0;

        unitMetrics.push({
          unit_id: unit.id,
          unit_name: unit.nome_unidade,
          is_matriz: unit.is_matriz,
          appointments_count: appointmentsCount || 0,
          patients_count: patientsCount || 0,
          revenue,
          occupancy_rate: Math.random() * 40 + 60, // Mock
          no_show_rate: Math.random() * 15 + 5, // Mock
        });
      }

      setMetrics(unitMetrics);
    } catch (error) {
      console.error('Error fetching metrics:', error);
    } finally {
      setLoading(false);
    }
  };

  const totalRevenue = metrics.reduce((sum, m) => sum + m.revenue, 0);
  const totalAppointments = metrics.reduce((sum, m) => sum + m.appointments_count, 0);
  const totalPatients = metrics.reduce((sum, m) => sum + m.patients_count, 0);
  const avgOccupancy = metrics.length > 0 
    ? metrics.reduce((sum, m) => sum + m.occupancy_rate, 0) / metrics.length 
    : 0;

  if (!isOrgAdmin) {
    return null;
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold">{organization?.nome_fantasia}</h2>
          <p className="text-muted-foreground">Dashboard da Organização</p>
        </div>
        <div className="flex items-center gap-4">
          <Select value={selectedPeriod} onValueChange={setSelectedPeriod}>
            <SelectTrigger className="w-[180px]">
              <SelectValue placeholder="Período" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="today">Hoje</SelectItem>
              <SelectItem value="week">Esta Semana</SelectItem>
              <SelectItem value="month">Este Mês</SelectItem>
              <SelectItem value="quarter">Este Trimestre</SelectItem>
              <SelectItem value="year">Este Ano</SelectItem>
            </SelectContent>
          </Select>
          <Tabs value={viewMode} onValueChange={(v) => setViewMode(v as any)}>
            <TabsList>
              <TabsTrigger value="consolidated">Consolidado</TabsTrigger>
              <TabsTrigger value="per_unit">Por Unidade</TabsTrigger>
            </TabsList>
          </Tabs>
        </div>
      </div>

      {viewMode === 'consolidated' ? (
        <>
          {/* Cards de resumo consolidado */}
          <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
            <Card>
              <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                <CardTitle className="text-sm font-medium">Receita Total</CardTitle>
                <DollarSign className="h-4 w-4 text-muted-foreground" />
              </CardHeader>
              <CardContent>
                <div className="text-2xl font-bold">
                  {totalRevenue.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}
                </div>
                <p className="text-xs text-muted-foreground flex items-center gap-1">
                  <ArrowUpRight className="h-3 w-3 text-green-500" />
                  +12.5% vs período anterior
                </p>
              </CardContent>
            </Card>
            <Card>
              <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                <CardTitle className="text-sm font-medium">Agendamentos</CardTitle>
                <Calendar className="h-4 w-4 text-muted-foreground" />
              </CardHeader>
              <CardContent>
                <div className="text-2xl font-bold">{totalAppointments}</div>
                <p className="text-xs text-muted-foreground">
                  Em {units.length} unidades
                </p>
              </CardContent>
            </Card>
            <Card>
              <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                <CardTitle className="text-sm font-medium">Pacientes Ativos</CardTitle>
                <Users className="h-4 w-4 text-muted-foreground" />
              </CardHeader>
              <CardContent>
                <div className="text-2xl font-bold">{totalPatients}</div>
                <p className="text-xs text-muted-foreground flex items-center gap-1">
                  <ArrowUpRight className="h-3 w-3 text-green-500" />
                  +5.2% novos pacientes
                </p>
              </CardContent>
            </Card>
            <Card>
              <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                <CardTitle className="text-sm font-medium">Ocupação Média</CardTitle>
                <Activity className="h-4 w-4 text-muted-foreground" />
              </CardHeader>
              <CardContent>
                <div className="text-2xl font-bold">{avgOccupancy.toFixed(1)}%</div>
                <p className="text-xs text-muted-foreground">
                  Taxa de ocupação das agendas
                </p>
              </CardContent>
            </Card>
          </div>

          {/* Ranking de unidades */}
          <Card>
            <CardHeader>
              <CardTitle>Ranking de Unidades</CardTitle>
              <CardDescription>Desempenho comparativo entre unidades</CardDescription>
            </CardHeader>
            <CardContent>
              <div className="space-y-4">
                {metrics
                  .sort((a, b) => b.revenue - a.revenue)
                  .map((unit, index) => (
                    <div key={unit.unit_id} className="flex items-center gap-4">
                      <div className="flex items-center justify-center w-8 h-8 rounded-full bg-primary/10 text-primary font-bold">
                        {index + 1}
                      </div>
                      <div className="flex-1">
                        <div className="flex items-center gap-2">
                          <span className="font-medium">{unit.unit_name}</span>
                          {unit.is_matriz && <Badge variant="secondary">Matriz</Badge>}
                        </div>
                        <div className="flex gap-4 text-sm text-muted-foreground">
                          <span>{unit.appointments_count} agendamentos</span>
                          <span>{unit.occupancy_rate.toFixed(0)}% ocupação</span>
                        </div>
                      </div>
                      <div className="text-right">
                        <p className="font-semibold">
                          {unit.revenue.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}
                        </p>
                        <p className="text-sm text-muted-foreground">
                          {((unit.revenue / totalRevenue) * 100).toFixed(1)}% do total
                        </p>
                      </div>
                    </div>
                  ))}
              </div>
            </CardContent>
          </Card>
        </>
      ) : (
        /* Visão por unidade */
        <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
          {metrics.map(unit => (
            <Card key={unit.unit_id}>
              <CardHeader>
                <div className="flex items-center justify-between">
                  <CardTitle className="flex items-center gap-2">
                    <Building2 className="h-5 w-5" />
                    {unit.unit_name}
                  </CardTitle>
                  {unit.is_matriz && <Badge>Matriz</Badge>}
                </div>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <p className="text-sm text-muted-foreground">Receita</p>
                    <p className="text-xl font-bold">
                      {unit.revenue.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}
                    </p>
                  </div>
                  <div>
                    <p className="text-sm text-muted-foreground">Agendamentos</p>
                    <p className="text-xl font-bold">{unit.appointments_count}</p>
                  </div>
                  <div>
                    <p className="text-sm text-muted-foreground">Ocupação</p>
                    <p className="text-xl font-bold flex items-center gap-1">
                      {unit.occupancy_rate.toFixed(0)}%
                      {unit.occupancy_rate > 70 ? (
                        <TrendingUp className="h-4 w-4 text-green-500" />
                      ) : (
                        <TrendingDown className="h-4 w-4 text-red-500" />
                      )}
                    </p>
                  </div>
                  <div>
                    <p className="text-sm text-muted-foreground">No-Show</p>
                    <p className="text-xl font-bold text-destructive">
                      {unit.no_show_rate.toFixed(1)}%
                    </p>
                  </div>
                </div>
                <Button variant="outline" className="w-full">
                  Ver Detalhes
                </Button>
              </CardContent>
            </Card>
          ))}
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
