interface PermissionSwitchProps {
  label: string;
  description?: string;
  checked: boolean;
  onCheckedChange: (checked: boolean) => void;
  icon?: React.ReactNode;
}

function PermissionSwitch({ label, description, checked, onCheckedChange, icon }: PermissionSwitchProps) {
  return (
    <div className="flex items-center justify-between p-3 rounded-lg border">
      <div className="flex items-center gap-3">
        {icon && <span className="text-muted-foreground">{icon}</span>}
        <div>
          <p className="font-medium text-sm">{label}</p>
          {description && <p className="text-xs text-muted-foreground">{description}</p>}
        </div>
      </div>
      <Switch checked={checked} onCheckedChange={onCheckedChange} />
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { useForm } from "react-hook-form";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Switch } from "@/components/ui/switch";
import { Separator } from "@/components/ui/separator";
import { toast } from "sonner";
import { Loader2 } from "lucide-react";

interface UnitSettingsDialogProps {
    unitId: string | null;
    organizationId: string;
    open: boolean;
    onOpenChange: (open: boolean) => void;
}

export function UnitSettingsDialog({ unitId, organizationId, open, onOpenChange }: UnitSettingsDialogProps) {
    const [loading, setLoading] = useState(false);
    const [saving, setSaving] = useState(false);
    const [orgSettings, setOrgSettings] = useState<any>(null);

    const { register, handleSubmit, setValue, watch, reset } = useForm({
        defaultValues: {
            override_horarios: false,
            horarios_customizados: { start: "09:00", end: "18:00", weekend: false },
            override_politica: false,
            politica_customizada: { antecedencia_horas: 24, multa_percentual: 0 }
        }
    });

    const overrideHorarios = watch("override_horarios");
    const overridePolitica = watch("override_politica");

    useEffect(() => {
        if (open && unitId && organizationId) {
            loadData();
        }
    }, [open, unitId, organizationId]);

    const loadData = async () => {
        setLoading(true);
        try {
            // Load Org Settings for reference
            const { data: orgData } = await supabase
                .from('org_settings')
                .select('*')
                .eq('organization_id', organizationId)
                .maybeSingle();
            setOrgSettings(orgData || {});

            // Load Unit Settings
            const { data: unitData, error } = await supabase
                .from('unit_settings')
                .select('*')
                .eq('unit_id', unitId)
                .maybeSingle();

            if (error) throw error;

            if (unitData) {
                setValue('override_horarios', unitData.override_horarios || false);
                if (unitData.horarios_customizados) setValue('horarios_customizados', unitData.horarios_customizados as any);

                setValue('override_politica', unitData.override_politica || false);
                if (unitData.politica_customizada) setValue('politica_customizada', unitData.politica_customizada as any);
            } else {
                // Create if not exists
                await supabase.from('unit_settings').insert({ unit_id: unitId, organization_id: organizationId });
                reset();
            }
        } catch (error) {
            console.error('Error loading settings:', error);
            toast.error("Erro ao carregar configurações.");
        } finally {
            setLoading(false);
        }
    };

    const onSubmit = async (data: any) => {
        if (!unitId) return;
        setSaving(true);
        try {
            const { error } = await supabase
                .from('unit_settings')
                .update({
                    override_horarios: data.override_horarios,
                    horarios_customizados: data.horarios_customizados,
                    override_politica: data.override_politica,
                    politica_customizada: data.politica_customizada,
                    updated_at: new Date().toISOString()
                })
                .eq('unit_id', unitId);

            if (error) throw error;
            toast.success("Configurações da unidade salvas!");
            onOpenChange(false);
        } catch (error) {
            console.error('Error saving unit settings:', error);
            toast.error("Erro ao salvar configurações.");
        } finally {
            setSaving(false);
        }
    };

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="max-w-lg max-h-[90vh] overflow-y-auto">
                <DialogHeader>
                    <DialogTitle>Configurações da Unidade</DialogTitle>
                </DialogHeader>

                {loading ? (
                    <div className="flex justify-center p-8"><Loader2 className="h-8 w-8 animate-spin text-muted-foreground" /></div>
                ) : (
                    <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">

                        {/* Horários */}
                        <div className="space-y-4 border p-4 rounded-md">
                            <div className="flex items-center justify-between">
                                <Label className="text-base font-semibold">Horários de Funcionamento</Label>
                                <div className="flex items-center space-x-2">
                                    <Switch
                                        checked={overrideHorarios}
                                        onCheckedChange={(c) => setValue("override_horarios", c)}
                                    />
                                    <span className="text-sm text-muted-foreground">Personalizar</span>
                                </div>
                            </div>

                            {!overrideHorarios && orgSettings && (
                                <div className="text-sm text-muted-foreground bg-muted p-2 rounded">
                                    Herdando da organização: {orgSettings.horarios_padrao?.start} - {orgSettings.horarios_padrao?.end}
                                </div>
                            )}

                            {overrideHorarios && (
                                <div className="grid grid-cols-2 gap-4 pt-2">
                                    <div className="space-y-2">
                                        <Label>Abertura</Label>
                                        <Input type="time" {...register("horarios_customizados.start")} />
                                    </div>
                                    <div className="space-y-2">
                                        <Label>Fechamento</Label>
                                        <Input type="time" {...register("horarios_customizados.end")} />
                                    </div>
                                </div>
                            )}
                        </div>

                        {/* Política */}
                        <div className="space-y-4 border p-4 rounded-md">
                            <div className="flex items-center justify-between">
                                <Label className="text-base font-semibold">Política de Cancelamento</Label>
                                <div className="flex items-center space-x-2">
                                    <Switch
                                        checked={overridePolitica}
                                        onCheckedChange={(c) => setValue("override_politica", c)}
                                    />
                                    <span className="text-sm text-muted-foreground">Personalizar</span>
                                </div>
                            </div>

                            {!overridePolitica && orgSettings && (
                                <div className="text-sm text-muted-foreground bg-muted p-2 rounded">
                                    Herdando da organização: {orgSettings.politica_cancelamento?.antecedencia_horas}h antecedência
                                </div>
                            )}

                            {overridePolitica && (
                                <div className="grid grid-cols-2 gap-4 pt-2">
                                    <div className="space-y-2">
                                        <Label>Antecedência (h)</Label>
                                        <Input type="number" {...register("politica_customizada.antecedencia_horas")} />
                                    </div>
                                    <div className="space-y-2">
                                        <Label>Multa (%)</Label>
                                        <Input type="number" {...register("politica_customizada.multa_percentual")} />
                                    </div>
                                </div>
                            )}
                        </div>

                        <DialogFooter>
                            <Button type="button" variant="outline" onClick={() => onOpenChange(false)}>Cancelar</Button>
                            <Button type="submit" disabled={saving}>
                                {saving && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                                Salvar
                            </Button>
                        </DialogFooter>
                    </form>
                )}
            </DialogContent>
        </Dialog>
    );
}

import React, { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Switch } from "@/components/ui/switch";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useToast } from "@/hooks/use-toast";
import { supabase } from "@/integrations/supabase/client";
import { Loader2 } from "lucide-react";
import { useAuth } from "@/hooks/useAuth";

interface Service {
  id: string;
  nome: string;
}

interface EditPacoteDialogProps {
  pacoteId: string;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSuccess?: () => void;
}

export function EditPacoteDialog({
  pacoteId,
  open,
  onOpenChange,
  onSuccess
}: EditPacoteDialogProps) {
  const [isLoading, setIsLoading] = useState(false);
  const [services, setServices] = useState<Service[]>([]);
  const { profile } = useAuth();
  const [formData, setFormData] = useState({
    nome: "",
    descricao: "",
    servico_id: "",
    numero_sessoes: "",
    preco: "",
    validade_dias: "90",
    renovacao_automatica: false,
    desconto_renovacao: "0",
    limiar_renovacao: "2",
    oferta_renovacao_ativa: true,
    ativo: true
  });

  const { toast } = useToast();

  useEffect(() => {
    if (open && profile?.tenant_id) {
      fetchServices();
      if (pacoteId) {
        fetchPacote();
      }
    }
  }, [open, pacoteId, profile?.tenant_id]);

  const fetchServices = async () => {
    try {
      const { data, error } = await supabase
        .from('servicos')
        .select('id, nome')
        .eq('tenant_id', profile.tenant_id)
        .eq('ativo', true)
        .order('nome');

      if (error) throw error;
      setServices(data || []);
    } catch (error) {
      console.error('Erro ao buscar procedimentos:', error);
    }
  };

  const fetchPacote = async () => {
    try {
      const { data, error } = await supabase
        .from('pacotes')
        .select('*')
        .eq('id', pacoteId)
        .single();

      if (error) throw error;

      setFormData({
        nome: data.nome || "",
        descricao: data.descricao || "",
        servico_id: data.servico_id || "",
        numero_sessoes: data.numero_sessoes?.toString() || "",
        preco: data.preco?.toString() || "",
        validade_dias: data.validade_dias?.toString() || "90",
        renovacao_automatica: data.renovacao_automatica || false,
        desconto_renovacao: data.desconto_renovacao?.toString() || "0",
        limiar_renovacao: data.limiar_renovacao?.toString() || "2",
        oferta_renovacao_ativa: data.oferta_renovacao_ativa !== false,
        ativo: data.ativo !== false
      });
    } catch (error) {
      console.error('Erro ao buscar pacote:', error);
      toast({
        title: "Erro",
        description: "Não foi possível carregar os dados do pacote.",
        variant: "destructive"
      });
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.nome || !formData.numero_sessoes || !formData.preco) {
      toast({
        title: "Campos obrigatórios",
        description: "Nome, número de sessões e preço são obrigatórios.",
        variant: "destructive"
      });
      return;
    }

    try {
      setIsLoading(true);

      const { error } = await supabase
        .from('pacotes')
        .update({
          nome: formData.nome.trim(),
          descricao: formData.descricao.trim() || null,
          servico_id: formData.servico_id || null,
          numero_sessoes: parseInt(formData.numero_sessoes),
          preco: parseFloat(formData.preco),
          validade_dias: parseInt(formData.validade_dias),
          renovacao_automatica: formData.renovacao_automatica,
          desconto_renovacao: parseFloat(formData.desconto_renovacao),
          limiar_renovacao: parseInt(formData.limiar_renovacao),
          oferta_renovacao_ativa: formData.oferta_renovacao_ativa,
          ativo: formData.ativo,
          updated_at: new Date().toISOString()
        })
        .eq('id', pacoteId);

      if (error) throw error;

      toast({
        title: "Sucesso!",
        description: "Pacote atualizado com sucesso."
      });

      onOpenChange(false);

      if (onSuccess) {
        onSuccess();
      }
    } catch (error) {
      console.error('Erro ao atualizar:', error);
      toast({
        title: "Erro",
        description: "Não foi possível atualizar o pacote.",
        variant: "destructive"
      });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="text-xl">Editar Pacote</DialogTitle>
          <DialogDescription>
            Atualize as informações do pacote de tratamento
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="nome">Nome do Pacote *</Label>
            <Input
              id="nome"
              value={formData.nome}
              onChange={(e) => setFormData({ ...formData, nome: e.target.value })}
              placeholder="Ex: Pacote 10 Sessões"
              required
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="descricao">Descrição</Label>
            <Textarea
              id="descricao"
              value={formData.descricao}
              onChange={(e) => setFormData({ ...formData, descricao: e.target.value })}
              placeholder="Descrição do pacote..."
              rows={2}
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="servico">Procedimento (Opcional)</Label>
            <Select value={formData.servico_id} onValueChange={(value) => setFormData({ ...formData, servico_id: value })}>
              <SelectTrigger>
                <SelectValue placeholder="Selecione um procedimento" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="">Nenhum procedimento específico</SelectItem>
                {services.map((service) => (
                  <SelectItem key={service.id} value={service.id}>
                    {service.nome}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="numero_sessoes">Número de Sessões *</Label>
              <Input
                id="numero_sessoes"
                type="number"
                min="1"
                value={formData.numero_sessoes}
                onChange={(e) => setFormData({ ...formData, numero_sessoes: e.target.value })}
                placeholder="10"
                required
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="preco">Preço (R$) *</Label>
              <Input
                id="preco"
                type="number"
                step="0.01"
                min="0"
                value={formData.preco}
                onChange={(e) => setFormData({ ...formData, preco: e.target.value })}
                placeholder="500.00"
                required
              />
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="validade">Validade (dias)</Label>
            <Input
              id="validade"
              type="number"
              min="1"
              value={formData.validade_dias}
              onChange={(e) => setFormData({ ...formData, validade_dias: e.target.value })}
              placeholder="90"
            />
          </div>

          <div className="flex items-center justify-between">
            <Label htmlFor="renovacao">Renovação Automática</Label>
            <Switch
              id="renovacao"
              checked={formData.renovacao_automatica}
              onCheckedChange={(checked) => setFormData({ ...formData, renovacao_automatica: checked })}
            />
          </div>

          {formData.renovacao_automatica && (
            <div className="space-y-2">
              <Label htmlFor="desconto">Desconto na Renovação (%)</Label>
              <Input
                id="desconto"
                type="number"
                step="0.01"
                min="0"
                max="100"
                value={formData.desconto_renovacao}
                onChange={(e) => setFormData({ ...formData, desconto_renovacao: e.target.value })}
                placeholder="10"
              />
            </div>
          )}

          <div className="flex items-center justify-between">
            <Label htmlFor="oferta">Oferecer Renovação Automática</Label>
            <Switch
              id="oferta"
              checked={formData.oferta_renovacao_ativa}
              onCheckedChange={(checked) => setFormData({ ...formData, oferta_renovacao_ativa: checked })}
            />
          </div>

          {formData.oferta_renovacao_ativa && (
            <div className="space-y-2">
              <Label htmlFor="limiar">
                Sessões Restantes para Oferta de Renovação
              </Label>
              <Input
                id="limiar"
                type="number"
                min="1"
                max="10"
                value={formData.limiar_renovacao}
                onChange={(e) => setFormData({ ...formData, limiar_renovacao: e.target.value })}
                placeholder="2"
              />
              <p className="text-xs text-muted-foreground">
                Quando restarem este número de sessões, o sistema oferecerá renovação
              </p>
            </div>
          )}

          <div className="flex items-center justify-between">
            <Label htmlFor="ativo">Pacote ativo?</Label>
            <Switch
              id="ativo"
              checked={formData.ativo}
              onCheckedChange={(checked) => setFormData({ ...formData, ativo: checked })}
            />
          </div>

          <div className="flex justify-end gap-3 pt-4">
            <Button
              type="button"
              variant="outline"
              onClick={() => onOpenChange(false)}
              disabled={isLoading}
            >
              Cancelar
            </Button>
            <Button type="submit" disabled={isLoading}>
              {isLoading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Salvar Alterações
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger, DialogDescription } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Switch } from "@/components/ui/switch";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useToast } from "@/hooks/use-toast";
import { supabase } from "@/integrations/supabase/client";
import { Loader2, Plus } from "lucide-react";
import { useAuth } from "@/hooks/useAuth";

interface NewPacoteDialogProps {
  children?: React.ReactNode;
  onSuccess?: () => void;
}

export function NewPacoteDialog({ children, onSuccess }: NewPacoteDialogProps) {
  const [open, setOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [servicos, setServicos] = useState<any[]>([]);
  const { profile } = useAuth();

  const [formData, setFormData] = useState({
    nome: "",
    descricao: "",
    servico_id: "",
    numero_sessoes: "",
    preco: "",
    validade_dias: "90",
    renovacao_automatica: false,
    desconto_renovacao: "0",
    limiar_renovacao: "2",
    oferta_renovacao_ativa: true
  });

  const { toast } = useToast();

  useEffect(() => {
    if (open && profile?.tenant_id) {
      fetchServicos();
    }
  }, [open, profile?.tenant_id]);

  const fetchServicos = async () => {
    try {
      const { data, error } = await supabase
        .from('servicos')
        .select('id, nome')
        .eq('tenant_id', profile.tenant_id)
        .eq('ativo', true)
        .order('nome');

      if (error) throw error;
      setServicos(data || []);
    } catch (error) {
      console.error('Erro ao buscar procedimentos:', error);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.nome || !formData.numero_sessoes || !formData.preco) {
      toast({
        title: "Campos obrigatórios",
        description: "Por favor, preencha todos os campos obrigatórios.",
        variant: "destructive"
      });
      return;
    }

    // Validações adicionais
    const numSessoes = parseInt(formData.numero_sessoes);
    const preco = parseFloat(formData.preco);
    const validadeDias = parseInt(formData.validade_dias);
    const descontoRenovacao = parseFloat(formData.desconto_renovacao);

    if (numSessoes <= 0) {
      toast({
        title: "Número de sessões inválido",
        description: "O número de sessões deve ser maior que zero.",
        variant: "destructive"
      });
      return;
    }

    if (preco <= 0) {
      toast({
        title: "Preço inválido",
        description: "O preço deve ser maior que zero.",
        variant: "destructive"
      });
      return;
    }

    if (validadeDias <= 0) {
      toast({
        title: "Validade inválida",
        description: "A validade deve ser maior que zero dias.",
        variant: "destructive"
      });
      return;
    }

    if (descontoRenovacao < 0 || descontoRenovacao > 100) {
      toast({
        title: "Desconto inválido",
        description: "O desconto deve estar entre 0% e 100%.",
        variant: "destructive"
      });
      return;
    }

    try {
      setIsLoading(true);

      if (!profile?.tenant_id) throw new Error("Tenant não encontrado");

      const { error } = await supabase
        .from('pacotes')
        .insert([{
          tenant_id: profile.tenant_id,
          nome: formData.nome.trim(),
          descricao: formData.descricao?.trim() || null,
          servico_id: formData.servico_id || null,
          numero_sessoes: numSessoes,
          preco: preco,
          validade_dias: validadeDias,
          renovacao_automatica: formData.renovacao_automatica,
          desconto_renovacao: descontoRenovacao,
          limiar_renovacao: parseInt(formData.limiar_renovacao),
          oferta_renovacao_ativa: formData.oferta_renovacao_ativa,
          ativo: true
        }]);

      if (error) {
        if (error.code === '23505') {
          throw new Error("Já existe um pacote com este nome");
        }
        throw error;
      }

      toast({
        title: "Sucesso!",
        description: "Pacote criado com sucesso."
      });

      setOpen(false);
      setFormData({
        nome: "",
        descricao: "",
        servico_id: "",
        numero_sessoes: "",
        preco: "",
        validade_dias: "90",
        renovacao_automatica: false,
        desconto_renovacao: "0",
        limiar_renovacao: "2",
        oferta_renovacao_ativa: true
      });

      if (onSuccess) onSuccess();
    } catch (error) {
      console.error('Erro ao criar pacote:', error);
      toast({
        title: "Erro",
        description: "Não foi possível criar o pacote.",
        variant: "destructive"
      });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        {children || (
          <Button>
            <Plus className="h-4 w-4 mr-2" />
            Novo Pacote
          </Button>
        )}
      </DialogTrigger>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="text-2xl">Novo Pacote de Tratamento</DialogTitle>
          <DialogDescription>
            Crie um pacote de sessões para oferecer aos seus clientes
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="space-y-2">
            <Label htmlFor="nome">Nome do Pacote *</Label>
            <Input
              id="nome"
              value={formData.nome}
              onChange={(e) => setFormData({ ...formData, nome: e.target.value })}
              placeholder="Ex: Pacote 10 Sessões Depilação a Laser"
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="descricao">Descrição</Label>
            <Textarea
              id="descricao"
              value={formData.descricao}
              onChange={(e) => setFormData({ ...formData, descricao: e.target.value })}
              placeholder="Descreva os benefícios e detalhes do pacote..."
              rows={3}
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="servico">Procedimento Relacionado (Opcional)</Label>
            <Select
              value={formData.servico_id}
              onValueChange={(value) => setFormData({ ...formData, servico_id: value === "none" ? "" : value })}
            >
              <SelectTrigger id="servico">
                <SelectValue placeholder="Selecione um procedimento" />
              </SelectTrigger>
              <SelectContent className="bg-background z-50">
                <SelectItem value="none">Nenhum procedimento específico</SelectItem>
                {servicos.map((servico) => (
                  <SelectItem key={servico.id} value={servico.id}>
                    {servico.nome}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="numero_sessoes">Número de Sessões *</Label>
              <Input
                id="numero_sessoes"
                type="number"
                min="1"
                value={formData.numero_sessoes}
                onChange={(e) => setFormData({ ...formData, numero_sessoes: e.target.value })}
                placeholder="Ex: 10"
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="preco">Preço do Pacote (R$) *</Label>
              <Input
                id="preco"
                type="number"
                step="0.01"
                min="0"
                value={formData.preco}
                onChange={(e) => setFormData({ ...formData, preco: e.target.value })}
                placeholder="Ex: 1500.00"
              />
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="validade_dias">Validade (dias)</Label>
            <Input
              id="validade_dias"
              type="number"
              min="1"
              value={formData.validade_dias}
              onChange={(e) => setFormData({ ...formData, validade_dias: e.target.value })}
              placeholder="Ex: 90"
            />
            <p className="text-xs text-muted-foreground">
              Prazo para usar todas as sessões do pacote
            </p>
          </div>

          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <Label htmlFor="renovacao_automatica">Renovação Automática</Label>
                <p className="text-xs text-muted-foreground">
                  Renovar automaticamente quando expirar
                </p>
              </div>
              <Switch
                id="renovacao_automatica"
                checked={formData.renovacao_automatica}
                onCheckedChange={(checked) => setFormData({ ...formData, renovacao_automatica: checked })}
              />
            </div>

            {formData.renovacao_automatica && (
              <div className="space-y-2">
                <Label htmlFor="desconto_renovacao">Desconto na Renovação (%)</Label>
                <Input
                  id="desconto_renovacao"
                  type="number"
                  step="0.01"
                  min="0"
                  max="100"
                  value={formData.desconto_renovacao}
                  onChange={(e) => setFormData({ ...formData, desconto_renovacao: e.target.value })}
                  placeholder="Ex: 10"
                />
              </div>
            )}

            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <Label htmlFor="oferta_renovacao_ativa">Oferecer Renovação Automática</Label>
                <p className="text-xs text-muted-foreground">
                  Notificar paciente quando próximo ao término
                </p>
              </div>
              <Switch
                id="oferta_renovacao_ativa"
                checked={formData.oferta_renovacao_ativa}
                onCheckedChange={(checked) => setFormData({ ...formData, oferta_renovacao_ativa: checked })}
              />
            </div>

            {formData.oferta_renovacao_ativa && (
              <div className="space-y-2">
                <Label htmlFor="limiar_renovacao">
                  Sessões Restantes para Oferta de Renovação
                </Label>
                <Input
                  id="limiar_renovacao"
                  type="number"
                  min="1"
                  max="10"
                  value={formData.limiar_renovacao}
                  onChange={(e) => setFormData({ ...formData, limiar_renovacao: e.target.value })}
                  placeholder="2"
                />
                <p className="text-xs text-muted-foreground">
                  Quando restarem este número de sessões, o sistema oferecerá renovação
                </p>
              </div>
            )}
          </div>

          <div className="flex justify-end gap-3 pt-4">
            <Button
              type="button"
              variant="outline"
              onClick={() => setOpen(false)}
              disabled={isLoading}
            >
              Cancelar
            </Button>
            <Button type="submit" disabled={isLoading}>
              {isLoading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Criar Pacote
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger, DialogDescription } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { useToast } from "@/hooks/use-toast";
import { supabase } from "@/integrations/supabase/client";
import { Loader2, Package } from "lucide-react";

interface VincularPacoteDialogProps {
  pacienteId: string;
  pacienteNome: string;
  onSuccess?: () => void;
}

export function VincularPacoteDialog({ pacienteId, pacienteNome, onSuccess }: VincularPacoteDialogProps) {
  const [open, setOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [pacotes, setPacotes] = useState<any[]>([]);
  const [pacoteSelecionado, setPacoteSelecionado] = useState<any>(null);
  const [renovacaoAutomatica, setRenovacaoAutomatica] = useState(false);

  const { toast } = useToast();

  useEffect(() => {
    if (open) {
      fetchPacotes();
    }
  }, [open]);

  const fetchPacotes = async () => {
    try {
      const { data, error } = await supabase
        .from('pacotes')
        .select('*')
        .eq('ativo', true)
        .order('nome');

      if (error) throw error;
      setPacotes(data || []);
    } catch (error) {
      console.error('Erro ao buscar pacotes:', error);
    }
  };

  const handlePacoteChange = (pacoteId: string) => {
    const pacote = pacotes.find(p => p.id === pacoteId);
    setPacoteSelecionado(pacote);
    if (pacote) {
      setRenovacaoAutomatica(pacote.renovacao_automatica);
    }
  };

  const handleSubmit = async () => {
    if (!pacoteSelecionado) {
      toast({
        title: "Selecione um pacote",
        description: "Por favor, selecione um pacote para vincular.",
        variant: "destructive"
      });
      return;
    }

    try {
      setIsLoading(true);

      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error("Usuário não autenticado");

      const { data: profile } = await supabase
        .from('profiles')
        .select('tenant_id')
        .eq('id', user.id)
        .maybeSingle();

      if (!profile?.tenant_id) throw new Error("Tenant não encontrado");

      // Calcular data de validade
      const dataValidade = new Date();
      dataValidade.setDate(dataValidade.getDate() + pacoteSelecionado.validade_dias);

      const { error } = await supabase
        .from('pacientes_pacotes')
        .insert([{
          tenant_id: profile.tenant_id,
          paciente_id: pacienteId,
          pacote_id: pacoteSelecionado.id,
          sessoes_restantes: pacoteSelecionado.numero_sessoes,
          sessoes_total: pacoteSelecionado.numero_sessoes,
          data_compra: new Date().toISOString(),
          data_validade: dataValidade.toISOString(),
          renovacao_automatica: renovacaoAutomatica,
          valor_pago: pacoteSelecionado.preco,
          status: 'ativo'
        }]);

      if (error) throw error;

      toast({
        title: "Sucesso!",
        description: `Pacote "${pacoteSelecionado.nome}" vinculado a ${pacienteNome}.`
      });

      setOpen(false);
      setPacoteSelecionado(null);

      if (onSuccess) onSuccess();
    } catch (error) {
      console.error('Erro ao vincular pacote:', error);
      toast({
        title: "Erro",
        description: "Não foi possível vincular o pacote ao paciente.",
        variant: "destructive"
      });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button variant="outline" size="sm">
          <Package className="h-4 w-4 mr-2" />
          Vincular Pacote
        </Button>
      </DialogTrigger>
      <DialogContent className="max-w-lg">
        <DialogHeader>
          <DialogTitle>Vincular Pacote de Tratamento</DialogTitle>
          <DialogDescription>
            Vincule um pacote de sessões para {pacienteNome}
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-6">
          <div className="space-y-2">
            <Label htmlFor="pacote">Selecione o Pacote</Label>
            <Select
              value={pacoteSelecionado?.id || ""}
              onValueChange={handlePacoteChange}
            >
              <SelectTrigger id="pacote">
                <SelectValue placeholder="Escolha um pacote" />
              </SelectTrigger>
              <SelectContent className="bg-background z-50">
                {pacotes.length === 0 ? (
                  <div className="p-2 text-sm text-muted-foreground text-center">
                    Nenhum pacote disponível
                  </div>
                ) : (
                  pacotes.map((pacote) => (
                    <SelectItem key={pacote.id} value={pacote.id}>
                      {pacote.nome} - {pacote.numero_sessoes} sessões - R$ {pacote.preco.toFixed(2)}
                    </SelectItem>
                  ))
                )}
              </SelectContent>
            </Select>
          </div>

          {pacoteSelecionado && (
            <>
              <div className="bg-muted p-4 rounded-lg space-y-2">
                <h4 className="font-medium">Detalhes do Pacote</h4>
                <div className="grid grid-cols-2 gap-2 text-sm">
                  <div>
                    <p className="text-muted-foreground">Sessões:</p>
                    <p className="font-medium">{pacoteSelecionado.numero_sessoes}</p>
                  </div>
                  <div>
                    <p className="text-muted-foreground">Valor:</p>
                    <p className="font-medium">R$ {pacoteSelecionado.preco.toFixed(2)}</p>
                  </div>
                  <div>
                    <p className="text-muted-foreground">Validade:</p>
                    <p className="font-medium">{pacoteSelecionado.validade_dias} dias</p>
                  </div>
                  <div>
                    <p className="text-muted-foreground">Valor/Sessão:</p>
                    <p className="font-medium">R$ {(pacoteSelecionado.preco / pacoteSelecionado.numero_sessoes).toFixed(2)}</p>
                  </div>
                </div>
              </div>

              <div className="flex items-center justify-between">
                <div className="space-y-0.5">
                  <Label htmlFor="renovacao">Renovação Automática</Label>
                  <p className="text-xs text-muted-foreground">
                    Renovar automaticamente ao expirar
                  </p>
                </div>
                <Switch
                  id="renovacao"
                  checked={renovacaoAutomatica}
                  onCheckedChange={setRenovacaoAutomatica}
                />
              </div>
            </>
          )}

          <div className="flex justify-end gap-3">
            <Button
              type="button"
              variant="outline"
              onClick={() => setOpen(false)}
              disabled={isLoading}
            >
              Cancelar
            </Button>
            <Button onClick={handleSubmit} disabled={isLoading || !pacoteSelecionado}>
              {isLoading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Vincular Pacote
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Calendar } from "@/components/ui/calendar";
import { Textarea } from "@/components/ui/textarea";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { Calendar as CalendarIcon, Clock, User, CheckCircle2 } from "lucide-react";
import { format, addDays, setHours, setMinutes, isBefore, isAfter, startOfDay } from "date-fns";
import { ptBR } from "date-fns/locale";

interface AgendamentoOnlineProps {
    pacienteId: string;
    tenantId: string;
}

export function AgendamentoOnline({ pacienteId, tenantId }: AgendamentoOnlineProps) {
    const [step, setStep] = useState(1);
    const [profissionais, setProfissionais] = useState<any[]>([]);
    const [servicos, setServicos] = useState<any[]>([]);
    const [horariosDisponiveis, setHorariosDisponiveis] = useState<any[]>([]);

    const [profissionalSelecionado, setProfissionalSelecionado] = useState('');
    const [servicoSelecionado, setServicoSelecionado] = useState('');
    const [dataSelecionada, setDataSelecionada] = useState<Date | undefined>(undefined);
    const [horarioSelecionado, setHorarioSelecionado] = useState('');
    const [observacoes, setObservacoes] = useState('');

    const [loading, setLoading] = useState(false);

    useEffect(() => {
        loadProfissionais();
        loadServicos();
    }, [tenantId]);

    useEffect(() => {
        if (profissionalSelecionado && dataSelecionada) {
            loadHorariosDisponiveis();
        }
    }, [profissionalSelecionado, dataSelecionada]);

    const loadProfissionais = async () => {
        try {
            const { data } = await supabase
                .from('profiles')
                .select('id, nome')
                .eq('tenant_id', tenantId)
                .eq('ativo', true);

            setProfissionais(data || []);
        } catch (error) {
            console.error('Erro:', error);
        }
    };

    const loadServicos = async () => {
        try {
            const { data } = await supabase
                .from('servicos')
                .select('*')
                .eq('tenant_id', tenantId)
                .eq('ativo', true);

            setServicos(data || []);
        } catch (error) {
            console.error('Erro:', error);
        }
    };

    const loadHorariosDisponiveis = async () => {
        if (!profissionalSelecionado || !dataSelecionada) return;

        try {
            setLoading(true);

            const dataInicio = startOfDay(dataSelecionada);
            const dataFim = addDays(dataInicio, 1);

            const { data: agendamentosExistentes } = await supabase
                .from('agenda')
                .select('inicio, fim')
                .eq('profissional_id', profissionalSelecionado)
                .gte('inicio', dataInicio.toISOString())
                .lt('inicio', dataFim.toISOString())
                .neq('status', 'cancelado');

            const horarios: any[] = [];
            const servicoDuracao = servicos.find(s => s.id === servicoSelecionado)?.duracao_minutos || 30;

            for (let hora = 8; hora < 18; hora++) {
                for (let minuto = 0; minuto < 60; minuto += 30) {
                    const inicio = setMinutes(setHours(dataSelecionada, hora), minuto);
                    const fim = new Date(inicio.getTime() + servicoDuracao * 60000);

                    const conflito = agendamentosExistentes?.some(ag => {
                        const agInicio = new Date(ag.inicio);
                        const agFim = new Date(ag.fim);
                        return (
                            (inicio >= agInicio && inicio < agFim) ||
                            (fim > agInicio && fim <= agFim) ||
                            (inicio <= agInicio && fim >= agFim)
                        );
                    });

                    if (!conflito && isBefore(new Date(), inicio)) {
                        horarios.push({ inicio, fim });
                    }
                }
            }

            setHorariosDisponiveis(horarios);
        } catch (error) {
            toast.error('Erro ao carregar horários');
        } finally {
            setLoading(false);
        }
    };

    const handleConfirmarAgendamento = async () => {
        if (!profissionalSelecionado || !servicoSelecionado || !horarioSelecionado) {
            toast.error('Preencha todos os campos');
            return;
        }

        try {
            setLoading(true);

            const horario = horariosDisponiveis.find(h =>
                h.inicio.toISOString() === horarioSelecionado
            );

            const { error } = await supabase
                .from('agenda')
                .insert({
                    tenant_id: tenantId,
                    paciente_id: pacienteId,
                    profissional_id: profissionalSelecionado,
                    servico_id: servicoSelecionado,
                    inicio: horario.inicio.toISOString(),
                    fim: horario.fim.toISOString(),
                    status: 'agendado',
                    confirmado: false,
                    observacoes
                });

            if (error) throw error;

            toast.success('Agendamento realizado!');
            setStep(4);

            setTimeout(() => {
                setStep(1);
                setProfissionalSelecionado('');
                setServicoSelecionado('');
                setDataSelecionada(undefined);
                setHorarioSelecionado('');
                setObservacoes('');
            }, 3000);

        } catch (error) {
            toast.error('Erro ao agendar');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="space-y-6">
            {/* Progress */}
            <div className="flex items-center justify-center gap-2">
                {[1, 2, 3].map((s) => (
                    <React.Fragment key={s}>
                        <div className={`flex items-center justify-center w-8 h-8 rounded-full ${step >= s ? 'bg-primary text-primary-foreground' : 'bg-muted'
                            }`}>
                            {s}
                        </div>
                        {s < 3 && <div className={`h-0.5 w-12 ${step > s ? 'bg-primary' : 'bg-muted'}`} />}
                    </React.Fragment>
                ))}
            </div>

            {/* Step 1: Profissional e Serviço */}
            {step === 1 && (
                <Card>
                    <CardHeader>
                        <CardTitle className="flex items-center gap-2">
                            <User className="h-5 w-5" />
                            Escolha o Profissional
                        </CardTitle>
                    </CardHeader>
                    <CardContent className="space-y-4">
                        <div>
                            <Label>Profissional</Label>
                            <Select value={profissionalSelecionado} onValueChange={setProfissionalSelecionado}>
                                <SelectTrigger>
                                    <SelectValue placeholder="Selecione" />
                                </SelectTrigger>
                                <SelectContent>
                                    {profissionais.map(p => (
                                        <SelectItem key={p.id} value={p.id}>{p.nome}</SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                        </div>

                        <div>
                            <Label>Serviço</Label>
                            <Select value={servicoSelecionado} onValueChange={setServicoSelecionado}>
                                <SelectTrigger>
                                    <SelectValue placeholder="Selecione" />
                                </SelectTrigger>
                                <SelectContent>
                                    {servicos.map(s => (
                                        <SelectItem key={s.id} value={s.id}>
                                            {s.nome} - {s.duracao_minutos}min - R$ {s.valor}
                                        </SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                        </div>

                        <Button
                            className="w-full"
                            onClick={() => setStep(2)}
                            disabled={!profissionalSelecionado || !servicoSelecionado}
                        >
                            Próximo: Escolher Data
                        </Button>
                    </CardContent>
                </Card>
            )}

            {/* Step 2: Data */}
            {step === 2 && (
                <Card>
                    <CardHeader>
                        <CardTitle className="flex items-center gap-2">
                            <CalendarIcon className="h-5 w-5" />
                            Escolha a Data
                        </CardTitle>
                    </CardHeader>
                    <CardContent className="space-y-4">
                        <div className="flex justify-center">
                            <Calendar
                                mode="single"
                                selected={dataSelecionada}
                                onSelect={setDataSelecionada}
                                disabled={(date) =>
                                    isBefore(date, new Date()) ||
                                    isAfter(date, addDays(new Date(), 60))
                                }
                                locale={ptBR}
                                className="rounded-md border"
                            />
                        </div>

                        <div className="flex gap-2">
                            <Button variant="outline" onClick={() => setStep(1)} className="flex-1">
                                Voltar
                            </Button>
                            <Button
                                onClick={() => setStep(3)}
                                disabled={!dataSelecionada}
                                className="flex-1"
                            >
                                Próximo: Horário
                            </Button>
                        </div>
                    </CardContent>
                </Card>
            )}

            {/* Step 3: Horário */}
            {step === 3 && (
                <Card>
                    <CardHeader>
                        <CardTitle className="flex items-center gap-2">
                            <Clock className="h-5 w-5" />
                            Escolha o Horário
                        </CardTitle>
                    </CardHeader>
                    <CardContent className="space-y-4">
                        {loading ? (
                            <div className="text-center py-8">Carregando...</div>
                        ) : horariosDisponiveis.length === 0 ? (
                            <div className="text-center py-8">
                                <p>Nenhum horário disponível</p>
                                <Button variant="outline" onClick={() => setStep(2)} className="mt-4">
                                    Outra Data
                                </Button>
                            </div>
                        ) : (
                            <>
                                <div className="grid grid-cols-3 gap-2 max-h-96 overflow-y-auto">
                                    {horariosDisponiveis.map((horario, i) => (
                                        <Button
                                            key={i}
                                            variant={horarioSelecionado === horario.inicio.toISOString() ? "default" : "outline"}
                                            onClick={() => setHorarioSelecionado(horario.inicio.toISOString())}
                                        >
                                            {format(horario.inicio, 'HH:mm')}
                                        </Button>
                                    ))}
                                </div>

                                <div>
                                    <Label>Observações</Label>
                                    <Textarea
                                        value={observacoes}
                                        onChange={(e) => setObservacoes(e.target.value)}
                                        rows={3}
                                    />
                                </div>

                                <div className="flex gap-2">
                                    <Button variant="outline" onClick={() => setStep(2)} className="flex-1">
                                        Voltar
                                    </Button>
                                    <Button
                                        onClick={handleConfirmarAgendamento}
                                        disabled={!horarioSelecionado || loading}
                                        className="flex-1"
                                    >
                                        Confirmar
                                    </Button>
                                </div>
                            </>
                        )}
                    </CardContent>
                </Card>
            )}

            {/* Step 4: Confirmação */}
            {step === 4 && (
                <Card className="border-green-200 bg-green-50">
                    <CardContent className="pt-6 text-center space-y-4">
                        <CheckCircle2 className="h-16 w-16 text-green-600 mx-auto" />
                        <h3 className="text-2xl font-bold">Agendamento Confirmado!</h3>
                        <p>Você receberá uma confirmação por WhatsApp.</p>
                    </CardContent>
                </Card>
            )}
        </div>
    );
}

import { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Switch } from "@/components/ui/switch";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { Loader2 } from "lucide-react";

interface EditPlanoSaudeDialogProps {
  planoId: string;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSuccess?: () => void;
}

export function EditPlanoSaudeDialog({
  planoId,
  open,
  onOpenChange,
  onSuccess,
}: EditPlanoSaudeDialogProps) {
  const [isLoading, setIsLoading] = useState(false);
  const [formData, setFormData] = useState({
    nome: "",
    descricao: "",
    ativo: true,
  });
  const { toast } = useToast();

  useEffect(() => {
    if (open && planoId) {
      fetchPlano();
    }
  }, [open, planoId]);

  const fetchPlano = async () => {
    try {
      const { data, error } = await supabase
        .from("planos_saude")
        .select("*")
        .eq("id", planoId)
        .single();

      if (error) throw error;

      setFormData({
        nome: data.nome,
        descricao: data.descricao || "",
        ativo: data.ativo,
      });
    } catch (error: any) {
      toast({
        title: "Erro ao carregar plano",
        description: error.message,
        variant: "destructive",
      });
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);

    try {
      const { error } = await supabase
        .from("planos_saude")
        .update({
          nome: formData.nome.trim(),
          descricao: formData.descricao.trim() || null,
          ativo: formData.ativo,
        })
        .eq("id", planoId);

      if (error) throw error;

      toast({
        title: "Sucesso!",
        description: "Plano atualizado com sucesso.",
      });

      onOpenChange(false);
      onSuccess?.();
    } catch (error: any) {
      toast({
        title: "Erro ao atualizar plano",
        description: error.message,
        variant: "destructive",
      });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[500px]">
        <DialogHeader>
          <DialogTitle>Editar Plano de Saúde</DialogTitle>
        </DialogHeader>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="nome">Nome do Plano *</Label>
            <Input
              id="nome"
              value={formData.nome}
              onChange={(e) => setFormData({ ...formData, nome: e.target.value })}
              required
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="descricao">Descrição</Label>
            <Textarea
              id="descricao"
              value={formData.descricao}
              onChange={(e) => setFormData({ ...formData, descricao: e.target.value })}
              rows={3}
            />
          </div>

          <div className="flex items-center space-x-2">
            <Switch
              id="ativo"
              checked={formData.ativo}
              onCheckedChange={(checked) => setFormData({ ...formData, ativo: checked })}
            />
            <Label htmlFor="ativo">Plano ativo</Label>
          </div>

          <div className="flex gap-3 pt-4">
            <Button
              type="button"
              variant="outline"
              onClick={() => onOpenChange(false)}
              className="flex-1"
            >
              Cancelar
            </Button>
            <Button type="submit" disabled={isLoading} className="flex-1">
              {isLoading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Salvar Alterações
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import { useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Switch } from "@/components/ui/switch";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { Loader2 } from "lucide-react";

interface NewPlanoSaudeDialogProps {
  children: React.ReactNode;
  onSuccess?: () => void;
}

export function NewPlanoSaudeDialog({ children, onSuccess }: NewPlanoSaudeDialogProps) {
  const [open, setOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [formData, setFormData] = useState({
    nome: "",
    descricao: "",
    ativo: true,
  });
  const { toast } = useToast();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);

    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error("Usuário não autenticado");

      const { data: profile } = await supabase
        .from("profiles")
        .select("tenant_id")
        .eq("id", user.id)
        .single();

      if (!profile?.tenant_id) throw new Error("Tenant não encontrado");

      const { error } = await supabase.from("planos_saude").insert({
        tenant_id: profile.tenant_id,
        nome: formData.nome.trim(),
        descricao: formData.descricao.trim() || null,
        ativo: formData.ativo,
      });

      if (error) throw error;

      toast({
        title: "Sucesso!",
        description: "Plano de saúde cadastrado com sucesso.",
      });

      setFormData({ nome: "", descricao: "", ativo: true });
      setOpen(false);
      onSuccess?.();
    } catch (error: any) {
      toast({
        title: "Erro ao cadastrar plano",
        description: error.message,
        variant: "destructive",
      });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>{children}</DialogTrigger>
      <DialogContent className="sm:max-w-[500px]">
        <DialogHeader>
          <DialogTitle>Novo Plano de Saúde</DialogTitle>
        </DialogHeader>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="nome">Nome do Plano *</Label>
            <Input
              id="nome"
              value={formData.nome}
              onChange={(e) => setFormData({ ...formData, nome: e.target.value })}
              placeholder="Ex: Unimed, Amil, SulAmérica..."
              required
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="descricao">Descrição</Label>
            <Textarea
              id="descricao"
              value={formData.descricao}
              onChange={(e) => setFormData({ ...formData, descricao: e.target.value })}
              placeholder="Informações adicionais sobre o plano..."
              rows={3}
            />
          </div>

          <div className="flex items-center space-x-2">
            <Switch
              id="ativo"
              checked={formData.ativo}
              onCheckedChange={(checked) => setFormData({ ...formData, ativo: checked })}
            />
            <Label htmlFor="ativo">Plano ativo</Label>
          </div>

          <div className="flex gap-3 pt-4">
            <Button
              type="button"
              variant="outline"
              onClick={() => setOpen(false)}
              className="flex-1"
            >
              Cancelar
            </Button>
            <Button type="submit" disabled={isLoading} className="flex-1">
              {isLoading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Cadastrar
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Badge } from "@/components/ui/badge";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { Save, FileSignature, Calendar } from "lucide-react";
import { RegistroMedico } from "./RegistroMedico";
import { format, differenceInYears } from "date-fns";
import { ptBR } from "date-fns/locale";

interface ProntuarioFormProps {
  pacienteId: string;
  agendamentoId?: string;
  onSave?: () => void;
}

export default function ProntuarioForm({ pacienteId, agendamentoId, onSave }: ProntuarioFormProps) {
  const [loading, setLoading] = useState(false);
  const [prontuarioId, setProntuarioId] = useState<string | null>(null);
  const [pacienteInfo, setPacienteInfo] = useState<any>(null);
  const [formData, setFormData] = useState({
    // SOAP
    subjetivo: "",
    objetivo: "",
    avaliacao: "",
    plano: "",
    // Vitais
    pressao_arterial: "",
    frequencia_cardiaca: "",
    temperatura: "",
    peso: "",
    altura: "",
    // CID-10
    cid10_principal: "",
    // Prescrições
    prescricoes: "",
    procedimentos: "",
    exames_solicitados: "",
  });

  useEffect(() => {
    fetchPacienteInfo();
  }, [pacienteId]);

  const fetchPacienteInfo = async () => {
    try {
      const { data, error } = await (supabase as any)
        .from('pacientes')
        .select('nome, data_nascimento')
        .eq('id', pacienteId)
        .maybeSingle();

      if (error) throw error;
      setPacienteInfo(data);
    } catch (error) {
      console.error('Erro ao buscar informações do paciente:', error);
    }
  };

  const calcularIdade = () => {
    if (pacienteInfo?.data_nascimento) {
      return differenceInYears(new Date(), new Date(pacienteInfo.data_nascimento));
    }
    return null;
  };

  const handleInputChange = (field: string, value: string) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const calculateIMC = () => {
    if (formData.peso && formData.altura) {
      const peso = parseFloat(formData.peso);
      const altura = parseFloat(formData.altura);
      if (peso > 0 && altura > 0) {
        return (peso / (altura * altura)).toFixed(2);
      }
    }
    return null;
  };

  const handleSave = async (status: 'rascunho' | 'finalizado') => {
    setLoading(true);
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error('Usuário não autenticado');

      const { data: profile } = await supabase
        .from('profiles')
        .select('tenant_id')
        .eq('id', user.id)
        .single();

      if (!profile) throw new Error('Perfil não encontrado');

      const imc = calculateIMC();

      const { data, error } = await (supabase as any).from('prontuarios').insert({
        tenant_id: profile.tenant_id,
        paciente_id: pacienteId,
        profissional_id: user.id,
        agendamento_id: agendamentoId,
        status,
        ...formData,
        frequencia_cardiaca: formData.frequencia_cardiaca ? parseInt(formData.frequencia_cardiaca) : null,
        temperatura: formData.temperatura ? parseFloat(formData.temperatura) : null,
        peso: null, // Peso agora é gerenciado pelo histórico
        altura: null, // Altura agora é gerenciada pelo RegistroMedico
        imc: null // IMC calculado automaticamente no histórico de peso
      }).select().single();

      if (error) throw error;

      if (data) {
        setProntuarioId(data.id);
      }

      toast.success(status === 'finalizado' ? 'Prontuário salvo com sucesso!' : 'Rascunho salvo!');
      onSave?.();
    } catch (error: any) {
      console.error('Erro ao salvar prontuário:', error);
      toast.error(error.message || 'Erro ao salvar prontuário');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-6">
      {pacienteInfo && (
        <Card>
          <CardHeader>
            <div className="flex items-center justify-between">
              <CardTitle>Informações do Paciente</CardTitle>
              {pacienteInfo.data_nascimento && (
                <Badge variant="secondary" className="flex items-center gap-2">
                  <Calendar className="h-4 w-4" />
                  {calcularIdade()} anos
                </Badge>
              )}
            </div>
          </CardHeader>
          <CardContent>
            <div className="space-y-2">
              <p className="text-lg font-semibold">{pacienteInfo.nome}</p>
              {pacienteInfo.data_nascimento && (
                <p className="text-sm text-muted-foreground">
                  Nascimento: {format(new Date(pacienteInfo.data_nascimento), "dd 'de' MMMM 'de' yyyy", { locale: ptBR })}
                </p>
              )}
            </div>
          </CardContent>
        </Card>
      )}

      {prontuarioId && (
        <RegistroMedico 
          prontuarioId={prontuarioId} 
          pacienteId={pacienteId} 
        />
      )}

      <Card>
      <CardHeader>
        <CardTitle>Prontuário Eletrônico</CardTitle>
      </CardHeader>
      <CardContent>
        <Tabs defaultValue="soap" className="space-y-4">
          <TabsList className="grid w-full grid-cols-4">
            <TabsTrigger value="soap">SOAP</TabsTrigger>
            <TabsTrigger value="vitais">Sinais Vitais</TabsTrigger>
            <TabsTrigger value="diagnostico">Diagnóstico</TabsTrigger>
            <TabsTrigger value="prescricoes">Prescrições</TabsTrigger>
          </TabsList>

          <TabsContent value="soap" className="space-y-4">
            <div className="space-y-2">
              <Label>Subjetivo (S)</Label>
              <Textarea
                placeholder="Sintomas relatados pelo paciente, queixa principal, história da doença atual..."
                value={formData.subjetivo}
                onChange={(e) => handleInputChange('subjetivo', e.target.value)}
                rows={4}
              />
            </div>
            <div className="space-y-2">
              <Label>Objetivo (O)</Label>
              <Textarea
                placeholder="Observações clínicas objetivas, exame físico, resultados de exames..."
                value={formData.objetivo}
                onChange={(e) => handleInputChange('objetivo', e.target.value)}
                rows={4}
              />
            </div>
            <div className="space-y-2">
              <Label>Avaliação (A)</Label>
              <Textarea
                placeholder="Avaliação clínica, diagnóstico, impressão diagnóstica..."
                value={formData.avaliacao}
                onChange={(e) => handleInputChange('avaliacao', e.target.value)}
                rows={4}
              />
            </div>
            <div className="space-y-2">
              <Label>Plano (P)</Label>
              <Textarea
                placeholder="Plano terapêutico, orientações, retorno, encaminhamentos..."
                value={formData.plano}
                onChange={(e) => handleInputChange('plano', e.target.value)}
                rows={4}
              />
            </div>
          </TabsContent>

          <TabsContent value="vitais" className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>Pressão Arterial</Label>
                <Input
                  placeholder="120/80 mmHg"
                  value={formData.pressao_arterial}
                  onChange={(e) => handleInputChange('pressao_arterial', e.target.value)}
                />
              </div>
              <div className="space-y-2">
                <Label>Frequência Cardíaca</Label>
                <Input
                  type="number"
                  placeholder="75 bpm"
                  value={formData.frequencia_cardiaca}
                  onChange={(e) => handleInputChange('frequencia_cardiaca', e.target.value)}
                />
              </div>
              <div className="space-y-2">
                <Label>Temperatura (°C)</Label>
                <Input
                  type="number"
                  step="0.1"
                  placeholder="36.5"
                  value={formData.temperatura}
                  onChange={(e) => handleInputChange('temperatura', e.target.value)}
                />
              </div>
              <div className="space-y-2">
                <Label>Peso (kg)</Label>
                <Input
                  type="number"
                  step="0.1"
                  placeholder="70.5"
                  value={formData.peso}
                  onChange={(e) => handleInputChange('peso', e.target.value)}
                />
              </div>
              <div className="space-y-2">
                <Label>Altura (m)</Label>
                <Input
                  type="number"
                  step="0.01"
                  placeholder="1.75"
                  value={formData.altura}
                  onChange={(e) => handleInputChange('altura', e.target.value)}
                />
              </div>
              <div className="space-y-2">
                <Label>IMC</Label>
                <Input
                  value={calculateIMC() || '-'}
                  disabled
                  className="bg-muted"
                />
              </div>
            </div>
          </TabsContent>

          <TabsContent value="diagnostico" className="space-y-4">
            <div className="space-y-2">
              <Label>CID-10 Principal</Label>
              <Input
                placeholder="Ex: A09 - Diarreia e gastroenterite"
                value={formData.cid10_principal}
                onChange={(e) => handleInputChange('cid10_principal', e.target.value)}
              />
            </div>
          </TabsContent>

          <TabsContent value="prescricoes" className="space-y-4">
            <div className="space-y-2">
              <Label>Prescrições</Label>
              <Textarea
                placeholder="Medicamentos prescritos, dosagem, frequência, duração..."
                value={formData.prescricoes}
                onChange={(e) => handleInputChange('prescricoes', e.target.value)}
                rows={4}
              />
            </div>
            <div className="space-y-2">
              <Label>Procedimentos Realizados</Label>
              <Textarea
                placeholder="Procedimentos realizados durante a consulta..."
                value={formData.procedimentos}
                onChange={(e) => handleInputChange('procedimentos', e.target.value)}
                rows={3}
              />
            </div>
            <div className="space-y-2">
              <Label>Exames Solicitados</Label>
              <Textarea
                placeholder="Exames complementares solicitados..."
                value={formData.exames_solicitados}
                onChange={(e) => handleInputChange('exames_solicitados', e.target.value)}
                rows={3}
              />
            </div>
          </TabsContent>
        </Tabs>

        <div className="flex gap-2 mt-6">
          <Button
            onClick={() => handleSave('rascunho')}
            variant="outline"
            disabled={loading}
          >
            <Save className="h-4 w-4 mr-2" />
            Salvar Rascunho
          </Button>
          <Button
            onClick={() => handleSave('finalizado')}
            disabled={loading}
          >
            <FileSignature className="h-4 w-4 mr-2" />
            Finalizar Prontuário
          </Button>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

import { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { useToast } from "@/hooks/use-toast";
import { supabase } from "@/integrations/supabase/client";
import { Ruler, Weight, TrendingUp, Plus, Pencil, Trash2 } from "lucide-react";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";

interface RegistroMedicoProps {
  prontuarioId: string;
  pacienteId: string;
  readOnly?: boolean;
}

interface RegistroPeso {
  id: string;
  peso_kg: number;
  imc: number | null;
  data_registro: string;
  observacoes: string | null;
}

export function RegistroMedico({ prontuarioId, pacienteId, readOnly = false }: RegistroMedicoProps) {
  const [altura, setAltura] = useState<number | null>(null);
  const [editandoAltura, setEditandoAltura] = useState(false);
  const [novaAltura, setNovaAltura] = useState("");

  const [registrosPeso, setRegistrosPeso] = useState<RegistroPeso[]>([]);
  const [adicionandoPeso, setAdicionandoPeso] = useState(false);
  const [novoPeso, setNovoPeso] = useState("");
  const [observacaoPeso, setObservacaoPeso] = useState("");

  const [loading, setLoading] = useState(true);
  const { toast } = useToast();

  useEffect(() => {
    fetchDados();
  }, [prontuarioId, pacienteId]);

  const fetchDados = async () => {
    try {
      setLoading(true);

      // Buscar altura do prontuário
      const { data: prontuario, error: errorProntuario } = await (supabase as any)
        .from('prontuarios')
        .select('altura_cm')
        .eq('id', prontuarioId)
        .maybeSingle();

      if (errorProntuario) throw errorProntuario;
      if (prontuario) {
        setAltura(prontuario.altura_cm);
      }

      // Buscar histórico de peso
      const { data: historico, error: errorHistorico } = await (supabase as any)
        .from('historico_peso')
        .select('*')
        .eq('paciente_id', pacienteId)
        .order('data_registro', { ascending: false });

      if (errorHistorico) throw errorHistorico;
      setRegistrosPeso(historico || []);
    } catch (error: any) {
      console.error('Erro ao buscar dados médicos:', error);
      toast({
        title: "Erro",
        description: "Não foi possível carregar os dados médicos.",
        variant: "destructive"
      });
    } finally {
      setLoading(false);
    }
  };

  const handleSalvarAltura = async () => {
    if (!novaAltura || isNaN(parseFloat(novaAltura))) {
      toast({
        title: "Erro",
        description: "Digite uma altura válida.",
        variant: "destructive"
      });
      return;
    }

    try {
      const { error } = await (supabase as any)
        .from('prontuarios')
        .update({ altura_cm: parseFloat(novaAltura) })
        .eq('id', prontuarioId);

      if (error) throw error;

      setAltura(parseFloat(novaAltura));
      setEditandoAltura(false);
      setNovaAltura("");

      toast({
        title: "Sucesso!",
        description: "Altura atualizada."
      });

      // Recalcular IMC dos registros de peso existentes
      fetchDados();
    } catch (error: any) {
      console.error('Erro ao salvar altura:', error);
      toast({
        title: "Erro",
        description: error.message || "Não foi possível salvar a altura.",
        variant: "destructive"
      });
    }
  };

  const handleAdicionarPeso = async () => {
    if (!novoPeso || isNaN(parseFloat(novoPeso))) {
      toast({
        title: "Erro",
        description: "Digite um peso válido.",
        variant: "destructive"
      });
      return;
    }

    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error("Usuário não autenticado");

      const { data: profile } = await supabase
        .from('profiles')
        .select('tenant_id')
        .eq('id', user.id)
        .maybeSingle();

      if (!profile?.tenant_id) throw new Error("Tenant não encontrado");

      const { error } = await (supabase as any)
        .from('historico_peso')
        .insert({
          tenant_id: profile.tenant_id,
          paciente_id: pacienteId,
          profissional_id: user.id,
          prontuario_id: prontuarioId,
          peso_kg: parseFloat(novoPeso),
          observacoes: observacaoPeso || null
        });

      if (error) throw error;

      toast({
        title: "Sucesso!",
        description: "Registro de peso adicionado."
      });

      setNovoPeso("");
      setObservacaoPeso("");
      setAdicionandoPeso(false);
      fetchDados();
    } catch (error: any) {
      console.error('Erro ao adicionar peso:', error);
      toast({
        title: "Erro",
        description: error.message || "Não foi possível adicionar o registro de peso.",
        variant: "destructive"
      });
    }
  };

  const handleExcluirPeso = async (id: string) => {
    if (!confirm("Deseja excluir este registro de peso?")) return;

    try {
      const { error } = await (supabase as any)
        .from('historico_peso')
        .delete()
        .eq('id', id);

      if (error) throw error;

      toast({
        title: "Sucesso!",
        description: "Registro excluído."
      });

      fetchDados();
    } catch (error: any) {
      console.error('Erro ao excluir:', error);
      toast({
        title: "Erro",
        description: "Não foi possível excluir o registro.",
        variant: "destructive"
      });
    }
  };

  const classificarIMC = (imc: number | null) => {
    if (!imc) return { texto: "N/A", cor: "secondary" };
    if (imc < 18.5) return { texto: "Abaixo do peso", cor: "destructive" };
    if (imc < 25) return { texto: "Peso normal", cor: "default" };
    if (imc < 30) return { texto: "Sobrepeso", cor: "secondary" };
    return { texto: "Obesidade", cor: "destructive" };
  };

  if (loading) {
    return <div className="text-center py-4">Carregando dados médicos...</div>;
  }

  return (
    <div className="space-y-4">
      {/* Altura */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Ruler className="h-5 w-5" />
            Altura
          </CardTitle>
          <CardDescription>Registro único da altura do paciente</CardDescription>
        </CardHeader>
        <CardContent>
          {editandoAltura ? (
            <div className="space-y-3">
              <div className="flex gap-2">
                <Input
                  type="number"
                  step="0.01"
                  value={novaAltura}
                  onChange={(e) => setNovaAltura(e.target.value)}
                  placeholder="Ex: 175.5"
                  className="max-w-xs"
                />
                <span className="flex items-center">cm</span>
              </div>
              <div className="flex gap-2">
                <Button onClick={handleSalvarAltura} size="sm">
                  Salvar
                </Button>
                <Button 
                  onClick={() => {
                    setEditandoAltura(false);
                    setNovaAltura("");
                  }} 
                  variant="outline" 
                  size="sm"
                >
                  Cancelar
                </Button>
              </div>
            </div>
          ) : (
            <div className="flex items-center justify-between">
              <div>
                {altura ? (
                  <p className="text-2xl font-bold">{altura} cm</p>
                ) : (
                  <p className="text-muted-foreground">Não cadastrada</p>
                )}
              </div>
              {!readOnly && (
                <Button 
                  onClick={() => {
                    setEditandoAltura(true);
                    setNovaAltura(altura?.toString() || "");
                  }} 
                  variant="outline" 
                  size="sm"
                >
                  <Pencil className="h-4 w-4 mr-2" />
                  {altura ? "Editar" : "Cadastrar"}
                </Button>
              )}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Peso */}
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div>
              <CardTitle className="flex items-center gap-2">
                <Weight className="h-5 w-5" />
                Histórico de Peso
              </CardTitle>
              <CardDescription>Registros de peso ao longo do tempo</CardDescription>
            </div>
            {!readOnly && !adicionandoPeso && (
              <Button onClick={() => setAdicionandoPeso(true)} size="sm">
                <Plus className="h-4 w-4 mr-2" />
                Novo Registro
              </Button>
            )}
          </div>
        </CardHeader>
        <CardContent className="space-y-4">
          {adicionandoPeso && (
            <div className="space-y-3 p-4 border rounded-lg bg-muted/50">
              <div className="space-y-2">
                <Label>Peso (kg)</Label>
                <Input
                  type="number"
                  step="0.1"
                  value={novoPeso}
                  onChange={(e) => setNovoPeso(e.target.value)}
                  placeholder="Ex: 75.5"
                  className="max-w-xs"
                />
              </div>
              <div className="space-y-2">
                <Label>Observações (opcional)</Label>
                <Textarea
                  value={observacaoPeso}
                  onChange={(e) => setObservacaoPeso(e.target.value)}
                  placeholder="Observações sobre a medição"
                  rows={2}
                />
              </div>
              <div className="flex gap-2">
                <Button onClick={handleAdicionarPeso} size="sm">
                  Adicionar
                </Button>
                <Button 
                  onClick={() => {
                    setAdicionandoPeso(false);
                    setNovoPeso("");
                    setObservacaoPeso("");
                  }} 
                  variant="outline" 
                  size="sm"
                >
                  Cancelar
                </Button>
              </div>
            </div>
          )}

          {registrosPeso.length === 0 ? (
            <p className="text-center text-muted-foreground py-4">
              Nenhum registro de peso cadastrado
            </p>
          ) : (
            <div className="space-y-3">
              {registrosPeso.map((registro) => {
                const classificacao = classificarIMC(registro.imc);
                return (
                  <div 
                    key={registro.id} 
                    className="flex items-start justify-between p-3 border rounded-lg"
                  >
                    <div className="space-y-1 flex-1">
                      <div className="flex items-center gap-3">
                        <p className="text-lg font-semibold">{registro.peso_kg} kg</p>
                        {registro.imc && (
                          <div className="flex items-center gap-2">
                            <Badge variant={classificacao.cor as any}>
                              IMC: {registro.imc.toFixed(1)}
                            </Badge>
                            <span className="text-sm text-muted-foreground">
                              {classificacao.texto}
                            </span>
                          </div>
                        )}
                      </div>
                      <p className="text-sm text-muted-foreground">
                        {format(new Date(registro.data_registro), "dd 'de' MMMM 'de' yyyy 'às' HH:mm", { locale: ptBR })}
                      </p>
                      {registro.observacoes && (
                        <p className="text-sm mt-2">{registro.observacoes}</p>
                      )}
                    </div>
                    {!readOnly && (
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => handleExcluirPeso(registro.id)}
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

import React, { useState } from "react";
import {
  DndContext,
  DragEndEvent,
  DragOverlay,
  DragStartEvent,
  PointerSensor,
  useSensor,
  useSensors,
  closestCenter,
} from "@dnd-kit/core";
import {
  SortableContext,
  verticalListSortingStrategy,
  arrayMove,
} from "@dnd-kit/sortable";
import {
  useSortable,
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import { cn } from "@/lib/utils";
import { AppointmentCard } from "../dashboard/AppointmentCard";

interface Appointment {
  id: string;
  patientName: string;
  time: string;
  doctor: string;
  status: "confirmed" | "pending" | "cancelled" | "completed" | "no-show" | "risk-high" | "risk-medium" | "risk-low";
  phone?: string;
  duration: number;
}

interface TimeSlot {
  id: string;
  time: string;
  appointment?: Appointment;
}

interface DragScheduleProps {
  appointments: Appointment[];
  onAppointmentMove: (appointmentId: string, newTime: string) => void;
  timeSlots: TimeSlot[];
  viewMode?: "timeline" | "cards";
  onCardReorder?: (appointmentId: string, targetId: string) => void;
  onEdit?: (appointmentId: string) => void;
  onDelete?: (appointmentId: string) => void;
  onEmptySlotClick?: (time: string) => void;
  selectedDate?: Date;
}

function SortableAppointmentCard({ 
  appointment, 
  viewMode = "timeline",
  onEdit,
  onDelete,
  onResolveConflict
}: { 
  appointment: any; 
  viewMode?: "timeline" | "cards";
  onEdit?: (id: string) => void;
  onDelete?: (id: string) => void;
  onResolveConflict?: (id: string) => void;
}) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id: appointment.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
  };

  return (
    <div
      ref={setNodeRef}
      style={style}
      {...attributes}
      {...listeners}
      className={cn(
        "cursor-grab active:cursor-grabbing",
        viewMode === "timeline" ? "w-full h-full" : "h-full",
        isDragging && "opacity-50 z-50"
      )}
    >
      <AppointmentCard
        {...appointment}
        onEdit={onEdit}
        onDelete={onDelete}
        hasConflict={appointment.hasConflict}
        conflictMinutes={appointment.conflictMinutes}
        onResolveConflict={onResolveConflict}
        className={cn(
          viewMode === "timeline" && "mb-2 w-full",
          viewMode === "cards" && "h-full"
        )}
      />
    </div>
  );
}

function DroppableTimeSlot({ 
  timeSlot, 
  appointment,
  onEdit,
  onDelete,
  onResolveConflict,
  onEmptySlotClick,
  selectedDate
}: { 
  timeSlot: TimeSlot; 
  appointment?: any;
  onEdit?: (id: string) => void;
  onDelete?: (id: string) => void;
  onResolveConflict?: (id: string) => void;
  onEmptySlotClick?: (time: string) => void;
  selectedDate?: Date;
}) {
  const {
    setNodeRef,
    isOver,
  } = useSortable({
    id: timeSlot.id,
  });

  // Check if slot is in the past
  const isPastSlot = (() => {
    if (!selectedDate) return false;
    const now = new Date();
    const [hours, minutes] = timeSlot.time.split(':').map(Number);
    const slotDateTime = new Date(selectedDate);
    slotDateTime.setHours(hours, minutes, 0, 0);
    return slotDateTime < now;
  })();

  const handleEmptySlotClick = () => {
    if (!appointment && onEmptySlotClick && !isPastSlot) {
      onEmptySlotClick(timeSlot.time);
    }
  };

  return (
    <div
      ref={setNodeRef}
      className={cn(
        "min-h-[80px] p-2 border border-dashed border-border rounded-lg transition-colors w-full",
        isOver && !isPastSlot && "border-primary bg-primary/10",
        !appointment && !isPastSlot && "border-muted-foreground/30 cursor-pointer hover:border-primary hover:bg-primary/5",
        !appointment && isPastSlot && "border-muted/20 bg-muted/5 cursor-not-allowed opacity-50"
      )}
      onClick={handleEmptySlotClick}
    >
      <div className={cn(
        "text-sm font-medium mb-2",
        isPastSlot ? "text-muted-foreground/50" : "text-muted-foreground"
      )}>
        {timeSlot.time}
      </div>
      {appointment && (
        <div className="w-full" onClick={(e) => e.stopPropagation()}>
          <SortableAppointmentCard 
            appointment={appointment} 
            viewMode="timeline"
            onEdit={onEdit}
            onDelete={onDelete}
            onResolveConflict={onResolveConflict}
          />
        </div>
      )}
      {!appointment && (
        <div className={cn(
          "text-xs text-center py-4",
          isPastSlot ? "text-muted-foreground/40" : "text-muted-foreground"
        )}>
          {isPastSlot ? "Horário passado" : "Clique para agendar"}
        </div>
      )}
    </div>
  );
}

export function DragSchedule({ 
  appointments, 
  onAppointmentMove, 
  timeSlots, 
  viewMode = "timeline",
  onCardReorder,
  onEdit,
  onDelete,
  onResolveConflict,
  onEmptySlotClick,
  selectedDate
}: DragScheduleProps & { onResolveConflict?: (id: string) => void }) {
  const [activeId, setActiveId] = useState<string | null>(null);
  const [activeAppointment, setActiveAppointment] = useState<Appointment | null>(null);

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: {
        distance: 8,
      },
    })
  );

  const handleDragStart = (event: DragStartEvent) => {
    setActiveId(event.active.id as string);
    const appointment = appointments.find(app => app.id === event.active.id);
    setActiveAppointment(appointment || null);
  };

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;

    if (!over) {
      setActiveId(null);
      setActiveAppointment(null);
      return;
    }

    if (viewMode === "cards") {
      // Modo cards: reordenar lista
      if (active.id !== over.id && onCardReorder) {
        onCardReorder(active.id as string, over.id as string);
      }
    } else {
      // Modo timeline: mover para novo horário
      if (active.id !== over.id) {
        const appointmentId = active.id as string;
        const newTimeSlot = timeSlots.find(slot => slot.id === over.id);

        if (newTimeSlot) {
          onAppointmentMove(appointmentId, newTimeSlot.time);
        }
      }
    }

    setActiveId(null);
    setActiveAppointment(null);
  };

  // Modo Timeline: slots com agendamentos
  if (viewMode === "timeline") {
    const slotsWithAppointments = timeSlots.map(slot => {
      const appointment = appointments.find(app => app.time === slot.time);
      return { ...slot, appointment };
    });

    return (
      <DndContext
        sensors={sensors}
        onDragStart={handleDragStart}
        onDragEnd={handleDragEnd}
        collisionDetection={closestCenter}
      >
        <SortableContext
          items={[...timeSlots.map(slot => slot.id), ...appointments.map(app => app.id)]}
          strategy={verticalListSortingStrategy}
        >
          <div className="space-y-2 w-full">
            {slotsWithAppointments.map((slot) => (
              <DroppableTimeSlot
                key={slot.id}
                timeSlot={slot}
                appointment={slot.appointment}
                onEdit={onEdit}
                onDelete={onDelete}
                onResolveConflict={onResolveConflict}
                onEmptySlotClick={onEmptySlotClick}
                selectedDate={selectedDate}
              />
            ))}
          </div>
        </SortableContext>

        <DragOverlay>
          {activeAppointment && (
            <AppointmentCard
              {...activeAppointment}
              className="rotate-3 shadow-lg"
            />
          )}
        </DragOverlay>
      </DndContext>
    );
  }

  // Modo Cards: grid de cards reorganizáveis
  return (
    <DndContext
      sensors={sensors}
      onDragStart={handleDragStart}
      onDragEnd={handleDragEnd}
      collisionDetection={closestCenter}
    >
      <SortableContext
        items={appointments.map(app => app.id)}
        strategy={verticalListSortingStrategy}
      >
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {appointments.map((appointment) => (
            <SortableAppointmentCard
              key={appointment.id}
              appointment={appointment}
              viewMode="cards"
              onEdit={onEdit}
              onDelete={onDelete}
            />
          ))}
        </div>
      </SortableContext>

      <DragOverlay>
        {activeAppointment && (
          <AppointmentCard
            {...activeAppointment}
            className="rotate-3 shadow-lg"
          />
        )}
      </DragOverlay>
    </DndContext>
  );
}

import React, { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger, DialogDescription } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Calendar } from "@/components/ui/calendar";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { useToast } from "@/hooks/use-toast";
import { supabase } from "@/integrations/supabase/client";
import { format, parse } from "date-fns";
import { ptBR } from "date-fns/locale";
import { CalendarIcon, Loader2 } from "lucide-react";
import { cn } from "@/lib/utils";
import { PatientCombobox } from "./PatientCombobox";
import { ProfessionalCombobox } from "./ProfessionalCombobox";
import { PackageUsageNotification } from "@/components/pacotes/PackageUsageNotification";

interface EditAppointmentDialogProps {
  children: React.ReactNode;
  appointmentId: string;
  onSuccess?: () => void;
}

export function EditAppointmentDialog({ children, appointmentId, onSuccess }: EditAppointmentDialogProps) {
  const [open, setOpen] = useState(false);

  // Abrir automaticamente quando houver appointmentId
  useEffect(() => {
    if (appointmentId) {
      setOpen(true);
    }
  }, [appointmentId]);

  const [isLoading, setIsLoading] = useState(false);
  const [isFetchingData, setIsFetchingData] = useState(true);
  const [packageUsageNotification, setPackageUsageNotification] = useState<any>(null);
  const [showPackageNotification, setShowPackageNotification] = useState(false);

  const [pacientes, setPacientes] = useState<any[]>([]);
  const [profissionais, setProfissionais] = useState<any[]>([]);
  const [servicos, setServicos] = useState<any[]>([]);
  const [pacientesPacotes, setPacientesPacotes] = useState<any[]>([]);

  const [formData, setFormData] = useState<{
    paciente_id: string;
    profissional_id: string;
    servico_id: string;
    paciente_pacote_id: string;
    data: Date;
    hora_inicio: string;
    sala: string;
    notas: string;
    status: any;
    tipo_atendimento: string;
    plano_saude_id: string;
    valor_consulta: string;
    forma_pagamento_id: string;
    conta_pix_id: string;
  }>({
    paciente_id: "",
    profissional_id: "",
    servico_id: "",
    paciente_pacote_id: "",
    data: new Date(),
    hora_inicio: "",
    sala: "",
    notas: "",
    status: "agendado",
    tipo_atendimento: "particular",
    plano_saude_id: "",
    valor_consulta: "",
    forma_pagamento_id: "",
    conta_pix_id: ""
  });

  const [planosSaude, setPlanosSaude] = useState<any[]>([]);
  const [formasPagamento, setFormasPagamento] = useState<any[]>([]);
  const [contasPix, setContasPix] = useState<any[]>([]);
  const [canEditValues, setCanEditValues] = useState(false);

  const { toast } = useToast();

  useEffect(() => {
    if (open) {
      fetchData();
      fetchAppointmentData();
    }
  }, [open, appointmentId]);

  const fetchAppointmentData = async () => {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error("Usuário não autenticado");

      // Verificar permissão para alterar valores
      const { data: profileData } = await supabase
        .from('profiles')
        .select('pode_alterar_valores, role')
        .eq('id', user.id)
        .single();

      setCanEditValues(profileData?.pode_alterar_valores === true || profileData?.role === 'admin');

      const { data, error } = await supabase
        .from('agenda')
        .select('*')
        .eq('id', appointmentId)
        .single();

      if (error) throw error;

      const inicioDate = new Date(data.inicio);

      setFormData({
        paciente_id: data.paciente_id,
        profissional_id: data.profissional_id || "",
        servico_id: data.servico_id,
        paciente_pacote_id: data.paciente_pacote_id || "",
        data: inicioDate,
        hora_inicio: format(inicioDate, 'HH:mm'),
        sala: data.sala || "",
        notas: data.notas || "",
        status: data.status || "agendado",
        tipo_atendimento: data.tipo_atendimento || "particular",
        plano_saude_id: data.plano_saude_id || "",
        valor_consulta: data.valor_consulta?.toString() || "",
        forma_pagamento_id: data.forma_pagamento_id || "",
        conta_pix_id: data.conta_pix_id || ""
      });

      // Buscar pacotes do paciente
      if (data.paciente_id) {
        fetchPacotesPaciente(data.paciente_id);
      }
    } catch (error) {
      console.error('Erro ao buscar dados do agendamento:', error);
      toast({
        title: "Erro",
        description: "Não foi possível carregar os dados do agendamento.",
        variant: "destructive"
      });
    }
  };

  const fetchData = async () => {
    try {
      setIsFetchingData(true);

      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error("Usuário não autenticado");

      const { data: profileData } = await supabase
        .from('profiles')
        .select('tenant_id')
        .eq('id', user.id)
        .single();

      if (!profileData) throw new Error("Perfil não encontrado");

      const [pacientesRes, profissionaisRes, servicosRes, planosSaudeRes, formasPagamentoRes, contasPixRes] = await Promise.all([
        supabase.from('pacientes').select('id, nome, telefone').eq('tenant_id', profileData.tenant_id).order('nome'),
        supabase.from('profiles').select('id, nome, role').eq('tenant_id', profileData.tenant_id).order('nome'),
        supabase.from('servicos').select('id, nome, duracao_minutos, preco').eq('tenant_id', profileData.tenant_id).eq('ativo', true).order('nome'),
        supabase.from('planos_saude').select('id, nome').eq('tenant_id', profileData.tenant_id).eq('ativo', true).order('nome'),
        supabase.from('formas_pagamento').select('id, nome, tipo').eq('tenant_id', profileData.tenant_id).eq('ativo', true).order('ordem'),
        supabase.from('contas_pix').select('id, nome, chave_pix').eq('tenant_id', profileData.tenant_id).eq('ativo', true).order('nome')
      ]);

      if (pacientesRes.error) throw pacientesRes.error;
      if (profissionaisRes.error) throw profissionaisRes.error;
      if (servicosRes.error) throw servicosRes.error;

      const profissionaisFiltrados = (profissionaisRes.data || []).filter(
        prof => prof.role === 'profissional' || prof.role === 'admin' || prof.role === 'admin_tenant'
      );

      setPacientes(pacientesRes.data || []);
      setProfissionais(profissionaisFiltrados);
      setServicos(servicosRes.data || []);
      setPlanosSaude(planosSaudeRes.data || []);
      setFormasPagamento(formasPagamentoRes.data || []);
      setContasPix(contasPixRes.data || []);
    } catch (error) {
      console.error('Erro ao buscar dados:', error);
      toast({
        title: "Erro",
        description: "Não foi possível carregar os dados necessários.",
        variant: "destructive"
      });
    } finally {
      setIsFetchingData(false);
    }
  };

  const fetchPacotesPaciente = async (pacienteId: string) => {
    if (!pacienteId) {
      setPacientesPacotes([]);
      return;
    }

    try {
      const { data, error } = await supabase
        .from('pacientes_pacotes')
        .select('*, pacotes(nome)')
        .eq('paciente_id', pacienteId)
        .eq('status', 'ativo')
        .gt('sessoes_restantes', 0);

      if (error) throw error;
      setPacientesPacotes(data || []);
    } catch (error) {
      console.error('Erro ao buscar pacotes do paciente:', error);
      setPacientesPacotes([]);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.paciente_id || !formData.profissional_id || !formData.servico_id || !formData.hora_inicio) {
      toast({
        title: "Campos obrigatórios",
        description: "Por favor, preencha todos os campos obrigatórios.",
        variant: "destructive"
      });
      return;
    }

    try {
      setIsLoading(true);

      const servico = servicos.find(s => s.id === formData.servico_id);
      if (!servico) throw new Error("Serviço não encontrado");

      const [hours, minutes] = formData.hora_inicio.split(':');
      const inicio = new Date(formData.data);
      inicio.setHours(parseInt(hours), parseInt(minutes), 0, 0);

      // Validar se o horário é futuro
      const now = new Date();
      if (inicio < now) {
        toast({
          title: "Horário inválido",
          description: "Não é possível agendar para um horário que já passou.",
          variant: "destructive"
        });
        return;
      }

      const fim = new Date(inicio);
      fim.setMinutes(inicio.getMinutes() + servico.duracao_minutos);

      const updateData: any = {
        paciente_id: formData.paciente_id,
        profissional_id: formData.profissional_id,
        servico_id: formData.servico_id,
        paciente_pacote_id: formData.paciente_pacote_id || null,
        inicio: inicio.toISOString(),
        fim: fim.toISOString(),
        sala: formData.sala || null,
        notas: formData.notas || null,
        status: formData.status,
        updated_at: new Date().toISOString()
      };

      // Só permitir alteração de valores financeiros se o usuário tiver permissão
      if (canEditValues) {
        updateData.tipo_atendimento = formData.tipo_atendimento;
        updateData.plano_saude_id = formData.tipo_atendimento === 'plano' ? formData.plano_saude_id || null : null;
        updateData.valor_consulta = formData.valor_consulta ? parseFloat(formData.valor_consulta) : null;
        updateData.forma_pagamento_id = formData.tipo_atendimento === 'particular' ? formData.forma_pagamento_id || null : null;
        updateData.conta_pix_id = formData.conta_pix_id || null;
      }

      const { error } = await supabase
        .from('agenda')
        .update(updateData)
        .eq('id', appointmentId);

      if (error) throw error;

      // Se status mudou para "realizado" e há um pacote vinculado, processar uso
      if (formData.status === 'realizado' && formData.paciente_pacote_id) {
        const { data: usageData, error: usageError } = await supabase
          .rpc('usar_sessao_pacote', {
            p_paciente_pacote_id: formData.paciente_pacote_id,
            p_agendamento_id: appointmentId
          });

        if (usageError) {
          console.error('Erro ao usar sessão do pacote:', usageError);
          toast({
            title: "Aviso",
            description: "Consulta atualizada, mas houve erro ao processar o pacote.",
            variant: "destructive"
          });
        } else if (usageData && typeof usageData === 'object' && 'success' in usageData && usageData.success) {
          setPackageUsageNotification(usageData);
          setShowPackageNotification(true);
        }
      }

      toast({
        title: "Sucesso!",
        description: "Consulta atualizada com sucesso."
      });

      setOpen(false);
      setTimeout(() => {
        if (onSuccess) onSuccess();
      }, 150);
    } catch (error) {
      console.error('Erro ao atualizar consulta:', error);
      toast({
        title: "Erro",
        description: "Não foi possível atualizar a consulta.",
        variant: "destructive"
      });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={(isOpen) => {
      setOpen(isOpen);
      if (!isOpen && onSuccess) {
        onSuccess();
      }
    }}>
      <DialogTrigger asChild>
        {children}
      </DialogTrigger>
      <DialogContent className="max-w-4xl max-h-[95vh] overflow-hidden flex flex-col">
        <DialogHeader className="flex-shrink-0">
          <DialogTitle className="text-xl">Editar Consulta</DialogTitle>
          <DialogDescription className="text-sm">Altere os dados da consulta agendada.</DialogDescription>
        </DialogHeader>

        {isFetchingData ? (
          <div className="flex items-center justify-center py-8">
            <Loader2 className="h-8 w-8 animate-spin text-primary" />
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="space-y-4 flex-1 overflow-y-auto">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
              <div className="space-y-2">
                <Label htmlFor="paciente">Paciente *</Label>
                <PatientCombobox
                  value={formData.paciente_id}
                  onValueChange={(value) => {
                    setFormData({ ...formData, paciente_id: value, paciente_pacote_id: "" });
                    fetchPacotesPaciente(value);
                  }}
                  patients={pacientes}
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="profissional">Profissional *</Label>
                <ProfessionalCombobox
                  value={formData.profissional_id}
                  onValueChange={(value) => setFormData({ ...formData, profissional_id: value })}
                  professionals={profissionais}
                />
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
              <div className="space-y-1.5">
                <Label htmlFor="servico">Procedimento *</Label>
                <Select
                  value={formData.servico_id}
                  onValueChange={(value) => setFormData({ ...formData, servico_id: value })}
                >
                  <SelectTrigger id="servico">
                    <SelectValue placeholder="Selecione o procedimento" />
                  </SelectTrigger>
                  <SelectContent className="bg-background z-50">
                    {servicos.map((servico) => (
                      <SelectItem key={servico.id} value={servico.id}>
                        {servico.nome} - {servico.duracao_minutos}min
                        {servico.preco && ` - R$ ${servico.preco}`}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-1.5">
                <Label htmlFor="status">Status *</Label>
                <Select
                  value={formData.status}
                  onValueChange={(value) => setFormData({ ...formData, status: value as any })}
                >
                  <SelectTrigger id="status">
                    <SelectValue placeholder="Selecione o status" />
                  </SelectTrigger>
                  <SelectContent className="bg-background z-50">
                    <SelectItem value="agendado">Agendado</SelectItem>
                    <SelectItem value="confirmado">Confirmado</SelectItem>
                    <SelectItem value="em_andamento">Em Andamento</SelectItem>
                    <SelectItem value="concluido">Concluído</SelectItem>
                    <SelectItem value="cancelado">Cancelado</SelectItem>
                    <SelectItem value="faltou">Faltou</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
              <div className="space-y-1.5">
                <Label>Data *</Label>
                <Popover>
                  <PopoverTrigger asChild>
                    <Button
                      variant="outline"
                      className={cn(
                        "w-full justify-start text-left font-normal",
                        !formData.data && "text-muted-foreground"
                      )}
                    >
                      <CalendarIcon className="mr-2 h-4 w-4 flex-shrink-0" />
                      <span className="truncate">
                        {formData.data ? format(formData.data, "dd/MM/yyyy") : "Selecione a data"}
                      </span>
                    </Button>
                  </PopoverTrigger>
                  <PopoverContent className="w-auto p-0 bg-background z-50" align="start">
                    <Calendar
                      mode="single"
                      selected={formData.data}
                      onSelect={(date) => date && setFormData({ ...formData, data: date })}
                      initialFocus
                      locale={ptBR}
                      disabled={(date) => date < new Date(new Date().setHours(0, 0, 0, 0))}
                      className={cn("p-3 pointer-events-auto")}
                    />
                  </PopoverContent>
                </Popover>
              </div>

              <div className="space-y-1.5">
                <Label htmlFor="hora_inicio">Horário *</Label>
                <Input
                  id="hora_inicio"
                  type="time"
