import React, { useState, useEffect, useRef } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { FlexibleDatePicker } from "@/components/ui/flexible-date-picker";
import { useToast } from "@/hooks/use-toast";
import { supabase } from "@/integrations/supabase/client";
import { Loader2 } from "lucide-react";
import { format, parse } from "date-fns";

interface EditPatientDialogProps {
  patientId: string;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSuccess?: () => void;
}

export function EditPatientDialog({ 
  patientId, 
  open, 
  onOpenChange, 
  onSuccess 
}: EditPatientDialogProps) {
  const [isLoading, setIsLoading] = useState(false);
  const [initialData, setInitialData] = useState({
    nome: "",
    telefone: "",
    email: "",
    preferencia_contato: "whatsapp" as "whatsapp" | "sms" | "email",
    consentimento_lgpd: false,
    notas_internas: "",
    data_nascimento: undefined as Date | undefined,
    plano_saude_id: "",
    numero_carteirinha: ""
  });
  const [formData, setFormData] = useState(initialData);
  const [hasChanges, setHasChanges] = useState(false);
  const [planosSaude, setPlanosSaude] = useState<any[]>([]);
  const nomeRef = useRef<HTMLInputElement>(null);
  const telefoneRef = useRef<HTMLInputElement>(null);

  const { toast } = useToast();

  useEffect(() => {
    if (open && patientId) {
      fetchPatient();
      fetchPlanosSaude();
    }
  }, [open, patientId]);

  useEffect(() => {
    const changed = JSON.stringify(formData) !== JSON.stringify(initialData);
    setHasChanges(changed);
  }, [formData, initialData]);

  const fetchPlanosSaude = async () => {
    try {
      const { data, error } = await supabase
        .from('planos_saude')
        .select('id, nome')
        .eq('ativo', true)
        .order('nome');

      if (error) throw error;
      setPlanosSaude(data || []);
    } catch (error) {
      console.error('Erro ao buscar planos de saúde:', error);
    }
  };

  const fetchPatient = async () => {
    try {
      const { data, error } = await (supabase as any)
        .from('pacientes')
        .select('*')
        .eq('id', patientId)
        .maybeSingle();

      if (error) throw error;

      if (data) {
        // Converter data_nascimento de string para Date (parsing robusto)
        let dataNascimento: Date | undefined = undefined;
        if (data.data_nascimento) {
          const [y, m, d] = (data.data_nascimento as string).split('-').map(Number);
          const parsedDate = new Date(y, (m ?? 1) - 1, d ?? 1);
          if (
            !isNaN(parsedDate.getTime()) &&
            parsedDate.getFullYear() === y &&
            parsedDate.getMonth() === ((m ?? 1) - 1) &&
            parsedDate.getDate() === (d ?? 1)
          ) {
            dataNascimento = parsedDate;
          }
        }

        const patientData = {
          nome: data.nome || "",
          telefone: data.telefone || "",
          email: data.email || "",
          preferencia_contato: data.preferencia_contato || "whatsapp",
          consentimento_lgpd: data.consentimento_lgpd || false,
          notas_internas: data.notas_internas || "",
          data_nascimento: dataNascimento,
          plano_saude_id: data.plano_saude_id || "",
          numero_carteirinha: data.numero_carteirinha || ""
        };
        setInitialData(patientData);
        setFormData(patientData);
      }
    } catch (error) {
      console.error('Erro ao buscar paciente:', error);
      toast({
        title: "Erro",
        description: "Não foi possível carregar os dados do paciente.",
        variant: "destructive"
      });
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    const missingFields: string[] = [];
    if (!formData.nome.trim()) missingFields.push("Nome");
    if (!formData.telefone.trim()) missingFields.push("Telefone");

    if (missingFields.length > 0) {
      toast({
        title: "Campos obrigatórios não preenchidos",
        description: `Por favor, preencha: ${missingFields.join(", ")}`,
        variant: "destructive"
      });

      if (!formData.nome.trim()) nomeRef.current?.focus();
      else if (!formData.telefone.trim()) telefoneRef.current?.focus();

      return;
    }

    try {
      setIsLoading(true);

      // Validar e formatar data de nascimento
      let dataNascimentoFormatada = null;
      if (formData.data_nascimento instanceof Date && !isNaN(formData.data_nascimento.getTime())) {
        dataNascimentoFormatada = format(formData.data_nascimento, 'yyyy-MM-dd');
      }

      const { data: updated, error } = await (supabase as any)
        .from('pacientes')
        .update({
          nome: formData.nome.trim(),
          telefone: formData.telefone.trim(),
          email: formData.email.trim() || null,
          preferencia_contato: formData.preferencia_contato,
          consentimento_lgpd: formData.consentimento_lgpd,
          notas_internas: formData.notas_internas.trim() || null,
          data_nascimento: dataNascimentoFormatada,
          plano_saude_id: formData.plano_saude_id || null,
          numero_carteirinha: formData.numero_carteirinha?.trim() || null,
          updated_at: new Date().toISOString()
        })
        .eq('id', patientId)
        .select()
        .maybeSingle();

      if (error) throw error;
      if (!updated) throw new Error('Nenhuma linha atualizada. Verifique permissões de gravação.');

      toast({
        title: "Sucesso!",
        description: "Paciente atualizado com sucesso."
      });

      onOpenChange(false);

      if (onSuccess) {
        onSuccess();
      }
    } catch (error) {
      console.error('Erro ao atualizar:', error);
      toast({
        title: "Erro",
        description: "Não foi possível atualizar o paciente.",
        variant: "destructive"
      });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl">
        <DialogHeader>
          <DialogTitle className="text-xl">Editar Paciente</DialogTitle>
          <DialogDescription>
            Atualize as informações do paciente
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="nome">Nome Completo *</Label>
            <Input
              id="nome"
              ref={nomeRef}
              value={formData.nome}
              onChange={(e) => setFormData({ ...formData, nome: e.target.value })}
              placeholder="Nome do paciente"
              required
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="telefone">Telefone *</Label>
              <Input
                id="telefone"
                ref={telefoneRef}
                value={formData.telefone}
                onChange={(e) => setFormData({ ...formData, telefone: e.target.value })}
                placeholder="(00) 00000-0000"
                required
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="email">E-mail</Label>
              <Input
                id="email"
                type="email"
                value={formData.email}
                onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                placeholder="email@exemplo.com"
              />
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="preferencia">Preferência de Contato</Label>
            <Select 
              value={formData.preferencia_contato} 
              onValueChange={(value) => setFormData({ ...formData, preferencia_contato: value as any })}
            >
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="whatsapp">WhatsApp</SelectItem>
                <SelectItem value="sms">SMS</SelectItem>
                <SelectItem value="email">E-mail</SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div className="flex items-center justify-between">
            <Label htmlFor="lgpd">Consentimento LGPD</Label>
            <Switch
              id="lgpd"
              checked={formData.consentimento_lgpd}
              onCheckedChange={(checked) => setFormData({ ...formData, consentimento_lgpd: checked })}
            />
          </div>

          <FlexibleDatePicker
            label="Data de Nascimento"
            value={formData.data_nascimento}
            onChange={(date) => setFormData({ ...formData, data_nascimento: date })}
          />

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="plano">Plano de Saúde</Label>
              <Select 
                value={formData.plano_saude_id} 
                onValueChange={(value) => setFormData({ ...formData, plano_saude_id: value })}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Selecione o plano" />
                </SelectTrigger>
                <SelectContent>
                  {planosSaude.map((plano) => (
                    <SelectItem key={plano.id} value={plano.id}>
                      {plano.nome}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label htmlFor="carteirinha">Número da Carteirinha</Label>
              <Input
                id="carteirinha"
                value={formData.numero_carteirinha}
                onChange={(e) => setFormData({ ...formData, numero_carteirinha: e.target.value })}
                placeholder="Número da carteirinha"
              />
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="notas">Notas Internas</Label>
            <Textarea
              id="notas"
              value={formData.notas_internas}
              onChange={(e) => setFormData({ ...formData, notas_internas: e.target.value })}
              placeholder="Observações internas sobre o paciente..."
              rows={3}
            />
          </div>

                <div className="flex justify-end gap-3 pt-4">
                  {hasChanges && (
                    <Button
                      type="button"
                      variant="outline"
                      onClick={() => {
                        setFormData(initialData);
                        setHasChanges(false);
                      }}
                    >
                      Cancelar Alterações
                    </Button>
                  )}
                  <Button type="submit" disabled={isLoading || !hasChanges}>
                    {isLoading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                    Salvar Alterações
                  </Button>
                </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Switch } from "@/components/ui/switch";
import { useToast } from "@/hooks/use-toast";
import { supabase } from "@/integrations/supabase/client";
import { Loader2 } from "lucide-react";

interface EditProcedimentoDialogProps {
  procedimentoId: string;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSuccess?: () => void;
  children?: React.ReactNode;
}

export function EditProcedimentoDialog({ 
  procedimentoId, 
  open, 
  onOpenChange, 
  onSuccess,
  children
}: EditProcedimentoDialogProps) {
  const [isLoading, setIsLoading] = useState(false);
  const [formData, setFormData] = useState({
    nome: "",
    duracao_minutos: "",
    preco: "",
    codigo_tuss: "",
    descricao: "",
    tempo_preparo_minutos: "",
    instrucoes: "",
    requisitos: "",
    confirmacao_24h: false,
    ativo: true
  });

  const { toast } = useToast();

  useEffect(() => {
    if (open && procedimentoId) {
      fetchProcedimento();
    }
  }, [open, procedimentoId]);

  const fetchProcedimento = async () => {
    try {
      const { data, error } = await supabase
        .from('procedimentos')
        .select('*')
        .eq('id', procedimentoId)
        .single();

      if (error) throw error;

      setFormData({
        nome: data.nome || "",
        duracao_minutos: data.duracao_minutos?.toString() || "",
        preco: data.preco?.toString() || "",
        codigo_tuss: data.codigo_tuss || "",
        descricao: data.descricao || "",
        tempo_preparo_minutos: data.tempo_preparo_minutos?.toString() || "",
        instrucoes: data.instrucoes || "",
        requisitos: data.requisitos || "",
        confirmacao_24h: data.confirmacao_24h || false,
        ativo: data.ativo !== false
      });
    } catch (error) {
      console.error('Erro ao buscar procedimento:', error);
      toast({
        title: "Erro",
        description: "Não foi possível carregar os dados do procedimento.",
        variant: "destructive"
      });
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.nome || !formData.duracao_minutos) {
      toast({
        title: "Campos obrigatórios",
        description: "Nome e duração são obrigatórios.",
        variant: "destructive"
      });
      return;
    }

    try {
      setIsLoading(true);

      const { error } = await supabase
        .from('procedimentos')
        .update({
          nome: formData.nome.trim(),
          duracao_minutos: parseInt(formData.duracao_minutos),
          preco: formData.preco ? parseFloat(formData.preco) : null,
          codigo_tuss: formData.codigo_tuss.trim() || null,
          descricao: formData.descricao.trim() || null,
          tempo_preparo_minutos: formData.tempo_preparo_minutos ? parseInt(formData.tempo_preparo_minutos) : null,
          instrucoes: formData.instrucoes.trim() || null,
          requisitos: formData.requisitos.trim() || null,
          confirmacao_24h: formData.confirmacao_24h,
          ativo: formData.ativo,
          updated_at: new Date().toISOString()
        })
        .eq('id', procedimentoId);

      if (error) throw error;

      toast({
        title: "Sucesso!",
        description: "Procedimento atualizado com sucesso."
      });

      onOpenChange(false);
      if (onSuccess) onSuccess();
    } catch (error) {
      console.error('Erro ao atualizar procedimento:', error);
      toast({
        title: "Erro",
        description: "Não foi possível atualizar o procedimento.",
        variant: "destructive"
      });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      {children}
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>Editar Procedimento</DialogTitle>
          <DialogDescription>Altere as informações do procedimento</DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2 col-span-2">
              <Label htmlFor="nome">Nome *</Label>
              <Input
                id="nome"
                value={formData.nome}
                onChange={(e) => setFormData(prev => ({ ...prev, nome: e.target.value }))}
                required
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="codigo_tuss">Código TUSS</Label>
              <Input
                id="codigo_tuss"
                value={formData.codigo_tuss}
                onChange={(e) => setFormData(prev => ({ ...prev, codigo_tuss: e.target.value }))}
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="duracao">Duração (minutos) *</Label>
              <Input
                id="duracao"
                type="number"
                min="1"
                value={formData.duracao_minutos}
                onChange={(e) => setFormData(prev => ({ ...prev, duracao_minutos: e.target.value }))}
                required
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="preparo">Tempo de Preparo (minutos)</Label>
              <Input
                id="preparo"
                type="number"
                min="0"
                value={formData.tempo_preparo_minutos}
                onChange={(e) => setFormData(prev => ({ ...prev, tempo_preparo_minutos: e.target.value }))}
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="preco">Preço (R$)</Label>
              <Input
                id="preco"
                type="number"
                step="0.01"
                min="0"
                value={formData.preco}
                onChange={(e) => setFormData(prev => ({ ...prev, preco: e.target.value }))}
              />
            </div>

            <div className="space-y-2 col-span-2">
              <Label htmlFor="descricao">Descrição</Label>
              <Textarea
                id="descricao"
                value={formData.descricao}
                onChange={(e) => setFormData(prev => ({ ...prev, descricao: e.target.value }))}
                rows={2}
              />
            </div>

            <div className="space-y-2 col-span-2">
              <Label htmlFor="instrucoes">Instruções</Label>
              <Textarea
                id="instrucoes"
                value={formData.instrucoes}
                onChange={(e) => setFormData(prev => ({ ...prev, instrucoes: e.target.value }))}
                rows={2}
              />
            </div>

            <div className="space-y-2 col-span-2">
              <Label htmlFor="requisitos">Requisitos</Label>
              <Textarea
                id="requisitos"
                value={formData.requisitos}
                onChange={(e) => setFormData(prev => ({ ...prev, requisitos: e.target.value }))}
                rows={2}
              />
            </div>

            <div className="flex items-center justify-between col-span-2">
              <Label htmlFor="confirmacao">Confirmar 24h antes</Label>
              <Switch
                id="confirmacao"
                checked={formData.confirmacao_24h}
                onCheckedChange={(checked) => setFormData(prev => ({ ...prev, confirmacao_24h: checked }))}
              />
            </div>

            <div className="flex items-center justify-between col-span-2">
              <Label htmlFor="ativo">Ativo</Label>
              <Switch
                id="ativo"
                checked={formData.ativo}
                onCheckedChange={(checked) => setFormData(prev => ({ ...prev, ativo: checked }))}
              />
            </div>
          </div>

          <div className="flex justify-end gap-3 pt-4">
            <Button type="button" variant="outline" onClick={() => onOpenChange(false)}>
              Cancelar
            </Button>
            <Button type="submit" disabled={isLoading}>
              {isLoading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Salvar Alterações
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { FlexibleDatePicker } from "@/components/ui/flexible-date-picker";
import { useToast } from "@/hooks/use-toast";
import { supabase } from "@/integrations/supabase/client";
import { Loader2, X } from "lucide-react";
import { format, parse } from "date-fns";

interface Especialidade {
  id: string;
  nome: string;
  conselho?: string;
}

interface TipoProfissional {
  id: string;
  nome: string;
}

interface EditProfessionalDialogProps {
  professionalId: string;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSuccess?: () => void;
}

export function EditProfessionalDialog({ 
  professionalId, 
  open, 
  onOpenChange, 
  onSuccess 
}: EditProfessionalDialogProps) {
  const [isLoading, setIsLoading] = useState(false);
  const [especialidades, setEspecialidades] = useState<Especialidade[]>([]);
  const [tiposProfissional, setTiposProfissional] = useState<any[]>([]);
  const [selectedEspecialidades, setSelectedEspecialidades] = useState<string[]>([]);
  const [formData, setFormData] = useState({
    nome: "",
    email: "",
    telefone: "",
    cpf: "",
    numero_registro: "",
    uf_registro: "",
    tipo_profissional_id: "",
    data_nascimento: undefined as Date | undefined
  });

  const { toast } = useToast();

  useEffect(() => {
    if (open) {
      fetchEspecialidades();
      fetchTiposProfissional();
      if (professionalId) {
        fetchProfessional();
      }
    }
  }, [open, professionalId]);

  const fetchEspecialidades = async () => {
    try {
      const { data, error } = await supabase
        .from('especialidades')
        .select('id, nome, conselho')
        .eq('ativo', true)
        .order('nome');

      if (error) throw error;
      setEspecialidades(data || []);
    } catch (error) {
      console.error('Erro ao buscar especialidades:', error);
    }
  };

  const fetchTiposProfissional = async () => {
    try {
      const { data, error } = await (supabase as any)
        .from('tipos_profissional')
        .select('id, nome')
        .eq('ativo', true)
        .order('nome');

      if (error) throw error;
      setTiposProfissional(data || []);
    } catch (error) {
      console.error('Erro ao buscar tipos de profissional:', error);
    }
  };

  const fetchProfessional = async () => {
    try {
      const { data, error } = await (supabase as any)
        .from('profiles')
        .select('*')
        .eq('id', professionalId)
        .maybeSingle();

      if (error) throw error;

      if (data) {
        // Converter data_nascimento de string para Date (parsing robusto)
        let dataNascimento: Date | undefined = undefined;
        if (data.data_nascimento) {
          const [y, m, d] = (data.data_nascimento as string).split('-').map(Number);
          const parsedDate = new Date(y, (m ?? 1) - 1, d ?? 1);
          if (
            !isNaN(parsedDate.getTime()) &&
            parsedDate.getFullYear() === y &&
            parsedDate.getMonth() === ((m ?? 1) - 1) &&
            parsedDate.getDate() === (d ?? 1)
          ) {
            dataNascimento = parsedDate;
          }
        }

        setFormData({
          nome: data.nome || "",
          email: data.email || "",
          telefone: data.telefone || "",
          cpf: data.cpf || "",
          numero_registro: data.numero_registro || "",
          uf_registro: data.uf_registro || "",
          tipo_profissional_id: data.tipo_profissional_id || "",
          data_nascimento: dataNascimento
        });

        // Buscar especialidades do profissional
        const { data: espData, error: espError } = await (supabase as any)
          .from('profissional_especialidades')
          .select('especialidade_id')
          .eq('profissional_id', professionalId);

        if (espError) throw espError;
        setSelectedEspecialidades(espData?.map((e: any) => e.especialidade_id) || []);
      }
    } catch (error) {
      console.error('Erro ao buscar profissional:', error);
      toast({
        title: "Erro",
        description: "Não foi possível carregar os dados do profissional.",
        variant: "destructive"
      });
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.nome) {
      toast({
        title: "Campos obrigatórios",
        description: "Nome é obrigatório.",
        variant: "destructive"
      });
      return;
    }

    try {
      setIsLoading(true);

      // Obter tenant_id
      const { data: profile } = await supabase
        .from('profiles')
        .select('tenant_id')
        .eq('id', professionalId)
        .maybeSingle();

      if (!profile?.tenant_id) throw new Error("Tenant não encontrado");

      // Validar e formatar data de nascimento
      let dataNascimentoFormatada = null;
      if (formData.data_nascimento instanceof Date && !isNaN(formData.data_nascimento.getTime())) {
        dataNascimentoFormatada = format(formData.data_nascimento, 'yyyy-MM-dd');
      }

      const { data: updated, error } = await (supabase as any)
        .from('profiles')
        .update({
          nome: formData.nome,
          telefone: formData.telefone || null,
          cpf: formData.cpf || null,
          numero_registro: formData.numero_registro || null,
          uf_registro: formData.uf_registro || null,
          tipo_profissional_id: formData.tipo_profissional_id ? formData.tipo_profissional_id : null,
          data_nascimento: dataNascimentoFormatada,
          updated_at: new Date().toISOString()
        })
        .eq('id', professionalId)
        .select()
        .maybeSingle();

      if (error) throw error;
      if (!updated) throw new Error('Nenhuma linha atualizada. Verifique permissões de gravação.');

      // Atualizar especialidades
      // Primeiro, remover todas as especialidades existentes
      await (supabase as any)
        .from('profissional_especialidades')
        .delete()
        .eq('profissional_id', professionalId);

      // Inserir as novas especialidades
      if (selectedEspecialidades.length > 0) {
        const { error: espError } = await (supabase as any)
          .from('profissional_especialidades')
          .insert(
            selectedEspecialidades.map(esp_id => ({
              tenant_id: profile.tenant_id,
              profissional_id: professionalId,
              especialidade_id: esp_id
            }))
          );

        if (espError) throw espError;
      }

      toast({
        title: "Sucesso!",
        description: "Profissional atualizado com sucesso."
      });

      onOpenChange(false);

      if (onSuccess) {
        onSuccess();
      }
    } catch (error) {
      console.error('Erro ao atualizar:', error);
      toast({
        title: "Erro",
        description: "Não foi possível atualizar o profissional.",
        variant: "destructive"
      });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="text-xl">Editar Profissional</DialogTitle>
          <DialogDescription>
            Atualize as informações do profissional de saúde
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="nome">Nome Completo *</Label>
            <Input
              id="nome"
              value={formData.nome}
              onChange={(e) => setFormData({ ...formData, nome: e.target.value })}
              placeholder="Nome do profissional"
              required
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="email">E-mail</Label>
              <Input
                id="email"
                type="email"
                disabled
                className="bg-muted cursor-not-allowed"
                value={formData.email}
                placeholder="email@exemplo.com"
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="telefone">Telefone</Label>
              <Input
                id="telefone"
                value={formData.telefone}
                onChange={(e) => setFormData({ ...formData, telefone: e.target.value })}
                placeholder="(00) 00000-0000"
              />
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="tipo">Tipo de Profissional</Label>
            <Select 
              value={formData.tipo_profissional_id} 
              onValueChange={(value) => setFormData({ ...formData, tipo_profissional_id: value })}
            >
              <SelectTrigger>
                <SelectValue placeholder="Selecione o tipo" />
              </SelectTrigger>
              <SelectContent>
                {tiposProfissional.map((tipo) => (
                  <SelectItem key={tipo.id} value={tipo.id}>
                    {tipo.nome}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="cpf">CPF</Label>
              <Input
                id="cpf"
                value={formData.cpf}
                onChange={(e) => setFormData({ ...formData, cpf: e.target.value })}
                placeholder="000.000.000-00"
              />
            </div>
          </div>

          <div className="space-y-2">
            <Label>Especialidades</Label>
            <Select
              value=""
              onValueChange={(value) => {
                if (!selectedEspecialidades.includes(value)) {
                  setSelectedEspecialidades([...selectedEspecialidades, value]);
                }
              }}
            >
              <SelectTrigger>
                <SelectValue placeholder="Adicionar especialidade" />
              </SelectTrigger>
              <SelectContent>
                {especialidades
                  .filter(esp => !selectedEspecialidades.includes(esp.id))
                  .map((esp) => (
                    <SelectItem key={esp.id} value={esp.id}>
                      {esp.nome} {esp.conselho && `(${esp.conselho})`}
                    </SelectItem>
                  ))}
              </SelectContent>
            </Select>
            <div className="flex flex-wrap gap-2 mt-2">
              {selectedEspecialidades.map(espId => {
                const esp = especialidades.find(e => e.id === espId);
                return esp ? (
                  <Badge key={espId} variant="secondary" className="gap-1">
                    {esp.nome}
                    <X
                      className="h-3 w-3 cursor-pointer"
                      onClick={() => setSelectedEspecialidades(
                        selectedEspecialidades.filter(id => id !== espId)
                      )}
                    />
                  </Badge>
                ) : null;
              })}
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="numero_registro">Número de Registro</Label>
              <Input
                id="numero_registro"
                value={formData.numero_registro}
                onChange={(e) => setFormData({ ...formData, numero_registro: e.target.value })}
                placeholder="Ex: 123456"
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="uf">UF</Label>
              <Input
                id="uf"
                value={formData.uf_registro}
                onChange={(e) => setFormData({ ...formData, uf_registro: e.target.value })}
                placeholder="Ex: SP"
                maxLength={2}
              />
            </div>
          </div>

          <FlexibleDatePicker
            label="Data de Nascimento"
            value={formData.data_nascimento}
            onChange={(date) => setFormData({ ...formData, data_nascimento: date })}
          />

          <div className="flex justify-end gap-3 pt-4">
            <Button
              type="button"
              variant="outline"
              onClick={() => onOpenChange(false)}
              disabled={isLoading}
            >
              Cancelar
            </Button>
            <Button type="submit" disabled={isLoading}>
              {isLoading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Salvar Alterações
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Switch } from "@/components/ui/switch";
import { useToast } from "@/hooks/use-toast";
import { supabase } from "@/integrations/supabase/client";
import { Loader2 } from "lucide-react";

interface EditServiceDialogProps {
  serviceId: string;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSuccess?: () => void;
}

export function EditServiceDialog({ 
  serviceId, 
  open, 
  onOpenChange, 
  onSuccess 
}: EditServiceDialogProps) {
  const [isLoading, setIsLoading] = useState(false);
  const [formData, setFormData] = useState({
    nome: "",
    duracao_minutos: "",
    preco: "",
    confirmacao_24h: false,
    ativo: true
  });

  const { toast } = useToast();

  useEffect(() => {
    if (open && serviceId) {
      fetchService();
    }
  }, [open, serviceId]);

  const fetchService = async () => {
    try {
      const { data, error } = await supabase
        .from('servicos')
        .select('*')
        .eq('id', serviceId)
        .single();

      if (error) throw error;

      setFormData({
        nome: data.nome || "",
        duracao_minutos: data.duracao_minutos?.toString() || "",
        preco: data.preco?.toString() || "",
        confirmacao_24h: data.confirmacao_24h || false,
        ativo: data.ativo !== false
      });
    } catch (error) {
      console.error('Erro ao buscar serviço:', error);
      toast({
        title: "Erro",
        description: "Não foi possível carregar os dados do serviço.",
        variant: "destructive"
      });
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.nome || !formData.duracao_minutos) {
      toast({
        title: "Campos obrigatórios",
        description: "Nome e duração são obrigatórios.",
        variant: "destructive"
      });
      return;
    }

    try {
      setIsLoading(true);

      const { error } = await supabase
        .from('servicos')
        .update({
          nome: formData.nome.trim(),
          duracao_minutos: parseInt(formData.duracao_minutos),
          preco: formData.preco ? parseFloat(formData.preco) : null,
          confirmacao_24h: formData.confirmacao_24h,
          ativo: formData.ativo,
          updated_at: new Date().toISOString()
        })
        .eq('id', serviceId);

      if (error) throw error;

      toast({
        title: "Sucesso!",
        description: "Serviço atualizado com sucesso."
      });

      onOpenChange(false);

      if (onSuccess) {
        onSuccess();
      }
    } catch (error) {
      console.error('Erro ao atualizar:', error);
      toast({
        title: "Erro",
        description: "Não foi possível atualizar o serviço.",
        variant: "destructive"
      });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-lg">
        <DialogHeader>
          <DialogTitle className="text-xl">Editar Serviço</DialogTitle>
          <DialogDescription>
            Atualize as informações do serviço
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="nome">Nome do Serviço *</Label>
            <Input
              id="nome"
              value={formData.nome}
              onChange={(e) => setFormData({ ...formData, nome: e.target.value })}
              placeholder="Ex: Consulta, Procedimento, Exame"
              required
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="duracao">Duração (minutos) *</Label>
              <Input
                id="duracao"
                type="number"
                min="1"
                value={formData.duracao_minutos}
                onChange={(e) => setFormData({ ...formData, duracao_minutos: e.target.value })}
                placeholder="30"
                required
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="preco">Preço (R$)</Label>
              <Input
                id="preco"
                type="number"
                step="0.01"
                min="0"
                value={formData.preco}
                onChange={(e) => setFormData({ ...formData, preco: e.target.value })}
                placeholder="150.00"
              />
            </div>
          </div>

          <div className="flex items-center justify-between">
            <Label htmlFor="confirmacao">Confirmar 24h antes?</Label>
            <Switch
              id="confirmacao"
              checked={formData.confirmacao_24h}
              onCheckedChange={(checked) => setFormData({ ...formData, confirmacao_24h: checked })}
            />
          </div>

          <div className="flex items-center justify-between">
            <Label htmlFor="ativo">Serviço ativo?</Label>
            <Switch
              id="ativo"
              checked={formData.ativo}
              onCheckedChange={(checked) => setFormData({ ...formData, ativo: checked })}
            />
          </div>

          <div className="flex justify-end gap-3 pt-4">
            <Button
              type="button"
              variant="outline"
              onClick={() => onOpenChange(false)}
              disabled={isLoading}
            >
              Cancelar
            </Button>
            <Button type="submit" disabled={isLoading}>
              {isLoading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Salvar Alterações
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { ChevronLeft, ChevronRight, Calendar as CalendarIcon } from "lucide-react";
import { format, startOfMonth, endOfMonth, eachDayOfInterval, isSameDay, isSameMonth, addMonths, subMonths, startOfWeek, endOfWeek } from "date-fns";
import { ptBR } from "date-fns/locale";
import { cn } from "@/lib/utils";
import { supabase } from "@/integrations/supabase/client";

interface DayStats {
  date: Date;
  appointmentCount: number;
  maxCapacity: number; // Define capacidade máxima por dia (pode ser configurável)
}

interface MonthlyCalendarProps {
  selectedDate: Date;
  onDateSelect: (date: Date) => void;
  className?: string;
}

export function MonthlyCalendar({ selectedDate, onDateSelect, className }: MonthlyCalendarProps) {
  const [currentMonth, setCurrentMonth] = useState(selectedDate);
  const [dayStats, setDayStats] = useState<DayStats[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  const MAX_APPOINTMENTS_PER_DAY = 12; // Configurável

  // Buscar estatísticas do mês
  const fetchMonthStats = async () => {
    try {
      setIsLoading(true);
      const monthStart = startOfMonth(currentMonth);
      const monthEnd = endOfMonth(currentMonth);

      const { data, error } = await supabase
        .from('agenda')
        .select('inicio, id')
        .gte('inicio', monthStart.toISOString())
        .lte('inicio', monthEnd.toISOString());

      if (error) throw error;

      // Agrupar por dia
      const statsByDay = new Map<string, number>();

      (data || []).forEach((apt) => {
        const aptDate = new Date(apt.inicio);
        const dateKey = format(aptDate, 'yyyy-MM-dd');
        statsByDay.set(dateKey, (statsByDay.get(dateKey) || 0) + 1);
      });

      // Criar array de estatísticas
      const daysInMonth = eachDayOfInterval({ start: monthStart, end: monthEnd });
      const stats: DayStats[] = daysInMonth.map(day => ({
        date: day,
        appointmentCount: statsByDay.get(format(day, 'yyyy-MM-dd')) || 0,
        maxCapacity: MAX_APPOINTMENTS_PER_DAY
      }));

      setDayStats(stats);
    } catch (error) {
      console.error('Erro ao buscar estatísticas do mês:', error);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchMonthStats();
  }, [currentMonth]);

  // Atualizar mês quando selectedDate mudar
  useEffect(() => {
    if (!isSameMonth(selectedDate, currentMonth)) {
      setCurrentMonth(selectedDate);
    }
  }, [selectedDate]);

  const handlePreviousMonth = () => {
    setCurrentMonth(prev => subMonths(prev, 1));
  };

  const handleNextMonth = () => {
    setCurrentMonth(prev => addMonths(prev, 1));
  };

  const handleToday = () => {
    const today = new Date();
    setCurrentMonth(today);
    onDateSelect(today);
  };

  // Obter cor baseado na quantidade de agendamentos
  const getDayColor = (stats: DayStats) => {
    if (stats.appointmentCount === 0) {
      return "bg-green-500/20 hover:bg-green-500/30 border-green-500/50"; // Livre
    } else if (stats.appointmentCount >= stats.maxCapacity) {
      return "bg-red-500/20 hover:bg-red-500/30 border-red-500/50"; // Lotado
    } else {
      return "bg-blue-500/20 hover:bg-blue-500/30 border-blue-500/50"; // Com agendamentos
    }
  };

  // Obter dias para renderizar (incluindo dias da semana anterior/próxima)
  const monthStart = startOfMonth(currentMonth);
  const monthEnd = endOfMonth(currentMonth);
  const calendarStart = startOfWeek(monthStart, { locale: ptBR });
  const calendarEnd = endOfWeek(monthEnd, { locale: ptBR });
  const calendarDays = eachDayOfInterval({ start: calendarStart, end: calendarEnd });

  const weekDays = ['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb'];

  return (
    <Card className={cn("", className)}>
      <CardHeader className="pb-3">
        <div className="flex items-center justify-between">
          <CardTitle className="text-lg flex items-center gap-2">
            <CalendarIcon className="h-5 w-5 text-primary" />
            {format(currentMonth, "MMMM yyyy", { locale: ptBR })}
          </CardTitle>
          <div className="flex gap-1">
            <Button
              variant="ghost"
              size="icon"
              className="h-8 w-8"
              onClick={handlePreviousMonth}
            >
              <ChevronLeft className="h-4 w-4" />
            </Button>
            <Button
              variant="ghost"
              size="icon"
              className="h-8 w-8"
              onClick={handleNextMonth}
            >
              <ChevronRight className="h-4 w-4" />
            </Button>
          </div>
        </div>
        <Button
          variant="outline"
          size="sm"
          onClick={handleToday}
          className="w-full mt-2"
        >
          Hoje
        </Button>
      </CardHeader>

      <CardContent className="pt-0">
        {isLoading ? (
          <div className="flex items-center justify-center py-8">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
          </div>
        ) : (
          <>
            {/* Cabeçalho dos dias da semana */}
            <div className="grid grid-cols-7 gap-1 mb-2">
              {weekDays.map((day) => (
                <div
                  key={day}
                  className="text-center text-xs font-semibold text-muted-foreground py-1"
                >
                  {day}
                </div>
              ))}
            </div>

            {/* Grid de dias */}
            <div className="grid grid-cols-7 gap-1">
              {calendarDays.map((day) => {
                const stats = dayStats.find(s => isSameDay(s.date, day));
                const isCurrentMonth = isSameMonth(day, currentMonth);
                const isSelected = isSameDay(day, selectedDate);
                const isToday = isSameDay(day, new Date());

                return (
                  <button
                    key={day.toISOString()}
                    onClick={() => onDateSelect(day)}
                    disabled={!isCurrentMonth}
                    className={cn(
                      "relative aspect-square rounded-md border transition-all",
                      "flex flex-col items-center justify-center text-sm",
                      "disabled:opacity-40 disabled:cursor-not-allowed",
                      isCurrentMonth && stats && getDayColor(stats),
                      !isCurrentMonth && "bg-muted/30 hover:bg-muted/50",
                      isSelected && "ring-2 ring-primary ring-offset-2",
                      isToday && !isSelected && "ring-1 ring-primary/50",
                      "hover:scale-105 active:scale-95"
                    )}
                  >
                    <span className={cn(
                      "font-medium",
                      isCurrentMonth ? "text-foreground" : "text-muted-foreground",
                      isToday && "font-bold"
                    )}>
                      {format(day, 'd')}
                    </span>
                    {stats && stats.appointmentCount > 0 && (
                      <span className="text-[10px] font-semibold mt-0.5">
                        {stats.appointmentCount}
                      </span>
                    )}
                  </button>
                );
              })}
            </div>

            {/* Legenda */}
            <div className="mt-4 pt-4 border-t space-y-2">
              <p className="text-xs font-semibold text-muted-foreground mb-2">Legenda:</p>
              <div className="flex items-center gap-2 text-xs">
                <div className="h-4 w-4 rounded bg-green-500/20 border border-green-500/50"></div>
                <span className="text-muted-foreground">Livre</span>
              </div>
              <div className="flex items-center gap-2 text-xs">
                <div className="h-4 w-4 rounded bg-blue-500/20 border border-blue-500/50"></div>
                <span className="text-muted-foreground">Com agendamentos</span>
              </div>
              <div className="flex items-center gap-2 text-xs">
                <div className="h-4 w-4 rounded bg-red-500/20 border border-red-500/50"></div>
                <span className="text-muted-foreground">Lotado ({MAX_APPOINTMENTS_PER_DAY}+)</span>
              </div>
            </div>
          </>
        )}
      </CardContent>
    </Card>
  );
}

import React, { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger, DialogDescription } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Calendar } from "@/components/ui/calendar";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { useToast } from "@/hooks/use-toast";
import { supabase } from "@/integrations/supabase/client";
import { format, startOfDay, endOfDay } from "date-fns";
import { ptBR } from "date-fns/locale";
import { CalendarIcon, Loader2, AlertTriangle } from "lucide-react";
import { cn } from "@/lib/utils";
import { NewPatientDialog } from "./NewPatientDialog";
import { NewProfessionalDialog } from "./NewProfessionalDialog";
import { PatientCombobox } from "./PatientCombobox";
import { ProfessionalCombobox } from "./ProfessionalCombobox";
import { checkNewAppointmentConflict } from "@/lib/scheduleConflicts";
import { automationEngine } from "@/domain/automations/automationEngine";
import { noShowModel } from "@/domain/analytics/noShowModel";

interface NewAppointmentDialogProps {
  children: React.ReactNode;
  selectedDate?: Date;
  selectedTime?: string;
  onSuccess?: () => void;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
}

export function NewAppointmentDialog({ children, selectedDate, selectedTime, onSuccess, open: controlledOpen, onOpenChange }: NewAppointmentDialogProps) {
  const [internalOpen, setInternalOpen] = useState(false);
  const open = controlledOpen !== undefined ? controlledOpen : internalOpen;
  const setOpen = onOpenChange || setInternalOpen;
  const [isLoading, setIsLoading] = useState(false);
  const [isFetchingData, setIsFetchingData] = useState(true);
  const [conflictWarning, setConflictWarning] = useState<{ show: boolean; minutes: number } | null>(null);
  const [forceCreate, setForceCreate] = useState(false);

  const [pacientes, setPacientes] = useState<any[]>([]);
  const [profissionais, setProfissionais] = useState<any[]>([]);
  const [servicos, setServicos] = useState<any[]>([]);
  const [pacientesPacotes, setPacientesPacotes] = useState<any[]>([]);
  const [existingAppointments, setExistingAppointments] = useState<any[]>([]);
  const [profissionalEspecialidades, setProfissionalEspecialidades] = useState<any[]>([]);
  const [planosSaude, setPlanosSaude] = useState<any[]>([]);
  const [formasPagamento, setFormasPagamento] = useState<any[]>([]);
  const [contasPix, setContasPix] = useState<any[]>([]);

  const [formData, setFormData] = useState({
    paciente_id: "",
    profissional_id: "",
    especialidade_id: "",
    servico_id: "",
    paciente_pacote_id: "",
    data: selectedDate || new Date(),
    hora_inicio: selectedTime || "",
    sala: "",
    notas: "",
    tipo_atendimento: "particular",
    plano_saude_id: "",
    valor_consulta: "",
    forma_pagamento_id: "",
    conta_pix_id: ""
  });

  // Atualizar data e hora quando props mudarem
  useEffect(() => {
    if (selectedDate) {
      setFormData(prev => ({ ...prev, data: selectedDate }));
    }
  }, [selectedDate]);

  useEffect(() => {
    if (selectedTime) {
      setFormData(prev => ({ ...prev, hora_inicio: selectedTime }));
    }
  }, [selectedTime]);

  const { toast } = useToast();

  useEffect(() => {
    if (open) {
      fetchData();
    }
  }, [open]);

  const fetchData = async () => {
    try {
      setIsFetchingData(true);

      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error("Usuário não autenticado");

      const { data: profileData, error: profileError } = await supabase
        .from('profiles')
        .select('tenant_id')
        .eq('id', user.id)
        .single();

      if (profileError) throw profileError;

      const [pacientesRes, profissionaisRes, servicosRes, planosSaudeRes, formasPagamentoRes, contasPixRes] = await Promise.all([
        supabase.from('pacientes').select('id, nome, telefone').eq('tenant_id', profileData.tenant_id).order('nome'),
        supabase.from('profiles').select('id, nome, role').eq('tenant_id', profileData.tenant_id).order('nome'),
        supabase.from('servicos').select('id, nome, duracao_minutos, preco').eq('tenant_id', profileData.tenant_id).eq('ativo', true).order('nome'),
        supabase.from('planos_saude').select('id, nome').eq('tenant_id', profileData.tenant_id).eq('ativo', true).order('nome'),
        supabase.from('formas_pagamento').select('id, nome, tipo').eq('tenant_id', profileData.tenant_id).eq('ativo', true).order('ordem'),
        supabase.from('contas_pix').select('id, nome, chave_pix').eq('tenant_id', profileData.tenant_id).eq('ativo', true).order('nome')
      ]);

      if (pacientesRes.error) throw pacientesRes.error;
      if (profissionaisRes.error) throw profissionaisRes.error;
      if (servicosRes.error) throw servicosRes.error;
      console.log('Procedimentos encontrados:', servicosRes.data);

      // Filtrar apenas profissionais no frontend
      const profissionaisFiltrados = (profissionaisRes.data || []).filter(
        prof => prof.role === 'profissional' || prof.role === 'admin' || prof.role === 'admin_tenant'
      );

      setPacientes(pacientesRes.data || []);
      setProfissionais(profissionaisFiltrados);
      setServicos(servicosRes.data || []);
      setPlanosSaude(planosSaudeRes.data || []);
      setFormasPagamento(formasPagamentoRes.data || []);
      setContasPix(contasPixRes.data || []);

      // Buscar agendamentos existentes no dia selecionado
      await fetchExistingAppointments(formData.data);
    } catch (error) {
      console.error('Erro ao buscar dados:', error);
      toast({
        title: "Erro",
        description: "Não foi possível carregar os dados necessários.",
        variant: "destructive"
      });
    } finally {
      setIsFetchingData(false);
    }
  };

  const fetchExistingAppointments = async (date: Date) => {
    try {
      const dayStart = startOfDay(date);
      const dayEnd = endOfDay(date);

      const { data, error } = await supabase
        .from('agenda')
        .select('id, inicio, fim, procedimentos:servico_id(duracao_minutos)')
        .gte('inicio', dayStart.toISOString())
        .lte('inicio', dayEnd.toISOString())
        .order('inicio');

      if (error) throw error;

      const appointments = (data || []).map(apt => ({
        id: apt.id,
        inicio: apt.inicio,
        duration: apt.procedimentos?.duracao_minutos || 30
      }));

      setExistingAppointments(appointments);
    } catch (error) {
      console.error('Erro ao buscar agendamentos:', error);
    }
  };

  // Verificar conflitos quando hora ou serviço mudam
  useEffect(() => {
    if (formData.hora_inicio && formData.servico_id && existingAppointments.length > 0) {
      const servico = servicos.find(s => s.id === formData.servico_id);
      if (!servico) return;

      const [hours, minutes] = formData.hora_inicio.split(':');
      const inicio = new Date(formData.data);
      inicio.setHours(parseInt(hours), parseInt(minutes), 0, 0);

      const conflict = checkNewAppointmentConflict(
        inicio,
        servico.duracao_minutos,
        existingAppointments
      );

      if (conflict.hasConflict) {
        setConflictWarning({ show: true, minutes: conflict.overlapMinutes });
      } else {
        setConflictWarning(null);
      }
    } else {
      setConflictWarning(null);
    }
  }, [formData.hora_inicio, formData.servico_id, formData.data, existingAppointments, servicos]);

  const fetchPacotesPaciente = async (pacienteId: string) => {
    if (!pacienteId) {
      setPacientesPacotes([]);
      return;
    }

    try {
      const { data, error } = await supabase
        .from('pacientes_pacotes')
        .select('*, pacotes(nome)')
        .eq('paciente_id', pacienteId)
        .eq('status', 'ativo')
        .gt('sessoes_restantes', 0);

      if (error) throw error;
      setPacientesPacotes(data || []);
    } catch (error) {
      console.error('Erro ao buscar pacotes do paciente:', error);
      setPacientesPacotes([]);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.paciente_id || !formData.profissional_id || !formData.servico_id || !formData.hora_inicio) {
      toast({
        title: "Campos obrigatórios",
        description: "Por favor, preencha todos os campos obrigatórios.",
        variant: "destructive"
      });
      return;
    }

    // Se há conflito e usuário não confirmou, alertar
    if (conflictWarning?.show && !forceCreate) {
      toast({
        title: "Conflito de horário",
        description: `Há uma sobreposição de ${conflictWarning.minutes} minutos. Clique em "Criar Mesmo Assim" para continuar.`,
        variant: "destructive"
      });
      return;
    }

    try {
      setIsLoading(true);

      const servico = servicos.find(s => s.id === formData.servico_id);
      if (!servico) throw new Error("Serviço não encontrado");

      const [hours, minutes] = formData.hora_inicio.split(':');
      const inicio = new Date(formData.data);
      inicio.setHours(parseInt(hours), parseInt(minutes), 0, 0);

      const fim = new Date(inicio);
      fim.setMinutes(inicio.getMinutes() + servico.duracao_minutos);

      // Buscar tenant_id do usuário logado
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error("Usuário não autenticado");

      const { data: profile } = await supabase
        .from('profiles')
        .select('tenant_id')
        .eq('id', user.id)
        .maybeSingle();

      if (!profile) {
        toast({ title: "Perfil não encontrado", description: "Conclua seu cadastro em Configurações.", variant: "destructive" });
        throw new Error("Perfil do usuário não encontrado");
      }
      if (!profile.tenant_id) {
        toast({ title: "Tenant não encontrado", description: "Associe seu perfil a uma clínica em Configurações.", variant: "destructive" });
        throw new Error("Tenant não encontrado");
      }

      // Buscar ordem máxima atual
      const { data: maxOrdem } = await supabase
        .from('agenda')
        .select('ordem')
        .eq('tenant_id', profile.tenant_id)
        .order('ordem', { ascending: false, nullsFirst: false })
        .limit(1)
        .maybeSingle();

      const novaOrdem = (maxOrdem?.ordem || 0) + 1;

      // Calcular Score de Risco de No-Show
      const riskAnalysis = await noShowModel.calcularScore({
        paciente_id: formData.paciente_id,
        data_agendamento: inicio,
        data_criacao: new Date(),
        origem: 'recepção', // ou pegar do contexto se for online
        servico_preco: servico.preco || 0
      });

      const { data: agendaData, error } = await supabase
        .from('agenda')
        .insert([{
          paciente_id: formData.paciente_id,
          profissional_id: formData.profissional_id,
          servico_id: formData.servico_id,
          especialidade_id: formData.especialidade_id || null,
          paciente_pacote_id: formData.paciente_pacote_id || null,
          inicio: inicio.toISOString(),
          fim: fim.toISOString(),
          sala: formData.sala || null,
          notas: formData.notas || null,
          status: 'agendado',
          tenant_id: profile.tenant_id,
          origem: 'recepção',
          ordem: novaOrdem,
          tipo_atendimento: formData.tipo_atendimento,
          plano_saude_id: formData.tipo_atendimento === 'plano' ? formData.plano_saude_id || null : null,
          valor_consulta: formData.valor_consulta ? parseFloat(formData.valor_consulta) : null,
          forma_pagamento_id: formData.tipo_atendimento === 'particular' ? formData.forma_pagamento_id || null : null,
          conta_pix_id: formData.conta_pix_id || null,
          no_show_score: riskAnalysis.score,
          no_show_risk_level: riskAnalysis.level
        }])
        .select()
        .single();

      if (error) throw error;

      // Se for atendimento particular com valor, criar lançamento no caixa
      if (formData.tipo_atendimento === 'particular' && formData.valor_consulta && agendaData) {
        await supabase.from('caixa_diario').insert({
          tenant_id: profile.tenant_id,
          agendamento_id: agendaData.id,
          paciente_id: formData.paciente_id,
          profissional_id: formData.profissional_id,
          data: format(formData.data, 'yyyy-MM-dd'),
          tipo_lancamento: 'entrada',
          valor: parseFloat(formData.valor_consulta),
          forma_pagamento: formasPagamento.find(f => f.id === formData.forma_pagamento_id)?.nome || 'Não especificado',
          conta_pix_id: formData.conta_pix_id || null,
          descricao: `Consulta - ${servico.nome}`,
          created_by: user.id
        });
      }

      toast({
        title: "Sucesso!",
        description: "Consulta cadastrada com sucesso."
      });

      // Trigger Automation
      const paciente = pacientes.find(p => p.id === formData.paciente_id);
      if (paciente && agendaData) {
        automationEngine.processarEventoAutomacao({
          tenant_id: profile.tenant_id,
          event_type: 'onAppointmentCreated',
          data: {
            agendamento: agendaData,
            paciente: paciente,
            servico: servico
          }
        }).catch(err => console.error("Erro ao disparar automação:", err));
      }

      // Resetar formulário
      setFormData({
        paciente_id: "",
        profissional_id: "",
        especialidade_id: "",
        servico_id: "",
        paciente_pacote_id: "",
        data: new Date(),
        hora_inicio: "",
        sala: "",
        notas: "",
        tipo_atendimento: "particular",
        plano_saude_id: "",
        valor_consulta: "",
        forma_pagamento_id: "",
        conta_pix_id: ""
      });

      // Fechar dialog e chamar callback com delay para evitar conflitos
      setOpen(false);
      setTimeout(() => {
        if (onSuccess) onSuccess();
      }, 150);
    } catch (error) {
      console.error('Erro ao cadastrar consulta:', error);
      toast({
        title: "Erro",
        description: "Não foi possível cadastrar a consulta.",
        variant: "destructive"
      });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        {children}
      </DialogTrigger>
      <DialogContent className="max-w-4xl max-h-[95vh] overflow-hidden flex flex-col">
        <DialogHeader className="flex-shrink-0">
          <DialogTitle className="text-xl">Nova Consulta</DialogTitle>
          <DialogDescription className="text-sm">Preencha os campos para agendar uma nova consulta.</DialogDescription>
        </DialogHeader>

        {isFetchingData ? (
          <div className="flex items-center justify-center py-8">
            <Loader2 className="h-8 w-8 animate-spin text-primary" />
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="space-y-4 flex-1 overflow-y-auto">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
              <div className="space-y-2">
                <div className="flex items-center justify-between">
                  <Label htmlFor="paciente">Paciente *</Label>
                  <NewPatientDialog onSuccess={(patientId) => {
                    fetchData();
                    setFormData({ ...formData, paciente_id: patientId });
                  }} />
                </div>
                <PatientCombobox
                  value={formData.paciente_id}
                  onValueChange={(value) => {
                    setFormData({ ...formData, paciente_id: value, paciente_pacote_id: "" });
                    fetchPacotesPaciente(value);
                  }}
                  patients={pacientes}
                />
              </div>

              <div className="space-y-2">
                <div className="flex items-center justify-between">
                  <Label htmlFor="profissional">Profissional *</Label>
                  <NewProfessionalDialog onSuccess={(professionalId) => {
                    fetchData();
                    setFormData({ ...formData, profissional_id: professionalId });
                  }} />
                </div>
                <ProfessionalCombobox
                  value={formData.profissional_id}
                  onValueChange={(value) => setFormData({ ...formData, profissional_id: value })}
                  professionals={profissionais}
                />
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
              <div className="space-y-1.5">
                <Label htmlFor="servico">Procedimento *</Label>
                <Select
                  value={formData.servico_id}
                  onValueChange={(value) => setFormData({ ...formData, servico_id: value })}
                >
                  <SelectTrigger id="servico">
                    <SelectValue placeholder="Selecione o procedimento" />
                  </SelectTrigger>
                  <SelectContent className="bg-background z-50">
                    {servicos.length === 0 ? (
                      <div className="p-2 text-sm text-muted-foreground text-center">
                        Nenhum procedimento cadastrado
                      </div>
                    ) : (
                      servicos.map((servico) => (
                        <SelectItem key={servico.id} value={servico.id}>
                          {servico.nome} - {servico.duracao_minutos}min
                          {servico.preco && ` - R$ ${servico.preco}`}
                        </SelectItem>
                      ))
                    )}
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-1.5">
                <Label htmlFor="pacote">Usar Pacote (Opcional)</Label>
                <Select
                  value={formData.paciente_pacote_id}
                  onValueChange={(value) => setFormData({ ...formData, paciente_pacote_id: value === "none" ? "" : value })}
                  disabled={!formData.paciente_id || pacientesPacotes.length === 0}
                >
                  <SelectTrigger id="pacote">
                    <SelectValue placeholder="Nenhum pacote" />
                  </SelectTrigger>
                  <SelectContent className="bg-background z-50">
                    <SelectItem value="none">Não usar pacote</SelectItem>
                    {pacientesPacotes.map((pp) => (
                      <SelectItem key={pp.id} value={pp.id}>
                        {pp.pacotes?.nome} ({pp.sessoes_restantes} sessões restantes)
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                {formData.paciente_id && pacientesPacotes.length === 0 && (
                  <p className="text-xs text-muted-foreground">
                    Paciente sem pacotes ativos
                  </p>
                )}
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
              <div className="space-y-1.5">
                <Label>Data *</Label>
                <Popover>
                  <PopoverTrigger asChild>
                    <Button
                      variant="outline"
                      className={cn(
                        "w-full justify-start text-left font-normal",
                        !formData.data && "text-muted-foreground"
                      )}
                    >
                      <CalendarIcon className="mr-2 h-4 w-4 flex-shrink-0" />
                      <span className="truncate">
                        {formData.data ? format(formData.data, "dd/MM/yyyy") : "Selecione a data"}
                      </span>
                    </Button>
                  </PopoverTrigger>
                  <PopoverContent className="w-auto p-0 bg-background z-50" align="start">
                    <Calendar
                      mode="single"
                      selected={formData.data}
                      onSelect={(date) => date && setFormData({ ...formData, data: date })}
                      initialFocus
                      locale={ptBR}
                      className={cn("p-3 pointer-events-auto")}
                    />
                  </PopoverContent>
                </Popover>
              </div>

              <div className="space-y-1.5">
                <Label htmlFor="hora_inicio">Horário *</Label>
                <Input
                  id="hora_inicio"
                  type="time"
                  value={formData.hora_inicio}
                  onChange={(e) => setFormData({ ...formData, hora_inicio: e.target.value })}
                  className="w-full"
                />
              </div>

              <div className="space-y-1.5">
                <Label htmlFor="sala">Sala/Consultório</Label>
                <Input
                  id="sala"
                  value={formData.sala}
                  onChange={(e) => setFormData({ ...formData, sala: e.target.value })}
                  placeholder="Ex: Consultório 1"
                  className="w-full"
                />
              </div>
            </div>

            {conflictWarning?.show && (
              <Alert variant="destructive" className="mt-4">
                <AlertTriangle className="h-4 w-4" />
                <AlertDescription>
                  <p className="font-semibold">Conflito de horário detectado!</p>
                  <p className="text-sm mt-1">
                    Há uma sobreposição de {conflictWarning.minutes} minutos com um agendamento anterior.
                    Você pode criar mesmo assim, mas recomendamos ajustar o horário.
                  </p>
                </AlertDescription>
              </Alert>
            )}

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1.5">
                <Label htmlFor="tipo_atendimento">Tipo de Atendimento *</Label>
                <Select
                  value={formData.tipo_atendimento}
                  onValueChange={(value: "plano" | "particular") => {
                    setFormData({ ...formData, tipo_atendimento: value, plano_saude_id: "", forma_pagamento_id: "", conta_pix_id: "" });
                  }}
                >
                  <SelectTrigger id="tipo_atendimento">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent className="bg-background z-50">
                    <SelectItem value="plano">Plano de Saúde</SelectItem>
                    <SelectItem value="particular">Particular</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-1.5">
                <Label htmlFor="valor_consulta">Valor da Consulta</Label>
                <Input
                  id="valor_consulta"
                  type="number"
                  step="0.01"
                  value={formData.valor_consulta}
                  onChange={(e) => setFormData({ ...formData, valor_consulta: e.target.value })}
                  placeholder="0.00"
                />
              </div>
            </div>

            {formData.tipo_atendimento === 'plano' && (
              <div className="space-y-1.5">
                <Label>Plano de Saúde *</Label>
                <Select
                  value={formData.plano_saude_id}
                  onValueChange={(value) => setFormData({ ...formData, plano_saude_id: value })}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Selecione o plano" />
                  </SelectTrigger>
                  <SelectContent className="bg-background z-50">
                    {planosSaude.map((plano) => (
                      <SelectItem key={plano.id} value={plano.id}>
                        {plano.nome}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            )}

            {formData.tipo_atendimento === 'particular' && (
              <>
                <div className="space-y-1.5">
                  <Label>Forma de Pagamento</Label>
                  <Select
                    value={formData.forma_pagamento_id}
                    onValueChange={(value) => {
                      setFormData({ ...formData, forma_pagamento_id: value });
                      const forma = formasPagamento.find(f => f.id === value);
                      if (forma?.tipo !== 'pix') {
                        setFormData(prev => ({ ...prev, conta_pix_id: "" }));
                      }
                    }}
                  >
                    <SelectTrigger>
                      <SelectValue placeholder="Selecione" />
                    </SelectTrigger>
                    <SelectContent className="bg-background z-50">
                      {formasPagamento.map((forma) => (
                        <SelectItem key={forma.id} value={forma.id}>
                          {forma.nome}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>

                {formasPagamento.find(f => f.id === formData.forma_pagamento_id)?.tipo === 'pix' && (
                  <div className="space-y-1.5">
                    <Label>Conta PIX</Label>
                    <Select
                      value={formData.conta_pix_id}
                      onValueChange={(value) => setFormData({ ...formData, conta_pix_id: value })}
                    >
                      <SelectTrigger>
                        <SelectValue placeholder="Selecione a conta PIX" />
                      </SelectTrigger>
                      <SelectContent className="bg-background z-50">
                        {contasPix.map((conta) => (
                          <SelectItem key={conta.id} value={conta.id}>
                            {conta.nome} - {conta.chave_pix}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                )}
              </>
            )}

            <div className="space-y-1.5">
              <Label htmlFor="notas">Observações</Label>
              <Textarea
                id="notas"
                value={formData.notas}
                onChange={(e) => setFormData({ ...formData, notas: e.target.value })}
                placeholder="Notas adicionais sobre a consulta..."
                rows={2}
                className="resize-none"
              />
            </div>

            <div className="flex justify-end gap-3 pt-2 flex-shrink-0 border-t mt-4">
              <Button
                type="button"
                variant="outline"
                onClick={() => setOpen(false)}
                disabled={isLoading}
              >
                Cancelar
              </Button>
              {conflictWarning?.show ? (
                <>
                  <Button
                    type="submit"
                    disabled={isLoading || !forceCreate}
                    variant="outline"
                  >
                    {isLoading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                    Cadastrar Consulta
                  </Button>
                  <Button
                    type="button"
                    variant="destructive"
                    onClick={() => {
                      setForceCreate(true);
                      setTimeout(() => {
                        const form = document.querySelector('form');
                        form?.requestSubmit();
                      }, 50);
                    }}
                    disabled={isLoading}
                  >
                    Criar Mesmo Assim
                  </Button>
                </>
              ) : (
                <Button type="submit" disabled={isLoading}>
                  {isLoading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                  Cadastrar Consulta
                </Button>
              )}
            </div>
          </form>
        )}
      </DialogContent>
    </Dialog>
  );
}

import React, { useState, useEffect, useRef } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger, DialogDescription } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { useToast } from "@/hooks/use-toast";
import { supabase } from "@/integrations/supabase/client";
import { Loader2, Plus } from "lucide-react";

interface NewEspecialidadeDialogProps {
  onSuccess?: (id: string) => void;
}

export function NewEspecialidadeDialog({ onSuccess }: NewEspecialidadeDialogProps) {
  const [open, setOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [formData, setFormData] = useState({
    nome: "",
    codigo_cfm: "",
    descricao: ""
  });
  const [hasChanges, setHasChanges] = useState(false);
  const nomeRef = useRef<HTMLInputElement>(null);

  const { toast } = useToast();

  useEffect(() => {
    setHasChanges(!!(formData.nome || formData.codigo_cfm || formData.descricao));
  }, [formData]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.nome.trim()) {
      toast({
        title: "Campo obrigatório não preenchido",
        description: "Por favor, preencha: Nome da especialidade",
        variant: "destructive"
      });
      nomeRef.current?.focus();
      return;
    }

    try {
      setIsLoading(true);

      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error("Usuário não autenticado");

      const { data: profile } = await supabase
        .from('profiles')
        .select('tenant_id')
        .eq('id', user.id)
        .maybeSingle();

      if (!profile || !profile.tenant_id) {
        throw new Error("Perfil não configurado. Configure seu perfil em Configurações.");
      }

      const { data, error } = await supabase
        .from('especialidades')
        .insert([{
          nome: formData.nome.trim(),
          codigo_cfm: formData.codigo_cfm.trim() || null,
          descricao: formData.descricao.trim() || null,
          tenant_id: profile.tenant_id,
          ativo: true
        }])
        .select()
        .single();

      if (error) {
        if (error.code === '23505') {
          throw new Error("Já existe uma especialidade com este nome");
        }
        throw error;
      }

      toast({
        title: "Sucesso!",
        description: "Especialidade cadastrada com sucesso."
      });

      setOpen(false);
      setFormData({ nome: "", codigo_cfm: "", descricao: "" });

      if (onSuccess && data) {
        onSuccess(data.id);
      }
    } catch (error) {
      console.error('Erro ao cadastrar:', error);
      const description = (error as any)?.message || "Não foi possível cadastrar a especialidade.";
      toast({
        title: "Erro",
        description,
        variant: "destructive"
      });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button>
          <Plus className="h-4 w-4 mr-2" />
          Nova Especialidade
        </Button>
      </DialogTrigger>
      <DialogContent className="max-w-lg">
        <DialogHeader>
          <DialogTitle className="text-xl">Cadastrar Nova Especialidade</DialogTitle>
          <DialogDescription>
            Cadastre uma especialidade médica reconhecida pelo CFM
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="nome">Nome da Especialidade *</Label>
            <Input
              id="nome"
              ref={nomeRef}
              value={formData.nome}
              onChange={(e) => setFormData({ ...formData, nome: e.target.value })}
              placeholder="Ex: Cardiologia, Pediatria, Ortopedia"
              required
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="codigo_cfm">Código CFM</Label>
            <Input
              id="codigo_cfm"
              value={formData.codigo_cfm}
              onChange={(e) => setFormData({ ...formData, codigo_cfm: e.target.value })}
              placeholder="Código de referência do CFM"
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="descricao">Descrição</Label>
            <Textarea
              id="descricao"
              value={formData.descricao}
              onChange={(e) => setFormData({ ...formData, descricao: e.target.value })}
              placeholder="Descrição sobre a especialidade..."
              rows={3}
            />
          </div>

          <div className="flex justify-end gap-3 pt-4">
            <Button
              type="button"
              variant="outline"
              onClick={() => setOpen(false)}
              disabled={isLoading}
            >
              Cancelar
            </Button>
            <Button type="submit" disabled={isLoading || !hasChanges}>
              {isLoading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Cadastrar
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

