              <Label htmlFor="telefone">Telefone *</Label>
              <Input
                id="telefone"
                ref={telefoneRef}
                value={formData.telefone}
                onChange={(e) => setFormData({ ...formData, telefone: e.target.value })}
                placeholder="(00) 00000-0000"
                required
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="email">E-mail</Label>
              <Input
                id="email"
                type="email"
                value={formData.email}
                onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                placeholder="email@exemplo.com"
              />
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="preferencia_contato">Preferência de Contato</Label>
            <Select
              value={formData.preferencia_contato}
              onValueChange={(value: "whatsapp" | "sms" | "email") => setFormData({ ...formData, preferencia_contato: value })}
            >
              <SelectTrigger id="preferencia_contato">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="whatsapp">WhatsApp</SelectItem>
                <SelectItem value="sms">SMS</SelectItem>
                <SelectItem value="email">E-mail</SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-2">
            <Label htmlFor="data_nascimento">Data de Nascimento</Label>
            <Popover>
              <PopoverTrigger asChild>
                <Button
                  variant="outline"
                  className={cn(
                    "w-full justify-start text-left font-normal",
                    !formData.data_nascimento && "text-muted-foreground"
                  )}
                >
                  <CalendarIcon className="mr-2 h-4 w-4" />
                  {formData.data_nascimento ? (
                    format(formData.data_nascimento, "dd 'de' MMMM 'de' yyyy", { locale: ptBR })
                  ) : (
                    <span>Selecione a data</span>
                  )}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0" align="start">
                <Calendar
                  mode="single"
                  selected={formData.data_nascimento}
                  onSelect={(date) => setFormData({ ...formData, data_nascimento: date })}
                  disabled={(date) =>
                    date > new Date() || date < new Date("1900-01-01")
                  }
                  initialFocus
                  className={cn("p-3 pointer-events-auto")}
                />
              </PopoverContent>
            </Popover>
          </div>

          <DynamicForm
            data={formData.custom_data}
            onChange={(key, value) => setFormData(prev => ({
              ...prev,
              custom_data: { ...prev.custom_data, [key]: value }
            }))}
          />

          <div className="flex items-center space-x-2">
            <Switch
              id="consentimento_lgpd"
              checked={formData.consentimento_lgpd}
              onCheckedChange={(checked) => setFormData({ ...formData, consentimento_lgpd: checked })}
            />
            <Label htmlFor="consentimento_lgpd" className="cursor-pointer">
              Consentimento LGPD obtido
            </Label>
          </div>

          <div className="space-y-2">
            <Label htmlFor="notas_internas">Observações Internas</Label>
            <Textarea
              id="notas_internas"
              value={formData.notas_internas}
              onChange={(e) => setFormData({ ...formData, notas_internas: e.target.value })}
              placeholder={`Anotações sobre o ${t.client_label.toLowerCase()}...`}
              rows={3}
            />
          </div>

          <div className="flex justify-end gap-3 pt-4">
            {hasChanges && (
              <Button
                type="button"
                variant="outline"
                onClick={() => {
                  const defaultData = {
                    nome: "",
                    telefone: "",
                    email: "",
                    preferencia_contato: "whatsapp" as "whatsapp" | "sms" | "email",
                    consentimento_lgpd: false,
                    notas_internas: "",
                    data_nascimento: undefined as Date | undefined,
                    plano_saude_id: "",
                    numero_carteirinha: "",
                    custom_data: {}
                  };
                  setFormData(defaultData);
                  setHasChanges(false);
                }}
                disabled={isLoading}
              >
                Cancelar Alterações
              </Button>
            )}
            <Button type="submit" disabled={isLoading || !hasChanges}>
              {isLoading ? (
                <>
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                  Cadastrando...
                </>
              ) : (
                `Cadastrar ${t.client_label}`
              )}
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger, DialogDescription } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { FlexibleDatePicker } from "@/components/ui/flexible-date-picker";
import { useToast } from "@/hooks/use-toast";
import { supabase } from "@/integrations/supabase/client";
import { Loader2, Plus, X } from "lucide-react";
import { format } from "date-fns";

interface NewProfessionalDialogProps {
  onSuccess?: (professionalId: string) => void;
}

export function NewProfessionalDialog({ onSuccess }: NewProfessionalDialogProps) {
  const [open, setOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [tiposProfissional, setTiposProfissional] = useState<any[]>([]);
  const [especialidades, setEspecialidades] = useState<any[]>([]);
  const [selectedEspecialidades, setSelectedEspecialidades] = useState<string[]>([]);
  const [formData, setFormData] = useState({
    nome: "",
    email: "",
    telefone: "",
    tipo_profissional_id: "",
    outro_especifique: "",
    data_nascimento: undefined as Date | undefined
  });

  const { toast } = useToast();

  useEffect(() => {
    if (open) {
      fetchTiposProfissional();
      fetchEspecialidades();
    }
  }, [open]);

  const fetchTiposProfissional = async () => {
    try {
      const { data, error } = await (supabase as any)
        .from("tipos_profissional")
        .select("*")
        .eq("ativo", true)
        .order("nome");

      if (error) throw error;
      setTiposProfissional(data || []);
    } catch (error) {
      console.error("Erro ao buscar tipos de profissional:", error);
    }
  };

  const fetchEspecialidades = async () => {
    try {
      const { data, error } = await supabase
        .from('especialidades')
        .select('id, nome, conselho')
        .eq('ativo', true)
        .order('nome');

      if (error) throw error;
      setEspecialidades(data || []);
    } catch (error) {
      console.error('Erro ao buscar especialidades:', error);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.nome || !formData.email) {
      toast({
        title: "Campos obrigatórios",
        description: "Nome e e-mail são obrigatórios.",
        variant: "destructive"
      });
      return;
    }

    if (formData.tipo_profissional_id === "outro" && !formData.outro_especifique) {
      toast({
        title: "Campos obrigatórios",
        description: "Por favor, especifique o tipo de profissional.",
        variant: "destructive"
      });
      return;
    }

    try {
      setIsLoading(true);

      // Buscar tenant_id do usuário logado
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error("Usuário não autenticado");

      const { data: profile } = await supabase
        .from('profiles')
        .select('tenant_id')
        .eq('id', user.id)
        .maybeSingle();

      if (!profile) throw new Error("Perfil do usuário não encontrado. Conclua seu cadastro em Configurações.");
      if (!profile.tenant_id) throw new Error("Tenant não encontrado. Associe seu perfil a uma clínica em Configurações.");

      // Criar usuário no auth (senha temporária será enviada por email)
      const tempPassword = Math.random().toString(36).slice(-12) + "A1!";

      const { data: authData, error: authError } = await supabase.functions.invoke('create-user', {
        body: {
          email: formData.email,
          password: tempPassword,
          userData: {
            nome: formData.nome,
            telefone: formData.telefone
          }
        }
      });

      if (authError) throw new Error(authError.message || "Erro ao chamar função de criação de usuário");
      if (authData.error) throw new Error(authData.error);
      if (!authData.user) throw new Error("Erro ao criar usuário");

      // Validar e formatar data de nascimento
      let dataNascimentoFormatada = null;
      if (formData.data_nascimento instanceof Date && !isNaN(formData.data_nascimento.getTime())) {
        dataNascimentoFormatada = format(formData.data_nascimento, 'yyyy-MM-dd');
      }

      // Atualizar perfil com role profissional
      const { error: updateError } = await (supabase as any)
        .from('profiles')
        .update({
          nome: formData.nome,
          telefone: formData.telefone || null,
          role: 'profissional',
          tenant_id: profile.tenant_id,
          tipo_profissional_id: formData.tipo_profissional_id || null,
          data_nascimento: dataNascimentoFormatada
        })
        .eq('id', authData.user.id);

      if (updateError) throw updateError;

      // Inserir especialidades
      if (selectedEspecialidades.length > 0) {
        const { error: espError } = await (supabase as any)
          .from('profissional_especialidades')
          .insert(
            selectedEspecialidades.map(esp_id => ({
              tenant_id: profile.tenant_id,
              profissional_id: authData.user.id,
              especialidade_id: esp_id
            }))
          );

        if (espError) throw espError;
      }

      toast({
        title: "Sucesso!",
        description: "Profissional cadastrado com sucesso. Um e-mail de confirmação foi enviado."
      });

      setOpen(false);
      setFormData({
        nome: "",
        email: "",
        telefone: "",
        tipo_profissional_id: "",
        outro_especifique: "",
        data_nascimento: undefined
      });
      setSelectedEspecialidades([]);

      if (onSuccess && authData.user) {
        onSuccess(authData.user.id);
      }
    } catch (error: any) {
      console.error('Erro ao cadastrar profissional:', error);

      let errorMessage = "Não foi possível cadastrar o profissional.";
      if (error.message?.includes("already registered")) {
        errorMessage = "Este e-mail já está cadastrado no sistema.";
      }

      toast({
        title: "Erro",
        description: errorMessage,
        variant: "destructive"
      });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button type="button">
          <Plus className="h-4 w-4 mr-2" />
          Novo Profissional
        </Button>
      </DialogTrigger>
      <DialogContent className="max-w-lg">
        <DialogHeader>
          <DialogTitle className="text-xl">Cadastrar Novo Profissional</DialogTitle>
          <DialogDescription>Informe os dados do profissional. Um e-mail de confirmação será enviado.</DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="prof_nome">Nome Completo *</Label>
            <Input
              id="prof_nome"
              value={formData.nome}
              onChange={(e) => setFormData({ ...formData, nome: e.target.value })}
              placeholder="Nome do profissional"
              required
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="prof_email">E-mail *</Label>
            <Input
              id="prof_email"
              type="email"
              value={formData.email}
              onChange={(e) => setFormData({ ...formData, email: e.target.value })}
              placeholder="email@exemplo.com"
              required
            />
            <p className="text-xs text-muted-foreground">
              Um e-mail de confirmação será enviado para este endereço
            </p>
          </div>

          <div className="space-y-2">
            <Label htmlFor="prof_telefone">Telefone</Label>
            <Input
              id="prof_telefone"
              value={formData.telefone}
              onChange={(e) => setFormData({ ...formData, telefone: e.target.value })}
              placeholder="(11) 99999-9999"
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="tipo">Tipo de Profissional</Label>
            <Select
              value={formData.tipo_profissional_id}
              onValueChange={(value) => setFormData({ ...formData, tipo_profissional_id: value, outro_especifique: value === "outro" ? formData.outro_especifique : "" })}
            >
              <SelectTrigger>
                <SelectValue placeholder="Selecione o tipo" />
              </SelectTrigger>
              <SelectContent>
                {tiposProfissional.map((tipo) => (
                  <SelectItem key={tipo.id} value={tipo.id}>
                    {tipo.nome}
                  </SelectItem>
                ))}
                <SelectItem value="outro">Outro</SelectItem>
              </SelectContent>
            </Select>
          </div>

          {formData.tipo_profissional_id === "outro" && (
            <div className="space-y-2">
              <Label htmlFor="outro_especifique">Especifique *</Label>
              <Input
                id="outro_especifique"
                value={formData.outro_especifique}
                onChange={(e) => setFormData({ ...formData, outro_especifique: e.target.value })}
                placeholder="Especifique o tipo de profissional"
                required
              />
            </div>
          )}

          <div className="space-y-2">
            <Label>Especialidades</Label>
            <Select
              value=""
              onValueChange={(value) => {
                if (!selectedEspecialidades.includes(value)) {
                  setSelectedEspecialidades([...selectedEspecialidades, value]);
                }
              }}
            >
              <SelectTrigger>
                <SelectValue placeholder="Adicionar especialidade" />
              </SelectTrigger>
              <SelectContent>
                {especialidades
                  .filter(esp => !selectedEspecialidades.includes(esp.id))
                  .map((esp) => (
                    <SelectItem key={esp.id} value={esp.id}>
                      {esp.nome} {esp.conselho && `(${esp.conselho})`}
                    </SelectItem>
                  ))}
              </SelectContent>
            </Select>
            <div className="flex flex-wrap gap-2 mt-2">
              {selectedEspecialidades.map(espId => {
                const esp = especialidades.find(e => e.id === espId);
                return esp ? (
                  <Badge key={espId} variant="secondary" className="gap-1">
                    {esp.nome}
                    <X
                      className="h-3 w-3 cursor-pointer"
                      onClick={() => setSelectedEspecialidades(
                        selectedEspecialidades.filter(id => id !== espId)
                      )}
                    />
                  </Badge>
                ) : null;
              })}
            </div>
          </div>

          <FlexibleDatePicker
            label="Data de Nascimento"
            value={formData.data_nascimento}
            onChange={(date) => setFormData({ ...formData, data_nascimento: date })}
          />

          <div className="flex justify-end gap-3 pt-4">
            <Button
              type="button"
              variant="outline"
              onClick={() => setOpen(false)}
              disabled={isLoading}
            >
              Cancelar
            </Button>
            <Button type="submit" disabled={isLoading}>
              {isLoading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Cadastrar
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState, useEffect, useRef } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger, DialogDescription } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Switch } from "@/components/ui/switch";
import { useToast } from "@/hooks/use-toast";
import { supabase } from "@/integrations/supabase/client";
import { Loader2, Plus } from "lucide-react";

interface NewServiceDialogProps {
  onSuccess?: (serviceId: string) => void;
}

export function NewServiceDialog({ onSuccess }: NewServiceDialogProps) {
  const [open, setOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [formData, setFormData] = useState({
    nome: "",
    duracao_minutos: "",
    preco: "",
    confirmacao_24h: false,
    ativo: true
  });
  const [hasChanges, setHasChanges] = useState(false);
  const nomeRef = useRef<HTMLInputElement>(null);
  const duracaoRef = useRef<HTMLInputElement>(null);

  const { toast } = useToast();

  useEffect(() => {
    setHasChanges(!!(formData.nome || formData.duracao_minutos || formData.preco));
  }, [formData]);

  // Lista de palavras-chave para validar se é atividade médica/exame
  const medicalKeywords = [
    'consulta', 'exame', 'cirurgia', 'procedimento', 'avaliação', 'tratamento',
    'raio-x', 'ultrassom', 'tomografia', 'ressonância', 'endoscopia', 'colonoscopia',
    'eletrocardiograma', 'hemograma', 'check-up', 'retorno', 'acompanhamento',
    'fisioterapia', 'terapia', 'sessão', 'aplicação', 'vacina', 'curativo',
    'biópsia', 'ecografia', 'audiometria', 'espirometria', 'holter', 'mapa'
  ];

  const validateMedicalService = (serviceName: string): boolean => {
    const nameLower = serviceName.toLowerCase().trim();
    return medicalKeywords.some(keyword => nameLower.includes(keyword));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    const missingFields: string[] = [];
    if (!formData.nome.trim()) missingFields.push("Nome");
    if (!formData.duracao_minutos) missingFields.push("Duração");

    if (missingFields.length > 0) {
      toast({
        title: "Campos obrigatórios não preenchidos",
        description: `Por favor, preencha: ${missingFields.join(", ")}`,
        variant: "destructive"
      });

      if (!formData.nome.trim()) nomeRef.current?.focus();
      else if (!formData.duracao_minutos) duracaoRef.current?.focus();

      return;
    }

    // Validar se é atividade médica
    if (!validateMedicalService(formData.nome)) {
      toast({
        title: "Serviço inválido",
        description: "Por favor, cadastre apenas atividades médicas, procedimentos ou exames. Ex: Consulta, Depilação a Laser, Exame de Sangue, Ultrassom, etc.",
        variant: "destructive"
      });
      nomeRef.current?.focus();
      return;
    }

    const duracao = parseInt(formData.duracao_minutos);
    if (isNaN(duracao) || duracao <= 0 || duracao > 480) {
      toast({
        title: "Duração inválida",
        description: "A duração deve ser entre 1 e 480 minutos (8 horas).",
        variant: "destructive"
      });
      return;
    }

    const preco = formData.preco ? parseFloat(formData.preco) : null;
    if (preco !== null && (isNaN(preco) || preco < 0)) {
      toast({
        title: "Preço inválido",
        description: "O preço deve ser um valor positivo.",
        variant: "destructive"
      });
      return;
    }

    try {
      setIsLoading(true);

      // Buscar tenant_id do usuário logado
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error("Usuário não autenticado");

      const { data: profile } = await supabase
        .from('profiles')
        .select('tenant_id')
        .eq('id', user.id)
        .maybeSingle();

      if (!profile) throw new Error("Perfil do usuário não encontrado. Conclua seu cadastro em Configurações.");
      if (!profile.tenant_id) throw new Error("Tenant não encontrado. Associe seu perfil a uma clínica em Configurações.");

      const { data, error } = await supabase
        .from('servicos')
        .insert([{
          nome: formData.nome.trim(),
          duracao_minutos: duracao,
          preco: preco,
          confirmacao_24h: formData.confirmacao_24h,
          ativo: formData.ativo,
          tenant_id: profile.tenant_id
        }])
        .select()
        .single();

      if (error) {
        if (error.code === '23505') {
          throw new Error("Já existe um serviço com este nome");
        }
        throw error;
      }

      toast({
        title: "Sucesso!",
        description: "Serviço cadastrado com sucesso."
      });

      setOpen(false);
      setFormData({
        nome: "",
        duracao_minutos: "",
        preco: "",
        confirmacao_24h: false,
        ativo: true
      });

      if (onSuccess && data) {
        onSuccess(data.id);
      }
    } catch (error) {
      console.error('Erro ao cadastrar serviço:', error);
      const description = (error as any)?.message || "Não foi possível cadastrar o serviço.";
      toast({
        title: "Erro",
        description,
        variant: "destructive"
      });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button>
          <Plus className="h-4 w-4 mr-2" />
          Novo Serviço
        </Button>
      </DialogTrigger>
      <DialogContent className="max-w-lg">
        <DialogHeader>
          <DialogTitle className="text-xl">Cadastrar Novo Serviço</DialogTitle>
          <DialogDescription>
            Cadastre atividades médicas, procediementos e exames (ex: Consulta, Ultrassom, Exame de sangue)
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="nome">Nome do Serviço/Exame *</Label>
            <Input
              id="nome"
              ref={nomeRef}
              value={formData.nome}
              onChange={(e) => setFormData({ ...formData, nome: e.target.value })}
              placeholder="Ex: Consulta médica, Ultrassom, Exame de sangue"
              required
            />
            <p className="text-xs text-muted-foreground">
              Apenas atividades médicas, estéticas e exames serão aceitos
            </p>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="duracao">Duração (minutos) *</Label>
              <Input
                id="duracao"
                ref={duracaoRef}
                type="number"
                min="1"
                max="480"
                value={formData.duracao_minutos}
                onChange={(e) => setFormData({ ...formData, duracao_minutos: e.target.value })}
                placeholder="30"
                required
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="preco">Preço (R$)</Label>
              <Input
                id="preco"
                type="number"
                step="0.01"
                min="0"
                value={formData.preco}
                onChange={(e) => setFormData({ ...formData, preco: e.target.value })}
                placeholder="150.00"
              />
            </div>
          </div>

          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <Label htmlFor="confirmacao_24h">Confirmação 24h antes</Label>
                <p className="text-xs text-muted-foreground">
                  Enviar confirmação automática 24h antes
                </p>
              </div>
              <Switch
                id="confirmacao_24h"
                checked={formData.confirmacao_24h}
                onCheckedChange={(checked) => setFormData({ ...formData, confirmacao_24h: checked })}
              />
            </div>

            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <Label htmlFor="ativo">Serviço ativo</Label>
                <p className="text-xs text-muted-foreground">
                  Disponível para agendamento
                </p>
              </div>
              <Switch
                id="ativo"
                checked={formData.ativo}
                onCheckedChange={(checked) => setFormData({ ...formData, ativo: checked })}
              />
            </div>
          </div>

          <div className="flex justify-end gap-3 pt-4">
            <Button
              type="button"
              variant="outline"
              onClick={() => setOpen(false)}
              disabled={isLoading}
            >
              Cancelar
            </Button>
            <Button type="submit" disabled={isLoading || !hasChanges}>
              {isLoading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Cadastrar
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import { useState } from 'react';
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import { useToast } from "@/components/ui/use-toast";
import { supabase } from "@/integrations/supabase/client";
import { UserRole } from "@/utils/rbac";
import { useAuth } from "@/hooks/useAuth";
import { seatManager } from "@/domain/billing/seatManager";

export function InviteMember() {
    const [email, setEmail] = useState("");
    const [role, setRole] = useState<UserRole>("receptionist");
    const [loading, setLoading] = useState(false);
    const { toast } = useToast();
    const { profile } = useAuth();

    const handleInvite = async () => {
        setLoading(true);
        try {
            // 1. Check if user exists (optional, or handled by Supabase Auth invite)
            // For this MVP, we'll assume we are creating a profile or invitation record.
            // In a real app, use supabase.auth.admin.inviteUserByEmail (requires service role)
            // or a dedicated Edge Function.

            // We will call a hypothetical edge function 'invite-user'
            const { error } = await supabase.functions.invoke('invite-user', {
                body: { email, role }
            });

            if (error) throw error;

            // Recalcular seats após convite (assumindo que convite ocupa seat)
            if (profile?.tenant_id) {
                // Não bloqueia a UI, mas garante atualização
                seatManager.onProfessionalCreated(profile.tenant_id).catch(console.error);
            }

            toast({
                title: "Convite enviado!",
                description: `Um convite foi enviado para ${email} com o perfil de ${role}.`,
            });
            setEmail("");
        } catch (error: any) {
            console.error("Erro ao convidar:", error);
            toast({
                title: "Erro ao enviar convite",
                description: error.message || "Tente novamente mais tarde.",
                variant: "destructive"
            });
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="flex flex-col gap-4 p-4 border rounded-lg">
            <h3 className="text-lg font-semibold">Convidar Membro da Equipe</h3>
            <div className="flex gap-2">
                <Input
                    placeholder="Email do colaborador"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                />
                <Select value={role} onValueChange={(v) => setRole(v as UserRole)}>
                    <SelectTrigger className="w-[180px]">
                        <SelectValue placeholder="Função" />
                    </SelectTrigger>
                    <SelectContent>
                        <SelectItem value="receptionist">Recepcionista</SelectItem>
                        <SelectItem value="professional">Profissional</SelectItem>
                        <SelectItem value="manager">Gerente</SelectItem>
                    </SelectContent>
                </Select>
                <Button onClick={handleInvite} disabled={loading}>
                    {loading ? "Enviando..." : "Convidar"}
                </Button>
            </div>
        </div>
    );
}

import React, { useState, useEffect, useRef } from 'react';
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { MessageCircle, X, Send, Loader2, User, Mail, Bot, Trash2 } from "lucide-react";
import { useAuth } from "@/hooks/useAuth";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";

interface Message {
    id: string;
    content: string;
    sender: 'user' | 'agent' | 'system' | 'bot';
    created_at: string;
}

export function SupportChatWidget() {
    const { user, profile } = useAuth();
    const [isOpen, setIsOpen] = useState(false);
    const [step, setStep] = useState<'initial' | 'chat'>('initial');
    const [ticketId, setTicketId] = useState<string | null>(null);
    const [messages, setMessages] = useState<Message[]>([]);
    const [newMessage, setNewMessage] = useState('');
    const [loading, setLoading] = useState(false);
    const [isOnline, setIsOnline] = useState(true);
    const [checkingStatus, setCheckingStatus] = useState(true);

    // Guest form
    const [guestName, setGuestName] = useState('');
    const [guestEmail, setGuestEmail] = useState('');

    const scrollRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        checkSupportStatus();
        const interval = setInterval(checkSupportStatus, 60000); // Check every minute
        return () => clearInterval(interval);
    }, []);

    useEffect(() => {
        if (isOpen && user) {
            setStep('chat');
            // Optionally load active ticket for user
            checkActiveTicket();
        } else if (isOpen) {
            // Check local storage for guest ticket
            const savedTicket = localStorage.getItem('cleanflow_guest_ticket');
            if (savedTicket) {
                setTicketId(savedTicket);
                setStep('chat');
                loadMessages(savedTicket);
            }
        }
    }, [isOpen, user]);

    useEffect(() => {
        if (scrollRef.current) {
            scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
        }
    }, [messages]);

    const checkSupportStatus = async () => {
        try {
            const now = new Date();
            const dayOfWeek = now.getDay(); // 0 = Sunday
            const timeString = now.toTimeString().slice(0, 5); // HH:MM
            const dateString = now.toISOString().split('T')[0]; // YYYY-MM-DD

            // Check holidays
            const { data: holiday } = await (supabase as any)
                .from('support_holidays')
                .select('id')
                .eq('date', dateString)
                .maybeSingle();

            if (holiday) {
                setIsOnline(false);
                setCheckingStatus(false);
                return;
            }

            // Check operating hours
            const { data: hours } = await (supabase as any)
                .from('support_operating_hours')
                .select('*')
                .eq('day_of_week', dayOfWeek)
                .eq('is_active', true)
                .maybeSingle();

            if (hours) {
                const start = hours.start_time.slice(0, 5);
                const end = hours.end_time.slice(0, 5);
                setIsOnline(timeString >= start && timeString <= end);
            } else {
                setIsOnline(false);
            }
        } catch (error) {
            console.error('Error checking status:', error);
            // Default to online if error to not block support
            setIsOnline(true);
        } finally {
            setCheckingStatus(false);
        }
    };

    const checkActiveTicket = async () => {
        if (!user) return;
        // Find most recent open ticket
        const { data } = await supabase
            .from('support_tickets')
            .select('id')
            .eq('user_id', user.id)
            .neq('status', 'closed')
            .neq('status', 'resolved')
            .order('created_at', { ascending: false })
            .limit(1)
            .maybeSingle();

        if (data) {
            setTicketId(data.id);
            loadMessages(data.id);
        }
    };

    const loadMessages = async (tid: string) => {
        const { data } = await supabase
            .from('support_ticket_messages')
            .select('*')
            .eq('ticket_id', tid)
            .order('created_at', { ascending: true });

        if (data) {
            setMessages(data.map((m: any) => ({
                id: m.id,
                content: m.mensagem,
                sender: m.sender_type === 'agent' ? 'agent' : m.sender_type === 'bot' ? 'bot' : 'user',
                created_at: m.created_at
            })));
        }
    };

    const handleStartChat = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);

        try {
            let ticket;

            if (user) {
                // Logged in user - use direct insert
                const { data, error } = await (supabase as any)
                    .from('support_tickets')
                    .insert({
                        title: 'Chat Support',
                        description: 'Chat started via widget',
                        status: 'open',
                        priority: 'medium',
                        origem: 'widget',
                        user_id: user.id,
                        tenant_id: profile?.tenant_id || null
                    })
                    .select()
                    .single();

                if (error) throw error;
                ticket = data;
            } else {
                // Guest - use RPC to bypass RLS select issues
                const { data, error } = await supabase
                    .rpc('create_guest_ticket', {
                        p_name: guestName,
                        p_email: guestEmail,
                        p_title: 'Chat Support (Guest)',
                        p_description: 'Chat started via widget'
                    });

                if (error) throw error;
                // RPC returns jsonb, so we cast it
                ticket = data as any;
            }

            setTicketId(ticket.id);
            if (!user) {
                localStorage.setItem('cleanflow_guest_ticket', ticket.id);
            }

            const protocol = ticket.id.slice(0, 8).toUpperCase();

            const hour = new Date().getHours();
            let greeting = 'Olá';
            if (hour < 12) greeting = 'Bom dia';
            else if (hour < 18) greeting = 'Boa tarde';
            else greeting = 'Boa noite';

            const welcomeMsg = isOnline
                ? `${greeting}, ${user ? profile?.nome : guestName}! Sou o assistente virtual do CleanFlow. Seu protocolo de atendimento é #${protocol}. Como posso ajudar você hoje?`
                : `${greeting}, ${user ? profile?.nome : guestName}. Sou o assistente virtual do CleanFlow. Seu protocolo de atendimento é #${protocol}. Estamos fora do horário de atendimento no momento, mas posso tentar tirar suas dúvidas!`;

            // Save welcome message to database
            await supabase
                .from('support_ticket_messages')
                .insert({
                    ticket_id: ticket.id,
                    mensagem: welcomeMsg,
                    sender_type: 'bot'
                });

            // Add welcome message to state
            setMessages([{
                id: 'welcome',
                content: welcomeMsg,
                sender: 'bot',
                created_at: new Date().toISOString()
            }]);

            setStep('chat');
        } catch (error) {
            console.error(error);
            toast.error('Erro ao iniciar chat');
        } finally {
            setLoading(false);
        }
    };

    const handleSendMessage = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!newMessage.trim() || !ticketId) return;

        const msgContent = newMessage;
        setNewMessage('');

        // Optimistic update
        const tempId = Math.random().toString();
        setMessages(prev => [...prev, {
            id: tempId,
            content: msgContent,
            sender: 'user',
            created_at: new Date().toISOString()
        }]);

        try {
            // Save user message
            await supabase
                .from('support_ticket_messages')
                .insert({
                    ticket_id: ticketId,
                    mensagem: msgContent,
                    user_id: user?.id || null,
                    sender_type: 'user'
                });

            // Try bot response
            const { data: botResponse } = await (supabase as any)
                .rpc('search_knowledge_base', { search_query: msgContent });

            const threshold = 0.6; // Stricter threshold

            if (botResponse && botResponse.length > 0 && botResponse[0].similarity > threshold) {
                const answer = botResponse[0].answer;

                // Add bot delay for realism
                setTimeout(async () => {
                    setMessages(prev => [...prev, {
                        id: Math.random().toString(),
                        content: answer,
                        sender: 'bot',
                        created_at: new Date().toISOString()
                    }]);

                    await supabase
                        .from('support_ticket_messages')
                        .insert({
                            ticket_id: ticketId,
                            mensagem: answer,
                            sender_type: 'bot'
                        });
                }, 1000);
            } else {
                // Fallback: Bot doesn't know
                // 1. Log for training
                await (supabase as any).rpc('log_unanswered_question', {
                    p_question: msgContent,
                    p_ticket_id: ticketId
                });

                const fallbackMsg = "Desculpe, não consegui encontrar uma resposta precisa para sua dúvida. \n\nO assunto exige intervenção humana. Um ticket de atendimento foi aberto e nossa equipe de suporte retornará via e-mail em breve.";
                const followUpMsg = "Agradecemos pelo contato! Continuo à disposição caso precise de ajuda com outros assuntos.";

                setTimeout(async () => {
                    // First message
                    setMessages(prev => [...prev, {
                        id: Math.random().toString(),
                        content: fallbackMsg,
                        sender: 'bot',
                        created_at: new Date().toISOString()
                    }]);

                    await supabase
                        .from('support_ticket_messages')
                        .insert({
                            ticket_id: ticketId,
                            mensagem: fallbackMsg,
                            sender_type: 'bot'
                        });

                    // Second message (Follow up)
                    setTimeout(async () => {
                        setMessages(prev => [...prev, {
                            id: Math.random().toString(),
                            content: followUpMsg,
                            sender: 'bot',
                            created_at: new Date().toISOString()
                        }]);

                        await supabase
                            .from('support_ticket_messages')
                            .insert({
                                ticket_id: ticketId,
                                mensagem: followUpMsg,
                                sender_type: 'bot'
                            });
                    }, 1500);

                }, 1000);
            }

        } catch (error) {
            console.error(error);
            toast.error('Erro ao enviar mensagem');
        }
    };

    const handleReset = () => {
        setTicketId(null);
        setMessages([]);
        setStep('initial');
        localStorage.removeItem('cleanflow_guest_ticket');
    };

    return (
        <div className="fixed bottom-6 right-6 z-[100] flex flex-col items-end gap-4">
            {isOpen && (
                <Card className="w-[350px] h-[500px] shadow-2xl border-blue-500/20 flex flex-col overflow-hidden animate-in slide-in-from-bottom-10 fade-in duration-300">
                    <CardHeader className={`p-4 shrink-0 flex flex-row items-center justify-between transition-colors ${isOnline ? 'bg-gradient-to-r from-blue-600 to-cyan-600' : 'bg-slate-700'
                        } text-white`}>
                        <div>
                            <CardTitle className="text-base flex items-center gap-2">
                                <MessageCircle className="h-5 w-5" />
                                Suporte CleanFlow
                            </CardTitle>
                            <div className="flex items-center gap-2 mt-1">
                                <span className={`w-2 h-2 rounded-full ${isOnline ? 'bg-green-400 animate-pulse' : 'bg-red-400'}`} />
                                <p className="text-xs text-blue-100 opacity-90">
                                    {checkingStatus ? 'Verificando...' : isOnline ? 'Online agora' : 'Fora do horário'}
                                </p>
                            </div>
                        </div>
                        <div className="flex gap-1">
                            {step === 'chat' && (
                                <Button variant="ghost" size="icon" className="text-white hover:bg-white/20 h-8 w-8" onClick={handleReset} title="Nova Conversa">
                                    <Trash2 className="h-4 w-4" />
                                </Button>
                            )}
                            <Button variant="ghost" size="icon" className="text-white hover:bg-white/20 h-8 w-8" onClick={() => setIsOpen(false)}>
                                <X className="h-4 w-4" />
                            </Button>
                        </div>
                    </CardHeader>

                    <CardContent className="flex-1 p-0 flex flex-col overflow-hidden bg-slate-50 dark:bg-slate-900">
                        {step === 'initial' ? (
                            <div className="p-6 flex flex-col h-full justify-center space-y-6">
                                <div className="text-center space-y-2">
                                    <div className="w-12 h-12 bg-blue-100 dark:bg-blue-900/30 rounded-full flex items-center justify-center mx-auto text-blue-600">
                                        <MessageCircle className="h-6 w-6" />
                                    </div>
                                    <h3 className="font-semibold">Olá! Como podemos te chamar?</h3>
                                    <p className="text-sm text-muted-foreground">Preencha seus dados para iniciarmos o atendimento.</p>
                                </div>

                                <form onSubmit={handleStartChat} className="space-y-4">
                                    <div className="space-y-2">
                                        <div className="relative">
                                            <User className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
                                            <Input
                                                placeholder="Seu nome"
                                                className="pl-9"
                                                value={guestName}
                                                onChange={e => setGuestName(e.target.value)}
                                                required
                                            />
                                        </div>
                                        <div className="relative">
                                            <Mail className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
                                            <Input
                                                type="email"
                                                placeholder="Seu e-mail"
                                                className="pl-9"
                                                value={guestEmail}
                                                onChange={e => setGuestEmail(e.target.value)}
                                                required
                                            />
                                        </div>
                                    </div>
                                    <Button type="submit" className="w-full bg-blue-600 hover:bg-blue-700" disabled={loading}>
                                        {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : 'Iniciar Chat'}
                                    </Button>
                                </form>
                            </div>
                        ) : (
                            <>
                                <div className="flex-1 overflow-y-auto p-4 space-y-4" ref={scrollRef}>
                                    {messages.map((msg) => (
                                        <div key={msg.id} className={`flex ${msg.sender === 'user' ? 'justify-end' : 'justify-start'} `}>
                                            <div className={`flex flex-col gap-1 max-w-[80%]`}>
                                                {msg.sender === 'bot' && (
                                                    <span className="text-xs text-muted-foreground flex items-center gap-1">
                                                        <Bot className="h-3 w-3" /> CleanBot
                                                    </span>
                                                )}
                                                <div className={`rounded-2xl px-4 py-2 text-xs ${msg.sender === 'user'
                                                    ? 'bg-blue-600 text-white rounded-tr-none'
                                                    : msg.sender === 'bot'
                                                        ? 'bg-purple-100 dark:bg-purple-900/30 text-purple-900 dark:text-purple-100 rounded-tl-none border border-purple-200 dark:border-purple-800'
                                                        : 'bg-slate-200 dark:bg-slate-800 text-slate-900 dark:text-slate-100 rounded-tl-none'
                                                    }`}>
                                                    {msg.content}
                                                </div>
                                            </div>
                                        </div>
                                    ))}
                                    {messages.length === 0 && (
                                        <div className="text-center text-muted-foreground text-xs py-8">
                                            Nenhuma mensagem ainda.
                                        </div>
                                    )}
                                </div>
                                <div className="p-3 border-t bg-white dark:bg-slate-950">
                                    <form onSubmit={handleSendMessage} className="flex gap-2">
                                        <Input
                                            value={newMessage}
                                            onChange={e => setNewMessage(e.target.value)}
                                            placeholder="Digite sua mensagem..."
                                            className="flex-1 text-xs"
                                        />
                                        <Button type="submit" size="icon" disabled={!newMessage.trim()}>
                                            <Send className="h-4 w-4" />
                                        </Button>
                                    </form>
                                </div>
                            </>
                        )}
                    </CardContent>
                </Card>
            )}

            <button
                onClick={() => setIsOpen(!isOpen)}
                className="w-16 h-16 bg-green-500 hover:bg-green-600 rounded-full shadow-2xl flex items-center justify-center transition-all hover:scale-110 group relative z-[100]"
                aria-label="Abrir chat de suporte"
            >
                {/* Animação de pulso (Halo) */}
                <span className="absolute inset-0 rounded-full bg-green-500 animate-ping opacity-20" />

                {isOpen ? (
                    <X className="h-8 w-8 text-white relative z-10" />
                ) : (
                    <MessageCircle className="h-8 w-8 text-white relative z-10" />
                )}

                {/* Status indicator dot (optional, keeping it small if needed, or relying on the green button) */}
                {isOnline && (
                    <span className="absolute top-0 right-0 w-4 h-4 bg-green-400 border-2 border-white rounded-full z-20" />
                )}
            </button>
        </div>
    );
}

import React, { createContext, useContext, useEffect, useState } from 'react';

type Theme = 'light' | 'dark';

interface ThemeProviderProps {
  children: React.ReactNode;
  defaultTheme?: Theme;
  storageKey?: string;
}

interface ThemeProviderState {
  theme: Theme;
  setTheme: (theme: Theme) => void;
  toggleTheme: () => void;
}

const initialState: ThemeProviderState = {
  theme: 'light',
  setTheme: () => null,
  toggleTheme: () => null,
};

const ThemeProviderContext = createContext<ThemeProviderState>(initialState);

export function ThemeProvider({
  children,
  defaultTheme = 'light',
  storageKey = 'cleanflow-ui-theme',
  ...props
}: ThemeProviderProps) {
  const [theme, setTheme] = useState<Theme>(
    () => (localStorage.getItem(storageKey) as Theme) || defaultTheme
  );

  useEffect(() => {
    const root = window.document.documentElement;
    root.classList.remove('light', 'dark');
    root.classList.add(theme);
  }, [theme]);

  const value = {
    theme,
    setTheme: (theme: Theme) => {
      localStorage.setItem(storageKey, theme);
      setTheme(theme);
    },
    toggleTheme: () => {
      const newTheme = theme === 'light' ? 'dark' : 'light';
      localStorage.setItem(storageKey, newTheme);
      setTheme(newTheme);
    },
  };

  return (
    <ThemeProviderContext.Provider {...props} value={value}>
      {children}
    </ThemeProviderContext.Provider>
  );
}

export const useTheme = () => {
  const context = useContext(ThemeProviderContext);

  if (context === undefined)
    throw new Error('useTheme must be used within a ThemeProvider');

  return context;
};

import React, { useEffect } from 'react';
import Joyride, { CallBackProps, STATUS, Step, Styles } from 'react-joyride';
import { useTourStore } from '@/stores/useTourStore';
import { useTheme } from '@/components/theme/ThemeProvider';

interface GuidedTourProps {
    steps: Step[];
    tourId: string;
    run?: boolean;
    continuous?: boolean;
    showProgress?: boolean;
    showSkipButton?: boolean;
}

export function GuidedTour({
    steps,
    tourId,
    run = false,
    continuous = true,
    showProgress = true,
    showSkipButton = true
}: GuidedTourProps) {
    const { theme } = useTheme();
    const { isRunning, currentTourId, stepIndex, endTour, markTourAsSeen, setStepIndex } = useTourStore();

    const shouldRun = run || (isRunning && currentTourId === tourId);

    const handleJoyrideCallback = (data: CallBackProps) => {
        const { status, index, type } = data;

        if (type === 'step:after') {
            setStepIndex(index + 1);
        }

        if ([STATUS.FINISHED, STATUS.SKIPPED].includes(status as any)) {
            endTour();
            markTourAsSeen();
        }
    };

    // Estilos personalizados baseados no tema
    const styles: Styles = {
        options: {
            primaryColor: theme === 'dark' ? '#3b82f6' : '#2563eb',
            backgroundColor: theme === 'dark' ? '#1f2937' : '#ffffff',
            textColor: theme === 'dark' ? '#f9fafb' : '#111827',
            overlayColor: 'rgba(0, 0, 0, 0.5)',
            arrowColor: theme === 'dark' ? '#1f2937' : '#ffffff',
            zIndex: 10000,
        },
        tooltip: {
            borderRadius: 8,
            padding: 20,
        },
        tooltipContainer: {
            textAlign: 'left',
        },
        tooltipTitle: {
            fontSize: '1.25rem',
            fontWeight: 'bold',
            marginBottom: '0.5rem',
        },
        tooltipContent: {
            fontSize: '0.95rem',
            lineHeight: '1.6',
        },
        buttonNext: {
            backgroundColor: theme === 'dark' ? '#3b82f6' : '#2563eb',
            borderRadius: 6,
            padding: '8px 16px',
            fontSize: '0.9rem',
        },
        buttonBack: {
            marginRight: 10,
            color: theme === 'dark' ? '#9ca3af' : '#6b7280',
        },
        buttonSkip: {
            color: theme === 'dark' ? '#9ca3af' : '#6b7280',
        },
    };

    const locale = {
        back: 'Voltar',
        close: 'Fechar',
        last: 'Finalizar',
        next: 'Próximo',
        skip: 'Pular tour',
    };

    return (
        <Joyride
            steps={steps}
            run={shouldRun}
            continuous={continuous}
            showProgress={showProgress}
            showSkipButton={showSkipButton}
            stepIndex={stepIndex}
            callback={handleJoyrideCallback}
            styles={styles}
            locale={locale}
            disableOverlayClose
            disableCloseOnEsc={false}
            spotlightClicks={true}
            scrollToFirstStep
            scrollOffset={100}
            hideCloseButton={false}
            disableScrolling={false}
        />
    );
}

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

