  const [editingUnit, setEditingUnit] = useState<string | null>(null);
  const [formData, setFormData] = useState<UnitFormData>(initialFormData);
  const [isSaving, setIsSaving] = useState(false);

  // Settings Dialog State
  const [settingsDialogOpen, setSettingsDialogOpen] = useState(false);
  const [settingsUnitId, setSettingsUnitId] = useState<string | null>(null);

  if (!organization) {
    return (
      <Card className="p-8 text-center">
        <AlertTriangle className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
        <p className="text-muted-foreground">Organização não encontrada</p>
      </Card>
    );
  }

  const handleOpenDialog = (unitId?: string) => {
    if (unitId) {
      const unit = units.find(u => u.id === unitId);
      if (unit) {
        setFormData({
          nome_unidade: unit.nome_unidade,
          codigo_interno: unit.codigo_interno || '',
          razao_social: unit.razao_social || '',
          documento: unit.documento || '',
          endereco_logradouro: (unit as any).endereco_logradouro || '',
          endereco_numero: (unit as any).endereco_numero || '',
          endereco_bairro: (unit as any).endereco_bairro || '',
          endereco_cidade: (unit as any).endereco_cidade || '',
          endereco_uf: (unit as any).endereco_uf || '',
          endereco_cep: (unit as any).endereco_cep || '',
          telefone: (unit as any).telefone || '',
          email: (unit as any).email || '',
          is_matriz: unit.is_matriz
        });
        setEditingUnit(unitId);
      }
    } else {
      setFormData(initialFormData);
      setEditingUnit(null);
    }
    setIsDialogOpen(true);
  };

  const handleCloseDialog = () => {
    setIsDialogOpen(false);
    setEditingUnit(null);
    setFormData(initialFormData);
  };

  const handleOpenSettings = (unitId: string) => {
    setSettingsUnitId(unitId);
    setSettingsDialogOpen(true);
  };

  const handleSave = async () => {
    if (!formData.nome_unidade.trim()) {
      toast({
        title: "Campo obrigatório",
        description: "O nome da unidade é obrigatório.",
        variant: "destructive"
      });
      return;
    }

    if (!formData.razao_social.trim()) {
      toast({
        title: "Campo obrigatório",
        description: "A razão social é obrigatória.",
        variant: "destructive"
      });
      return;
    }

    setIsSaving(true);

    try {
      const unitData = {
        organization_id: organization.id,
        nome_unidade: formData.nome_unidade,
        codigo_interno: formData.codigo_interno || null,
        razao_social: formData.razao_social,
        documento: formData.documento || null,
        endereco_logradouro: formData.endereco_logradouro || null,
        endereco_numero: formData.endereco_numero || null,
        endereco_bairro: formData.endereco_bairro || null,
        endereco_cidade: formData.endereco_cidade || null,
        endereco_uf: formData.endereco_uf || null,
        endereco_cep: formData.endereco_cep || null,
        telefone: formData.telefone || null,
        email: formData.email || null,
        is_matriz: formData.is_matriz
      };

      if (editingUnit) {
        const { error } = await supabase
          .from('units')
          .update(unitData)
          .eq('id', editingUnit);

        if (error) throw error;

        toast({
          title: "Sucesso",
          description: "Unidade atualizada com sucesso!"
        });
      } else {
        // Create unit
        const { data: newUnit, error: unitError } = await supabase
          .from('units')
          .insert(unitData)
          .select()
          .single();

        if (unitError) throw unitError;

        // Create unit_settings
        const { error: settingsError } = await supabase
          .from('unit_settings')
          .insert({
            unit_id: newUnit.id,
            organization_id: organization.id
          });

        if (settingsError) throw settingsError;

        toast({
          title: "Sucesso",
          description: "Unidade criada com sucesso!",
          action: (
            <Button
              variant="outline"
              size="sm"
              onClick={() => handleOpenSettings(newUnit.id)}
            >
              Configurar Agora
            </Button>
          )
        });
      }

      handleCloseDialog();
      refreshData();

    } catch (error: any) {
      console.error('Erro ao salvar unidade:', error);
      toast({
        title: "Erro",
        description: error.message || "Não foi possível salvar a unidade.",
        variant: "destructive"
      });
    } finally {
      setIsSaving(false);
    }
  };

  const handleDelete = async (unitId: string) => {
    const unit = units.find(u => u.id === unitId);
    if (!unit) return;

    if (unit.is_matriz) {
      toast({
        title: "Ação não permitida",
        description: "Não é possível excluir a unidade matriz.",
        variant: "destructive"
      });
      return;
    }

    if (!confirm(`Tem certeza que deseja excluir a unidade "${unit.nome_unidade}"?`)) {
      return;
    }

    try {
      const { error } = await supabase
        .from('units')
        .update({ status: 'inativo' })
        .eq('id', unitId);

      if (error) throw error;

      toast({
        title: "Sucesso",
        description: "Unidade desativada com sucesso."
      });

      refreshData();

    } catch (error: any) {
      console.error('Erro ao excluir unidade:', error);
      toast({
        title: "Erro",
        description: "Não foi possível excluir a unidade.",
        variant: "destructive"
      });
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold">Gestão de Unidades</h2>
          <p className="text-muted-foreground">
            Gerencie as unidades/filiais da organização {organization.nome_fantasia}
          </p>
        </div>
        {isOrgAdmin && (
          <Button onClick={() => handleOpenDialog()}>
            <Plus className="h-4 w-4 mr-2" />
            Nova Unidade
          </Button>
        )}
      </div>

      <Card>
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Unidade</TableHead>
              <TableHead>Razão Social</TableHead>
              <TableHead>CNPJ</TableHead>
              <TableHead>Cidade/UF</TableHead>
              <TableHead>Status</TableHead>
              <TableHead className="text-right">Ações</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {units.length === 0 ? (
              <TableRow>
                <TableCell colSpan={6} className="text-center py-8">
                  <Building2 className="h-12 w-12 mx-auto text-muted-foreground mb-2" />
                  <p className="text-muted-foreground">Nenhuma unidade cadastrada</p>
                </TableCell>
              </TableRow>
            ) : (
              units.map((unit) => (
                <TableRow key={unit.id}>
                  <TableCell>
                    <div className="flex items-center gap-2">
                      <MapPin className="h-4 w-4 text-muted-foreground" />
                      <div>
                        <p className="font-medium">{unit.nome_unidade}</p>
                        {unit.codigo_interno && (
                          <p className="text-xs text-muted-foreground">{unit.codigo_interno}</p>
                        )}
                      </div>
                      {unit.is_matriz && (
                        <Badge variant="secondary">Matriz</Badge>
                      )}
                    </div>
                  </TableCell>
                  <TableCell>{unit.razao_social || '-'}</TableCell>
                  <TableCell>{unit.documento || '-'}</TableCell>
                  <TableCell>
                    {(unit as any).endereco_cidade && (unit as any).endereco_uf
                      ? `${(unit as any).endereco_cidade}/${(unit as any).endereco_uf}`
                      : '-'
                    }
                  </TableCell>
                  <TableCell>
                    <Badge variant={unit.status === 'ativo' ? 'default' : 'secondary'}>
                      {unit.status === 'ativo' ? 'Ativa' : 'Inativa'}
                    </Badge>
                  </TableCell>
                  <TableCell className="text-right">
                    <div className="flex items-center justify-end gap-2">
                      {isOrgAdmin && (
                        <>
                          <Button
                            variant="ghost"
                            size="icon"
                            onClick={() => handleOpenSettings(unit.id)}
                            title="Configurações"
                          >
                            <Settings className="h-4 w-4" />
                          </Button>
                          <Button
                            variant="ghost"
                            size="icon"
                            onClick={() => handleOpenDialog(unit.id)}
                            title="Editar"
                          >
                            <Edit className="h-4 w-4" />
                          </Button>
                          {!unit.is_matriz && (
                            <Button
                              variant="ghost"
                              size="icon"
                              onClick={() => handleDelete(unit.id)}
                              title="Excluir"
                            >
                              <Trash2 className="h-4 w-4 text-destructive" />
                            </Button>
                          )}
                        </>
                      )}
                    </div>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </Card>

      {/* Dialog for Add/Edit Unit */}
      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>
              {editingUnit ? 'Editar Unidade' : 'Nova Unidade'}
            </DialogTitle>
          </DialogHeader>

          <div className="space-y-6 py-4">
            {/* Identificação */}
            <div className="space-y-4">
              <h3 className="font-semibold text-sm text-muted-foreground uppercase tracking-wide">
                Identificação
              </h3>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label htmlFor="nome_unidade">Nome da Unidade *</Label>
                  <Input
                    id="nome_unidade"
                    placeholder="Ex: Filial Centro"
                    value={formData.nome_unidade}
                    onChange={(e) => setFormData(prev => ({ ...prev, nome_unidade: e.target.value }))}
                  />
                </div>
                <div>
                  <Label htmlFor="codigo_interno">Código Interno</Label>
                  <Input
                    id="codigo_interno"
                    placeholder="Ex: FIL01"
                    value={formData.codigo_interno}
                    onChange={(e) => setFormData(prev => ({ ...prev, codigo_interno: e.target.value }))}
                  />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label htmlFor="razao_social">Razão Social *</Label>
                  <Input
                    id="razao_social"
                    placeholder="Nome legal da empresa"
                    value={formData.razao_social}
                    onChange={(e) => setFormData(prev => ({ ...prev, razao_social: e.target.value }))}
                  />
                </div>
                <div>
                  <Label htmlFor="documento">CNPJ</Label>
                  <Input
                    id="documento"
                    placeholder="00.000.000/0000-00"
                    value={formData.documento}
                    onChange={(e) => setFormData(prev => ({ ...prev, documento: e.target.value }))}
                  />
                </div>
              </div>
            </div>

            {/* Endereço */}
            <div className="space-y-4">
              <h3 className="font-semibold text-sm text-muted-foreground uppercase tracking-wide">
                Endereço
              </h3>
              <div className="grid grid-cols-3 gap-4">
                <div className="col-span-2">
                  <Label htmlFor="endereco_logradouro">Logradouro</Label>
                  <Input
                    id="endereco_logradouro"
                    placeholder="Rua, Avenida..."
                    value={formData.endereco_logradouro}
                    onChange={(e) => setFormData(prev => ({ ...prev, endereco_logradouro: e.target.value }))}
                  />
                </div>
                <div>
                  <Label htmlFor="endereco_numero">Número</Label>
                  <Input
                    id="endereco_numero"
                    placeholder="123"
                    value={formData.endereco_numero}
                    onChange={(e) => setFormData(prev => ({ ...prev, endereco_numero: e.target.value }))}
                  />
                </div>
              </div>
              <div className="grid grid-cols-3 gap-4">
                <div>
                  <Label htmlFor="endereco_bairro">Bairro</Label>
                  <Input
                    id="endereco_bairro"
                    value={formData.endereco_bairro}
                    onChange={(e) => setFormData(prev => ({ ...prev, endereco_bairro: e.target.value }))}
                  />
                </div>
                <div>
                  <Label htmlFor="endereco_cidade">Cidade</Label>
                  <Input
                    id="endereco_cidade"
                    value={formData.endereco_cidade}
                    onChange={(e) => setFormData(prev => ({ ...prev, endereco_cidade: e.target.value }))}
                  />
                </div>
                <div>
                  <Label htmlFor="endereco_uf">UF</Label>
                  <Input
                    id="endereco_uf"
                    placeholder="SP"
                    maxLength={2}
                    value={formData.endereco_uf}
                    onChange={(e) => setFormData(prev => ({ ...prev, endereco_uf: e.target.value.toUpperCase() }))}
                  />
                </div>
              </div>
              <div>
                <Label htmlFor="endereco_cep">CEP</Label>
                <Input
                  id="endereco_cep"
                  placeholder="00000-000"
                  value={formData.endereco_cep}
                  onChange={(e) => setFormData(prev => ({ ...prev, endereco_cep: e.target.value }))}
                  className="w-40"
                />
              </div>
            </div>

            {/* Contato */}
            <div className="space-y-4">
              <h3 className="font-semibold text-sm text-muted-foreground uppercase tracking-wide">
                Contato
              </h3>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label htmlFor="telefone">Telefone</Label>
                  <Input
                    id="telefone"
                    placeholder="(00) 00000-0000"
                    value={formData.telefone}
                    onChange={(e) => setFormData(prev => ({ ...prev, telefone: e.target.value }))}
                  />
                </div>
                <div>
                  <Label htmlFor="email">E-mail</Label>
                  <Input
                    id="email"
                    type="email"
                    placeholder="unidade@empresa.com"
                    value={formData.email}
                    onChange={(e) => setFormData(prev => ({ ...prev, email: e.target.value }))}
                  />
                </div>
              </div>
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={handleCloseDialog}>
              Cancelar
            </Button>
            <Button onClick={handleSave} disabled={isSaving}>
              {isSaving ? (
                <>
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                  Salvando...
                </>
              ) : (
                'Salvar'
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <UnitSettingsDialog
        open={settingsDialogOpen}
        onOpenChange={setSettingsDialogOpen}
        unitId={settingsUnitId}
        organizationId={organization.id}
      />
    </div>
  );
}

import { useState, useEffect } from 'react';
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { useToast } from "@/components/ui/use-toast";
import { Car, Plus, Wrench, CheckCircle, Clock } from 'lucide-react';

interface Vehicle {
    id: string;
    identifier: string; // Placa
    description: string; // Modelo
    metadata: {
        ano?: string;
        km?: string;
        cor?: string;
    };
}

interface ServiceOrder {
    id: string;
    title: string;
    status: 'open' | 'in_progress' | 'waiting_parts' | 'done';
    customer_id: string;
    customer_name?: string; // Join
    vehicle_id?: string;
    vehicle_plate?: string; // Join/Metadata
    created_at: string;
}

export function WorkshopDashboard() {
    const [orders, setOrders] = useState<ServiceOrder[]>([]);
    const [loading, setLoading] = useState(true);
    const { toast } = useToast();

    useEffect(() => {
        fetchOrders();
    }, []);

    const fetchOrders = async () => {
        setLoading(true);
        try {
            // Fetch service files of type 'os'
            const { data, error } = await supabase
                .from('service_files')
                .select(`
                    *,
                    pacientes (nome)
                `)
                .eq('type', 'os')
                .order('created_at', { ascending: false });

            if (error) throw error;

            const formattedOrders: ServiceOrder[] = data.map(item => ({
                id: item.id,
                title: item.title,
                status: item.status as any,
                customer_id: item.customer_id,
                customer_name: item.pacientes?.nome,
                vehicle_plate: item.content?.placa,
                created_at: item.created_at
            }));

            setOrders(formattedOrders);
        } catch (error) {
            console.error("Error fetching orders:", error);
        } finally {
            setLoading(false);
        }
    };

    const updateStatus = async (id: string, newStatus: string) => {
        try {
            const { error } = await supabase
                .from('service_files')
                .update({ status: newStatus })
                .eq('id', id);

            if (error) throw error;

            setOrders(prev => prev.map(o => o.id === id ? { ...o, status: newStatus as any } : o));
            toast({ title: "Status atualizado!" });
        } catch (error) {
            toast({ title: "Erro ao atualizar", variant: "destructive" });
        }
    };

    const getStatusColor = (status: string) => {
        switch (status) {
            case 'open': return 'bg-blue-500';
            case 'in_progress': return 'bg-yellow-500';
            case 'waiting_parts': return 'bg-orange-500';
            case 'done': return 'bg-green-500';
            default: return 'bg-gray-500';
        }
    };

    const getStatusLabel = (status: string) => {
        switch (status) {
            case 'open': return 'Aberto';
            case 'in_progress': return 'Em Andamento';
            case 'waiting_parts': return 'Aguardando Peças';
            case 'done': return 'Pronto';
            default: return status;
        }
    };

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <h2 className="text-2xl font-bold flex items-center gap-2">
                    <Wrench className="h-6 w-6" />
                    Oficina - Ordens de Serviço
                </h2>
                <NewOSDialog onSuccess={fetchOrders} />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                {['open', 'in_progress', 'waiting_parts', 'done'].map(status => (
                    <div key={status} className="bg-muted/50 p-4 rounded-lg min-h-[400px]">
                        <h3 className="font-semibold mb-4 flex items-center gap-2">
                            <span className={`w-3 h-3 rounded-full ${getStatusColor(status)}`} />
                            {getStatusLabel(status)}
                            <Badge variant="outline" className="ml-auto">
                                {orders.filter(o => o.status === status).length}
                            </Badge>
                        </h3>

                        <div className="space-y-3">
                            {orders.filter(o => o.status === status).map(order => (
                                <Card key={order.id} className="cursor-pointer hover:shadow-md transition-shadow">
                                    <CardContent className="p-4">
                                        <div className="flex justify-between items-start mb-2">
                                            <span className="font-medium text-sm">{order.title}</span>
                                            {order.vehicle_plate && (
                                                <Badge variant="secondary" className="text-xs">
                                                    {order.vehicle_plate}
                                                </Badge>
                                            )}
                                        </div>
                                        <p className="text-xs text-muted-foreground mb-3">
                                            {order.customer_name}
                                        </p>

                                        <div className="flex gap-2 justify-end">
                                            {status !== 'done' && (
                                                <Button
                                                    size="icon"
                                                    variant="ghost"
                                                    className="h-6 w-6"
                                                    onClick={() => updateStatus(order.id, 'done')}
                                                    title="Marcar como Pronto"
                                                >
                                                    <CheckCircle className="h-4 w-4 text-green-600" />
                                                </Button>
                                            )}
                                            {status === 'open' && (
                                                <Button
                                                    size="icon"
                                                    variant="ghost"
                                                    className="h-6 w-6"
                                                    onClick={() => updateStatus(order.id, 'in_progress')}
                                                    title="Iniciar Serviço"
                                                >
                                                    <Clock className="h-4 w-4 text-blue-600" />
                                                </Button>
                                            )}
                                        </div>
                                    </CardContent>
                                </Card>
                            ))}
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
}

function NewOSDialog({ onSuccess }: { onSuccess: () => void }) {
    const [open, setOpen] = useState(false);
    const [loading, setLoading] = useState(false);
    const [customers, setCustomers] = useState<any[]>([]);
    const [formData, setFormData] = useState({
        customer_id: '',
        title: '',
        placa: '',
        descricao: ''
    });

    useEffect(() => {
        if (open) fetchCustomers();
    }, [open]);

    const fetchCustomers = async () => {
        const { data } = await supabase.from('pacientes').select('id, nome').order('nome');
        setCustomers(data || []);
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        try {
            const { data: { user } } = await supabase.auth.getUser();
            const { data: profile } = await supabase.from('profiles').select('tenant_id').eq('id', user?.id).single();

            await supabase.from('service_files').insert({
                tenant_id: profile?.tenant_id,
                customer_id: formData.customer_id,
                type: 'os',
                title: formData.title,
                status: 'open',
                content: {
                    placa: formData.placa,
                    descricao: formData.descricao
                }
            });

            setOpen(false);
            onSuccess();
        } catch (error) {
            console.error(error);
        } finally {
            setLoading(false);
        }
    };

    return (
        <Dialog open={open} onOpenChange={setOpen}>
            <DialogTrigger asChild>
                <Button><Plus className="mr-2 h-4 w-4" /> Nova O.S.</Button>
            </DialogTrigger>
            <DialogContent>
                <DialogHeader>
                    <DialogTitle>Nova Ordem de Serviço</DialogTitle>
                </DialogHeader>
                <form onSubmit={handleSubmit} className="space-y-4">
                    <div>
                        <Label>Cliente</Label>
                        <select
                            className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background file:border-0 file:bg-transparent file:text-sm file:font-medium placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
                            value={formData.customer_id}
                            onChange={e => setFormData({ ...formData, customer_id: e.target.value })}
                            required
                        >
                            <option value="">Selecione...</option>
                            {customers.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
                        </select>
                    </div>
                    <div>
                        <Label>Título (Ex: Revisão 10k)</Label>
                        <Input
                            value={formData.title}
                            onChange={e => setFormData({ ...formData, title: e.target.value })}
                            required
                        />
                    </div>
                    <div>
                        <Label>Placa do Veículo</Label>
                        <Input
                            value={formData.placa}
                            onChange={e => setFormData({ ...formData, placa: e.target.value })}
                            required
                        />
                    </div>
                    <div>
                        <Label>Descrição do Problema</Label>
                        <Input
                            value={formData.descricao}
                            onChange={e => setFormData({ ...formData, descricao: e.target.value })}
                        />
                    </div>
                    <Button type="submit" className="w-full" disabled={loading}>Criar O.S.</Button>
                </form>
            </DialogContent>
        </Dialog>
    );
}

import { supabase } from "@/integrations/supabase/client";
import { whatsappService } from "@/domain/whatsapp/whatsappService";
import { AutomationContext, AutomationFlow, AutomationNode, AutomationEdge } from "./types";

export const automationEngine = {
    async processarEventoAutomacao(context: AutomationContext) {
        console.log(`[AutomationEngine] Processando evento: ${context.event_type} para tenant: ${context.tenant_id}`);

        try {
            // 1. Buscar fluxos ativos para este tenant
            const { data: flows, error: flowError } = await supabase
                .from('automations_flows')
                .select('*')
                .eq('tenant_id', context.tenant_id)
                .eq('ativo', true);

            if (flowError) throw flowError;
            if (!flows || flows.length === 0) {
                console.log('[AutomationEngine] Nenhum fluxo ativo encontrado.');
                return;
            }

            // 2. Para cada fluxo, verificar se o gatilho corresponde
            for (const flow of flows) {
                await this._executarFluxo(flow, context);
            }

        } catch (error) {
            console.error('[AutomationEngine] Erro crítico ao processar automação:', error);
            // Logar erro sistêmico se necessário
        }
    },

    async _executarFluxo(flow: AutomationFlow, context: AutomationContext) {
        try {
            // Buscar nós e arestas do fluxo
            const { data: nodes, error: nodeError } = await supabase
                .from('automations_nodes')
                .select('*')
                .eq('flow_id', flow.id)
                .order('ordem');

            const { data: edges, error: edgeError } = await supabase
                .from('automations_edges')
                .select('*')
                .eq('flow_id', flow.id);

            if (nodeError || edgeError || !nodes) return;

            // Encontrar nó inicial (trigger)
            const triggerNode = nodes.find(n => n.tipo === 'trigger' && n.config_json?.event === context.event_type);

            if (!triggerNode) {
                // Este fluxo não começa com este evento
                return;
            }

            console.log(`[AutomationEngine] Iniciando fluxo "${flow.nome}" (ID: ${flow.id})`);

            // Iniciar travessia
            await this._processarNo(triggerNode, nodes, edges || [], context, flow.id);

        } catch (error) {
            console.error(`[AutomationEngine] Erro no fluxo ${flow.id}:`, error);
            await this._logAudit(context.tenant_id, flow.id, null, context.event_type, null, 'error', { error });
        }
    },

    async _processarNo(
        currentNode: AutomationNode,
        allNodes: AutomationNode[],
        allEdges: AutomationEdge[],
        context: AutomationContext,
        flowId: string
    ) {
        // Executar lógica do nó atual
        let shouldContinue = true;

        if (currentNode.tipo === 'condition') {
            shouldContinue = await this._avaliarCondicao(currentNode, context);
        } else if (currentNode.tipo === 'action') {
            await this._executarAcao(currentNode, context, flowId);
        }

        // Se for condição e falhar (false), procurar aresta de "false" ou parar?
        // Simplificação: Se condição for true, segue aresta padrão. Se false, segue aresta "else" se existir.
        // Aqui assumimos um grafo simples: edges conectam nodes.

        // Encontrar próximos nós
        const nextEdges = allEdges.filter(e => e.from_node_id === currentNode.id);

        for (const edge of nextEdges) {
            // Se tiver condição na aresta (ex: branch), verificar
            // Se o nó atual foi uma condição, o resultado dela dita qual aresta seguir

            if (currentNode.tipo === 'condition') {
                // Lógica de branch: edge.condicao_json deve bater com o resultado
                // Ex: edge.condicao_json = { result: true }
                const edgeCondition = edge.condicao_json?.result;
                if (edgeCondition !== undefined && edgeCondition !== shouldContinue) {
                    continue; // Não segue esta aresta
                }
            }

            const nextNode = allNodes.find(n => n.id === edge.to_node_id);
            if (nextNode) {
                await this._processarNo(nextNode, allNodes, allEdges, context, flowId);
            }
        }
    },

    async _avaliarCondicao(node: AutomationNode, context: AutomationContext): Promise<boolean> {
        const config = node.config_json;

        switch (config.condition_type) {
            case 'check_risk_noshow':
                // Verificar risco no payload (agendamento já tem o score calculado)
                const score = context.data?.agendamento?.no_show_score || 0;
                return score >= (config.threshold || 70);

            case 'check_unit':
                return context.data?.unidade_id === config.unit_id;

            case 'check_service':
                return context.data?.servico_id === config.service_id;

            default:
                return true;
        }
    },

    async _executarAcao(node: AutomationNode, context: AutomationContext, flowId: string) {
        const config = node.config_json;
        const actionType = config.action_type;

        try {
            switch (actionType) {
                case 'send_whatsapp':
                    if (context.data?.paciente?.telefone) {
                        const messageType = config.message_type || 'operacional';
                        const content = this._interpolarVariaveis(config.template, context.data);

                        if (messageType === 'marketing') {
                            await whatsappService.enfileirarMensagemMarketing(context.tenant_id, {
                                telefone: context.data.paciente.telefone,
                                conteudo: content
                            });
                        } else {
                            await whatsappService.enfileirarMensagemOperacional(context.tenant_id, {
                                telefone: context.data.paciente.telefone,
                                conteudo: content
                            });
                        }
                    }
                    break;

                case 'send_email':
                    console.log('[AutomationEngine] Mock: Enviando email para', context.data?.paciente?.email);
                    break;

                case 'add_tag':
                    console.log('[AutomationEngine] Mock: Adicionando tag', config.tag, 'ao paciente', context.data?.paciente?.id);
                    break;
            }

            await this._logAudit(context.tenant_id, flowId, node.id, context.event_type, actionType, 'success', { config });

        } catch (error: any) {
            console.error(`[AutomationEngine] Erro na ação ${actionType}:`, error);
            await this._logAudit(context.tenant_id, flowId, node.id, context.event_type, actionType, 'error', { error: error.message });
        }
    },

    _interpolarVariaveis(template: string, data: any): string {
        if (!template) return '';
        return template.replace(/{{(\w+)}}/g, (_, key) => {
            // Suporte básico a variáveis planas (ex: {{paciente_nome}})
            // Idealmente usar lodash.get para nested props
            return data[key] || data.paciente?.[key] || `{{${key}}}`;
        });
    },

    async _logAudit(
        tenantId: string,
        flowId: string | null,
        nodeId: string | null,
        eventType: string,
        actionType: string | null,
        status: string,
        details: any
    ) {
        await supabase.from('automation_logs').insert({
            tenant_id: tenantId,
            flow_id: flowId,
            node_id: nodeId,
            event_type: eventType,
            action_type: actionType,
            status,
            details
        });
    }
};

export type AutomationEventType =
    | 'onAppointmentCreated'
    | 'onAppointmentConfirmed'
    | 'onAppointmentNoShow'
    | 'onInvoiceDue'
    | 'onInvoicePaid';

export type NodeType = 'trigger' | 'condition' | 'action';

export type ActionType =
    | 'send_whatsapp'
    | 'send_email'
    | 'send_sms'
    | 'add_tag';

export type ConditionType =
    | 'check_risk_noshow'
    | 'check_unit'
    | 'check_service'
    | 'check_channel_allowed';

export interface AutomationFlow {
    id: string;
    tenant_id: string | null;
    nome: string;
    descricao?: string;
    ativo: boolean;
    is_global?: boolean;
    segmento?: string;
    created_at: string;
    updated_at: string;
}

export interface AutomationNode {
    id: string;
    flow_id: string;
    tipo: NodeType;
    config_json: any;
    ordem: number;
    created_at: string;
}

export interface AutomationEdge {
    id: string;
    flow_id: string;
    from_node_id: string;
    to_node_id: string;
    condicao_json?: any;
    created_at: string;
}

export interface AutomationContext {
    tenant_id: string;
    event_type: AutomationEventType;
    data: any; // Payload do evento (agendamento, fatura, etc)
}

