import { useEffect, useLayoutEffect, useState } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { toast } from 'sonner';

type Theme = 'light' | 'dark';

export function useAdminTheme() {
    const [theme, setTheme] = useState<Theme>(() => {
        // Initialize from localStorage to avoid FOUC
        if (typeof window !== 'undefined') {
            const saved = localStorage.getItem('admin-theme') as Theme;
            return saved || 'dark';
        }
        return 'dark';
    });
    const [loading, setLoading] = useState(true);

    // Apply theme immediately before paint
    useLayoutEffect(() => {
        const root = window.document.documentElement;
        root.classList.remove('light', 'dark');
        root.classList.add(theme);
        // Also save to localStorage to ensure consistency
        localStorage.setItem('admin-theme', theme);
    }, [theme]);

    useEffect(() => {
        loadThemePreference();
    }, []);

    const loadThemePreference = async () => {
        try {
            const { data: { user } } = await supabase.auth.getUser();

            if (!user) {
                setLoading(false);
                return;
            }

            const { data: systemUser, error } = await supabase
                .from('system_users')
                .select('theme_preference')
                .eq('id', user.id)
                .single();

            if (!error && systemUser) {
                const userTheme = (systemUser as any).theme_preference as Theme;
                if (userTheme && userTheme !== theme) {
                    setTheme(userTheme);
                }
            }
        } catch (error) {
            console.error('Erro ao carregar tema:', error);
        } finally {
            setLoading(false);
        }
    };

    const toggleTheme = async () => {
        const newTheme: Theme = theme === 'dark' ? 'light' : 'dark';
        setTheme(newTheme);

        try {
            const { data: { user } } = await supabase.auth.getUser();
            if (user) {
                await supabase
                    .from('system_users')
                    .update({ theme_preference: newTheme } as any)
                    .eq('id', user.id);
            }
            toast.success(`Tema ${newTheme === 'dark' ? 'escuro' : 'claro'} ativado`);
        } catch (error) {
            console.error('Erro ao salvar tema:', error);
        }
    };

    return {
        theme,
        toggleTheme,
        loading
    };
}

import { createContext, useContext, useEffect, useState } from "react";
import { User, Session } from "@supabase/supabase-js";
import { supabase } from "@/integrations/supabase/client";
import { useNavigate } from "react-router-dom";

interface AuthContextType {
  user: User | null;
  session: Session | null;
  profile: any | null;
  loading: boolean;
  signIn: (email: string, password: string) => Promise<{ error: any }>;
  signUp: (email: string, password: string, userData: any) => Promise<{ error: any }>;
  signOut: () => Promise<void>;
  refreshProfile: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [session, setSession] = useState<Session | null>(null);
  const [profile, setProfile] = useState<any | null>(null);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  const fetchProfile = async (userId: string) => {
    const { data } = await (supabase as any)
      .from("profiles")
      .select("*, tenants(*)")
      .eq("id", userId)
      .single();
    
    if (data) {
      setProfile(data);
    }
  };

  const refreshProfile = async () => {
    if (user?.id) {
      await fetchProfile(user.id);
    }
  };

  useEffect(() => {
    // Set up auth state listener
    const { data: { subscription } } = supabase.auth.onAuthStateChange(
      async (event, session) => {
        console.log('[useAuth] Auth state changed:', event, session?.user?.id);
        setSession(session);
        setUser(session?.user ?? null);
        
        if (session?.user) {
          console.log('[useAuth] Session user found, fetching profile');
          // Fetch profile data
          setTimeout(async () => {
            await fetchProfile(session.user.id);
          }, 0);
        } else {
          console.log('[useAuth] No session user, clearing profile');
          setProfile(null);
        }
      }
    );

    // Check for existing session
    supabase.auth.getSession().then(({ data: { session } }) => {
      console.log('[useAuth] Initial session check:', session?.user?.id);
      setSession(session);
      setUser(session?.user ?? null);
      
      if (session?.user) {
        console.log('[useAuth] Initial session user found, fetching profile');
        fetchProfile(session.user.id).then(() => {
          setLoading(false);
        });
      } else {
        console.log('[useAuth] No initial session user');
        setLoading(false);
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  // Subscribe to profile changes
  useEffect(() => {
    if (!user?.id) return;

    const channel = supabase
      .channel('profile-changes')
      .on(
        'postgres_changes',
        {
          event: 'UPDATE',
          schema: 'public',
          table: 'profiles',
          filter: `id=eq.${user.id}`
        },
        () => {
          refreshProfile();
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [user?.id]);

  const signIn = async (email: string, password: string) => {
    const { error } = await supabase.auth.signInWithPassword({
      email,
      password,
    });
    return { error };
  };

  const signUp = async (email: string, password: string, userData: any) => {
    const { data, error } = await supabase.auth.signUp({
      email,
      password,
      options: {
        emailRedirectTo: `${window.location.origin}/`,
      },
    });

    if (error) return { error };

    // Create tenant and profile will be created via trigger or directly
    return { error: null };
  };

  const signOut = async () => {
    await supabase.auth.signOut();
    setUser(null);
    setSession(null);
    setProfile(null);
    navigate("/");
  };

  return (
    <AuthContext.Provider
      value={{ user, session, profile, loading, signIn, signUp, signOut, refreshProfile }}
    >
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error("useAuth must be used within an AuthProvider");
  }
  return context;
}

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useAuth } from '@/hooks/useAuth';
import { toast } from 'sonner';
import { billingService } from '@/domain/billing/billingService';

interface BillingContextType {
    status: string | null;
    planCode: string | null;
    loading: boolean;
    refreshBilling: () => Promise<void>;
}

const BillingContext = createContext<BillingContextType | undefined>(undefined);

export function BillingProvider({ children }: { children: ReactNode }) {
    const { profile } = useAuth();
    const [status, setStatus] = useState<string | null>(null);
    const [planCode, setPlanCode] = useState<string | null>(null);
    const [loading, setLoading] = useState(true);

    const fetchBilling = async () => {
        if (!profile?.tenant_id) {
            setLoading(false);
            return;
        }

        try {
            const overview = await billingService.carregarAssinaturaAtual(profile.tenant_id);
            const sub = overview.subscription;

            if (sub) {
                // Check if status changed from non-active to active to show toast
                if (status && status !== 'active' && sub.status === 'active') {
                    toast.success("Pagamento recebido! Sua assinatura está ativa.");
                }
                setStatus(sub.status);
                setPlanCode(sub.plan_id);
            } else {
                setStatus(null);
                setPlanCode(null);
            }
        } catch (error) {
            console.error('Error fetching billing:', error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchBilling();

        if (!profile?.tenant_id) return;

        const channel = supabase
            .channel('billing-updates')
            .on(
                'postgres_changes',
                {
                    event: 'UPDATE',
                    schema: 'public',
                    table: 'subscriptions', // Atualizado para nome em inglês
                    filter: `tenant_id=eq.${profile.tenant_id}`
                },
                (payload) => {
                    console.log('Billing update received:', payload);
                    const newData = payload.new as any;

                    if (status && status !== 'active' && newData.status === 'active') {
                        toast.success("Pagamento recebido! Sua assinatura está ativa.");
                    }

                    setStatus(newData.status);
                    setPlanCode(newData.plan_id);
                }
            )
            .subscribe();

        return () => {
            supabase.removeChannel(channel);
        };
    }, [profile?.tenant_id]);

    return (
        <BillingContext.Provider value={{ status, planCode, loading, refreshBilling: fetchBilling }}>
            {children}
        </BillingContext.Provider>
    );
}

export function useBilling() {
    const context = useContext(BillingContext);
    if (context === undefined) {
        throw new Error('useBilling must be used within a BillingProvider');
    }
    return context;
}

import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";

export interface DashboardFilters {
  tenant_id?: string;
  priority?: string;
  status?: string;
}

export interface DashboardPreferences {
  theme: 'claro' | 'escuro' | 'sistema';
  filters: DashboardFilters;
}

export const useDashboardPreferences = () => {
  const [theme, setTheme] = useState<'claro' | 'escuro' | 'sistema'>('claro');
  const [filters, setFilters] = useState<DashboardFilters>({});
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadPreferences();
  }, []);

  useEffect(() => {
    applyTheme();
  }, [theme]);

  const loadPreferences = async () => {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      const { data } = await supabase
        .from('support_dashboard_preferences')
        .select('*')
        .eq('support_user_id', user.id)
        .maybeSingle();

      if (data?.preferences) {
        const prefs = data.preferences as any as DashboardPreferences;
        setTheme(prefs.theme || 'claro');
        setFilters(prefs.filters || {});
      }
    } catch (error) {
      console.error('Error loading preferences:', error);
    } finally {
      setLoading(false);
    }
  };

  const applyTheme = () => {
    const root = document.documentElement;

    if (theme === 'sistema') {
      const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
      root.classList.toggle('dark', prefersDark);
    } else {
      root.classList.toggle('dark', theme === 'escuro');
    }
  };

  const updateTheme = async (newTheme: 'claro' | 'escuro' | 'sistema') => {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      setTheme(newTheme);

      const preferences: DashboardPreferences = { theme: newTheme, filters };

      await supabase
        .from('support_dashboard_preferences')
        .upsert({
          support_user_id: user.id,
          preferences: preferences as any
        } as any);

      // Log action
      await supabase.from('support_actions_log').insert({
        support_user_id: user.id,
        action_type: 'dashboard_preferences_changed',
        target_type: 'preferences',
        description: `Tema alterado para ${newTheme}`,
        metadata: { theme: newTheme } as any
      } as any);

      toast.success('Tema atualizado');
    } catch (error) {
      console.error('Error updating theme:', error);
      toast.error('Erro ao atualizar tema');
    }
  };

  const updateFilters = async (newFilters: DashboardFilters) => {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      setFilters(newFilters);

      const preferences: DashboardPreferences = { theme, filters: newFilters };

      await supabase
        .from('support_dashboard_preferences')
        .upsert({
          support_user_id: user.id,
          preferences: preferences as any
        } as any);

      // Log action
      await supabase.from('support_actions_log').insert({
        support_user_id: user.id,
        action_type: 'dashboard_preferences_changed',
        target_type: 'preferences',
        description: 'Filtros do dashboard atualizados',
        metadata: { filters: newFilters } as any
      } as any);
    } catch (error) {
      console.error('Error updating filters:', error);
      toast.error('Erro ao atualizar filtros');
    }
  };

  return {
    theme,
    filters,
    loading,
    updateTheme,
    updateFilters
  };
};

import { useState, useEffect, useRef } from 'react';

export interface ValidationRule {
  field: string;
  label: string;
  required?: boolean;
  validator?: (value: any) => string | null;
}

export function useFormValidation<T extends Record<string, any>>(
  initialData: T,
  rules: ValidationRule[]
) {
  const [formData, setFormData] = useState<T>(initialData);
  const [hasChanges, setHasChanges] = useState(false);
  const fieldRefs = useRef<Record<string, HTMLInputElement | HTMLTextAreaElement | null>>({});

  useEffect(() => {
    const changed = JSON.stringify(formData) !== JSON.stringify(initialData);
    setHasChanges(changed);
  }, [formData, initialData]);

  const validateForm = (): { isValid: boolean; errors: string[] } => {
    const errors: string[] = [];
    let firstInvalidField: string | null = null;

    for (const rule of rules) {
      const value = formData[rule.field];
      
      if (rule.required && (!value || (typeof value === 'string' && !value.trim()))) {
        errors.push(rule.label);
        if (!firstInvalidField) firstInvalidField = rule.field;
      } else if (rule.validator && value) {
        const error = rule.validator(value);
        if (error) {
          errors.push(`${rule.label}: ${error}`);
          if (!firstInvalidField) firstInvalidField = rule.field;
        }
      }
    }

    // Focus on first invalid field
    if (firstInvalidField && fieldRefs.current[firstInvalidField]) {
      fieldRefs.current[firstInvalidField]?.focus();
    }

    return {
      isValid: errors.length === 0,
      errors
    };
  };

  const registerField = (fieldName: string) => (el: HTMLInputElement | HTMLTextAreaElement | null) => {
    fieldRefs.current[fieldName] = el;
  };

  const resetForm = () => {
    setFormData(initialData);
    setHasChanges(false);
  };

  const updateField = (field: keyof T, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  return {
    formData,
    setFormData,
    hasChanges,
    validateForm,
    registerField,
    resetForm,
    updateField
  };
}

import React, { createContext, useContext, useState, useEffect, useCallback, ReactNode } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useAuth } from '@/hooks/useAuth';

interface Organization {
  id: string;
  nome_fantasia: string;
  razao_social: string | null;
  documento: string | null;
  moeda: string;
  timezone: string;
  status: string;
}

interface Unit {
  id: string;
  organization_id: string;
  nome_unidade: string;
  codigo_interno: string | null;
  razao_social: string | null;
  documento: string | null;
  is_matriz: boolean;
  status: string;
}

interface UserRole {
  id: string;
  organization_id: string;
  unit_id: string | null;
  role: 'org_admin' | 'org_finance' | 'unit_admin' | 'unit_finance' | 'atendimento' | 'leitura';
}

interface OrganizationContextType {
  organization: Organization | null;
  units: Unit[];
  currentUnit: Unit | null;
  userRoles: UserRole[];
  isLoading: boolean;
  isMultiUnit: boolean;
  setCurrentUnit: (unit: Unit | null) => void;
  refreshData: () => Promise<void>;
  hasRole: (roles: UserRole['role'][]) => boolean;
  hasUnitAccess: (unitId: string) => boolean;
  isOrgAdmin: boolean;
  isUnitAdmin: boolean;
  isMaster: boolean;
}

const OrganizationContext = createContext<OrganizationContextType | undefined>(undefined);

export function OrganizationProvider({ children }: { children: ReactNode }) {
  const { profile, user } = useAuth();
  const [organization, setOrganization] = useState<Organization | null>(null);
  const [units, setUnits] = useState<Unit[]>([]);
  const [currentUnit, setCurrentUnit] = useState<Unit | null>(null);
  const [userRoles, setUserRoles] = useState<UserRole[]>([]);
  const [isMaster, setIsMaster] = useState(false);
  const [isLoading, setIsLoading] = useState(true);

  const fetchOrganizationData = useCallback(async () => {
    if (!profile?.organization_id) {
      setIsLoading(false);
      return;
    }

    try {
      setIsLoading(true);

      // Fetch organization
      const { data: orgData, error: orgError } = await supabase
        .from('organizations')
        .select('*')
        .eq('id', profile.organization_id)
        .maybeSingle();

      if (orgError) throw orgError;
      if (orgData) {
        setOrganization(orgData as Organization);
      }

      // Fetch units
      const { data: unitsData, error: unitsError } = await supabase
        .from('units')
        .select('*')
        .eq('organization_id', profile.organization_id)
        .eq('status', 'ativo')
        .order('is_matriz', { ascending: false })
        .order('nome_unidade');

      if (unitsError) throw unitsError;
      setUnits((unitsData as Unit[]) || []);

      // Set default current unit (matriz or first)
      if (unitsData && unitsData.length > 0 && !currentUnit) {
        const matriz = unitsData.find((u: any) => u.is_matriz);
        setCurrentUnit((matriz || unitsData[0]) as Unit);
      }

      // Fetch user roles
      if (user?.id) {
        const { data: rolesData, error: rolesError } = await supabase
          .from('user_unit_roles')
          .select('*')
          .eq('user_id', user.id)
          .eq('organization_id', profile.organization_id);

        if (rolesError) throw rolesError;
        setUserRoles((rolesData as UserRole[]) || []);

        // Check if user is master/system_user
        const { data: systemUserData } = await (supabase as any)
          .from('system_users')
          .select('id')
          .eq('id', user.id)
          .maybeSingle();

        setIsMaster(!!systemUserData);
      }

    } catch (error) {
      console.error('Erro ao buscar dados da organização:', error);
    } finally {
      setIsLoading(false);
    }
  }, [profile?.organization_id, user?.id]);

  useEffect(() => {
    fetchOrganizationData();
  }, [fetchOrganizationData]);

  // Check if user has any of the specified roles
  const hasRole = useCallback((roles: UserRole['role'][]) => {
    return userRoles.some(ur => roles.includes(ur.role));
  }, [userRoles]);

  // Check if user has access to a specific unit
  const hasUnitAccess = useCallback((unitId: string) => {
    // Org-level roles have access to all units
    const hasOrgRole = userRoles.some(ur =>
      ur.unit_id === null && ['org_admin', 'org_finance'].includes(ur.role)
    );
    if (hasOrgRole) return true;

    // Check unit-specific access
    return userRoles.some(ur => ur.unit_id === unitId);
  }, [userRoles]);

  const isMultiUnit = units.length > 1;
  const isOrgAdmin = hasRole(['org_admin']);
  const isUnitAdmin = hasRole(['org_admin', 'unit_admin']);

  return (
    <OrganizationContext.Provider value={{
      organization,
      units,
      currentUnit,
      userRoles,
      isLoading,
      isMultiUnit,
      setCurrentUnit,
      refreshData: fetchOrganizationData,
      hasRole,
      hasUnitAccess,
      isOrgAdmin,
      isUnitAdmin,
      isMaster
    }}>
      {children}
    </OrganizationContext.Provider>
  );
}

export function useOrganizationContext() {
  const context = useContext(OrganizationContext);
  if (context === undefined) {
    throw new Error('useOrganizationContext must be used within an OrganizationProvider');
  }
  return context;
}

import { useState, useEffect } from 'react';
import { supabase } from '@/integrations/supabase/client';

const MIN_WIDTH = 200;
const MAX_WIDTH = 400;
const DEFAULT_WIDTH = 256; // 64 * 4 = w-64 in tailwind

export function useSidebarWidth() {
  const [width, setWidth] = useState(DEFAULT_WIDTH);
  const [isResizing, setIsResizing] = useState(false);

  useEffect(() => {
    loadWidth();
  }, []);

  const loadWidth = async () => {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      const { data } = await (supabase
        .from('user_preferences' as any)
        .select('sidebar_width')
        .eq('user_id', user.id)
        .maybeSingle() as any);

      if (data?.sidebar_width) {
        setWidth(data.sidebar_width);
      }
    } catch (error: any) {
      // Ignora erro se a tabela não existir ou outro erro de busca, mantendo o fallback DEFAULT_WIDTH
      if (error?.code !== 'PGRST116' && error?.status !== 404) {
        console.error('Erro ao carregar largura da sidebar:', error);
      }
    }
  };

  const saveWidth = async (newWidth: number) => {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      await (supabase
        .from('user_preferences' as any)
        .upsert({
          user_id: user.id,
          sidebar_width: newWidth,
          updated_at: new Date().toISOString()
        }, {
          onConflict: 'user_id'
        } as any) as any);
    } catch (error) {
      console.error('Erro ao salvar largura da sidebar:', error);
    }
  };

  const handleMouseDown = () => {
    setIsResizing(true);
  };

  const handleMouseMove = (e: MouseEvent) => {
    if (!isResizing) return;

    const newWidth = Math.min(Math.max(e.clientX, MIN_WIDTH), MAX_WIDTH);
    setWidth(newWidth);
  };

  const handleMouseUp = () => {
    if (isResizing) {
      setIsResizing(false);
      saveWidth(width);
    }
  };

  useEffect(() => {
    if (isResizing) {
      document.addEventListener('mousemove', handleMouseMove);
      document.addEventListener('mouseup', handleMouseUp);

      return () => {
        document.removeEventListener('mousemove', handleMouseMove);
        document.removeEventListener('mouseup', handleMouseUp);
      };
    }
  }, [isResizing, width]);

  return {
    width,
    isResizing,
    handleMouseDown,
    MIN_WIDTH,
    MAX_WIDTH
  };
}

import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";

export interface ChatSession {
  id: string;
  tenant_id: string;
  client_name: string | null;
  client_email: string | null;
  client_phone: string | null;
  status: 'waiting' | 'active' | 'resolved' | 'closed';
  assigned_agent_id: string | null;
  started_at: string;
  accepted_at: string | null;
  ended_at: string | null;
  wait_time_seconds: number | null;
  metadata: Record<string, any>;
}

export interface ChatMessage {
  id: string;
  session_id: string;
  sender_type: 'client' | 'agent' | 'system';
  sender_id: string | null;
  sender_name: string | null;
  message: string;
  attachments: any[];
  created_at: string;
}

export const useSupportChat = () => {
  const [waitingSessions, setWaitingSessions] = useState<ChatSession[]>([]);
  const [activeSessions, setActiveSessions] = useState<ChatSession[]>([]);
  const [recentSessions, setRecentSessions] = useState<ChatSession[]>([]);
  const [soundEnabled, setSoundEnabled] = useState(true);
  const [soundVolume, setSoundVolume] = useState(80);

  // Load agent preferences
  useEffect(() => {
    loadAgentPreferences();
  }, []);

  // Subscribe to chat sessions
  useEffect(() => {
    loadSessions();

    const channel = supabase
      .channel('support-chat-sessions')
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'support_chat_sessions'
        },
        (payload) => {
          console.log('Chat session change:', payload);
          
          if (payload.eventType === 'INSERT' && payload.new.status === 'waiting') {
            playNotificationSound();
            toast.info(`Novo chat aguardando: ${payload.new.client_name || 'Cliente'}`);
          }
          
          loadSessions();
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [soundEnabled, soundVolume]);

  const loadAgentPreferences = async () => {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      const { data, error } = await supabase
        .from('support_agent_preferences')
        .select('*')
        .eq('agent_id', user.id)
        .maybeSingle();

      if (error) throw error;

      if (data) {
        setSoundEnabled(data.sound_enabled);
        setSoundVolume(data.sound_volume);
      } else {
        // Create default preferences
        await supabase.from('support_agent_preferences').insert({
          agent_id: user.id,
          sound_enabled: true,
          sound_volume: 80,
          max_concurrent_chats: 3
        });
      }
    } catch (error) {
      console.error('Error loading agent preferences:', error);
    }
  };

  const loadSessions = async () => {
    try {
      // Waiting sessions
      const { data: waiting, error: waitingError } = await supabase
        .from('support_chat_sessions')
        .select('*')
        .eq('status', 'waiting')
        .order('started_at', { ascending: true });

      if (waitingError) throw waitingError;
      setWaitingSessions((waiting || []) as ChatSession[]);

      // Active sessions for current agent
      const { data: { user } } = await supabase.auth.getUser();
      if (user) {
        const { data: active, error: activeError } = await supabase
          .from('support_chat_sessions')
          .select('*')
          .eq('status', 'active')
          .eq('assigned_agent_id', user.id)
          .order('accepted_at', { ascending: false });

        if (activeError) throw activeError;
        setActiveSessions((active || []) as ChatSession[]);
      }

      // Recent closed sessions
      const { data: recent, error: recentError } = await supabase
        .from('support_chat_sessions')
        .select('*')
        .in('status', ['resolved', 'closed'])
        .order('ended_at', { ascending: false })
        .limit(10);

      if (recentError) throw recentError;
      setRecentSessions((recent || []) as ChatSession[]);
    } catch (error) {
      console.error('Error loading sessions:', error);
    }
  };

  const acceptChat = async (sessionId: string) => {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error('Usuário não autenticado');

      // Check current active chats
      const { data: prefs } = await supabase
        .from('support_agent_preferences')
        .select('max_concurrent_chats')
        .eq('agent_id', user.id)
        .single();

      const maxChats = prefs?.max_concurrent_chats || 3;

      if (activeSessions.length >= maxChats) {
        toast.error(`Você já está atendendo ${maxChats} chats simultaneamente`);
        return false;
      }

      const { error } = await supabase
        .from('support_chat_sessions')
        .update({
          status: 'active',
          assigned_agent_id: user.id,
          accepted_at: new Date().toISOString()
        })
        .eq('id', sessionId);

      if (error) throw error;

      playAcceptSound();
      toast.success('Chat aceito com sucesso!');
      
      // Log action
      await supabase.from('support_actions_log').insert({
        support_user_id: user.id,
        action_type: 'chat_accepted',
        target_type: 'chat_session',
        target_id: sessionId,
        description: 'Agente aceitou chat'
      });

      return true;
    } catch (error) {
      console.error('Error accepting chat:', error);
      toast.error('Erro ao aceitar chat');
      return false;
    }
  };

  const sendMessage = async (sessionId: string, message: string) => {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error('Usuário não autenticado');

      const { error } = await supabase
        .from('support_chat_messages')
        .insert({
          session_id: sessionId,
          sender_type: 'agent',
          sender_id: user.id,
          message
        });

      if (error) throw error;
      return true;
    } catch (error) {
      console.error('Error sending message:', error);
      toast.error('Erro ao enviar mensagem');
      return false;
    }
  };

  const resolveChat = async (sessionId: string) => {
    try {
      const { error } = await supabase
        .from('support_chat_sessions')
        .update({
          status: 'resolved',
          ended_at: new Date().toISOString()
        })
        .eq('id', sessionId);

      if (error) throw error;
      toast.success('Chat resolvido!');
      
      const { data: { user } } = await supabase.auth.getUser();
      if (user) {
        await supabase.from('support_actions_log').insert({
          support_user_id: user.id,
          action_type: 'chat_resolved',
          target_type: 'chat_session',
          target_id: sessionId,
          description: 'Chat marcado como resolvido'
        });
      }

      return true;
    } catch (error) {
      console.error('Error resolving chat:', error);
      toast.error('Erro ao resolver chat');
      return false;
    }
  };

  const elevateToTicket = async (sessionId: string) => {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error('Usuário não autenticado');

      // Get session and messages
      const { data: session } = await supabase
        .from('support_chat_sessions')
        .select('*')
        .eq('id', sessionId)
        .single();

      const { data: messages } = await supabase
        .from('support_chat_messages')
        .select('*')
        .eq('session_id', sessionId)
        .order('created_at', { ascending: true });

      if (!session) throw new Error('Sessão não encontrada');

      // Create transcript
      const transcript = messages?.map(m => 
        `[${new Date(m.created_at).toLocaleString()}] ${m.sender_type === 'agent' ? 'Agente' : 'Cliente'}: ${m.message}`
      ).join('\n\n');

      // Create ticket
      const { data: ticket, error } = await supabase
        .from('support_tickets')
        .insert({
          tenant_id: session.tenant_id,
          user_id: user.id,
          title: `Chat de ${session.client_name || 'Cliente'}`,
          description: `Chat elevado a ticket\n\nCliente: ${session.client_name || 'N/A'}\nEmail: ${session.client_email || 'N/A'}\nTelefone: ${session.client_phone || 'N/A'}\n\n--- Histórico do Chat ---\n\n${transcript}`,
          priority: 'medium',
          status: 'open',
          origem: 'chat'
        })
        .select()
        .single();

      if (error) throw error;

      // Update session
      const currentMetadata = (session.metadata as Record<string, any>) || {};
      await supabase
        .from('support_chat_sessions')
        .update({
          status: 'closed',
          ended_at: new Date().toISOString(),
          metadata: { ...currentMetadata, elevated_ticket_id: ticket.id }
        })
        .eq('id', sessionId);

      // Log action
      await supabase.from('support_actions_log').insert({
        support_user_id: user.id,
        action_type: 'chat_elevated',
        target_type: 'chat_session',
        target_id: sessionId,
        description: `Chat elevado ao ticket #${ticket.numero}`,
        metadata: { ticket_id: ticket.id, ticket_numero: ticket.numero }
      });

      toast.success(`Chat elevado ao ticket #${ticket.numero}`);
      return ticket;
    } catch (error) {
      console.error('Error elevating to ticket:', error);
      toast.error('Erro ao elevar chat a ticket');
      return null;
    }
  };

  const updatePreferences = async (preferences: { sound_enabled?: boolean; sound_volume?: number; max_concurrent_chats?: number }) => {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      const { error } = await supabase
        .from('support_agent_preferences')
        .upsert({
          agent_id: user.id,
          ...preferences
        });

      if (error) throw error;

      if (preferences.sound_enabled !== undefined) setSoundEnabled(preferences.sound_enabled);
      if (preferences.sound_volume !== undefined) setSoundVolume(preferences.sound_volume);

      toast.success('Preferências atualizadas');
    } catch (error) {
      console.error('Error updating preferences:', error);
      toast.error('Erro ao atualizar preferências');
    }
  };

  const playNotificationSound = () => {
    if (!soundEnabled) return;
    
    const audio = new Audio('data:audio/wav;base64,UklGRnoGAABXQVZFZm10IBAAAAABAAEAQB8AAEAfAAABAAgAZGF0YQoGAACBhYqFbF1fdJivrJBhNjVgodDbq2EcBj+a2/LDciUFLIHO8tiJNwgZaLvt559NEAxQp+PwtmMcBjiR1/LMeSwFJHfH8N2QQAoUXrTp66hVFApGn+DyvmwhBzGM0/PKdyoFJHjH8N6RQQMTX7Tp661VFA==');
    audio.volume = soundVolume / 100;
    audio.play().catch(e => console.error('Error playing sound:', e));
  };

  const playAcceptSound = () => {
    if (!soundEnabled) return;
    
    const audio = new Audio('data:audio/wav;base64,UklGRnoGAABXQVZFZm10IBAAAAABAAEAQB8AAEAfAAABAAgAZGF0YQoGAAB/fn9/fn9/fn9/fn9/fn9/fn9/fn9/fn9/fn9/fn9/fn9/fn9/fn9/fn9/fn9/fn9/fn9/fn9/fn9/fn9/fn9/fn9/fn9/fn9/fn9/fn9/fn9/fn9/fn9/fn9/fn9/fn9/fg==');
    audio.volume = soundVolume / 100;
    audio.play().catch(e => console.error('Error playing sound:', e));
  };

  return {
    waitingSessions,
    activeSessions,
    recentSessions,
    soundEnabled,
    soundVolume,
    acceptChat,
    sendMessage,
    resolveChat,
    elevateToTicket,
    updatePreferences,
    loadSessions
  };
};

import React, { createContext, useContext, useState, useEffect, useCallback, ReactNode } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useAuth } from '@/hooks/useAuth';

interface TenantData {
  nome: string;
  tipo: string;
  cnpj: string | null;
  razao_social: string | null;
  nome_fantasia: string | null;
  font_size: number;
  cor_primaria: string | null;
  cor_acao: string | null;
}

interface TenantContextType {
  tenantData: TenantData | null;
  isLoading: boolean;
  refreshTenantData: () => Promise<void>;
  updateTenantData: (data: Partial<TenantData>) => void;
  displayName: string;
}

const TenantContext = createContext<TenantContextType | undefined>(undefined);

export function TenantProvider({ children }: { children: ReactNode }) {
  const { profile } = useAuth();
  const [tenantData, setTenantData] = useState<TenantData | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  const fetchTenantData = useCallback(async () => {
    const impersonationId = localStorage.getItem('support_impersonation_tenant_id');
    const targetTenantId = impersonationId || profile?.tenant_id;

    if (!targetTenantId) {
      setIsLoading(false);
      return;
    }

    try {
      setIsLoading(true);
      const { data, error } = await supabase
        .from('tenants')
        .select('nome, tipo, cnpj, razao_social, nome_fantasia, font_size, cor_primaria, cor_acao')
        .eq('id', targetTenantId)
        .maybeSingle();

      if (error) throw error;
      if (data) {
        setTenantData({
          nome: data.nome,
          tipo: data.tipo,
          cnpj: data.cnpj,
          razao_social: data.razao_social,
          nome_fantasia: data.nome_fantasia,
          font_size: data.font_size || 16,
          cor_primaria: data.cor_primaria,
          cor_acao: data.cor_acao
        });
      }
    } catch (error) {
      console.error('Erro ao buscar dados do tenant:', error);
      setTenantData({
        nome: "Empresa",
        tipo: "clinica",
        cnpj: null,
        razao_social: null,
        nome_fantasia: null,
        font_size: 16,
        cor_primaria: null,
        cor_acao: null
      });
    } finally {
      setIsLoading(false);
    }
  }, [profile?.tenant_id]);

  useEffect(() => {
    fetchTenantData();
  }, [fetchTenantData]);

  // Apply font size to document root
  useEffect(() => {
    if (tenantData?.font_size) {
      document.documentElement.style.fontSize = `${tenantData.font_size}px`;
    }
  }, [tenantData?.font_size]);

  const updateTenantData = useCallback((data: Partial<TenantData>) => {
    setTenantData(prev => prev ? { ...prev, ...data } : null);
  }, []);

  // Display name: prefer nome_fantasia, fallback to razao_social, then nome
  const displayName = tenantData?.nome_fantasia || tenantData?.razao_social || tenantData?.nome || "Empresa";

  return (
    <TenantContext.Provider value={{
      tenantData,
      isLoading,
      refreshTenantData: fetchTenantData,
      updateTenantData,
      displayName
    }}>
      {children}
    </TenantContext.Provider>
  );
}

export function useTenantData() {
  const context = useContext(TenantContext);
  if (context === undefined) {
    throw new Error('useTenantData must be used within a TenantProvider');
  }
  return context;
}

import { useState, useEffect, useCallback } from 'react';
import { useAuth } from './useAuth';
import { supabase } from '@/integrations/supabase/client';

// Map of role aliases to actual database roles
const ROLE_ALIASES: Record<string, string[]> = {
  'admin_tenant': ['admin'], // profiles.role
  'financeiro_tenant': ['org_finance', 'unit_finance'],
  'suporte': ['master', 'admin', 'agente'], // support_role
  'org_admin': ['org_admin'],
  'org_finance': ['org_finance'],
  'unit_admin': ['unit_admin'],
  'unit_finance': ['unit_finance'],
  'atendimento': ['atendimento'],
  'leitura': ['leitura'],
};

export type AppRole =
  | 'admin_tenant'
  | 'financeiro_tenant'
  | 'suporte'
  | 'org_admin'
  | 'org_finance'
  | 'unit_admin'
  | 'unit_finance'
  | 'atendimento'
  | 'leitura';

interface UserRolesState {
  profileRole: string | null;
  orgRoles: string[];
  supportRoles: string[];
  isLoading: boolean;
  error: string | null;
}

export function useUserRoles() {
  const { user, profile, loading: authLoading } = useAuth();
  const [state, setState] = useState<UserRolesState>({
    profileRole: null,
    orgRoles: [],
    supportRoles: [],
    isLoading: true,
    error: null,
  });

  const fetchRoles = useCallback(async () => {
    if (!user?.id) {
      setState(prev => ({ ...prev, isLoading: false }));
      return;
    }

    try {
      // Fetch organization roles from user_unit_roles
      const { data: unitRoles, error: unitRolesError } = await (supabase
        .from('user_unit_roles' as any)
        .select('role')
        .eq('user_id', user.id) as any);

      if (unitRolesError) {
        console.error('[useUserRoles] Error fetching unit roles:', unitRolesError);
      }

      // Fetch system roles from system_users
      const { data: systemUser, error: systemError } = await (supabase
        .from('system_users' as any)
        .select('system_role, active')
        .eq('id', user.id)
        .maybeSingle() as any);

      if (systemError) {
        console.error('[useUserRoles] Error fetching system user:', systemError);
      }

      const orgRoles = unitRoles?.map(r => r.role) || [];

      // System users have a single system_role
      const supportRoles = systemUser?.active && systemUser?.system_role
        ? [systemUser.system_role]
        : [];

      setState({
        profileRole: profile?.role || null,
        orgRoles,
        supportRoles,
        isLoading: false,
        error: null,
      });
    } catch (err) {
      console.error('[useUserRoles] Error:', err);
      setState(prev => ({
        ...prev,
        isLoading: false,
        error: 'Erro ao carregar papéis do usuário',
      }));
    }
  }, [user?.id, profile?.role]);

  useEffect(() => {
    if (!authLoading) {
      fetchRoles();
    }
  }, [authLoading, fetchRoles]);

  const hasRole = useCallback((roles: AppRole[]): boolean => {
    if (state.isLoading) return false;

    // Master has access to everything
    if (state.supportRoles.includes('master')) {
      return true;
    }

    // Expand aliases to actual roles
    const expandedRoles = roles.flatMap(role => ROLE_ALIASES[role] || [role]);

    // Check profile role (tenant admin)
    if (state.profileRole && expandedRoles.includes(state.profileRole)) {
      return true;
    }

    // Check organization roles
    if (state.orgRoles.some(role => expandedRoles.includes(role))) {
      return true;
    }

    // Check support roles
    if (state.supportRoles.some(role => expandedRoles.includes(role))) {
      return true;
    }

    return false;
  }, [state]);

  const hasAnyRole = useCallback((roles: AppRole[]): boolean => {
    return hasRole(roles);
  }, [hasRole]);

  const hasAllRoles = useCallback((roles: AppRole[]): boolean => {
    return roles.every(role => hasRole([role]));
  }, [hasRole]);

  return {
    ...state,
    hasRole,
    hasAnyRole,
    hasAllRoles,
    refreshRoles: fetchRoles,
  };
}

import { useEffect, useState, useRef } from "react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";

interface WhatsAppNotification {
  id: string;
  conversation_id: string;
  telefone: string;
  paciente_nome?: string;
  mensagem: string;
  timestamp: string;
}

export function useWhatsAppNotifications() {
  const [unreadCount, setUnreadCount] = useState(0);
  const [notifications, setNotifications] = useState<WhatsAppNotification[]>([]);
  const [soundEnabled, setSoundEnabled] = useState(true);
  const audioContextRef = useRef<AudioContext | null>(null);

  useEffect(() => {
    loadUnreadCount();
    subscribeToNewMessages();
  }, []);

  const loadUnreadCount = async () => {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      const { data: profile } = await supabase
        .from("profiles")
        .select("tenant_id")
        .eq("id", user.id)
        .single();

      if (!profile?.tenant_id) return;

      const { count, error } = await supabase
        .from("whatsapp_messages")
        .select("id", { count: "exact", head: true })
        .eq("direcao", "entrada")
        .is("metadata->lido", null);

      if (error) throw error;
      setUnreadCount(count || 0);
    } catch (error) {
      console.error("Erro ao carregar contador de não lidas:", error);
    }
  };

  const subscribeToNewMessages = () => {
    const channel = supabase
      .channel("whatsapp-new-messages")
      .on(
        "postgres_changes",
        {
          event: "INSERT",
          schema: "public",
          table: "whatsapp_messages",
          filter: "direcao=eq.entrada",
        },
        async (payload) => {
          const newMessage = payload.new as any;

          // Buscar dados da conversa
          const { data: conversation } = await supabase
            .from("whatsapp_conversations")
            .select(`
              id,
              telefone,
              pacientes:paciente_id(nome)
            `)
            .eq("id", newMessage.conversation_id)
            .single();

          if (conversation) {
            const notification: WhatsAppNotification = {
              id: newMessage.id,
              conversation_id: newMessage.conversation_id,
              telefone: conversation.telefone,
              paciente_nome: conversation.pacientes?.nome,
              mensagem: newMessage.conteudo,
              timestamp: newMessage.timestamp,
            };

            setNotifications(prev => [notification, ...prev]);
            setUnreadCount(prev => prev + 1);

            // Tocar som
            if (soundEnabled) {
              playNotificationSound();
            }

            // Mostrar toast
            toast.info(`Nova mensagem de ${notification.paciente_nome || notification.telefone}`, {
              description: notification.mensagem.substring(0, 100),
            });
          }
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  };

  const playNotificationSound = () => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    }

    const ctx = audioContextRef.current;
    const oscillator = ctx.createOscillator();
    const gainNode = ctx.createGain();

    oscillator.connect(gainNode);
    gainNode.connect(ctx.destination);

    // Som de notificação WhatsApp-like
    oscillator.frequency.setValueAtTime(800, ctx.currentTime);
    oscillator.frequency.setValueAtTime(600, ctx.currentTime + 0.1);

    gainNode.gain.setValueAtTime(0.3, ctx.currentTime);
    gainNode.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.3);

    oscillator.start(ctx.currentTime);
    oscillator.stop(ctx.currentTime + 0.3);
  };

  const markAsRead = async (conversationId: string) => {
    try {
      // Atualizar metadata das mensagens para marcar como lidas
      const { data: messages, error: fetchError } = await supabase
        .from("whatsapp_messages")
        .select("id, metadata")
        .eq("conversation_id", conversationId)
        .eq("direcao", "entrada");

      if (fetchError) throw fetchError;

      for (const msg of messages || []) {
        await supabase
          .from("whatsapp_messages")
          .update({
            metadata: { ...(msg.metadata as any), lido: true, lido_em: new Date().toISOString() }
          })
          .eq("id", msg.id);
      }

      setNotifications(prev => prev.filter(n => n.conversation_id !== conversationId));
      loadUnreadCount();
    } catch (error) {
      console.error("Erro ao marcar como lida:", error);
    }
  };

  const clearNotification = (notificationId: string) => {
    setNotifications(prev => prev.filter(n => n.id !== notificationId));
  };

  return {
    unreadCount,
    notifications,
    soundEnabled,
    setSoundEnabled,
    markAsRead,
    clearNotification,
  };
}

import { useState, useEffect, useCallback } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { toast } from 'sonner';

interface PhoneNumber {
  id: string;
  phone_number: string;
  display_name: string;
  is_shared: boolean;
  status: string;
}

interface PhoneAllocation {
  id: string;
  phone_number_id: string;
  departamento: string;
  is_primary: boolean;
  status: string;
  phone_number?: PhoneNumber;
}

interface Department {
  id: string;
  nome: string;
  codigo: string;
  descricao: string | null;
  ativo: boolean;
}

interface PhonePackage {
  id: string;
  nome: string;
  descricao: string | null;
  quantidade_numeros: number;
  preco_mensal: number;
  moeda: string;
  inclui_creditos: number;
  planos_permitidos: string[];
  destaque: boolean;
  periodo_minimo_dias: number;
}

interface RoutingConfig {
  id: string;
  usa_numero_compartilhado: boolean;
  ai_routing_enabled: boolean;
  ai_model: string;
  menu_inicial_enabled: boolean;
}

interface PhoneSubscription {
  id: string;
  tenant_id: string;
  package_id: string;
  status: 'pending' | 'active' | 'cancelled' | 'cancellation_scheduled' | 'expired';
  data_inicio: string | null;
  data_proximo_faturamento: string | null;
  data_cancelamento_solicitado: string | null;
  data_cancelamento_efetivo: string | null;
  valor_mensal: number;
  numeros_contratados: number;
  numeros_ativos: number;
  departamentos: string[];
  package?: PhonePackage;
}

export function useWhatsAppPhoneNumbers() {
  const [allocations, setAllocations] = useState<PhoneAllocation[]>([]);
  const [departments, setDepartments] = useState<Department[]>([]);
  const [packages, setPackages] = useState<PhonePackage[]>([]);
  const [routingConfig, setRoutingConfig] = useState<RoutingConfig | null>(null);
  const [subscription, setSubscription] = useState<PhoneSubscription | null>(null);
  const [loading, setLoading] = useState(true);
  const [tenantId, setTenantId] = useState<string | null>(null);

  const loadData = useCallback(async () => {
    try {
      setLoading(true);

      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      const { data: profile } = await supabase
        .from('profiles')
        .select('tenant_id')
        .eq('id', user.id)
        .single();

      if (!profile?.tenant_id) return;
      setTenantId(profile.tenant_id);

      // Carregar assinatura ativa
      const { data: activeSub } = await supabase
        .from('phone_number_subscriptions')
        .select(`
          *,
          package:phone_number_packages(*)
        `)
        .eq('tenant_id', profile.tenant_id)
        .in('status', ['active', 'pending', 'cancellation_scheduled'])
        .maybeSingle();

      if (activeSub) {
        setSubscription({
          ...activeSub,
          package: activeSub.package
        } as unknown as PhoneSubscription);
      } else {
        setSubscription(null);
      }

      // Carregar alocações com números
      const { data: allocs } = await supabase
        .from('tenant_phone_allocations')
        .select(`
          *,
          phone_number:whatsapp_phone_numbers(*)
        `)
        .eq('tenant_id', profile.tenant_id)
        .neq('status', 'cancelled');

      setAllocations(allocs || []);

      // Carregar departamentos
      const { data: depts } = await supabase
        .from('tenant_whatsapp_departments')
        .select('*')
        .eq('tenant_id', profile.tenant_id)
        .eq('ativo', true)
        .order('ordem');

      setDepartments(depts || []);

      // Carregar configuração de roteamento
      const { data: routing } = await supabase
        .from('tenant_whatsapp_routing')
        .select('*')
        .eq('tenant_id', profile.tenant_id)
        .maybeSingle();

      setRoutingConfig(routing);

      // Carregar pacotes disponíveis
      const { data: pkgs } = await supabase
        .from('phone_number_packages')
        .select('*')
        .eq('ativo', true)
        .order('preco_mensal');

      setPackages(pkgs || []);

    } catch (error) {
      console.error('Error loading phone data:', error);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadData();
  }, [loadData]);

  const purchasePackage = async (packageId: string, departamentos: string[]) => {
    try {
      const { data, error } = await supabase.functions.invoke('criar-assinatura-numero', {
        body: { package_id: packageId, departamentos }
      });

      if (error) throw error;
      if (data.error) throw new Error(data.error);

      if (data.url) {
        window.open(data.url, '_blank');
      }
    } catch (error: any) {
      console.error('Error purchasing package:', error);
      toast.error(error.message || 'Erro ao processar compra');
    }
  };

  const cancelSubscription = async (motivo?: string) => {
    if (!subscription) {
      toast.error('Nenhuma assinatura ativa encontrada');
      return null;
    }

    try {
      const { data, error } = await supabase.functions.invoke('cancelar-assinatura-numero', {
        body: { 
          subscription_id: subscription.id, 
          motivo,
          confirma_termos: true
        }
      });

      if (error) throw error;
      if (data.error) throw new Error(data.error);

      toast.success(data.mensagem || 'Cancelamento agendado com sucesso');
      await loadData();
      return data;
    } catch (error: any) {
      console.error('Error cancelling subscription:', error);
      toast.error(error.message || 'Erro ao cancelar assinatura');
      return null;
    }
  };

  const createDepartment = async (nome: string, codigo: string, descricao?: string) => {
    if (!tenantId) return;

    try {
      const { error } = await supabase.from('tenant_whatsapp_departments').insert({
        tenant_id: tenantId,
        nome,
        codigo,
        descricao,
        ordem: departments.length
      });

      if (error) throw error;
      toast.success('Departamento criado');
      await loadData();
    } catch (error: any) {
      console.error('Error creating department:', error);
      toast.error(error.message || 'Erro ao criar departamento');
    }
  };

  const updateRoutingConfig = async (config: Partial<RoutingConfig>) => {
    if (!tenantId) return;

    try {
      const { error } = await supabase
        .from('tenant_whatsapp_routing')
        .upsert({
          tenant_id: tenantId,
          ...routingConfig,
          ...config
        }, { onConflict: 'tenant_id' });

      if (error) throw error;
      toast.success('Configuração atualizada');
      await loadData();
    } catch (error: any) {
      console.error('Error updating routing:', error);
      toast.error(error.message || 'Erro ao atualizar configuração');
    }
  };

  const usesSharedNumber = !subscription || subscription.status === 'cancelled' || subscription.status === 'expired';
  const hasExclusiveNumbers = subscription && ['active', 'cancellation_scheduled'].includes(subscription.status);
  const hasPendingSubscription = subscription?.status === 'pending';
  const isCancellationScheduled = subscription?.status === 'cancellation_scheduled';

  return {
    allocations,
    departments,
    packages,
    routingConfig,
    subscription,
    loading,
    usesSharedNumber,
    hasExclusiveNumbers,
    hasPendingSubscription,
    isCancellationScheduled,
    purchasePackage,
    cancelSubscription,
    createDepartment,
    updateRoutingConfig,
    reload: loadData
  };
}

