import { EditAppointmentDialog } from "@/components/schedule/EditAppointmentDialog";
import { NextDayPreview } from "@/components/schedule/NextDayPreview";
import { MonthlyCalendar } from "@/components/schedule/MonthlyCalendar";
import { DigitalClock } from "@/components/schedule/DigitalClock";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Calendar as CalendarComponent } from "@/components/ui/calendar";
import { Plus, Filter, Search, Calendar, ChevronLeft, ChevronRight } from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { format, addDays, subDays, startOfDay, endOfDay, isToday, isValid } from "date-fns";
import { ptBR } from "date-fns/locale";
import { cn } from "@/lib/utils";
import { detectConflict, calculateAdjustments } from "@/lib/scheduleConflicts";
import { useAgendaDia } from "@/hooks/data/useAgendaDia";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";

const Agenda = () => {
  const [viewMode, setViewMode] = useState<"cards" | "timeline">("timeline");
  const [appointments, setAppointments] = useState<any[]>([]);
  const [appointmentsWithConflicts, setAppointmentsWithConflicts] = useState<any[]>([]);
  const [nextDayAppointments, setNextDayAppointments] = useState<any[]>([]);


  const [selectedDate, setSelectedDate] = useState<Date>(new Date());
  const [editingAppointmentId, setEditingAppointmentId] = useState<string | null>(null);
  const [deletingAppointmentId, setDeletingAppointmentId] = useState<string | null>(null);
  const [rescheduleDialogOpen, setRescheduleDialogOpen] = useState(false);
  const [rescheduleAppointmentId, setRescheduleAppointmentId] = useState<string | null>(null);
  const [rescheduleTime, setRescheduleTime] = useState("");
  const [conflictAdjustDialogOpen, setConflictAdjustDialogOpen] = useState(false);
  const [conflictAdjustData, setConflictAdjustData] = useState<{
    appointmentId: string;
    newTime: string;
    affectedCount: number;
  } | null>(null);
  const [newAppointmentDialogOpen, setNewAppointmentDialogOpen] = useState(false);
  const [newAppointmentTime, setNewAppointmentTime] = useState("");
  const { toast } = useToast();

  const { data: appointmentsData, isLoading: isLoadingAppointments, refetch: refetchAppointments } = useAgendaDia({
    date: selectedDate
  });

  const { data: nextDayData, isLoading: isLoadingNextDay } = useAgendaDia({
    date: addDays(selectedDate, 1)
  });

  useEffect(() => {
    if (appointmentsData) {
      const formattedAppointments = appointmentsData.map((apt: any) => {
        const inicioDate = apt?.inicio ? new Date(apt.inicio) : null;
        const fimDate = apt?.fim ? new Date(apt.fim) : null;

        const safeTime = inicioDate && isValid(inicioDate)
          ? format(inicioDate, 'HH:mm')
          : '--:--';

        const safeDuration = (inicioDate && fimDate && isValid(inicioDate) && isValid(fimDate))
          ? Math.round((fimDate.getTime() - inicioDate.getTime()) / 60000)
          : 30; // default de 30 min

        return {
          id: apt.id,
          patientName: apt.pacientes?.nome || 'Paciente',
          time: safeTime,
          doctor: apt.profiles?.nome || 'Profissional',
          status: apt.status || 'pending',
          phone: apt.pacientes?.telefone || '',
          duration: safeDuration,
          duration: safeDuration,
          ordem: apt.ordem,
          inicio: apt.inicio,
          riskLevel: apt.no_show_risk_level
        };
      });

      setAppointments(formattedAppointments);

      // Detectar conflitos
      const withConflicts = formattedAppointments.map((apt: any) => {
        const aptInicio = new Date(apt.inicio);
        const aptFim = new Date(aptInicio);
        aptFim.setMinutes(aptInicio.getMinutes() + apt.duration);

        const conflict = detectConflict(
          apt.id,
          aptInicio,
          aptFim,
          formattedAppointments
        );

        return {
          ...apt,
          hasConflict: !!conflict,
          conflictMinutes: conflict?.overlapMinutes || 0
        };
      });

      setAppointmentsWithConflicts(withConflicts);
    }
  }, [appointmentsData]);

  useEffect(() => {
    if (nextDayData) {
      const formattedAppointments = nextDayData.map((apt: any) => {
        const inicioDate = apt?.inicio ? new Date(apt.inicio) : null;
        const fimDate = apt?.fim ? new Date(apt.fim) : null;

        const safeTime = inicioDate && isValid(inicioDate)
          ? format(inicioDate, 'HH:mm')
          : '--:--';

        const safeDuration = (inicioDate && fimDate && isValid(inicioDate) && isValid(fimDate))
          ? Math.round((fimDate.getTime() - inicioDate.getTime()) / 60000)
          : 30;

        return {
          id: apt.id,
          patientName: apt.pacientes?.nome || 'Paciente',
          time: safeTime,
          doctor: apt.profiles?.nome || 'Profissional',
          status: apt.status || 'pending',
          phone: apt.pacientes?.telefone || '',
          duration: safeDuration,
          ordem: apt.ordem,
          inicio: apt.inicio
        };
      });

      setNextDayAppointments(formattedAppointments);
    }
  }, [nextDayData]);

  // Configurar realtime
  useEffect(() => {
    const channel = supabase
      .channel('agenda-changes')
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'agenda'
        },
        (payload) => {
          console.log('Mudança na agenda:', payload);
          // Usar um pequeno delay para evitar múltiplas chamadas simultâneas
          setTimeout(() => {
            // Invalidate queries to trigger refetch
            refetchAppointments();
          }, 100);
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [selectedDate]);

  // Recarregar dados ao trocar de visualização ou data
  // useEffect(() => {
  //   fetchAppointments();
  //   fetchNextDayAppointments();
  // }, [viewMode, selectedDate]);

  const handlePreviousDay = () => {
    setSelectedDate(prev => subDays(prev, 1));
  };

  const handleNextDay = () => {
    setSelectedDate(prev => addDays(prev, 1));
  };

  const handleNavigateToNextDay = () => {
    setSelectedDate(prev => addDays(prev, 1));
  };

  const handleToday = () => {
    setSelectedDate(new Date());
  };

  const getPageTitle = () => {
    if (isToday(selectedDate)) {
      return "Agenda de Hoje";
    }
    const dayName = format(selectedDate, "EEEE", { locale: ptBR });
    const formattedDate = format(selectedDate, "dd/MM/yyyy", { locale: ptBR });
    const capitalizedDay = dayName.charAt(0).toUpperCase() + dayName.slice(1);
    return `Agenda do dia ${formattedDate} - ${capitalizedDay}`;
  };

  const timeSlots = [
    { id: "slot-08:00", time: "08:00" },
    { id: "slot-08:30", time: "08:30" },
    { id: "slot-09:00", time: "09:00" },
    { id: "slot-09:30", time: "09:30" },
    { id: "slot-10:00", time: "10:00" },
    { id: "slot-10:30", time: "10:30" },
    { id: "slot-11:00", time: "11:00" },
    { id: "slot-11:30", time: "11:30" },
    { id: "slot-12:00", time: "12:00" },
    { id: "slot-12:30", time: "12:30" },
    { id: "slot-13:00", time: "13:00" },
    { id: "slot-13:30", time: "13:30" },
    { id: "slot-14:00", time: "14:00" },
    { id: "slot-14:30", time: "14:30" },
    { id: "slot-15:00", time: "15:00" },
    { id: "slot-15:30", time: "15:30" },
    { id: "slot-16:00", time: "16:00" },
    { id: "slot-16:30", time: "16:30" },
    { id: "slot-17:00", time: "17:00" },
    { id: "slot-17:30", time: "17:30" },
  ];

  const handleAppointmentMove = async (appointmentId: string, newTime: string) => {
    try {
      const appointment = appointments.find(app => app.id === appointmentId);
      if (!appointment) return;

      const [hours, minutes] = newTime.split(':');
      const newInicio = new Date(appointment.inicio);
      newInicio.setHours(parseInt(hours), parseInt(minutes), 0, 0);

      const newFim = new Date(newInicio);
      newFim.setMinutes(newInicio.getMinutes() + appointment.duration);

      // Validar se o horário já passou
      const now = new Date();
      if (newInicio < now) {
        toast({
          title: "Horário inválido",
          description: "Não é possível mover um agendamento para um horário que já passou.",
          variant: "destructive"
        });
        return;
      }

      // Detectar conflitos de horário
      const conflictingAppointments = appointments.filter(app => {
        if (app.id === appointmentId) return false;

        const appInicio = new Date(app.inicio);
        const appFim = new Date(appInicio);
        appFim.setMinutes(appInicio.getMinutes() + app.duration);

        // Verificar se há sobreposição
        return (newInicio < appFim && newFim > appInicio);
      });

      // Atualização otimista - atualizar UI imediatamente
      const updatedAppointments = appointments.map(app => {
        if (app.id === appointmentId) {
          return {
            ...app,
            time: newTime,
            inicio: newInicio.toISOString()
          };
        }
        return app;
      });

      // Reajustar appointments conflitantes
      let adjustedAppointments = [...updatedAppointments];
      const dbUpdates: Array<{ id: string, inicio: string, fim: string }> = [
        { id: appointmentId, inicio: newInicio.toISOString(), fim: newFim.toISOString() }
      ];

      if (conflictingAppointments.length > 0) {
        let nextAvailableTime = new Date(newFim);

        for (const conflicting of conflictingAppointments) {
          const conflictInicio = nextAvailableTime;
          const conflictFim = new Date(nextAvailableTime);
          conflictFim.setMinutes(conflictInicio.getMinutes() + conflicting.duration);

          // Atualizar no estado local
          adjustedAppointments = adjustedAppointments.map(app => {
            if (app.id === conflicting.id) {
              return {
                ...app,
                time: format(conflictInicio, 'HH:mm'),
                inicio: conflictInicio.toISOString()
              };
            }
            return app;
          });

          // Adicionar às atualizações do banco
          dbUpdates.push({
            id: conflicting.id,
            inicio: conflictInicio.toISOString(),
            fim: conflictFim.toISOString()
          });

          nextAvailableTime = conflictFim;
        }
      }

      // Atualizar UI imediatamente (otimista)
      setAppointments(adjustedAppointments);

      // Atualizar também appointmentsWithConflicts para refletir mudança imediata
      const updatedWithConflicts = adjustedAppointments.map(apt => {
        const aptInicio = new Date(apt.inicio);
        const aptFim = new Date(aptInicio);
        aptFim.setMinutes(aptInicio.getMinutes() + apt.duration);

        const conflict = detectConflict(
          apt.id,
          aptInicio,
          aptFim,
          adjustedAppointments
        );

        return {
          ...apt,
          hasConflict: !!conflict,
          conflictMinutes: conflict?.overlapMinutes || 0
        };
      });
      setAppointmentsWithConflicts(updatedWithConflicts);

      // Salvar todas as mudanças no banco
      for (const update of dbUpdates) {
        const { error } = await supabase
          .from('agenda')
          .update({
            inicio: update.inicio,
            fim: update.fim
          })
          .eq('id', update.id);

        if (error) throw error;
      }

      toast({
        title: "Sucesso",
        description: conflictingAppointments.length > 0
          ? `Horário atualizado! ${conflictingAppointments.length} consulta(s) reajustada(s).`
          : "Horário atualizado com sucesso!"
      });
    } catch (error) {
      console.error('Erro ao mover agendamento:', error);
      toast({
        title: "Erro",
        description: "Não foi possível atualizar o horário.",
        variant: "destructive"
      });
      // Reverter para estado do banco
      refetchAppointments();
    }
  };

  const handleCardReorder = async (appointmentId: string, targetId: string) => {
    // Abrir diálogo para solicitar novo horário
    setRescheduleAppointmentId(appointmentId);
    setRescheduleDialogOpen(true);
  };

  const handleEmptySlotClick = (time: string) => {
    setNewAppointmentTime(time);
    setNewAppointmentDialogOpen(true);
  };

  const handleResolveConflict = async (appointmentId: string) => {
    const appointment = appointmentsWithConflicts.find(apt => apt.id === appointmentId);
    if (!appointment) return;

    // Mostrar dialog para ajustar horário
    setConflictAdjustData({
      appointmentId,
      newTime: appointment.time,
      affectedCount: 0 // Calculado ao confirmar
    });
    setRescheduleTime(appointment.time);
    setConflictAdjustDialogOpen(true);
  };

  const handleConfirmConflictAdjust = async () => {
    if (!conflictAdjustData || !rescheduleTime) return;

    try {
      const appointment = appointments.find(app => app.id === conflictAdjustData.appointmentId);
      if (!appointment) return;

      const [hours, minutes] = rescheduleTime.split(':');
      const newInicio = new Date(appointment.inicio);
      newInicio.setHours(parseInt(hours), parseInt(minutes), 0, 0);

      // Calcular ajustes necessários
      const adjustments = calculateAdjustments(
        conflictAdjustData.appointmentId,
        newInicio,
        appointment.duration,
        appointments
      );

      // Se há ajustes necessários e o usuário não viu o aviso ainda
      if (adjustments.length > 0 && conflictAdjustData.affectedCount === 0) {
        setConflictAdjustData({
          ...conflictAdjustData,
          affectedCount: adjustments.length
        });
        return; // Mostrar aviso primeiro
      }

      // Aplicar ajustes
      const updates = [
        {
          id: conflictAdjustData.appointmentId,
          inicio: newInicio,
          fim: new Date(newInicio.getTime() + appointment.duration * 60000)
        },
        ...adjustments
      ];

      // Atualizar no banco
      for (const update of updates) {
        const { error } = await supabase
          .from('agenda')
          .update({
            inicio: update.inicio.toISOString(),
            fim: update.fim.toISOString()
          })
          .eq('id', update.id);

        if (error) throw error;
      }

      toast({
        title: "Sucesso",
        description: `Horário ajustado. ${adjustments.length > 0 ? `${adjustments.length} agendamento(s) posterior(es) também foram ajustados.` : ''}`
      });

      // Recarregar
      refetchAppointments();
      setConflictAdjustDialogOpen(false);
      setConflictAdjustData(null);
      setRescheduleTime("");
    } catch (error) {
      console.error('Erro ao ajustar horários:', error);
      toast({
        title: "Erro",
        description: "Não foi possível ajustar os horários.",
        variant: "destructive"
      });
    }
  };

  const handleConfirmReschedule = async () => {
    if (!rescheduleAppointmentId || !rescheduleTime) {
      toast({
        title: "Erro",
        description: "Por favor, informe o novo horário.",
        variant: "destructive"
      });
      return;
    }

    try {
      const appointment = appointments.find(app => app.id === rescheduleAppointmentId);
      if (!appointment) return;

      const [hours, minutes] = rescheduleTime.split(':');
      const newInicio = new Date(appointment.inicio);
      newInicio.setHours(parseInt(hours), parseInt(minutes), 0, 0);

      const newFim = new Date(newInicio);
      newFim.setMinutes(newInicio.getMinutes() + appointment.duration);

      // Validar se o horário já passou
      const now = new Date();
      if (newInicio < now) {
        toast({
          title: "Horário inválido",
          description: "Não é possível reagendar para um horário que já passou.",
          variant: "destructive"
        });
        return;
      }

      // Atualizar no banco
      const { error } = await supabase
        .from('agenda')
        .update({
          inicio: newInicio.toISOString(),
          fim: newFim.toISOString()
        })
        .eq('id', rescheduleAppointmentId);

      if (error) throw error;

      // Atualizar UI
      setAppointments(prev => prev.map(app => {
        if (app.id === rescheduleAppointmentId) {
          return {
            ...app,
            time: rescheduleTime,
            inicio: newInicio.toISOString()
          };
        }
        return app;
      }));

      toast({
        title: "Sucesso",
        description: "Horário atualizado com sucesso!"
      });

      // Fechar diálogo e limpar estado
      setRescheduleDialogOpen(false);
      setRescheduleAppointmentId(null);
      setRescheduleTime("");
    } catch (error) {
      console.error('Erro ao reagendar:', error);
      toast({
        title: "Erro",
        description: "Não foi possível atualizar o horário.",
        variant: "destructive"
      });
    }
  };

  const handleDelete = async () => {
    if (!deletingAppointmentId) return;

    try {
      const { error } = await supabase
        .from('agenda')
        .delete()
        .eq('id', deletingAppointmentId);

      if (error) throw error;

      // Atualizar UI imediatamente
      setAppointments(prev => prev.filter(app => app.id !== deletingAppointmentId));

      toast({
        title: "Sucesso",
        description: "Agendamento excluído com sucesso!"
      });
    } catch (error) {
      console.error('Erro ao excluir agendamento:', error);
      toast({
        title: "Erro",
        description: "Não foi possível excluir o agendamento.",
        variant: "destructive"
      });
    } finally {
      setDeletingAppointmentId(null);
    }
  };

  return (
    <MainLayout>
      <div className="space-y-6">
        <div className="flex items-center justify-between flex-wrap gap-4">
          <div>
            <h1 className="text-3xl font-bold text-foreground">{getPageTitle()}</h1>
            <p className="text-muted-foreground">
              Gerenciar consultas e horários
            </p>
          </div>
        </div>

        <div className="flex items-center justify-between flex-wrap gap-4">
          <div className="flex items-center gap-2">
            <Button
              variant="outline"
              size="icon"
              onClick={handlePreviousDay}
              title="Dia anterior"
            >
              <ChevronLeft className="h-4 w-4" />
            </Button>

            <Popover>
              <PopoverTrigger asChild>
                <Button variant="outline" className="min-w-[200px]">
                  <Calendar className="h-4 w-4 mr-2" />
                  {format(selectedDate, "dd/MM/yyyy - EEEE", { locale: ptBR })}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0" align="start">
                <CalendarComponent
                  mode="single"
                  selected={selectedDate}
                  onSelect={(date) => date && setSelectedDate(date)}
                  initialFocus
                  locale={ptBR}
                  className={cn("p-3 pointer-events-auto")}
                />
              </PopoverContent>
            </Popover>

            <Button
              variant="outline"
              size="icon"
              onClick={handleNextDay}
              title="Próximo dia"
            >
              <ChevronRight className="h-4 w-4" />
            </Button>

            {!isToday(selectedDate) && (
              <Button
                variant="outline"
                onClick={handleToday}
              >
                Hoje
              </Button>
            )}
          </div>

          <div className="flex gap-2">
            <Button
              variant={viewMode === "timeline" ? "default" : "outline"}
              size="sm"
              onClick={() => setViewMode("timeline")}
            >
              <Calendar className="h-4 w-4 mr-2" />
              Timeline
            </Button>
            <Button
              variant={viewMode === "cards" ? "default" : "outline"}
              size="sm"
              onClick={() => setViewMode("cards")}
            >
              Cards
            </Button>
          </div>

          <div className="flex gap-3">
            <Button variant="outline">
              <Filter className="h-4 w-4 mr-2" />
              Filtros
            </Button>
            <Button variant="outline">
              <Search className="h-4 w-4 mr-2" />
              Buscar
            </Button>
            <NewAppointmentDialog
              selectedDate={selectedDate}
              onSuccess={() => refetchAppointments()}
              open={newAppointmentDialogOpen}
              onOpenChange={(open) => {
                setNewAppointmentDialogOpen(open);
                if (!open) setNewAppointmentTime("");
              }}
              selectedTime={newAppointmentTime}
            >
              <Button>
                <Plus className="h-4 w-4 mr-2" />
                Nova Consulta
              </Button>
            </NewAppointmentDialog>
          </div>
        </div>

        {isLoadingAppointments ? (
          <div className="flex items-center justify-center p-12">
            <div className="text-center">
              <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary mx-auto mb-4"></div>
              <p className="text-muted-foreground">Carregando agendamentos...</p>
            </div>
          </div>
        ) : (
          <div className="grid grid-cols-1 xl:grid-cols-[350px_1fr_400px] lg:grid-cols-[320px_1fr] gap-6">
            {/* Coluna Esquerda - Calendário Mensal */}
            <div className="lg:sticky lg:top-6 lg:self-start">
              <MonthlyCalendar
                selectedDate={selectedDate}
                onDateSelect={setSelectedDate}
              />
            </div>

            {/* Coluna Central - Agenda do Dia */}
            <div>
              {viewMode === "timeline" ? (
                <>
                  <div className="mb-4 p-4 bg-muted rounded-lg">
                    <p className="text-sm text-muted-foreground">
                      <strong>Arrastar e Soltar:</strong> Arraste os agendamentos para reorganizar os horários.
                      As alterações serão salvas automaticamente.
                    </p>
                  </div>
                  <DragSchedule
                    appointments={appointmentsWithConflicts}
                    timeSlots={timeSlots}
                    onAppointmentMove={handleAppointmentMove}
                    viewMode="timeline"
                    onEdit={setEditingAppointmentId}
                    onDelete={setDeletingAppointmentId}
                    onResolveConflict={handleResolveConflict}
                    onEmptySlotClick={handleEmptySlotClick}
                    selectedDate={selectedDate}
                  />
                </>
              ) : (
                <>
                  <div className="mb-4 p-4 bg-muted rounded-lg">
                    <p className="text-sm text-muted-foreground">
                      <strong>Arrastar e Soltar:</strong> Arraste os cards para reorganizar a ordem dos agendamentos.
                    </p>
                  </div>
                  <DragSchedule
                    appointments={appointmentsWithConflicts}
                    timeSlots={[]}
                    onAppointmentMove={handleAppointmentMove}
                    onCardReorder={handleCardReorder}
                    viewMode="cards"
                    onEdit={setEditingAppointmentId}
                    onDelete={setDeletingAppointmentId}
                    onResolveConflict={handleResolveConflict}
                    selectedDate={selectedDate}
                  />
                </>
              )}
            </div>

            {/* Coluna Direita - Preview do Próximo Dia e Relógio (apenas em telas XL) */}
            <div className="hidden xl:block xl:sticky xl:top-6 xl:self-start space-y-4">
              <NextDayPreview
                date={addDays(selectedDate, 1)}
                appointments={nextDayAppointments}
                onNavigate={handleNavigateToNextDay}
                isLoading={isLoadingNextDay}
              />
              <DigitalClock />
            </div>
          </div>
        )}
      </div>

      {editingAppointmentId && (
        <EditAppointmentDialog
          appointmentId={editingAppointmentId}
          onSuccess={() => {
            fetchAppointments();
            fetchNextDayAppointments();
            setEditingAppointmentId(null);
          }}
        >
          <Button style={{ display: 'none' }} />
        </EditAppointmentDialog>
      )}

      <AlertDialog open={!!deletingAppointmentId} onOpenChange={() => setDeletingAppointmentId(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Confirmar Exclusão</AlertDialogTitle>
            <AlertDialogDescription>
              Tem certeza que deseja excluir este agendamento? Esta ação não pode ser desfeita.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancelar</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">
              Excluir
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Dialog de ajuste de conflito */}
      <AlertDialog open={conflictAdjustDialogOpen} onOpenChange={setConflictAdjustDialogOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Ajustar Horário Conflitante</AlertDialogTitle>
            <AlertDialogDescription>
              {conflictAdjustData?.affectedCount === 0 ? (
                <>
                  <p className="mb-4">Ajuste o horário deste agendamento para resolver o conflito:</p>
                  <Input
                    type="time"
                    value={rescheduleTime}
                    onChange={(e) => setRescheduleTime(e.target.value)}
                    className="mb-2"
                  />
                </>
              ) : (
                <p>
                  Este ajuste afetará <strong>{conflictAdjustData?.affectedCount}</strong> agendamento(s) posterior(es),
                  que serão automaticamente remarcados. Deseja continuar?
                </p>
              )}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel onClick={() => {
              setConflictAdjustDialogOpen(false);
              setConflictAdjustData(null);
              setRescheduleTime("");
            }}>
              Cancelar
            </AlertDialogCancel>
            <AlertDialogAction onClick={handleConfirmConflictAdjust}>
              {conflictAdjustData?.affectedCount === 0 ? "Verificar Ajuste" : "Confirmar Alterações"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      <AlertDialog open={rescheduleDialogOpen} onOpenChange={setRescheduleDialogOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Novo Horário</AlertDialogTitle>
            <AlertDialogDescription>
              Informe o novo horário para este agendamento:
            </AlertDialogDescription>
          </AlertDialogHeader>
          <div className="py-4">
            <input
              type="time"
              value={rescheduleTime}
              onChange={(e) => setRescheduleTime(e.target.value)}
              className="w-full px-3 py-2 border border-border rounded-md bg-background text-foreground"
            />
          </div>
          <AlertDialogFooter>
            <AlertDialogCancel onClick={() => {
              setRescheduleDialogOpen(false);
              setRescheduleAppointmentId(null);
              setRescheduleTime("");
            }}>
              Cancelar
            </AlertDialogCancel>
            <AlertDialogAction onClick={handleConfirmReschedule}>
              Confirmar
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </MainLayout>
  );
};

export default Agenda;

import { useState, useEffect } from "react";
import { useSearchParams } from "react-router-dom";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Calendar } from "@/components/ui/calendar";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";
import { Calendar as CalendarIcon, Clock, User, Phone, Mail, CheckCircle } from "lucide-react";
import { LandingHeader } from "@/components/landing/LandingHeader";
import { LandingFooter } from "@/components/landing/LandingFooter";

export default function AgendamentoPublico() {
  const [searchParams] = useSearchParams();
  const tenantSlug = searchParams.get('clinica');

  const [step, setStep] = useState<'select-service' | 'select-datetime' | 'fill-data' | 'confirm'>('select-service');
  const [loading, setLoading] = useState(true);
  const [services, setServices] = useState<any[]>([]);
  const [professionals, setProfessionals] = useState<any[]>([]);
  const [availableSlots, setAvailableSlots] = useState<any[]>([]);

  const [selectedService, setSelectedService] = useState<any>(null);
  const [selectedProfessional, setSelectedProfessional] = useState<any>(null);
  const [selectedDate, setSelectedDate] = useState<Date | undefined>(undefined);
  const [selectedSlot, setSelectedSlot] = useState<string>("");

  const [patientData, setPatientData] = useState({
    nome: "",
    telefone: "",
    email: "",
    notas: "",
  });

  const [tenantId, setTenantId] = useState<string | null>(null);

  useEffect(() => {
    loadTenantAndServices();
  }, [tenantSlug]);

  const loadTenantAndServices = async () => {
    try {
      setLoading(true);

      // Buscar configuração de agendamento online pelo slug
      const { data: config, error: configError } = await supabase
        .from('agendamento_online_config')
        .select('*, tenants(*)')
        .eq('slug_publico', tenantSlug)
        .eq('ativo', true)
        .single();

      if (configError || !config) {
        toast.error('Link de agendamento não encontrado ou inativo');
        return;
      }

      setTenantId(config.tenant_id);

      // Buscar serviços disponíveis
      const { data: servicesData } = await supabase
        .from('servicos')
        .select('*')
        .eq('tenant_id', config.tenant_id)
        .eq('ativo', true);

      setServices(servicesData || []);

      // Buscar profissionais
      const { data: profsData } = await supabase
        .from('profiles')
        .select('*')
        .eq('tenant_id', config.tenant_id)
        .in('role', ['profissional', 'admin']);

      setProfessionals(profsData || []);
    } catch (error) {
      console.error('Erro ao carregar dados:', error);
      toast.error('Erro ao carregar informações de agendamento');
    } finally {
      setLoading(false);
    }
  };

  const loadAvailableSlots = async () => {
    if (!selectedDate || !selectedService || !selectedProfessional) return;

    try {
      // Buscar horários já ocupados
      const startOfDay = new Date(selectedDate);
      startOfDay.setHours(0, 0, 0, 0);

      const endOfDay = new Date(selectedDate);
      endOfDay.setHours(23, 59, 59, 999);

      const { data: appointments } = await supabase
        .from('agenda')
        .select('inicio, fim')
        .eq('profissional_id', selectedProfessional.id)
        .gte('inicio', startOfDay.toISOString())
        .lte('inicio', endOfDay.toISOString());

      // Gerar slots disponíveis (8h às 18h, a cada 30 min)
      const slots = [];
      const startHour = 8;
      const endHour = 18;

      for (let hour = startHour; hour < endHour; hour++) {
        for (const minute of [0, 30]) {
          const slotTime = new Date(selectedDate);
          slotTime.setHours(hour, minute, 0, 0);

          const slotEndTime = new Date(slotTime);
          slotEndTime.setMinutes(slotEndTime.getMinutes() + selectedService.duracao_minutos);

          // Verificar se está ocupado
          const isOccupied = appointments?.some((apt: any) => {
            const aptStart = new Date(apt.inicio);
            const aptEnd = new Date(apt.fim);
            return (slotTime >= aptStart && slotTime < aptEnd) ||
              (slotEndTime > aptStart && slotEndTime <= aptEnd);
          });

          if (!isOccupied && slotTime > new Date()) {
            slots.push({
              time: slotTime.toTimeString().slice(0, 5),
              datetime: slotTime,
            });
          }
        }
      }

      setAvailableSlots(slots);
    } catch (error) {
      console.error('Erro ao carregar horários:', error);
      toast.error('Erro ao carregar horários disponíveis');
    }
  };

  useEffect(() => {
    if (selectedDate && selectedService && selectedProfessional) {
      loadAvailableSlots();
    }
  }, [selectedDate, selectedService, selectedProfessional]);

  const handleConfirmAppointment = async () => {
    try {
      if (!selectedSlot || !selectedDate || !tenantId) return;

      // Criar ou buscar paciente
      let patientId;

      const { data: existingPatient } = await supabase
        .from('pacientes')
        .select('id')
        .eq('tenant_id', tenantId)
        .eq('telefone', patientData.telefone)
        .single();

      if (existingPatient) {
        patientId = existingPatient.id;
      } else {
        const { data: newPatient, error: patientError } = await supabase
          .from('pacientes')
          .insert({
            tenant_id: tenantId,
            nome: patientData.nome,
            telefone: patientData.telefone,
            email: patientData.email,
            notas_internas: patientData.notas,
            consentimento_lgpd: true,
            consentimento_data: new Date().toISOString(),
          })
          .select()
          .single();

        if (patientError) throw patientError;
        patientId = newPatient.id;
      }

      // Criar agendamento
      const [hours, minutes] = selectedSlot.split(':').map(Number);
      const startTime = new Date(selectedDate);
      startTime.setHours(hours, minutes, 0, 0);

      const endTime = new Date(startTime);
      endTime.setMinutes(endTime.getMinutes() + selectedService.duracao_minutos);

      const { error: agendamentoError } = await supabase
        .from('agenda')
        .insert({
          tenant_id: tenantId,
          paciente_id: patientId,
          profissional_id: selectedProfessional.id,
          servico_id: selectedService.id,
          inicio: startTime.toISOString(),
          fim: endTime.toISOString(),
          status: 'agendado',
          origem: 'online',
          confirmado: false,
        });

      if (agendamentoError) throw agendamentoError;

      // Registrar consentimento
      await supabase.from('consent_records' as any).insert({
        tenant_id: tenantId,
        contact_id: patientId,
        contact_type: 'paciente',
        consent_type: 'operational',
        status: 'opted_in',
        origin: 'agendamento_online',
        term_version: '1.0',
        given_at: new Date().toISOString(),
      });

      setStep('confirm');
      toast.success('Agendamento realizado com sucesso!');
    } catch (error: any) {
      console.error('Erro ao confirmar agendamento:', error);
      toast.error('Erro ao realizar agendamento');
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
      </div>
    );
  }

  if (!tenantSlug || !tenantId) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <Card className="w-full max-w-md">
          <CardContent className="p-6">
            <p className="text-center text-muted-foreground">
              Link de agendamento inválido
            </p>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background">
      <LandingHeader />

      <main className="container mx-auto px-4 py-12">
        {step === 'confirm' ? (
          <Card className="max-w-2xl mx-auto">
            <CardContent className="p-12 text-center">
              <CheckCircle className="h-16 w-16 text-green-500 mx-auto mb-4" />
              <h2 className="text-2xl font-bold mb-2">Agendamento Confirmado!</h2>
              <p className="text-muted-foreground mb-4">
                Seu agendamento foi realizado com sucesso. Em breve você receberá uma confirmação por WhatsApp.
              </p>
              <div className="bg-muted p-4 rounded-lg mb-6">
                <p className="font-medium">{selectedService?.nome}</p>
                <p className="text-sm text-muted-foreground">
                  Dr(a). {selectedProfessional?.nome}
                </p>
                <p className="text-sm text-muted-foreground">
                  {selectedDate?.toLocaleDateString('pt-BR')} às {selectedSlot}
                </p>
              </div>
              <Button onClick={() => window.location.reload()}>
                Fazer Novo Agendamento
              </Button>
            </CardContent>
          </Card>
        ) : (
          <div className="max-w-4xl mx-auto">
            <Card>
              <CardHeader>
                <CardTitle className="text-2xl">Agendamento Online</CardTitle>
                <CardDescription>
                  Siga os passos para agendar sua consulta
                </CardDescription>
              </CardHeader>
              <CardContent>
                {/* Progress Steps */}
                <div className="flex justify-between mb-8">
                  {['Serviço', 'Data e Hora', 'Dados', 'Confirmar'].map((label, idx) => (
                    <div key={idx} className="flex items-center">
                      <div className={`w-8 h-8 rounded-full flex items-center justify-center ${['select-service', 'select-datetime', 'fill-data', 'confirm'][idx] === step
                        ? 'bg-primary text-white'
                        : 'bg-muted'
                        }`}>
                        {idx + 1}
                      </div>
                      <span className="ml-2 text-sm hidden sm:inline">{label}</span>
                    </div>
                  ))}
                </div>

                {step === 'select-service' && (
                  <div className="space-y-4">
                    <h3 className="font-semibold mb-4">Selecione o Serviço</h3>
                    <div className="grid gap-4">
                      {services.map((service) => (
                        <Card
                          key={service.id}
                          className={`cursor-pointer hover:border-primary transition-colors ${selectedService?.id === service.id ? 'border-primary' : ''
                            }`}
                          onClick={() => setSelectedService(service)}
                        >
                          <CardContent className="p-4">
                            <div className="flex justify-between items-start">
                              <div>
                                <h4 className="font-medium">{service.nome}</h4>
                                <p className="text-sm text-muted-foreground">
                                  {service.duracao_minutos} minutos
                                </p>
                              </div>
                              {service.preco && (
                                <Badge>R$ {service.preco}</Badge>
                              )}
                            </div>
                          </CardContent>
                        </Card>
                      ))}
                    </div>
                    <Button
                      onClick={() => setStep('select-datetime')}
                      disabled={!selectedService}
                      className="w-full"
                    >
                      Continuar
                    </Button>
                  </div>
                )}

                {step === 'select-datetime' && (
                  <div className="space-y-6">
                    <div>
                      <h3 className="font-semibold mb-4">Selecione o Profissional</h3>
                      <div className="grid gap-3">
                        {professionals.map((prof) => (
                          <Card
                            key={prof.id}
                            className={`cursor-pointer hover:border-primary transition-colors ${selectedProfessional?.id === prof.id ? 'border-primary' : ''
                              }`}
                            onClick={() => setSelectedProfessional(prof)}
                          >
                            <CardContent className="p-3 flex items-center gap-3">
                              <User className="h-8 w-8 text-muted-foreground" />
                              <div>
                                <p className="font-medium">Dr(a). {prof.nome}</p>
                              </div>
                            </CardContent>
                          </Card>
                        ))}
                      </div>
                    </div>

                    {selectedProfessional && (
                      <div>
                        <h3 className="font-semibold mb-4">Selecione a Data</h3>
                        <Calendar
                          mode="single"
                          selected={selectedDate}
                          onSelect={setSelectedDate}
                          disabled={(date) => date < new Date() || date.getDay() === 0}
                          className="rounded-md border mx-auto"
                        />
                      </div>
                    )}

                    {selectedDate && availableSlots.length > 0 && (
                      <div>
                        <h3 className="font-semibold mb-4">Horários Disponíveis</h3>
                        <div className="grid grid-cols-4 gap-2">
                          {availableSlots.map((slot) => (
                            <Button
                              key={slot.time}
                              variant={selectedSlot === slot.time ? "default" : "outline"}
                              onClick={() => setSelectedSlot(slot.time)}
                              className="text-sm"
                            >
                              {slot.time}
                            </Button>
                          ))}
                        </div>
                      </div>
                    )}

                    <div className="flex gap-2">
                      <Button variant="outline" onClick={() => setStep('select-service')}>
                        Voltar
                      </Button>
                      <Button
                        onClick={() => setStep('fill-data')}
                        disabled={!selectedSlot}
                        className="flex-1"
                      >
                        Continuar
                      </Button>
                    </div>
                  </div>
                )}

                {step === 'fill-data' && (
                  <div className="space-y-4">
                    <h3 className="font-semibold mb-4">Seus Dados</h3>
                    <div className="space-y-2">
                      <Label htmlFor="nome">Nome Completo *</Label>
                      <Input
                        id="nome"
                        value={patientData.nome}
                        onChange={(e) => setPatientData({ ...patientData, nome: e.target.value })}
                        required
                      />
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="telefone">Telefone (WhatsApp) *</Label>
                      <Input
                        id="telefone"
                        type="tel"
                        value={patientData.telefone}
                        onChange={(e) => setPatientData({ ...patientData, telefone: e.target.value })}
                        placeholder="(00) 00000-0000"
                        required
                      />
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="email">E-mail</Label>
                      <Input
                        id="email"
                        type="email"
                        value={patientData.email}
                        onChange={(e) => setPatientData({ ...patientData, email: e.target.value })}
                      />
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="notas">Observações</Label>
                      <Input
                        id="notas"
                        value={patientData.notas}
                        onChange={(e) => setPatientData({ ...patientData, notas: e.target.value })}
                        placeholder="Algo que o profissional deva saber..."
                      />
                    </div>
                    <div className="flex gap-2">
                      <Button variant="outline" onClick={() => setStep('select-datetime')}>
                        Voltar
                      </Button>
                      <Button
                        onClick={handleConfirmAppointment}
                        disabled={!patientData.nome || !patientData.telefone}
                        className="flex-1"
                      >
                        Confirmar Agendamento
                      </Button>
                    </div>
                  </div>
                )}
              </CardContent>
            </Card>
          </div>
        )}
      </main>

      <LandingFooter />
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { MainLayout } from "@/components/layout/MainLayout";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Calendar } from "@/components/ui/calendar";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { toast } from "sonner";
import {
    Plus, Bell, Clock, CheckCircle2, AlertCircle, Calendar as CalendarIcon,
    Trash2, Edit, Filter, TrendingUp
} from "lucide-react";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";

interface Alarme {
    id: string;
    titulo: string;
    descricao: string;
    tipo: 'alarme' | 'lembrete' | 'tarefa';
    prioridade: 'baixa' | 'media' | 'alta' | 'urgente';
    data_hora: string;
    concluido: boolean;
    ativo: boolean;
    canal_notificacao: string;
}

export default function AlarmesLembretes() {
    const { profile } = useAuth();
    const [alarmes, setAlarmes] = useState<Alarme[]>([]);
    const [filtroTipo, setFiltroTipo] = useState<string>('todos');
    const [filtroStatus, setFiltroStatus] = useState<string>('pendentes');
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        if (profile?.tenant_id) {
            loadAlarmes();
        }
    }, [profile?.tenant_id, filtroTipo, filtroStatus]);

    const loadAlarmes = async () => {
        try {
            setLoading(true);

            let query = supabase
                .from('alarmes_lembretes')
                .select('*')
                .eq('tenant_id', profile.tenant_id)
                .order('data_hora', { ascending: true });

            if (filtroTipo !== 'todos') {
                query = query.eq('tipo', filtroTipo);
            }

            if (filtroStatus === 'pendentes') {
                query = query.eq('concluido', false).eq('ativo', true);
            } else if (filtroStatus === 'concluidos') {
                query = query.eq('concluido', true);
            }

            const { data, error } = await query;

            if (error) throw error;
            setAlarmes(data || []);
        } catch (error) {
            console.error('Erro ao carregar alarmes:', error);
            toast.error('Erro ao carregar alarmes');
        } finally {
            setLoading(false);
        }
    };

    const handleCriarAlarme = async (data: Partial<Alarme>) => {
        try {
            const { error } = await supabase
                .from('alarmes_lembretes')
                .insert({
                    tenant_id: profile.tenant_id,
                    usuario_id: profile.id,
                    ...data
                });

            if (error) throw error;

            toast.success('Alarme criado com sucesso!');
            loadAlarmes();
        } catch (error) {
            toast.error('Erro ao criar alarme');
        }
    };

    const handleConcluir = async (id: string) => {
        try {
            const { error } = await supabase.rpc('marcar_alarme_concluido', {
                p_alarme_id: id,
                p_usuario_id: profile.id
            });

            if (error) throw error;

            toast.success('Alarme concluído!');
            loadAlarmes();
        } catch (error) {
            toast.error('Erro ao concluir alarme');
        }
    };

    const handleExcluir = async (id: string) => {
        try {
            const { error } = await supabase
                .from('alarmes_lembretes')
                .delete()
                .eq('id', id);

            if (error) throw error;

            toast.success('Alarme excluído!');
            loadAlarmes();
        } catch (error) {
            toast.error('Erro ao excluir alarme');
        }
    };

    const getTipoBadge = (tipo: string) => {
        const configs = {
            alarme: { color: 'bg-red-100 text-red-800', icon: AlertCircle, label: 'Alarme' },
            lembrete: { color: 'bg-blue-100 text-blue-800', icon: Bell, label: 'Lembrete' },
            tarefa: { color: 'bg-green-100 text-green-800', icon: CheckCircle2, label: 'Tarefa' }
        };

        const config = configs[tipo as keyof typeof configs] || configs.lembrete;
        const Icon = config.icon;

        return (
            <Badge className={config.color}>
                <Icon className="h-3 w-3 mr-1" />
                {config.label}
            </Badge>
        );
    };

    const getPrioridadeBadge = (prioridade: string) => {
        const colors = {
            baixa: 'bg-gray-100 text-gray-800',
            media: 'bg-yellow-100 text-yellow-800',
            alta: 'bg-orange-100 text-orange-800',
            urgente: 'bg-red-100 text-red-800'
        };

        return (
            <Badge className={colors[prioridade as keyof typeof colors] || colors.media}>
                {prioridade.toUpperCase()}
            </Badge>
        );
    };

    const isAtrasado = (dataHora: string) => {
        return new Date(dataHora) < new Date();
    };

    return (
        <MainLayout>
            <div className="container mx-auto p-6 space-y-6">
                {/* Header */}
                <div className="flex items-center justify-between">
                    <div>
                        <h1 className="text-2xl font-bold tracking-tight">Alarmes e Lembretes</h1>
                        <p className="text-muted-foreground">Gerencie seus alarmes, lembretes e tarefas</p>
                    </div>
                    <NovoAlarmeDialog onCreate={handleCriarAlarme} />
                </div>

                {/* Filtros */}
                <Card>
                    <CardContent className="pt-6">
                        <div className="flex gap-4">
                            <div className="flex-1">
                                <Label>Tipo</Label>
                                <Select value={filtroTipo} onValueChange={setFiltroTipo}>
                                    <SelectTrigger>
                                        <SelectValue />
                                    </SelectTrigger>
                                    <SelectContent>
                                        <SelectItem value="todos">Todos</SelectItem>
                                        <SelectItem value="alarme">Alarmes</SelectItem>
                                        <SelectItem value="lembrete">Lembretes</SelectItem>
                                        <SelectItem value="tarefa">Tarefas</SelectItem>
                                    </SelectContent>
                                </Select>
                            </div>
                            <div className="flex-1">
                                <Label>Status</Label>
                                <Select value={filtroStatus} onValueChange={setFiltroStatus}>
                                    <SelectTrigger>
                                        <SelectValue />
                                    </SelectTrigger>
                                    <SelectContent>
                                        <SelectItem value="pendentes">Pendentes</SelectItem>
                                        <SelectItem value="concluidos">Concluídos</SelectItem>
                                        <SelectItem value="todos">Todos</SelectItem>
                                    </SelectContent>
                                </Select>
                            </div>
                        </div>
                    </CardContent>
                </Card>

                {/* Lista de Alarmes */}
                <div className="space-y-3">
                    {loading ? (
                        <div className="text-center py-8">Carregando...</div>
                    ) : alarmes.length === 0 ? (
                        <Card>
                            <CardContent className="py-12 text-center">
                                <Bell className="h-12 w-12 mx-auto mb-4 text-muted-foreground opacity-50" />
                                <p className="text-muted-foreground">Nenhum alarme encontrado</p>
                            </CardContent>
                        </Card>
                    ) : (
                        alarmes.map((alarme) => (
                            <Card key={alarme.id} className={`${isAtrasado(alarme.data_hora) && !alarme.concluido ? 'border-red-300 bg-red-50/50' : ''
                                }`}>
                                <CardContent className="p-4">
                                    <div className="flex items-start justify-between">
                                        <div className="flex-1">
                                            <div className="flex items-center gap-2 mb-2">
                                                <h3 className="font-semibold">{alarme.titulo}</h3>
                                                {getTipoBadge(alarme.tipo)}
                                                {getPrioridadeBadge(alarme.prioridade)}
                                                {isAtrasado(alarme.data_hora) && !alarme.concluido && (
                                                    <Badge variant="destructive">Atrasado</Badge>
                                                )}
                                                {alarme.concluido && (
                                                    <Badge className="bg-green-100 text-green-800">
                                                        <CheckCircle2 className="h-3 w-3 mr-1" />
                                                        Concluído
                                                    </Badge>
                                                )}
                                            </div>

                                            {alarme.descricao && (
                                                <p className="text-sm text-muted-foreground mb-2">{alarme.descricao}</p>
                                            )}

                                            <div className="flex items-center gap-4 text-sm text-muted-foreground">
                                                <span className="flex items-center gap-1">
                                                    <CalendarIcon className="h-4 w-4" />
                                                    {format(new Date(alarme.data_hora), "dd/MM/yyyy 'às' HH:mm", { locale: ptBR })}
                                                </span>
                                                <span className="flex items-center gap-1">
                                                    <Bell className="h-4 w-4" />
                                                    {alarme.canal_notificacao}
                                                </span>
                                            </div>
                                        </div>

                                        <div className="flex gap-2">
                                            {!alarme.concluido && (
                                                <Button
                                                    size="sm"
                                                    variant="outline"
                                                    onClick={() => handleConcluir(alarme.id)}
                                                >
                                                    <CheckCircle2 className="h-4 w-4" />
                                                </Button>
                                            )}
                                            <Button
                                                size="sm"
                                                variant="ghost"
                                                onClick={() => handleExcluir(alarme.id)}
                                            >
                                                <Trash2 className="h-4 w-4" />
                                            </Button>
                                        </div>
                                    </div>
                                </CardContent>
                            </Card>
                        ))
                    )}
                </div>
            </div>
        </MainLayout>
    );
}

function NovoAlarmeDialog({ onCreate }: { onCreate: (data: any) => void }) {
    const [open, setOpen] = useState(false);
    const [titulo, setTitulo] = useState('');
    const [descricao, setDescricao] = useState('');
    const [tipo, setTipo] = useState('lembrete');
    const [prioridade, setPrioridade] = useState('media');
    const [data, setData] = useState<Date | undefined>(new Date());
    const [hora, setHora] = useState('09:00');
    const [canal, setCanal] = useState('sistema');

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();

        if (!data) {
            toast.error('Selecione uma data');
            return;
        }

        const [horas, minutos] = hora.split(':');
        const dataHora = new Date(data);
        dataHora.setHours(parseInt(horas), parseInt(minutos));

        onCreate({
            titulo,
            descricao,
            tipo,
            prioridade,
            data_hora: dataHora.toISOString(),
            canal_notificacao: canal
        });

        setOpen(false);
        setTitulo('');
        setDescricao('');
        setTipo('lembrete');
        setPrioridade('media');
        setData(new Date());
        setHora('09:00');
        setCanal('sistema');
    };

    return (
        <Dialog open={open} onOpenChange={setOpen}>
            <DialogTrigger asChild>
                <Button>
                    <Plus className="mr-2 h-4 w-4" /> Novo Alarme
                </Button>
            </DialogTrigger>
            <DialogContent className="max-w-2xl">
                <DialogHeader>
                    <DialogTitle>Criar Alarme/Lembrete</DialogTitle>
                </DialogHeader>
                <form onSubmit={handleSubmit} className="space-y-4">
                    <div>
                        <Label>Título</Label>
                        <Input
                            placeholder="Ex: Ligar para paciente"
                            value={titulo}
                            onChange={e => setTitulo(e.target.value)}
                            required
                        />
                    </div>

                    <div>
                        <Label>Descrição</Label>
                        <Textarea
                            placeholder="Detalhes adicionais..."
                            value={descricao}
                            onChange={e => setDescricao(e.target.value)}
                            rows={3}
                        />
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <Label>Tipo</Label>
                            <Select value={tipo} onValueChange={setTipo}>
                                <SelectTrigger>
                                    <SelectValue />
                                </SelectTrigger>
                                <SelectContent>
                                    <SelectItem value="alarme">Alarme (Urgente)</SelectItem>
                                    <SelectItem value="lembrete">Lembrete</SelectItem>
                                    <SelectItem value="tarefa">Tarefa</SelectItem>
                                </SelectContent>
                            </Select>
                        </div>

                        <div>
                            <Label>Prioridade</Label>
                            <Select value={prioridade} onValueChange={setPrioridade}>
                                <SelectTrigger>
                                    <SelectValue />
                                </SelectTrigger>
                                <SelectContent>
                                    <SelectItem value="baixa">Baixa</SelectItem>
                                    <SelectItem value="media">Média</SelectItem>
                                    <SelectItem value="alta">Alta</SelectItem>
                                    <SelectItem value="urgente">Urgente</SelectItem>
                                </SelectContent>
                            </Select>
                        </div>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <Label>Data</Label>
                            <Calendar
                                mode="single"
                                selected={data}
                                onSelect={setData}
                                locale={ptBR}
                                className="rounded-md border"
                            />
                        </div>

                        <div className="space-y-4">
                            <div>
                                <Label>Hora</Label>
                                <Input
                                    type="time"
                                    value={hora}
                                    onChange={e => setHora(e.target.value)}
                                    required
                                />
                            </div>

                            <div>
                                <Label>Canal de Notificação</Label>
                                <Select value={canal} onValueChange={setCanal}>
                                    <SelectTrigger>
                                        <SelectValue />
                                    </SelectTrigger>
                                    <SelectContent>
                                        <SelectItem value="sistema">Sistema</SelectItem>
                                        <SelectItem value="email">E-mail</SelectItem>
                                        <SelectItem value="whatsapp">WhatsApp</SelectItem>
                                        <SelectItem value="todos">Todos</SelectItem>
                                    </SelectContent>
                                </Select>
                            </div>
                        </div>
                    </div>

                    <div className="flex gap-2 justify-end">
                        <Button type="button" variant="outline" onClick={() => setOpen(false)}>
                            Cancelar
                        </Button>
                        <Button type="submit">
                            Criar Alarme
                        </Button>
                    </div>
                </form>
            </DialogContent>
        </Dialog>
    );
}

import React, { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
