  const handleSaveConfiguracoes = async () => {
    if (!profile?.tenant_id) return;

    if (!clinicData.razaoSocial.trim()) {
      toast({
        title: "Campo obrigatório",
        description: "A Razão Social é obrigatória.",
        variant: "destructive"
