                        )}
                        {exame.requisitos && (
                          <p className="text-muted-foreground"><strong>Requisitos:</strong> {exame.requisitos}</p>
                        )}
                      </div>
                    )}
                  </div>

                  <div className="flex sm:flex-col gap-2 justify-end">
                    <div className="flex items-center gap-2">
                      <Switch
                        checked={exame.ativo}
                        onCheckedChange={() => toggleStatus(exame.id, exame.ativo)}
                      />
                    </div>
                    <EditExameDialog
                      exameId={exame.id}
                      open={editingId === exame.id}
                      onOpenChange={(open) => setEditingId(open ? exame.id : null)}
                      onSuccess={fetchExames}
                    >
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => setEditingId(exame.id)}
                      >
                        <Edit className="h-4 w-4" />
                      </Button>
                    </EditExameDialog>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => deleteExame(exame.id)}
                    >
                      <Trash2 className="h-4 w-4 text-destructive" />
                    </Button>
                  </div>
                </div>
              </Card>
            ))}
          </div>
        )}

        {editingId && (
          <EditExameDialog
            exameId={editingId}
            open={true}
            onOpenChange={(open) => !open && setEditingId(null)}
            onSuccess={fetchExames}
          />
        )}
      </div>
    </MainLayout>
  );
};

export default Exames;

import React, { useState, useEffect } from "react";
import { MainLayout } from "@/components/layout/MainLayout";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Switch } from "@/components/ui/switch";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { 
  Edit, 
  Trash2, 
  Loader2,
  Search,
  FileText,
  Clock,
  DollarSign
} from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { NewExameProcedimentoDialog } from "@/components/schedule/NewExameProcedimentoDialog";
import { EditExameProcedimentoDialog } from "@/components/schedule/EditExameProcedimentoDialog";

interface ExameProcedimento {
  id: string;
  nome: string;
  tipo: string;
  codigo_tuss: string | null;
  descricao: string | null;
  tempo_preparo_minutos: number | null;
  tempo_jejum_horas: number | null;
  duracao_minutos: number | null;
  valor: number | null;
  instrucoes: string | null;
  requisitos: string | null;
  ativo: boolean;
  created_at: string;
}

const tipoLabels: Record<string, string> = {
  exame_laboratorial: "Exame Laboratorial",
  exame_imagem: "Exame de Imagem",
  procedimento_cirurgico: "Procedimento Cirúrgico",
  procedimento_terapeutico: "Procedimento Terapêutico",
  procedimento_diagnostico: "Procedimento Diagnóstico"
};

const ExamesProcedimentos = () => {
  const [items, setItems] = useState<ExameProcedimento[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [activeTab, setActiveTab] = useState("todos");
  const [editingId, setEditingId] = useState<string | null>(null);
  const { toast } = useToast();

  const fetchItems = async () => {
    try {
      setIsLoading(true);
      const { data, error } = await supabase
        .from('exames_procedimentos')
        .select('*')
        .order('nome');

      if (error) throw error;
      setItems(data || []);
    } catch (error) {
      console.error('Erro ao buscar:', error);
      toast({
        title: "Erro",
        description: "Não foi possível carregar os dados.",
        variant: "destructive"
      });
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchItems();
  }, []);

  const toggleStatus = async (id: string, currentStatus: boolean) => {
    try {
      const { error } = await supabase
        .from('exames_procedimentos')
        .update({ ativo: !currentStatus })
        .eq('id', id);

      if (error) throw error;

      setItems(prev => prev.map(item => 
        item.id === id ? { ...item, ativo: !currentStatus } : item
      ));

      toast({
        title: "Status atualizado",
        description: `Item ${!currentStatus ? "ativado" : "desativado"} com sucesso.`
      });
    } catch (error) {
      console.error('Erro ao atualizar status:', error);
      toast({
        title: "Erro",
        description: "Não foi possível atualizar o status.",
        variant: "destructive"
      });
    }
  };

  const deleteItem = async (id: string) => {
    // Importar validação
    const { validateExameProcedimentoDelete } = await import('@/lib/deleteValidation');

    // Validar antes de excluir
    const validation = await validateExameProcedimentoDelete(id);

    if (!validation.canDelete) {
      toast({
        title: "Não é possível excluir",
        description: validation.message,
        variant: "destructive",
        duration: 10000
      });
      return;
    }

    if (!confirm("Tem certeza que deseja excluir este item?")) return;

    try {
      const { error } = await supabase
        .from('exames_procedimentos')
        .delete()
        .eq('id', id);

      if (error) throw error;

      setItems(prev => prev.filter(item => item.id !== id));

      toast({
        title: "Item excluído",
        description: "O item foi removido com sucesso."
      });
    } catch (error) {
      console.error('Erro ao excluir:', error);
      toast({
        title: "Erro",
        description: "Não foi possível excluir o item.",
        variant: "destructive"
      });
    }
  };

  const filteredItems = items.filter(item => {
    const matchesSearch = item.nome.toLowerCase().includes(searchTerm.toLowerCase()) ||
      (item.codigo_tuss && item.codigo_tuss.includes(searchTerm));

    if (activeTab === "todos") return matchesSearch;
    if (activeTab === "exames") return matchesSearch && item.tipo.startsWith("exame_");
    if (activeTab === "procedimentos") return matchesSearch && item.tipo.startsWith("procedimento_");
    return matchesSearch;
  });

  const renderItem = (item: ExameProcedimento) => (
    <Card key={item.id} className="p-6">
      <div className="flex items-start justify-between mb-4">
        <div className="flex items-center gap-4">
          <div className="p-3 bg-primary-light rounded-full">
            <FileText className="h-6 w-6 text-primary" />
          </div>
          <div>
            <h3 className="text-lg font-semibold text-foreground">{item.nome}</h3>
            <div className="flex gap-2 mt-1">
              <Badge variant="outline">{tipoLabels[item.tipo]}</Badge>
              {item.codigo_tuss && (
                <Badge variant="secondary">TUSS: {item.codigo_tuss}</Badge>
              )}
            </div>
            {item.descricao && (
              <p className="text-sm text-muted-foreground mt-2">{item.descricao}</p>
            )}
          </div>
        </div>
        <div className="flex items-center gap-2">
          <Badge variant={item.ativo ? "default" : "secondary"}>
            {item.ativo ? "Ativo" : "Inativo"}
          </Badge>
          <Switch
            checked={item.ativo}
            onCheckedChange={() => toggleStatus(item.id, item.ativo)}
          />
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-4">
        {item.duracao_minutos && (
          <div className="flex items-center gap-2">
            <Clock className="h-4 w-4 text-muted-foreground" />
            <span className="text-sm">{item.duracao_minutos} min</span>
          </div>
        )}
        {item.tempo_jejum_horas && (
          <div className="text-sm text-muted-foreground">
            Jejum: {item.tempo_jejum_horas}h
          </div>
        )}
        {item.tempo_preparo_minutos && (
          <div className="text-sm text-muted-foreground">
            Preparo: {item.tempo_preparo_minutos} min
          </div>
        )}
        {item.valor && (
          <div className="flex items-center gap-2">
            <DollarSign className="h-4 w-4 text-muted-foreground" />
            <span className="text-sm">R$ {item.valor.toFixed(2)}</span>
          </div>
        )}
      </div>

      {(item.instrucoes || item.requisitos) && (
        <div className="mb-4 space-y-2">
          {item.instrucoes && (
            <p className="text-sm"><strong>Instruções:</strong> {item.instrucoes}</p>
          )}
          {item.requisitos && (
            <p className="text-sm"><strong>Requisitos:</strong> {item.requisitos}</p>
          )}
        </div>
      )}

      <div className="flex gap-2">
        <Button 
          size="sm" 
          variant="outline"
          onClick={() => setEditingId(item.id)}
        >
          <Edit className="h-4 w-4 mr-2" />
          Editar
        </Button>
        <Button
          size="sm" 
          variant="outline" 
          onClick={() => deleteItem(item.id)}
          className="text-destructive hover:text-destructive"
        >
          <Trash2 className="h-4 w-4 mr-2" />
          Excluir
        </Button>
      </div>
    </Card>
  );

  return (
    <MainLayout>
      <div className="space-y-6">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold text-foreground">Exames e Procedimentos</h1>
            <p className="text-muted-foreground">
              Gerenciar exames e procedimentos disponíveis ({items.length})
            </p>
          </div>
          {!isLoading && items.length > 0 && (
            <NewExameProcedimentoDialog onSuccess={() => fetchItems()} />
          )}
        </div>

        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <Input
            placeholder="Buscar por nome ou código TUSS..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="pl-10"
          />
        </div>

        <Tabs value={activeTab} onValueChange={setActiveTab}>
          <TabsList>
            <TabsTrigger value="todos">Todos ({items.length})</TabsTrigger>
            <TabsTrigger value="exames">
              Exames ({items.filter(i => i.tipo.startsWith("exame_")).length})
            </TabsTrigger>
            <TabsTrigger value="procedimentos">
              Procedimentos ({items.filter(i => i.tipo.startsWith("procedimento_")).length})
            </TabsTrigger>
          </TabsList>

          <TabsContent value={activeTab} className="space-y-4">
            {isLoading ? (
              <div className="flex items-center justify-center py-12">
                <Loader2 className="h-8 w-8 animate-spin text-primary" />
              </div>
            ) : filteredItems.length === 0 ? (
              <div className="text-center py-12">
                <FileText className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
                <h3 className="text-lg font-semibold mb-2">
                  {searchTerm ? "Nenhum item encontrado" : "Nenhum item cadastrado"}
                </h3>
                <p className="text-muted-foreground mb-4">
                  {searchTerm ? "Tente uma busca diferente" : "Comece adicionando seu primeiro item"}
                </p>
                {!searchTerm && <NewExameProcedimentoDialog onSuccess={() => fetchItems()} />}
              </div>
            ) : (
              <div className="grid gap-4">
                {filteredItems.map(renderItem)}
              </div>
            )}
          </TabsContent>
        </Tabs>
      </div>

      {editingId && (
        <EditExameProcedimentoDialog
          itemId={editingId}
          open={!!editingId}
          onOpenChange={(open) => !open && setEditingId(null)}
          onSuccess={() => fetchItems()}
        />
      )}
    </MainLayout>
  );
};

export default ExamesProcedimentos;

import React, { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Activity, Mail, Building2, Users, User, Eye, EyeOff } from "lucide-react";
import { ThemeToggle } from "@/components/theme/ThemeToggle";
import { useAuth } from "@/hooks/useAuth";
import { toast } from "sonner";
import { z } from "zod";
import { supabase } from "@/integrations/supabase/client";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";

const loginSchema = z.object({
  email: z.string().trim().email({ message: "E-mail inválido" }).max(255, { message: "E-mail muito longo" }),
  password: z.string().min(6, { message: "A senha deve ter pelo menos 6 caracteres" }).max(100, { message: "Senha muito longa" })
});

interface ManagerRole {
  type: 'user' | 'unit_manager' | 'org_manager';
  unitId?: string;
  unitName?: string;
  organizationId?: string;
  organizationName?: string;
}

interface UserOrgInfo {
  organizationId: string;
  organizationName: string;
  units: { id: string; name: string }[];
  isOrgAdmin: boolean;
  unitRoles: { unitId: string; role: string }[];
}

const Login = () => {
  const [email, setEmail] = useState(() => localStorage.getItem("cleanflow_remember_email") || "");
  const [password, setPassword] = useState(() => localStorage.getItem("cleanflow_remember_password") || "");
  const [rememberMe, setRememberMe] = useState(() => !!localStorage.getItem("cleanflow_remember_email"));
  const [loading, setLoading] = useState(false);
  const [showRoleSelector, setShowRoleSelector] = useState(false);
  const [userOrgInfo, setUserOrgInfo] = useState<UserOrgInfo | null>(null);
  const { signIn } = useAuth();
  const navigate = useNavigate();
  const [showPassword, setShowPassword] = useState(false);

  const checkUserOrganizationRoles = async (userId: string): Promise<UserOrgInfo | null> => {
    try {
      // Check if user has organization roles
      const { data: roles, error: rolesError } = await (supabase
        .from('user_unit_roles' as any)
        .select(`
          role,
          organization_id,
          unit_id,
          organizations:organization_id (nome_fantasia),
          units:unit_id (nome_unidade)
        `)
        .eq('user_id', userId) as any);

      if (rolesError || !roles || roles.length === 0) {
        return null;
      }

      const orgAdminRole = roles.find(r => r.role === 'org_admin' && !r.unit_id);

      if (orgAdminRole && orgAdminRole.organization_id) {
        // Fetch all units for this organization
        const { data: units } = await (supabase
          .from('units' as any)
          .select('id, nome_unidade')
          .eq('organization_id', orgAdminRole.organization_id)
          .eq('status', 'ativo') as any);

        const orgName = (orgAdminRole.organizations as any)?.nome_fantasia || 'Organização';

        return {
          organizationId: orgAdminRole.organization_id,
          organizationName: orgName,
          units: units?.map(u => ({ id: u.id, name: u.nome_unidade })) || [],
          isOrgAdmin: true,
          unitRoles: roles.filter(r => r.unit_id).map(r => ({
            unitId: r.unit_id!,
            role: r.role
          }))
        };
      }

      // Check if user has unit-level roles
      const unitRoles = roles.filter(r => r.unit_id);
      if (unitRoles.length > 0) {
        const firstUnit = unitRoles[0];
        const orgName = (firstUnit.organizations as any)?.nome_fantasia || 'Organização';

        return {
          organizationId: firstUnit.organization_id!,
          organizationName: orgName,
          units: unitRoles.map(r => ({
            id: r.unit_id!,
            name: (r.units as any)?.nome_unidade || 'Unidade'
          })),
          isOrgAdmin: false,
          unitRoles: unitRoles.map(r => ({
            unitId: r.unit_id!,
            role: r.role
          }))
        };
      }

      return null;
    } catch (error) {
      console.error('Error checking organization roles:', error);
      return null;
    }
  };

  const handleRoleSelection = (role: ManagerRole, savePreference = true) => {
    // Store the selected role in sessionStorage for the app to use
    sessionStorage.setItem('cleanflow_access_mode', JSON.stringify(role));

    // Save preference to localStorage for future logins
    if (savePreference) {
      localStorage.setItem('cleanflow_role_preference', JSON.stringify(role));
    }

    setShowRoleSelector(false);

    if (role.type === 'org_manager') {
      navigate('/organization-manager');
    } else if (role.type === 'unit_manager' && role.unitId) {
      sessionStorage.setItem('cleanflow_current_unit', role.unitId);
      navigate('/dashboard');
    } else {
      navigate('/dashboard');
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    const validation = loginSchema.safeParse({ email, password });
    if (!validation.success) {
      const firstError = validation.error.errors[0];
      toast.error(firstError.message);
      return;
    }

    setLoading(true);

    try {
      const { data: isLocked } = await (supabase.rpc('check_account_lock' as any, { p_email: email }) as any);

      if (isLocked) {
        toast.error("Conta bloqueada temporariamente devido a múltiplas tentativas falhadas");
        await (supabase.rpc('log_login_attempt' as any, {
          p_email: email,
          p_success: false,
          p_failure_reason: 'Account locked'
        }) as any);
        setLoading(false);
        return;
      }

      const { error } = await signIn(email, password);

      if (error) {
        await (supabase.rpc('log_login_attempt' as any, {
          p_email: email,
          p_success: false,
          p_failure_reason: error.message
        }) as any);
        toast.error("Erro ao fazer login: " + error.message);
        setLoading(false);
      } else {
        await (supabase.rpc('log_login_attempt' as any, {
          p_email: email,
          p_success: true
        }) as any);

        if (rememberMe) {
          localStorage.setItem("cleanflow_remember_email", email);
          localStorage.setItem("cleanflow_remember_password", password);
        } else {
          localStorage.removeItem("cleanflow_remember_email");
          localStorage.removeItem("cleanflow_remember_password");
        }

        // Check if user is a manager
        const { data: { user } } = await supabase.auth.getUser();
        if (user) {
          const orgInfo = await checkUserOrganizationRoles(user.id);

          if (orgInfo && (orgInfo.isOrgAdmin || orgInfo.units.length > 1)) {
            // Check for saved role preference
            const savedPreference = localStorage.getItem('cleanflow_role_preference');
            if (savedPreference) {
              try {
                const preference = JSON.parse(savedPreference) as ManagerRole;
                // Validate the preference is still valid for this user
                const isValidPreference =
                  preference.type === 'user' ||
                  (preference.type === 'org_manager' && orgInfo.isOrgAdmin) ||
                  (preference.type === 'unit_manager' && orgInfo.units.some(u => u.id === preference.unitId));

                if (isValidPreference) {
                  toast.success("Login realizado com sucesso!");
                  handleRoleSelection(preference, false);
                  return;
                }
              } catch {
                localStorage.removeItem('cleanflow_role_preference');
              }
            }

            setUserOrgInfo(orgInfo);
            setShowRoleSelector(true);
            setLoading(false);
            return;
          }
        }

        toast.success("Login realizado com sucesso!");
        navigate("/dashboard");
      }
    } catch (err) {
      console.error('Login error:', err);
      setLoading(false);
    }
  };

  const handleSocialLogin = async (provider: 'google' | 'azure') => {
    try {
      console.log(`[Login] Iniciando login com ${provider}`);
      setLoading(true);

      const redirectUrl = `${window.location.origin}/dashboard`;
      console.log(`[Login] Redirect URL: ${redirectUrl}`);

      const { data, error } = await supabase.auth.signInWithOAuth({
        provider,
        options: {
          redirectTo: redirectUrl,
          scopes: provider === 'google'
            ? 'https://www.googleapis.com/auth/userinfo.email https://www.googleapis.com/auth/userinfo.profile openid'
            : undefined,
        }
      });

      console.log(`[Login] Resposta do ${provider} OAuth:`, {
        url: data?.url,
        provider: data?.provider,
        error: error?.message
      });

      if (error) {
        console.error(`[Login] Erro no ${provider} OAuth:`, error);
        toast.error("Erro ao fazer login: " + error.message);
        setLoading(false);
      }
    } catch (error) {
      console.error(`[Login] Exceção no login com ${provider}:`, error);
      toast.error("Erro ao fazer login social");
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-primary/5 via-background to-success/5">
      <header className="fixed top-0 left-0 right-0 z-50 bg-card/95 backdrop-blur-md border-b border-border">
        <div className="container mx-auto px-4 py-4 flex items-center justify-between">
          <Link to="/" className="flex items-center gap-2">
            <Activity className="h-8 w-8 text-primary" />
            <span className="text-2xl font-bold text-foreground">CleanFlow</span>
          </Link>
          <ThemeToggle />
        </div>
      </header>

      <div className="container mx-auto px-4 pt-32 pb-20">
        <Card className="max-w-md mx-auto p-8">
          <div className="text-center mb-8">
            <h1 className="text-3xl font-bold text-foreground mb-2">Login</h1>
            <p className="text-muted-foreground">
              Entre na sua conta CleanFlow
            </p>
          </div>

          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <Label htmlFor="email">E-mail</Label>
              <Input
                id="email"
                type="email"
                placeholder="seu@email.com"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
              />
            </div>
            <div>
              <Label htmlFor="password">Senha</Label>
              <div className="relative">
                <Input
                  id="password"
                  type={showPassword ? "text" : "password"}
                  placeholder="••••••••"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  required
                  className="pr-10"
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors focus:outline-none"
                  aria-label={showPassword ? "Ocultar senha" : "Mostrar senha"}
                >
                  {showPassword ? (
                    <EyeOff className="h-4 w-4" />
                  ) : (
                    <Eye className="h-4 w-4" />
                  )}
                </button>
              </div>
            </div>
            <div className="flex items-center space-x-2">
              <input
                type="checkbox"
                id="remember"
                checked={rememberMe}
                onChange={(e) => setRememberMe(e.target.checked)}
                className="h-4 w-4 rounded border-border text-primary focus:ring-primary"
              />
              <Label htmlFor="remember" className="text-sm font-normal cursor-pointer">
                Lembrar de mim
              </Label>
            </div>
            <Button
              type="submit"
              className="w-full bg-primary hover:bg-primary-hover"
              disabled={loading}
            >
              {loading ? "Entrando..." : "Entrar"}
            </Button>
          </form>

          <div className="relative my-6">
            <div className="absolute inset-0 flex items-center">
              <div className="w-full border-t border-border" />
            </div>
            <div className="relative flex justify-center text-xs uppercase">
              <span className="bg-card px-2 text-muted-foreground">
                Ou continue com
              </span>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-3">
            <Button
              variant="outline"
              onClick={() => handleSocialLogin('google')}
              disabled={loading}
              className="w-full"
            >
              <svg className="mr-2 h-4 w-4" viewBox="0 0 24 24">
                <path
                  fill="currentColor"
