import React, { useState, useEffect } from "react";
import { MainLayout } from "@/components/layout/MainLayout";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import {
  Plus,
  Search,
  Filter,
  Phone,
  Mail,
  MessageSquare,
  AlertTriangle,
  User,
  Loader2,
  Trash2
} from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { NewPatientDialog } from "@/components/schedule/NewPatientDialog";
import { EditPatientDialog } from "@/components/schedule/EditPatientDialog";
import { VincularPacoteDialog } from "@/components/pacotes/VincularPacoteDialog";
import { useToast } from "@/hooks/use-toast";
import { useTerminology } from "@/stores/useSegmentStore";

interface Patient {
  id: string;
  nome: string;
  telefone: string;
  email: string | null;
  preferencia_contato: "whatsapp" | "sms" | "email";
  historico_faltas: number;
  risco_no_show: number;
  created_at: string;
}

const Pacientes = () => {
  const t = useTerminology();
  const [patients, setPatients] = useState<Patient[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [editingId, setEditingId] = useState<string | null>(null);
  const { toast } = useToast();

  const fetchPatients = async () => {
    try {
      setIsLoading(true);
      const { data, error } = await supabase
        .from('pacientes')
        .select('*')
        .order('nome');

      if (error) throw error;
      setPatients(data || []);
    } catch (error) {
      console.error('Erro ao buscar pacientes:', error);
      toast({
        title: "Erro",
        description: "Não foi possível carregar os pacientes.",
        variant: "destructive"
      });
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchPatients();
  }, []);

  const getRiskLevel = (risco: number): "low" | "medium" | "high" => {
    if (risco <= 30) return "low";
    if (risco <= 70) return "medium";
    return "high";
  };

  const getRiskBadge = (level: "low" | "medium" | "high") => {
    const config = {
      low: { label: "Baixo", variant: "default" as const, color: "text-success" },
      medium: { label: "Médio", variant: "secondary" as const, color: "text-warning" },
      high: { label: "Alto", variant: "destructive" as const, color: "text-destructive" }
    };
    return config[level as keyof typeof config];
  };

  const filteredPatients = patients.filter(p =>
    p.nome.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.telefone.includes(searchTerm) ||
    (p.email && p.email.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  return (
    <MainLayout>
      <div className="space-y-6">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold text-foreground">{t.client_label}s</h1>
            <p className="text-muted-foreground">
              Gerenciar cadastro e histórico de {t.client_label.toLowerCase()}s ({patients.length})
            </p>
          </div>
          <NewPatientDialog onSuccess={() => fetchPatients()} />
        </div>

        <div className="flex gap-3">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
            <Input
              placeholder={`Buscar por nome, telefone ou e-mail...`}
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="pl-10"
            />
          </div>
        </div>

        {isLoading ? (
          <div className="flex items-center justify-center py-12">
            <Loader2 className="h-8 w-8 animate-spin text-primary" />
          </div>
        ) : filteredPatients.length === 0 ? (
          <div className="text-center py-12">
            <User className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
            <h3 className="text-lg font-semibold mb-2">
              {searchTerm ? `Nenhum ${t.client_label.toLowerCase()} encontrado` : `Nenhum ${t.client_label.toLowerCase()} cadastrado`}
            </h3>
            <p className="text-muted-foreground mb-4">
              {searchTerm ? "Tente uma busca diferente" : `Comece adicionando seu primeiro ${t.client_label.toLowerCase()}`}
            </p>
          </div>
        ) : (
          <div className="grid gap-4">
            {filteredPatients.map((patient) => {
              const riskLevel = getRiskLevel(patient.risco_no_show);
              const riskConfig = getRiskBadge(riskLevel);

              return (
                <div key={patient.id} className="p-6 bg-card border border-border rounded-lg hover:bg-card-hover transition-colors">
                  <div className="flex items-start justify-between mb-4">
                    <div className="flex items-center gap-4">
                      <div className="p-3 bg-primary-light rounded-full">
                        <User className="h-6 w-6 text-primary" />
                      </div>
                      <div>
                        <h3 className="text-lg font-semibold text-foreground">{patient.nome}</h3>
                        <p className="text-sm text-muted-foreground">
                          Cadastrado em {new Date(patient.created_at).toLocaleDateString('pt-BR')}
                        </p>
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      <Badge variant={riskConfig.variant}>
                        <AlertTriangle className="h-3 w-3 mr-1" />
                        Risco {riskConfig.label}
                      </Badge>
                      {patient.historico_faltas > 0 && (
                        <Badge variant="destructive">
                          {patient.historico_faltas} faltas
                        </Badge>
                      )}
                    </div>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-4">
                    <div className="flex items-center gap-2">
                      <Phone className="h-4 w-4 text-muted-foreground" />
                      <span className="text-sm">{patient.telefone}</span>
                    </div>
                    <div className="flex items-center gap-2">
                      <Mail className="h-4 w-4 text-muted-foreground" />
                      <span className="text-sm">{patient.email || "Não informado"}</span>
                    </div>
                    <div className="flex items-center gap-2">
                      <MessageSquare className="h-4 w-4 text-muted-foreground" />
                      <span className="text-sm capitalize">Prefere {patient.preferencia_contato}</span>
                    </div>
                  </div>

                  <div className="flex gap-2 flex-wrap">
                    <Button
                      size="sm"
                      variant="outline"
                      onClick={() => setEditingId(patient.id)}
                    >
                      Editar
                    </Button>
                    <VincularPacoteDialog
                      pacienteId={patient.id}
                      pacienteNome={patient.nome}
                      onSuccess={() => fetchPatients()}
                    />
                    <Button
                      size="sm"
                      variant="outline"
                      onClick={async () => {
                        const { validatePacienteDelete } = await import('@/lib/deleteValidation');
                        const validation = await validatePacienteDelete(patient.id);

                        if (!validation.canDelete) {
                          toast({
                            title: "Não é possível excluir",
                            description: validation.message,
                            variant: "destructive",
                            duration: 10000
                          });
                          return;
                        }

                        if (!confirm(`Tem certeza que deseja excluir o ${t.client_label.toLowerCase()} ${patient.nome}?`)) return;

                        try {
                          const { error } = await supabase
                            .from('pacientes')
                            .delete()
                            .eq('id', patient.id);

                          if (error) throw error;

                          setPatients(prev => prev.filter(p => p.id !== patient.id));

                          toast({
                            title: `${t.client_label} excluído`,
                            description: `O ${t.client_label.toLowerCase()} foi removido com sucesso.`
                          });
                        } catch (error) {
                          console.error('Erro ao excluir:', error);
                          toast({
                            title: "Erro",
                            description: `Não foi possível excluir o ${t.client_label.toLowerCase()}.`,
                            variant: "destructive"
                          });
                        }
                      }}
                      className="text-destructive hover:text-destructive"
                    >
                      <Trash2 className="h-4 w-4 mr-2" />
                      Excluir
                    </Button>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {editingId && (
        <EditPatientDialog
          patientId={editingId}
          open={!!editingId}
          onOpenChange={(open) => !open && setEditingId(null)}
          onSuccess={() => fetchPatients()}
        />
      )}
    </MainLayout>
  );
};

export default Pacientes;

import React, { useState, useEffect } from "react";
import { MainLayout } from "@/components/layout/MainLayout";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { Input } from "@/components/ui/input";
import { 
  Edit, 
  Trash2, 
  Package,
  Loader2,
  DollarSign,
  Calendar as CalendarIcon,
  Users,
  Search
} from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { NewPacoteDialog } from "@/components/pacotes/NewPacoteDialog";
import { EditPacoteDialog } from "@/components/pacotes/EditPacoteDialog";

interface Pacote {
  id: string;
  nome: string;
  descricao: string | null;
  numero_sessoes: number;
  preco: number;
  validade_dias: number;
  renovacao_automatica: boolean;
  desconto_renovacao: number;
  ativo: boolean;
  servico_id: string | null;
  procedimentos?: { nome: string };
}

const Pacotes = () => {
  const [pacotes, setPacotes] = useState<Pacote[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [editingId, setEditingId] = useState<string | null>(null);
  const { toast } = useToast();

  const fetchPacotes = async () => {
    try {
      setIsLoading(true);
      const { data, error } = await supabase
        .from('pacotes')
        .select('*, procedimentos:servico_id(nome)')
        .order('nome');

      if (error) throw error;
      setPacotes(data || []);
    } catch (error) {
      console.error('Erro ao buscar pacotes:', error);
      toast({
        title: "Erro",
        description: "Não foi possível carregar os pacotes.",
        variant: "destructive"
      });
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchPacotes();
  }, []);

  const togglePacoteStatus = async (pacoteId: string, currentStatus: boolean) => {
    try {
      const { error } = await supabase
        .from('pacotes')
        .update({ ativo: !currentStatus })
        .eq('id', pacoteId);

      if (error) throw error;

      setPacotes(prev => prev.map(pacote => 
        pacote.id === pacoteId 
          ? { ...pacote, ativo: !currentStatus }
          : pacote
      ));

      toast({
        title: "Status atualizado",
        description: `Pacote ${!currentStatus ? "ativado" : "desativado"} com sucesso.`
      });
    } catch (error) {
      console.error('Erro ao atualizar status:', error);
      toast({
        title: "Erro",
        description: "Não foi possível atualizar o status do pacote.",
        variant: "destructive"
      });
    }
  };

  const deletePacote = async (pacoteId: string) => {
    // Importar validação
    const { validatePacoteDelete } = await import('@/lib/deleteValidation');

    // Validar antes de excluir
    const validation = await validatePacoteDelete(pacoteId);

    if (!validation.canDelete) {
      toast({
        title: "Não é possível excluir",
        description: validation.message,
        variant: "destructive",
        duration: 10000
      });
      return;
    }

    if (!confirm("Tem certeza que deseja excluir este pacote? Esta ação não pode ser desfeita.")) return;

    try {
      const { error } = await supabase
        .from('pacotes')
        .delete()
        .eq('id', pacoteId);

      if (error) throw error;

      setPacotes(prev => prev.filter(pacote => pacote.id !== pacoteId));

      toast({
        title: "Pacote excluído",
        description: "O pacote foi removido com sucesso."
      });
    } catch (error) {
      console.error('Erro ao excluir pacote:', error);
      toast({
        title: "Erro",
        description: "Não foi possível excluir o pacote.",
        variant: "destructive"
      });
    }
  };

  const filteredPacotes = pacotes.filter(p => 
    p.nome.toLowerCase().includes(searchTerm.toLowerCase()) ||
    (p.descricao && p.descricao.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  const activePacotes = filteredPacotes.filter(p => p.ativo);
  const totalRevenue = filteredPacotes.reduce((acc, p) => acc + p.preco, 0);

  return (
    <MainLayout>
      <div className="space-y-6">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold text-foreground">Pacotes de Tratamentos</h1>
            <p className="text-muted-foreground">
              Gerencie pacotes de sessões para tratamentos estéticos e de beleza ({pacotes.length})
            </p>
          </div>
          {!isLoading && pacotes.length > 0 && (
            <NewPacoteDialog onSuccess={() => fetchPacotes()} />
          )}
        </div>

        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <Input
            placeholder="Buscar pacotes..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="pl-10"
          />
        </div>

        {/* Estatísticas dos Pacotes */}
        {!isLoading && filteredPacotes.length > 0 && (
          <Card className="p-6">
            <h3 className="text-lg font-semibold mb-4">Estatísticas dos Pacotes</h3>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div className="text-center">
                <p className="text-2xl font-bold text-primary">{activePacotes.length}</p>
                <p className="text-sm text-muted-foreground">Pacotes Ativos</p>
              </div>
              <div className="text-center">
                <p className="text-2xl font-bold text-success">R$ {totalRevenue.toFixed(0)}</p>
                <p className="text-sm text-muted-foreground">Receita Total</p>
              </div>
              <div className="text-center">
                <p className="text-2xl font-bold text-muted-foreground">{pacotes.length}</p>
                <p className="text-sm text-muted-foreground">Total de Pacotes</p>
              </div>
            </div>
          </Card>
        )}

        {/* Lista de Pacotes */}
        {isLoading ? (
          <div className="flex items-center justify-center py-12">
            <Loader2 className="h-8 w-8 animate-spin text-primary" />
          </div>
        ) : filteredPacotes.length === 0 ? (
          <div className="text-center py-12">
            <Package className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
            <h3 className="text-lg font-semibold mb-2">
              {searchTerm ? "Nenhum pacote encontrado" : "Nenhum pacote cadastrado"}
            </h3>
            <p className="text-muted-foreground mb-4">
              {searchTerm ? "Tente uma busca diferente" : "Crie pacotes de tratamentos para oferecer aos seus clientes"}
            </p>
            {!searchTerm && <NewPacoteDialog onSuccess={() => fetchPacotes()} />}
          </div>
        ) : (
          <div className="grid gap-4">
            {filteredPacotes.map((pacote) => (
              <Card key={pacote.id} className="p-6">
                <div className="flex items-start justify-between mb-4">
                  <div className="flex items-center gap-3">
                    <div className="p-2 bg-primary-light rounded-lg">
                      <Package className="h-5 w-5 text-primary" />
                    </div>
                    <div>
                      <h3 className="text-lg font-semibold text-foreground">{pacote.nome}</h3>
                      {pacote.descricao && (
                        <p className="text-sm text-muted-foreground mt-1">{pacote.descricao}</p>
                      )}
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    <Badge variant={pacote.ativo ? "default" : "secondary"}>
                      {pacote.ativo ? "Ativo" : "Inativo"}
                    </Badge>
                    <Switch
                      checked={pacote.ativo}
                      onCheckedChange={() => togglePacoteStatus(pacote.id, pacote.ativo)}
                    />
                  </div>
                </div>

                <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-4">
                  <div>
                    <p className="text-xs text-muted-foreground mb-1">Sessões</p>
                    <div className="flex items-center gap-2">
                      <Users className="h-4 w-4 text-primary" />
                      <span className="text-sm font-medium">{pacote.numero_sessoes} sessões</span>
                    </div>
                  </div>
                  <div>
                    <p className="text-xs text-muted-foreground mb-1">Preço</p>
                    <div className="flex items-center gap-2">
                      <DollarSign className="h-4 w-4 text-success" />
                      <span className="text-sm font-medium">R$ {pacote.preco.toFixed(2)}</span>
                    </div>
                  </div>
                  <div>
                    <p className="text-xs text-muted-foreground mb-1">Validade</p>
                    <div className="flex items-center gap-2">
                      <CalendarIcon className="h-4 w-4 text-warning" />
                      <span className="text-sm font-medium">{pacote.validade_dias} dias</span>
                    </div>
                  </div>
                  {pacote.renovacao_automatica && (
                    <div>
                      <p className="text-xs text-muted-foreground mb-1">Renovação</p>
                      <Badge variant="outline" className="text-xs">
                        Automática {pacote.desconto_renovacao > 0 && `(-${pacote.desconto_renovacao}%)`}
                      </Badge>
                    </div>
                  )}
                </div>

                {pacote.procedimentos && (
                  <div className="mb-4">
                    <p className="text-xs text-muted-foreground mb-1">Procedimento vinculado</p>
                    <Badge variant="secondary">{pacote.procedimentos.nome}</Badge>
                  </div>
                )}

                <div className="flex gap-2">
                  <Button 
                    size="sm" 
                    variant="outline"
                    onClick={() => setEditingId(pacote.id)}
                  >
                    <Edit className="h-4 w-4 mr-2" />
                    Editar
                  </Button>
                  <Button
                    size="sm" 
                    variant="outline" 
                    onClick={() => deletePacote(pacote.id)}
                    className="text-destructive hover:text-destructive"
                  >
                    <Trash2 className="h-4 w-4 mr-2" />
                    Excluir
                  </Button>
                </div>
              </Card>
            ))}
          </div>
        )}
      </div>

      {editingId && (
        <EditPacoteDialog
          pacoteId={editingId}
          open={!!editingId}
          onOpenChange={(open) => !open && setEditingId(null)}
          onSuccess={() => fetchPacotes()}
        />
      )}
    </MainLayout>
  );
};

export default Pacotes;

import { useState } from "react";
import { Eye, EyeOff } from "lucide-react";
import { useNavigate } from "react-router-dom";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { toast } from "sonner";

export default function PatientLogin() {
  const navigate = useNavigate();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      const { data, error } = await supabase.auth.signInWithPassword({
        email,
        password,
      });

      if (error) throw error;

      // Verificar se é um usuário paciente
      const { data: pacienteUsuario } = await supabase
        .from('paciente_usuarios' as any)
        .select('*')
        .eq('auth_user_id', data.user.id)
        .single();

      if (!pacienteUsuario) {
        await supabase.auth.signOut();
        throw new Error('Usuário não é um paciente válido');
      }

      toast.success('Login realizado com sucesso!');
      navigate('/patient-portal');
    } catch (error: any) {
      console.error('Erro no login:', error);
      toast.error(error.message || 'Erro ao fazer login');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-background p-4">
      <Card className="w-full max-w-md">
        <CardHeader className="text-center">
          <CardTitle className="text-2xl">Portal do Paciente</CardTitle>
          <CardDescription>
            Acesse suas consultas, documentos e histórico médico
          </CardDescription>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleLogin} className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="email">E-mail</Label>
              <Input
                id="email"
                type="email"
                placeholder="seu@email.com"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="password">Senha</Label>
              <div className="relative">
                <Input
                  id="password"
                  type={showPassword ? "text" : "password"}
                  placeholder="••••••••"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  required
                  className="pr-10"
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors focus:outline-none"
                  aria-label={showPassword ? "Ocultar senha" : "Mostrar senha"}
                >
                  {showPassword ? (
                    <EyeOff className="h-4 w-4" />
                  ) : (
                    <Eye className="h-4 w-4" />
                  )}
                </button>
              </div>
            </div>
            <Button type="submit" className="w-full" disabled={loading}>
              {loading ? 'Entrando...' : 'Entrar'}
            </Button>
            <div className="text-center text-sm">
              <a href="#" className="text-primary hover:underline">
                Esqueci minha senha
              </a>
            </div>
            <div className="text-center text-sm text-muted-foreground">
              Primeiro acesso? Entre em contato com a clínica para criar sua conta.
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Button } from "@/components/ui/button";
import { Calendar, FileText, Clock, Video, LogOut, Plus } from "lucide-react";
import { toast } from "sonner";
import { AgendamentoOnline } from "@/components/patient/AgendamentoOnline";

export default function PatientPortal() {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [paciente, setPaciente] = useState<any>(null);
  const [agendamentos, setAgendamentos] = useState<any[]>([]);
  const [documentos, setDocumentos] = useState<any[]>([]);
  const [prontuarios, setProntuarios] = useState<any[]>([]);

  useEffect(() => {
    loadPatientData();
  }, []);

  const loadPatientData = async () => {
    try {
      const { data: { user } } = await supabase.auth.getUser();

      if (!user) {
        navigate('/patient-login');
        return;
      }

      // Buscar dados do paciente
      const { data: pacienteUsuario } = await supabase
        .from('paciente_usuarios' as any)
        .select('*, pacientes(*)')
        .eq('auth_user_id', user.id)
        .single();

      if (!pacienteUsuario) {
        toast.error('Paciente não encontrado');
        navigate('/patient-login');
        return;
      }

      setPaciente((pacienteUsuario as any).pacientes);

      // Buscar agendamentos futuros
      const { data: agendamentosData } = await supabase
        .from('agenda')
        .select('*, procedimentos:servico_id(nome), profiles(nome)')
        .eq('paciente_id', (pacienteUsuario as any).paciente_id)
        .gte('inicio', new Date().toISOString())
        .order('inicio', { ascending: true })
        .limit(10);

      setAgendamentos(agendamentosData || []);

      // Buscar documentos
      const { data: documentosData } = await supabase
        .from('paciente_documentos' as any)
        .select('*')
        .eq('paciente_id', (pacienteUsuario as any).paciente_id)
        .eq('visivel_paciente', true)
        .order('created_at', { ascending: false })
        .limit(10);

      setDocumentos(documentosData || []);

      // Buscar prontuários finalizados
      const { data: prontuariosData } = await supabase
        .from('prontuarios' as any)
        .select('*, profiles(nome)')
        .eq('paciente_id', (pacienteUsuario as any).paciente_id)
        .in('status', ['finalizado', 'assinado'])
        .order('data_atendimento', { ascending: false })
        .limit(10);

      setProntuarios(prontuariosData || []);

    } catch (error) {
      console.error('Erro ao carregar dados:', error);
      toast.error('Erro ao carregar dados do paciente');
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    navigate('/patient-login');
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary mx-auto mb-4"></div>
          <p>Carregando...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background">
      <header className="border-b">
        <div className="container mx-auto px-4 py-4 flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold">Portal do Paciente</h1>
            <p className="text-sm text-muted-foreground">
              Bem-vindo(a), {paciente?.nome}
            </p>
          </div>
          <Button variant="outline" onClick={handleLogout}>
            <LogOut className="h-4 w-4 mr-2" />
            Sair
          </Button>
        </div>
      </header>

      <main className="container mx-auto px-4 py-8">
        <Tabs defaultValue="novo" className="space-y-6">
          <TabsList className="grid w-full grid-cols-5">
            <TabsTrigger value="novo">
              <Plus className="h-4 w-4 mr-2" />
              Novo Agendamento
            </TabsTrigger>
            <TabsTrigger value="agendamentos">
              <Calendar className="h-4 w-4 mr-2" />
              Agendamentos
            </TabsTrigger>
            <TabsTrigger value="documentos">
              <FileText className="h-4 w-4 mr-2" />
              Documentos
            </TabsTrigger>
            <TabsTrigger value="historico">
              <Clock className="h-4 w-4 mr-2" />
              Histórico
            </TabsTrigger>
            <TabsTrigger value="videoconsulta">
              <Video className="h-4 w-4 mr-2" />
              Videoconsulta
            </TabsTrigger>
          </TabsList>

          <TabsContent value="novo" className="space-y-4">
            <AgendamentoOnline
              pacienteId={paciente?.id}
              tenantId={paciente?.tenant_id}
            />
          </TabsContent>

          <TabsContent value="agendamentos" className="space-y-4">
            <Card>
              <CardHeader>
                <CardTitle>Próximas Consultas</CardTitle>
              </CardHeader>
              <CardContent>
                {agendamentos.length === 0 ? (
                  <p className="text-muted-foreground text-center py-8">
                    Nenhuma consulta agendada
                  </p>
                ) : (
                  <div className="space-y-4">
                    {agendamentos.map((agendamento) => (
                      <div
                        key={agendamento.id}
                        className="border rounded-lg p-4 flex items-center justify-between"
                      >
                        <div>
                          <p className="font-medium">{agendamento.servicos?.nome}</p>
                          <p className="text-sm text-muted-foreground">
                            Dr(a). {agendamento.profiles?.nome}
                          </p>
                          <p className="text-sm text-muted-foreground">
                            {new Date(agendamento.inicio).toLocaleDateString('pt-BR', {
                              weekday: 'long',
                              year: 'numeric',
                              month: 'long',
                              day: 'numeric',
                              hour: '2-digit',
                              minute: '2-digit'
                            })}
                          </p>
                        </div>
                        <div className="flex gap-2">
                          {agendamento.confirmado ? (
                            <span className="text-xs bg-green-100 text-green-800 px-2 py-1 rounded">
                              Confirmado
                            </span>
                          ) : (
                            <Button size="sm" variant="outline">
                              Confirmar
                            </Button>
                          )}
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </CardContent>
            </Card>
          </TabsContent>

          <TabsContent value="documentos" className="space-y-4">
            <Card>
              <CardHeader>
                <CardTitle>Meus Documentos</CardTitle>
              </CardHeader>
              <CardContent>
                {documentos.length === 0 ? (
                  <p className="text-muted-foreground text-center py-8">
                    Nenhum documento disponível
                  </p>
                ) : (
                  <div className="space-y-4">
                    {documentos.map((documento) => (
                      <div
                        key={documento.id}
                        className="border rounded-lg p-4 flex items-center justify-between"
                      >
                        <div>
                          <p className="font-medium">{documento.titulo}</p>
                          <p className="text-sm text-muted-foreground">
                            {documento.tipo.charAt(0).toUpperCase() + documento.tipo.slice(1)}
                          </p>
                          <p className="text-xs text-muted-foreground">
                            {new Date(documento.created_at).toLocaleDateString('pt-BR')}
                          </p>
                        </div>
                        <Button size="sm" variant="outline">
                          Visualizar
                        </Button>
                      </div>
                    ))}
                  </div>
                )}
              </CardContent>
            </Card>
          </TabsContent>

          <TabsContent value="historico" className="space-y-4">
            <Card>
              <CardHeader>
                <CardTitle>Histórico de Consultas</CardTitle>
              </CardHeader>
              <CardContent>
                {prontuarios.length === 0 ? (
                  <p className="text-muted-foreground text-center py-8">
                    Nenhum histórico disponível
                  </p>
                ) : (
                  <div className="space-y-4">
                    {prontuarios.map((prontuario) => (
                      <div
                        key={prontuario.id}
                        className="border rounded-lg p-4"
                      >
                        <div className="flex items-center justify-between mb-2">
                          <p className="font-medium">
                            Dr(a). {prontuario.profiles?.nome}
                          </p>
                          <p className="text-sm text-muted-foreground">
                            {new Date(prontuario.data_atendimento).toLocaleDateString('pt-BR')}
                          </p>
                        </div>
                        {prontuario.avaliacao && (
                          <p className="text-sm text-muted-foreground mb-2">
                            <strong>Avaliação:</strong> {prontuario.avaliacao}
                          </p>
                        )}
                        {prontuario.plano && (
                          <p className="text-sm text-muted-foreground">
                            <strong>Plano:</strong> {prontuario.plano}
                          </p>
                        )}
                      </div>
                    ))}
                  </div>
                )}
              </CardContent>
            </Card>
          </TabsContent>

          <TabsContent value="videoconsulta" className="space-y-4">
            <Card>
              <CardHeader>
                <CardTitle>Videoconsultas</CardTitle>
              </CardHeader>
              <CardContent>
                <p className="text-muted-foreground text-center py-8">
                  Nenhuma videoconsulta disponível no momento
                </p>
              </CardContent>
            </Card>
          </TabsContent>
        </Tabs>
      </main>
    </div>
  );
}

import React, { useState, useEffect } from "react";
import { MainLayout } from "@/components/layout/MainLayout";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Avatar, AvatarImage, AvatarFallback } from "@/components/ui/avatar";
import { useAuth } from "@/hooks/useAuth";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { Loader2, Upload, User, Mail, Phone, MapPin, FileText, RefreshCw } from "lucide-react";
import { z } from "zod";

const profileSchema = z.object({
  nome: z.string().trim().min(1, { message: "Nome é obrigatório" }).max(200, { message: "Nome muito longo" }),
  telefone: z.string().trim().min(10, { message: "Telefone inválido" }).max(20, { message: "Telefone muito longo" }).optional().or(z.literal("")),
  email: z.string().trim().email({ message: "E-mail inválido" }).max(255, { message: "E-mail muito longo" }).optional().or(z.literal("")),
  cpf: z.string().trim().max(14, { message: "CPF muito longo" }).optional().or(z.literal("")),
  cidade: z.string().trim().max(100, { message: "Cidade muito longa" }).optional().or(z.literal("")),
  uf: z.string().trim().length(2, { message: "UF deve ter 2 caracteres" }).optional().or(z.literal(""))
});

const Perfil = () => {
  const { user, profile, refreshProfile } = useAuth();
  const { toast } = useToast();
  const [isLoading, setIsLoading] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [formData, setFormData] = useState({
    nome: "",
    telefone: "",
    email: "",
    cpf: "",
    cidade: "",
    uf: "",
    conselho_profissional: "",
    numero_registro: "",
    uf_registro: ""
  });
  const [avatarUrl, setAvatarUrl] = useState<string | null>(null);

  useEffect(() => {
    if (profile) {
      setFormData({
        nome: profile.nome || "",
        telefone: profile.telefone || "",
        email: profile.email || "",
        cpf: profile.cpf || "",
        cidade: profile.cidade || "",
        uf: profile.uf || "",
        conselho_profissional: profile.conselho_profissional || "",
        numero_registro: profile.numero_registro || "",
        uf_registro: profile.uf_registro || ""
      });
      setAvatarUrl(profile.avatar_url || null);
    }
  }, [profile]);

  const handleAvatarUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file || !user) return;

    // Validar tipo de arquivo
    if (!file.type.startsWith('image/')) {
      toast({
        title: "Erro",
        description: "Por favor, selecione uma imagem válida.",
        variant: "destructive"
      });
      return;
    }

    // Validar tamanho (máx 2MB)
    if (file.size > 2 * 1024 * 1024) {
      toast({
        title: "Erro",
        description: "A imagem deve ter no máximo 2MB.",
        variant: "destructive"
      });
      return;
    }

    try {
      setIsUploading(true);

      // Deletar avatar anterior se existir
      if (avatarUrl) {
        const oldPath = avatarUrl.split('/').pop();
        if (oldPath) {
          await supabase.storage
            .from('avatars')
            .remove([`${user.id}/${oldPath}`]);
        }
      }

      // Upload do novo avatar
      const fileExt = file.name.split('.').pop();
      const fileName = `${Date.now()}.${fileExt}`;
      const filePath = `${user.id}/${fileName}`;

      const { error: uploadError } = await supabase.storage
        .from('avatars')
        .upload(filePath, file);

      if (uploadError) throw uploadError;

      // Obter URL pública
      const { data: { publicUrl } } = supabase.storage
        .from('avatars')
        .getPublicUrl(filePath);

      // Atualizar profile com nova URL
      const { error: updateError } = await supabase
        .from('profiles')
        .update({ avatar_url: publicUrl })
        .eq('id', user.id);

      if (updateError) throw updateError;

      setAvatarUrl(publicUrl);

      // Refresh profile in context
      await refreshProfile();

      toast({
        title: "Sucesso",
        description: "Foto de perfil atualizada com sucesso!"
      });
    } catch (error) {
      console.error('Erro ao fazer upload:', error);
      toast({
        title: "Erro",
        description: "Não foi possível fazer upload da imagem.",
        variant: "destructive"
      });
    } finally {
      setIsUploading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;

    // Validate input
    const validation = profileSchema.safeParse(formData);
    if (!validation.success) {
      const firstError = validation.error.errors[0];
      toast({
        title: "Erro de validação",
        description: firstError.message,
        variant: "destructive"
      });
      return;
    }

    try {
      setIsLoading(true);

      const { error } = await supabase
        .from('profiles')
        .update({
          nome: formData.nome,
          telefone: formData.telefone,
          email: formData.email,
          cpf: formData.cpf,
          cidade: formData.cidade,
          uf: formData.uf,
          conselho_profissional: formData.conselho_profissional,
          numero_registro: formData.numero_registro,
          uf_registro: formData.uf_registro
        })
        .eq('id', user.id);

      if (error) throw error;

      // Refresh profile in context
      await refreshProfile();

      toast({
        title: "Sucesso",
        description: "Perfil atualizado com sucesso!"
      });
    } catch (error: any) {
      console.error('Erro ao atualizar perfil:', error);
      toast({
        title: "Erro",
        description: error.message || "Não foi possível atualizar o perfil.",
        variant: "destructive"
      });
    } finally {
      setIsLoading(false);
    }
  };

  const getInitials = (name: string) => {
    return name
      .split(' ')
      .map(n => n[0])
      .join('')
      .toUpperCase()
      .substring(0, 2);
  };

  return (
    <MainLayout>
      <div className="space-y-6 max-w-4xl mx-auto">
        <div>
          <h1 className="text-3xl font-bold text-foreground">Meu Perfil</h1>
          <p className="text-muted-foreground">
            Gerencie suas informações pessoais e configurações
          </p>
        </div>

        {/* Avatar Section */}
        <Card className="p-6">
          <div className="flex items-center gap-6">
            <div className="relative">
              <Avatar className="h-24 w-24">
                {avatarUrl ? (
                  <AvatarImage src={avatarUrl} alt={profile?.nome} />
                ) : (
                  <AvatarFallback className="bg-gradient-primary text-primary-foreground text-2xl">
                    {profile?.nome ? getInitials(profile.nome) : <User className="h-12 w-12" />}
                  </AvatarFallback>
                )}
              </Avatar>
              {isUploading && (
                <div className="absolute inset-0 bg-background/80 rounded-full flex items-center justify-center">
                  <Loader2 className="h-6 w-6 animate-spin text-primary" />
                </div>
              )}
            </div>
            <div className="flex-1">
              <h3 className="text-lg font-semibold mb-2">Foto de Perfil</h3>
              <p className="text-sm text-muted-foreground mb-4">
                Escolha uma foto para seu perfil (JPG, PNG ou WEBP, máx 2MB)
              </p>
              <label htmlFor="avatar-upload">
                <Button variant="outline" disabled={isUploading} asChild>
                  <span>
                    <Upload className="h-4 w-4 mr-2" />
                    {isUploading ? "Enviando..." : "Alterar Foto"}
                  </span>
                </Button>
              </label>
              <input
                id="avatar-upload"
                type="file"
                accept="image/*"
                className="hidden"
                onChange={handleAvatarUpload}
                disabled={isUploading}
              />
            </div>
          </div>
        </Card>

        {/* Profile Form */}
        <Card className="p-6">
          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="nome">
                  <User className="h-4 w-4 inline mr-2" />
                  Nome Completo *
                </Label>
                <Input
                  id="nome"
                  value={formData.nome}
                  onChange={(e) => setFormData(prev => ({ ...prev, nome: e.target.value }))}
                  required
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="email">
                  <Mail className="h-4 w-4 inline mr-2" />
                  E-mail
                </Label>
                <Input
                  id="email"
                  type="email"
                  value={formData.email}
                  onChange={(e) => setFormData(prev => ({ ...prev, email: e.target.value }))}
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="telefone">
                  <Phone className="h-4 w-4 inline mr-2" />
                  Telefone
                </Label>
                <Input
                  id="telefone"
                  value={formData.telefone}
                  onChange={(e) => setFormData(prev => ({ ...prev, telefone: e.target.value }))}
                  placeholder="(00) 00000-0000"
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="cpf">
                  <FileText className="h-4 w-4 inline mr-2" />
                  CPF
                </Label>
                <Input
                  id="cpf"
                  value={formData.cpf}
                  onChange={(e) => setFormData(prev => ({ ...prev, cpf: e.target.value }))}
                  placeholder="000.000.000-00"
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="cidade">
                  <MapPin className="h-4 w-4 inline mr-2" />
                  Cidade
                </Label>
                <Input
                  id="cidade"
                  value={formData.cidade}
                  onChange={(e) => setFormData(prev => ({ ...prev, cidade: e.target.value }))}
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="uf">UF</Label>
                <Input
                  id="uf"
                  value={formData.uf}
                  onChange={(e) => setFormData(prev => ({ ...prev, uf: e.target.value.toUpperCase() }))}
                  maxLength={2}
                  placeholder="SP"
                />
              </div>
            </div>

            {/* Professional Info (if applicable) */}
            {profile?.role === 'profissional' && (
              <>
                <div className="border-t pt-6">
                  <h3 className="text-lg font-semibold mb-4">Informações Profissionais</h3>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <div className="space-y-2">
