                console.error('Erro ao reativar tours:', error);
                toast({
                  title: "Erro",
                  description: "Não foi possível reativar os tours.",
                  variant: "destructive"
                });
              }
            }}
          >
            <RefreshCw className="h-4 w-4 mr-2" />
            Reativar Todos os Tours
          </Button>
        </Card>
      </div>
    </MainLayout>
  );
};

