import { useState, useEffect } from "react";
import { MainLayout } from "@/components/layout/MainLayout";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { Loader2, Plus, Pencil, Trash2, Search } from "lucide-react";
import { NewPlanoSaudeDialog } from "@/components/planos/NewPlanoSaudeDialog";
import { EditPlanoSaudeDialog } from "@/components/planos/EditPlanoSaudeDialog";

interface PlanoSaude {
  id: string;
  nome: string;
  descricao: string | null;
  ativo: boolean;
  created_at: string;
}

export default function PlanosSaude() {
  const [planos, setPlanos] = useState<PlanoSaude[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [editingId, setEditingId] = useState<string | null>(null);
  const { toast } = useToast();

  const fetchPlanos = async () => {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error("Usuário não autenticado");

      const { data: profile } = await supabase
        .from("profiles")
        .select("tenant_id")
        .eq("id", user.id)
        .single();

      if (!profile?.tenant_id) throw new Error("Tenant não encontrado");

      const { data, error } = await supabase
        .from("planos_saude")
        .select("*")
        .eq("tenant_id", profile.tenant_id)
        .order("nome");

      if (error) throw error;
      setPlanos(data || []);
    } catch (error: any) {
      toast({
        title: "Erro ao carregar planos",
        description: error.message,
        variant: "destructive",
      });
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchPlanos();
  }, []);

  const handleDelete = async (id: string, nome: string) => {
    if (!confirm(`Tem certeza que deseja excluir o plano "${nome}"?`)) return;

    try {
      const { error } = await supabase
        .from("planos_saude")
        .delete()
        .eq("id", id);

      if (error) throw error;

      toast({
        title: "Sucesso!",
        description: "Plano excluído com sucesso.",
      });
      fetchPlanos();
    } catch (error: any) {
      toast({
        title: "Erro ao excluir plano",
        description: error.message,
        variant: "destructive",
      });
    }
  };

  const filteredPlanos = planos.filter(plano =>
    plano.nome.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (isLoading) {
    return (
      <MainLayout>
        <div className="flex items-center justify-center h-96">
          <Loader2 className="h-8 w-8 animate-spin text-primary" />
        </div>
      </MainLayout>
    );
  }

  return (
    <MainLayout>
      <div className="space-y-6">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold tracking-tight">Planos de Saúde</h1>
            <p className="text-muted-foreground">
              Gerencie os planos de saúde aceitos pela clínica
            </p>
          </div>
          <NewPlanoSaudeDialog onSuccess={fetchPlanos}>
            <Button>
              <Plus className="mr-2 h-4 w-4" />
              Novo Plano
            </Button>
          </NewPlanoSaudeDialog>
        </div>

        <div className="relative">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-muted-foreground h-4 w-4" />
          <Input
            placeholder="Buscar planos..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="pl-10"
          />
        </div>

        {filteredPlanos.length === 0 ? (
          <Card>
            <CardContent className="flex flex-col items-center justify-center py-12">
              <p className="text-muted-foreground mb-4">
                {searchTerm ? "Nenhum plano encontrado" : "Nenhum plano cadastrado"}
              </p>
              {!searchTerm && (
                <NewPlanoSaudeDialog onSuccess={fetchPlanos}>
                  <Button>
                    <Plus className="mr-2 h-4 w-4" />
                    Cadastrar Primeiro Plano
                  </Button>
                </NewPlanoSaudeDialog>
              )}
            </CardContent>
          </Card>
        ) : (
          <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
            {filteredPlanos.map((plano) => (
              <Card key={plano.id}>
                <CardHeader className="flex flex-row items-start justify-between space-y-0 pb-2">
                  <CardTitle className="text-lg font-semibold">
                    {plano.nome}
                  </CardTitle>
                  <Badge variant={plano.ativo ? "default" : "secondary"}>
                    {plano.ativo ? "Ativo" : "Inativo"}
                  </Badge>
                </CardHeader>
                <CardContent className="space-y-4">
                  {plano.descricao && (
                    <p className="text-sm text-muted-foreground">
                      {plano.descricao}
                    </p>
                  )}
                  <div className="flex gap-2">
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => setEditingId(plano.id)}
                      className="flex-1"
                    >
                      <Pencil className="mr-2 h-3 w-3" />
                      Editar
                    </Button>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => handleDelete(plano.id, plano.nome)}
                      className="flex-1"
                    >
                      <Trash2 className="mr-2 h-3 w-3" />
                      Excluir
                    </Button>
                  </div>
                </CardContent>
              </Card>
            ))}
          </div>
        )}

        {editingId && (
          <EditPlanoSaudeDialog
            planoId={editingId}
            open={!!editingId}
            onOpenChange={(open) => !open && setEditingId(null)}
            onSuccess={fetchPlanos}
          />
        )}
      </div>
    </MainLayout>
  );
}

import React, { useState, useEffect } from "react";
import { MainLayout } from "@/components/layout/MainLayout";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { Input } from "@/components/ui/input";
import { 
  Edit, 
  Trash2, 
  Clock, 
  DollarSign,
  Settings,
  Loader2,
  CheckCircle2,
  Search
} from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { NewProcedimentoDialog } from "@/components/schedule/NewProcedimentoDialog";
import { EditProcedimentoDialog } from "@/components/schedule/EditProcedimentoDialog";

interface Procedimento {
  id: string;
  nome: string;
  duracao_minutos: number;
  preco: number | null;
  codigo_tuss: string | null;
  descricao: string | null;
  tempo_preparo_minutos: number | null;
  instrucoes: string | null;
  requisitos: string | null;
  confirmacao_24h: boolean;
  ativo: boolean;
  created_at: string;
}

const Procedimentos = () => {
  const [procedimentos, setProcedimentos] = useState<Procedimento[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [editingId, setEditingId] = useState<string | null>(null);
  const { toast } = useToast();

  const fetchProcedimentos = async () => {
    try {
      setIsLoading(true);
      const { data, error } = await supabase
        .from('procedimentos')
        .select('*')
        .order('nome');

      if (error) throw error;
      setProcedimentos(data || []);
    } catch (error) {
      console.error('Erro ao buscar procedimentos:', error);
      toast({
        title: "Erro",
        description: "Não foi possível carregar os procedimentos.",
        variant: "destructive"
      });
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchProcedimentos();
  }, []);

  const toggleStatus = async (id: string, currentStatus: boolean) => {
    try {
      const { error } = await supabase
        .from('procedimentos')
        .update({ ativo: !currentStatus })
        .eq('id', id);

      if (error) throw error;

      setProcedimentos(prev => prev.map(proc => 
        proc.id === id ? { ...proc, ativo: !currentStatus } : proc
      ));

      toast({
        title: "Status atualizado",
        description: `Procedimento ${!currentStatus ? "ativado" : "desativado"} com sucesso.`
      });
    } catch (error) {
      console.error('Erro ao atualizar status:', error);
      toast({
        title: "Erro",
        description: "Não foi possível atualizar o status.",
        variant: "destructive"
      });
    }
  };

  const deleteProcedimento = async (id: string) => {
    if (!confirm("Tem certeza que deseja excluir este procedimento? Esta ação não pode ser desfeita.")) return;

    try {
      const { error } = await supabase
        .from('procedimentos')
        .delete()
        .eq('id', id);

      if (error) throw error;

      setProcedimentos(prev => prev.filter(proc => proc.id !== id));

      toast({
        title: "Procedimento excluído",
        description: "O procedimento foi removido com sucesso."
      });
    } catch (error) {
      console.error('Erro ao excluir procedimento:', error);
      toast({
        title: "Erro",
        description: "Não foi possível excluir o procedimento.",
        variant: "destructive"
      });
    }
  };

  const filteredProcedimentos = procedimentos.filter(proc =>
    proc.nome.toLowerCase().includes(searchTerm.toLowerCase()) ||
    proc.codigo_tuss?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const activeProcedimentos = filteredProcedimentos.filter(p => p.ativo).length;

  return (
    <MainLayout>
      <div className="space-y-6 p-6">
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
          <div>
            <h1 className="text-3xl font-bold text-foreground">Procedimentos</h1>
            <p className="text-muted-foreground">
              Gerencie os procedimentos oferecidos
            </p>
          </div>
          <NewProcedimentoDialog onSuccess={fetchProcedimentos}>
            <Button size="lg">
              <Settings className="mr-2 h-5 w-5" />
              Novo Procedimento
            </Button>
          </NewProcedimentoDialog>
        </div>

        <div className="flex gap-4">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-muted-foreground h-4 w-4" />
            <Input
              placeholder="Buscar procedimentos..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="pl-10"
            />
          </div>
        </div>

        <Card className="p-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="flex items-center gap-3">
              <div className="p-3 rounded-lg bg-primary/10">
                <Settings className="h-6 w-6 text-primary" />
              </div>
              <div>
                <p className="text-sm text-muted-foreground">Procedimentos Ativos</p>
                <p className="text-2xl font-bold">{activeProcedimentos}</p>
              </div>
            </div>
            <div className="flex items-center gap-3">
              <div className="p-3 rounded-lg bg-secondary/10">
                <CheckCircle2 className="h-6 w-6 text-secondary-foreground" />
              </div>
              <div>
                <p className="text-sm text-muted-foreground">Total de Procedimentos</p>
                <p className="text-2xl font-bold">{procedimentos.length}</p>
              </div>
            </div>
          </div>
        </Card>

        {isLoading ? (
          <div className="flex justify-center items-center py-12">
            <Loader2 className="h-8 w-8 animate-spin text-primary" />
          </div>
        ) : filteredProcedimentos.length === 0 ? (
          <Card className="p-12">
            <div className="text-center">
              <Settings className="mx-auto h-12 w-12 text-muted-foreground/50 mb-4" />
              <h3 className="text-lg font-semibold mb-2">
                {searchTerm ? "Nenhum procedimento encontrado" : "Nenhum procedimento cadastrado"}
              </h3>
              <p className="text-muted-foreground mb-4">
                {searchTerm 
                  ? "Tente ajustar sua busca"
                  : "Comece adicionando seu primeiro procedimento"
                }
              </p>
            </div>
          </Card>
        ) : (
          <div className="grid gap-4">
            {filteredProcedimentos.map((procedimento) => (
              <Card key={procedimento.id} className="p-6 hover:shadow-md transition-shadow">
                <div className="flex flex-col sm:flex-row justify-between gap-4">
                  <div className="flex-1 space-y-3">
                    <div className="flex items-start justify-between">
                      <div>
                        <h3 className="font-semibold text-lg">{procedimento.nome}</h3>
                        {procedimento.codigo_tuss && (
                          <p className="text-sm text-muted-foreground">
                            TUSS: {procedimento.codigo_tuss}
                          </p>
                        )}
                      </div>
                      <div className="flex items-center gap-2">
                        <Badge variant={procedimento.ativo ? "default" : "secondary"}>
                          {procedimento.ativo ? "Ativo" : "Inativo"}
                        </Badge>
                        {procedimento.confirmacao_24h && (
                          <Badge variant="outline">Confirmação 24h</Badge>
                        )}
                      </div>
                    </div>

                    {procedimento.descricao && (
                      <p className="text-sm text-muted-foreground">{procedimento.descricao}</p>
                    )}

                    <div className="flex flex-wrap gap-4 text-sm">
                      <div className="flex items-center gap-2">
                        <Clock className="h-4 w-4 text-muted-foreground" />
                        <span>{procedimento.duracao_minutos} minutos</span>
                      </div>
                      {procedimento.tempo_preparo_minutos && (
                        <div className="flex items-center gap-2">
                          <Clock className="h-4 w-4 text-muted-foreground" />
                          <span>Preparo: {procedimento.tempo_preparo_minutos} min</span>
                        </div>
                      )}
                      {procedimento.preco && (
                        <div className="flex items-center gap-2">
                          <DollarSign className="h-4 w-4 text-muted-foreground" />
                          <span>R$ {Number(procedimento.preco).toFixed(2)}</span>
                        </div>
                      )}
                    </div>
                  </div>

                  <div className="flex sm:flex-col gap-2 justify-end">
                    <div className="flex items-center gap-2">
                      <Switch
                        checked={procedimento.ativo}
                        onCheckedChange={() => toggleStatus(procedimento.id, procedimento.ativo)}
                      />
                    </div>
                    <EditProcedimentoDialog
                      procedimentoId={procedimento.id}
                      open={editingId === procedimento.id}
                      onOpenChange={(open) => setEditingId(open ? procedimento.id : null)}
                      onSuccess={fetchProcedimentos}
                    >
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => setEditingId(procedimento.id)}
                      >
                        <Edit className="h-4 w-4" />
                      </Button>
                    </EditProcedimentoDialog>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => deleteProcedimento(procedimento.id)}
                    >
                      <Trash2 className="h-4 w-4 text-destructive" />
                    </Button>
                  </div>
                </div>
              </Card>
            ))}
          </div>
        )}

        {editingId && (
          <EditProcedimentoDialog
            procedimentoId={editingId}
            open={true}
            onOpenChange={(open) => !open && setEditingId(null)}
            onSuccess={fetchProcedimentos}
          />
        )}
      </div>
    </MainLayout>
  );
};

export default Procedimentos;

import React, { useState, useEffect } from "react";
import { MainLayout } from "@/components/layout/MainLayout";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import {
  Edit,
  Trash2,
  User,
  Loader2,
  Search,
  Mail,
  Phone as IconeTelefone,
  FileText,
  Upload
} from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { NewProfessionalDialog } from "@/components/schedule/NewProfessionalDialog";
import { EditProfessionalDialog } from "@/components/schedule/EditProfessionalDialog";
import { DeleteProfessionalDialog } from "@/components/schedule/DeleteProfessionalDialog";

interface Professional {
  id: string;
  nome: string;
  email: string | null;
  telefone: string | null;
  cpf: string | null;
  conselho_profissional: string | null;
  numero_registro: string | null;
  uf_registro: string | null;
  role: string;
  especialidade_id: string | null;
  especialidades?: {
    nome: string;
  };
  created_at: string;
}

const Profissionais = () => {
  const [professionals, setProfessionals] = useState<Professional[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [editingId, setEditingId] = useState<string | null>(null);
  const [deletingProfessional, setDeletingProfessional] = useState<{ id: string; nome: string } | null>(null);
  const { toast } = useToast();

  const fetchProfessionals = async () => {
    try {
      setIsLoading(true);
      const { data, error } = await supabase
        .from('profiles')
        .select(`
          *,
          especialidades:especialidade_id(nome)
        `)
        .eq('role', 'profissional')
        .order('nome');

      if (error) throw error;
      setProfessionals((data as any) || []);
    } catch (error) {
      console.error('Erro ao buscar profissionais:', error);
      toast({
        title: "Erro",
        description: "Não foi possível carregar os profissionais.",
        variant: "destructive"
      });
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchProfessionals();
  }, []);

  const filteredProfessionals = professionals.filter(p =>
    p.nome.toLowerCase().includes(searchTerm.toLowerCase()) ||
    (p.email && p.email.toLowerCase().includes(searchTerm.toLowerCase())) ||
    (p.numero_registro && p.numero_registro.includes(searchTerm))
  );

  return (
    <MainLayout>
      <div className="space-y-6">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold text-foreground">Profissionais</h1>
            <p className="text-muted-foreground">
              Gerenciar cadastro de profissionais de saúde ({professionals.length})
            </p>
          </div>
          {!isLoading && professionals.length > 0 && (
            <div className="flex gap-2">
              <Button variant="outline" onClick={() => window.location.href = '/profissionais/recontratar'}>
                <Upload className="mr-2 h-4 w-4" />
                Recontratar (CSV)
              </Button>
              <NewProfessionalDialog onSuccess={() => fetchProfessionals()} />
            </div>
          )}
        </div>

        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <Input
            placeholder="Buscar por nome, e-mail ou registro..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="pl-10"
          />
        </div>

        {isLoading ? (
          <div className="flex items-center justify-center py-12">
            <Loader2 className="h-8 w-8 animate-spin text-primary" />
          </div>
        ) : filteredProfessionals.length === 0 ? (
          <div className="text-center py-12">
            <User className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
            <h3 className="text-lg font-semibold mb-2">
              {searchTerm ? "Nenhum profissional encontrado" : "Nenhum profissional cadastrado"}
            </h3>
            <p className="text-muted-foreground mb-4">
              {searchTerm ? "Tente uma busca diferente" : "Comece adicionando seu primeiro profissional"}
            </p>
            {!searchTerm && <NewProfessionalDialog onSuccess={() => fetchProfessionals()} />}
          </div>
        ) : (
          <div className="grid gap-4">
            {filteredProfessionals.map((professional) => (
              <Card key={professional.id} className="p-6">
                <div className="flex items-start justify-between mb-4">
                  <div className="flex items-center gap-4">
                    <div className="p-3 bg-primary-light rounded-full">
                      <User className="h-6 w-6 text-primary" />
                    </div>
                    <div>
                      <h3 className="text-lg font-semibold text-foreground">{professional.nome}</h3>
                      {professional.especialidades && (
                        <Badge variant="secondary" className="mt-1">
                          {professional.especialidades.nome}
                        </Badge>
                      )}
                    </div>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-4">
                  {professional.email && (
                    <div className="flex items-center gap-2">
                      <Mail className="h-4 w-4 text-muted-foreground" />
                      <span className="text-sm">{professional.email}</span>
                    </div>
                  )}
                  {professional.telefone && (
                    <div className="flex items-center gap-2">
                      <IconeTelefone className="h-4 w-4 text-muted-foreground" />
                      <span className="text-sm">{professional.telefone}</span>
                    </div>
                  )}
                  {professional.conselho_profissional && professional.numero_registro && (
                    <div className="flex items-center gap-2">
                      <FileText className="h-4 w-4 text-muted-foreground" />
                      <span className="text-sm">
                        {professional.conselho_profissional} {professional.numero_registro}
                        {professional.uf_registro && ` - ${professional.uf_registro}`}
                      </span>
                    </div>
                  )}
                </div>

                <div className="flex gap-2">
                  <Button
                    size="sm"
                    variant="outline"
                    onClick={() => setEditingId(professional.id)}
                  >
                    <Edit className="h-4 w-4 mr-2" />
                    Editar
                  </Button>
                  <Button
                    size="sm"
                    variant="outline"
                    onClick={() => setDeletingProfessional({ id: professional.id, nome: professional.nome })}
                    className="text-destructive hover:text-destructive"
                  >
                    <Trash2 className="h-4 w-4 mr-2" />
                    Excluir
                  </Button>
                </div>
              </Card>
            ))}
          </div>
        )}
      </div>

      {editingId && (
        <EditProfessionalDialog
          professionalId={editingId}
          open={!!editingId}
          onOpenChange={(open) => !open && setEditingId(null)}
          onSuccess={() => fetchProfessionals()}
        />
      )}

      {deletingProfessional && (
        <DeleteProfessionalDialog
          professional={deletingProfessional}
          open={!!deletingProfessional}
          onOpenChange={(open) => !open && setDeletingProfessional(null)}
          onSuccess={() => fetchProfessionals()}
        />
      )}
    </MainLayout>
  );
};

export default Profissionais;

import { useState, useEffect } from "react";
import { MainLayout } from "@/components/layout/MainLayout";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { FileText, Search, Plus } from "lucide-react";
import { Badge } from "@/components/ui/badge";

export default function Prontuarios() {
  const [prontuarios, setProntuarios] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");

  useEffect(() => {
    loadProntuarios();
  }, []);

  const loadProntuarios = async () => {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      const { data: profile } = await supabase
        .from('profiles')
        .select('tenant_id, role')
        .eq('id', user.id)
        .single();

      if (!profile) return;

      let query = supabase
        .from('prontuarios' as any)
        .select(`
          *,
          pacientes(nome, telefone),
          profiles(nome)
        `)
        .eq('tenant_id', profile.tenant_id)
        .order('data_atendimento', { ascending: false });

      // Profissionais veem apenas seus próprios prontuários
      if (profile.role === 'profissional') {
        query = query.eq('profissional_id', user.id);
      }

      const { data, error } = await query;

      if (error) throw error;
      setProntuarios(data || []);
    } catch (error: any) {
      console.error('Erro ao carregar prontuários:', error);
      toast.error('Erro ao carregar prontuários');
    } finally {
      setLoading(false);
    }
  };

  const filteredProntuarios = prontuarios.filter(p =>
    p.pacientes?.nome.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.profiles?.nome.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const getStatusBadge = (status: string) => {
    const variants: Record<string, any> = {
      rascunho: "secondary",
      finalizado: "default",
      assinado: "default"
    };
    return <Badge variant={variants[status] || "secondary"}>{status}</Badge>;
  };

  return (
    <MainLayout>
      <div className="space-y-6">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold">Prontuários Eletrônicos</h1>
            <p className="text-muted-foreground">
              Gerenciamento de prontuários médicos (SOAP)
            </p>
          </div>
          <Button>
            <Plus className="h-4 w-4 mr-2" />
            Novo Prontuário
          </Button>
        </div>

        <Card>
          <CardHeader>
            <CardTitle>Buscar Prontuários</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="relative">
              <Search className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
              <Input
                placeholder="Buscar por paciente ou profissional..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pl-10"
              />
            </div>
          </CardContent>
        </Card>

        {loading ? (
          <Card>
            <CardContent className="py-8">
              <div className="flex items-center justify-center">
                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
              </div>
            </CardContent>
          </Card>
        ) : filteredProntuarios.length === 0 ? (
          <Card>
            <CardContent className="py-8">
              <div className="text-center text-muted-foreground">
                <FileText className="h-12 w-12 mx-auto mb-4 opacity-50" />
                <p>Nenhum prontuário encontrado</p>
              </div>
            </CardContent>
          </Card>
        ) : (
          <div className="grid gap-4">
            {filteredProntuarios.map((prontuario) => (
              <Card key={prontuario.id} className="hover:shadow-md transition-shadow">
                <CardContent className="p-6">
                  <div className="flex items-start justify-between">
                    <div className="flex-1">
                      <div className="flex items-center gap-3 mb-2">
                        <h3 className="font-semibold text-lg">
                          {prontuario.pacientes?.nome}
                        </h3>
                        {getStatusBadge(prontuario.status)}
                      </div>
                      <div className="space-y-1 text-sm text-muted-foreground">
                        <p>
                          <strong>Profissional:</strong> Dr(a). {prontuario.profiles?.nome}
                        </p>
                        <p>
                          <strong>Data do Atendimento:</strong>{' '}
                          {new Date(prontuario.data_atendimento).toLocaleDateString('pt-BR', {
                            day: '2-digit',
                            month: '2-digit',
                            year: 'numeric',
                            hour: '2-digit',
                            minute: '2-digit'
                          })}
                        </p>
                        {prontuario.cid10_principal && (
                          <p>
                            <strong>CID-10:</strong> {prontuario.cid10_principal}
                          </p>
                        )}
                      </div>
                      {prontuario.avaliacao && (
                        <p className="mt-3 text-sm line-clamp-2">
                          <strong>Avaliação:</strong> {prontuario.avaliacao}
                        </p>
                      )}
                    </div>
                    <Button variant="outline" size="sm">
                      Visualizar
                    </Button>
                  </div>
                </CardContent>
              </Card>
            ))}
          </div>
        )}
      </div>
    </MainLayout>
  );
}

import { useState, useEffect } from "react";
import { MainLayout } from "@/components/layout/MainLayout";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import {
  Download, Search, Calendar, Users, Stethoscope,
  FileText, Activity, AlertTriangle, Clock, CheckCircle2, FileDown, ArrowUpDown
} from "lucide-react";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";
import autoTable from "jspdf-autotable";
import { Tables } from "@/integrations/supabase/types";
import "./Relatorios.css";

export default function Relatorios() {
  const { toast } = useToast();
  const [loading, setLoading] = useState(true);

  // Estados de filtro para cada relatório
  const [filterAgendamento, setFilterAgendamento] = useState({ search: "", status: "", dateFrom: "", dateTo: "" });
  const [filterPaciente, setFilterPaciente] = useState({ search: "", risco: "" });
  const [filterProfissional, setFilterProfissional] = useState({ search: "", especialidade: "" });
  const [filterConfirmacao, setFilterConfirmacao] = useState({ search: "", dateFrom: "", dateTo: "" });
  const [filterListaEspera, setFilterListaEspera] = useState({ search: "", prioridade: "" });
  const [filterAlerta, setFilterAlerta] = useState({ search: "", tipo: "", prioridade: "" });
  const [filterMensagem, setFilterMensagem] = useState({ search: "", canal: "", status: "" });

  // Estados de ordenação
  const [sortAgendamento, setSortAgendamento] = useState({ field: 'inicio', direction: 'desc' as 'asc' | 'desc' });
  const [sortPaciente, setSortPaciente] = useState({ field: 'nome', direction: 'asc' as 'asc' | 'desc' });
  const [sortProfissional, setSortProfissional] = useState({ field: 'nome', direction: 'asc' as 'asc' | 'desc' });

  // Estados para cada relatório
  const [agendamentos, setAgendamentos] = useState<any[]>([]);
  const [pacientes, setPacientes] = useState<Tables<"pacientes">[]>([]);
  const [profissionais, setProfissionais] = useState<any[]>([]);
  const [confirmacoes, setConfirmacoes] = useState<any[]>([]);
  const [listaEspera, setListaEspera] = useState<any[]>([]);
  const [alertas, setAlertas] = useState<any[]>([]);
  const [mensagens, setMensagens] = useState<Tables<"log_mensagens">[]>([]);

  useEffect(() => {
    fetchAllReports();
  }, []);

  const fetchAllReports = async () => {
    setLoading(true);
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      const { data: profile } = await supabase
        .from('profiles')
        .select('tenant_id')
        .eq('id', user.id)
        .single();

      if (!profile?.tenant_id) return;

      // Buscar agendamentos
      const { data: agendamentosData } = await supabase
        .from('agenda')
        .select(`
          *,
          pacientes:paciente_id(nome, telefone),
          procedimentos:servico_id(nome),
          profiles:profissional_id(nome)
        `)
        .eq('tenant_id', profile.tenant_id)
        .order('inicio', { ascending: false })
        .limit(100);

      // Buscar pacientes
      const { data: pacientesData } = await supabase
        .from('pacientes')
        .select('*')
        .eq('tenant_id', profile.tenant_id)
        .order('created_at', { ascending: false });

      // Buscar profissionais
      const { data: profissionaisData } = await supabase
        .from('profiles')
        .select(`
          *,
          especialidades:especialidade_id(nome)
        `)
        .eq('tenant_id', profile.tenant_id)
        .eq('role', 'profissional')
        .order('created_at', { ascending: false });

      // Buscar confirmações (agendamentos confirmados)
      const { data: confirmacoesData } = await supabase
        .from('agenda')
        .select(`
          *,
          pacientes:paciente_id(nome, telefone),
          procedimentos:servico_id(nome)
        `)
        .eq('tenant_id', profile.tenant_id)
        .eq('confirmado', true)
        .order('confirmado_em', { ascending: false })
        .limit(100);

      // Buscar lista de espera
      const { data: listaEsperaData } = await supabase
        .from('lista_espera')
        .select(`
          *,
          pacientes:paciente_id(nome, telefone),
          procedimentos:servico_id(nome)
        `)
        .eq('tenant_id', profile.tenant_id)
        .eq('ativo', true)
        .order('prioridade', { ascending: false });

      // Buscar alertas
      const { data: alertasData } = await supabase
        .from('alertas_risco')
        .select(`
          *,
          pacientes:paciente_id(nome, telefone)
        `)
        .eq('tenant_id', profile.tenant_id)
        .order('created_at', { ascending: false })
        .limit(100);

      // Buscar mensagens
      const { data: mensagensData } = await supabase
        .from('log_mensagens')
        .select('*')
        .eq('tenant_id', profile.tenant_id)
        .order('created_at', { ascending: false })
        .limit(100);

      setAgendamentos(agendamentosData || []);
      setPacientes(pacientesData || []);
      setProfissionais(profissionaisData || []);
      setConfirmacoes(confirmacoesData || []);
      setListaEspera(listaEsperaData || []);
      setAlertas(alertasData || []);
      setMensagens(mensagensData || []);
    } catch (error) {
      console.error('Erro ao buscar relatórios:', error);
      toast({
        title: "Erro ao carregar relatórios",
        description: "Não foi possível carregar os dados dos relatórios.",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const exportToCSV = (data: any[], filename: string) => {
    if (data.length === 0) {
      toast({
        title: "Sem dados para exportar",
        description: "Não há dados disponíveis neste relatório.",
        variant: "destructive",
      });
      return;
    }

    const headers = Object.keys(data[0]).join(',');
    const rows = data.map(row =>
      Object.values(row).map(val =>
        typeof val === 'object' ? JSON.stringify(val) : val
      ).join(',')
    );

    const csv = [headers, ...rows].join('\n');
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${filename}_${format(new Date(), 'yyyy-MM-dd')}.csv`;
    a.click();

    toast({
      title: "Exportado com sucesso",
      description: `Relatório ${filename} exportado em CSV.`,
    });
  };

  const exportToPDF = (data: any[], filename: string, columns: string[], headers: string[]) => {
    if (data.length === 0) {
      toast({
        title: "Sem dados para exportar",
        description: "Não há dados disponíveis neste relatório.",
        variant: "destructive",
      });
      return;
    }

    const doc = new jsPDF();

    // Título
    doc.setFontSize(16);
    doc.text(`Relatório - ${filename}`, 14, 15);
    doc.setFontSize(10);
    doc.text(`Gerado em: ${format(new Date(), "dd/MM/yyyy HH:mm", { locale: ptBR })}`, 14, 22);

    // Tabela
    const tableData = data.map(row =>
      columns.map(col => {
        const value = row[col];
        if (typeof value === 'object' && value !== null) {
          return JSON.stringify(value);
        }
        return value || '-';
      })
    );

    autoTable(doc, {
      head: [headers],
      body: tableData,
      startY: 28,
      styles: { fontSize: 8 },
      headStyles: { fillColor: [1, 108, 165] },
    });

    doc.save(`${filename}_${format(new Date(), 'yyyy-MM-dd')}.pdf`);

    toast({
      title: "Exportado com sucesso",
      description: `Relatório ${filename} exportado em PDF.`,
    });
  };

  const getStatusBadge = (status: string) => {
    const statusMap: Record<string, { label: string; variant: any }> = {
      agendado: { label: "Agendado", variant: "default" },
      confirmado: { label: "Confirmado", variant: "success" },
      realizado: { label: "Realizado", variant: "success" },
      cancelado: { label: "Cancelado", variant: "destructive" },
      faltou: { label: "Faltou", variant: "destructive" },
    };

    const config = statusMap[status] || { label: status, variant: "default" };
    return <Badge variant={config.variant as any}>{config.label}</Badge>;
  };

  const getPrioridadeBadge = (prioridade: string) => {
    const prioridadeMap: Record<string, { variant: any }> = {
      baixa: { variant: "secondary" },
      media: { variant: "default" },
      alta: { variant: "warning" },
      critica: { variant: "destructive" },
    };

    const config = prioridadeMap[prioridade] || { variant: "default" };
    return <Badge variant={config.variant as any}>{prioridade}</Badge>;
  };

  const sortData = (data: any[], field: string, direction: 'asc' | 'desc') => {
    return [...data].sort((a, b) => {
      let aVal = a[field];
      let bVal = b[field];

      // Handle nested objects (e.g., pacientes.nome)
      if (field.includes('.')) {
        const parts = field.split('.');
        aVal = parts.reduce((obj, key) => obj?.[key], a);
        bVal = parts.reduce((obj, key) => obj?.[key], b);
      }

      // Handle null values
      if (aVal == null) return 1;
      if (bVal == null) return -1;

      // String comparison
      if (typeof aVal === 'string' && typeof bVal === 'string') {
        return direction === 'asc'
          ? aVal.localeCompare(bVal)
          : bVal.localeCompare(aVal);
      }

      // Number/Date comparison
      return direction === 'asc' ? aVal - bVal : bVal - aVal;
    });
  };

  const handleSort = (field: string, currentSort: any, setSortFunc: any) => {
    const newDirection = currentSort.field === field && currentSort.direction === 'asc' ? 'desc' : 'asc';
    setSortFunc({ field, direction: newDirection });
  };

  if (loading) {
    return (
      <MainLayout>
        <div className="flex items-center justify-center min-h-screen">
          <p className="text-muted-foreground">Carregando relatórios...</p>
        </div>
      </MainLayout>
    );
  }

  return (
    <MainLayout>
      <div className="space-y-6 reports-page">
        <div>
          <h1 className="text-3xl font-bold text-foreground">Relatórios</h1>
          <p className="text-muted-foreground">
            Visualize e exporte relatórios completos do sistema
          </p>
        </div>

        <Tabs defaultValue="agendamentos" className="space-y-4">
          <TabsList className="grid w-full grid-cols-4 lg:grid-cols-7">
            <TabsTrigger value="agendamentos">
              <Calendar className="h-4 w-4 mr-2" />
              Agendamentos
            </TabsTrigger>
            <TabsTrigger value="pacientes">
              <Users className="h-4 w-4 mr-2" />
              Pacientes
            </TabsTrigger>
            <TabsTrigger value="profissionais">
              <Stethoscope className="h-4 w-4 mr-2" />
              Profissionais
            </TabsTrigger>
            <TabsTrigger value="confirmacoes">
              <CheckCircle2 className="h-4 w-4 mr-2" />
              Confirmações
            </TabsTrigger>
            <TabsTrigger value="lista-espera">
              <Clock className="h-4 w-4 mr-2" />
              Lista Espera
            </TabsTrigger>
            <TabsTrigger value="alertas">
              <AlertTriangle className="h-4 w-4 mr-2" />
              Alertas
            </TabsTrigger>
            <TabsTrigger value="mensagens">
              <Activity className="h-4 w-4 mr-2" />
              Mensagens
            </TabsTrigger>
          </TabsList>

          {/* Relatório de Agendamentos */}
          <TabsContent value="agendamentos">
            <Card>
              <CardHeader>
                <div className="flex items-center justify-between">
                  <div>
                    <CardTitle>Relatório de Agendamentos</CardTitle>
                    <CardDescription>
                      {agendamentos.filter(a => {
                        const matchSearch = !filterAgendamento.search || a.pacientes?.nome?.toLowerCase().includes(filterAgendamento.search.toLowerCase());
                        const matchStatus = !filterAgendamento.status || a.status === filterAgendamento.status;
                        const matchDateFrom = !filterAgendamento.dateFrom || new Date(a.inicio) >= new Date(filterAgendamento.dateFrom);
                        const matchDateTo = !filterAgendamento.dateTo || new Date(a.inicio) <= new Date(filterAgendamento.dateTo);
                        return matchSearch && matchStatus && matchDateFrom && matchDateTo;
                      }).length} agendamentos encontrados
                    </CardDescription>
                  </div>
                  <div className="flex gap-2">
                    <Button
                      onClick={() => exportToCSV(
                        agendamentos.filter(a => {
                          const matchSearch = !filterAgendamento.search || a.pacientes?.nome?.toLowerCase().includes(filterAgendamento.search.toLowerCase());
                          const matchStatus = !filterAgendamento.status || a.status === filterAgendamento.status;
                          const matchDateFrom = !filterAgendamento.dateFrom || new Date(a.inicio) >= new Date(filterAgendamento.dateFrom);
                          const matchDateTo = !filterAgendamento.dateTo || new Date(a.inicio) <= new Date(filterAgendamento.dateTo);
                          return matchSearch && matchStatus && matchDateFrom && matchDateTo;
                        }),
                        'agendamentos'
                      )}
                    >
                      <Download className="h-4 w-4 mr-2" />
                      Exportar CSV
                    </Button>
                    <Button
                      variant="destructive"
                      onClick={() => exportToPDF(
                        agendamentos.filter(a => {
                          const matchSearch = !filterAgendamento.search || a.pacientes?.nome?.toLowerCase().includes(filterAgendamento.search.toLowerCase());
                          const matchStatus = !filterAgendamento.status || a.status === filterAgendamento.status;
                          const matchDateFrom = !filterAgendamento.dateFrom || new Date(a.inicio) >= new Date(filterAgendamento.dateFrom);
                          const matchDateTo = !filterAgendamento.dateTo || new Date(a.inicio) <= new Date(filterAgendamento.dateTo);
                          return matchSearch && matchStatus && matchDateFrom && matchDateTo;
                        }).map(a => ({
                          data: format(new Date(a.inicio), "dd/MM/yyyy HH:mm", { locale: ptBR }),
                          paciente: a.pacientes?.nome,
                          servico: a.servicos?.nome,
                          profissional: a.profiles?.nome || '-',
                          status: a.status,
                          confirmado: a.confirmado ? 'Sim' : 'Não'
                        })),
                        'agendamentos',
                        ['data', 'paciente', 'servico', 'profissional', 'status', 'confirmado'],
                        ['Data/Hora', 'Paciente', 'Serviço', 'Profissional', 'Status', 'Confirmado']
                      )}
                    >
                      <FileDown className="h-4 w-4 mr-2" />
                      Exportar PDF
                    </Button>
                  </div>
                </div>
              </CardHeader>
              <CardContent>
                <div className="mb-4 grid grid-cols-1 md:grid-cols-4 gap-4">
                  <div className="relative">
                    <Search className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
                    <Input
                      placeholder="Buscar paciente..."
                      value={filterAgendamento.search}
                      onChange={(e) => setFilterAgendamento({ ...filterAgendamento, search: e.target.value })}
                      className="pl-10"
                    />
                  </div>
                  <select
                    className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm"
                    value={filterAgendamento.status}
                    onChange={(e) => setFilterAgendamento({ ...filterAgendamento, status: e.target.value })}
                  >
                    <option value="">Todos os status</option>
                    <option value="agendado">Agendado</option>
                    <option value="confirmado">Confirmado</option>
                    <option value="realizado">Realizado</option>
                    <option value="cancelado">Cancelado</option>
                    <option value="faltou">Faltou</option>
                  </select>
                  <Input
                    type="date"
                    placeholder="Data início"
                    value={filterAgendamento.dateFrom}
                    onChange={(e) => setFilterAgendamento({ ...filterAgendamento, dateFrom: e.target.value })}
                  />
                  <Input
                    type="date"
                    placeholder="Data fim"
                    value={filterAgendamento.dateTo}
                    onChange={(e) => setFilterAgendamento({ ...filterAgendamento, dateTo: e.target.value })}
                  />
                </div>
