                            <Button variant="outline" className="justify-start h-auto py-3" onClick={() => onAdd('trigger', { event: 'onAppointmentNotConfirmed' })}>
                                <Clock className="mr-2 h-4 w-4" /> Cliente Não Confirmou (D-1)
                            </Button>
