    const [keys, setKeys] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [newKey, setNewKey] = useState<string | null>(null);

    useEffect(() => {
        if (tenantId) loadKeys();
    }, [tenantId]);

    const loadKeys = async () => {
        setLoading(true);
        const { data } = await supabase
            .from('api_keys')
            .select('*')
            .eq('tenant_id', tenantId)
            .order('created_at', { ascending: false });
        setKeys(data || []);
        setLoading(false);
    };

    const handleCreateKey = async (nome: string) => {
        try {
            // Gerar chave no cliente (apenas para demonstração, idealmente backend retornaria)
            // Formato: sk_live_RANDOM
            const randomPart = Array.from(crypto.getRandomValues(new Uint8Array(24)))
                .map(b => b.toString(16).padStart(2, '0')).join('');
            const rawKey = `sk_live_${randomPart}`;

            // Hash SHA-256
            const encoder = new TextEncoder();
            const data = encoder.encode(rawKey);
            const hashBuffer = await crypto.subtle.digest('SHA-256', data);
            const hashArray = Array.from(new Uint8Array(hashBuffer));
            const hashHex = hashArray.map(b => b.toString(16).padStart(2, '0')).join('');

            const { data: keyData, error } = await supabase.from('api_keys').insert({
                tenant_id: tenantId,
                nome,
                chave_hash: hashHex,
                prefixo: `sk_live_...${randomPart.slice(-4)}`
            }).select().single();

            if (error) throw error;

            // Log de auditoria
            await supabase.from('system_logs').insert({
                tenant_id: tenantId,
                event_type: 'api_key_created',
                details: { key_id: keyData.id, key_name: nome }
            });

            setNewKey(rawKey); // Mostrar chave completa UMA VEZ
            loadKeys();
            toast.success("Chave de API criada com sucesso!");
        } catch (error) {
            console.error(error);
            toast.error("Erro ao criar chave.");
        }
    };

    const handleRevoke = async (id: string) => {
        await supabase.from('api_keys').delete().eq('id', id);
        loadKeys();
        toast.success("Chave revogada.");
    };

    return (
        <Card>
            <CardHeader className="flex flex-row items-center justify-between">
                <div>
                    <CardTitle>Chaves de API</CardTitle>
                    <CardDescription>Use estas chaves para autenticar requisições à nossa API pública.</CardDescription>
                </div>
                <NewKeyDialog onCreate={handleCreateKey} />
            </CardHeader>
            <CardContent>
                {newKey && (
                    <div className="mb-6 p-4 bg-green-50 dark:bg-green-900/20 border border-green-200 rounded-lg">
                        <h4 className="font-semibold text-green-800 dark:text-green-300 mb-2">Nova Chave Gerada</h4>
                        <p className="text-sm text-green-700 dark:text-green-400 mb-3">
                            Copie esta chave agora. Você não poderá vê-la novamente.
                        </p>
                        <div className="flex items-center gap-2">
                            <code className="bg-white dark:bg-slate-950 p-2 rounded border flex-1 font-mono text-sm break-all">
                                {newKey}
                            </code>
                            <Button size="icon" variant="outline" onClick={() => {
                                navigator.clipboard.writeText(newKey);
                                toast.success("Copiado!");
                            }}>
                                <Copy className="h-4 w-4" />
                            </Button>
                        </div>
                    </div>
                )}

                <Table>
                    <TableHeader>
                        <TableRow>
                            <TableHead>Nome</TableHead>
                            <TableHead>Prefixo</TableHead>
                            <TableHead>Criado em</TableHead>
                            <TableHead>Último uso</TableHead>
                            <TableHead className="text-right">Ações</TableHead>
                        </TableRow>
                    </TableHeader>
                    <TableBody>
                        {keys.map(key => (
                            <TableRow key={key.id}>
                                <TableCell className="font-medium">{key.nome}</TableCell>
                                <TableCell className="font-mono text-xs">{key.prefixo}</TableCell>
                                <TableCell>{new Date(key.created_at).toLocaleDateString()}</TableCell>
                                <TableCell>
                                    {key.last_used_at ? new Date(key.last_used_at).toLocaleString() : '-'}
                                </TableCell>
                                <TableCell className="text-right">
                                    <Button variant="ghost" size="icon" className="text-destructive" onClick={() => handleRevoke(key.id)}>
                                        <Trash2 className="h-4 w-4" />
                                    </Button>
                                </TableCell>
                            </TableRow>
                        ))}
                        {keys.length === 0 && !loading && (
                            <TableRow>
                                <TableCell colSpan={5} className="text-center text-muted-foreground py-8">
                                    Nenhuma chave de API ativa.
                                </TableCell>
                            </TableRow>
                        )}
                    </TableBody>
                </Table>
            </CardContent>
        </Card>
    );
}

function WebhooksManager({ tenantId }: { tenantId: string }) {
    const [webhooks, setWebhooks] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        if (tenantId) loadWebhooks();
    }, [tenantId]);

    const loadWebhooks = async () => {
        setLoading(true);
        const { data } = await supabase
            .from('webhook_subscriptions')
            .select('*')
            .eq('tenant_id', tenantId)
            .order('created_at', { ascending: false });
        setWebhooks(data || []);
        setLoading(false);
    };

    const handleCreateWebhook = async (url: string, events: string[]) => {
        try {
            // Gerar segredo aleatório
            const secret = Array.from(crypto.getRandomValues(new Uint8Array(32)))
                .map(b => b.toString(16).padStart(2, '0')).join('');

            const { data: webhookData, error } = await supabase.from('webhook_subscriptions').insert({
                tenant_id: tenantId,
                url,
                event_types: events,
                segredo: secret
            }).select().single();

            if (error) throw error;

            // Log de auditoria
            await supabase.from('system_logs').insert({
                tenant_id: tenantId,
                event_type: 'webhook_created',
                details: { webhook_id: webhookData.id, url, events }
            });

            loadWebhooks();
            toast.success("Webhook criado com sucesso!");
        } catch (error) {
            toast.error("Erro ao criar webhook.");
        }
    };

    const handleDelete = async (id: string) => {
        await supabase.from('webhook_subscriptions').delete().eq('id', id);
        loadWebhooks();
        toast.success("Webhook removido.");
    };

    return (
        <Card>
            <CardHeader className="flex flex-row items-center justify-between">
                <div>
                    <CardTitle>Webhooks</CardTitle>
                    <CardDescription>Receba notificações em tempo real sobre eventos do sistema.</CardDescription>
                </div>
                <NewWebhookDialog onCreate={handleCreateWebhook} />
            </CardHeader>
            <CardContent>
                <Table>
                    <TableHeader>
                        <TableRow>
                            <TableHead>URL</TableHead>
                            <TableHead>Eventos</TableHead>
                            <TableHead>Status</TableHead>
                            <TableHead>Segredo</TableHead>
                            <TableHead className="text-right">Ações</TableHead>
                        </TableRow>
                    </TableHeader>
                    <TableBody>
                        {webhooks.map(wh => (
                            <TableRow key={wh.id}>
                                <TableCell className="font-mono text-xs max-w-[200px] truncate" title={wh.url}>
                                    {wh.url}
                                </TableCell>
                                <TableCell>
                                    <div className="flex flex-wrap gap-1">
                                        {wh.event_types.map((ev: string) => (
                                            <Badge key={ev} variant="secondary" className="text-[10px]">{ev}</Badge>
                                        ))}
                                    </div>
                                </TableCell>
                                <TableCell>
                                    <Badge variant={wh.ativo ? "default" : "secondary"}>
                                        {wh.ativo ? "Ativo" : "Inativo"}
                                    </Badge>
                                </TableCell>
                                <TableCell>
                                    <div className="flex items-center gap-2">
                                        <code className="text-xs bg-muted p-1 rounded">
                                            {wh.segredo.slice(0, 8)}...
                                        </code>
                                        <Button size="icon" variant="ghost" className="h-6 w-6" onClick={() => {
                                            navigator.clipboard.writeText(wh.segredo);
                                            toast.success("Segredo copiado!");
                                        }}>
                                            <Copy className="h-3 w-3" />
                                        </Button>
                                    </div>
                                </TableCell>
                                <TableCell className="text-right">
                                    <Button variant="ghost" size="icon" className="text-destructive" onClick={() => handleDelete(wh.id)}>
                                        <Trash2 className="h-4 w-4" />
                                    </Button>
                                </TableCell>
                            </TableRow>
                        ))}
                        {webhooks.length === 0 && !loading && (
                            <TableRow>
                                <TableCell colSpan={5} className="text-center text-muted-foreground py-8">
                                    Nenhum webhook configurado.
                                </TableCell>
                            </TableRow>
                        )}
                    </TableBody>
                </Table>
            </CardContent>
        </Card>
    );
}

