function NewWebhookDialog({ onCreate }: { onCreate: (url: string, events: string[]) => void }) {
    const [open, setOpen] = useState(false);
    const [url, setUrl] = useState('');
    const [selectedEvents, setSelectedEvents] = useState<string[]>([]);

    const availableEvents = [
        'appointment.created',
        'appointment.updated',
        'appointment.no_show',
        'invoice.paid'
    ];

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (selectedEvents.length === 0) {
            toast.error("Selecione pelo menos um evento");
            return;
        }
        onCreate(url, selectedEvents);
        setOpen(false);
        setUrl('');
        setSelectedEvents([]);
    };

    const toggleEvent = (ev: string) => {
        if (selectedEvents.includes(ev)) {
            setSelectedEvents(selectedEvents.filter(e => e !== ev));
        } else {
            setSelectedEvents([...selectedEvents, ev]);
        }
    };

    return (
        <Dialog open={open} onOpenChange={setOpen}>
            <DialogTrigger asChild>
                <Button><Plus className="mr-2 h-4 w-4" /> Novo Webhook</Button>
            </DialogTrigger>
            <DialogContent>
                <DialogHeader>
                    <DialogTitle>Adicionar Webhook</DialogTitle>
                </DialogHeader>
                <form onSubmit={handleSubmit} className="space-y-4">
                    <div>
                        <Label>URL de Destino</Label>
                        <Input value={url} onChange={e => setUrl(e.target.value)} placeholder="https://api.seusistema.com/webhook" required type="url" />
                    </div>
                    <div>
                        <Label className="mb-2 block">Eventos</Label>
                        <div className="space-y-2">
                            {availableEvents.map(ev => (
                                <div key={ev} className="flex items-center space-x-2">
                                    <Switch
                                        id={ev}
                                        checked={selectedEvents.includes(ev)}
                                        onCheckedChange={() => toggleEvent(ev)}
                                    />
                                    <Label htmlFor={ev} className="font-normal cursor-pointer">{ev}</Label>
                                </div>
                            ))}
                        </div>
                    </div>
                    <Button type="submit" className="w-full">Salvar Webhook</Button>
                </form>
            </DialogContent>
        </Dialog>
    );
}

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
