  useEffect(() => {
    checkExistingAuth();

    // Listen for auth state changes (OAuth callback)
    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
      if (event === 'SIGNED_IN' && session?.user) {
        await checkSupportUserAndRedirect(session.user.id);
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  const checkSupportUserAndRedirect = async (userId: string) => {
    try {
      const { data: supportUser, error } = await (supabase
        .from("system_users" as any)
        .select("*")
        .eq("id", userId)
        .maybeSingle() as any);

      if (error) {
        console.error("Error fetching support user:", error);
        return;
      }

      if (!supportUser) {
        // If user doesn't have support permissions, sign them out
        await supabase.auth.signOut();
        toast.error("Acesso negado: você não tem permissões de suporte");
        return;
      }

      if (!supportUser.active) {
        await logAuthEvent(supportUser.id, "login_falha", "Conta de suporte inativa");
        await supabase.auth.signOut();
        toast.error("Acesso negado: sua conta está inativa");
        return;
      }

      // Log successful login
      await logAuthEvent(supportUser.id, "login_sucesso", "Login OAuth realizado com sucesso");

      toast.success("Login realizado com sucesso!");
      navigate("/admin");
    } catch (error) {
      console.error("Error in checkSupportUserAndRedirect:", error);
    }
  };

  const checkExistingAuth = async () => {
    try {
      const { data: { user } } = await supabase.auth.getUser();

      if (user) {
        await checkSupportUserAndRedirect(user.id);
        return;
      }
    } catch (error) {
      console.error("Error checking auth:", error);
    } finally {
      setCheckingAuth(false);
    }
  };

  const logAuthEvent = async (
    usuarioId: string | null,
    tipoEvento: string,
    descricao: string | null = null
  ) => {
    try {
      await (supabase.rpc("log_admin_auth_event" as any, {
        p_usuario_id: usuarioId,
        p_tipo_evento: tipoEvento,
        p_descricao: descricao,
        p_ip_address: null,
        p_user_agent: navigator.userAgent,
        p_metadata: {}
      }) as any);
    } catch (error) {
      console.error("Error logging auth event:", error);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      const { data: authData, error: authError } = await supabase.auth.signInWithPassword({
        email,
        password,
      });

      if (authError) {
        await logAuthEvent(null, "login_falha", `Falha de autenticação: ${authError.message}`);
        toast.error("Erro ao fazer login: " + authError.message);
        return;
      }

      if (!authData.user) {
        await logAuthEvent(null, "login_falha", "Usuário não encontrado");
        toast.error("Erro ao fazer login");
        return;
      }

      // Check if user is a support user
      const { data: supportUser, error: supportError } = await (supabase
        .from("system_users" as any)
        .select("*")
        .eq("id", authData.user.id)
        .maybeSingle() as any);

      if (supportError) {
        console.error("Error fetching support user:", supportError);
        await supabase.auth.signOut();
        toast.error("Erro ao verificar permissões");
        return;
      }

      if (!supportUser) {
        await logAuthEvent(null, "login_falha", "Usuário não é um usuário de suporte");
        await supabase.auth.signOut();
        toast.error("Acesso negado: você não tem permissões de suporte");
        return;
      }

      if (!supportUser.active) {
        await logAuthEvent(supportUser.id, "login_falha", "Conta de suporte inativa ou suspensa");
        await supabase.auth.signOut();
        toast.error("Acesso negado: sua conta está inativa");
        return;
      }

      // Log successful login
      await logAuthEvent(supportUser.id, "login_sucesso", "Login realizado com sucesso");

      toast.success("Login realizado com sucesso!");
      navigate("/admin");
      return;


    } catch (error) {
      console.error("Error during login:", error);
      await logAuthEvent(null, "login_falha", "Erro inesperado durante login");
      toast.error("Erro ao fazer login");
    } finally {
      setLoading(false);
    }
  };

  const handleGoogleLogin = async () => {
    try {
      setLoading(true);
      const { error } = await supabase.auth.signInWithOAuth({
        provider: 'google',
        options: {
          redirectTo: `${window.location.origin}/admin`
        }
      });

      if (error) {
        toast.error("Erro ao fazer login com Google: " + error.message);
        setLoading(false);
      }
      // Don't set loading to false here, as user will be redirected
    } catch (error) {
      console.error("Error during Google login:", error);
      toast.error("Erro ao fazer login com Google");
      setLoading(false);
    }
  };

  if (checkingAuth) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background">
        <Loader2 className="h-8 w-8 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-background p-4">
      <Card className="w-full max-w-md">
        <CardHeader className="space-y-1 text-center">
          <div className="flex justify-center mb-4">
            <div className="h-12 w-12 rounded-full bg-primary/10 flex items-center justify-center">
              <Shield className="h-6 w-6 text-primary" />
            </div>
          </div>
          <CardTitle className="text-2xl font-bold">CleanFlow Admin</CardTitle>
          <CardDescription>
            Faça login para acessar o painel administrativo
          </CardDescription>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="email">E-mail</Label>
              <Input
                id="email"
                type="email"
                placeholder="seu@email.com"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
                disabled={loading}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="password">Senha</Label>
              <div className="relative">
                <Input
                  id="password"
                  type={showPassword ? "text" : "password"}
                  placeholder="••••••••"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  required
                  disabled={loading}
                  className="pr-10"
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors focus:outline-none"
                  aria-label={showPassword ? "Ocultar senha" : "Mostrar senha"}
                  disabled={loading}
                >
                  {showPassword ? (
                    <EyeOff className="h-4 w-4" />
                  ) : (
                    <Eye className="h-4 w-4" />
                  )}
                </button>
              </div>
            </div>
            <div className="flex items-center space-x-2">
              <Checkbox
                id="remember"
                checked={rememberMe}
                onCheckedChange={(checked) => setRememberMe(checked as boolean)}
                disabled={loading}
              />
              <label
                htmlFor="remember"
                className="text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70"
              >
                Lembrar de mim
              </label>
            </div>
            <Button type="submit" className="w-full" disabled={loading}>
              {loading ? (
                <>
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                  Entrando...
                </>
              ) : (
                "Entrar"
              )}
            </Button>

            <div className="relative my-4">
              <div className="absolute inset-0 flex items-center">
                <Separator className="w-full" />
              </div>
              <div className="relative flex justify-center text-xs uppercase">
                <span className="bg-background px-2 text-muted-foreground">
                  Ou continue com
                </span>
              </div>
            </div>

            <Button
              type="button"
              variant="outline"
              className="w-full"
              onClick={handleGoogleLogin}
              disabled={loading}
            >
              <svg className="mr-2 h-4 w-4" viewBox="0 0 24 24">
                <path
                  fill="currentColor"
                  d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"
                />
                <path
                  fill="currentColor"
                  d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"
                />
                <path
                  fill="currentColor"
                  d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"
                />
                <path
                  fill="currentColor"
                  d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"
                />
              </svg>
              {loading ? "Entrando..." : "Entrar com Google"}
            </Button>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { useOrganizationContext } from "@/hooks/useOrganizationContext";
import { Building2, Settings, TrendingUp, Users, AlertTriangle, ShieldAlert } from "lucide-react";
import { toast } from "sonner";
import { OrgSettingsForm } from "@/components/organization/OrgSettingsForm";
import { UnitSettingsDialog } from "@/components/organization/UnitSettingsDialog";

interface Unit {
    id: string;
    organization_id: string;
    nome: string;
    created_at: string;
}

interface UnitAnalytics {
    unit_id: string;
    unit_name: string;
    taxa_ocupacao_mensal_estimada: number;
    taxa_no_show: number;
    total_agendamentos: number;
}

export default function OrgGovernance() {
    const { profile } = useAuth();
    const { isOrgAdmin, hasRole, isMaster } = useOrganizationContext();
    const [units, setUnits] = useState<Unit[]>([]);
    const [analytics, setAnalytics] = useState<UnitAnalytics[]>([]);
    const [loading, setLoading] = useState(true);
    const [selectedUnitId, setSelectedUnitId] = useState<string | null>(null);
    const [unitSettingsOpen, setUnitSettingsOpen] = useState(false);

    const canAccess = isOrgAdmin || hasRole(['org_finance']) || isMaster;

    useEffect(() => {
        if (profile?.organization_id && canAccess) {
            loadData();
        }
    }, [profile?.organization_id, canAccess]);

    const loadData = async () => {
        setLoading(true);
        try {
            // Carregar unidades
            const { data: unitsData } = await (supabase as any)
                .from('units')
                .select('*')
                .eq('organization_id', profile?.organization_id);
            setUnits((unitsData as any) || []);

            // Carregar analytics consolidados
            const { data: analyticsData } = await (supabase as any)
                .from('view_org_analytics')
                .select('*')
                .eq('organization_id', profile?.organization_id);
            setAnalytics((analyticsData as any) || []);

        } catch (error) {
            console.error(error);
            toast.error("Erro ao carregar dados da organização.");
        } finally {
            setLoading(false);
        }
    };

    const handleConfigureUnit = (unitId: string) => {
        setSelectedUnitId(unitId);
        setUnitSettingsOpen(true);
    };

    if (!canAccess) {
        return (
            <div className="container mx-auto p-6 flex flex-col items-center justify-center h-[50vh] space-y-4">
                <ShieldAlert className="h-16 w-16 text-destructive" />
                <h1 className="text-2xl font-bold">Acesso Negado</h1>
                <p className="text-muted-foreground">Você não tem permissão para acessar esta página.</p>
            </div>
        );
    }

    return (
        <div className="container mx-auto p-6 space-y-8">
            <div>
                <h1 className="text-3xl font-bold tracking-tight">Governança da Organização</h1>
                <p className="text-muted-foreground">Gerencie suas unidades e visualize o desempenho consolidado.</p>
            </div>

            {/* KPIs Consolidados */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                <KPICard
                    title="Total de Unidades"
                    value={units.length.toString()}
                    icon={Building2}
                />
                <KPICard
                    title="Ocupação Média"
                    value={`${(analytics.reduce((acc, curr) => acc + Number(curr.taxa_ocupacao_mensal_estimada || 0), 0) / (analytics.length || 1)).toFixed(1)}%`}
                    icon={TrendingUp}
                />
                <KPICard
                    title="Taxa de No-Show Global"
                    value={`${(analytics.reduce((acc, curr) => acc + Number(curr.taxa_no_show || 0), 0) / (analytics.length || 1)).toFixed(1)}%`}
                    icon={AlertTriangle}
                    trend="down"
                />
                <KPICard
                    title="Total de Agendamentos"
                    value={analytics.reduce((acc, curr) => acc + Number(curr.total_agendamentos || 0), 0).toString()}
                    icon={Users}
                />
            </div>

            <Tabs defaultValue="units" className="space-y-4">
                <TabsList>
                    <TabsTrigger value="units">Unidades</TabsTrigger>
                    <TabsTrigger value="settings">Configurações Globais</TabsTrigger>
                </TabsList>

                <TabsContent value="units">
                    <Card>
                        <CardHeader>
                            <CardTitle>Desempenho por Unidade</CardTitle>
                            <CardDescription>Visão detalhada de cada unidade da rede.</CardDescription>
                        </CardHeader>
                        <CardContent>
                            <Table>
                                <TableHeader>
                                    <TableRow>
                                        <TableHead>Unidade</TableHead>
                                        <TableHead>Ocupação</TableHead>
                                        <TableHead>No-Show</TableHead>
                                        <TableHead>Agendamentos</TableHead>
                                        <TableHead className="text-right">Ações</TableHead>
                                    </TableRow>
                                </TableHeader>
                                <TableBody>
                                    {analytics.map(unit => (
                                        <TableRow key={unit.unit_id}>
                                            <TableCell className="font-medium">{unit.unit_name}</TableCell>
                                            <TableCell>
                                                <Badge variant={Number(unit.taxa_ocupacao_mensal_estimada) > 70 ? "default" : "secondary"}>
                                                    {unit.taxa_ocupacao_mensal_estimada}%
                                                </Badge>
                                            </TableCell>
                                            <TableCell>{unit.taxa_no_show}%</TableCell>
                                            <TableCell>{unit.total_agendamentos}</TableCell>
                                            <TableCell className="text-right">
                                                <Button
                                                    variant="outline"
                                                    size="sm"
                                                    onClick={() => handleConfigureUnit(unit.unit_id)}
                                                >
                                                    <Settings className="mr-2 h-4 w-4" /> Configurar
                                                </Button>
                                            </TableCell>
                                        </TableRow>
                                    ))}
                                    {analytics.length === 0 && !loading && (
                                        <TableRow>
                                            <TableCell colSpan={5} className="text-center text-muted-foreground py-8">
                                                Nenhuma unidade encontrada ou sem dados recentes.
                                            </TableCell>
                                        </TableRow>
                                    )}
                                </TableBody>
                            </Table>
                        </CardContent>
                    </Card>
                </TabsContent>

                <TabsContent value="settings">
                    {profile?.organization_id && (
                        <OrgSettingsForm organizationId={profile.organization_id} />
                    )}
                </TabsContent>
            </Tabs>

            <UnitSettingsDialog
                open={unitSettingsOpen}
                onOpenChange={setUnitSettingsOpen}
                unitId={selectedUnitId}
                organizationId={profile?.organization_id || ''}
            />
        </div>
    );
}

interface KPICardProps {
    title: string;
    value: string;
    icon: React.ComponentType<{ className?: string }>;
    trend?: 'up' | 'down';
}

function KPICard({ title, value, icon: Icon, trend }: KPICardProps) {
    return (
        <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                <CardTitle className="text-sm font-medium">{title}</CardTitle>
                <Icon className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
                <div className="text-2xl font-bold">{value}</div>
            </CardContent>
        </Card>
    );
}

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription, CardFooter } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger, DialogFooter } from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { toast } from "sonner";
import { Puzzle, Settings, Play } from "lucide-react";
import { AdminLayout } from "@/components/layout/AdminLayout";

// Lista de plugins disponíveis (mockada do frontend, deve bater com o backend)
const SYSTEM_PLUGINS = [
    {
        key: 'email-contador',
        name: 'Notificar Contador',
        description: 'Envia e-mail automático quando faturas são pagas.',
        hooks: ['onInvoicePaid'],
        defaultConfig: { email_contador: 'contador@exemplo.com' }
    },
    {
        key: 'webhook-erp',
        name: 'Integração ERP',
        description: 'Envia dados de novos agendamentos para endpoint externo.',
        hooks: ['onAppointmentCreated'],
        defaultConfig: { erp_url: 'https://api.erp.com/v1/events', api_key: '' }
    }
];

export default function PluginsManager() {
    const { profile } = useAuth();
    const [activePlugins, setActivePlugins] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        if (profile?.tenant_id) loadPlugins();
    }, [profile?.tenant_id]);

    const loadPlugins = async () => {
        setLoading(true);
        const { data } = await supabase
            .from('plugins_registry')
            .select('*')
            .eq('tenant_id', profile?.tenant_id);
        setActivePlugins(data || []);
        setLoading(false);
    };

    const handleTogglePlugin = async (pluginKey: string, enabled: boolean) => {
        const existing = activePlugins.find(p => p.nome === pluginKey);

        if (enabled) {
            if (!existing) {
                // Ativar novo (criar registro)
                const sysPlugin = SYSTEM_PLUGINS.find(p => p.key === pluginKey);
                if (!sysPlugin) return;

                const { error } = await supabase.from('plugins_registry').insert({
                    tenant_id: profile?.tenant_id,
                    nome: pluginKey,
                    hooks: sysPlugin.hooks,
                    config_json: sysPlugin.defaultConfig,
                    ativo: true
                });
                if (error) toast.error("Erro ao ativar plugin");
                else toast.success("Plugin ativado");
            } else {
                // Reativar
                await supabase.from('plugins_registry').update({ ativo: true }).eq('id', existing.id);
                toast.success("Plugin ativado");
            }
        } else {
            if (existing) {
                // Desativar
                await supabase.from('plugins_registry').update({ ativo: false }).eq('id', existing.id);
                toast.success("Plugin desativado");
            }
        }
        loadPlugins();
    };

    const handleSaveConfig = async (id: string, config: string) => {
        try {
            const json = JSON.parse(config);
            const { error } = await supabase
                .from('plugins_registry')
                .update({ config_json: json })
                .eq('id', id);

            if (error) throw error;
            toast.success("Configuração salva!");
            loadPlugins();
        } catch (e) {
            toast.error("JSON inválido");
        }
    };

    return (
        <AdminLayout>
            <div className="container mx-auto p-6 space-y-8">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight">Loja de Plugins</h1>
                    <p className="text-muted-foreground">Estenda as funcionalidades do sistema com integrações prontas.</p>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {SYSTEM_PLUGINS.map(plugin => {
                        const active = activePlugins.find(p => p.nome === plugin.key);
                        const isEnabled = active?.ativo || false;

                        return (
                            <Card key={plugin.key} className={isEnabled ? "border-primary/50 bg-primary/5" : ""}>
                                <CardHeader>
                                    <div className="flex justify-between items-start">
                                        <div className="p-2 bg-muted rounded-full">
                                            <Puzzle className="h-6 w-6 text-primary" />
                                        </div>
                                        <Switch
                                            checked={isEnabled}
                                            onCheckedChange={(checked) => handleTogglePlugin(plugin.key, checked)}
                                        />
                                    </div>
                                    <CardTitle className="mt-4">{plugin.name}</CardTitle>
                                    <CardDescription>{plugin.description}</CardDescription>
                                </CardHeader>
                                <CardContent>
                                    <div className="flex flex-wrap gap-2 mb-4">
                                        {plugin.hooks.map(hook => (
                                            <Badge key={hook} variant="secondary" className="text-[10px]">{hook}</Badge>
                                        ))}
                                    </div>
                                </CardContent>
                                <CardFooter>
                                    {isEnabled && active && (
                                        <ConfigDialog
                                            pluginName={plugin.name}
                                            initialConfig={JSON.stringify(active.config_json, null, 2)}
                                            onSave={(cfg) => handleSaveConfig(active.id, cfg)}
                                        />
                                    )}
                                </CardFooter>
                            </Card>
                        );
                    })}
                </div>
            </div>
        </AdminLayout>
    );
}

function ConfigDialog({ pluginName, initialConfig, onSave }: { pluginName: string, initialConfig: string, onSave: (c: string) => void }) {
    const [config, setConfig] = useState(initialConfig);
    const [open, setOpen] = useState(false);

    return (
        <Dialog open={open} onOpenChange={setOpen}>
            <DialogTrigger asChild>
                <Button variant="outline" className="w-full">
                    <Settings className="mr-2 h-4 w-4" /> Configurar
                </Button>
            </DialogTrigger>
            <DialogContent>
                <DialogHeader>
                    <DialogTitle>Configurar {pluginName}</DialogTitle>
                </DialogHeader>
                <div className="space-y-4">
                    <Label>Configuração (JSON)</Label>
                    <Textarea
                        value={config}
                        onChange={e => setConfig(e.target.value)}
                        className="font-mono h-[200px]"
                    />
                </div>
                <DialogFooter>
                    <Button onClick={() => { onSave(config); setOpen(false); }}>Salvar Alterações</Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

import React, { useState } from "react";
import { MainLayout } from "@/components/layout/MainLayout";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Upload, FileText, CheckCircle, AlertTriangle, Loader2 } from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { useAuth } from "@/hooks/useAuth";

const RecontratarProfissionalCsv = () => {
    const [file, setFile] = useState<File | null>(null);
    const [previewData, setPreviewData] = useState<any | null>(null);
    const [loading, setLoading] = useState(false);
    const [step, setStep] = useState<'upload' | 'preview' | 'finish'>('upload');
    const { toast } = useToast();
    const { user, profile } = useAuth();

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            setFile(e.target.files[0]);
            setPreviewData(null);
            setStep('upload');
        }
    };

    const handlePreview = async () => {
        if (!file) return;

        setLoading(true);
        try {
            const text = await file.text();
            const lines = text.split('\n');

            // Basic CSV validation
            if (!lines[0].includes('entity,payload_json,hash_integridade,version')) {
                throw new Error("Formato CSV inválido. Verifique se é um backup oficial do CleanFlow.");
            }

            // Find professional row
            const professionalRow = lines.find(line => line.startsWith('professional,'));
            if (!professionalRow) throw new Error("Dados do profissional não encontrados no arquivo.");

            // Parse payload (handling potential CSV escaping issues simply for preview)
            // A robust parser would use a library, but for our specific format:
            const parts = professionalRow.split(/,(?=(?:(?:[^"]*"){2})*[^"]*$)/); // Split by comma ignoring quotes
            const payloadJson = JSON.parse(parts[1].replace(/^"|"$/g, '').replace(/""/g, '"'));
            const payload = JSON.parse(payloadJson); // Double parse because of CSV stringify

            setPreviewData({
                nome: payload.professional.nome,
                cpf: payload.professional.cpf,
                email: payload.professional.email,
                total_agendamentos: payload.agenda?.length || 0,
                version: parts[3]
            });
            setStep('preview');
        } catch (error: any) {
            console.error('Erro ao ler arquivo:', error);
            toast({
                title: "Erro na leitura",
                description: error.message || "Não foi possível ler o arquivo de backup.",
                variant: "destructive"
            });
        } finally {
            setLoading(false);
        }
    };

    const handleImport = async () => {
        if (!file) return;

        setLoading(true);
        try {
            const text = await file.text();

            // Call Edge Function for secure import
            const { data, error } = await supabase.functions.invoke('backup-professional', {
                body: {
                    action: 'import_backup',
                    csv_content: text,
                    tenant_id: profile?.tenant_id,
                    user_id: user?.id
                }
            });

            if (error) throw error;

            setStep('finish');
            toast({
                title: "Sucesso",
                description: "Profissional recontratado com sucesso!"
            });

        } catch (error: any) {
            console.error('Erro na importação:', error);
            toast({
                title: "Erro na importação",
                description: "Falha ao processar o backup. Verifique a integridade do arquivo.",
                variant: "destructive"
            });
        } finally {
            setLoading(false);
        }
    };

    return (
        <MainLayout>
            <div className="max-w-3xl mx-auto space-y-6">
                <div>
                    <h1 className="text-3xl font-bold text-foreground">Recontratar Profissional</h1>
                    <p className="text-muted-foreground">
                        Restaure o cadastro e histórico de um profissional usando o backup CSV.
                    </p>
                </div>

                <Card>
                    <CardHeader>
                        <CardTitle>Importar Backup CSV</CardTitle>
                        <CardDescription>
                            Selecione o arquivo gerado durante a exclusão do profissional.
                        </CardDescription>
                    </CardHeader>
                    <CardContent className="space-y-6">

                        {step === 'upload' && (
                            <div className="space-y-4">
                                <div className="grid w-full max-w-sm items-center gap-1.5">
                                    <Label htmlFor="csv-file">Arquivo de Backup (.csv)</Label>
                                    <Input id="csv-file" type="file" accept=".csv" onChange={handleFileChange} />
                                </div>
                                <Button onClick={handlePreview} disabled={!file || loading}>
                                    {loading ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <FileText className="mr-2 h-4 w-4" />}
                                    Validar e Pré-visualizar
                                </Button>
                            </div>
                        )}

                        {step === 'preview' && previewData && (
                            <div className="space-y-4">
                                <Alert className="bg-blue-50 border-blue-200">
                                    <CheckCircle className="h-4 w-4 text-blue-600" />
                                    <AlertTitle className="text-blue-800">Arquivo Válido</AlertTitle>
                                    <AlertDescription className="text-blue-700">
                                        Backup versão {previewData.version} validado com sucesso.
                                    </AlertDescription>
                                </Alert>

                                <div className="grid grid-cols-2 gap-4 p-4 border rounded-md">
                                    <div>
                                        <Label className="text-muted-foreground">Nome</Label>
                                        <p className="font-medium">{previewData.nome}</p>
                                    </div>
                                    <div>
                                        <Label className="text-muted-foreground">CPF</Label>
                                        <p className="font-medium">{previewData.cpf || '-'}</p>
                                    </div>
                                    <div>
                                        <Label className="text-muted-foreground">Email</Label>
                                        <p className="font-medium">{previewData.email || '-'}</p>
                                    </div>
                                    <div>
                                        <Label className="text-muted-foreground">Registros Históricos</Label>
                                        <p className="font-medium">{previewData.total_agendamentos} agendamentos</p>
                                    </div>
                                </div>

                                <div className="flex gap-3">
                                    <Button variant="outline" onClick={() => setStep('upload')}>Voltar</Button>
                                    <Button onClick={handleImport} disabled={loading}>
                                        {loading ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <Upload className="mr-2 h-4 w-4" />}
                                        Confirmar Recontratação
                                    </Button>
                                </div>
                            </div>
                        )}

                        {step === 'finish' && (
                            <div className="text-center py-8 space-y-4">
                                <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-green-100 mb-4">
                                    <CheckCircle className="h-8 w-8 text-green-600" />
                                </div>
                                <h3 className="text-xl font-semibold">Profissional Recontratado!</h3>
                                <p className="text-muted-foreground">
                                    O cadastro foi restaurado e o profissional já está ativo novamente no sistema.
                                </p>
                                <Button onClick={() => window.location.href = '/profissionais'}>
                                    Voltar para Lista de Profissionais
                                </Button>
                            </div>
                        )}

                    </CardContent>
                </Card>
            </div>
        </MainLayout>
    );
};

export default RecontratarProfissionalCsv;

import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { supabase } from "@/integrations/supabase/client";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { BarChart, Bar, LineChart, Line, PieChart, Pie, Cell, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from "recharts";
import { ArrowLeft, Download, TrendingUp, Clock, CheckCircle, AlertCircle } from "lucide-react";
import { toast } from "sonner";
import { AdminLayout } from "@/components/layout/AdminLayout";

const COLORS = ['#016CA5', '#25D366', '#FFB800', '#FF6B6B'];

interface ReportData {
  ticketsByStatus: any[];
  ticketsByPriority: any[];
  ticketsByOrigin: any[];
  ticketsTrend: any[];
  slaMetrics: {
    cumprido: number;
    emRisco: number;
    estourado: number;
    total: number;
  };
  resolutionTime: {
    avg: number;
    min: number;
    max: number;
  };
  teamPerformance: any[];
}

const AdminReports = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const [period, setPeriod] = useState("30");
  const [reportData, setReportData] = useState<ReportData | null>(null);

  useEffect(() => {
    loadReportData();
  }, [period]);

  const loadReportData = async () => {
    setLoading(true);
    try {
      const daysAgo = new Date();
      daysAgo.setDate(daysAgo.getDate() - parseInt(period));

      // Buscar tickets do período
      const { data: tickets, error } = await supabase
        .from("support_tickets")
        .select("*")
        .gte("created_at", daysAgo.toISOString());

      if (error) throw error;

      // Processar dados para os gráficos
      const ticketsByStatus = processTicketsByStatus(tickets || []);
      const ticketsByPriority = processTicketsByPriority(tickets || []);
      const ticketsByOrigin = processTicketsByOrigin(tickets || []);
      const ticketsTrend = processTicketsTrend(tickets || [], parseInt(period));
      const slaMetrics = processSLAMetrics(tickets || []);
      const resolutionTime = processResolutionTime(tickets || []);
      const teamPerformance = await processTeamPerformance(tickets || []);

      setReportData({
        ticketsByStatus,
        ticketsByPriority,
        ticketsByOrigin,
        ticketsTrend,
        slaMetrics,
        resolutionTime,
        teamPerformance
      });
    } catch (error) {
      console.error("Error loading report data:", error);
      toast.error("Erro ao carregar relatórios");
    } finally {
      setLoading(false);
    }
  };

  const processTicketsByStatus = (tickets: any[]) => {
    const statusCount: Record<string, number> = {};
    tickets.forEach(ticket => {
      statusCount[ticket.status] = (statusCount[ticket.status] || 0) + 1;
    });

    return Object.entries(statusCount).map(([status, count]) => ({
      name: translateStatus(status),
      value: count,
      status
    }));
  };

  const processTicketsByPriority = (tickets: any[]) => {
    const priorityCount: Record<string, number> = {};
    tickets.forEach(ticket => {
      priorityCount[ticket.priority] = (priorityCount[ticket.priority] || 0) + 1;
    });

    return Object.entries(priorityCount).map(([priority, count]) => ({
      name: translatePriority(priority),
      value: count
    }));
  };

  const processTicketsByOrigin = (tickets: any[]) => {
    const originCount: Record<string, number> = {};
    tickets.forEach(ticket => {
      const origin = ticket.origem || 'manual';
      originCount[origin] = (originCount[origin] || 0) + 1;
    });

    return Object.entries(originCount).map(([origin, count]) => ({
      name: translateOrigin(origin),
      value: count
    }));
  };

  const processTicketsTrend = (tickets: any[], days: number) => {
    const trend: Record<string, number> = {};

    for (let i = days - 1; i >= 0; i--) {
      const date = new Date();
      date.setDate(date.getDate() - i);
      const dateStr = date.toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' });
      trend[dateStr] = 0;
    }

    tickets.forEach(ticket => {
      const date = new Date(ticket.created_at);
      const dateStr = date.toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' });
      if (trend[dateStr] !== undefined) {
        trend[dateStr]++;
      }
    });

    return Object.entries(trend).map(([date, count]) => ({
      date,
      tickets: count
    }));
  };

  const processSLAMetrics = (tickets: any[]) => {
    let cumprido = 0;
    let emRisco = 0;
    let estourado = 0;

    tickets.forEach(ticket => {
      if (!ticket.sla || !ticket.sla.limite) return;

      const now = new Date();
      const limite = new Date(ticket.sla.limite);
      const tempoRestante = limite.getTime() - now.getTime();

      if (ticket.status === 'resolved' || ticket.status === 'closed') {
        if (ticket.sla.atingido === false) {
          cumprido++;
        } else {
          estourado++;
        }
      } else if (tempoRestante <= 0) {
        estourado++;
      } else {
        const inicio = new Date(ticket.sla.inicio);
        const tempoTotal = limite.getTime() - inicio.getTime();
        const percentualGasto = ((tempoTotal - tempoRestante) / tempoTotal) * 100;

        if (percentualGasto >= 80) {
          emRisco++;
        } else {
          cumprido++;
        }
      }
    });

    return {
      cumprido,
      emRisco,
      estourado,
      total: tickets.length
    };
  };

  const processResolutionTime = (tickets: any[]) => {
    const resolvedTickets = tickets.filter(t => t.resolved_at);

    if (resolvedTickets.length === 0) {
      return { avg: 0, min: 0, max: 0 };
    }

    const times = resolvedTickets.map(ticket => {
      const created = new Date(ticket.created_at);
      const resolved = new Date(ticket.resolved_at);
      return (resolved.getTime() - created.getTime()) / (1000 * 60 * 60); // horas
    });

    return {
      avg: times.reduce((a, b) => a + b, 0) / times.length,
      min: Math.min(...times),
      max: Math.max(...times)
    };
  };

  const processTeamPerformance = async (tickets: any[]) => {
    const { data: supportUsers } = await supabase
      .from("usuarios_suporte")
      .select("id, nome, auth_user_id");

    if (!supportUsers) return [];

    const performance = supportUsers.map(user => {
      const assignedTickets = tickets.filter(t => t.assigned_to === user.auth_user_id);
      const resolvedTickets = assignedTickets.filter(t => t.status === 'resolved' || t.status === 'closed');

      return {
        name: user.nome,
        atribuidos: assignedTickets.length,
        resolvidos: resolvedTickets.length,
        taxa: assignedTickets.length > 0
          ? Math.round((resolvedTickets.length / assignedTickets.length) * 100)
          : 0
      };
    }).filter(p => p.atribuidos > 0);

    return performance;
  };

  const translateStatus = (status: string) => {
    const translations: Record<string, string> = {
      open: 'Aberto',
      in_progress: 'Em Progresso',
      waiting_customer: 'Aguardando Cliente',
      resolved: 'Resolvido',
      closed: 'Fechado'
    };
    return translations[status] || status;
  };

  const translatePriority = (priority: string) => {
    const translations: Record<string, string> = {
      urgent: 'Urgente',
      high: 'Alta',
      medium: 'Média',
      low: 'Baixa'
    };
    return translations[priority] || priority;
  };

  const translateOrigin = (origin: string) => {
    const translations: Record<string, string> = {
      chat: 'Chat',
      email: 'Email',
      whatsapp: 'WhatsApp',
      manual: 'Manual'
    };
    return translations[origin] || origin;
  };

  const exportReport = async (format: 'csv' | 'pdf') => {
    if (!reportData) return;

    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      if (format === 'csv') {
        const csvContent = generateCSV();
        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const link = document.createElement('a');
        link.href = URL.createObjectURL(blob);
        link.download = `relatorio-suporte-${new Date().toISOString().split('T')[0]}.csv`;
        link.click();
      } else {
        await generatePDF();
      }

      // Registrar exportação
      await supabase.rpc('registrar_exportacao', {
        p_user_id: user.id,
        p_export_type: 'support_report',
        p_table_name: 'support_tickets',
        p_filters: { period },
        p_record_count: reportData.ticketsByStatus.reduce((sum, item) => sum + item.value, 0),
        p_file_format: format
      });

      toast.success(`Relatório exportado como ${format.toUpperCase()} com sucesso`);
    } catch (error) {
      console.error('Erro ao exportar:', error);
      toast.error("Erro ao registrar exportação");
    }
  };

  const generatePDF = async () => {
    if (!reportData) return;
    const { jsPDF } = await import("jspdf");
    const autoTable = (await import("jspdf-autotable")).default;

    const doc = new jsPDF();

    // Título
    doc.setFontSize(18);
    doc.text("Relatório de Suporte CleanFlow", 14, 22);

    doc.setFontSize(11);
    doc.setTextColor(100);
    doc.text(`Período: Últimos ${period} dias`, 14, 30);
    doc.text(`Gerado em: ${new Date().toLocaleString('pt-BR')}`, 14, 36);

    let finalY = 45;

    // Métricas SLA
    doc.setFontSize(14);
    doc.setTextColor(0);
    doc.text("Métricas de SLA", 14, finalY);
    finalY += 6;

    autoTable(doc, {
      startY: finalY,
      head: [['Status', 'Quantidade', 'Percentual']],
      body: [
        ['Cumprido', reportData.slaMetrics.cumprido, `${((reportData.slaMetrics.cumprido / reportData.slaMetrics.total) * 100).toFixed(1)}%`],
        ['Em Risco', reportData.slaMetrics.emRisco, `${((reportData.slaMetrics.emRisco / reportData.slaMetrics.total) * 100).toFixed(1)}%`],
        ['Estourado', reportData.slaMetrics.estourado, `${((reportData.slaMetrics.estourado / reportData.slaMetrics.total) * 100).toFixed(1)}%`],
      ],
    });

    // @ts-ignore
    finalY = doc.lastAutoTable.finalY + 15;

    // Tickets por Status
    doc.text("Tickets por Status", 14, finalY);
    finalY += 6;

    autoTable(doc, {
      startY: finalY,
      head: [['Status', 'Quantidade']],
      body: reportData.ticketsByStatus.map(item => [item.name, item.value]),
    });

    // @ts-ignore
    finalY = doc.lastAutoTable.finalY + 15;

    // Performance da Equipe
    doc.text("Performance da Equipe", 14, finalY);
    finalY += 6;

    autoTable(doc, {
      startY: finalY,
      head: [['Agente', 'Atribuídos', 'Resolvidos', 'Taxa de Resolução']],
      body: reportData.teamPerformance.map(item => [
        item.name,
        item.atribuidos,
        item.resolvidos,
        `${item.taxa}%`
      ]),
    });

    doc.save(`relatorio-suporte-${new Date().toISOString().split('T')[0]}.pdf`);
  };

  const generateCSV = () => {
    if (!reportData) return '';

    let csv = 'RELATÓRIO DE SUPORTE\n\n';
    csv += `Período: Últimos ${period} dias\n`;
    csv += `Gerado em: ${new Date().toLocaleString('pt-BR')}\n\n`;

    csv += 'MÉTRICAS DE SLA\n';
    csv += 'Status,Quantidade,Percentual\n';
    csv += `Cumprido,${reportData.slaMetrics.cumprido},${((reportData.slaMetrics.cumprido / reportData.slaMetrics.total) * 100).toFixed(1)}%\n`;
    csv += `Em Risco,${reportData.slaMetrics.emRisco},${((reportData.slaMetrics.emRisco / reportData.slaMetrics.total) * 100).toFixed(1)}%\n`;
    csv += `Estourado,${reportData.slaMetrics.estourado},${((reportData.slaMetrics.estourado / reportData.slaMetrics.total) * 100).toFixed(1)}%\n\n`;

    csv += 'TICKETS POR STATUS\n';
    csv += 'Status,Quantidade\n';
    reportData.ticketsByStatus.forEach(item => {
      csv += `${item.name},${item.value}\n`;
    });

    csv += '\nPERFORMANCE DA EQUIPE\n';
    csv += 'Agente,Atribuídos,Resolvidos,Taxa de Resolução\n';
    reportData.teamPerformance.forEach(item => {
      csv += `${item.name},${item.atribuidos},${item.resolvidos},${item.taxa}%\n`;
    });

    return csv;
  };

  if (loading) {
    return <div className="flex items-center justify-center min-h-screen">Carregando...</div>;
  }

  return (
    <AdminLayout>
      <div className="space-y-6">
        <div className="flex items-center justify-between mb-8">
          <div className="flex items-center gap-4">
            <div>
              <h1 className="text-3xl font-bold">Relatórios de Suporte</h1>
              <p className="text-muted-foreground">Análises e métricas do sistema de tickets</p>
            </div>
          </div>

          <div className="flex items-center gap-4">
            <Select value={period} onValueChange={setPeriod}>
              <SelectTrigger className="w-40">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="7">Últimos 7 dias</SelectItem>
                <SelectItem value="15">Últimos 15 dias</SelectItem>
                <SelectItem value="30">Últimos 30 dias</SelectItem>
                <SelectItem value="60">Últimos 60 dias</SelectItem>
                <SelectItem value="90">Últimos 90 dias</SelectItem>
              </SelectContent>
            </Select>

            <Button onClick={() => exportReport('csv')} variant="outline">
              <Download className="h-4 w-4 mr-2" />
              CSV
            </Button>
            <Button onClick={() => exportReport('pdf')}>
              <Download className="h-4 w-4 mr-2" />
              PDF
            </Button>
          </div>
        </div>

        {reportData && (
          <>
            {/* Métricas Principais */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-8">
              <Card className="p-6">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-sm text-muted-foreground">SLA Cumprido</p>
                    <p className="text-3xl font-bold text-green-600">
                      {reportData.slaMetrics.total > 0
                        ? Math.round((reportData.slaMetrics.cumprido / reportData.slaMetrics.total) * 100)
                        : 0}%
                    </p>
                    <p className="text-xs text-muted-foreground mt-1">
                      {reportData.slaMetrics.cumprido} de {reportData.slaMetrics.total}
                    </p>
                  </div>
                  <CheckCircle className="h-8 w-8 text-green-600" />
                </div>
              </Card>

              <Card className="p-6">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-sm text-muted-foreground">SLA em Risco</p>
                    <p className="text-3xl font-bold text-yellow-600">
                      {reportData.slaMetrics.total > 0
                        ? Math.round((reportData.slaMetrics.emRisco / reportData.slaMetrics.total) * 100)
                        : 0}%
                    </p>
                    <p className="text-xs text-muted-foreground mt-1">
                      {reportData.slaMetrics.emRisco} tickets
                    </p>
                  </div>
                  <Clock className="h-8 w-8 text-yellow-600" />
                </div>
              </Card>

              <Card className="p-6">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-sm text-muted-foreground">SLA Estourado</p>
                    <p className="text-3xl font-bold text-red-600">
                      {reportData.slaMetrics.total > 0
                        ? Math.round((reportData.slaMetrics.estourado / reportData.slaMetrics.total) * 100)
                        : 0}%
                    </p>
                    <p className="text-xs text-muted-foreground mt-1">
                      {reportData.slaMetrics.estourado} tickets
                    </p>
                  </div>
                  <AlertCircle className="h-8 w-8 text-red-600" />
                </div>
              </Card>

              <Card className="p-6">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-sm text-muted-foreground">Tempo Médio</p>
                    <p className="text-3xl font-bold">
                      {reportData.resolutionTime.avg.toFixed(1)}h
                    </p>
                    <p className="text-xs text-muted-foreground mt-1">
                      Resolução de tickets
                    </p>
                  </div>
                  <TrendingUp className="h-8 w-8 text-primary" />
                </div>
              </Card>
            </div>

            <Tabs defaultValue="overview" className="space-y-4">
              <TabsList>
                <TabsTrigger value="overview">Visão Geral</TabsTrigger>
                <TabsTrigger value="team">Performance da Equipe</TabsTrigger>
                <TabsTrigger value="trends">Tendências</TabsTrigger>
              </TabsList>

              <TabsContent value="overview" className="space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <Card className="p-6">
                    <h3 className="text-lg font-semibold mb-4">Tickets por Status</h3>
                    <ResponsiveContainer width="100%" height={300}>
                      <PieChart>
                        <Pie
                          data={reportData.ticketsByStatus}
                          cx="50%"
                          cy="50%"
                          labelLine={false}
                          label={(entry) => `${entry.name}: ${entry.value}`}
                          outerRadius={80}
                          fill="#8884d8"
