export type ProviderType = 'stripe' | 'pagarme' | 'none';
export type SeatType = 'profissional' | 'secretaria' | 'unidade';
export type BillingItemType = 'plano' | 'seat_extra' | 'ajuste_prorata' | 'desconto';
