import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

export type LogLevel = 'info' | 'warn' | 'error' | 'debug';

export class EdgeLogger {
  private supabase: any;
  private requestId: string;

  constructor(requestId?: string) {
    this.supabase = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
    );
    this.requestId = requestId || crypto.randomUUID();
  }

  async log(
    level: LogLevel,
    message: string,
    service: string,
    metadata: Record<string, any> = {}
  ) {
    try {
      await this.supabase.rpc('log_system_event', {
        p_level: level,
        p_message: message,
        p_service: service,
        p_request_id: this.requestId,
        p_metadata: metadata
      });

      console.log(`[${level.toUpperCase()}] [${service}] ${message}`, metadata);
    } catch (error) {
      console.error('Failed to log event:', error);
    }
  }

  info(message: string, service: string, metadata?: Record<string, any>) {
    return this.log('info', message, service, metadata);
  }

  warn(message: string, service: string, metadata?: Record<string, any>) {
    return this.log('warn', message, service, metadata);
  }

  error(message: string, service: string, metadata?: Record<string, any>) {
    return this.log('error', message, service, metadata);
  }

  debug(message: string, service: string, metadata?: Record<string, any>) {
    return this.log('debug', message, service, metadata);
  }

  getRequestId(): string {
    return this.requestId;
  }
}

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.7.1";
import { crypto } from "https://deno.land/std@0.177.0/crypto/mod.ts";

const corsHeaders = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

serve(async (req) => {
    if (req.method === 'OPTIONS') {
        return new Response('ok', { headers: corsHeaders });
    }

    try {
        const authHeader = req.headers.get('Authorization');
        if (!authHeader?.startsWith('Bearer ')) {
            return new Response(JSON.stringify({ error: 'Missing or invalid API Key' }), {
                status: 401,
                headers: { ...corsHeaders, 'Content-Type': 'application/json' }
            });
        }

        const apiKey = authHeader.split(' ')[1];

        // Hash the incoming key to compare with stored hash
        // Assuming key format: sk_live_RANDOMSTRING
        // We store hash of the full key
        const encoder = new TextEncoder();
        const data = encoder.encode(apiKey);
        const hashBuffer = await crypto.subtle.digest('SHA-256', data);
        const hashArray = Array.from(new Uint8Array(hashBuffer));
        const hashHex = hashArray.map(b => b.toString(16).padStart(2, '0')).join('');

        // Initialize Supabase Admin Client (to bypass RLS for auth check)
        const supabaseAdmin = createClient(
            Deno.env.get('SUPABASE_URL') ?? '',
            Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
        );

        // Validate Key
        const { data: keyData, error: keyError } = await supabaseAdmin
            .from('api_keys')
            .select('tenant_id, ativo')
            .eq('chave_hash', hashHex)
            .single();

        if (keyError || !keyData || !keyData.ativo) {
            return new Response(JSON.stringify({ error: 'Invalid or inactive API Key' }), {
                status: 401,
                headers: { ...corsHeaders, 'Content-Type': 'application/json' }
            });
        }

        const tenantId = keyData.tenant_id;
        const url = new URL(req.url);
        const path = url.pathname.replace('/api-gateway', ''); // Remove function name prefix if needed

        // Update last_used_at (async, fire and forget)
        supabaseAdmin.from('api_keys').update({ last_used_at: new Date().toISOString() }).eq('chave_hash', hashHex).then();

        // Route handling
        if (req.method === 'GET' && path.endsWith('/appointments')) {
            return await handleGetAppointments(supabaseAdmin, tenantId, url.searchParams);
        }

        if (req.method === 'POST' && path.endsWith('/appointments')) {
            const body = await req.json();
            return await handleCreateAppointment(supabaseAdmin, tenantId, body);
        }

        if (req.method === 'GET' && path.endsWith('/customers')) {
            return await handleGetCustomers(supabaseAdmin, tenantId, url.searchParams);
        }

        return new Response(JSON.stringify({ error: 'Not Found' }), {
            status: 404,
            headers: { ...corsHeaders, 'Content-Type': 'application/json' }
        });

    } catch (error) {
        return new Response(JSON.stringify({ error: error.message }), {
            status: 500,
            headers: { ...corsHeaders, 'Content-Type': 'application/json' }
        });
    }
});

async function handleGetAppointments(supabase: any, tenantId: string, params: URLSearchParams) {
    const page = parseInt(params.get('page') || '1');
    const limit = Math.min(parseInt(params.get('limit') || '20'), 100);
    const offset = (page - 1) * limit;

    const { data, error, count } = await supabase
        .from('agenda')
        .select('*, pacientes(nome, telefone), profiles(nome)', { count: 'exact' })
        .eq('tenant_id', tenantId)
        .range(offset, offset + limit - 1)
        .order('inicio', { ascending: false });

    if (error) throw error;

    return new Response(JSON.stringify({ data, meta: { page, limit, total: count } }), {
        headers: { ...corsHeaders, 'Content-Type': 'application/json' }
    });
}

async function handleGetCustomers(supabase: any, tenantId: string, params: URLSearchParams) {
    const page = parseInt(params.get('page') || '1');
    const limit = Math.min(parseInt(params.get('limit') || '20'), 100);
    const offset = (page - 1) * limit;

    const { data, error, count } = await supabase
        .from('pacientes')
        .select('*', { count: 'exact' })
        .eq('tenant_id', tenantId)
        .range(offset, offset + limit - 1)
        .order('nome');

    if (error) throw error;

    return new Response(JSON.stringify({ data, meta: { page, limit, total: count } }), {
        headers: { ...corsHeaders, 'Content-Type': 'application/json' }
    });
}

async function handleCreateAppointment(supabase: any, tenantId: string, body: any) {
    // Basic validation
    if (!body.paciente_id || !body.profissional_id || !body.inicio || !body.servico_id) {
        return new Response(JSON.stringify({ error: 'Missing required fields' }), { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } });
    }

    // Ensure tenant isolation
    // Check if patient belongs to tenant
    const { data: patient } = await supabase.from('pacientes').select('id').eq('id', body.paciente_id).eq('tenant_id', tenantId).single();
    if (!patient) return new Response(JSON.stringify({ error: 'Invalid patient' }), { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } });

    const { data, error } = await supabase
        .from('agenda')
        .insert({
            ...body,
            tenant_id: tenantId,
            origem: 'api',
            status: 'agendado'
        })
        .select()
        .single();

    if (error) throw error;

    return new Response(JSON.stringify({ data }), {
        status: 201,
        headers: { ...corsHeaders, 'Content-Type': 'application/json' }
    });
}

import { SupabaseClient } from 'https://esm.sh/@supabase/supabase-js@2';

export async function applyPolicies(supabase: SupabaseClient, logger: any) {
    await logger.info('Iniciando aplicação de políticas de retenção', 'retention', {});

    // Buscar políticas ativas
    const { data: policies, error: policiesError } = await supabase
        .from('retention_policies_detailed')
        .select('*')
        .eq('active', true);

    if (policiesError) throw policiesError;

    const results = [];

    for (const policy of policies || []) {
        const cutoffDate = new Date();
        cutoffDate.setMonth(cutoffDate.getMonth() - policy.retention_months);

        let deletedCount = 0;

        try {
            switch (policy.target_table) {
                case 'log_mensagens': {
                    const { count, error: deleteError } = await supabase
                        .from('log_mensagens')
                        .delete({ count: 'exact' })
                        .lt('created_at', cutoffDate.toISOString())
                        .in('status', policy.apply_to_status || ['enviado', 'falhou']);

                    if (deleteError) throw deleteError;
                    if (count !== null) deletedCount = count;
                    break;
                }

                case 'message_audit': {
                    const { count, error: deleteError } = await supabase
                        .from('message_audit')
                        .delete({ count: 'exact' })
                        .lt('timestamp', cutoffDate.toISOString());

                    if (deleteError) throw deleteError;
                    if (count !== null) deletedCount = count;
                    break;
                }

                case 'system_logs': {
                    const { count, error: deleteError } = await supabase
                        .from('system_logs')
                        .delete({ count: 'exact' })
                        .lt('created_at', cutoffDate.toISOString())
                        .not('level', 'in', '(error,critical)');

                    if (deleteError) throw deleteError;
                    if (count !== null) deletedCount = count;
                    break;
                }

                case 'auditoria_admin': {
                    const { count, error: deleteError } = await supabase
                        .from('auditoria_admin')
                        .delete({ count: 'exact' })
                        .lt('created_at', cutoffDate.toISOString());

                    if (deleteError) throw deleteError;
                    if (count !== null) deletedCount = count;
                    break;
                }
            }

            // Atualizar última aplicação
            await supabase
                .from('retention_policies_detailed')
                .update({ last_applied_at: new Date().toISOString() })
                .eq('id', policy.id);

            results.push({
                policy: policy.policy_name,
                table: policy.target_table,
                deleted: deletedCount,
                cutoff_date: cutoffDate.toISOString()
            });

            await logger.info(
                `Política aplicada: ${policy.policy_name}`,
                'retention',
                { policy_id: policy.id, deleted: deletedCount }
            );
        } catch (error) {
            await logger.error(
                `Erro ao aplicar política ${policy.policy_name}`,
                'retention',
                { error, policy_id: policy.id }
            );

            results.push({
                policy: policy.policy_name,
                table: policy.target_table,
                error: error instanceof Error ? error.message : 'Erro desconhecido'
            });
        }
    }

    // 2. Aplicar configurações por Tenant
    const { data: tenantSettings, error: settingsError } = await supabase
        .from('tenant_retention_settings')
        .select('*');

    if (!settingsError && tenantSettings) {
        for (const setting of tenantSettings) {
            try {
                // Logs do Sistema
                if (setting.retencao_logs_dias) {
                    const cutoffLogs = new Date();
                    cutoffLogs.setDate(cutoffLogs.getDate() - setting.retencao_logs_dias);

                    const { count: countSys, error: errSys } = await supabase
                        .from('system_logs')
                        .delete({ count: 'exact' })
                        .eq('tenant_id', setting.tenant_id)
                        .lt('created_at', cutoffLogs.toISOString());

                    if (!errSys && countSys !== null) {
                        results.push({ tenant: setting.tenant_id, table: 'system_logs', deleted: countSys, type: 'tenant' });
                    }
                }

                // Mensagens
                if (setting.retencao_mensagens_dias) {
                    const cutoffMsgs = new Date();
                    cutoffMsgs.setDate(cutoffMsgs.getDate() - setting.retencao_mensagens_dias);

                    const { count: countMsgs, error: errMsgs } = await supabase
                        .from('log_mensagens')
                        .delete({ count: 'exact' })
                        .eq('tenant_id', setting.tenant_id)
                        .lt('created_at', cutoffMsgs.toISOString());

                    if (!errMsgs && countMsgs !== null) {
                        results.push({ tenant: setting.tenant_id, table: 'log_mensagens', deleted: countMsgs, type: 'tenant' });
                    }
                }

            } catch (err) {
                await logger.error(`Erro retention tenant ${setting.tenant_id}`, 'retention', { error: err });
            }
        }
    }

    return results;
}

