import { serve } from "https://deno.land/std@0.190.0/http/server.ts";
import Stripe from "https://esm.sh/stripe@18.5.0";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.57.2";
import { z } from "https://deno.land/x/zod@v3.22.4/mod.ts";
import { corsHeaders, handleCors } from "../_shared/cors.ts";
import { EdgeLogger } from "../_shared/logger.ts";

// Validation schemas
const checkoutRequestSchema = z.object({
  priceId: z.string().startsWith("price_").max(100),
  billingCycle: z.enum(["monthly", "annual"]).optional(),
  planSlug: z.string().min(1).max(50).regex(/^[a-z0-9-]+$/),
  quantity: z.number().min(1).optional().default(1)
});

const authHeaderSchema = z.string().startsWith("Bearer ").max(1000);

serve(async (req) => {
  const corsResponse = handleCors(req);
  if (corsResponse) return corsResponse;

  const logger = new EdgeLogger();
  const supabaseClient = createClient(
    Deno.env.get("SUPABASE_URL") ?? "",
    Deno.env.get("SUPABASE_ANON_KEY") ?? ""
  );

  try {
    await logger.info("Checkout session requested", "checkout");

    // Validate request body
    const body = await req.json();
    const { priceId, billingCycle, planSlug, quantity } = checkoutRequestSchema.parse(body);

    await logger.info("Request data validated", "checkout", { priceId, billingCycle, planSlug, quantity });

    // Validate authorization header
    const authHeader = req.headers.get("Authorization");
    if (!authHeader) throw new Error("No authorization header provided");
    const validatedAuthHeader = authHeaderSchema.parse(authHeader);
    const token = validatedAuthHeader.replace("Bearer ", "");
    const { data } = await supabaseClient.auth.getUser(token);
    const user = data.user;
    if (!user?.email) throw new Error("User not authenticated or email not available");
    await logger.info("User authenticated", "checkout", { userId: user.id, email: user.email });

    const stripe = new Stripe(Deno.env.get("STRIPE_SECRET_KEY") || "", {
      apiVersion: "2025-08-27.basil" as any
    });

    // Check for existing customer
    const customers = await stripe.customers.list({ email: user.email, limit: 1 });
    let customerId;
    if (customers.data.length > 0) {
      customerId = customers.data[0].id;
      await logger.info("Existing customer found", "checkout", { customerId });
    } else {
      await logger.info("No existing customer, will create on checkout", "checkout");
    }

    // Create checkout session
    const session = await stripe.checkout.sessions.create({
      customer: customerId,
      customer_email: customerId ? undefined : user.email,
      line_items: [
        {
          price: priceId,
          quantity: quantity,
        },
      ],
      mode: "subscription",
      success_url: `${req.headers.get("origin")}/dashboard?subscription=success`,
      cancel_url: `${req.headers.get("origin")}/?subscription=canceled`,
      metadata: {
        user_id: user.id,
        plan_slug: planSlug,
        billing_cycle: billingCycle || 'monthly',
      },
    });

    await logger.info("Checkout session created", "checkout", { sessionId: session.id, url: session.url });

    return new Response(JSON.stringify({ url: session.url, sessionId: session.id }), {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
      status: 200,
    });
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : String(error);
    await logger.error("Checkout error", "checkout", { message: errorMessage });
    return new Response(JSON.stringify({ error: errorMessage }), {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
      status: 500,
    });
  }
});

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import Stripe from "https://esm.sh/stripe@18.5.0";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.57.2";

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

const logStep = (step: string, details?: any) => {
  const detailsStr = details ? ` - ${JSON.stringify(details)}` : '';
  console.log(`[CRIAR-ASSINATURA-NUMERO] ${step}${detailsStr}`);
};

serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response(null, { headers: corsHeaders });
  }

  const supabase = createClient(
    Deno.env.get("SUPABASE_URL") ?? "",
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? ""
  );

  const supabaseAnon = createClient(
    Deno.env.get("SUPABASE_URL") ?? "",
    Deno.env.get("SUPABASE_ANON_KEY") ?? ""
  );

  try {
    logStep("Iniciando criação de assinatura");

    // Autenticar usuário
    const authHeader = req.headers.get("Authorization")!;
    const token = authHeader.replace("Bearer ", "");
    const { data: userData } = await supabaseAnon.auth.getUser(token);
    const user = userData.user;
    if (!user?.email) throw new Error("Usuário não autenticado");
    logStep("Usuário autenticado", { email: user.email });

    const { package_id, departamentos } = await req.json();
    logStep("Dados recebidos", { package_id, departamentos });

    // Buscar profile e tenant
    const { data: profile } = await supabase
      .from('profiles')
      .select('tenant_id, role, nome')
      .eq('id', user.id)
      .single();

    if (!profile?.tenant_id) throw new Error("Tenant não encontrado");
    if (profile.role !== 'admin') throw new Error("Apenas administradores podem contratar números");
    logStep("Profile validado", { tenant_id: profile.tenant_id });

    // Verificar se já tem assinatura ativa
    const { data: existingSubscription } = await supabase
      .from('phone_number_subscriptions')
      .select('id, status')
      .eq('tenant_id', profile.tenant_id)
      .in('status', ['active', 'pending', 'cancellation_scheduled'])
      .single();

    if (existingSubscription) {
      throw new Error("Já existe uma assinatura de número ativa. Cancele a atual antes de contratar outra.");
    }

    // Buscar pacote
    const { data: pkg } = await supabase
      .from('phone_number_packages')
      .select('*')
      .eq('id', package_id)
      .eq('ativo', true)
      .single();

    if (!pkg) throw new Error("Pacote não encontrado");
    logStep("Pacote encontrado", { nome: pkg.nome, preco: pkg.preco_mensal });

    // Buscar tenant para dados de faturamento
    const { data: tenant } = await supabase
      .from('tenants')
      .select('nome, email, cnpj')
      .eq('id', profile.tenant_id)
      .single();

    // Verificar plano do tenant (se necessário)
    const { data: subscription } = await supabase
      .from('subscriptions')
      .select('*, plan:plans(slug)')
      .eq('tenant_id', profile.tenant_id)
      .eq('status', 'active')
      .maybeSingle();

    const planSlug = (subscription?.plan as any)?.slug || 'free';
    if (pkg.planos_permitidos && pkg.planos_permitidos.length > 0 && !pkg.planos_permitidos.includes(planSlug)) {
      throw new Error(`Este pacote requer plano ${pkg.planos_permitidos.join(' ou ')}`);
    }

    // Criar checkout Stripe
    const stripe = new Stripe(Deno.env.get("STRIPE_SECRET_KEY") || "", {
      apiVersion: "2025-08-27.basil" as any,
    });

    // Buscar ou criar customer
    const customers = await stripe.customers.list({ email: user.email, limit: 1 });
    let customerId = customers.data[0]?.id;

    if (!customerId) {
      const customer = await stripe.customers.create({
        email: user.email,
        name: tenant?.nome || profile.nome,
        metadata: {
          tenant_id: profile.tenant_id,
          cnpj: tenant?.cnpj || ''
        }
      });
      customerId = customer.id;
      logStep("Cliente Stripe criado", { customerId });
    }

    // Criar price se não existir
    let priceId = pkg.stripe_price_id;
    if (!priceId) {
      const product = await stripe.products.create({
        name: `CleanFlow - ${pkg.nome}`,
        description: pkg.descricao || `${pkg.quantidade_numeros} número(s) WhatsApp exclusivo(s)`,
        metadata: { package_id: pkg.id }
      });

      const price = await stripe.prices.create({
        product: product.id,
        unit_amount: Math.round(pkg.preco_mensal * 100),
        currency: (pkg.moeda || 'BRL').toLowerCase(),
        recurring: { interval: 'month' },
      });

      priceId = price.id;
      logStep("Price Stripe criado", { priceId });

      // Atualizar pacote com price_id
      await supabase
        .from('phone_number_packages')
        .update({ stripe_price_id: priceId })
        .eq('id', package_id);
    }

    // Criar registro de assinatura pendente
    const { data: newSubscription, error: subError } = await supabase
      .from('phone_number_subscriptions')
      .insert({
        tenant_id: profile.tenant_id,
        package_id: package_id,
        stripe_customer_id: customerId,
        status: 'pending',
        valor_mensal: pkg.preco_mensal,
        valor_custo: pkg.custo_provedor,
