import { serve } from "https://deno.land/std@0.190.0/http/server.ts";
import Stripe from "https://esm.sh/stripe@18.5.0";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { EdgeLogger } from "../_shared/logger.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  const logger = new EdgeLogger();
  const supabaseClient = createClient(
    Deno.env.get("SUPABASE_URL") ?? "",
    Deno.env.get("SUPABASE_ANON_KEY") ?? ""
  );

  try {
    const authHeader = req.headers.get("Authorization")!;
    const token = authHeader.replace("Bearer ", "");
    const { data } = await supabaseClient.auth.getUser(token);
    const user = data.user;
    if (!user?.email) throw new Error("Usuário não autenticado");

    const { agendamento_id, valor } = await req.json();

    logger.info('Criando sinal de consulta', 'payment', { agendamento_id, valor });

    // Buscar agendamento
    const { data: agendamento, error: agendError } = await supabaseClient
      .from('agenda')
      .select('*, pacientes(*)')
      .eq('id', agendamento_id)
      .single();

    if (agendError || !agendamento) throw new Error('Agendamento não encontrado');

    // Initialize Stripe
    const stripe = new Stripe(Deno.env.get("STRIPE_SECRET_KEY") || "", {
      apiVersion: "2025-08-27.basil",
    });

    // Check for existing customer
    const customers = await stripe.customers.list({ 
      email: (agendamento.pacientes as any)?.email || user.email, 
      limit: 1 
    });

    let customerId;
    if (customers.data.length > 0) {
      customerId = customers.data[0].id;
    }

    // Criar sessão de pagamento
    const session = await stripe.checkout.sessions.create({
      customer: customerId,
      customer_email: customerId ? undefined : ((agendamento.pacientes as any)?.email || user.email),
      line_items: [
        {
          price_data: {
            currency: 'brl',
            product_data: {
              name: `Sinal - Consulta ${new Date(agendamento.inicio).toLocaleString('pt-BR')}`,
              description: `Sinal para garantir sua consulta`,
            },
            unit_amount: Math.round(valor * 100), // Converter para centavos
          },
          quantity: 1,
        },
      ],
      mode: "payment",
      success_url: `${req.headers.get("origin")}/agenda?sinal_pago=true`,
      cancel_url: `${req.headers.get("origin")}/agenda?sinal_cancelado=true`,
      metadata: {
        agendamento_id,
        tenant_id: agendamento.tenant_id,
        tipo: 'sinal_consulta'
      }
    });

    // Salvar registro do sinal
    const { data: sinal, error: sinalError } = await supabaseClient
      .from('sinais_consulta' as any)
      .insert({
        tenant_id: agendamento.tenant_id,
        agendamento_id,
        paciente_id: agendamento.paciente_id,
        valor,
        metodo: 'cartao',
        status: 'pendente',
        stripe_checkout_session_id: session.id,
        link_pagamento: session.url,
        expira_em: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString()
      })
      .select()
      .single();

    if (sinalError) throw sinalError;

    logger.info('Sinal criado', 'payment', { sinal_id: sinal.id, session_id: session.id });

    return new Response(JSON.stringify({ url: session.url, sinal_id: sinal.id }), {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
      status: 200,
    });

  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : String(error);
    logger.error('Erro ao criar sinal', 'payment', { error: errorMessage });
    return new Response(JSON.stringify({ error: errorMessage }), {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
      status: 500,
    });
  }
});

import { serve } from "https://deno.land/std@0.190.0/http/server.ts";
import Stripe from "https://esm.sh/stripe@18.5.0";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.57.2";
import { z } from "https://deno.land/x/zod@v3.22.4/mod.ts";
import { corsHeaders, handleCors } from "../_shared/cors.ts";
import { EdgeLogger } from "../_shared/logger.ts";

// Validation schema for Authorization header
const authHeaderSchema = z.string().startsWith("Bearer ").max(1000);

serve(async (req) => {
  const corsResponse = handleCors(req);
  if (corsResponse) return corsResponse;

  const logger = new EdgeLogger();

  try {
    await logger.info("Customer portal access requested", "customer-portal");

    const stripeKey = Deno.env.get("STRIPE_SECRET_KEY");
    if (!stripeKey) throw new Error("STRIPE_SECRET_KEY is not set");

    const supabaseClient = createClient(
      Deno.env.get("SUPABASE_URL") ?? "",
      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "",
      { auth: { persistSession: false } }
    );

    const authHeader = req.headers.get("Authorization");
    if (!authHeader) throw new Error("No authorization header provided");

    // Validate authorization header format
    const validatedAuthHeader = authHeaderSchema.parse(authHeader);
    const token = validatedAuthHeader.replace("Bearer ", "");
    const { data: userData, error: userError } = await supabaseClient.auth.getUser(token);
    if (userError) throw new Error(`Authentication error: ${userError.message}`);
    const user = userData.user;
    if (!user?.email) throw new Error("User not authenticated or email not available");
    await logger.info("User authenticated", "customer-portal", { userId: user.id, email: user.email });

    const stripe = new Stripe(stripeKey, { apiVersion: "2025-08-27" as any });
    const customers = await stripe.customers.list({ email: user.email, limit: 1 });
    if (customers.data.length === 0) {
      throw new Error("No Stripe customer found for this user");
    }
    const customerId = customers.data[0].id;
    await logger.info("Found Stripe customer", "customer-portal", { customerId });

    const origin = req.headers.get("origin") || "http://localhost:3000";
    const portalSession = await stripe.billingPortal.sessions.create({
      customer: customerId,
      return_url: `${origin}/configuracoes`,
    });
    await logger.info("Customer portal session created", "customer-portal", { sessionId: portalSession.id, url: portalSession.url });

    return new Response(JSON.stringify({ url: portalSession.url }), {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
      status: 200,
    });
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : String(error);
    await logger.error("Customer portal error", "customer-portal", { message: errorMessage });
    return new Response(JSON.stringify({ error: errorMessage }), {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
      status: 500,
    });
  }
});

import { serve } from "https://deno.land/std@0.190.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { EdgeLogger } from "../_shared/logger.ts";

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

// Mapa de DDDs para idiomas
const DDD_IDIOMA_MAP: Record<string, string> = {
  // Internacional - EN
  '1': 'en',  // EUA/Canadá
  '44': 'en', // Reino Unido

  // Internacional - ES
  '34': 'es', // Espanha
  '52': 'es', // México
  '54': 'es', // Argentina
  '56': 'es', // Chile
  '57': 'es', // Colômbia

  // Brasil - PT (default)
  '55': 'pt',
};

serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response(null, { headers: corsHeaders });
  }

  const logger = new EdgeLogger();
  const supabase = createClient(
    Deno.env.get('SUPABASE_URL') ?? '',
    Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
  );

  try {
    const { paciente_id, tenant_id, telefone } = await req.json();

    logger.info('Detectando idioma', 'i18n', { paciente_id });

    // Verificar se já existe preferência
    const { data: existente } = await supabase
      .from('paciente_preferencias_idioma' as any)
      .select('*')
      .eq('tenant_id', tenant_id)
      .eq('paciente_id', paciente_id)
      .single();

    if (existente && existente.confirmado_pelo_paciente) {
      return new Response(
        JSON.stringify({ idioma: existente.idioma, metodo: 'confirmado' }),
        { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    // Detectar por DDD
    let idiomaDetectado = 'pt';
    let metodoDeteccao = 'default';

    if (telefone) {
      const ddd = telefone.replace(/\D/g, '').substring(0, 2);

      for (const [codigo, idioma] of Object.entries(DDD_IDIOMA_MAP)) {
        if (telefone.startsWith('+' + codigo) || ddd === codigo) {
          idiomaDetectado = idioma;
          metodoDeteccao = 'ddd';
          break;
        }
      }
    }

    // Salvar/atualizar preferência
    const { error: upsertError } = await supabase
      .from('paciente_preferencias_idioma' as any)
      .upsert({
        tenant_id,
        paciente_id,
        idioma: idiomaDetectado,
        metodo_deteccao: metodoDeteccao,
        deteccao_automatica: true
      }, {
        onConflict: 'tenant_id,paciente_id'
      });

    if (upsertError) throw upsertError;

    logger.info('Idioma detectado', 'i18n', { idioma: idiomaDetectado, metodo: metodoDeteccao });

    return new Response(
      JSON.stringify({ idioma: idiomaDetectado, metodo: metodoDeteccao }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );

  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : String(error);
    logger.error('Erro ao detectar idioma', 'i18n', { error: errorMessage });
    return new Response(
      JSON.stringify({ error: errorMessage }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 500 }
    );
  }
});

