import { serve } from "https://deno.land/std@0.190.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { EdgeLogger } from "../_shared/logger.ts";

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response(null, { headers: corsHeaders });
  }

  const logger = new EdgeLogger();
  const supabase = createClient(
    Deno.env.get('SUPABASE_URL') ?? '',
    Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
  );

  try {
    logger.info('Iniciando orquestração de lembretes', 'lembretes', {});

    // Buscar agendamentos que precisam de lembretes
    const horaAtual = new Date();
    const janelas = [72, 24, 1]; // horas antes do agendamento

    let totalEnviados = 0;

    for (const janela of janelas) {
      const dataAlvo = new Date(horaAtual.getTime() + janela * 60 * 60 * 1000);
      const dataMin = new Date(dataAlvo.getTime() - 30 * 60 * 1000); // -30min
      const dataMax = new Date(dataAlvo.getTime() + 30 * 60 * 1000); // +30min

      const { data: agendamentos, error: agendError } = await supabase
        .from('agenda')
        .select('*, servicos(*), pacientes(*), tenants(*)')
        .gte('inicio', dataMin.toISOString())
        .lte('inicio', dataMax.toISOString())
        .eq('status', 'agendado')
        .eq('confirmado', false);

      if (agendError || !agendamentos || agendamentos.length === 0) continue;

      logger.info(`Processando ${agendamentos.length} agendamentos para janela ${janela}h`, 'lembretes', {});

      for (const agendamento of agendamentos) {
        try {
          // Verificar se já foi enviado lembrete nesta janela
          const { data: jaEnviado } = await supabase
            .from('lembrete_historico' as any)
            .select('id')
            .eq('agendamento_id', agendamento.id)
            .eq('janela_horas', janela)
            .single();

          if (jaEnviado) continue;

          // Buscar configuração de lembretes para este tipo de serviço
          const tipoServico = (agendamento.servicos as any)?.tipo || 'geral';
          const { data: config } = await supabase
            .from('lembrete_configs' as any)
            .select('*')
            .eq('tenant_id', agendamento.tenant_id)
            .eq('tipo_servico', tipoServico)
            .single();

          // Buscar templates disponíveis para esta janela
          const { data: templates } = await supabase
            .from('lembrete_templates' as any)
            .select('*')
            .eq('tenant_id', agendamento.tenant_id)
            .eq('janela_horas', janela)
            .eq('ativo', true)
            .order('score', { ascending: false });

          if (!templates || templates.length === 0) continue;

          // A/B Testing: selecionar template randomicamente entre os top 2
          const templateSelecionado = config?.ab_testing_ativo && templates.length > 1
            ? templates[Math.floor(Math.random() * Math.min(2, templates.length))]
            : templates[0];

          // Preparar mensagem
          const mensagem = templateSelecionado.corpo_mensagem
            .replace('{{nome_paciente}}', (agendamento.pacientes as any)?.nome || 'Paciente')
            .replace('{{data}}', new Date(agendamento.inicio).toLocaleDateString('pt-BR'))
            .replace('{{hora}}', new Date(agendamento.inicio).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }))
            .replace('{{servico}}', (agendamento.servicos as any)?.nome || 'Consulta');

          // Enviar lembrete via WhatsApp
          const { error: sendError } = await supabase.functions.invoke('enviar-whatsapp', {
            body: {
              to: (agendamento.pacientes as any)?.telefone,
              template_name: 'lembrete_agendamento',
              template_params: [
                { type: "text", text: (agendamento.pacientes as any)?.nome || 'Paciente' },
                { type: "text", text: new Date(agendamento.inicio).toLocaleDateString('pt-BR') },
                { type: "text", text: new Date(agendamento.inicio).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }) }
              ],
              tipo: 'template'
            }
          });

          if (!sendError) {
            // Registrar no histórico
            await supabase.from('lembrete_historico' as any).insert({
              tenant_id: agendamento.tenant_id,
              agendamento_id: agendamento.id,
              template_id: templateSelecionado.id,
              janela_horas: janela,
              variante: templateSelecionado.variante
            });

            // Atualizar contador do template
            await supabase.from('lembrete_templates' as any)
              .update({ total_envios: (templateSelecionado.total_envios || 0) + 1 })
              .eq('id', templateSelecionado.id);

            totalEnviados++;
          }

        } catch (agendError) {
          logger.error('Erro ao processar agendamento', 'lembretes', {
            agendamento_id: agendamento.id,
            error: agendError instanceof Error ? agendError.message : String(agendError)
          });
        }
      }
    }

    // Atualizar scores dos templates
    await supabase.rpc('atualizar_scores_templates');

    logger.info('Orquestração concluída', 'lembretes', { total_enviados: totalEnviados });

    return new Response(
      JSON.stringify({
        success: true,
        total_enviados: totalEnviados
      }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );

  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : String(error);
    logger.error('Erro na orquestração de lembretes', 'lembretes', { error: errorMessage });
    return new Response(
      JSON.stringify({ error: errorMessage }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 500 }
    );
  }
});

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import Stripe from "https://esm.sh/stripe@18.5.0";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.57.2";

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response(null, { headers: corsHeaders });
  }

  const stripe = new Stripe(Deno.env.get("STRIPE_SECRET_KEY") || "", {
    apiVersion: "2025-08-27" as any,
  });

  const supabase = createClient(
    Deno.env.get("SUPABASE_URL") ?? "",
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? ""
  );

  try {
    const body = await req.text();
    const signature = req.headers.get("stripe-signature");

    // Em produção, verificar signature com webhook secret
    const event = JSON.parse(body);

    console.log(`[PHONE-WEBHOOK] Received event: ${event.type}`);

    if (event.type === 'checkout.session.completed') {
      const session = event.data.object;

      if (session.metadata?.tipo !== 'phone_number_subscription') {
        return new Response(JSON.stringify({ received: true }), {
          headers: { ...corsHeaders, 'Content-Type': 'application/json' }
        });
      }

      const tenantId = session.metadata.tenant_id;
      const packageId = session.metadata.package_id;
      const departamentos = JSON.parse(session.metadata.departamentos || '["geral"]');

      // Buscar pacote
      const { data: pkg } = await supabase
        .from('phone_number_packages')
        .select('*')
        .eq('id', packageId)
        .single();

      if (!pkg) throw new Error('Pacote não encontrado');

      // Provisionar números para cada departamento
      const { data: provider } = await supabase
        .from('whatsapp_providers')
        .select('*')
        .eq('nome', '360dialog')
        .single();

      for (let i = 0; i < pkg.quantidade_numeros; i++) {
        const departamento = departamentos[i] || `dept_${i + 1}`;

        // Criar número (em produção, chamar API do 360dialog)
        const phoneNumber = `+5511${Date.now().toString().slice(-9)}`;

        const { data: newPhone } = await supabase
          .from('whatsapp_phone_numbers')
          .insert({
            provider_id: provider?.id,
            phone_number: phoneNumber,
            display_name: `${departamento} - ${tenantId.slice(0, 8)}`,
            is_shared: false,
            status: 'pending',
            custo_mensal: provider?.custo_mensal_numero || 15,
            moeda: 'EUR'
          })
          .select()
          .single();

        if (newPhone) {
          // Criar alocação
          const { data: allocation } = await supabase
            .from('tenant_phone_allocations')
            .insert({
              tenant_id: tenantId,
              phone_number_id: newPhone.id,
              departamento,
              is_primary: i === 0
            })
            .select()
            .single();

          // Criar assinatura
          if (allocation) {
            await supabase.from('phone_number_subscriptions').insert({
              tenant_id: tenantId,
              allocation_id: allocation.id,
              preco_mensal: pkg.preco_mensal / pkg.quantidade_numeros,
              moeda: pkg.moeda,
              stripe_subscription_id: session.subscription,
              status: 'active',
              periodo_atual_inicio: new Date().toISOString(),
              periodo_atual_fim: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString()
            });

            // Criar departamento
            await supabase.from('tenant_whatsapp_departments').insert({
              tenant_id: tenantId,
              nome: departamento.charAt(0).toUpperCase() + departamento.slice(1),
              codigo: departamento,
              phone_allocation_id: allocation.id
            });
          }
        }
      }

      // Atualizar roteamento para não usar número compartilhado
      await supabase
        .from('tenant_whatsapp_routing')
        .upsert({
          tenant_id: tenantId,
          usa_numero_compartilhado: false,
          ai_routing_enabled: true
        }, { onConflict: 'tenant_id' });

      // Adicionar créditos inclusos
      if (pkg.inclui_creditos > 0) {
        const { data: credits } = await supabase
          .from('tenant_whatsapp_credits')
          .select('saldo_creditos')
          .eq('tenant_id', tenantId)
          .single();

        const saldoAtual = credits?.saldo_creditos || 0;

        await supabase.from('tenant_whatsapp_credits').upsert({
          tenant_id: tenantId,
          saldo_creditos: saldoAtual + pkg.inclui_creditos
        }, { onConflict: 'tenant_id' });

        await supabase.from('tenant_credit_transactions').insert({
          tenant_id: tenantId,
          tipo: 'bonus',
          quantidade: pkg.inclui_creditos,
          saldo_anterior: saldoAtual,
          saldo_novo: saldoAtual + pkg.inclui_creditos,
          motivo: `Créditos inclusos no pacote ${pkg.nome}`
        });
      }

      console.log(`[PHONE-WEBHOOK] Provisioned ${pkg.quantidade_numeros} numbers for tenant ${tenantId}`);
    }

    return new Response(JSON.stringify({ received: true }), {
      headers: { ...corsHeaders, 'Content-Type': 'application/json' }
    });

  } catch (error) {
    console.error('[PHONE-WEBHOOK] Error:', error);
    return new Response(JSON.stringify({ 
      error: error instanceof Error ? error.message : 'Erro interno' 
    }), {
      status: 500,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' }
    });
  }
});

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
import { corsHeaders, handleCors } from '../_shared/cors.ts';
import { EdgeLogger } from '../_shared/logger.ts';

interface CheckinPayload {
  agendamento_id: string;
  paciente_id: string;
  tenant_id: string;
  etapa: 'convenio' | 'carteirinha' | 'foto_frente' | 'foto_verso' | 'motivo' | 'lgpd';
  valor?: string;
  foto_url?: string;
}

Deno.serve(async (req) => {
  const corsResponse = handleCors(req);
  if (corsResponse) return corsResponse;

  const logger = new EdgeLogger();
  
  try {
    const supabase = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
    );

    const payload: CheckinPayload = await req.json();
    logger.info('Processando check-in WhatsApp', 'checkin_whatsapp', { payload });

    const { agendamento_id, paciente_id, tenant_id, etapa, valor, foto_url } = payload;

    // Buscar ou criar registro de check-in
    let { data: checkin, error: errorCheckin } = await supabase
      .from('checkin_whatsapp')
      .select('*')
      .eq('agendamento_id', agendamento_id)
      .eq('paciente_id', paciente_id)
      .single();

    if (errorCheckin && errorCheckin.code !== 'PGRST116') {
      throw errorCheckin;
    }

    if (!checkin) {
      // Criar novo check-in
      const { data: novoCheckin, error: errorNovo } = await supabase
        .from('checkin_whatsapp')
        .insert({
          tenant_id,
          agendamento_id,
          paciente_id,
          status: 'aguardando_dados',
          etapa_atual: etapa
        })
        .select()
        .single();

      if (errorNovo) throw errorNovo;
      checkin = novoCheckin;
    }

    // Validar dados baseado no tipo de serviço
    const { data: agendamento } = await supabase
      .from('agenda')
      .select('servico_id, servicos(tipo)')
      .eq('id', agendamento_id)
      .single();

    const tipoServico = (agendamento?.servicos as any)?.tipo || 'geral';

    // Processar cada etapa
    const updateData: any = { etapa_atual: etapa };
    let proximaEtapa = '';
    let mensagemResposta = '';

    switch (etapa) {
      case 'convenio':
        if (!valor || valor.trim().length < 2) {
          updateData.tentativas = (checkin.tentativas || 0) + 1;
          updateData.ultimo_erro = 'Convênio inválido';
          mensagemResposta = '❌ Por favor, informe o nome do convênio/seguradora corretamente.';
        } else {
          updateData.convenio = valor;
          proximaEtapa = 'carteirinha';
          mensagemResposta = '✅ Convênio registrado!\n\n📋 Agora, envie o *número da carteirinha*.';
        }
        break;

      case 'carteirinha':
        if (!valor || valor.trim().length < 3) {
          updateData.tentativas = (checkin.tentativas || 0) + 1;
          updateData.ultimo_erro = 'Carteirinha inválida';
          mensagemResposta = '❌ Por favor, informe o número da carteirinha corretamente.';
        } else {
          updateData.numero_carteirinha = valor;
          proximaEtapa = 'foto_frente';
          mensagemResposta = '✅ Carteirinha registrada!\n\n📸 Envie uma *foto da frente* da carteirinha.';
        }
        break;

      case 'foto_frente':
        if (!foto_url) {
          updateData.tentativas = (checkin.tentativas || 0) + 1;
          updateData.ultimo_erro = 'Foto não recebida';
          mensagemResposta = '❌ Não recebemos a foto. Por favor, envie novamente a foto da *frente da carteirinha*.';
        } else {
          updateData.foto_frente_url = foto_url;
          proximaEtapa = 'foto_verso';
          mensagemResposta = '✅ Foto da frente recebida!\n\n📸 Agora envie a *foto do verso* da carteirinha.';
        }
        break;

      case 'foto_verso':
        if (!foto_url) {
          updateData.tentativas = (checkin.tentativas || 0) + 1;
          updateData.ultimo_erro = 'Foto não recebida';
          mensagemResposta = '❌ Não recebemos a foto. Por favor, envie novamente a foto do *verso da carteirinha*.';
        } else {
          updateData.foto_verso_url = foto_url;
          proximaEtapa = 'motivo';
          mensagemResposta = '✅ Foto do verso recebida!\n\n💬 Qual o *motivo da sua consulta*? (descreva brevemente)';
        }
        break;

      case 'motivo':
        if (!valor || valor.trim().length < 5) {
          updateData.tentativas = (checkin.tentativas || 0) + 1;
          updateData.ultimo_erro = 'Motivo muito curto';
          mensagemResposta = '❌ Por favor, descreva o motivo da consulta com mais detalhes.';
        } else {
          updateData.motivo_consulta = valor;
          proximaEtapa = 'lgpd';
          mensagemResposta = '✅ Motivo registrado!\n\n' +
            '📋 *Termos LGPD*\n\n' +
            'Você autoriza o uso dos seus dados para:\n' +
            '1️⃣ - Sim para tudo (lembretes + promoções)\n' +
            '2️⃣ - Apenas lembretes\n' +
            '3️⃣ - Não autorizo';
        }
        break;

      case 'lgpd':
        if (valor === '1') {
          updateData.consentimento_lgpd = true;
          updateData.opt_in_lembretes = true;
          updateData.opt_in_promocoes = true;
        } else if (valor === '2') {
          updateData.consentimento_lgpd = true;
          updateData.opt_in_lembretes = true;
          updateData.opt_in_promocoes = false;
        } else if (valor === '3') {
          updateData.consentimento_lgpd = false;
          updateData.opt_in_lembretes = false;
          updateData.opt_in_promocoes = false;
        } else {
          mensagemResposta = '❌ Resposta inválida. Responda:\n1️⃣ - Sim para tudo\n2️⃣ - Apenas lembretes\n3️⃣ - Não autorizo';
          break;
        }

        updateData.status = 'completo';
        updateData.pronto_atendimento = true;
        proximaEtapa = 'concluido';
        
        mensagemResposta = '✅ *Check-in concluído!*\n\n' +
          '🎉 Você está pronto para o atendimento!\n\n' +
          'Seus dados foram registrados com sucesso. Aguarde sua consulta.';

        // Registrar consentimento LGPD
        if (updateData.consentimento_lgpd) {
          await supabase.from('consent_records').insert({
            tenant_id,
            contact_id: paciente_id,
            consent_type: 'whatsapp',
            status: 'opted_in',
            channel: 'whatsapp',
            ip_address: 'whatsapp',
            metadata: {
              opt_in_lembretes: updateData.opt_in_lembretes,
              opt_in_promocoes: updateData.opt_in_promocoes,
              checkin_id: checkin.id
            }
          });
        }

        // Log de auditoria
        await supabase.rpc('log_system_event', {
          p_level: 'info',
          p_message: 'Check-in WhatsApp concluído',
          p_service: 'checkin_whatsapp',
          p_tenant_id: tenant_id,
          p_user_id: paciente_id,
          p_metadata: {
            checkin_id: checkin.id,
            agendamento_id,
            consentimento_lgpd: updateData.consentimento_lgpd
          }
        });
        break;
    }

    // Atualizar check-in
    updateData.etapa_atual = proximaEtapa || etapa;
    
    const { error: errorUpdate } = await supabase
      .from('checkin_whatsapp')
      .update(updateData)
      .eq('id', checkin.id);

    if (errorUpdate) throw errorUpdate;

    logger.info('Check-in processado', 'checkin_whatsapp', {
      checkin_id: checkin.id,
      etapa,
      proxima_etapa: proximaEtapa
    });

    return new Response(
      JSON.stringify({
        success: true,
        message: mensagemResposta,
        proxima_etapa: proximaEtapa,
        concluido: proximaEtapa === 'concluido'
      }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );

  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : String(error);
    logger.error('Erro ao processar check-in', 'checkin_whatsapp', { error: errorMessage });
    return new Response(
      JSON.stringify({ error: errorMessage }),
      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }
});

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

interface MetricEvent {
  tenant_id: string;
  event_type: 'sent' | 'delivered' | 'read' | 'failed';
  error_category?: 'network' | 'template' | 'invalid_number' | 'blocked' | 'other';
  latency_ms?: number;
  quality_rating?: 'green' | 'yellow' | 'red';
  phone_number?: string;
}

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    const supabase = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
    );

    const { events } = await req.json() as { events: MetricEvent[] };

    if (!events || !Array.isArray(events)) {
      throw new Error('Events array is required');
    }

    console.log(`Processing ${events.length} metric events`);

    // Agrupar eventos por tenant e período (hora)
    const metricsByTenantHour = new Map<string, any>();

    for (const event of events) {
      const hourKey = `${event.tenant_id}_${new Date().toISOString().slice(0, 13)}`;

      if (!metricsByTenantHour.has(hourKey)) {
        metricsByTenantHour.set(hourKey, {
          tenant_id: event.tenant_id,
          periodo: new Date(new Date().setMinutes(0, 0, 0)),
          mensagens_enviadas: 0,
          mensagens_entregues: 0,
          mensagens_lidas: 0,
          mensagens_falhadas: 0,
          erros_rede: 0,
          erros_template: 0,
          erros_numero_invalido: 0,
          erros_bloqueio: 0,
          erros_outros: 0,
          latencies: [] as number[],
          tps_count: 0,
          quality_rating: event.quality_rating || 'unknown',
        });
      }

      const metrics = metricsByTenantHour.get(hourKey);

      // Atualizar contadores
      if (event.event_type === 'sent') metrics.mensagens_enviadas++;
      if (event.event_type === 'delivered') metrics.mensagens_entregues++;
      if (event.event_type === 'read') metrics.mensagens_lidas++;
      if (event.event_type === 'failed') {
        metrics.mensagens_falhadas++;
        if (event.error_category === 'network') metrics.erros_rede++;
        if (event.error_category === 'template') metrics.erros_template++;
        if (event.error_category === 'invalid_number') metrics.erros_numero_invalido++;
        if (event.error_category === 'blocked') metrics.erros_bloqueio++;
        if (event.error_category === 'other') metrics.erros_outros++;
      }

      if (event.latency_ms) {
        metrics.latencies.push(event.latency_ms);
      }

      metrics.tps_count++;

      // Verificar rate limit se fornecido
      if (event.phone_number) {
        const { data: canSend } = await supabase.rpc('check_rate_limit', {
          p_tenant_id: event.tenant_id,
          p_phone_number: event.phone_number
        });

        if (!canSend) {
          console.log(`Rate limit exceeded for ${event.phone_number}`);
        }
      }
    }

    // Calcular e salvar métricas agregadas
    const results = [];
    for (const [_, metrics] of metricsByTenantHour) {
      // Calcular percentis de latência
      const sortedLatencies = metrics.latencies.sort((a: number, b: number) => a - b);
      const p50 = sortedLatencies[Math.floor(sortedLatencies.length * 0.5)] || 0;
      const p95 = sortedLatencies[Math.floor(sortedLatencies.length * 0.95)] || 0;
      const p99 = sortedLatencies[Math.floor(sortedLatencies.length * 0.99)] || 0;

      // Calcular TPS
      const tpsMedio = metrics.tps_count / 3600; // média por segundo na hora

      // Taxa de erro
      const totalMessages = metrics.mensagens_enviadas || 1;
      const errorRate = (metrics.mensagens_falhadas / totalMessages) * 100;

      // Inserir/atualizar métricas
      const { data, error } = await supabase
        .from('whatsapp_metrics')
        .upsert({
          tenant_id: metrics.tenant_id,
          periodo: metrics.periodo,
          mensagens_enviadas: metrics.mensagens_enviadas,
          mensagens_entregues: metrics.mensagens_entregues,
          mensagens_lidas: metrics.mensagens_lidas,
          mensagens_falhadas: metrics.mensagens_falhadas,
          erros_rede: metrics.erros_rede,
          erros_template: metrics.erros_template,
          erros_numero_invalido: metrics.erros_numero_invalido,
          erros_bloqueio: metrics.erros_bloqueio,
          erros_outros: metrics.erros_outros,
          latencia_p50: Math.round(p50),
          latencia_p95: Math.round(p95),
          latencia_p99: Math.round(p99),
          tps_medio: tpsMedio,
          quality_rating: metrics.quality_rating,
        }, { onConflict: 'tenant_id,periodo' });

      if (error) {
        console.error('Error saving metrics:', error);
        continue;
      }

      // Verificar alarmes
      if (errorRate > 2) {
        await supabase.rpc('create_alarm', {
          p_tenant_id: metrics.tenant_id,
          p_alarm_type: 'error_rate',
          p_threshold_value: 2,
          p_current_value: errorRate,
          p_message: `Taxa de erro está em ${errorRate.toFixed(2)}% (limite: 2%)`,
          p_severity: errorRate > 5 ? 'critical' : 'error',
          p_metadata: { periodo: metrics.periodo }
        });
      }

      if (metrics.erros_template > 0) {
        await supabase.rpc('create_alarm', {
          p_tenant_id: metrics.tenant_id,
          p_alarm_type: 'template_rejection',
          p_threshold_value: 0,
          p_current_value: metrics.erros_template,
          p_message: `${metrics.erros_template} templates foram rejeitados`,
          p_severity: 'error',
          p_metadata: { periodo: metrics.periodo }
        });
      }

      if (metrics.quality_rating === 'red' || metrics.quality_rating === 'yellow') {
        await supabase.rpc('create_alarm', {
          p_tenant_id: metrics.tenant_id,
          p_alarm_type: 'quality_rating',
          p_threshold_value: 0,
          p_current_value: 0,
          p_message: `Quality rating está ${metrics.quality_rating}`,
          p_severity: metrics.quality_rating === 'red' ? 'critical' : 'warning',
          p_metadata: { periodo: metrics.periodo }
        });
      }

      results.push(data);
    }

    return new Response(JSON.stringify({ 
      success: true, 
      processed: events.length,
      metrics_updated: results.length 
    }), {
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });

  } catch (error) {
    console.error('Error processing metrics:', error);
    const errorMessage = error instanceof Error ? error.message : 'Unknown error';
    return new Response(JSON.stringify({ error: errorMessage }), {
      status: 500,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }
});

import { serve } from "https://deno.land/std@0.190.0/http/server.ts";
import Stripe from "https://esm.sh/stripe@18.5.0";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.57.2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  const supabaseClient = createClient(
    Deno.env.get("SUPABASE_URL") ?? "",
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? ""
  );

  try {
    const authHeader = req.headers.get("Authorization")!;
    const token = authHeader.replace("Bearer ", "");
    const { data } = await supabaseClient.auth.getUser(token);
    const user = data.user;
    if (!user) throw new Error("User not authenticated");

    const { session_id } = await req.json();

    const stripe = new Stripe(Deno.env.get("STRIPE_SECRET_KEY") || "", {
      apiVersion: "2025-08-27" as any,
    });

    // Verificar sessão de pagamento
    const session = await stripe.checkout.sessions.retrieve(session_id);

    if (session.payment_status !== "paid") {
      throw new Error("Pagamento não confirmado");
    }

    const package_id = session.metadata?.package_id;
    if (!package_id) {
      throw new Error("ID do pacote não encontrado");
    }

    // Buscar tenant do usuário
    const { data: profile } = await supabaseClient
      .from("profiles")
      .select("tenant_id")
      .eq("id", user.id)
      .single();

    if (!profile?.tenant_id) {
      throw new Error("Tenant não encontrado");
    }

    // Creditar mensagens usando a função do banco
    const { data: result, error } = await supabaseClient.rpc("creditar_whatsapp", {
      p_tenant_id: profile.tenant_id,
      p_package_id: package_id,
      p_created_by: user.id,
    });

    if (error) throw error;

    return new Response(JSON.stringify({ success: true, result }), {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
      status: 200,
    });
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : String(error);
    return new Response(JSON.stringify({ error: errorMessage }), {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
      status: 500,
    });
  }
});

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import Stripe from "https://esm.sh/stripe@18.5.0";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.57.2";

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response(null, { headers: corsHeaders });
  }

  const supabase = createClient(
    Deno.env.get("SUPABASE_URL") ?? "",
    Deno.env.get("SUPABASE_ANON_KEY") ?? ""
  );

  try {
    // Autenticar usuário
    const authHeader = req.headers.get("Authorization")!;
    const token = authHeader.replace("Bearer ", "");
    const { data: userData } = await supabase.auth.getUser(token);
    const user = userData.user;
    if (!user?.email) throw new Error("Usuário não autenticado");

    const { package_id, departamentos } = await req.json();

    // Buscar profile e tenant
    const { data: profile } = await supabase
      .from('profiles')
      .select('tenant_id, role')
      .eq('id', user.id)
      .single();

    if (!profile?.tenant_id) throw new Error("Tenant não encontrado");
    if (profile.role !== 'admin') throw new Error("Apenas administradores podem contratar números");

    // Buscar pacote
    const { data: pkg } = await supabase
      .from('phone_number_packages')
      .select('*')
      .eq('id', package_id)
      .eq('ativo', true)
      .single();

    if (!pkg) throw new Error("Pacote não encontrado");

    // Verificar plano do tenant
    const { data: subscription } = await supabase
      .from('subscriptions')
      .select('*, plan:plans(slug)')
      .eq('tenant_id', profile.tenant_id)
      .eq('status', 'active')
      .single();

    const planSlug = (subscription?.plan as any)?.slug || 'free';
    if (!pkg.planos_permitidos.includes(planSlug)) {
      throw new Error(`Este pacote requer plano ${pkg.planos_permitidos.join(' ou ')}`);
    }

    // Criar checkout Stripe
    const stripe = new Stripe(Deno.env.get("STRIPE_SECRET_KEY") || "", {
      apiVersion: "2025-08-27" as any,
    });

    // Buscar ou criar customer
    const customers = await stripe.customers.list({ email: user.email, limit: 1 });
    let customerId = customers.data[0]?.id;

    if (!customerId) {
      const customer = await stripe.customers.create({ email: user.email });
      customerId = customer.id;
    }

    // Criar price se não existir
    let priceId = pkg.stripe_price_id;
    if (!priceId) {
      const product = await stripe.products.create({
        name: `CleanFlow - ${pkg.nome}`,
        description: pkg.descricao || `${pkg.quantidade_numeros} número(s) WhatsApp exclusivo(s)`,
      });

      const price = await stripe.prices.create({
        product: product.id,
        unit_amount: Math.round(pkg.preco_mensal * 100),
        currency: pkg.moeda.toLowerCase(),
        recurring: { interval: 'month' },
      });

      priceId = price.id;

      // Atualizar pacote com price_id
      await supabase
        .from('phone_number_packages')
        .update({ stripe_price_id: priceId })
        .eq('id', package_id);
    }

    // Criar checkout session
    const session = await stripe.checkout.sessions.create({
      customer: customerId,
      line_items: [{ price: priceId, quantity: 1 }],
      mode: 'subscription',
      success_url: `${req.headers.get("origin")}/configuracoes-whatsapp?phone_success=true&session_id={CHECKOUT_SESSION_ID}`,
      cancel_url: `${req.headers.get("origin")}/configuracoes-whatsapp?phone_cancelled=true`,
      metadata: {
        tenant_id: profile.tenant_id,
        package_id: package_id,
        departamentos: JSON.stringify(departamentos || ['geral']),
        tipo: 'phone_number_subscription'
      },
      subscription_data: {
        metadata: {
          tenant_id: profile.tenant_id,
          package_id: package_id,
        }
      }
    });

    return new Response(JSON.stringify({ url: session.url }), {
      headers: { ...corsHeaders, 'Content-Type': 'application/json' }
    });

  } catch (error) {
    console.error('[PROVISION-PHONE] Error:', error);
    return new Response(JSON.stringify({
      error: error instanceof Error ? error.message : 'Erro interno'
    }), {
      status: 500,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' }
    });
  }
});

import { serve } from "https://deno.land/std@0.190.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.57.2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  const supabaseClient = createClient(
    Deno.env.get("SUPABASE_URL") ?? "",
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? ""
  );

  try {
    // Buscar todas as subscriptions ativas
    const { data: subscriptions, error: subError } = await supabaseClient
      .from("subscriptions")
      .select("*, plans!inner(slug, metadata)")
      .eq("status", "active");

    if (subError) throw subError;

    let totalResetado = 0;

    for (const subscription of subscriptions || []) {
      const plan = subscription.plans;
      const mensagensMensais = (plan.metadata as any)?.mensagens_mensais || 0;

      if (mensagensMensais > 0) {
        const tenant_id = subscription.tenant_id;

        // Buscar créditos atuais
        const { data: credits } = await supabaseClient
          .from("tenant_whatsapp_credits")
          .select("saldo_creditos, creditos_plano_mes_atual")
          .eq("tenant_id", tenant_id)
          .single();

        if (credits) {
          // Remover créditos do plano atual não utilizados
          const creditosNaoUtilizados = credits.creditos_plano_mes_atual || 0;
          const novoSaldo = credits.saldo_creditos - creditosNaoUtilizados + mensagensMensais;

          // Atualizar créditos
          await supabaseClient
            .from("tenant_whatsapp_credits")
            .update({
              saldo_creditos: novoSaldo,
              creditos_plano_mes_atual: mensagensMensais,
              updated_at: new Date().toISOString(),
            })
            .eq("tenant_id", tenant_id);

          // Registrar transação
          await supabaseClient
            .from("tenant_credit_transactions")
            .insert({
              tenant_id: tenant_id,
              tipo: "reset_mensal",
              quantidade: mensagensMensais,
              motivo: `Reset mensal do plano ${plan.slug}`,
              metadata: { 
                plan_id: plan.id,
                creditos_anteriores: creditosNaoUtilizados 
              },
            });

          totalResetado++;
        }
      }
    }

    return new Response(
      JSON.stringify({ 
        success: true, 
        totalResetado,
        message: `${totalResetado} planos resetados`
      }),
      {
        headers: { ...corsHeaders, "Content-Type": "application/json" },
        status: 200,
      }
    );
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : String(error);
    return new Response(JSON.stringify({ error: errorMessage }), {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
      status: 500,
    });
  }
});

import { serve } from "https://deno.land/std@0.190.0/http/server.ts";
import Stripe from "https://esm.sh/stripe@18.5.0";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.57.2";

// CORS restrito ao domínio CleanFlow
const corsHeaders = {
  "Access-Control-Allow-Origin": "https://clinflow.lovable.app",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type, stripe-signature",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

const logStep = (step: string, details?: any) => {
  const detailsStr = details ? ` - ${JSON.stringify(details)}` : '';
  console.log(`[STRIPE-WEBHOOK] ${step}${detailsStr}`);
};

serve(async (req) => {
  // Handle CORS preflight
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  // Apenas POST permitido
  if (req.method !== "POST") {
    return new Response(JSON.stringify({ error: "Method not allowed" }), {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
      status: 405,
    });
  }

  const supabaseAdmin = createClient(
    Deno.env.get("SUPABASE_URL") ?? "",
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "",
    { auth: { persistSession: false } }
  );

  try {
    logStep("Webhook received");

    // Verificar se STRIPE_WEBHOOK_SECRET está configurado
    const webhookSecret = Deno.env.get("STRIPE_WEBHOOK_SECRET");
    if (!webhookSecret) {
      logStep("ERROR: STRIPE_WEBHOOK_SECRET not configured");
      return new Response(
        JSON.stringify({ error: "Webhook secret not configured" }),
        { headers: { ...corsHeaders, "Content-Type": "application/json" }, status: 400 }
      );
    }

    // Obter signature do header
    const signature = req.headers.get("stripe-signature");
    if (!signature) {
      logStep("ERROR: Missing stripe-signature header");
      return new Response(
        JSON.stringify({ error: "Missing stripe-signature header" }),
        { headers: { ...corsHeaders, "Content-Type": "application/json" }, status: 400 }
      );
    }

    // Obter body raw para verificação
    const body = await req.text();

    // Inicializar Stripe com apiVersion válida
    const stripeKey = Deno.env.get("STRIPE_SECRET_KEY");
    if (!stripeKey) {
      logStep("ERROR: STRIPE_SECRET_KEY not configured");
      return new Response(
        JSON.stringify({ error: "Stripe key not configured" }),
        { headers: { ...corsHeaders, "Content-Type": "application/json" }, status: 500 }
      );
    }

    const stripe = new Stripe(stripeKey, {
      apiVersion: "2025-08-27.basil" as any
    });

    // Verificar assinatura do webhook
    let event: Stripe.Event;
    try {
      event = stripe.webhooks.constructEvent(body, signature, webhookSecret);
      logStep("Signature verified", { eventId: event.id, type: event.type });
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : String(err);
      logStep("ERROR: Signature verification failed", { error: errorMessage });
      return new Response(
        JSON.stringify({ error: `Webhook signature verification failed: ${errorMessage}` }),
        { headers: { ...corsHeaders, "Content-Type": "application/json" }, status: 400 }
      );
    }

    // Verificar idempotência - ignorar eventos já processados
    const { data: existingEvent } = await supabaseAdmin.rpc(
      'check_stripe_event_processed',
      { p_event_id: event.id }
    );

    if (existingEvent === true) {
      logStep("Event already processed, skipping", { eventId: event.id });
      return new Response(
        JSON.stringify({ received: true, status: "already_processed" }),
        { headers: { ...corsHeaders, "Content-Type": "application/json" }, status: 200 }
      );
    }

    // Processar evento baseado no tipo
    let processed = false;
    let processingDetails: any = {};

    switch (event.type) {
      case "checkout.session.completed": {
        const session = event.data.object as Stripe.Checkout.Session;
        logStep("Processing checkout.session.completed", { sessionId: session.id });

        const metadata = session.metadata || {};

        // Verificar se é compra de créditos WhatsApp
        if (metadata.tipo === "creditos_whatsapp" && metadata.tenant_id && metadata.package_id) {
          await processWhatsAppCredits(supabaseAdmin, session, metadata);
          processingDetails = { action: "whatsapp_credits", tenantId: metadata.tenant_id };
        }
        // Verificar se é assinatura de plano
        else if (metadata.plan_slug && metadata.user_id) {
          await processSubscription(supabaseAdmin, session, metadata);
          processingDetails = { action: "subscription", userId: metadata.user_id };
        }
        // Verificar se é assinatura de número de telefone
        else if (metadata.type === "phone_subscription" && metadata.tenant_id) {
          await processPhoneSubscription(supabaseAdmin, session, metadata);
          processingDetails = { action: "phone_subscription", tenantId: metadata.tenant_id };
        }

        processed = true;
        break;
      }

      case "customer.subscription.updated":
      case "customer.subscription.deleted": {
        const subscription = event.data.object as Stripe.Subscription;
        logStep(`Processing ${event.type}`, { subscriptionId: subscription.id });

        await updateSubscriptionStatus(supabaseAdmin, subscription);
        processingDetails = { action: "subscription_update", subscriptionId: subscription.id };
        processed = true;
        break;
      }

      case "invoice.payment_succeeded": {
        const invoice = event.data.object as Stripe.Invoice;
        logStep("Processing invoice.payment_succeeded", { invoiceId: invoice.id });

        // Renovação de créditos mensais se aplicável
        if (invoice.subscription) {
          await handleInvoicePayment(supabaseAdmin, invoice);
          processingDetails = { action: "invoice_payment", invoiceId: invoice.id };
        }
        processed = true;
        break;
      }

      case "invoice.payment_failed": {
        const invoice = event.data.object as Stripe.Invoice;
        logStep("Processing invoice.payment_failed", { invoiceId: invoice.id });

        await handlePaymentFailed(supabaseAdmin, invoice);
        processingDetails = { action: "payment_failed", invoiceId: invoice.id };
        processed = true;
        break;
      }

      default:
        logStep("Unhandled event type", { type: event.type });
        processed = false;
    }

    // Registrar evento como processado (idempotência)
    await supabaseAdmin.rpc('register_stripe_event', {
      p_event_id: event.id,
      p_event_type: event.type,
      p_payload: { processed, ...processingDetails }
    });

    logStep("Event processed and registered", { eventId: event.id, processed });

    return new Response(
      JSON.stringify({ received: true, processed, eventId: event.id }),
      { headers: { ...corsHeaders, "Content-Type": "application/json" }, status: 200 }
    );

  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : String(error);
    logStep("ERROR in webhook", { message: errorMessage });
    return new Response(
      JSON.stringify({ error: errorMessage }),
      { headers: { ...corsHeaders, "Content-Type": "application/json" }, status: 500 }
    );
  }
});

// ============= Helper Functions =============

async function processWhatsAppCredits(
  supabase: any,
  session: Stripe.Checkout.Session,
  metadata: Record<string, string>
) {
  logStep("Processing WhatsApp credits", { tenantId: metadata.tenant_id, packageId: metadata.package_id });

  // Buscar pacote
  const { data: creditPackage, error: packageError } = await supabase
    .from("credit_packages")
    .select("quantidade_creditos, nome")
    .eq("id", metadata.package_id)
    .single();

  if (packageError || !creditPackage) {
    throw new Error("Credit package not found");
  }

  // Creditar usando função do banco
  const { data: result, error } = await supabase.rpc('creditar_whatsapp', {
    p_tenant_id: metadata.tenant_id,
    p_package_id: metadata.package_id,
    p_created_by: metadata.user_id || null
  });

  if (error) {
    throw new Error(`Failed to credit WhatsApp: ${error.message}`);
  }

  logStep("WhatsApp credits added", result);
}

async function processSubscription(
  supabase: any,
  session: Stripe.Checkout.Session,
  metadata: Record<string, string>
) {
  logStep("Processing subscription", { userId: metadata.user_id, planSlug: metadata.plan_slug });

  // Buscar plano
  const { data: plan, error: planError } = await supabase
    .from("plans")
    .select("id")
    .eq("slug", metadata.plan_slug)
    .single();

  if (planError || !plan) {
    logStep("Plan not found, will be updated on check-subscription call");
    return;
  }

  // Buscar tenant do usuário
  const { data: profile } = await supabase
    .from("profiles")
    .select("tenant_id")
    .eq("id", metadata.user_id)
    .single();

  if (!profile?.tenant_id) {
    logStep("Tenant not found for user");
    return;
  }

  // Criar/atualizar subscription
  await supabase
    .from("subscriptions")
    .upsert({
      tenant_id: profile.tenant_id,
      plan_id: plan.id,
      stripe_subscription_id: session.subscription as string,
      stripe_customer_id: session.customer as string,
      status: "active",
      billing_cycle: metadata.billing_cycle || "monthly",
    }, {
      onConflict: 'tenant_id'
    });

  logStep("Subscription created/updated in database");
}

async function processPhoneSubscription(
  supabase: any,
  session: Stripe.Checkout.Session,
  metadata: Record<string, string>
) {
  logStep("Processing phone subscription", { tenantId: metadata.tenant_id });

  await supabase
    .from("tenant_phone_subscriptions")
    .update({
      status: "active",
      stripe_subscription_id: session.subscription as string,
      stripe_customer_id: session.customer as string,
      updated_at: new Date().toISOString()
    })
    .eq("tenant_id", metadata.tenant_id)
    .eq("status", "pending");

  logStep("Phone subscription activated");
}

async function updateSubscriptionStatus(
  supabase: any,
  subscription: Stripe.Subscription
) {
  const status = subscription.status === "active" ? "active" :
    subscription.status === "canceled" ? "canceled" : subscription.status;

  await supabase
    .from("subscriptions")
    .update({
      status,
      current_period_start: new Date(subscription.current_period_start * 1000).toISOString(),
      current_period_end: new Date(subscription.current_period_end * 1000).toISOString(),
      cancel_at_period_end: subscription.cancel_at_period_end,
      updated_at: new Date().toISOString()
    })
    .eq("stripe_subscription_id", subscription.id);

  logStep("Subscription status updated", { subscriptionId: subscription.id, status });
}

async function handleInvoicePayment(
  supabase: any,
  invoice: Stripe.Invoice
) {
  // Atualizar subscription como paga
  await supabase
    .from("subscriptions")
    .update({
      status: "active",
      updated_at: new Date().toISOString()
    })
    .eq("stripe_subscription_id", invoice.subscription as string);

  logStep("Invoice payment processed", { invoiceId: invoice.id });
}

async function handlePaymentFailed(
  supabase: any,
  invoice: Stripe.Invoice
) {
  // Marcar subscription como past_due
  await supabase
    .from("subscriptions")
    .update({
      status: "past_due",
      updated_at: new Date().toISOString()
    })
    .eq("stripe_subscription_id", invoice.subscription as string);

  // Criar alerta
  await supabase.rpc('log_system_event', {
    p_level: 'warning',
    p_message: `Payment failed for invoice ${invoice.id}`,
    p_service: 'stripe_webhook',
    p_metadata: { invoice_id: invoice.id, customer_id: invoice.customer }
  });

  logStep("Payment failure handled", { invoiceId: invoice.id });
}

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import Stripe from "https://esm.sh/stripe@18.5.0";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.57.2";

const logStep = (step: string, details?: any) => {
  const detailsStr = details ? ` - ${JSON.stringify(details)}` : '';
  console.log(`[WEBHOOK-PHONE-SUB] ${step}${detailsStr}`);
};

serve(async (req) => {
  const stripe = new Stripe(Deno.env.get("STRIPE_SECRET_KEY") || "", {
    apiVersion: "2025-08-27.basil" as any,
  });

  const supabase = createClient(
    Deno.env.get("SUPABASE_URL") ?? "",
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? ""
  );

  try {
    const signature = req.headers.get("stripe-signature");
    const body = await req.text();

    // Verificar assinatura do webhook (se configurado)
    const webhookSecret = Deno.env.get("STRIPE_PHONE_WEBHOOK_SECRET");
    let event: Stripe.Event;

    if (webhookSecret && signature) {
      event = stripe.webhooks.constructEvent(body, signature, webhookSecret);
    } else {
      event = JSON.parse(body);
    }

    logStep("Evento recebido", { type: event.type, id: event.id });

    const eventData = event.data.object as any;

    switch (event.type) {
      case 'checkout.session.completed': {
        // Pagamento confirmado - ativar assinatura
        if (eventData.metadata?.tipo === 'phone_number_subscription') {
          const internalSubscriptionId = eventData.metadata.internal_subscription_id;
          const stripeSubscriptionId = eventData.subscription;
          const tenantId = eventData.metadata.tenant_id;
          const packageId = eventData.metadata.package_id;

          logStep("Checkout completado", { internalSubscriptionId, stripeSubscriptionId });

          // Buscar subscription do Stripe para pegar datas
          const stripeSub = await stripe.subscriptions.retrieve(stripeSubscriptionId);

          // Atualizar assinatura interna
          const { error: updateError } = await supabase
            .from('phone_number_subscriptions')
            .update({
              status: 'active',
              stripe_subscription_id: stripeSubscriptionId,
              data_inicio: new Date(stripeSub.current_period_start * 1000).toISOString().split('T')[0],
              data_proximo_faturamento: new Date(stripeSub.current_period_end * 1000).toISOString().split('T')[0],
              updated_at: new Date().toISOString()
            })
            .eq('id', internalSubscriptionId);

          if (updateError) {
            logStep("Erro ao atualizar subscription", { error: updateError });
          } else {
            logStep("Assinatura ativada com sucesso");

            // Buscar pacote para ver quantos números provisionar
            const { data: pkg } = await supabase
              .from('phone_number_packages')
              .select('quantidade_numeros')
              .eq('id', packageId)
              .single();

            // Iniciar provisionamento de número
            // Por enquanto, alocar número compartilhado ou criar placeholder
            const { data: sharedNumber } = await supabase
              .from('whatsapp_phone_numbers')
              .select('id')
              .eq('is_shared', true)
              .eq('status', 'active')
              .limit(1)
              .single();

            const departamentos = JSON.parse(eventData.metadata.departamentos || '["geral"]');

            for (let i = 0; i < (pkg?.quantidade_numeros || 1); i++) {
              const dept = departamentos[i] || 'geral';

              // Criar placeholder de alocação (número será provisionado pelo provedor depois)
              await supabase
                .from('tenant_phone_allocations')
                .insert({
                  tenant_id: tenantId,
                  phone_number_id: sharedNumber?.id, // Temporário até provisionar número exclusivo
                  subscription_id: internalSubscriptionId,
                  departamento: dept,
                  is_primary: i === 0,
                  status: 'provisioning',
                  metadata: { 
                    awaiting_provisioning: true,
                    provisioning_started_at: new Date().toISOString()
                  }
                });
            }

            logStep("Alocações criadas, aguardando provisionamento");

            // TODO: Chamar API do provedor para provisionar número
            // Isso seria feito de forma assíncrona via outra edge function ou job
          }
        }
        break;
      }

      case 'invoice.payment_succeeded': {
        // Pagamento de renovação bem-sucedido
        const subscriptionId = eventData.subscription;

        if (subscriptionId) {
          const stripeSub = await stripe.subscriptions.retrieve(subscriptionId);

          const { data: internalSub } = await supabase
            .from('phone_number_subscriptions')
            .select('id, tenant_id')
            .eq('stripe_subscription_id', subscriptionId)
            .single();

          if (internalSub) {
            await supabase
              .from('phone_number_subscriptions')
              .update({
                data_proximo_faturamento: new Date(stripeSub.current_period_end * 1000).toISOString().split('T')[0],
                notificacao_renovacao_enviada: false,
                updated_at: new Date().toISOString()
              })
              .eq('id', internalSub.id);

            logStep("Renovação processada", { subscription_id: internalSub.id });
          }
        }
        break;
      }

      case 'invoice.payment_failed': {
        // Falha no pagamento
        const subscriptionId = eventData.subscription;

        if (subscriptionId) {
          const { data: internalSub } = await supabase
            .from('phone_number_subscriptions')
            .select('id, tenant_id')
            .eq('stripe_subscription_id', subscriptionId)
            .single();

          if (internalSub) {
            // Criar alarme
            await supabase.from('whatsapp_alarms').insert({
              tenant_id: internalSub.tenant_id,
              alarm_type: 'payment_failed',
              severity: 'error',
              message: 'Falha no pagamento da assinatura do número WhatsApp',
              metadata: {
                subscription_id: internalSub.id,
                invoice_id: eventData.id
              }
            });

            logStep("Alarme de falha de pagamento criado");
          }
        }
        break;
      }

      case 'customer.subscription.deleted': {
        // Assinatura cancelada (efetivação do cancelamento)
        const stripeSubId = eventData.id;

        const { data: internalSub } = await supabase
          .from('phone_number_subscriptions')
          .select('id, tenant_id')
          .eq('stripe_subscription_id', stripeSubId)
          .single();

        if (internalSub) {
          // Atualizar status para cancelado
          await supabase
            .from('phone_number_subscriptions')
            .update({
              status: 'cancelled',
              data_fim: new Date().toISOString().split('T')[0],
              updated_at: new Date().toISOString()
            })
            .eq('id', internalSub.id);

          // Desativar alocações de número
          await supabase
            .from('tenant_phone_allocations')
            .update({
              status: 'cancelled',
              cancelado_em: new Date().toISOString()
            })
            .eq('subscription_id', internalSub.id);

          // Registrar log
          await supabase.from('phone_subscription_cancellation_logs').insert({
            subscription_id: internalSub.id,
            tenant_id: internalSub.tenant_id,
            tipo: 'efetivacao',
            metadata: { stripe_event_id: event.id }
          });

          logStep("Cancelamento efetivado", { subscription_id: internalSub.id });
        }
        break;
      }

      default:
        logStep("Evento não tratado", { type: event.type });
    }

    return new Response(JSON.stringify({ received: true }), {
      headers: { 'Content-Type': 'application/json' }
    });

  } catch (error) {
    logStep("ERRO", { message: error instanceof Error ? error.message : 'Erro desconhecido' });
    return new Response(JSON.stringify({ 
      error: error instanceof Error ? error.message : 'Erro interno' 
    }), {
      status: 500,
      headers: { 'Content-Type': 'application/json' }
    });
  }
});

